    PRINT '    ' + 'Creating a table to hold index definition'
    SET @SQL = 'CREATE TABLE dbo.TableIndexDefs(      '  + CHAR(13) + '    ' + '    ' +
			   '    TableName nvarchar(50) COLLATE CATALOG_DEFAULT NULL, ' + CHAR(13) + '    ' + '    ' +
			   '    IndexName nvarchar(100) COLLATE CATALOG_DEFAULT NULL, ' + CHAR(13) + '    ' + '    ' +
               '    IndexColumns  nvarchar(256)  NULL, '  + CHAR(13) + '    ' + '    ' +
               '    IsPrimaryKey  bit           NULL, '  + CHAR(13) + '    ' + '    ' +
               '    IsConstraint  bit           NULL, '  + CHAR(13) + '    ' + '    ' +
               '    IsClustered   bit           NULL, '  + CHAR(13) + '    ' + '    ' +
               '    IsUnique      bit           NULL, '  + CHAR(13) + '    ' + '    ' +
               '    Dropped       bit           NULL, '  + CHAR(13) + '    ' + '    ' +
               '    Recreated     bit           NULL, '  + CHAR(13) + '    ' + '    ' +
               '    IncludeColumns nvarchar(256) NULL )'

    PRINT '    ' + '    ' + @SQL
    EXEC( @SQL )
    PRINT ' '
    END
ELSE BEGIN
    PRINT '    ' + 'Updating TableIndexDefs structure'
    -- Drop the two indexes on TableName and IndexName, if they exist
	IF (IsNull(IndexProperty(object_id('TableIndexDefs'), 'IXTableIndexDefsTableName', 'IsStatistics'), 1) = 0) BEGIN
		SET @SQL = 'DROP INDEX IXTableIndexDefsTableName ON TableIndexDefs'
		PRINT '    ' + '    ' + @SQL
		EXEC( @SQL )
		PRINT ' '
		END

	IF (IsNull(IndexProperty(object_id('TableIndexDefs'), 'IXTableIndexDefsIndexName', 'IsStatistics'), 1) = 0) BEGIN
		SET @SQL = 'DROP INDEX IXTableIndexDefsIndexName ON TableIndexDefs'
		PRINT '    ' + '    ' + @SQL
		EXEC( @SQL )
		PRINT ' '
		END

	-- Make sure the TableName and IndexName columns match the CATALOG_DEFAULT collation
    SET @SQL = 'ALTER TABLE TableIndexDefs ALTER COLUMN TableName nvarchar(50) COLLATE CATALOG_DEFAULT NULL'
    PRINT '    ' + '    ' + @SQL
    EXEC( @SQL )
    PRINT ' '

    SET @SQL = 'ALTER TABLE TableIndexDefs ALTER COLUMN IndexName nvarchar(100) COLLATE CATALOG_DEFAULT NULL'
    PRINT '    ' + '    ' + @SQL
    EXEC( @SQL )
    PRINT ' '

    -- Recreate the two indexes on TableName and IndexName
    SET @SQL = 'CREATE INDEX IXTableIndexDefsTableName ON TableIndexDefs(TableName)'
    PRINT '    ' + '    ' + @SQL
    EXEC( @SQL )
    PRINT ' '

    SET @SQL = 'CREATE INDEX IXTableIndexDefsIndexName ON TableIndexDefs(IndexName)'
    PRINT '    ' + '    ' + @SQL
    EXEC( @SQL )
    PRINT ' '
    END

IF NOT EXISTS(SELECT * FROM sys.columns WHERE [name] = 'IncludeColumns' AND [object_id] = OBJECT_ID('TableIndexDefs')) BEGIN
    SET @SQL = 'ALTER TABLE TableIndexDefs ADD IncludeColumns varchar(256) NULL'
    PRINT '    ' + '    ' + @SQL
    EXEC( @SQL )
    PRINT ' '
    END

