/*
 *     *****************     Upgrade Procs and Functions     *****************
 *
 *  Misc supporting/utility procs and "functions" (GTSTableExists, GTSIndexExists, etc)
 */


/*
 *  SQL Server prior to 2000 does not support user defined function.  The following stored procedures
 *  mimic the function by using the "return" feature for the stored procedure
 */
SET nocount ON   -- turn off "x row(s) affected" message

PRINT 'Recreating the upgrade stored procedures...'

--
--                      FUNCTION GTSSplitStringByDelimeter
--
PRINT '    ' + 'Creating GTSSplitStringByDelimeter...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSSplitStringByDelimeter') AND (o.type = 'TF')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP FUNCTION dbo.GTSSplitStringByDelimeter
GO
CREATE FUNCTION dbo.GTSSplitStringByDelimeter(
	@ValueToSplit as varchar(1024),
	@Delimeter as varchar(1)
	) RETURNS @tValues TABLE(ValueElement varchar(128) collate DATABASE_DEFAULT) AS
	BEGIN
	DECLARE @I AS INT, @Aux AS INT

	SET @I = 1
	SET @Aux = 1
	WHILE @I <= LEN(@ValueToSplit) BEGIN
	    IF SUBSTRING(@ValueToSplit,@I,1)= @Delimeter BEGIN
	        INSERT INTO @tValues (ValueElement) VALUES (LTRIM(RTRIM(SUBSTRING(@ValueToSplit,@Aux,(@I-@Aux)))))
	        SET @Aux = @i + 1
	        END
	    SET @i = @i + 1
	    END
	-- If we didn't find any delimeters, place original string in the return table
	IF (@Aux = 1) BEGIN
        INSERT INTO @tValues (ValueElement) VALUES (@ValueToSplit)
        END
	-- If there wasn't a trailing delimeter, place the remaining string in the return table
    ELSE IF (@Aux < @i) BEGIN
        INSERT INTO @tValues (ValueElement) VALUES (LTRIM(RTRIM(SUBSTRING(@ValueToSplit,@Aux,(@I-@Aux)))))
	    END
	RETURN
	END
GO

--
--                      FUNCTION GTSGetUpdatedOrderAccountID
--
PRINT '    ' + 'Creating GTSGetUpdatedOrderAccountID...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGetUpdatedOrderAccountID') AND (o.type = 'FN')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP FUNCTION dbo.GTSGetUpdatedOrderAccountID
GO
CREATE FUNCTION dbo.GTSGetUpdatedOrderAccountID(@OrderID int, @EnforceCreditLimitByContact bit, @UseBillToContactForCreditCheck bit) RETURNS int AS
    BEGIN
    -- Determine the most current AccountID for the order depending on configuration.
    DECLARE @AccountID int
    SELECT @AccountID =
        CASE
            WHEN (@EnforceCreditLimitByContact = 0) THEN (SELECT TOP(1) AccountID FROM Customers WHERE CustomerID = Orders.CustomerID)
            WHEN (@EnforceCreditLimitByContact = 1) AND (@UseBillToContactForCreditCheck = 0) AND ((SELECT TOP(1) AllowChargeFOPs FROM ContactConnections WHERE ContactID = Orders.ContactID AND ConnectionID = Orders.CustomerID) = 1) THEN (SELECT TOP(1) AccountID FROM Customers WHERE CustomerID = Orders.CustomerID)
            WHEN (@EnforceCreditLimitByContact = 1) AND (@UseBillToContactForCreditCheck = 1) AND ((SELECT TOP(1) AllowChargeFOPs FROM ContactConnections WHERE ContactID = Orders.BillToContactID AND ConnectionID = Orders.CustomerID) = 1) THEN (SELECT TOP(1) AccountID FROM Customers WHERE CustomerID = Orders.CustomerID)
            ELSE 0
        END
        FROM Orders
        WHERE OrderID = @OrderID

    -- Replace NULL with 0
    SELECT @AccountID =
        CASE
            WHEN @AccountID IS NOT NULL THEN @AccountID
            ELSE 0
        END

    RETURN @AccountID
    END
GO

--
--                      FUNCTION GTSTableSupportsClusteredOnlineIndex
--
PRINT '    ' + 'Creating GTSTableSupportsClusteredOnlineIndex...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSTableSupportsClusteredOnlineIndex') AND (o.type = 'FN')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP FUNCTION dbo.GTSTableSupportsClusteredOnlineIndex
GO
CREATE FUNCTION dbo.GTSTableSupportsClusteredOnlineIndex(@TableName varchar(128)) RETURNS Bit AS
    BEGIN
    DECLARE @FoundUnsupportedField varchar(128)
    DECLARE @Return bit

	SELECT @FoundUnsupportedField = c.name
	    FROM sys.all_columns c
	        INNER JOIN sys.all_objects o ON c.object_id = o.object_id
	        INNER JOIN sys.types t ON c.system_type_id = t.system_type_id
	    WHERE (c.system_type_id IN (35, 99, 34, 173) OR                     -- text, ntext, image, binary
	           c.system_type_id IN (231,167,165,241) AND c.max_length = -1) -- nvarchar, varchar, varbinary, xml
			AND o.name = @TableName
	        AND o.[type] = 'U'

	IF @FoundUnsupportedField IS NULL
	    SET @Return = 1
	ELSE
	    SET @Return = 0

	RETURN @Return
    END
GO

--
--                      FUNCTION GTSFieldsSupportOnlineIndex
--
PRINT '    ' + 'Creating GTSFieldsSupportOnlineIndex...'
