--                      PROCEDURE GetNextPublishCount
--
PRINT '    ' + 'Creating GetNextPublishCount...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GetNextPublishCount') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GetNextPublishCount
GO
CREATE PROCEDURE dbo.GetNextPublishCount AS BEGIN
    SET nocount ON
    /*
     Updates the PublishStatus table and gets the next value for the
     PublishCount column. This in essence performs a manual central data
     maintenance publish, where the return value should be used to set the
     PublishCount column on the desired RowChanges entries.

     Usage

     DECLARE
         @NextPublishCount int

     EXEC @NextPublishCount = GetNextPublishCount
     */
    DECLARE
        @NextPublishCount int,
        @LockResult int

    BEGIN TRANSACTION

    EXEC @LockResult = sp_getapplock @Resource = 'GetNextPublishCount', @LockMode = 'Exclusive'

    IF @LockResult < 0 BEGIN
        ROLLBACK TRANSACTION
        RETURN( -1 )
        END

    UPDATE PublishStatus SET PublishCount = PublishCount + 1, LastPublish = GetDate(), RecordVersion = RecordVersion + 1, LastUpdate = GetDate(), LastUpdatedBy = 'GetNextPC'
    SELECT @NextPublishCount = PublishCount FROM PublishStatus

    IF @@Error = 0
        COMMIT TRANSACTION
    ELSE
        ROLLBACK TRANSACTION

    RETURN( @NextPublishCount )
    END
GO


