--
--                      PROCEDURE GTS_SP_DropTable
--
PRINT '    ' + 'Creating GTS_SP_DropTable...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_DropTable') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_DropTable
GO
CREATE PROCEDURE dbo.GTS_SP_DropTable(@TableName nvarchar(255), @RecreateIfExists bit = 1) AS BEGIN
    /*
    Drops and re-creates table with TableName if RecreateIfExists is 1.
    Returns 0 if table does not exist.
    */
    SET NOCOUNT ON;

    if @RecreateIfExists = 1 BEGIN
        BEGIN TRANSACTION

        if EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'dbo' AND TABLE_NAME = @TableName) BEGIN
            DECLARE @SQL nvarchar(MAX)
            SET @SQL = 'DROP TABLE [dbo].[' + @TableName + ']'
            EXEC(@SQL)
            END

        COMMIT TRANSACTION
        END
    END
GO

--
--                      PROCEDURE GTS_SP_CloneTableStructure
--
PRINT '    ' + 'Creating GTS_SP_CloneTableStructure...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_CloneTableStructure') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_CloneTableStructure
GO
CREATE PROCEDURE dbo.GTS_SP_CloneTableStructure(@SourceTable nvarchar(255), @DestinationTable nvarchar(255), @RecreateIfExists bit = 1) AS BEGIN
    /*
        Drops and re-creates destination table if RecreateIfExists is 1.
        Clones the column definitions from an existing table to the destination table.
        Does not copy any rows, constraints, or indexes.

        You will almost certainly want to follow up a call to this with a call to GTS_SP_CloneTableDefaults
        so that default columns are populated with a value so that you can insert rows into the destination table.
    */
    SET NOCOUNT ON;
    BEGIN TRANSACTION

    EXEC GTS_SP_DropTable @DestinationTable, @RecreateIfExists

    -- Create columns
    DECLARE @SQL nvarchar(MAX)
    SET @SQL = 'SELECT TOP 0 * INTO [dbo].[' + @DestinationTable + '] FROM [dbo].[' + @SourceTable + ']'
    EXEC(@SQL)
    COMMIT TRANSACTION
    END
GO


--
--                      PROCEDURE GTS_SP_CloneTableDefaults
--
PRINT '    ' + 'Creating GTS_SP_CloneTableDefaults...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_CloneTableDefaults') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_CloneTableDefaults
GO
CREATE PROCEDURE dbo.GTS_SP_CloneTableDefaults(@SourceTable nvarchar(255), @DestinationTable nvarchar(255)) AS BEGIN
    /*
    Clones any default constraints from the source table to the destination table.
    Both tables must exist.
    */
    SET NOCOUNT ON;
    BEGIN TRANSACTION

    DECLARE @ColumnName nvarchar(255), @ColumnID int, @DefaultObjectID int, @ConstraintName nvarchar(255), @Definition nvarchar(255)

    DECLARE ColumnCursor CURSOR FOR
        SELECT name, column_id, default_object_id FROM sys.columns WHERE default_object_id <> 0 AND object_id = object_id('[dbo].[' + @SourceTable + ']')

    OPEN ColumnCursor;

    FETCH NEXT FROM ColumnCursor INTO @ColumnName, @ColumnID, @DefaultObjectID;
    WHILE @@FETCH_STATUS = 0 BEGIN
        SELECT @ConstraintName = name, @Definition = definition
            FROM sys.default_constraints
            WHERE object_id = @DefaultObjectID

        DECLARE @SQL nvarchar(MAX)
        SET @SQL = 'ALTER TABLE [dbo].[' + @DestinationTable + '] ADD DEFAULT ' + @Definition + ' FOR [' + @ColumnName + ']'
        EXEC(@SQL);

        FETCH NEXT FROM ColumnCursor INTO @ColumnName, @ColumnID, @DefaultObjectID;
        END

    CLOSE ColumnCursor;
    DEALLOCATE ColumnCursor;

    COMMIT TRANSACTION
    END
GO


--
--                      PROCEDURE GTS_SP_CloneTableIndexes
--
PRINT '    ' + 'Creating GTS_SP_CloneTableIndexes...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_CloneTableIndexes') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_CloneTableIndexes
GO
CREATE PROCEDURE dbo.GTS_SP_CloneTableIndexes(@SourceTable nvarchar(255), @DestinationTable nvarchar(255)) AS BEGIN
    /*
    Clones indexes from the source table to the destination table.
    Clones constraints.

    Does not clone default constraints.
    There may be unsupported index types.
    Note: Assumes that you name (unique) constraints with the table name in it (in order to not duplicate constraint names)
    */
    SET NOCOUNT ON;
    BEGIN TRANSACTION

    -- Create primary key
    DECLARE @PKSchema nvarchar(255), @PKName nvarchar(255), @TypeDesc nvarchar(60), @SQL nvarchar(MAX)

    SELECT TOP 1 @PKSchema = CONSTRAINT_SCHEMA, @PKName = CONSTRAINT_NAME
        FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS
        WHERE TABLE_SCHEMA = 'dbo' AND TABLE_NAME = @SourceTable AND CONSTRAINT_TYPE = 'PRIMARY KEY'

    IF NOT @PKSchema IS NULL AND NOT @PKName IS NULL BEGIN
        -- Get primary key type (clustered, non-clustered)
        SELECT @TypeDesc = type_desc FROM sys.indexes WHERE object_id = object_id('[dbo].[' + @SourceTable + ']') AND name = @PKName

        DECLARE @PKColumns nvarchar(MAX)
        SET @PKColumns = ''

        SELECT @PKColumns = @PKColumns + '[' + COLUMN_NAME + '],'
            FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE
            WHERE TABLE_NAME = @SourceTable and TABLE_SCHEMA = 'dbo' AND CONSTRAINT_SCHEMA = @PKSchema AND CONSTRAINT_NAME= @PKName
            ORDER BY ORDINAL_POSITION

        SET @PKColumns = LEFT(@PKColumns, LEN(@PKColumns) - 1)

        SET @SQL = 'ALTER TABLE [dbo].[' + @DestinationTable + '] ADD CONSTRAINT [PK' + @DestinationTable + '] PRIMARY KEY ' + @TypeDesc + ' (' + @PKColumns + ')'
        EXEC(@SQL);
        END

    -- Create other indexes
    DECLARE @IndexId int, @IndexName nvarchar(255), @IsUnique bit, @IsUniqueConstraint bit, @FilterDefinition nvarchar(max)

    DECLARE IndexCursor CURSOR FOR
        SELECT index_id, name, is_unique, is_unique_constraint, type_desc, filter_definition FROM sys.indexes WHERE object_id = object_id('[dbo].[' + @SourceTable + ']')

    OPEN IndexCursor;

    FETCH NEXT FROM IndexCursor INTO @IndexId, @IndexName, @IsUnique, @IsUniqueConstraint, @TypeDesc, @FilterDefinition;
    WHILE @@FETCH_STATUS = 0 BEGIN
        -- Only create a clustered index if one has not already been created
        DECLARE @CreateIndex bit
        SET @CreateIndex = 1

        IF @TypeDesc = 'CLUSTERED' BEGIN
            DECLARE @DestTypeDesc nvarchar(255)
            SELECT @DestTypeDesc = type_desc FROM sys.indexes WHERE object_id = object_id('[dbo].[' + @DestinationTable + ']') AND type_desc = 'CLUSTERED'
            if @DestTypeDesc = 'CLUSTERED' SET @CreateIndex = 0
            END

        IF @CreateIndex = 1 BEGIN
            DECLARE @Unique nvarchar(255)
            SET @Unique = CASE WHEN @IsUnique = 1 THEN 'UNIQUE' ELSE '' END

            DECLARE @KeyColumns nvarchar(max), @IncludedColumns nvarchar(max)
            SET @KeyColumns = ''
            SET @IncludedColumns = ''

            SELECT @KeyColumns = @KeyColumns + '[' + c.name + '] ' + CASE WHEN is_descending_key = 1 THEN 'DESC' ELSE 'ASC' END + ',' from sys.index_columns ic
                INNER JOIN sys.columns c ON c.object_id = ic.object_id and c.column_id = ic.column_id
                WHERE index_id = @IndexId and ic.object_id = object_id('[dbo].[' + @SourceTable + ']') and key_ordinal > 0
                ORDER BY index_column_id

            SELECT @IncludedColumns = @IncludedColumns + '[' + c.name + '],' from sys.index_columns ic
                INNER JOIN sys.columns c ON c.object_id = ic.object_id and c.column_id = ic.column_id
                WHERE index_id = @IndexId and ic.object_id = object_id('[dbo].[' + @SourceTable + ']') and key_ordinal = 0
                ORDER BY index_column_id

            IF LEN(@KeyColumns) > 0
                SET @KeyColumns = LEFT(@KeyColumns, LEN(@KeyColumns) - 1)

            IF LEN(@IncludedColumns) > 0 BEGIN
                SET @IncludedColumns = ' INCLUDE (' + LEFT(@IncludedColumns, LEN(@IncludedColumns) - 1) + ')'
                END

            IF @FilterDefinition IS NULL
                SET @FilterDefinition = ''
            ELSE
                SET @FilterDefinition = 'WHERE ' + @FilterDefinition + ' '

            IF @IsUniqueConstraint = 0 BEGIN
                SET @SQL = 'CREATE ' + @Unique + ' ' + @TypeDesc + ' INDEX [' + @IndexName + '] ON [dbo].[' + @DestinationTable + '] (' + @KeyColumns + ')' + @IncludedColumns + @FilterDefinition
                EXEC(@SQL);
                END
            ELSE BEGIN
                SET @IndexName = REPLACE(@IndexName, @SourceTable, @DestinationTable)

                SET @SQL = 'ALTER TABLE [dbo].[' + @DestinationTable + '] ADD CONSTRAINT [' + @IndexName + '] UNIQUE ' + @TypeDesc + ' (' + @KeyColumns + ')'
                EXEC(@SQL);
                END
            END

        FETCH NEXT FROM IndexCursor INTO @IndexId, @IndexName, @IsUnique, @IsUniqueConstraint, @TypeDesc, @FilterDefinition;
        END;

    CLOSE IndexCursor;
    DEALLOCATE IndexCursor;

    -- Create constraints
    DECLARE @ConstraintName nvarchar(max), @CheckClause nvarchar(max)
    DECLARE ConstraintCursor CURSOR FOR

    SELECT REPLACE(c.CONSTRAINT_NAME, @SourceTable, @DestinationTable), CHECK_CLAUSE
        FROM INFORMATION_SCHEMA.CONSTRAINT_TABLE_USAGE t
        INNER JOIN INFORMATION_SCHEMA.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA = TABLE_SCHEMA AND c.CONSTRAINT_NAME = t.CONSTRAINT_NAME
        WHERE TABLE_SCHEMA = 'dbo' AND TABLE_NAME = @SourceTable

    OPEN ConstraintCursor;

    FETCH NEXT FROM ConstraintCursor INTO @ConstraintName, @CheckClause;
    WHILE @@FETCH_STATUS = 0 BEGIN
        SET @SQL = 'ALTER TABLE [dbo].[' + @DestinationTable + '] WITH CHECK ADD CONSTRAINT [' + @ConstraintName + '] CHECK ' + @CheckClause
        EXEC(@SQL);

        SET @SQL = 'ALTER TABLE [dbo].[' + @DestinationTable + '] CHECK CONSTRAINT [' + @ConstraintName + ']'
        EXEC(@SQL);

        FETCH NEXT FROM ConstraintCursor INTO @ConstraintName, @CheckClause;
        END;

    CLOSE ConstraintCursor;
    DEALLOCATE ConstraintCursor;

    COMMIT TRANSACTION
    END
GO


--
--                      PROCEDURE GTS_SP_CloneTable
--
PRINT '    ' + 'Creating GTS_SP_CloneTable...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_CloneTable') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_CloneTable
GO
CREATE PROCEDURE dbo.GTS_SP_CloneTable(@SourceTable nvarchar(255), @DestinationTable nvarchar(255), @RecreateIfExists bit = 1) AS BEGIN
    /*
    Clones source table to destination table, including all rows in the table.
    Optionally drops and re-creates destination table before performing the clone.

    Copies:
        * Structure
        * Primary key
        * Indexes (including ASC/DESC, included columns, filters)
        * Constraints (and unique constraints)
        * Default constraints

    DOES NOT copy:
        * Triggers
        * File groups
        * Probably lots of other things

    Note: Assumes that you name (unique) constraints with the table name in it (in order to not duplicate constraint names)
    */
    SET NOCOUNT ON;
    BEGIN TRANSACTION

    EXEC GTS_SP_DropTable @DestinationTable, @RecreateIfExists

    -- Create the table, copy rows

    DECLARE @SQL nvarchar(MAX)

    SET @SQL = 'SELECT * INTO [dbo].[' + @DestinationTable + '] FROM [dbo].[' + @SourceTable + ']'
    EXEC(@SQL);

    EXEC GTS_SP_CloneTableDefaults @SourceTable, @DestinationTable
    EXEC GTS_SP_CloneTableIndexes @SourceTable, @DestinationTable

    COMMIT TRANSACTION
    END
GO

SET NOEXEC OFF
GO

