--
--                      PROCEDURE GTSRowSize
--
PRINT '    ' + 'Creating GTSRowSize...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSRowSize') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSRowSize
GO
CREATE PROCEDURE dbo.GTSRowSize(@TableName VarChar(100)) AS BEGIN
    SET nocount ON
    /*
     Displays the size of one row (in bytes) of the specified table.

     Usage

     EXEC GTSRowSize Tickets

     HINT: To get a list of all tables and their row sizes in a database, run
     this:

     EXEC sp_MSForEachTable 'exec GTSRowSize ''?'''
     */
     DECLARE @RSize int

     SELECT @RSize = sum(b.length)
        FROM sysobjects a, syscolumns b, systypes c
        WHERE a.id = b.id
        AND b.xtype = c.xtype
        AND c.name <> 'boolean'
		AND a.id = OBJECT_ID(@TableName)

     SELECT @TableName as TableName, @RSize as RowSize

     RETURN(@RSize)
     END
GO

--
--              PROCEDURE GTSGetJointMemberByVisualID
--    /*  This stored procedure collects data for ACS when a validation   */
--    /*  is performed and requires one card per named member.  The       */
--    /*  stored procedure GTSGetJointMembersByPassNo is executed instead */
--    /*  when ACS is not in this mode.                                   */
--
PRINT '    ' + 'Creating GTSGetJointMemberByVisualID...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGetJointMemberByVisualID') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSGetJointMemberByVisualID
GO
CREATE PROCEDURE dbo.GTSGetJointMemberByVisualID
       @VisualID   nvarchar(100),
       @FacilityID Integer
        /*
        Collects data for a single joint member validation in ACS32 when the "people picker" is not being used
        */
        AS BEGIN
            SET NOCOUNT ON
                  SELECT J.JointMemberID, J.ContactID, J.MemberType, J.PrimaryMember, J.Status,
                         P.PixelDepth, P.ImageData,
                         C.FirstName, C.MiddleName, C.LastName, C.AgeGroup, C.DOB,
                         R.JointMemberID as AdmittedEarlier
                  FROM JointMembers J (NOLOCK)
                        LEFT OUTER JOIN CustContacts C (NOLOCK)
                                ON (J.ContactID <> 0) AND (J.ContactID = C.CustContactID)
                        LEFT OUTER JOIN Pictures P (NOLOCK)
                                ON (J.PictureID <> 0) AND (J.PictureID = P.PictureID)
                         LEFT OUTER JOIN Reentry R (NOLOCK)
                            ON (R.JointMemberID = J.JointMemberID) AND (R.Facility = @FacilityID)
                  WHERE J.VisualID = @VisualID
            END
GO


--
--              PROCEDURE GTS_SP_ConvertContactPhoneNumbers
--    /*  When the system is configured to use the PhoneNumbers table,    */
--    /*  CustContactPhoneNumbers are converted to PhoneNumbers records   */
--
PRINT '    ' + 'Creating GTS_SP_ConvertContactPhoneNumbers...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_ConvertContactPhoneNumbers') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_ConvertContactPhoneNumbers
GO

CREATE PROCEDURE dbo.GTS_SP_ConvertContactPhoneNumbers AS
BEGIN
  SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported  */
  DECLARE
    @ContactID Integer,
    @Phone char(30),
    @UnformattedPhone varchar(30),
    @Fax char(30),
    @Cell char(30),
    @LastUpdatedBy varchar(20),
    @PhoneNumberID Integer

  DECLARE CustContactCursor CURSOR FOR
    SELECT CustContactID, Phone, UnformattedPhone, Fax, Cell, LastUpdatedBy
    FROM CustContacts
    WHERE (Phone <> '') or (Fax <> '') or (Cell <> '')
 /* PhoneTypes Home=0, Work=1, Mobile=2, Fax=3, Other=4 */
  OPEN CustContactCursor
  FETCH NEXT FROM CustContactCursor INTO @ContactID, @Phone, @UnformattedPhone, @Fax, @Cell, @LastUpdatedBy
  WHILE ( @@Fetch_Status = 0 ) BEGIN
    /* Insert @Phone and @UnformattedPhone into PhoneNumbers, if not already there, else update the number */
    IF (@Phone <> '') AND ((Select Count(PhoneNumberID) from PhoneNumbers where (ContactID = @ContactID) and (PhoneType = 0)) = 0) BEGIN
      EXEC @PhoneNumberID = GetNextGatewayCounter 'PhoneNumberID'
      Insert into PhoneNumbers
                      (PhoneNumberID, PhoneType, Number, UnformattedNumber, Allowcontact, ContactID, CustomerID, RecordVersion, LastUpdate, LastUpdatedBy)
            Values(@PhoneNumberID, 0, @Phone, @UnformattedPhone, 1, @ContactID, 0, 1, GetDate(), @LastUpdatedBy)
      END
    ELSE Update PhoneNumbers Set Number = @Phone, UnformattedNumber = @UnformattedPhone where (ContactID = @ContactID) and (PhoneType = 0)

    /* Insert @Cell into PhoneNumbers, if not already there, else update the number */
    IF (@Cell <> '') AND ((Select Count(PhoneNumberID) from PhoneNumbers where (ContactID = @ContactID) and (PhoneType = 2)) = 0) BEGIN
      EXEC @PhoneNumberID = GetNextGatewayCounter 'PhoneNumberID'
      Insert into PhoneNumbers
                  (PhoneNumberID, PhoneType, Number, UnformattedNumber, Allowcontact, ContactID, CustomerID, RecordVersion, LastUpdate, LastUpdatedBy)
            Values(@PhoneNumberID, 2, @Cell, '', 1, @ContactID, 0, 1, GetDate(), @LastUpdatedBy)
      END
      ELSE Update PhoneNumbers Set Number = @Cell where (ContactID = @ContactID) and (PhoneType = 2)

    /* Insert @Fax into PhoneNumbers, if not already there, else update the number */
    IF (@Fax <> '') AND ((Select Count(PhoneNumberID) from PhoneNumbers where (ContactID = @ContactID) and (PhoneType = 3)) = 0) BEGIN
      EXEC @PhoneNumberID = GetNextGatewayCounter 'PhoneNumberID'
      Insert into PhoneNumbers
                  (PhoneNumberID, PhoneType, Number, UnformattedNumber, Allowcontact, ContactID, CustomerID, RecordVersion, LastUpdate, LastUpdatedBy)
            Values(@PhoneNumberID, 3, @Fax, '', 1, @ContactID, 0, 1, GetDate(), @LastUpdatedBy)
      END
    ELSE Update PhoneNumbers Set Number = @Fax where (ContactID = @ContactID) and (PhoneType = 3)

    FETCH NEXT FROM CustContactCursor INTO @ContactID, @Phone, @UnformattedPhone, @Fax, @Cell, @LastUpdatedBy
	  END

  CLOSE CustContactCursor
  DEALLOCATE CustContactCursor

END
GO

--
--              PROCEDURE GTS_SP_GetSpendingHistory
-- /* Used to display spending history on Contact, Customer and Pass forms in Galaxy */
--

PRINT '    ' + 'Creating GTS_SP_GetSpendingHistory...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_GetSpendingHistory') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_GetSpendingHistory
GO

CREATE PROCEDURE dbo.GTS_SP_GetSpendingHistory
    @SessionID Char(50),
    @ContactID int,
    @CustomerID int,
    @UseDateRange bit,
    @FromDate DateTime,
    @ThruDate DateTime
AS
BEGIN
  SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported  */

  -- Remove any existing data in the temp table for the SessionID
  delete from TempSpendingHistory where SessionID = @SessionID

  -- Get header data and insert into TempSpendingHistory temp table
  IF (@ContactID <> 0) BEGIN
  	insert into TempSpendingHistory
		select distinct @SessionID, h.JnlTranID, h.FiscalDate, h.TranDate, h.NodeNo, h.TranNo, h.Agency/1000 as AgencyID, a.AgencyName
		FROM JnlHeaders h
		LEFT OUTER join Agencies a on h.Agency/1000 = a.AgencyNo
		WHERE (h.JnlTranID in (
			select distinct h.jnltranid
			FROM JnlHeaders h
			INNER JOIN JnlDetails d ON h.JnlTranID = d.JnlTranID
			INNER JOIN JnlContacts c ON d.JnlCodeID = 87 AND d.AuxTableID = c.JnlContactID and c.ContactID = @ContactID
			WHERE (@UseDateRange = 0) or (h.FiscalDate between @FromDate and @ThruDate)
			))
    END
  ELSE IF (@CustomerID <> 0) BEGIN
	insert into TempSpendingHistory
		select distinct @SessionID, h.JnlTranID, h.FiscalDate, h.TranDate, h.NodeNo, h.TranNo, h.Agency/1000 as AgencyID, a.AgencyName
		FROM JnlHeaders h
		INNER JOIN JnlDetails d ON h.JnlTranID = d.JnlTranID
		LEFT OUTER join Agencies a on h.Agency/1000 = a.AgencyNo
		WHERE (h.JnlTranID in (
			select distinct h.jnltranid
			FROM JnlHeaders h
			INNER JOIN JnlDetails d ON (h.JnlTranID = d.JnlTranID) and (d.JnlCodeID = 24 and d.AuxTableID = @CustomerID)
			WHERE (@UseDateRange = 0) or (h.FiscalDate between @FromDate and @ThruDate)
			))
    END

  SET NOCOUNT OFF  -- Turn on the NOCOUNT option so number of rows affected by final select is returned as part of result set

  /*
  Note that in the following three queries,  d.JnlDetailID is included in the select list so that each
  row is uniuqe.  Without this it was possible to get two rows that were idential (say for two tickets
  in the same transaction), and using a union would filter out one of them.
  */



  Select JnlTranID, FiscalDate, TranDate,
		NodeNo, TranNo, AgencyID, PLU, ItemName, Sum(Qty) as Qty, UnitPrice,
		Sum(Tax) AS Tax, Sum(DiscountAmount) as DiscountAmount, Sum(TotalAmount) AS TotalAmount,
		AgencyName, DiscountName, ItemKind, VisualID, PassStatus, ValidFrom, ValidUntil from (
	-- Get Tickets
	SELECT distinct tsh.JnlTranID as JnlTranID, tsh.FiscalDate AS FiscalDate, tsh.TranDate AS TranDate,
		tsh.NodeNo AS NodeNo, tsh.TranNo AS TranNo, tsh.AgencyID, t.PLU, i.Name as ItemName,
		d.Qty, i.price as UnitPrice, t.Tax, t.DiscAmt as DiscountAmount, (d.Amount + t.Tax) AS TotalAmount,
		tsh.AgencyName, d.JnlDetailID, dc.Name as DiscountName, i.Kind as ItemKind, t.visualid,
		case when p.visualid = '' then 0 else p.Status end as PassStatus, P.ValidFrom, P.ValidUntil
	FROM TempSpendingHistory tsh
	INNER JOIN JnlDetails d ON tsh.JnlTranID = d.JnlTranID
	INNER JOIN JnlTickets t ON d.JnlCodeID = 101 AND d.AuxTableID = t.JnlDetailID
	LEFT OUTER join Items i on t.plu = i.plu
	LEFT OUTER join Discounts dc on t.DiscNo = dc.DiscountID
	LEFT OUTER join Passes p on t.VisualID = p.VisualID AND p.VisualID <> ''
	WHERE tsh.SessionID = @SessionID
  union
	-- Get Items and Fees
	SELECT distinct tsh.JnlTranID as JnlTranID, tsh.FiscalDate AS FiscalDate, tsh.TranDate AS TranDate,
		tsh.NodeNo AS NodeNo, tsh.TranNo AS TranNo, tsh.AgencyID, ji.PLU, i.Name as ItemName,
		d.Qty, i.price as UnitPrice, ji.Tax,  ji.DiscAmt as DiscountAmount, (d.Amount + ji.Tax) AS TotalAmount,
		tsh.AgencyName, d.JnlDetailID, dc.Name as DiscountName, i.Kind as ItemKind,
		NULL as VisualID, NULL as PassStatus, NULL as ValidFrom, NULL as ValidUntil
	FROM TempSpendingHistory tsh
	INNER JOIN JnlDetails d ON tsh.JnlTranID = d.JnlTranID
	INNER JOIN JnlItems ji ON (d.JnlCodeID in (102, 103)) AND d.AuxTableID = ji.JnlItemID
	LEFT OUTER join Items i on ji.plu = i.plu
	LEFT OUTER join Discounts dc on ji.DiscNo = dc.DiscountID
	WHERE tsh.SessionID = @SessionID
  ) as ResultSet --order by TranDate, NodeNo, TranNo, PLU
	group by JnlTranID, FiscalDate, TranDate, NodeNo, TranNo, AgencyID,
             ItemName, PLU, UnitPrice, AgencyName, DiscountName, ItemKind,
			 VisualID, PassStatus, ValidFrom, ValidUntil
END
GO

PRINT '    ' + 'Creating dbo.GTS_SP_SELECT4KIOSKORDERPICKUP...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_SELECT4KIOSKORDERPICKUP') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_SELECT4KIOSKORDERPICKUP
GO

	CREATE PROCEDURE dbo.GTS_SP_SELECT4KIOSKORDERPICKUP
		@LastName nvarchar(30)
	AS
	BEGIN
        SET NOCOUNT ON;
        SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

		SELECT o.*
		FROM Orders o
			JOIN DeliveryMethods dm
				on o.DeliveryMethodID = dm.DeliveryMethodID
			JOIN CustContacts cc
				on o.ContactID = cc.CustContactID
		WHERE (o.OrderStatus < 3) AND (o.UnissuedQty > 0) AND (o.Balance <= 0)
		AND ((dm.Kind = 7) or (dm.AllowKioskPickup = 1))
		AND ((cc.UnformattedLastName = @LastName) OR  (cc.LastName = @LastName));
	END
GO

