IF EXISTS (
    SELECT o.id FROM SysObjects o, SysUsers u
	    WHERE (o.name = 'CreateEventLogStoredProcedures') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.CreateEventLogStoredProcedures
GO

CREATE PROCEDURE [dbo].[CreateEventLogStoredProcedures] AS BEGIN
    SET NOCOUNT ON
    DECLARE @SQL nvarchar(4000)
    DECLARE @Err Int

    PRINT 'Creating GTSGetEventLogRecords stored procedure'
    IF EXISTS (
        SELECT o.id FROM SysObjects o, SysUsers u
            WHERE (o.name = 'GTSGetEventLogRecords') AND (o.type = 'P')
            AND   (o.uid = u.uid)
            AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTSGetEventLogRecords

    SET @SQL =
        'CREATE PROCEDURE [dbo].[GTSGetEventLogRecords] AS BEGIN
            SET NOCOUNT ON

            DECLARE @LockName nvarchar(255)
            DECLARE @LockResult int
            DECLARE @ReturnEmpty bit

            SET @LockName = ''GTS_GetEventLogRecords''
            SET @ReturnEmpty = 1

            BEGIN TRANSACTION

            /* Acquire application lock */
            EXEC @LockResult = sp_getapplock
                    @Resource = @LockName, @LockMode = ''Exclusive'', @LockTimeout = 1000

            IF @LockResult < 0 BEGIN
                ROLLBACK TRANSACTION
                END
            ELSE BEGIN
                SELECT TOP 5 GxTriggerUID, RecordID INTO #Temp FROM GxTriggers WHERE ProcessCode = 10 AND ProcessStatus = 0

                UPDATE GxTriggers
                    SET ProcessStatus = 1,
                    RecordVersion = RecordVersion + 1,
                    LastUpdate = GetDate()
                WHERE GxTriggers.GxTriggerUID IN (SELECT #Temp.GxTriggerUID FROM #Temp)

                IF @@Error = 0 BEGIN
                    COMMIT TRANSACTION
                    SET @ReturnEmpty = 0
                    END
                ELSE
                    ROLLBACK TRANSACTION
                END

            IF @ReturnEmpty = 0
                SELECT GxEventLogUID AS Id,
                    EventDateTime,
                    NodeID AS NodeId,
                    UserID AS UserId,
                    Severity,
                    ApplicationName,
                    ProcessName,
                    EventText,
                    EventData,
                    ErrorCode,
                    EventCode,
                    EventSubCode,
                    AgencyNo,
                    RecordVersion,
                    LastUpdate,
                    LastUpdatedBy
                FROM GxEventLog WHERE GxEventLogUID IN (SELECT #Temp.RecordID FROM #Temp)
            ELSE
                SELECT TOP 0
                	GxEventLogUID AS Id,
                    NodeID AS NodeId,
                    UserID AS UserId,
                    Severity,
                    ApplicationName,
                    ProcessName,
                    EventText,
                    EventData,
                    ErrorCode,
                    EventCode,
                    EventSubCode,
                    AgencyNo,
                    RecordVersion,
                    LastUpdate,
                    LastUpdatedBy FROM GxEventLog
            END'

	EXEC(@SQL)
	SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTSGetEventLogRecords due to an error.'
    ELSE PRINT N'Stored procedure GTSGetEventLogRecords created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created
    END
GO

