CREATE PROCEDURE dbo.GTSDropTablePK(@RunMode int, @Error int OUTPUT, @TableName sysname) AS BEGIN
    --
    --  Drops the PK for the specified table
    --

    DECLARE @SQL VARCHAR(4000)

    SET @SQL = 'ALTER TABLE ' + @TableName + ' DROP CONSTRAINT |ConstraintName| '

    SET @SQL = REPLACE(@SQL, '|ConstraintName|', (SELECT name FROM sysobjects WHERE xtype = 'PK' AND parent_obj = OBJECT_ID(@TableName)))

    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END
GO

