--
--                      PROCEDURE GTSSameColumnDef
--
PRINT '    ' + 'Creating GTSSameColumnDef...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSSameColumnDef') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSSameColumnDef
GO
CREATE PROCEDURE dbo.GTSSameColumnDef( @TableName        sysname,
                                   @Column           sysname,
                                   @Type             sysname,
                                   @Length           int      = -1,
                                   @NullStr          char(10) = 'NULL') AS BEGIN
    --
    --  Check if the datbase table column definition is same as the parameter
    --
    DECLARE
        @ColumnNullable bit,
        @ColumnLength int

    SET @ColumnLength = @Length

    IF (@Type = 'nchar') OR (@Type = 'nvarchar') AND (@Length > 0)
        SET @ColumnLength = 2 * @ColumnLength

    -- Convert integer to int, since c.name will only ever be int, never integer
    IF (@Type = 'integer') SET @Type = 'int'

    IF EXISTS(SELECT b.id FROM SysColumns b, SysTypes c
              WHERE (b.name = @Column) AND (b.id = object_id(@TableName)) AND (b.xusertype = c.xusertype)
              AND   (c.name = @Type) AND ((c.name NOT LIKE '%char') or (b.length = @ColumnLength))
              AND   (b.IsNullable = CASE WHEN (@NullStr = 'NULL') THEN 1 ELSE 0 END))
        RETURN( 1 )

    RETURN( 0 )
    END
GO

