---
---                     function GTSGetFiscalYearStartDate
---

PRINT '    ' + 'Creating GTSGetFiscalYearStartDate...'
if object_id('dbo.GTSGetFiscalYearStartDate') IS NOT NULL
	DROP FUNCTION dbo.GTSGetFiscalYearStartDate;
GO

CREATE FUNCTION dbo.GTSGetFiscalYearStartDate (
	@FiscalYearEndMonth int,
	@FiscalYearEndDay int,
	@AsOfDate datetime
) returns datetime
AS
BEGIN
	DECLARE @FiscalYearStartDate datetime,
			@PreviousFiscalYearStartDate datetime;

	SET @PreviousFiscalYearStartDate = dateadd(day,1,cast(cast(datepart(year,@AsOfDate) AS VARCHAR(4)) + right('0' + cast(@FiscalYearEndMonth AS VARCHAR(2)),2) + right('0' + cast(@FiscalYearEndDay AS VARCHAR(2)),2) AS datetime));
	-- If the calculated date is greater than the as of date, this means we are in the new calendar year but not yet beyond the fiscal year boundary.
	-- Therefore the actual previous start date is one year prior.
	if @PreviousFiscalYearStartDate > @AsOfDate
		SET @PreviousFiscalYearStartDate = dateadd(year,-1,@PreviousFiscalYearStartDate);
	RETURN @PreviousFiscalYearStartDate;
END
GO


