--
--                      PROCEDURE GTSGetColumnDefinition
--
PRINT '    ' + 'Creating GTSGetColumnDefinition...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGetColumnDefinition') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSGetColumnDefinition
GO
CREATE PROCEDURE dbo.GTSGetColumnDefinition( @TableName        sysname,
                                         @Column           sysname,
                                         @Type             sysname  OUTPUT,
                                         @Length           int      OUTPUT,
                                         @NullStr          char(10) OUTPUT) AS BEGIN
    --
    --  Check if the datbase table column definition is same as the parameter
    --
    DECLARE
        @IsNullable bit

    SELECT @IsNullable = ColumnProperty(Object_ID(@TableName), @Column, 'AllowsNULL')

    /* if column does not exists, don't bother */
    IF @IsNullable IS NULL RETURN( 0 )


    If @IsNullable = 1
        SET @NullStr = 'NULL'
    ELSE
        SET @NullStr = 'NOT NULL'


    SELECT @Type = c.name, @Length = b.length
    FROM SysColumns b, SysTypes c
    WHERE (b.name      = @Column)
    AND   (b.id        = Object_ID(@TableName))
    AND   (b.xUserType = c.xUserType)

    RETURN( 1 )
    END
GO


