CREATE PROCEDURE dbo.GTSUpgradeAddUpgradeIndexDef( @TableName     sysname,
                                               @IndexName     sysname,
                                               @IndexColumns  varchar(256),
                                               @IsPrimaryKey  bit,
                                               @IsConstraint  bit,
                                               @IsClustered   bit,
                                               @IsUnique      bit,
                                               @Dropped       bit,
                                               @IncludeColumns varchar(256)) AS BEGIN
    --
    --  This proc simply inserts an entry to GTSUpgradeIndexDef table
    --
    DECLARE
        @SQL varchar(1000)

    SET @SQL = 'INSERT INTO TableIndexDefs (TableName, IndexName, IndexColumns, IsPrimaryKey, IsConstraint, IsClustered, IsUnique, Dropped, Recreated, IncludeColumns) VALUES(' +
                   '''' + @TableName + ''', ''' + @IndexName + ''', ''' + @IndexColumns + ''', ' +
                   convert(varchar, @IsPrimaryKey) + ', ' +
                   convert(varchar, @IsConstraint) + ', ' +
                   convert(varchar, @IsClustered ) + ', ' +
                   convert(varchar, @IsUnique)     + ', ' +
                   convert(varchar, @Dropped)      + ', ' +
                   '0 /* Recreated */ '            + ', ' +
                   '''' + @IncludeColumns + ''')'
    EXEC( @SQL )
    END
