--
--                      PROCEDURE GTSGetIndexColumns
--
PRINT '    ' + 'Creating GTSGetIndexColumns...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGetIndexColumns') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSGetIndexColumns
GO
CREATE PROCEDURE dbo.GTSGetIndexColumns( @TableName     sysname,
                                     @IndexName     sysname,
                                     @IndexColumns  varchar(256) OUTPUT ) AS BEGIN

    --
    -- returns all the columns for an index separated by commas
    --
    DECLARE
        @Column        sysname,
        @IndexKey      integer,
        @IndexID       integer

    SELECT @IndexID = IndexProperty(object_id(@TableName), @IndexName, 'IndexID')

    SET @IndexKey = 1
    SET @Column = Index_COL(@TableName, @IndexID, @IndexKey)
    SET @IndexColumns = IsNULL(@Column, '')

    WHILE( (@IndexKey <= 16) AND (@Column IS NOT NULL) ) BEGIN
        SET @IndexKey = @IndexKey + 1
        SET @Column = Index_COL(@TableName, @IndexID, @IndexKey)
        SET @IndexColumns = @IndexColumns + IsNULL(',' + @Column, '')  -- 'string' + NULL = NULL
        END

    -- if no index exists, return NULL
    IF (@IndexColumns = '') SET @IndexColumns = NULL
    END
GO

--
--                      FUNCTION GTSGetIndexIncludedColumns
--
PRINT '    ' + 'Creating GTSGetIndexIncludedColumns...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGetIndexIncludedColumns') AND (o.type = 'FN')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP FUNCTION dbo.GTSGetIndexIncludedColumns
GO

CREATE FUNCTION dbo.GTSGetIndexIncludedColumns(@TableName sysname, @IndexName sysname) RETURNS varchar(256) AS BEGIN
    --
    -- Returns all the columns that are included in the specified index separated by commas.
    -- Result is created as ',<column1>,<column2>,<columnX>' and the STUFF call gets rid of the initial comma.
    --
	RETURN(STUFF((select inccols.included_cols from sys.indexes i
    cross apply (select ',' + c.name from sys.index_columns col join sys.columns c on col.object_id = c.object_id and col.column_id = c.column_id
                 where col.index_id = i.index_id and col.object_id = i.object_id and col.is_included_column = 1
                 order by col.index_column_id asc
                 for xml path('')) inccols(included_cols)
    where i.object_id = object_id(@TableName) and name = @IndexName), 1, 1, ''))
    END
GO

--
--                      PROCEDURE GTSUpgradeGatherTableIndexes
--
PRINT '    ' + 'Creating GTSUpgradeGatherTableIndexes...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeGatherTableIndexes') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeGatherTableIndexes
GO
CREATE PROCEDURE dbo.GTSUpgradeGatherTableIndexes( @TableName sysname ) AS BEGIN
    SET nocount ON
    --
    --  This stored procedure collects index definitions for a table.
    --  If there are any index for the table, it gathers
    --  columns for the index and other info such as
    --    - is it a primary key
    --    - is it a constraint
    --    - is it clustered
    --    - is it unique
    --
    --  These data can be used to recreate the index after
    --  the index was dropped before alter a column which
    --  depended on it.
    --

    -- If index for a table added already, don't add it the second time
    IF NOT EXISTS( SELECT s.name FROM sys.indexes s LEFT JOIN TableIndexDefs t ON t.IndexName = s.name AND t.TableName = @TableName WHERE s.object_id = object_id(@TableName) AND t.TableName IS NULL) RETURN

    DECLARE
        @IndexName     sysname,
        @IndexColumns  varchar(256),
        @IncludedColumns varchar(256),
        @IsPrimaryKey  bit,
        @IsConstraint  bit,
        @IsClustered   bit,
        @IsUnique      bit

    DECLARE SysIndexesCursor INSENSITIVE CURSOR FOR
        SELECT name FROM SysIndexes
        WHERE (id = object_id(@TableName))
        AND   (IsNULL(IndexProperty(id, name, 'IsStatistics'), 1) = 0)

    OPEN SysIndexesCursor

    FETCH NEXT FROM SysIndexesCursor INTO @IndexName
    WHILE( @@Fetch_Status = 0 ) BEGIN
        IF NOT EXISTS(SELECT IndexName FROM TableIndexDefs WHERE TableName = @TableName AND IndexName = @IndexName) BEGIN
            EXEC GTSGetIndexColumns  @TableName, @IndexName, @IndexColumns OUTPUT
            IF (@IndexColumns IS NOT NULL) BEGIN
                SET @IsPrimaryKey = IsNULL(ObjectProperty(object_id(@IndexName), 'IsPrimaryKey'), 0)
                SET @IsConstraint = IsNULL(ObjectProperty(object_id(@IndexName), 'IsConstraint'), 0)
                SET @IsClustered  = IsNULL(IndexProperty (object_id(@TableName), @IndexName, 'IsClustered'), 0)
                SET @IsUnique     = IsNULL(IndexProperty (object_id(@TableName), @IndexName, 'IsUnique'   ), 0)

                EXEC @IncludedColumns = GTSGetIndexIncludedColumns @TableName, @IndexName
                IF @IncludedColumns is NULL SET @IncludedColumns = ''

                EXEC GTSUpgradeAddUpgradeIndexDef  @TableName, @IndexName, @IndexColumns,
                     @IsPrimaryKey, @IsConstraint, @IsClustered, @IsUnique, 0 /* Dropped */, @IncludedColumns
                END
            END

        FETCH NEXT FROM SysIndexesCursor INTO @IndexName
        END

    CLOSE SysIndexesCursor
    DEALLOCATE SysIndexesCursor
    END
GO



--
--                     PROCEDURE GTSIndexExistsByColumnDef
--
PRINT '    ' + 'Creating GTSIndexExistsByColumnDef...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSIndexExistsByColumnDef') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSIndexExistsByColumnDef
GO
CREATE PROCEDURE dbo.GTSIndexExistsByColumnDef( @TableName sysname, @IndexColumns varchar(256) ) AS BEGIN
    --
    --  Check if an index for IndexColumn
    --

    EXEC GTSUpgradeGatherTableIndexes @TableName

    IF EXISTS(SELECT IndexName
              FROM TableIndexDefs
              WHERE TableName = @TableName
              AND   IndexColumns = @IndexColumns
              AND   Dropped = 0) RETURN( 1 )

    RETURN( 0 )
    END
GO


--
--                      PROCEDURE GTSAddUpgradeLog
--
PRINT '    ' + 'Creating GTSAddUpgradeLog...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSAddUpgradeLog') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSAddUpgradeLog
GO
CREATE PROCEDURE dbo.GTSAddUpgradeLog( @RunMode  int,
                                   @Log      varchar(4000),
                                   @Indent   int,
                                   @ErrorID  int = 0 ) AS BEGIN
    /*
     *  Insert into UpgradeLogs if not in a test mode
     */
    WHILE (@Indent > 0) BEGIN
        SET @Log = '    ' + @Log
        SET @Indent = @Indent - 1
        END

    /*
     *  If called from GTSUpgradeError, the error message has been printed
     *  So, don't print the error message the second time
     */
    IF (@ErrorID = 0) PRINT @Log

    IF ((@RunMode % 10) = 1)
        INSERT INTO UpgradeLogs VALUES( @Log, GetDate() )
    END
GO



--
--                      PROCEDURE GTSUpgradeDoEndUpgrade
--
PRINT '    ' + 'Creating GTSUpgradeDoEndUpgrade...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeDoEndUpgrade') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeDoEndUpgrade
GO
CREATE PROCEDURE dbo.GTSUpgradeDoEndUpgrade( @RunMode    int,
                                         @Error      int,
                                         @Tablename  sysname) AS BEGIN
    DECLARE
        @Log               varchar(1000),
        @UpgradeHistoryID  int

    IF (@Error = 0)
        SET @Log = 'Upgrade script has completed successfully.'
    ELSE
        SET @Log = 'Error occurred while upgrading "' + @TableName + '" table....upgrade has been terminated.'

    SET @Log = CHAR(13) + @Log
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 0

    IF ((@RunMode % 10) = 1) BEGIN
        SELECT @UpgradeHistoryID = MAX(UpgradeHistoryID) FROM UpgradeHistory

        UPDATE UpgradeHistory SET ErrorID = @Error, Log = Log + CHAR(13) + @Log WHERE UpgradeHistoryID = @UpgradeHistoryID
        END

    /*
     *  Now, the script is done.  Update all the ManualUpgradeTables entries to be Manual
     */
    EXEC( 'UPDATE ManualUpgradeTables SET Manual = 1' )
    END
GO



--
--                      PROCEDURE GTSUpgradeError
--
PRINT '    ' + 'Creating GTSUpgradeError...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeError') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeError
GO
CREATE PROCEDURE dbo.GTSUpgradeError( @RunMode int, @Error int OUTPUT, @ErrorStr varchar(3900) ) AS BEGIN
    DECLARE
        @UpgradeHistoryID int

    /*
      @Error
        -1:  alter column:  column has dependent indexes
        -2:  'Cannot modify "' + @Column + '" column because it does not exists in table "' + @TableName + '"!!!'
        -3:  'Default value not found for "' + @TableName + '.' + @Column + '".'
        -4:  GTSUpgradeRenameColumn():  'Column ' + @ColumnName + ' does not exists in the table ' + @TableName + '.'
        -5:  PK/Index name already exists in DB and @SkipDupIndexName = 0.

      others:  system error
    */

    raiserror(@ErrorStr, 16, 1)

    IF ((@RunMode % 10) = 1) BEGIN
        SELECT @UpgradeHistoryID = MAX(UpgradeHistoryID) FROM UpgradeHistory

        UPDATE UpgradeHistory SET ErrorID = @Error, Log = Log + CHAR(13) + @ErrorStr WHERE UpgradeHistoryID = @UpgradeHistoryID
        END

    EXEC GTSAddUpgradeLog  @RunMode, @ErrorStr, 0, @Error

    IF ((@RunMode %10) = 0) SET @Error = 0
    END
GO


--
--                      PROCEDURE GTSUpgradeExecSQL
--
PRINT '    ' + 'Creating GTSUpgradeExecSQL...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeExecSQL') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeExecSQL
GO
CREATE PROCEDURE dbo.GTSUpgradeExecSQL( @RunMode      int,
                                    @Error            int OUTPUT,
                                    @SQL              varchar(7900),
                                    @GiveASpace       bit = 1,
                                    @SuppressDisplay  bit = 0,
                                    @DontUseNoCount   bit = 0 ) AS BEGIN
    --
    --  calls SQL EXECute statement with a given @SQL statement.  If an error occurs,
    --  it prints the SQL statement which caused the error
    --
    DECLARE
        @Log            varchar(4000),
        @Indent         int,
        @Err            int,
        @SQL1           varchar(3900),
        @SQL2           varchar(3900),
        @CreateSQL      varchar(200),
        @AffectedSQL    varchar(200),
        @NoCountOnSQL   varchar(200)

    SELECT @SQL1 = SubString(@SQL, 1,    3700)
    SELECT @SQL2 = SubString(@SQL, 3701, 3700)

    IF (@SuppressDisplay = 0) BEGIN
        IF SubString(@SQL1, 1, 12) = 'CREATE TABLE'
            SET @Indent = 1
        ELSE
            SET @Indent = 2

        EXEC GTSAddUpgradeLog  @RunMode, @SQL1, @Indent
        END

    IF ((@RunMode % 10) = 1) BEGIN   -- execute the SQL statement if not in a test mode
        IF @DontUseNoCount = 0
            SET @NoCountOnSQL = 'SET nocount ON ' + CHAR(13) -- we are going to manage "(x row(s) affected)"
        ELSE
            SET @NoCountOnSQL = ''

        IF (@SuppressDisplay = 0)
            SET @AffectedSQL = CHAR(13) + -- add "(x row(s) affected)"
                   'PRINT ''        ('' + convert(varchar, @@RowCount) + '' row(s) affected)'' + '' '' '


        IF SubString(@SQL1, 1, 14) = 'CREATE TRIGGER'
            EXEC(@SQL1 + @SQL2 )
        ELSE
            EXEC( @NoCountOnSQL + @SQL1 + @SQL2 + @AffectedSQL )

        SELECT @Err = @@Error

        IF @Err <> 0 BEGIN
            SELECT @Error = @Err
            SET @SQL1 = 'Error occurred while executing the SQL statement below.' + CHAR(13) + CHAR(13) +
                       @SQL1 + CHAR(13) + ' '
            EXEC GTSUpgradeError  @RunMode, @Error OUTPUT, @SQL1
            END
        END

    IF (@GiveASpace = 1) EXEC GTSAddUpgradeLog  @RunMode, ' ', @Indent
    END
GO

--
--                      PROCEDURE GTSUpgradeAddTable
--
PRINT '    ' + 'Creating GTSUpgradeAddTable...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeAddTable') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeAddTable
GO
CREATE PROCEDURE dbo.GTSUpgradeAddTable( @RunMode             int,
                                         @Error               int OUTPUT,
                                         @TableName           sysname,
                                         @TableStructure      varchar(7500) ) AS BEGIN
    --
    --  creates a table if the table does not exist
    --
    SET nocount ON

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    DECLARE
        @SQL          varchar(7900),
        @Log          varchar(2000),
        @Indent       int,
        @TableExists  bit

    IF ((@RunMode / 10) = 1)
        SET @Log = 'Checking for a table upgrade --->  dbo.' + @TableName + ' at ' + convert(varchar, GetDate(),9)
    ELSE
        SET @Log = 'Checking for a Post upgrade  --->  dbo.' + @TableName + ' at ' + convert(varchar, GetDate(),9)

    EXEC GTSAddUpgradeLog  @RunMode, @Log, 0

    -- don't do anything if table is set as manual upgrade
    IF EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1)) BEGIN
        SET @Log = '    ' + '*******************************************************' + CHAR(13) +
                   '    ' + '***      This table is set as Manual Upgrade.       ***' + CHAR(13) +
                   '    ' + '***  The scripts to upgrade the table are supplied  ***' + CHAR(13) +
                   '    ' + '***      BUT the scripts will NOT be executed.      ***' + CHAR(13) +
                   '    ' + '*******************************************************'

        EXEC GTSAddUpgradeLog  @RunMode, @Log, 0

        IF ((@RunMode % 10) = 1) SET @RunMode = @RunMode - 1   -- if not in test mode, make it a test mode
        END

    EXEC @TableExists = GTSTableExists  @TableName
    IF (@TableExists = 0) BEGIN

        SELECT @SQL = 'CREATE TABLE dbo.' + @TableName + ' ( '
        SELECT @SQL = @SQL + @TableStructure
        SELECT @SQL = @SQL + '    ' + '    ' + ')'

        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    END
GO



--
--                      PROCEDURE GTSHasClusteredPK
--
PRINT '    ' + 'Creating GTSHasClusteredPK...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSHasClusteredPK') AND (o.type = 'FN')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP FUNCTION dbo.GTSHasClusteredPK
GO
CREATE FUNCTION dbo.GTSHasClusteredPK(@TableName  sysname) RETURNS BIT AS BEGIN
    /*
      This UD function returns true (1) if TableName's PK is a clustered index
    */
    DECLARE
        @PKID   integer,
        @PK      sysname

    SELECT @PK = name, @PKID = id FROM SysObjects WHERE parent_obj = object_id(@TableName)
    IF @PK IS NULL RETURN( 0 )

    RETURN( OBJECTPROPERTY(@PKID, 'CnstIsClustKey') )
    END
GO

