--
--                      PROCEDURE GTSUpgradeAddPK
--
PRINT '    ' + 'Creating GTSUpgradeAddPK...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeAddPK') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeAddPK
GO
CREATE PROCEDURE dbo.GTSUpgradeAddPK( @RunMode    int,
                                  @Error      int OUTPUT,
                                  @TableName  sysname,
                                  @PKColumns  varchar(256),
                                  @PKName     sysname,
                                  @CLUSTERED  varchar(15) = 'CLUSTERED' ) AS BEGIN
    --
    --  This stored procedure adds a NON/CLUSTERED primary key constraints.
    --
    -- @CLUSTERED: "Clustered" (default) or "NonClustered"
    --
    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    /*
     *  If table is set as Manual Upgrade, set the upgrade as TestMode for this table.
     *  So that any upgrades to this table are displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1  -- make it a test mode

    DECLARE
        @SQL           varchar(1000),
        @HasPK         bit,
        @Log           varchar(1000),
        @PKNameExists  bit,
        @IndexExists   bit

    EXEC @IndexExists = GTSIndexExistsByColumnDef @TableName, @PKColumns
    IF @IndexExists = 1 RETURN

    /*
     *  If table has already has clustered index, create non-clustered PK
     */
    IF ObjectProperty(object_id(@TableName), 'TableHasClustIndex') = 1 SELECT @CLUSTERED = 'NONCLUSTERED'

    EXEC @HasPK = GTSTableHasPK  @TableName
    IF (@HasPK = 0) BEGIN
        /* if PKName already exists in DB, skip the PK creation */
        EXEC @PKNameExists = GTSIndexExists @TableName, @PKName
        IF @PKNameExists = 1 BEGIN
            IF EXISTS(SELECT Value FROM UpgradeSettings WHERE Setting = 'Skip Dup PK/Index name' and Value = 1) BEGIN
                SET @Log = 'PKName "' + @PKName +'" already exists in DB...Upgrade option @SkipDupIndexName is set to skip index creation...'
                EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
                SET @RunMode = @RunMode - 1  -- make it a test mode
                END
            ELSE BEGIN
                SET @Error = -5
                SET @Log = 'PKName "' + @PKName +'" already exists in DB...Upgrade option @SkipDupIndexName is not set to skip index creation...'
                EXEC GTSUpgradeError @RunMode, @Error, @Log
                RETURN
                END
            END

        IF (@PKColumns NOT LIKE '%,%') AND  -- only one column PK
           (ColumnProperty(object_id(@TableName), @PKColumns, 'AllowsNULL') = 1) BEGIN
            /*
             *  PK Column is NULLable, so don't try to create a PK for this table.
             *  The creation of PK is done by the Post upgrade script mode
             */
            RETURN
            END

        SET @Log = 'Adding Primary Key constraint "' + @PKName + '"...'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

        SET @SQL = 'ALTER TABLE ' + @TableName + ' ADD CONSTRAINT ' + @PKName + ' ' +
                   'PRIMARY KEY ' + @CLUSTERED + ' (' + @PKColumns + ')'

        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    END
GO



--
--                      PROCEDURE GTSUpgradeDropIndexByName
--
PRINT '    ' + 'Creating GTSUpgradeDropIndexByName...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeDropIndexByName') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeDropIndexByName
GO
CREATE PROCEDURE dbo.GTSUpgradeDropIndexByName(@RunMode    int,
                                         @Error      int OUTPUT,
                                         @TableName  sysname,
                                         @IndexName  sysname,
                                         @ObsoleteIt bit = 0) AS BEGIN
    /*
     This proc simply drops the given index (or constraint) name
     */
    SET NOCOUNT ON

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    DECLARE
         @IsConstraint  bit,
         @IsClustered   bit,
         @IsUnique      bit,
         @IndexColumns  varchar(256),
         @SQL           varchar(256),
         @Log           varchar(256)

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    -- collect Index defs for this table
    EXEC GTSUpgradeGatherTableIndexes  @TableName

    SELECT @IndexColumns = IndexColumns, @IsConstraint = IsConstraint, @IsUnique = IsUnique, @IsClustered = IsClustered
    FROM TableIndexDefs
    WHERE (TableName = @TableName) AND (IndexName = @IndexName) and (Dropped = 0)

    /* if index is not found, just bail */
    IF @IndexColumns IS NULL RETURN

    SET @Log = 'Dropping'
    IF @IsUnique     = 1 SET @Log = @Log + ' ' + 'Unique'
    IF @IsClustered  = 1 SET @Log = @Log + ' ' + 'Clustered'
    IF @IsConstraint = 1
        SET @Log = @Log + ' ' + 'Constraint'
    ELSE
        SET @Log = @Log + ' ' + 'Index'
    SET @Log = @Log + ' ' + @IndexName + ' on (' + @IndexColumns + ')'
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

    IF @IsConstraint = 1 BEGIN
        SET @SQL = 'ALTER TABLE ' + @TableName + ' DROP CONSTRAINT ' + @IndexName
        END
    ELSE BEGIN
        SET @SQL = 'DROP INDEX ' + @TableName + '.' + @IndexName
        END

    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

    /*
     *  For obsoleting index, "remove" the entry from recreate index process
     */
    IF @ObsoleteIt = 1 BEGIN
        UPDATE TableIndexDefs SET Dropped = 0
        WHERE  TableName = @TableName
        AND    IndexName = @IndexName
        END
    --DAD 091204 When not in test mode, explicitly set Dropped = 1
    ELSE IF ((@RunMode % 10) = 1) BEGIN
        UPDATE TableIndexDefs SET Dropped = 1
        WHERE  TableName = @TableName
        AND    IndexName = @IndexName
        END
    END
GO


--
--                      PROCEDURE GTSUpgradeDropIndexByColumn
--
PRINT '    ' + 'Creating GTSUpgradeDropIndexByColumn...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeDropIndexByColumn') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeDropIndexByColumn
GO
CREATE PROCEDURE dbo.GTSUpgradeDropIndexByColumn( @RunMode     int,
                                          @Error       int OUTPUT,
                                          @TableName   sysname,
                                          @IXColumns   varchar(256),
                                          @ObsoleteIt  bit = 0) AS BEGIN
    /*
     *  Remove obsolete indexes created by GTS by column
     */

    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    /*
     *  If not POST upgrade mode, don't bother
     */
    IF ((@RunMode / 10) <> 2) RETURN

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    DECLARE
        @SQL           varchar(256),
        @IXName        sysname,
        @Log           varchar(1000)

    SELECT @IXName = NULL

    EXEC GTSUpgradeGatherTableIndexes @TableName
    SELECT @IXName = IndexName
    FROM TableIndexDefs
    WHERE TableName = @TableName
    AND   IndexColumns = @IXColumns

    /*
     *  If we have don't have a matching column definition, don't bother
     */
    IF @IXName IS NULL RETURN

    EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, @IXName, @ObsoleteIt

    END
GO




--
--                      PROCEDURE GTSUpgradeJnlClusterIndexChangeDropObsoleteIndex
--
PRINT '    ' + 'Creating GTSUpgradeJnlClusterIndexChangeDropObsoleteIndex...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeJnlClusterIndexChangeDropObsoleteIndex') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeJnlClusterIndexChangeDropObsoleteIndex
GO
CREATE PROCEDURE dbo.GTSUpgradeJnlClusterIndexChangeDropObsoleteIndex(
                                         @RunMode    int,
                                         @Error      int OUTPUT,
                                         @TableName  sysname) AS BEGIN

    /*
     *  Once the Jnl tables clustered index have changed, Galaxy no longer needs
     *  an index on JnlTranID since it is covered under the clustered index.
     *  Hence, remove the index on JnlTranID
     */

    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc
    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    IF ((@RunMode / 10) <> 2) RETURN    -- if not POS Upgrade mode, don't bother

    DECLARE
        @IXName sysname

    EXEC GTSUpgradeGatherTableIndexes @TableName

    SELECT @IXName = NULL

    /*
     *  First check if there is a clustered index with columns starting with JnlTranID
     */
    SELECT @IXName = IndexName
    FROM TableIndexDefs
    WHERE TableName = @TableName
    AND   IsClustered = 1
    AND   IndexColumns LIKE 'JnlTranID,%'

    IF @IXName IS NOT NULL BEGIN
        EXEC GTSUpgradeDropIndexByColumn @RunMode, @Error OUTPUT, @TableName, JnlTranID, 1 /* obsolete it */
        END
    END
GO



--
--                      PROCEDURE GTSUpgradeDropColumn
--
PRINT '    ' + 'Creating GTSUpgradeDropColumn...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeDropColumn') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeDropColumn
GO
CREATE PROCEDURE dbo.GTSUpgradeDropColumn( @RunMode              int,
                                           @Error                int OUTPUT,
                                           @TableName            sysname,
                                           @ColumnName           sysname,
                                           @DropObsoletedColumns bit) AS BEGIN
    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    DECLARE
        @SQL           varchar(1000),
        @TableExists   bit,
        @ColumnExists  bit,
        @Log           varchar(1000)

    EXEC @TableExists  = GTSTableExists  @TableName
    IF (@TableExists = 0) BEGIN
        SET @Log = 'UpgradeDropColumn: Table "' + @TableName + '" does not exist.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

        RETURN
        END

    EXEC @ColumnExists = GTSColumnExists  @TableName, @ColumnName
    IF (@ColumnExists = 0) BEGIN
        SET @Log = 'UpgradeDropColumn: Column "' + @ColumnName + '" does not exist.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

        RETURN
        END

    /*
     *  Only allow GTSUpgradeDropColumn to proceed if @RunMode is 21 and
     *  @DropObsoletedColumns is 1.
     */
    IF NOT ((@RunMode = 21) AND (@DropObsoletedColumns = 1)) BEGIN
        SET @Log = 'UpgradeDropColumn: Column"' + @ColumnName + '" not dropped. Set @RunMode = 21 and @DropObsoletedColumns = 1 to drop column.'
        EXEC GTSAddUpgradeLog @RunMode, @Log, 1

        RETURN
        END

    SET @Log = '*** Dropping existing column "' + @ColumnName + '" ***'
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

    SET @SQL = 'ALTER TABLE ' + @TableName + ' DROP COLUMN ' + @ColumnName
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END
GO


--
--                      PROCEDURE GTSUpgradeAddIndex
--
PRINT '    ' + 'Creating GTSUpgradeAddIndex...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeAddIndex') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeAddIndex
GO
CREATE PROCEDURE dbo.GTSUpgradeAddIndex( @RunMode     int,
                                         @Error       int OUTPUT,
                                         @TableName   sysname,
                                         @IXColumns   varchar(256),
                                         @IXName      sysname,
                                         @Unique      varchar(15) = '',
                                         @Clustered   varchar(15) = '',
                                         @FillFactor  int = 0,
                                         @IncludeColumns varchar(256) = '',
                                         @FilterWhereClause varchar(256) = '') AS BEGIN
    --
    --  This stored procedure creates a [UNIQUE] [CLUSTERED] index.
    --  It takes 9 parameters where last four are optional.
    --      @Unique:    creates an UNIQUE index, default is non
    --      @Clustered: creates a CLUSTERED index, default is non
    --
    --  NOTE: Make sure there are NO spaces between the commas and column names
    --  for the @IncludeColumns parameter. Example:
    --
    --          'Qty,Price,PLU,VisualID'
    --
    --  If the index with the same columns already exists, the new
    --  index will not be created unless
    --       1. the new index is an unique index and the existing
    --          index is not.  The old index is dropped
    --       2. The specified included columns don't match the existing included columns
    --       3. clustered vs non clusterd...not implemented...
    --
    --
    -- @Unique:    "UNIQUE" or "" (non unique)
    -- @Clustered: "CLUSTERED" or "" (non clustered)
    --

    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    DECLARE
        @SQL           varchar(1000),
        @IndexName     sysname,
        @IndexExists   bit,
        @IsConstraint  bit,
        @IsUnique      bit,
        @Log           varchar(1000),
        @IndexDropped  bit,
        @IXNameExists  bit,
        @DBVersion     varchar(10),
        @DBEdition	   int,
        @DBLevel	   varchar(128),
        @AllowOnlineIndex bit,
        @Edition_Enterprise int,
        @Edition_Developer int,
        @Edition_Enterprise_Core int,
        @IncludedColumnsMatch int,
        @IsManagedInstance bit

    IF (@Error <> 0) RETURN  -- Bail out if an error occurred
    SET @Edition_Enterprise      =  1804890536 -- Return value of SERVERPROPERTY('EditionID') for Enterprise Edition
    SET @Edition_Enterprise_Core =  1872460670 -- Return value of SERVERPROPERTY('EditionID') for Enterprise Edition: Core-based Licensing
    SET @Edition_Developer       = -2117995310 -- Return value of SERVERPROPERTY('EditionID') for Developer Edition
    SET @IsManagedInstance       = CASE WHEN CONVERT(INT, SERVERPROPERTY('EngineEdition')) = 8 THEN 1 ELSE 0 END

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    -- collect Index defs for this table
    EXEC GTSUpgradeGatherTableIndexes  @TableName

    -- Remove all spaces from @IXColumns and @IncludeColumns
    SET @IXColumns = REPLACE(@IXColumns, ' ', '')
    SET @IncludeColumns = REPLACE(@IncludeColumns, ' ', '')

    SELECT @IndexName = IndexName, @IsConstraint = IsConstraint, @IsUnique = IsUnique, @IndexDropped = Dropped
        FROM TableIndexDefs
        --DAD 091204  add (Dropped = 0) to WHERE
        WHERE (TableName = @TableName) AND (IndexColumns = @IXColumns) and (Dropped = 0) and ((IncludeColumns is NULL) or (IncludeColumns = @IncludeColumns))

    IF (@IndexName IS NOT NULL) BEGIN
        /*
         *  An index already exists with a same column definition.
         */

        --DAD 091204 if in test mode, add note to log
        IF ((@RunMode % 10) = 0) BEGIN
            SET @Log = 'If not existing, will Add'
            SET @Log = @Log + ' ' + 'index ' + @IXName + ' on (' + @IXColumns + ')'

    	    IF (@IncludeColumns <> '') SET @Log = @Log + ' including (' + @IncludeColumns + ')'

            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            END

        IF ((@Unique = '') AND (@IsUnique = 0)) OR ((@Unique <> '') AND (@IsUnique = 1)) BEGIN
            -- index already exists and UNIQUEness are not different
            RETURN
            END
        END

    SET @Log = 'Adding'
    IF @Unique    <> '' SET @Log = @Log + ' ' + @Unique
    IF @Clustered <> '' SET @Log = @Log + ' ' + @Clustered
    SET @Log = @Log + ' ' + 'index ' + @IXName + ' on (' + @IXColumns + ')'

    IF (@IncludeColumns <> '') SET @Log = @Log + ' including (' + @IncludeColumns + ')'

    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

    IF ((@IndexName IS NOT NULL) and (@IsUnique = 0) and (@IndexDropped = 0)) BEGIN
        /*
         * New index is unique but existing one is not.  Drop existing index
         */
        IF (@IsConstraint = 1) BEGIN
            SET @Log = 'Dropping existing non unique constraint because the new constraint is unique or included columns changed'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @SQL = '    ' + 'ALTER TABLE ' + @TableName + ' DROP CONSTRAINT ' + @IndexName
            END
        ELSE BEGIN
            SET @Log = 'Dropping existing non unique index because the new index is unique or included columns changed'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @SQL = '    ' + 'DROP INDEX ' + @TableName + '.' + @IndexName
            END

        SET @IndexDropped = 1   -- for test mode...
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    /*
     *  Now, by the time we come to this point, the index name should not exist
     *  in the table, but there is still a possibility.  AND it is happening for
     *  OrderLines.IXOrderlinesOrderIDLineNbr index.
     *  one of the older version has this index ON (OrderID,LineNbr), but
     *  newer version of Galaxy has this index on (OrderLineID,LineNbr).
     *  notify that this has occurred.
     */
    EXEC @IndexExists = GTSIndexExistsByColumnDef @TableName, @IXColumns
    IF (@IndexExists = 1) AND ((@IndexDropped = 0) or (@IndexDropped is NULL)) BEGIN
        DECLARE  @IndexColumns  varchar(256)
        EXEC GTSGetIndexColumns  @TableName, @IXName, @IndexColumns OUTPUT

        SET @Log = 'Column definition for the index "' + @IXName + '" is different.  Old: (' + @IndexColumns + '),  New: (' + @IXColumns + ')' + CHAR(13) + '    ' + '    ' +
                   'Dropping old definition and creating index with the new definition'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2

        EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, @IXName
        END


    /* if Index Name already exists in DB, skip the index creation */
    EXEC @IXNameExists = GTSIndexExists @TableName, @IXName
    IF @IXNameExists = 1 BEGIN
        IF EXISTS(SELECT Value FROM UpgradeSettings WHERE Setting = 'Skip Dup PK/Index name' and Value = 1) BEGIN
            SET @Log = 'Index Name "' + @IXName +'" already exists in DB...Upgrade option @SkipDupIndexName is set to skip index creation...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            SET @RunMode = @RunMode - 1  -- make it a test mode
            END
        ELSE BEGIN
            SET @Log = 'Index Name "' + @IXName +'" already exists in DB...Upgrade option @SkipDupIndexName is not set to skip index creation...'
            IF ((@RunMode % 10) = 1) BEGIN
                SET @Error = -5
                EXEC GTSUpgradeError @RunMode, @Error, @Log
                END
            ELSE BEGIN
                SET @Log = 'Upgrade Error (-5): ' + @Log
                EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
                END
            RETURN
            END
        END

    SET @SQL = 'CREATE '  + @Unique + ' ' + @Clustered + ' INDEX ' + @IXName + ' ON ' +
                            @TableName + '(' + @IXColumns + ')'

    IF @IncludeColumns <> '' BEGIN
	    SET @SQL = @SQL + ' INCLUDE (' + @IncludeColumns + ')'
        END

    IF @FilterWhereClause <> '' BEGIN
	    SET @SQL = @SQL + ' WHERE ' + @FilterWhereClause
        END

	SET @DBVersion = CONVERT(VARCHAR, ServerProperty('productversion'))
	SET @DBVersion = LEFT(@DBVersion, CHARINDEX('.', @DBVersion) - 1)
    SET @DBEdition = CONVERT(INT, ServerProperty('EditionID'))
	SET @DBLevel   = CONVERT(VARCHAR, ServerProperty('ProductLevel'))

    -- Online Indexes are only supported with version 2005+ using the Enterprise or Developer editions, or on SQL Managed Instances
    IF ((CONVERT(SMALLINT, @DBVersion) >= 9) AND (@DBEdition IN (@Edition_Enterprise, @Edition_Enterprise_Core, @Edition_Developer))) OR
       (@IsManagedInstance = 1) BEGIN
	     -- If clustered, none of the fields can be a LOB type, otherwise only
		 -- the fields in the index are restricted from being a LOB field type
		 IF @Clustered = '' BEGIN
		      -- SQL Server 2005 RTM doesn't support unique non-clustered online indexes
		      IF (@Unique <> '') AND (CONVERT(SMALLINT, @DBVersion) = 9) AND (@DBLevel = 'RTM')
                  SET @AllowOnlineIndex=0
			  ELSE SET @AllowOnlineIndex = dbo.GTSFieldsSupportOnlineIndex(@TableName, @IXColumns)
			  END
		 ELSE SET @AllowOnlineIndex = dbo.GTSTableSupportsClusteredOnlineIndex(@TableName)
		 END
	ELSE SET @AllowOnlineIndex=0

    IF (@FillFactor <> 0) OR (@AllowOnlineIndex = 1)
    BEGIN
		SET @SQL = @SQL + ' ' + 'WITH ('
		IF @AllowOnlineIndex = 1 BEGIN
			SET @SQL = @SQL + 'ONLINE = ON'
			IF @FillFactor <> 0 SET @SQL = @SQL + ', FILLFACTOR = ' + CONVERT(VARCHAR, @FillFactor)
   		    END
		ELSE SET @SQL = @SQL + 'FILLFACTOR = ' + CONVERT(VARCHAR, @FillFactor)
		SET @SQL = @SQL + ')'
	END
    PRINT @SQL
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END
GO



--
--                      PROCEDURE GTSUpgradeAddClusteredIndex
--
PRINT '    ' + 'Creating GTSUpgradeAddClusteredIndex...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeAddClusteredIndex') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeAddClusteredIndex
GO
CREATE PROCEDURE dbo.GTSUpgradeAddClusteredIndex(@RunMode    int,
                                                 @Error      int OUTPUT,
                                                 @TableName  sysname,
                                                 @IXColumns  varchar(256),
                                                 @IXName     sysname,
                                                 @FillFactor int = 0) AS BEGIN
    /*
     add a clustered index.
     First, it must check if there is already a cluster index or constraint.
     If there is and it is not the index we are trying to add, it must be dropped
     dropped.

     So, caller must be very careful when calling this routine since it can be very expensive.
     */
    SET NOCOUNT ON

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    -- if option to change clustered index is not set just bail out
    -- IF NOT EXISTS(SELECT Value FROM UpgradeSettings WHERE Setting = 'Allow Clustered Index Change' AND Value = 1) RETURN

    DECLARE
         @ExistingClusteredIndex  sysname,
         @ExistingIndexColumns    varchar(256)

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    -- collect Index defs for this table
    EXEC GTSUpgradeGatherTableIndexes  @TableName

    /* check if we already have a clustered index */
    SELECT @ExistingClusteredIndex = IndexName, @ExistingIndexColumns = IndexColumns
    FROM TableIndexDefs
    WHERE (TableName = @TableName) AND (IsClustered = 1)

    /* first check if existing clustered index has the same columns as the one we are trying to add */
    IF @ExistingIndexColumns = @IXColumns RETURN     -- no change is needed

    IF @ExistingClusteredIndex IS NOT NULL BEGIN
        /* The index columns are different, drop the existing one */
        EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, @ExistingClusteredIndex, 1 /* obsolete it */
        END

    /* create new */
    EXEC GTSUpgradeAddIndex @RunMode, @Error OUTPUT, @TableName, @IXColumns, @IXName, '', 'CLUSTERED', @FillFactor
    END
GO




--
--                      PROCEDURE GTSUpgradeAddJnlPK
--
PRINT '    ' + 'Creating GTSUpgradeAddJnlPK...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeAddJnlPK') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeAddJnlPK
GO
CREATE PROCEDURE dbo.GTSUpgradeAddJnlPK( @RunMode    int,
                                         @Error      int OUTPUT,
                                         @TableName  sysname,
                                         @PKColumns  varchar(256),
                                         @PKName     sysname,
                                         @IndexName  sysname) AS BEGIN
    /*
    This stored procedure removes clustered index on jnl* primary key
    and add clustered index on (JnlTranID, jnl*ID)

    if PK does not exists
        Add non-clustered PK
        Add clustered index on (JnlTranID, Jnl*ID)
        done

    Check PK is Clustered
        if clustered, check @ChangeJnlClusteredIndex option
            if option set
                remove PK clustered index
                add clustered index on (JnlTranID, Jnl*ID)
            if option not set dont do anything
        if non-clustered, check @ChangeJnlClusteredIndex option
            if option set
                add clustered index on (JnlTranID, Jnl*ID)
            if option not set, don't do anything
    */
    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1  -- make it a test mode

    DECLARE
        @HasPK         bit,
        @xPKName       sysname,
        @IndexColumns  sysname,
        @ChangeJnlClusteredIndex bit

    SELECT @IndexColumns = 'JnlTranID,' + @PKColumns
    EXEC @HasPK = GTSTableHasPK  @TableName
    IF (@HasPK = 0) BEGIN
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, @IndexColumns, @IndexName, 'UNIQUE', 'CLUSTERED'
        EXEC GTSUpgradeAddPK     @RunMode, @Error OUTPUT, @TableName, @PKColumns,    @PKName,    'NONCLUSTERED'
        RETURN
        END

    SELECT @ChangeJnlClusteredIndex = convert(bit, value) FROM UpgradeSettings WHERE Setting = 'Change Jnl Clustered Index'
    SET @ChangeJnlClusteredIndex = IsNULL(@ChangeJnlClusteredIndex, 0)

    IF (dbo.GTSHasClusteredPK(@TableName) = 1) BEGIN
        IF (@ChangeJnlClusteredIndex = 1) BEGIN
            SELECT @xPKName = dbo.GTSGetPKName(@TableName)
            EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, @xPKName, 1 /* obsolete it */
            EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, @IndexColumns, @IndexName, 'UNIQUE', 'CLUSTERED'
            EXEC GTSUpgradeAddPK     @RunMode, @Error OUTPUT, @TableName, @PKColumns,    @PKName,    'NONCLUSTERED'
            END
        END
    ELSE BEGIN
        IF (@ChangeJnlClusteredIndex = 1) BEGIN
            EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, @IndexColumns, @IndexName, 'UNIQUE', 'CLUSTERED'
            END
        END
    END
GO



--
--                      PROCEDURE GTSUpgradeAddColumn
--
PRINT '    ' + 'Creating GTSUpgradeAddColumn...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeAddColumn') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeAddColumn
GO
CREATE PROCEDURE dbo.GTSUpgradeAddColumn( @RunMode        int,
                                          @Error          int OUTPUT,
                                          @TableName      sysname,
                                          @Column         sysname,
                                          @Type           sysname,
                                          @Length         int      = -1,
                                          @NullStr        char(10) = 'NULL',
                                          @DefaultValue   sysname = NULL,
                                          @IsIdentity     bit = 0) AS BEGIN

    /*
      This stored procedure adds a new column to a table.
      It only adds the column as "NULL" regardless of the actual "NULL/NOT NULL"
      definition.
      It takes max of 5 parameters where the last two are optional
      Optional Params:
          @Length (default = -1):
              This param should ONLY be used for *char type.  This is used
              to construct varchar(22).

          @NullStr (default = 'NULL'):
              This proc basically ignores this parameter and sets the
              column definition to "NULL"
              This may be used later on for something, so it is better to
              pass "NOT NULL" if the column definition is supped to be
              "NOT NULL".  this param is ignored because of backward compatibility
			  If a non-null default value is given, this parameter is not ignored

          @DefaultValue
              This is a initial value to populate the existing rows for the new column

    */

    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    DECLARE
        @SQL           varchar(1000),
        @CharLenStr    varchar(20),
        @TableExists   bit,
        @ColumnExists  bit,
        @Log           varchar(1000)

    EXEC @TableExists  = GTSTableExists  @TableName
    EXEC @ColumnExists = GTSColumnExists  @TableName, @Column

    -- Track all new column additions for end-of-run persistence; flag notable ones for summary display
    IF OBJECT_ID('tempdb..#ColumnAdditions') IS NOT NULL
       AND (@TableExists = 1) AND (@ColumnExists = 0) BEGIN
        DECLARE
            @TrackAddDef      varchar(200),
            @TrackAddDefault  varchar(200),
            @TrackAddShowInSummary bit

        IF @Type LIKE '%char'
            IF (@Type = 'nvarchar') AND (@Length = -1)
                SET @TrackAddDef = @Type + '(max)'
            ELSE
                SET @TrackAddDef = @Type + '(' + CONVERT(varchar, @Length) + ')'
        ELSE
            SET @TrackAddDef = @Type

        SET @TrackAddDef = @TrackAddDef + ' ' + LTRIM(RTRIM(ISNULL(@NullStr, 'NULL')))
        SET @TrackAddDefault = ISNULL(@DefaultValue, '')

        -- Notable additions (NOT NULL or with default value) are shown in end-of-run summary
        IF (LTRIM(RTRIM(@NullStr)) = 'NOT NULL' OR ISNULL(@DefaultValue, '') <> '')
            SET @TrackAddShowInSummary = 1
        ELSE
            SET @TrackAddShowInSummary = 0

        INSERT INTO #ColumnAdditions (TableName, ColumnName, Definition, DefaultValue, ShowInSummary)
        VALUES (@TableName, @Column, @TrackAddDef, @TrackAddDefault, @TrackAddShowInSummary)
    END

    IF (@TableExists = 1) AND (@ColumnExists = 0) BEGIN
        SET @Log = 'Adding a new column "' + @Column + '"'
        IF @DefaultValue IS NULL
            SET @Log = @Log + '...'
        ELSE
            SET @Log = @Log + ' with default value of "' + @DefaultValue + '"'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

        IF (@Type LIKE '%char') BEGIN
            IF (@Type = 'nvarchar') AND (@Length = -1) BEGIN
                SET @CharLenStr = '(max)'
                END
            ELSE BEGIN
                SET @CharLenStr = '(' + convert(varchar, @Length) + ')'  -- i.e. (20)
                END
            END
        ELSE
            SET @CharLenStr = ''

        IF @IsIdentity = 1
            SET @SQL = 'ALTER TABLE ' + @TableName + ' ADD ' + @Column + ' ' +
                @Type + ' ' + @CharLenStr + ' NOT NULL IDENTITY(1,1)'
        ELSE IF @DefaultValue IS NOT NULL
            SET @SQL = 'ALTER TABLE ' + @TableName + ' ADD ' + @Column + ' ' +
                @Type + ' ' + @CharLenStr + ISNULL(@NullStr, ' NULL')
        ELSE
            SET @SQL = 'ALTER TABLE ' + @TableName + ' ADD ' + @Column + ' ' +
                @Type + ' ' + @CharLenStr + ' NULL'

        /*
         if @DefaultValue is given, add the column with a default value.
         */
        IF @DefaultValue IS NOT NULL BEGIN
            SET @SQL = @SQL + ' CONSTRAINT ' + @TableName + @Column + 'Default' +
                              ' DEFAULT ' + @DefaultValue + ' WITH VALUES'
            END

        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    END
GO



--
--                      PROCEDURE GTSUpgradeDropDependencies
--
PRINT '    ' + 'Creating GTSUpgradeDropDependencies...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeDropDependencies') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeDropDependencies
GO
CREATE PROCEDURE dbo.GTSUpgradeDropDependencies( @RunMode         int,
                                             @Error           int OUTPUT,
                                             @TableName       sysname,
                                             @Column          sysname,
                                             @DropDependency  bit    ) AS BEGIN
    --
    --  This stored procedure drops all index/constraints/pk
    --  those are depends on a column so that a column can be
    --  ALTER'ed by the upgrade script.
    --
    --

    SET nocount ON

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    DECLARE DependencyCursor CURSOR FOR
        SELECT IndexName, IsConstraint
        FROM TableIndexDefs
        WHERE (TableName = @TableName) AND ((IndexColumns LIKE '%' + @Column + '%') OR (IncludeColumns LIKE '%' + @Column + '%')) AND (Dropped = 0)
        ORDER BY IsClustered ASC  -- get the clustered index the last, so no unnec. index rebuild..

    DECLARE
        @SQL                varchar(256),
        @Log                varchar(1000),
        @IndexName          sysname,
        @IsConstraint       bit,
        @DependencyDropped  bit

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    OPEN DependencyCursor
    FETCH FROM DependencyCursor INTO @IndexName, @IsConstraint

    SET @DependencyDropped = 0

    IF (@@FETCH_STATUS = 0) BEGIN
        IF (@DropDependency = 0) BEGIN
            PRINT ' '
            SET @Error = -1
            SET @Log = 'The following indexes depend on the column "' + @Column + '".  Drop them manually and re-run the script.' + CHAR(13) +
                       'Or set "DropDependency" to true (1) for UpgradeSettings to automatically drop the dependencies.'  + CHAR(13) +
                       'The scripts to drop the indexes are supplied but is not executed.'
            EXEC GTSUpgradeError @RunMode, @Error OUTPUT, @Log
            END
        ELSE BEGIN
            SET @DependencyDropped = 1
            SET @Log = 'The following indexes depend on the column "' + @Column + '".  They will be dropped before altering the column.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            END
        END

    WHILE (@@FETCH_STATUS = 0) BEGIN
        IF (@IsConstraint = 1)
            SET @SQL = 'ALTER TABLE ' + @TableName + ' ' + 'DROP CONSTRAINT [' + @IndexName + ']'
        ELSE
            SET @SQL = 'DROP INDEX ' + @TableName + '.[' + @IndexName + ']'

        IF (@DropDependency = 0)
            EXEC GTSAddUpgradeLog  @RunMode, @SQL, 2
        ELSE BEGIN
            /*
             *  Drop the index and set the Dropped flag on TableIndexDefs to
             *  TRUE so that same IndexName for the table does not get pickedup
             *  by the cursor query above.  This situation occurs when two+
             *  indexes share a common column.
             */
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

            SET @SQL = 'UPDATE TableIndexDefs SET Dropped = 1 WHERE ' +
                       '(TableName = ''' + @TableName + ''') AND ' +
                       '(IndexName = ''' + @IndexName + ''') '
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END

        FETCH FROM DependencyCursor INTO @IndexName, @IsConstraint
        END

    CLOSE DependencyCursor
    DEALLOCATE DependencyCursor

    RETURN( @DependencyDropped )
    END
GO

--
--                      PROCEDURE CheckRevertingUnicodeColumn
--
PRINT '    ' + 'Creating CheckRevertingUnicodeColumn...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'CheckRevertingUnicodeColumn') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.CheckRevertingUnicodeColumn
GO
CREATE PROCEDURE dbo.CheckRevertingUnicodeColumn(
    @TableName        sysname,
    @Column           sysname,
    @Type             sysname,
    @Length           int,
    @RevertingUnicodeColumn bit OUTPUT) AS BEGIN
    /*
    This stored procedure determines if we're attempting to revert a column
    that is nchar or nvarchar back to a char or varchar type. If we are
    attempting to do this, the @RevertingUnicodeColumn value will be 1, otherwise
    we return 0.
    */
	DECLARE
        @OldColumnType     sysname,
        @OldColumnLen      int,
        @Log               varchar(1000),
        @OldColumnNullable char(10)

    EXEC GTSGetColumnDefinition @TableName, @Column, @OldColumnType OUTPUT, @OldColumnLen OUTPUT, @OldColumnNullable OUTPUT
    IF (@OldColumnType LIKE '%n%') AND (NOT (@Type LIKE '%n%')) AND (@Length * 2 = @OldColumnLen) SET @RevertingUnicodeColumn = 1
    ELSE SET @RevertingUnicodeColumn = 0
	END
GO


--
--                      PROCEDURE GTSUpgradeChangeColumn
--
PRINT '    ' + 'Creating GTSUpgradeChangeColumn...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeChangeColumn') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeChangeColumn
GO
CREATE PROCEDURE dbo.GTSUpgradeChangeColumn( @RunMode          int,
                                         @Error            int OUTPUT,
                                         @DropDependency   bit,
                                         @TableName        sysname,
                                         @Column           sysname,
                                         @Type             sysname,
                                         @Length           int = -1,
                                         @NullStr          char(10) = 'NULL') AS BEGIN
    --
    --  This stored procedure changes a give column definition to a new.
    --  It takes max of 5 parameters where the last two are optional
    --  Optional Params:
    --      @Length (default = -1):
    --          This param should ONLY be used for *char type changes.
    --          When this param is omitted or the default value is pass'ed to it
    --          it ignores the length check.  An example of this is changing
    --          a "float" to a "money".  This does not need to check the length
    --
    --      @NullStr (default = 'NULL'):
    --          This parameter should ONLY be used when column has been changed
    --          from "NOT NULL" to "NULL".  Since we want to keep the
    --          upgrade a backward compatible, only the "NOT NULL" to "NULL"
    --          change is allowed at the time of the Upgrade script.
    --          A "NULL" to "NOT NULL" change should omit this param and handle
    --          the "NOT NULL" change in the Post upgrade script.
    --

    IF ((@RunMode / 10) = 2) RETURN   /* for now, if in post upgrade mode, just exit */

    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    DECLARE
        @SQL                       varchar(1000),
        @CharLenStr                varchar(20),
        @ColumnExists              bit,
        @TableExists               bit,    -- for TestMode
        @SameColumnDef             bit,
        @SameColumnDefWithNULL     bit,
        @SameColumnDefWithNotNULL  bit,
        @DependencyDropped         bit,
        @OldColumnType             sysname,
        @OldColumnLen              int,
        @OldColumnNullable         char(10),
        @Option                    varchar(50),
        @OptionValue               varchar(256),
        @Log                       varchar(1000),
        @RevertingUnicodeColumn    bit

    /*
     *  If in TestMode and the table does not exists, this means that the table is new.
     *  So, we don't need to check for column changes since the table definition is up-to-date
     */
    EXEC @TableExists = GTSTableExists  @TableName
    IF (@TableExists = 0) AND ((@RunMode % 10) = 0) RETURN

    -- collect Index defs for this table
    EXEC GTSUpgradeGatherTableIndexes  @TableName

    /*
     *  If the column does not exists, give an error and return
     */
    EXEC @ColumnExists = GTSColumnExists  @TableName, @Column
    /*
    IF (@ColumnExists = 0) AND ((@RunMode %10) = 1) BEGIN
        SET @Error = -2
        SET @Log = 'Cannot modify "' + @Column + '" column because it does not exists in table "' + @TableName + '"!!!'
        EXEC GTSUpgradeError  @RunMode, @Error OUTPUT, @Log
        RETURN
        END
    */

    IF @ColumnExists = 0 RETURN
    /*
    If the column does not exist, then don't bother!!
    */

    EXEC @SameColumnDef = GTSSameColumnDef  @TableName, @Column, @Type, @Length, @NullStr
    IF (@SameColumnDef = 1) RETURN

    /*
     *  the following two calls to GTSSameColumnDef are to prevent executing same SQL by running
     *  the same mode multiple times.
     */
    EXEC @SameColumnDefWithNULL    = GTSSameColumnDef  @TableName, @Column, @Type, @Length, 'NULL'
    EXEC @SameColumnDefWithNotNULL = GTSSameColumnDef  @TableName, @Column, @Type, @Length, 'NOT NULL'

    IF ((@RunMode / 10) = 1 /* upgrade mode */) AND (@SameColumnDefWithNULL    = 1) AND (@NullStr = 'NOT NULL') RETURN
    IF ((@RunMode / 10) = 2 /* post upgrade */) AND (@SameColumnDefWithNotNULL = 1) AND (@NullStr = 'NOT NULL') RETURN


    /*
     *  Now check for @IgnoreVarcharToCharChange and @IgnoreOneCharLengthChange upgrade options
     */

    IF (@Type LIKE '%char') BEGIN
        EXEC GTSGetColumnDefinition @TableName, @Column, @OldColumnType OUTPUT, @OldColumnLen OUTPUT, @OldColumnNullable OUTPUT

        SET @Option = 'Ignore Varchar To Char Change'
        SELECT @OptionValue = Convert(int, Value) FROM UpgradeSettings WHERE Setting = @Option
        SET @OptionValue = IsNULL(@OptionValue, 0)
        IF (@OptionValue = 1) AND (@Length = @OldColumnLen) AND (@OldColumnType LIKE '%char') AND (@Type <> @OldColumnType) AND (@Type <> 'nvarchar') BEGIN
            SET @Log = 'Upgrade Option is set to ignore "Varchar to Char" or "Char To Varchar" conversion of the same length'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            SET @Log = 'The following column upgrade script WILL NOT BE executed.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

            SET @RunMode = (@RunMode / 10) * 10   -- make it a test mode so we get the script
            END

        SET @Option = 'Ignore One Char Length Change'
        SELECT @OptionValue = Convert(int, Value) FROM UpgradeSettings WHERE Setting = @Option
        SET @OptionValue = IsNULL(@OptionValue, 0)
        IF (@OptionValue = 1) AND ((@Length - @OldColumnLen) = 1)BEGIN
            SET @Log = 'Upgrade Option is set to ignore increase of one character length upgrade (i.e. char(5) to char(6)).'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            SET @Log = 'The following column upgrade script WILL NOT BE executed.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

            SET @RunMode = (@RunMode / 10) * 10   -- make it a test mode so we get the script
            END

        -- If the existing column is an nchar or nvarchar, bail if we're trying to revert it back to a char or varchar and it's the same size
        EXEC CheckRevertingUnicodeColumn @TableName, @Column, @Type, @Length, @RevertingUnicodeColumn OUTPUT
        IF @RevertingUnicodeColumn = 1 RETURN
        END

    /*
     *  If changing from "NULL" to "NOT NULL" and the existing column is 'NULL', change the
     *  column as "NULL" to maintain the backward compatiblity.  The Post Upgrade script will convert
     *  it to "NOT NULL".
     */
    IF ((@RunMode / 10) = 1 /* upgrade mode */) AND (@NullStr = 'NOT NULL') AND
       (IsNULL(ColumnProperty(object_id(@TableName), @Column, 'AllowsNull'), 1) = 1)
        SET @NullStr = 'NULL'

    SET @Log = 'Upgrading the "' + @Column + '" column...'
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

    -- if there is a dependency, let the user know
    IF EXISTS (SELECT TableName FROM TableIndexDefs
               WHERE (TableName = @TableName) AND ((IndexColumns LIKE '%' + @Column + '%') OR (IncludeColumns LIKE '%' + @Column + '%'))) BEGIN
        /*
         *  Drop the column dependency if the UpgradeSettings are set as so.
         */
        EXEC @DependencyDropped = GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, @TableName, @Column, @DropDependency

        -- not configured to drop when executing, make it a test mode, so the script is printed
        IF (@DropDependency = 0) SET @RunMode = ((@RunMode / 10) * 10)
        END

    IF (@Type LIKE '%char') BEGIN
        IF (@Type = 'nvarchar') AND (@Length = -1) BEGIN
            SET @CharLenStr = '(max)'
            END
        ELSE BEGIN
            SET @CharLenStr = '(' + convert(varchar, @Length) + ')'  -- i.e. (20)
            END
        END
    ELSE
        SET @CharLenStr = ''

    SELECT @SQL = 'ALTER TABLE ' + @TableName + ' ALTER COLUMN ' +
                  @Column + ' ' + @Type + ' ' + @CharLenStr + ' ' + @NullStr

    -- Track column alterations for end-of-run summary
    IF OBJECT_ID('tempdb..#ColumnAlterations') IS NOT NULL BEGIN
        DECLARE
            @TrackOldType     sysname,
            @TrackOldLen      int,
            @TrackOldNullable char(10),
            @TrackOldDef      varchar(200),
            @TrackNewDef      varchar(200)

        EXEC GTSGetColumnDefinition @TableName, @Column, @TrackOldType OUTPUT, @TrackOldLen OUTPUT, @TrackOldNullable OUTPUT
        IF @TrackOldType LIKE '%char'
            IF @TrackOldLen = -1
                SET @TrackOldDef = @TrackOldType + '(max) ' + @TrackOldNullable
            ELSE
                SET @TrackOldDef = @TrackOldType + '(' + CONVERT(varchar, CASE WHEN @TrackOldType LIKE 'n%' THEN @TrackOldLen / 2 ELSE @TrackOldLen END) + ') ' + @TrackOldNullable
        ELSE
            SET @TrackOldDef = @TrackOldType + ' ' + @TrackOldNullable

        IF @Type LIKE '%char'
            SET @TrackNewDef = @Type + CASE WHEN @Type = 'nvarchar' AND @Length = -1 THEN '(max)' ELSE '(' + CONVERT(varchar, @Length) + ')' END + ' ' + @NullStr
        ELSE
            SET @TrackNewDef = @Type + ' ' + @NullStr

        INSERT INTO #ColumnAlterations (TableName, ColumnName, OldDefinition, NewDefinition, ShowInSummary)
        VALUES (@TableName, @Column, @TrackOldDef, @TrackNewDef, 1)
    END

    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

    IF (@DependencyDropped = 1) PRINT ' '
    END
GO



--
--
--                      PROCEDURE GTSUpgradeChangeColumn_SubString
--
PRINT '    ' + 'Creating GTSUpgradeChangeColumn_SubString...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeChangeColumn_SubString') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeChangeColumn_SubString
GO
CREATE PROCEDURE dbo.GTSUpgradeChangeColumn_SubString( @RunMode          int,
                                                   @Error            int OUTPUT,
                                                   @DropDependency   bit,
                                                   @TableName        sysname,
                                                   @Column           sysname,
                                                   @Type             sysname,
                                                   @Length           int = -1,
                                                   @NullStr          char(10) = 'NULL') AS BEGIN
    --
    --  This stored procedure is just like the GTSUpgradeChangeColumn
    --  except that it does SubString the char type before calling the
    --  GTSUpgradeChangeColumn procedure.  This routine is used when
    --  char type has been changed from larger size to smaller size
    --

    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...
    if @Type NOT LIKE '%char' RETURN

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    DECLARE
        @SQL            varchar(1000),
        @CharLenStr     varchar(20),
        @TableExists    bit,
        @SameColumnDef  bit,
        @Log            varchar(1000),
        @RevertingUnicodeColumn bit

    /*
     *  If in TestMode and the table does not exists, this means that the table is new.
     *  So, we don't need to check for column changes since the table definition is up-to-date
     */
    EXEC @TableExists = GTSTableExists  @TableName
    IF (@TableExists = 0) AND ((@RunMode % 10) = 0) RETURN

    EXEC @SameColumnDef = GTSSameColumnDef  @TableName, @Column, @Type, @Length, @NullStr

    IF @SameColumnDef = 1 RETURN

    -- If the existing column is an nchar or nvarchar, bail if we're trying to revert it back to a char or varchar and it's the same size
    EXEC CheckRevertingUnicodeColumn @TableName, @Column, @Type, @Length, @RevertingUnicodeColumn OUTPUT
    IF @RevertingUnicodeColumn = 1 RETURN

    SET @Log = 'Char type column "' + @Column + '" has been changed from larger size to small...truncating data to fit the new size...'
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

    SET @SQL = 'UPDATE ' + @TableName + ' SET ' + @Column + ' = ' +
               'SubString(' + @Column + ', 1, ' + convert(varchar, @Length) + ')'

    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

    EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency, @TableName, @Column, @Type, @Length, @NullStr
    END
GO



--
--                      PROCEDURE GTSUpgradeRenameColumn
--
PRINT '    ' + 'Creating GTSUpgradeRenameColumn...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeRenameColumn') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeRenameColumn
GO
CREATE PROCEDURE dbo.GTSUpgradeRenameColumn( @RunMode        int,
                                             @Error          int OUTPUT,
                                             @TableName      sysname,
                                             @ColumnName     sysname,
                                             @NewColumnName  sysname ) AS BEGIN
    SET nocount ON

    /*
    This procedure renames a column.  It drops all dependent indexes before renaming a column.
    Also, the dropped index will not be auto-recreated due to the script cannot determine
    the correct index name to the columns for the index.
    */
    DECLARE
        @SQL    varchar(256),
        @Log    varchar(1000),
        @Found  bit

    EXEC @Found = GTSTableExists @TableName
    IF @Found = 0 RETURN     -- table does not exists, test mode...
    IF @ColumnName = @NewColumnName RETURN
    EXEC @Found = GTSColumnExists @TableName, @NewColumnName
    IF @Found = 1 RETURN     -- already renamed

    EXEC @Found = GTSColumnExists @TableName, @ColumnName
    IF @Found = 0 BEGIN
        /*
        SET @Log = 'Column ' + @ColumnName + ' does not exists in the table ' + @TableName + '.'
        SET @Error = -4
        EXEC GTSUpgradeError  @RunMode, @Error OUTPUT,  @Log
        */
        RETURN
        END

    EXEC GTSUpgradeGatherTableIndexes  @TableName
    EXEC GTSUpgradeDropDependencies @RunMode, @Error OUTPUT, @TableName, @ColumnName, 1 /* drop it */

    SET @Log = 'Renaming column ' + @TableName + '.' + @ColumnName + ' To ' + @NewColumnName
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

    IF EXISTS(SELECT TableName FROM TableIndexDefs
              WHERE TableName = @TableName
              AND   IndexColumns LIKE '%' + @ColumnName + '%') BEGIN
        SET @Log = 'Note: The dropped dependent indexes will not be auto-recreated by the script.  ' +
                   'This is due to the script cannot determine the correct index name to the columns for the index.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
        END


    SET @SQL = 'EXEC sp_rename ''' + @TableName + '.' + @ColumnName + ''',''' + @NewColumnName + ''''

    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

    /*
    The dropped indexes will not be auto-recreated by the script.  This is due to script cannot
    determine the correct Index name to the columns for the index
    */
    if (@RunMode % 10) = 1 BEGIN
        UPDATE TableIndexDefs SET Dropped = 0
        WHERE TableName = @TableName
        AND   IndexColumns LIKE '%' + @ColumnName + '%'
        END
    END
GO



--
--                      PROCEDURE GTSUpgradeAddAuditColumns
--
PRINT '    ' + 'Creating GTSUpgradeAddAuditColumns...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeAddAuditColumns') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeAddAuditColumns
GO
CREATE PROCEDURE dbo.GTSUpgradeAddAuditColumns( @RunMode    int,
                                            @Error      int OUTPUT,
                                            @TableName  sysname ) AS BEGIN

    --
    --  This stored procedure adds the audit columns with NULL so the upgrade is
    --  backward compatible.  When this proc is used for a table on Upgrade script
    --  the post upgrade script for the same table must call "GTSPostUpgradeAuditColumns"
    --  stored proc
    --

    SET nocount ON  -- turn off printing (1 row(s) affected) for this proc

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    /*
     *  If table is set as Manual Upgrade, set the uprade as TestMode for this table.
     *  So that any upgrades to this table is displayed but not actually applied.
     */
    IF ((@RunMode % 10) = 1) AND EXISTS(SELECT Manual FROM ManualUpgradeTables WHERE (TableName = @TableName) AND (Manual = 1))
        SET @RunMode = @RunMode - 1   -- make it a test mode

    EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  RecordVersion,  int     ,  -1,  'NOT NULL'
    EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  LastUpdate   ,  DateTime,  -1,  'NOT NULL'
    EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  LastUpdatedBy,  varchar,   20,  'NULL'
    END
GO



--
--                      PROCEDURE GTSUpgradeAddNewIDConstraintForGUID
--
PRINT '    ' + 'Creating GTSUpgradeAddNewIDConstraintForGUID...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeAddNewIDConstraintForGUID') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeAddNewIDConstraintForGUID
GO
CREATE PROCEDURE dbo.GTSUpgradeAddNewIDConstraintForGUID( @RunMode        int,
														  @Error          int OUTPUT,
														  @DropDependency bit,
														  @TableName      sysname,
														  @ColumnName     sysname,
												          @ToNotNull      bit = 0) AS BEGIN
    SET nocount ON

    /*
    This procedure adds a default value of newid() to a GUID column (and can change the column to NOT NULL).
    It drops all dependent indexes before performing this operation.

    Optional Params:
        @ToNotNull
            If this bit is set, after adding the default constraint the column will be updated to be NOT NULL
            if it was NULL. This will backfill all existing rows.

            NOTE: Do NOT set this parameter to 1 for potentially larger tables like Orders or OrderLines,
                  as it will take an excessive amount of time to backfill all existing rows!
    */
    DECLARE
        @SQL    varchar(256),
		@ConstraintName varchar(256),
        @Log    varchar(1000),
		@DependencyDropped bit

	SET @ConstraintName = @TableName + @ColumnName + 'Default'

	-- if there is a dependency, let the user know
    IF EXISTS (SELECT TableName FROM TableIndexDefs
               WHERE (TableName = @TableName) AND ((IndexColumns LIKE '%' + @ColumnName + '%') OR (IncludeColumns LIKE '%' + @ColumnName + '%'))) BEGIN
        /*
         *  Drop the column dependency if the UpgradeSettings are set as so.
         */
        EXEC @DependencyDropped = GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, @TableName, @ColumnName, @DropDependency

        -- not configured to drop when executing, make it a test mode, so the script is printed
        IF (@DropDependency = 0) SET @RunMode = ((@RunMode / 10) * 10)
        END

	-- drop existing default if it isn't newid()
	IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME = @ColumnName AND COLUMN_DEFAULT != '(newid())') BEGIN
		SET @Log = 'Dropping existing default constraint for ' + @TableName + '.' + @ColumnName
		EXEC GTSAddUpgradeLog @RunMode, @Log, 1
		SET @SQL = 'ALTER TABLE ' + @TableName + ' DROP CONSTRAINT ' + @ConstraintName
		EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
		END

	IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME = @ColumnName AND COLUMN_DEFAULT IS NULL) BEGIN
		SET @Log = 'Adding newid() default constraint for ' + @TableName + '.' + @ColumnName
		EXEC GTSAddUpgradeLog @RunMode, @Log, 1
		SET @SQL = 'ALTER TABLE ' + @TableName + ' ADD CONSTRAINT ' + @ConstraintName + ' DEFAULT newid() FOR ' + @ColumnName
		EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
		END

	IF @ToNotNull = 1 AND (EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME = @ColumnName AND IS_NULLABLE = 'YES')) BEGIN
		SET @Log = 'Adding new GUIDs for existing rows that do not have one for ' + @TableName + '.' + @ColumnName
		EXEC GTSAddUpgradeLog @RunMode, @Log, 1
		SET @SQL = 'UPDATE ' + @TableName + ' SET ' + @ColumnName + ' = newid() WHERE ' + @ColumnName + ' IS NULL'
		EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

		SET @Log = 'Updating ' + @TableName + '.' + @ColumnName + ' to be non-nullable'
		EXEC GTSAddUpgradeLog @RunMode, @Log, 1
		SET @SQL = 'ALTER TABLE ' + @TableName + ' ALTER COLUMN ' + @ColumnName + ' uniqueidentifier NOT NULL'
		EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
		END
    END
GO



/*
 *        The following procs are used during the Post Upgrade.
 *
 */
--
--                      PROCEDURE GTSAddUpgradeDefaultValue
--
PRINT '    ' + 'Creating GTSAddUpgradeDefaultValues...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSAddUpgradeDefaultValue') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSAddUpgradeDefaultValue
GO
CREATE PROCEDURE dbo.GTSAddUpgradeDefaultValue( @TableName     sysname,
                                            @ColumnName    sysname,
                                            @Type          sysname,
                                            @DefaultValue  varchar(100) ) AS BEGIN
    --
    -- Add one default value to UpgradeDefaultValues table
    --

    SET nocount ON  -- don't display "x row(s) affected"

    DECLARE
        @SQL    varchar(1000),
        @Error  int,
        @Log    varchar(1000)

    IF NOT EXISTS (SELECT DefaultValue FROM UpgradeDefaultValues
                   WHERE (IsNULL(TableName , 'NULL') = IsNULL(@TableName,  'NULL')) AND
                         (IsNULL(ColumnName, 'NULL') = IsNULL(@ColumnName, 'NULL')) AND
                         (IsNULL(ColumnType, 'NULL') = IsNULL(@Type,       'NULL')) ) BEGIN

        SET @Log = 'Adding a default value of "' + @DefaultValue + '" for  ' +
                   '(table)'  + IsNULL(@TableName, '*') + '.' +
                   '(column)' + IsNULL(@ColumnName, '*') + '.' +
                   '(type)'   + IsNull(@Type, '*')
        EXEC GTSAddUpgradeLog  1 /* just add it */, @Log, 1

        SELECT @SQL = 'INSERT INTO UpgradeDefaultValues VALUES(' +
                          CASE WHEN @TableName  IS NULL THEN 'NULL, ' ELSE '''' + @TableName  + ''', ' END +
                          CASE WHEN @ColumnName IS NULL THEN 'NULL, ' ELSE '''' + @ColumnName + ''', ' END +
                          CASE WHEN @Type       IS NULL THEN 'NULL, ' ELSE '''' + @Type       + ''', ' END +
                          + @DefaultValue + ') '

        EXEC GTSUpgradeExecSQL  1 /* Execute the script */, @Error OUTPUT, @SQL
        END
    END
GO



--
--                      PROCEDURE GTSAddUpgradeDefaultValues
--
PRINT '    ' + 'Creating GTSAddUpgradeDefaultValues...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSAddUpgradeDefaultValues') ANd (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSAddUpgradeDefaultValues
GO
CREATE PROCEDURE dbo.GTSAddUpgradeDefaultValues AS BEGIN
    /*
     * The following values are the default values given by GTS.
     * If a different values are desired, either modify the existing
     * default values or add new ones
     */
    DECLARE
        @Log  varchar(1000)

    SET @Log = 'Checking and adding the default values to use for "NULL" to "NOT NULL" change'
    EXEC GTSAddUpgradeLog  1 /* just add it */, @Log, 0

    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'int',       '0'
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'integer',   '0'
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'bit',       '0'
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'boolean',   '0'
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'datetime',  '''GetDate()'''
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'money',     '0'
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'float',     '0.00'
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'char',      ''' '''
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'varchar',   ''' '''
    EXEC GTSAddUpgradeDefaultValue  NULL,  NULL,  'text',      ''' '''

    EXEC GTSAddUpgradeDefaultValue NULL, 'RecordVersion', NULL, '1'
    EXEC GTSAddUpgradeDefaultValue NULL, 'LastUpdate',    NULL, '''GetDate()'''
    EXEC GTSAddUpgradeDefaultValue NULL, 'LastUpdatedBy', NULL, '''GTSUpgrade'''
    END
GO


--
--                      PROCEDURE GTSPostUpgradeChangePK
--
PRINT '    ' + 'Creating GTSPostUpgradeChangePK...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSPostUpgradeChangePK') ANd (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSPostUpgradeChangePK
GO
CREATE PROCEDURE dbo.GTSPostUpgradeChangePK( @RunMode      int,
                                         @Error        int OUTPUT,
                                         @TableName    sysname,
                                         @NewPKColumn  varchar(256),
                                         @NewPKName    sysname) AS BEGIN
    --
    -- Change the PK if the existing PK column definition is different than what is
    -- passed to this stored procedure.
    --     processing:
    --         1. Get the existing PK constraint name
    --         2. If PK exists for this table, get the column definitions for PK
    --         3. If PK exists and column definitions are different, drop existing PK
    --         4. IF PK does not exist or column definitions are differet,
    --         4.a  Set unique values for the new PK column
    --         4.b  Change the PK column to NOT NULL
    --         4.c  Apply new PK
    --         4.d  Update GatewayCounters for the PK column
    --
    --  Example of a call:  EXEC GTSPostUpgradeChangePK  @RunMode, @Error OUTPUT, 'tablename', 'gateway pk column', 'pk name'
    --
    --    EXEC GTSPostUpgradeChangePK  @RunMode, @Error OUTPUT, 'AccessCodes', 'AccessCodeID', 'PKAccessCodesAccessCodeID'
    --
    SET nocount ON

    DECLARE
        @OldPKName     sysname,
        @OldPKColumns  varchar(256),
        @SQL           varchar(1000),
        @Log           varchar(1000)

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    /*
     *  Only works with one PK column....
     */

    SELECT @OldPKName = name FROM SysObjects WHERE (xtype = 'PK') AND (parent_obj = object_id(@TableName))
    IF (@OldPKName IS NOT NULL) EXEC GTSGetIndexColumns  @TableName, @OldPKName, @OldPKColumns OUTPUT

    IF (@OldPKName IS NULL) OR (@OLDPKColumns <> @NewPKColumn) BEGIN
        SET @Log = 'Changing PK Column...'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
        END

    IF (@OldPKName IS NOT NULL) AND (@OldPKColumns <> @NewPKColumn) BEGIN
        SET @Log = 'Dropping existing primary key contraint ' + @OldPKName + ' ON (' + @OldPKColumns + ')'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2

        SET @SQL = 'ALTER TABLE ' + @TableName + ' DROP CONSTRAINT ' + @OldPKName
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF (@OldPKName IS NULL) OR (@OldPKColumns <> @NewPKColumn) BEGIN
        SET @Log = 'Adding an identity column IdentityID to set unique values for each row'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @SQL = 'ALTER TABLE ' + @TableName + ' ADD IdentityID INT NOT NULL IDENTITY(1,1) '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

        SET @Log = 'Populating unique values for ' + @NewPKColumn + ' from IdentityID'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @SQL = 'UPDATE ' + @TableName + ' SET ' + @NewPkColumn + ' = IdentityID WHERE ' +
                   '(' + @NewPKColumn + ' IS NULL) OR (' + @NewPKColumn + ' = 0)'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

        SET @Log = 'Dropping the IdentityID column'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @SQL = 'ALTER TABLE ' + @TableName + ' DROP COLUMN IdentityID'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

        SET @Log = 'Changing the PK column to NOT NULL'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @SQL = 'ALTER TABLE ' + @TableName + ' ALTER COLUMN ' + @NewPKColumn + ' int NOT NULL'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

        /*
        -- PK will be created by GTSUpgradeAddPK call in the table definition section
        PRINT '    ' + '    ' + 'Add a primary key contraint ' + @NewPKName + ' ON (' + @NewPKColumn + ') '
        SET @SQL = 'ALTER TABLE ' + @TableName + ' ADD CONSTRAINT ' + @NewPKName + ' ' +
                   'PRIMARY KEY CLUSTERED (' + @NewPKColumn + ')'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        */

        IF NOT EXISTS (SELECT name FROM GatewayCounters WHERE name = @NewPKColumn) BEGIN
            SET @Log = 'Adding a GatewayCounters name ' + @NewPKColumn + ' with value = 0'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @SQL = 'INSERT INTO GatewayCounters VALUES(''' + @NewPKColumn + ''', 0)'
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END

        SET @Log = 'Updating GatewayCounters name ' + @NewPKColumn
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @SQL = 'UPDATE GatewayCounters SET CountValue = (' +
                   'SELECT IsNULL(max(' + @NewPKColumn + '), 0) FROM ' + @TableName + ') ' +
                   'WHERE (name = ''' + @NewPKColumn + ''') '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    END
GO



--
--                      PROCEDURE GTSGetDefaultValue
--
PRINT '    ' + 'Creating GTSGetDefaultValue...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGetDefaultValue') ANd (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSGetDefaultValue
GO
CREATE PROCEDURE dbo.GTSGetDefaultValue( @TableName  sysname,
                                     @Column     sysname,
                                     @Type       sysname,
                                     @Result     varchar(100) OUTPUT ) AS BEGIN
    SET nocount ON

    --
    -- find the first occurance of the match... the match is table.column or *.column
    -- which ever is a first....NULL IS then value
    --
    SELECT TOP 1 @Result = DefaultValue FROM UpgradeDefaultValues
        WHERE (TableName = @TableName) OR (ColumnName = @Column) OR (ColumnType = @Type)
        ORDER BY TableName DESC, ColumnName DESC, ColumnType DESC  -- NULL is < '0'
    /*
    -- if the default is not found for table.column, set a GTS upgrade default value for a given type
    IF @Result IS NULL BEGIN
        SET @Result = CASE
            WHEN (@Type LIKE '%int')    THEN '0'
            WHEN (@Type LIKE '%char')   THEN ' '
            WHEN (@Type = 'bit')        THEN '0'
            WHEN (@Type = 'boolean')    THEN '0'
            WHEN (@Type LIKE '%money')  THEN '0.00'
            WHEN (@Type LIKE 'float')   THEN '0.00'
            WHEN (@Type = 'DateTime')   THEN 'GetDate()'

            ELSE ' '
            END
        END
    */
    END
GO



--
--                      PROCEDURE GTSUpgradeReCreateDroppedIndexes
--
PRINT '    ' + 'Creating GTSUpgradeRecreateDroppedIndexes...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeReCreateDroppedIndexes') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeReCreateDroppedIndexes
GO
CREATE PROCEDURE dbo.GTSUpgradeReCreateDroppedIndexes( @RunMode        int,
                                                   @Error          int OUTPUT,
                                                   @TableName      sysname,
                                                   @RecreateIndex  bit) AS BEGIN
    --
    --  This proc recreates the dropped indexes due to column changes
    --

    SET nocount ON  -- don't display (x rows affected) message

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    IF (@RecreateIndex = 0) RETURN

    DECLARE DroppedIndexesCursor CURSOR FOR
        SELECT IndexName, IndexColumns, IsPrimaryKey, IsClustered, IsConstraint, IsUnique, IncludeColumns
		FROM TableIndexDefs
        WHERE (TableName = @TableName) AND (Dropped = 1)
        ORDER BY IsClustered DESC   -- recreate the clustered key first

    DECLARE
        @SQL           varchar(1000),
        @IndexName     sysname,
        @IndexColumns  nvarchar(max),
		@IncludedColumns nvarchar(max),
        @IsPrimaryKey  bit,
        @IsClustered   bit,
        @IsConstraint  bit,
        @IsUnique      bit,
        @IndexExists   bit,
        @TableHasPK    bit,
        @Log           varchar(1000)

    OPEN DroppedIndexesCursor
    FETCH FROM DroppedIndexesCursor INTO
        @IndexName, @IndexColumns, @IsPrimaryKey, @IsClustered, @IsConstraint, @IsUnique, @IncludedColumns

    IF ((@@FETCH_STATUS = 0) AND (@RecreateIndex = 1)) BEGIN
        SET @Log = 'Recreating dropped indexes'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
        END

    WHILE( @@FETCH_STATUS = 0 ) BEGIN
        EXEC @IndexExists = GTSIndexExists  @TableName, @IndexName
        EXEC @TableHasPK  = GTSTableHasPK   @TableName
        IF ((@IsPrimaryKey = 1) AND (@TableHasPK  = 0)) OR
           ((@IsPrimaryKey = 0) AND (@IndexExists = 0)) BEGIN
            IF (@IsConstraint = 1) BEGIN
               -- could be a Primary Key
               SELECT @SQL = 'ALTER TABLE ' + @TableName + ' ADD CONSTRAINT [' + @IndexName + '] ' +
                             CASE WHEN (@IsPrimaryKey = 1) THEN 'PRIMARY KEY'
                                  WHEN (@IsUnique     = 1) THEN 'UNIQUE' ELSE ' ' END + ' ' +
                             CASE WHEN (@IsClustered  = 1) THEN 'CLUSTERED' ELSE 'NONCLUSTERED' END + ' ' +
                             '(' + @IndexColumns + ')'
               END
            ELSE BEGIN
                -- it is an index
                SELECT @SQL = 'CREATE' + CASE WHEN (@IsUnique    = 1) THEN ' UNIQUE'    ELSE ' ' END +
                                         CASE WHEN (@IsClustered = 1) THEN ' CLUSTERED' ELSE ' ' END + ' ' +
                              'INDEX [' + @IndexName + '] ON dbo.' + @TableName + '(' + @IndexColumns + ')'
                IF (@IncludedColumns IS NOT NULL) AND (@IncludedColumns <>  '')
                    SET @SQL = @SQL + ' INCLUDE (' + @IncludedColumns + ')';
				END

            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END

        /*
         *  Now, set the Dropped to FALSE for the re-created index
         */
        SET @SQL = 'UPDATE TableIndexDefs SET Recreated = 1 WHERE ' +
                   '(TableName = ''' + @TableName + ''') AND ' +
                   '(IndexName = ''' + @IndexName + ''') '
        EXEC GTSUpgradeExecSQL  1 /* just run the SQL */, @Error OUTPUT, @SQL

        FETCH FROM DroppedIndexesCursor INTO
            @IndexName, @IndexColumns, @IsPrimaryKey, @IsClustered, @IsConstraint, @IsUnique, @IncludedColumns
        END

    CLOSE DroppedIndexesCursor
    DEALLOCATE DroppedIndexesCursor
    END
GO



--
--         PROCEDRUE  GTSPostUpgradeChangeToNotNULL
--
PRINT '    ' + 'Creating GTSPostUpgradeChangeToNotNULL...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSPostUpgradeChangeToNotNULL') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSPostUpgradeChangeToNotNULL
GO
CREATE PROCEDURE dbo.GTSPostUpgradeChangeToNotNULL( @RunMode         int,
                                                @Error           int OUTPUT,
                                                @DropDependency  bit,
                                                @TableName       sysname,
                                                @Column          sysname,
                                                @Type            sysname,
                                                @Length          integer = -1) AS BEGIN
    --
    --  This stored procedure sets the default value for a column where the column has been
    --  changed from NULL to NOT NULL.  Then, it alter the column to be NOT NULL column.
    --
    --  The default values are stored in the UpgradeDefaultValues table.  GetDefaultValue() function
    --  gets the correct default value for a give table.column.
    --
    -- when length is -1, don't check for length...datetime, float, int, etc
    --
    SET nocount ON

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...
    IF ((@RunMode / 10) <> 2) RETURN       -- if not in post upgrade mode, exit

    DECLARE
        @SQL           varchar(1000),
        @DefaultValue  varchar(100),
        @CharLenStr    varchar(10),
        @Log           varchar(1000)

    IF EXISTS(SELECT id FROM SysColumns WHERE (name = @Column) AND (id = object_id(@TableName))) AND
       NOT EXISTS(SELECT b.id FROM SysColumns b, SysTypes c
                  WHERE (b.name = @Column) AND (b.id = object_id(@TableName)) AND (b.xusertype = c.xusertype)
                  AND   (c.name = @Type) AND ((b.length = @Length) OR (@length = -1)) AND (b.IsNullable = 0)) BEGIN

        SET @Log = 'Changing the nullable column "' + @Column + '" to NOT NULL'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

        EXEC GTSGetDefaultValue  @TableName, @Column, @Type, @DefaultValue OUTPUT

        IF @DefaultValue IS NULL BEGIN
            SET @Error = -3
            SET @Log = 'Default value not found for "' + @TableName + '.' + @Column + '".' +
                       'Please add default value to UpgradeDefaultValues table.'  + CHAR(13) +
                       'Post upgrade changes to ' + @TableName + ' ' + @Column + ' ' + @Type + ' NOT NULL has not been applied.'
            EXEC GTSUpgradeError  @RunMode, @Error OUTPUT, @Log
            RETURN
            END
        ELSE BEGIN
            SET @Log = 'Set the default value of "' + @DefaultValue + '" to column "' + @Column + '"'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SELECT @SQL = 'UPDATE ' + @TableName + ' SET ' + @Column + ' = ' +
                              CASE WHEN @Type LIKE '%CHAR' THEN '''' + @DefaultValue + '''' ELSE @DefaultValue END + ' ' +
                              'WHERE '  + @Column + ' IS NULL'
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL, 0 /* don't give a blank line */

            EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency, @TableName, @Column, @Type, @Length,  'NOT NULL'
            END
        END
    END
GO



