--         PROCEDRUE  GTSPostUpgradeAuditColumns
--
PRINT '    ' + 'Creating GTSPostUpgradeAuditColumns...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSPostUpgradeAuditColumns') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSPostUpgradeAuditColumns
GO
CREATE PROCEDURE dbo.GTSPostUpgradeAuditColumns( @RunMode         int,
                                             @Error           int OUTPUT,
                                             @DropDependency  bit,
                                             @TableName       sysname ) AS BEGIN
    --
    --  This stored procedure changes any of the audit colums to NOT NULL.  Before changing the
    --  columns to NOT NULL, it will populate default values for each audit columns where its
    --  value is NULL
    --
    --     RecordVersion   -  1
    --     LastUpdate      -  system date--getdate()
    --     LastUpdatedBy   =  'GTSUpgrade'
    --
    SET nocount ON

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    DECLARE
        @SQL varchar(1000)

    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency, @TableName, 'RecordVersion', 'int'
    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency, @TableName, 'LastUpdate',    'DateTime'
    END
GO

/*  Start miscellaneous utility procedures */
PRINT '    ' + 'Creating GTS_SP_CopyDatabase...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_CopyDatabase') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_CopyDatabase
GO

CREATE PROCEDURE dbo.GTS_SP_CopyDatabase(@TempBackupPath nvarchar(255),
                                               @CopyDatabaseName sysname,
                                               @DataFilePath nvarchar(255),
                                               @LogFilePath nvarchar(255),
                                               @Force bit = 0,
                                               @PostRestoreCmd nvarchar(max),
                                               @Help bit = 0) AS BEGIN
    /***
    ================================================================================
    =help

    Name        : GTS_SP_CopyDatabase
    Description : Restores a copy of the Galaxy database for reporting or other purposes.

    Parameters  :

    Name                  | I/O   | Description
    --------------------------------------------------------------------------------
    @TempBackupPath         I       A path where the temporary backup file should be placed.
    @CopyDatabaseName       I       The name of the copy database that will be restored.
    @DataFilePath           I       The path at which to place the new data files.
    @LogFilePath            I       The path at which to place log files.
    @Force                  I       If set to 1, and the copy database already exists, it will
                                    disconnect all existing connections before performing the restore.
    @PostRestoreCmd         I       If specified, will execute a stored procedure after the restore process is
                                    complete. This must be a stored procedure with no required parameters. This
                                    is useful for granting more rights or creating custom indices on the reporting
                                    database. This should be specified as "<schema>.<procedure>".

    =endhelp

    Return Value: Return code
         Success : 0
         Failure : Error number and Description
    ================================================================================
    ***/
    SET NOCOUNT ON;

    DECLARE @DBName sysname;
    DECLARE @BackupFileName sysname;
    DECLARE @SQL nvarchar(max);
    DECLARE @Version numeric(18,10),
            @EngineEdition nvarchar(128),
            @UseCompression bit,
            @MoveCommand nvarchar(max);

    DECLARE @Files TABLE
    (
      LogicalName nvarchar(128) PRIMARY KEY,
      PhysicalName nvarchar(128),
      FileType char(1),
      FileGroupName nvarchar(128),
      Size numeric(20),
      MaxSize numeric(20),
      FileID bigint,
      CreateLSN numeric(25),
      DropLSN numeric(25),
      UniqueID uniqueidentifier,
      ReadOnlyLSN numeric(25),
      ReadWriteLSN numeric(25),
      BackupSizeInBytes bigint,
      SourceBlockSize int,
      FileGroupID int,
      LogGroupGUID uniqueidentifier,
      DifferentialBaseLSN numeric(25),
      DifferentialBaseGUID uniqueidentifier,
      IsReadOnly bit,
      IsPresent bit,
      TDEThumbprint varbinary(32) DEFAULT NULL
    );

    DECLARE @MessageText nvarchar(max);

    -- Props to Adam Machanic and sp_whoisactive for this technique
    -- to get help text from within a stored procedure.
    -- http://sqlblog.com/blogs/adam_machanic/archive/2012/03/22/released-who-is-active-v11-11.aspx
    IF @Help = 1
    BEGIN

      SELECT @SQL = dest.text
        FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) dest
        WHERE r.session_id = @@SPID;
      --PRINT @SQL;
      -- Cut up the SQL text and get the help section
      SET @MessageText = SUBSTRING(@SQL,
                            CHARINDEX('=help',@SQL),
                            CHARINDEX('=endhelp',@SQL)-CHARINDEX('=help',@SQL)+8
                          );

      PRINT @MessageText;
      RETURN;

    END;

    BEGIN TRY

      SET @Version = CAST(LEFT(CAST(SERVERPROPERTY('ProductVersion') AS nvarchar(max)),CHARINDEX('.',CAST(SERVERPROPERTY('ProductVersion') AS nvarchar(max))) - 1) + '.' + REPLACE(RIGHT(CAST(SERVERPROPERTY('ProductVersion') AS nvarchar(max)), LEN(CAST(SERVERPROPERTY('ProductVersion') AS nvarchar(max))) - CHARINDEX('.',CAST(SERVERPROPERTY('ProductVersion') AS nvarchar(max)))),'.','') AS numeric(18,10));
      SET @EngineEdition = cast(SERVERPROPERTY('Edition') AS nvarchar(128));

      -- If we are using SQL 2008 Enterprise or SQL 2008 R2 Std + we want to use native backup compression
      IF (@Version >= 10 AND @Version < 10.5 AND @EngineEdition LIKE 'Enterprise%')
         OR (@Version >= 10.5 AND (@EngineEdition LIKE 'Standard%' OR @EngineEdition LIKE 'Enterprise%' OR @EngineEdition LIKE 'Developer%'))
        SET @UseCompression = 1;
      ELSE
        SET @UseCompression = 0;

      SET @DBName = DB_NAME();

      IF RIGHT(@TempBackupPath,1) != '\'
        SET @TempBackupPath = @TempBackupPath + '\';

      IF RIGHT(@DataFilePath,1) != '\'
        SET @DataFilePath = @DataFilePath + '\';

      IF RIGHT(@LogFilePath,1) != '\'
        SET @LogFilePath = @LogFilePath + '\';

      SET @BackupFileName = @TempBackupPath + @DBName + '_Copy.bak';

      -- Take an adhoc, copy_only backup of the database
      SET @SQL = 'BACKUP DATABASE ' + QUOTENAME(@DBName) + ' TO DISK = ' + QUOTENAME(@BackupFileName,'''') +
                 ' WITH STATS=5,INIT,FORMAT,COPY_ONLY';
      IF @UseCompression = 1
        SET @SQL = @SQL + ',COMPRESSION';

      RAISERROR('Starting backup of database %s.',10,1,@DBName) WITH NOWAIT;
      RAISERROR('Command:%s',10,1,@SQL) WITH NOWAIT;

      EXEC sp_executesql @SQL;

      SET @SQL = 'RESTORE FILELISTONLY FROM DISK = ' + QUOTENAME(@BackupFileName,'''');
      RAISERROR('Constructing file list for restore.',10,1) WITH NOWAIT;
      RAISERROR('Command:%s',10,1,@SQL) WITH NOWAIT;

      INSERT INTO @Files
      EXEC sp_executesql @SQL;

      SET @MoveCommand = (
        SELECT CASE f.FileID
                WHEN 1 THEN ''
                ELSE ','
               END +
                'MOVE ' + QUOTENAME(f.LogicalName,'''') + ' TO ' +
                QUOTENAME(CASE f.FileType
                           WHEN 'D' THEN @DataFilePath
                           WHEN 'L' THEN @LogFilePath
                          END +
                          @CopyDatabaseName +
                          '_' +
                          convert(nvarchar,f.FileID) +
                          CASE f.FileType
                           WHEN 'D' THEN CASE f.FileID
                                          WHEN 1 THEN '.mdf'
                                          ELSE '.ndf'
                                         END
                           WHEN 'L' THEN '.ldf'
                          END,''''
                         )
          FROM @Files f
        ORDER BY f.FileID ASC
        FOR XML PATH('')
      );

      -- Restore the database
      SET @SQL = 'RESTORE DATABASE '
                  + QUOTENAME(@CopyDatabaseName)
                  + ' FROM DISK = ' + QUOTENAME(@BackupFileName,'''')
                  + ' WITH STATS=5,'
                  + @MoveCommand;
      IF EXISTS (
        SELECT 1
          FROM sys.databases d
         WHERE d.name = @CopyDatabaseName
      )
      BEGIN
        SET @SQL = @SQL + ',REPLACE';
        IF @Force = 1
          SET @SQL = 'ALTER DATABASE ' + QUOTENAME(@CopyDatabaseName) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;' + @SQL;
      END;
      RAISERROR('Starting restore of database %s.',10,1,@CopyDatabaseName) WITH NOWAIT;
      RAISERROR('Command:%s',10,1,@SQL) WITH NOWAIT;

      EXEC sp_executesql @SQL;

      IF @PostRestoreCmd IS NOT NULL
      BEGIN
        RAISERROR('Executing post restore command.',10,1,@CopyDatabaseName) WITH NOWAIT;
        RAISERROR('Command:%s',10,1,@PostRestoreCmd) WITH NOWAIT;
        EXEC @PostRestoreCmd;
      END;

    END TRY
    BEGIN CATCH

      DECLARE @ERROR_MESSAGE NVARCHAR(2048);
      DECLARE @ERROR_SEVERITY TINYINT;
      DECLARE @ERROR_NUMBER INT;

      SET @ERROR_MESSAGE = ERROR_MESSAGE();
      SET @ERROR_NUMBER = ERROR_NUMBER();
      SET @ERROR_SEVERITY = ERROR_SEVERITY();

      IF XACT_STATE() <> 0
        ROLLBACK;

      RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
      RAISERROR('Due to a limitation in SQL error handling, helpful error messages may not be shown when a backup or restore command fails.',10,1) WITH NOWAIT;
      RAISERROR('To determine the actual error message, such as an inability to aquire exclusive database access, run the last printed command before the error occurred.',10,1) WITH NOWAIT;

    END CATCH;
END
GO

PRINT '    ' + 'Creating GTS_SP_PurgeGxRecordLog...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTS_SP_PurgeGxRecordLog') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_PurgeGxRecordLog
GO

CREATE PROCEDURE [dbo].[GTS_SP_PurgeGxRecordLog](@RetentionPeriodInDays smallint = 90,
                                                 @Help bit = 0,
                                                 @MaxBatchRecordSize int = 1000000,
                                                 @TableColumnExclusions varchar(max) = '') AS BEGIN
    /***
    ================================================================================
    =help

    Name        : GTS_SP_PurgeGxRecordLog
    Description : Purges records older than the specified number of days from the GXRecordLog table.

    Parameters  :

      @RetentionPeriodInDays - Data older than this many days will be purged from the table.
      @MaxBatchRecordSize    - The maximum number of records to delete in a single delete statement.  This
                               used to be hard coded to 1,000,000 in the stored procedure
      @TableColumnExclusions - A list of tables and columns to exclude in the purge.  Values in this list
                               will remain even if they are older than the @RetentionPeriodInDays.  The format is
                               'TableID.FieldName, TableID.FieldName'.  TableID is the table's integer value
                               found in the Galaxy Database Dictionary in the 'Table IDs' section. FieldName is
                               the column name of that table to exclude from the purge.  An example would be
                               '113.IdentificationNo, 108.*' which would prevent GxRecordLogs for the CustContacts
                               table (113), IdentificationNo column and ALL (*) rows from the Orders table (108)
                               from being purged.

    =endhelp
    ================================================================================
    ***/
    SET NOCOUNT ON;

    DECLARE @PurgeDate datetime, -- The oldest date of records to retain
            @IterationPurgeRowCount bigint, -- The number of rows deleted this iteration
            @TotalPurgeRowCount bigint, -- The total number of rows deleted so far
            @ToBePurgedRowCount bigint, -- The number of rows qualified to be purged.
            @RemainingRowCount bigint, -- The number of rows remaining to be purged.
            @MaxGXRecordLogID bigint; -- The maximum PK value for rows to be purged.

    DECLARE @ERROR_MESSAGE NVARCHAR(2048);
    DECLARE @ERROR_SEVERITY TINYINT;
    DECLARE @ERROR_NUMBER INT;

	DECLARE @Exclusions TABLE
	(
      TableID int,
      ColumnName varchar(255)
	);

    SET @IterationPurgeRowCount = 0;
    SET @TotalPurgeRowCount = 0;
    SET @ToBePurgedRowCount = 0;
    SET @RemainingRowCount = 0;

    DECLARE @sql nvarchar(max),
            @MessageText nvarchar(max);

    -- Props to Adam Machanic and sp_whoisactive for this technique
    -- to get help text from within a stored procedure.
    -- http://sqlblog.com/blogs/adam_machanic/archive/2012/03/22/released-who-is-active-v11-11.aspx
    IF @Help = 1
    BEGIN

      SELECT @SQL = dest.text
        FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) dest
        WHERE r.session_id = @@SPID;
      --PRINT @SQL;
      -- Cut up the SQL text and get the help section
      SET @MessageText = SUBSTRING(@SQL,
                            CHARINDEX('=help',@SQL),
                            CHARINDEX('=endhelp',@SQL)-CHARINDEX('=help',@SQL)+8
                          );

      PRINT @MessageText;
      RETURN;

    END;

    BEGIN TRY

      SET @PurgeDate = DATEADD(day,DATEDIFF(day,0,CURRENT_TIMESTAMP) - @RetentionPeriodInDays,0);

      INSERT INTO @Exclusions
      SELECT
        SUBSTRING(
          ValueElement,
          1,
          CHARINDEX('.', ValueElement, 0) - 1) as TableID,

        SUBSTRING(
          ValueElement,
          CHARINDEX('.', ValueElement, 0) + 1,
          LEN(ValueElement) - CHARINDEX('.', ValueElement, 0)) as ColumnName

      FROM GTSSplitStringByDelimeter(@TableColumnExclusions, ',')
      WHERE @TableColumnExclusions <> ''

      SELECT @ToBePurgedRowCount = COUNT_BIG(1),
             @MaxGXRecordLogID = MAX(l.GxRecordLogID)
      FROM dbo.GxRecordLog l
      LEFT JOIN @Exclusions ex ON ex.TableID = l.TableID and (ex.ColumnName in (l.FieldName, '*'))
      WHERE l.ModifyDate < @PurgeDate
      AND IsNull(ex.TableID, 0) = 0;

      RAISERROR('Beginning purge operations.',10,1) WITH NOWAIT;
      IF @ToBePurgedRowCount > 0
        RAISERROR('There are %I64d rows qualified for purging.',10,1,@ToBePurgedRowCount) WITH NOWAIT;
      ELSE
      BEGIN
        RAISERROR('There are no rows qualified for purging.',10,1) WITH NOWAIT;
        RETURN;
      END;

      SET @RemainingRowCount = @ToBePurgedRowCount;

      -- Disable indexes
      SET @SQL = (
        SELECT
            'ALTER INDEX '
              + quotename(sidx.name)
              + ' ON '
              + quotename(ssch.name)
              + '.' + quotename(sobj.name)
              + ' '
              + 'DISABLE;' + char(10)
          FROM
            sys.schemas ssch join sys.objects sobj
              on ssch.schema_id = sobj.schema_id
                 and ssch.name = 'dbo'
                 and sobj.name = 'GXRecordLog'
            join sys.indexes sidx
              on sobj.object_id = sidx.object_id
                 and sidx.is_primary_key = 0 -- exclude primary keys
                 and sidx.is_unique = 0 -- exclude unique indexes
                 and sidx.index_id > 1 -- exclude clustered index and heap
                 and sidx.is_disabled = 0
        FOR XML path('')
      );

      EXEC sp_executesql @sql;

      -- We use a nested TRY block here to be sure indexes are re-enabled afterwards even in the event of an error
      BEGIN TRY
        WHILE 1=1
        BEGIN
          DELETE TOP(@MaxBatchRecordSize) gx
            FROM dbo.GxRecordLog gx
            LEFT JOIN @Exclusions ex ON ex.TableID = gx.TableID and (ex.ColumnName in (gx.FieldName, '*'))
            WHERE gx.GxRecordLogID <= @MaxGXRecordLogID
            AND IsNull(ex.TableID, 0) = 0

          SET @IterationPurgeRowCount = @@ROWCOUNT;
          SET @TotalPurgeRowCount = @TotalPurgeRowCount + @IterationPurgeRowCount;
          SET @RemainingRowCount = @RemainingRowCount - @IterationPurgeRowCount;

          RAISERROR('%I64d rows purged in this iteration, %I64d rows deleted total. %I64d rows remaining.'
                    ,10
                    ,1
                    ,@IterationPurgeRowCount
                    ,@TotalPurgeRowCount
                    ,@RemainingRowCount) WITH NOWAIT;

          IF @IterationPurgeRowCount = 0 BREAK;

        END;
      END TRY
      BEGIN CATCH
        SET @ERROR_MESSAGE = CONVERT(varchar,ERROR_LINE()) + ': ' + ERROR_MESSAGE();
        SET @ERROR_NUMBER = ERROR_NUMBER();
        SET @ERROR_SEVERITY = ERROR_SEVERITY();
      END CATCH;

      -- Re-enable indexes
      SET @SQL = (
        SELECT
            'ALTER INDEX '
              + quotename(sidx.name)
              + ' ON '
              + quotename(ssch.name)
              + '.' + quotename(sobj.name)
              + ' '
              + 'REBUILD;' + char(10)
          FROM
            sys.schemas ssch join sys.objects sobj
              on ssch.schema_id = sobj.schema_id
                 and ssch.name = 'dbo'
                 and sobj.name = 'GXRecordLog'
            join sys.indexes sidx
              on sobj.object_id = sidx.object_id
                 and sidx.is_primary_key = 0 -- exclude primary keys
                 and sidx.is_unique = 0 -- exclude unique indexes
                 and sidx.index_id > 1 -- exclude clustered index and heap
                 and sidx.is_disabled = 1
        FOR XML path('')
      );

      EXEC sp_executesql @sql;

      -- If an error occurred during purging, re-raise it.
      IF @ERROR_MESSAGE IS NOT NULL
        RAISERROR(@ERROR_MESSAGE,16,1);

    END TRY
    BEGIN CATCH

      SET @ERROR_MESSAGE = CONVERT(varchar,ERROR_LINE()) + ': ' + ERROR_MESSAGE();
      SET @ERROR_NUMBER = ERROR_NUMBER();
      SET @ERROR_SEVERITY = ERROR_SEVERITY();

      IF XACT_STATE() <> 0
        ROLLBACK;

      RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);

    END CATCH;
END
GO


