/**********************************************************
    dbo.GTS_SP_GeteGalaxyTransactionID: Returns the next ID
    from dbo.eGalaxyTransactionIDs.  Requires that a row be
    inserted with LastTranNo zero before calling for
    performance reasons.
 *********************************************************/
CREATE PROCEDURE dbo.GTS_SP_GeteGalaxyTransactionID
    @NodeNo integer,
    @LastTranNo integer OUTPUT AS
BEGIN
    SET XACT_ABORT, NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE dbo.eGalaxyTransactionIDs WITH (UPDLOCK, SERIALIZABLE)
            SET @LastTranNo = LastTranNo = LastTranNo + 1,
                RecordVersion = RecordVersion + 1,
                LastUpdate = GetDate(),
                LastUpdatedBy = 'NxtEGXTrns'
            WHERE NodeNo = @NodeNo;

        IF @@ROWCOUNT = 0 BEGIN
            DECLARE
                @PK INT,
                @PKColumnName VARCHAR(30) = 'eGalaxyTransactionID',
                @GCRange INT = 1;

            SET @LastTranNo = 1;

            EXECUTE @PK = dbo.GetNextGatewayCounter @PKColumnName, @GCRange;

            INSERT dbo.eGalaxyTransactionIDs
                (eGalaxyTransactionID, NodeNo, LastTranNo, RecordVersion, LastUpdate, LastUpdatedBy)
                VALUES
                (@PK, @NodeNo, @LastTranNo, 1, GetDate(), 'NxtEGXTrns');
            END;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        DECLARE @ERROR_MESSAGE NVARCHAR(2048);
        DECLARE @ERROR_SEVERITY TINYINT;
        DECLARE @ERROR_NUMBER INT;

        SET @ERROR_MESSAGE = ERROR_MESSAGE();
        SET @ERROR_NUMBER = ERROR_NUMBER();
        SET @ERROR_SEVERITY = ERROR_SEVERITY();

        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;

        RAISERROR(@ERROR_MESSAGE, @ERROR_SEVERITY, 1);
        END CATCH;
END
GO

