IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GetNexteGalaxyTransactionID') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GetNexteGalaxyTransactionID;
GO
SET QUOTED_IDENTIFIER ON
GO

/**********************************************************
	dbo.GetNexteGalaxyTransactionID : Returns the next ID
	from dbo.eGalaxyTransactionIDs or a range of IDs
 *********************************************************/
CREATE PROCEDURE dbo.GetNexteGalaxyTransactionID
(
    @NodeNo int,
    @LastUpdatedBy  nvarchar(20),
    @Range int = 1,
    @StartValue int = null OUTPUT,
    @EndValue int = null OUTPUT
) AS
BEGIN

    SET NOCOUNT ON

    BEGIN TRY
        IF @Range < 1 RAISERROR('@Range parameter value must be greater than zero.', 16, 1)
        BEGIN TRANSACTION

        -- Initial value
        SELECT @StartValue = LastTranNo + 1 FROM dbo.eGalaxyTransactionIDs WITH (UPDLOCK) WHERE NodeNo = @NodeNo

        UPDATE dbo.eGalaxyTransactionIDs SET LastTranNo = LastTranNo + @Range WHERE NodeNo = @NodeNo
        SELECT @EndValue = LastTranNo FROM dbo.eGalaxyTransactionIDs WHERE NodeNo = @NodeNo

        IF @StartValue IS NULL BEGIN
            DECLARE
                 @PK int
                ,@PKColumnName varchar(30)
                ,@GCRange int

            SET @PKColumnName = 'eGalaxyTransactionID'
            SET @GCRange = 1

            EXECUTE @PK = dbo.GetNextGatewayCounter @PKColumnName, @Range

            INSERT dbo.eGalaxyTransactionIDs (eGalaxyTransactionID, NodeNo, LastTranNo, RecordVersion, LastUpdate, LastUpdatedBy)
                VALUES (@PK, @NodeNo, @Range, 1, GETDATE(), @LastUpdatedBy)
            SET @StartValue = 1
            SET @EndValue = @Range
            END

        COMMIT TRANSACTION

        RETURN @StartValue

    END TRY
    BEGIN CATCH
        DECLARE @ERROR_MESSAGE NVARCHAR(2048);
        DECLARE @ERROR_SEVERITY TINYINT;
        DECLARE @ERROR_NUMBER INT;

        SET @ERROR_MESSAGE = ERROR_MESSAGE();
        SET @ERROR_NUMBER = ERROR_NUMBER();
        SET @ERROR_SEVERITY = ERROR_SEVERITY();

        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION

        RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
        END CATCH
END
GO

