IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGenerateSeries') AND (o.type = 'TF')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP FUNCTION dbo.GTSGenerateSeries;
GO

/**********************************************************
	dbo.GTSGenerateSeries : Builds a table of Id's
		starting from @StartNumber and ending with
		@EndNumber.
 *********************************************************/
CREATE FUNCTION dbo.GTSGenerateSeries
(
    @StartNumber    int,
    @EndNumber      int

)
RETURNS @ids TABLE
(
    Row#    int,
    ID      int
)
AS
BEGIN
    ;WITH n(n) AS
    (
        SELECT @StartNumber
        UNION ALL
        SELECT n+1 FROM n WHERE n < @EndNumber
    )
    INSERT INTO @ids
        SELECT
        ROW_NUMBER() OVER(ORDER BY n) AS Row#,
        n FROM n ORDER BY n
    OPTION (MAXRECURSION 100)

    RETURN
END
GO

