--
PRINT '    ' + 'Creating UpgradeeGalaxyTransactionCounters...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'UpgradeeGalaxyTransactionCounters') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.UpgradeeGalaxyTransactionCounters
GO

CREATE PROCEDURE dbo.UpgradeeGalaxyTransactionCounters AS BEGIN
    DECLARE
                @eGalaxyConfigNodeNo Int,
                @eGalaxyConfigLastTranNo Int,
                @eGalaxyTranIDLastTranNo Int,
                @RowCount Int,
                @ID Int

        DECLARE Upgrade_Cursor CURSOR FOR SELECT NodeNo, LastTranNo FROM eGalaxyConfig
        OPEN Upgrade_Cursor

        FETCH NEXT FROM Upgrade_Cursor INTO @eGalaxyConfigNodeNo, @eGalaxyConfigLastTranNo
        WHILE (@@FETCH_STATUS = 0) BEGIN

                IF (@eGalaxyConfigNodeNo > 0) AND (@eGalaxyConfigLastTranNo > 0) BEGIN
                        SELECT @RowCount = Count(*) FROM eGalaxyTransactionIDs WHERE NodeNo=@eGalaxyConfigNodeNo
                        IF @RowCount = 0 BEGIN
                                SELECT @ID = MAX(eGalaxyTransactionID) FROM eGalaxyTransactionIDs
                                SET @ID = IsNULL(@ID, 0)
                                SET @ID = @ID + 1

                            INSERT INTO eGalaxyTransactionIDs Values (@ID, @eGalaxyConfigNodeNo, @eGalaxyConfigLastTranNo, 1, GetDate(), 'GTSUpgrade')

                                IF NOT EXISTS(SELECT CountValue FROM GatewayCounters WHERE Name = 'eGalaxyTransactionID')
                                        INSERT INTO GatewayCounters VALUES ('eGalaxyTransactionID', @ID)
                                ELSE
                                        UPDATE GatewayCounters SET CountValue=@ID WHERE Name='eGalaxyTransactionID'
                                END
                        ELSE BEGIN
                                SELECT @eGalaxyTranIDLastTranNo = LastTranNo FROM eGalaxyTransactionIDs WHERE NodeNo=@eGalaxyConfigNodeNo
                                IF (@eGalaxyTranIDLastTranNo IS NULL) OR (@eGalaxyTranIDLastTranNo = 0) OR (@eGalaxyTranIDLastTranNo < @eGalaxyConfigLastTranNo) BEGIN
                                        UPDATE eGalaxyTransactionIDs SET LastTranNo=@eGalaxyConfigLastTranNo, RecordVersion=RecordVersion+1, LastUpdate=GetDate(), LastUpdatedBy='GTSUpgrade'
                                                WHERE NodeNo=@eGalaxyConfigNodeNo
                                        END
                                END
                        END

                FETCH NEXT FROM Upgrade_Cursor INTO @eGalaxyConfigNodeNo, @eGalaxyConfigLastTranNo
                END
        CLOSE Upgrade_Cursor
        DEALLOCATE Upgrade_Cursor
    END
GO

--
--         PROCEDRUE  GTSUpgradeUpdateOrderLinesForPayOnIssuance
--
PRINT '    ' + 'Creating GTSUpgradeUpdateOrderLinesForPayOnIssuance...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeUpdateOrderLinesForPayOnIssuance') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeUpdateOrderLinesForPayOnIssuance
GO
CREATE PROCEDURE dbo.GTSUpgradeUpdateOrderLinesForPayOnIssuance( @RunMode int, @Error int OUTPUT ) WITH RECOMPILE AS BEGIN
    /*                        1.8.16
    This store procedure updates the existing pre 1.8.16 OE Payment OrderLines
    to indicated that the payments have been issued (journalized)

    Note: The conversion should be done only once.  The script already handles this.
          This note is just to inidcate that this conversion process should be done only once.
    */
    DECLARE
        @SQL          nvarchar(3000),
        @Txt          varchar(3000),
        @RecordCount  integer,
        @ColumnExists bit,
        @Err          int

    SET NOCOUNT ON

    IF (ObjectProperty(object_id('Orders'),     'IsUserTable') IS NULL) OR
       (ObjectProperty(object_id('OrderLines'), 'IsUserTable') IS NULL) RETURN

    SET @SQL = 'SET NOCOUNT ON
                SELECT @RecordCount = count(*)
                FROM OrderLines ol, Orders o
                WHERE ol.OrderID = o.OrderID
                AND ol.IssuedQuantity = 0
                AND DetailType in (2,4)  '   /* 2: payments; 4: voided payments */

    EXEC @ColumnExists = GTSColumnExists 'Orders', 'PayOnIssuance'
    IF @ColumnExists = 1 SET @SQL = @SQL + ' ' + 'AND ((PayOnIssuance IS NULL) OR (PayOnIssuance = 0))'

    EXEC sp_executesql @SQL, N'@RecordCount int OUTPUT', @RecordCount OUTPUT

    SELECT @Err = @@Error
    IF @Err > 0 SET @Error = @Err

    IF @RecordCount <= 0 RETURN

    SET @Txt = 'Updating OrderLines.IssuedQuantity for payment records...'
    EXEC GTSAddUpgradeLog @RunMode, @Txt, 1

    IF ((@RunMode % 10) = 0) BEGIN
        /* Test Mode...just give us the counts */
        SET @Txt =  'There are ' + Convert(varchar, @RecordCount) + ' OrderLines to be updated.'
        EXEC GTSAddUpgradeLog @RunMode, @Txt, 2
        END
    ELSE BEGIN
        SET @Txt = 'Updating ' + Convert(varchar, @RecordCount) + ' Orderlines...'
        EXEC GTSAddUpgradeLog @RunMode, @Txt, 2

        -- Script needs to be dynamic because PayOnIssuance might not exist yet before the upgrade
        SET @SQL = '
            SET NOCOUNT ON

            DECLARE
                PaymentLine_Cursor CURSOR FOR
                    SELECT ol.OrderLineID
                    FROM OrderLines ol, Orders o
                    WHERE ol.OrderID = o.OrderID
                    AND ((PayOnIssuance IS NULL) OR (PayOnIssuance = 0))
                    AND ol.IssuedQuantity = 0
                    AND DetailType in (2,4)  -- 2: payments; 4: voided payments

            DECLARE
                @OrderLineID Integer

            OPEN PaymentLine_Cursor
            FETCH NEXT FROM PaymentLine_Cursor INTO @OrderLineID
            WHILE (@@FETCH_STATUS = 0) BEGIN
                UPDATE OrderLines SET IssuedQuantity = 1 WHERE OrderLineID = @OrderLineID

                FETCH NEXT FROM PaymentLine_Cursor INTO @OrderLineID
                END

            CLOSE PaymentLine_Cursor
            DEALLOCATE PaymentLine_Cursor
        '   -- closing quote
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL, 0, 1  /* suppress display */

        SET @Txt = 'done'
        EXEC GTSAddUpgradeLog @RunMode, @Txt, 2
        END
    END
Go



--
--                      PROCEDURE GTSUpgradeCorrectOrderLineAmountForPayment
--
PRINT '    ' + 'Creating GTSUpgradeCorrectOrderLineAmountForPayment...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeCorrectOrderLineAmountForPayment') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeCorrectOrderLineAmountForPayment
GO
CREATE PROCEDURE dbo.GTSUpgradeCorrectOrderLineAmountForPayment(@RunMode  int,
                                                                @Error    int OUTPUT) AS BEGIN
    SET nocount ON

    /*
    Check to see if the payment order line amount matches its OrderPayment table amount.
    If not, update the ordeer line with OrderPayment's.
    */

    IF (@Error <> 0) RETURN  -- If error occurred, dont do anything anymore...

    DECLARE
        @Count        int,
        @Log          varchar(256),
        @SQL          varchar(2000),
        @TableExists  bit

    EXEC @TableExists = GTSTableExists OrderPayments
    IF @TableExists = 0 RETURN

    SELECT @Count = count(*)
    FROM OrderLines ol, OrderPayments op
    WHERE ol.detailtype = 2
    AND   ol.DetailTableID= op.OrderPaymentID
    AND   ol.amount <> op.PaymentAmount

    IF @Count > 0 BEGIN
        SET @Log = 'Checking Payment OrderLines with mismatched payment amounts between OrderLine and its OrderPayment'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

        SET @Log = convert(varchar, @Count) + ' OrderLines found.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2

        SET @SQL = 'UPDATE OrderLines SET amount = PaymentAmount
                    FROM  OrderLines ol, OrderPayments op
                    WHERE ol.DetailType = 2
                    AND   ol.DetailTableID = op.OrderPaymentID
                    AND   ol.Amount <> op.PaymentAmount '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    END
GO

--
--         PROCEDRUE  GTSUpgradeGeneralStatements
--
PRINT '    ' + 'Creating GTSUpgradeGeneralStatements...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeGeneralStatements') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeGeneralStatements
GO
CREATE PROCEDURE dbo.GTSUpgradeGeneralStatements( @RunMode int, @Error int OUTPUT ) WITH RECOMPILE AS BEGIN
    /*                        1.8.17
    This stored procedure adds entries to OEStatementGroups for any Statements defined to
    CustCategories not in OEStatementGroups yet.

    Note: The conversion should be done only once.  The script already handles this.
          This note is just to inidcate that this conversion process should be done only once.
    */
    DECLARE
        @CustCategoryID  Int,
        @StatementID     Int,
        @RecordCount     int,
        @TableExists     bit,
        @Txt             varchar(300),
        @SQL             varchar(3000)

    SET NOCOUNT ON

    /* if CustCategories table does not exists, just exit -- most likely new DB */
    EXEC @TableExists = GTSTableExists CustCategories
    IF @TableExists = 0 RETURN

    EXEC @TableExists = GTSTableExists OEStatementGroups
    IF @TableExists = 1 BEGIN
        SELECT @RecordCount = count(*)
        FROM CustCategories cc
             LEFT OUTER JOIN OEStatementGroups oes ON (cc.CustCategoryID = oes.GroupID) AND (oes.GroupIDType = 0) AND (oes.StatementType = 0)
        WHERE oes.GroupID IS NULL
        END
    ELSE BEGIN
        SELECT @RecordCount = count(*) FROM CustCategories
        END

    IF @RecordCount <= 0 RETURN

    SET @Txt = 'Add assigned Customer Category Statements to table OEStatementGroups.  There are ' +
                convert(varchar, @RecordCount) + ' records to be added.'
    EXEC GTSAddUpgradeLog @RunMode, @Txt, 1

    IF ((@RunMode % 10) = 1) BEGIN
        DECLARE
            @ID int

        DECLARE
            CustCat_Cursor CURSOR FOR
                SELECT cc.CustCategoryID, cc.StatementID
                FROM CustCategories cc
                    LEFT OUTER JOIN OEStatementGroups oes ON (cc.CustCategoryID = oes.GroupID)
                                                             AND (oes.GroupIDType = 0) AND (oes.StatementType = 0)
                WHERE oes.GroupID IS NULL

        SELECT @ID = MAX(OEStatementGroupID) FROM OEStatementGroups

        SET @ID = IsNULL(@ID, 0)
        SET @Txt = 'Adding ' + convert(varchar, @RecordCount) + ' records.'
        EXEC GTSAddUpgradeLog @RunMode, @Txt, 1

        OPEN CustCat_Cursor
        FETCH NEXT FROM CustCat_Cursor INTO @CustCategoryID, @StatementID

        WHILE (@@FETCH_STATUS = 0) BEGIN
            SET @ID = @ID + 1
            SET @SQL = 'INSERT INTO OEStatementGroups Values(' +
                            convert(varchar, @ID)              + ', 0, ' +
                            convert(varchar, @CustCategoryID)  + ', '    +
                            convert(varchar, @StatementID)     + ', 0, 1, GetDate(), ''GTSUpgrade'' )'

            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL, 0, 1  /* suppress display */

            FETCH NEXT FROM CustCat_Cursor INTO @CustCategoryID, @StatementID
            END

        CLOSE CustCat_Cursor
        DEALLOCATE CustCat_Cursor

        -- now update the GatewayCounters entry
        IF NOT EXISTS(SELECT CountValue FROM GatewayCounters WHERE Name = 'OEStatementGroupID')
            SET @SQL = 'INSERT INTO GatewayCounters VALUES (''OEStatementGroupID'', ' + convert(varchar, @ID) + ')'
        ELSE
            SET @SQL = 'UPDATE GatewayCounters SET CountValue = ' + convert(varchar, @ID) + ' WHERE Name = ''OEStatementGroupID'''

        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    END
GO



--
--         PROCEDRUE  RecreateTicketsAccessCodeIDIndexAsNonUnique
--
PRINT '    ' + 'Creating RecreateTicketsAccessCodeIDIndexAsNonUnique...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'RecreateTicketsAccessCodeIDIndexAsNonUnique') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.RecreateTicketsAccessCodeIDIndexAsNonUnique
GO
CREATE PROCEDURE dbo.RecreateTicketsAccessCodeIDIndexAsNonUnique( @RunMode int, @Error int OUTPUT) WITH RECOMPILE AS BEGIN
    /*                            Galaxy 2.5
    This is a MUST CHANGE if upgrading TCon32 to verion 2.5 and later.

    First we need to check if DB has any version prior to 2.5.  If it does, check the user
    option @UpgradingTCon32_2_5_Later, "Upgrading TCon32 to Version 2.5 and Later"
    */
    SET nocount ON

    DECLARE
        @Option             sysname,
        @OptionValue        int,
        @UpgradeIsRequired  bit,
        @IndexName          sysname,
        @Log                varchar(4000),
        @SQL                varchar(4000),
        @ProcessUpgrade     bit

    SET @ProcessUpgrade = 0

    /*
    Check if UpgradeIsRequired
    First, we must get all the index info for Tickets
    */
    EXEC GTSUpgradeGatherTableIndexes  'Tickets'

    SELECT @IndexName = IndexName, @UpgradeIsRequired = IsUnique
    FROM TableIndexDefs
    WHERE (TableName = 'Tickets') AND (IndexColumns = 'AccessCode,ID')

    IF @IndexName IS NULL BEGIN
        -- index is not found, must be a new install.  Create and exit
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, Tickets, 'AccessCode,ID', IXTicketsAccessCodeID
        RETURN
        END

    SET @Option = 'Upgrading TCon32 to Version 2.5 and Later'
    SELECT @OptionValue = Convert(int, Value) FROM UpgradeSettings WHERE Setting = @Option
    SET @OptionValue = IsNULL(@OptionValue, 0)

    IF @UpgradeIsRequired = 1 BEGIN
        EXEC GTSAddUpgradeLog  @RunMode, ' ', 1
        SET @Log = 'This is a sepecial one-time upgrade of the Tickets table'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
        EXEC GTSAddUpgradeLog  @RunMode, ' ', 1
        END

    IF @OptionValue = 0 BEGIN
        IF @UpgradeIsRequired = 1 BEGIN
            /*
            Tickets(AccessCode, ID) index is still unique (or index does not exists)
            print a warning message the option must be set to convert the index to non-unique
            */
            SET @Log = 'The index on Tickets(AccessCode,ID) is still an Unique Index.  If TCon32 is'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'also upgrading to version 2.5 and later, for the first time, the index on the'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'Tickets(AccessCode, ID) must be changed to a non-unique index.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            EXEC GTSAddUpgradeLog  @RunMode, ' ', 2

            SET @Log = 'If TCon32 is also upgrading to Version 2.5 and later for the first time,'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'please set "@UpgradingTCon32_2_5_Later" upgrade option to 1.  This setting'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'will convert the Tickets(AccessCode,ID) index to a non-unique Index'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            EXEC GTSAddUpgradeLog  @RunMode, ' ', 2

            SET @RunMode = (@RunMode / 10) * 10  -- make it a test mode
            SET @ProcessUpgrade = 1
            END
        END
    ELSE BEGIN
        /*
        Option is set to upgrade the Index, check to see if it is needed
        */
        IF @UpgradeIsRequired = 1 BEGIN
            SET @ProcessUpgrade = 1
            END
        ELSE BEGIN
            EXEC GTSAddUpgradeLog  @RunMode, ' ', 1
            SET @Log = 'This is a sepecial one-time upgrade to the Tickets table.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSAddUpgradeLog  @RunMode, ' ', 1

            SET @Log = 'The "@UpgradingTCon32_2_5_Later" option is set to upgrade the Tickets(AccessCode, ID) index'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'to a non-unique index but the index is already a non-unique index'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            END
        END

    IF @ProcessUpgrade = 1 BEGIN
        SET @Log = 'This upgrade will upgrade the Tickets table regardless of the ManualUpgrades table '
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = 'setting for the Tickets table.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        EXEC GTSAddUpgradeLog  @RunMode, ' ', 2

        SET @Log = 'TCon32 version 2.5 and later requires the index on (AccessCode, ID) be a non-unique index.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = 'NOTE: Once upgraded, TCon32 prior to version 2.5 will not work correctly.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        EXEC GTSAddUpgradeLog  @RunMode, ' ', 2

        IF @IndexName IS NOT NULL BEGIN
            SET @Log = 'First, we drop existing Unique Index "' + @IndexName + '"'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @SQL = 'DROP INDEX Tickets.' + @IndexName
            EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL

            SET @Log = 'Now, recreate the index withotut the Unique Constraint'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @SQL = 'CREATE INDEX IXTicketsAccessCodeID ON Tickets(AccessCode,ID)'
            EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
            END
        END
    END
GO


--
--         PROCEDURE  CreateReentryTable
--
PRINT '    ' + 'Creating CreateReentryTable...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'CreateReentryTable') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.CreateReentryTable
GO
CREATE PROCEDURE dbo.CreateReentryTable( @RunMode int, @Error int OUTPUT) WITH RECOMPILE AS BEGIN
    /*                          Galaxy 2.5
    This is a MUST CHANGE if upgrading TCon32 to verion 2.5 and later.

    Prior to 2.5, TCon32 handled the Reentry table upgrades.  Now, TCon32 will just use the
    Reentry table as is and GalaxyDatabase.SQL will handle the upgrade.

    So, we must do a special hanlding for the Reentry table.

    The 2.5 change to reentry is to use Gateway Counter value for its key.  So, the
    new PK Column "ReentryID' is the "trigger" to for conversion.
    */
    SET nocount ON

    DECLARE
        @TableName          sysname,
        @TableStructure     varchar(7500),
        @Option             sysname,
        @OptionValue        int,
        @UpgradeIsRequired  bit,
        @Log                varchar(4000),
        @SQL                varchar(4000),
        @ProcessUpgrade     bit
--
--  -------------------------------------------------------------------
--
--                  ***  Reentry  ***
--
SET @TableName = 'Reentry'
SET @TableStructure = '
        ReentryID        int          NOT NULL,
        AccessCode       int              NULL,
        SerialNo         nvarchar(20)         NULL,
        Facility         int              NULL,
        EntryTime        DateTime         NULL,
        Qty              int              NULL,
        ACP              int              NULL,
        VisualID         nvarchar(40)      NULL,
        BankNo           int              NULL,
        Override         int              NULL,
        ScannedVisualID  nvarchar(40)      NULL,
        AdultQty         int              NULL,
        ChildQty         int              NULL,
        GuestQty         int              NULL,
        JointMemberID    int              NULL,
        Status           int              NULL,
        Attraction       int              NULL,
        OperationID      int              NULL,

        RecordVersion  int       NOT NULL,
        LastUpdate     datetime  NOT NULL,
        LastUpdatedBy  nvarchar(20) NULL
' -- *** NO CLOSING PARENTHESIS
    SET @SQL = 'CREATE TABLE dbo.' + @TableName + ' ( ' + @TableStructure + '    ' + '    ' + ')'

    SET @ProcessUpgrade = 0   -- don't upgrade until told to do so

    IF ((@RunMode / 10) = 1)
        SET @Log = 'Checking for a table upgrade --->  dbo.' + @TableName + ' at ' + convert(varchar, GetDate(),9)
    ELSE
        SET @Log = 'Checking for a Post upgrade  --->  dbo.' + @TableName + ' at ' + convert(varchar, GetDate(),9)
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 0

    -- is our "key" column there?
    IF ColumnProperty(object_id('Reentry'), 'ReentryID', 'AllowsNULL') IS NULL
        SET @UpgradeIsRequired = 1
    ELSE
        SET @UpgradeIsRequired = 0


    -- Check if we have the option set
    SET @Option = 'Upgrading TCon32 to Version 2.5 and Later'
    SELECT @OptionValue = Convert(int, Value) FROM UpgradeSettings WHERE Setting = @Option
    SET @OptionValue = IsNULL(@OptionValue, 0)

    IF @UpgradeIsRequired = 1 BEGIN
        EXEC GTSAddUpgradeLog  @RunMode, ' ', 1
        SET @Log = 'This is a sepecial one-time upgrade to the Reentry table.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
        EXEC GTSAddUpgradeLog  @RunMode, ' ', 1
        END

    IF @OptionValue = 0 BEGIN
        IF @UpgradeIsRequired = 1 BEGIN
            /*
            ReentryID column does not exists and the option to convert the Reentry table is
            not set.  Warn the user this is a must change for TCon32 upgrade to 2.5+
            */
            SET @Log = 'TCon32 version 2.5 and later uses the Gateway Counter values to identify a unique row'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'in Reentry table.  This is a MUST CHANGE upgade if TCon32 is also upgraded to verion 2.5 and later.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'If TCon32 is also upgrading to Version 2.5 and later for the first time,'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'please set "@UpgradingTCon32_2_5_Later" upgrade option to 1.  This setting'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'will convert the Reentry table.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            EXEC GTSAddUpgradeLog  @RunMode, ' ', 2

            SET @ProcessUpgrade = 1
            SET @RunMode = (@RunMode / 10) * 10   -- make it a test mode
            END
        END
    ELSE BEGIN
        IF @UpgradeIsRequired = 1 BEGIN
            SET @Log = 'This upgrade will upgrade the Reentry table regardless of the ManualUpgrades table setting.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = ''
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            EXEC GTSAddUpgradeLog  @RunMode, ' ', 2
            SET @Log = 'TCon32 version 2.5 and later uses the Gateway Counter values to identify a unique row'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'in Reentry table.  This is a MUST CHANGE upgade if TCon32 is also upgraded to verion 2.5 and later.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            EXEC GTSAddUpgradeLog  @RunMode, ' ', 2

            SET @ProcessUpgrade = 1
            END
        ELSE BEGIN
            -- just a friendly saying the structure is up-to-date with TCon32 2.5+
            SET @Log = 'The "@UpgradingTCon32_2_5_Later" upgrade option is set to upgrade the Reentry Table.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            SET @Log = 'But the Reentry table is up-to-date and does not need this one-time only upgrade.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
            END
        END

    IF @ProcessUpgrade = 1 BEGIN
        SET @Log = 'NOTE: Once upgraded, TCon32 prior to version 2.5 will not work correctly.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = 'NOTE: This upgrade process drops the Reentry table and recreates the Reentry table'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = '      with the correct structure.  This means, all the reentry information will be lost.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        EXEC GTSAddUpgradeLog  @RunMode, ' ', 2

        SET @Log = 'First, drop the existing Reentry table'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, 'DROP TABLE Reentry'

        SET @Log = 'Now, create the Reentry table with a correct structure'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2

        /*
        EXEC GTSUpgradeExecSQL   @RunMode, @Error OUTPUT, @SQL
        EXEC GTSUpgradeAddPK     @RunMode, @Error OUTPUT, @TableName, ReentryID,                      PKReentryReentryID
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'AccessCode,SerialNo,Facility', IXReentryAccessSerialFacility
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, EntryTime,                      IXReentryEntryTime
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, Facility,                       IXReentryFacility
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, SerialNo,                       IXReentrySerialNo
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, VisualID,                       IXReentryVisualID
        */

        EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

        EXEC GTSUpgradeAddPK     @RunMode, @Error OUTPUT, @TableName, ReentryID,                      PKReentryReentryID

        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'AccessCode,SerialNo,Facility', IXReentryAccessSerialFacility
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, EntryTime,                      IXReentryEntryTime
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, Facility,                       IXReentryFacility
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, SerialNo,                       IXReentrySerialNo
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, VisualID,                       IXReentryVisualID
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, LastUpdate,                     IXReentryLastUpdate
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, ScannedVisualID,                IXReentryScannedVisualID
        EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, JointMemberID,                  IXReentryJointMemberID
        /* Don't need to add "new" columns here since we JUST dropped and recreated the table! */
        END

    /* Add columns in case we didn't drop and recreate */
    IF @ProcessUpgrade = 0 BEGIN
	      EXEC GTSUpgradeAddColumn @RunMode, @Error OUTPUT, @TableName, OperationID,					  int
		    END
    END
GO



--
--         PROCEDRUE  MediaTablePrefetchModeUpgrade
--
PRINT '    ' + 'Creating MediaTablePrefetchModeUpgrade...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'MediaTablePrefetchModeUpgrade') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.MediaTablePrefetchModeUpgrade
GO
CREATE PROCEDURE dbo.MediaTablePrefetchModeUpgrade( @RunMode int, @Error int OUTPUT) WITH RECOMPILE AS BEGIN

    DECLARE
        @SQL varchar(1000),
        @Log varchar(1000)

    IF ColumnProperty(object_id('Media'), 'PrefetchMode', 'AllowsNULL') IS NULL BEGIN
        SET @Log = 'This is a one time upgrade task to Media table.  This change will add a new column'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = 'PrefetchMode to replace the existing Prefetch column.  This new column is an integer'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = 'type to give more state of Prefetch.  All existing Prefetch setting value will be   '
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = 'mapped as follows:'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = '    Prefetch  =>  PefetchMode'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = '     NULL             0'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = '     0                0'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        SET @Log = '     1                1'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2

        EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Media,  PrefetchMode,  int

        SET @SQL = 'UPDATE Media SET PrefetchMode = Convert(int, IsNULL(Prefetch, 0))'
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END
    END
GO


