--

PRINT '    ' + 'Creating GetDeliveryMethods...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GetDeliveryMethods') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GetDeliveryMethods
GO

CREATE PROCEDURE dbo.GetDeliveryMethods
	@OrderID int
AS BEGIN

DECLARE @DeliveryMethodCount int

-- ---------------------------------------------------------------------------
-- Checks all the orderlines in the order for at lease one common delivery
-- method group id. this is need to determine how to write the select for
-- delivery method query.
-- ---------------------------------------------------------------------------

SELECT @DeliveryMethodCount = COUNT(*) FROM DeliveryMethodGroups WHERE DeliveryMethodGroupID IN
(select DeliveryMethodGroupID from DeliveryMethodGroups Where DeliveryMethodGroupID IN
	(select DeliveryMethodGroupID from items where PLU IN
		(select PLU FROM OrderLines Where OrderID = @OrderID)))

	IF @DeliveryMethodCount > 1
		BEGIN

		-- ---------------------------------------------------------------------------
		-- Get the common delivery methods for the order belonging to differing
		-- delivery method groups.
		-- ---------------------------------------------------------------------------

		SELECT * FROM DeliveryMethods WHERE DeliveryMethodID IN
		(select a.DeliveryMethodID from (select DISTINCT DeliveryMethodGroupID, DeliveryMethodID from DeliveryMethodGroupDetails where DeliveryMethodGroupID IN
			(select DeliveryMethodGroupID from DeliveryMethodGroups Where DeliveryMethodGroupID IN
				(select DeliveryMethodGroupID from items where PLU IN
					(select PLU FROM OrderLines WHERE OrderID = @OrderID AND PLU<> '')))) a
			LEFT OUTER JOIN DeliveryMethodGroupDetails b ON a.DeliveryMethodID = b.DeliveryMethodID AND a.DeliveryMethodGroupID <> b.DeliveryMethodGroupID
			WHERE
			b.DeliveryMethodID IS NOT NULL
			GROUP BY a.DeliveryMethodID)
			ORDER BY DeliveryMethodID
		END
	ELSE
		BEGIN

		-- ---------------------------------------------------------------------------
		-- Get the common delivery methods for the order belonging to to a single
		-- common delivery method group.
		-- ---------------------------------------------------------------------------

			SELECT * FROM DeliveryMethods WHERE DeliveryMethodID IN
			 (SELECT DeliveryMethodID FROM DeliveryMethodGroupDetails WHERE DeliveryMethodGroupID IN
				(SELECT DeliveryMethodGroupID FROM DeliveryMethodGroups WHERE DeliveryMethodGroupID IN
					(SELECT DeliveryMethodGroupID FROM items WHERE PLU IN
						(SELECT PLU FROM OrderLines WHERE OrderID = @OrderID AND PLU<> ''))))
			ORDER BY DeliveryMethodID
		END

	RETURN
        END
GO
--
--
--                  ***  End GetDeliveryMethods Stored Procedure  ***
--  -------------------------------------------------------------------
--

