CREATE PROCEDURE [dbo].[GTSUpdateFacilityCounts]
    @FacilityID Int,
    @Date DateTime,
    @EntryCounts Int,
    @ReentryCounts Int,
    @CrossoverCounts Int,
    @EntryClicks Int,
    @ReentryClicks Int,
    @ExitClicks Int

    /*
    Updates EntryCounts, ReentryCounts, CrossoverCounts, EntryClicks, ReentryClicks,
    and ExitClick Delta values for the given FacilityID and Date. Calling this
    stored procedure where FacilityID and/or Date is not found creates a new row
    with the Delta values.
    */

AS
BEGIN
    SET NOCOUNT ON
    SET XACT_ABORT ON

    DECLARE @LockName nVarChar(255)
    DECLARE @LockResult Int
    DECLARE @RecordVersion Int
    DECLARE @LastUpdatedBy varchar(20)
    DECLARE @StartTranCount Int

    BEGIN TRY
         SELECT @StartTranCount = @@TRANCOUNT

         /* The name of the application lock is "GTS_UpdateFacilityCountsX" (where X is the FacilityID) */
         SET @LockName = 'GTS_UpdateFacilityCounts' + CAST(@FacilityID as VarChar(10))

         IF @StartTranCount = 0 BEGIN TRANSACTION

            /* Acquire application lock */
             EXEC @LockResult = sp_getapplock
                  @Resource = @LockName, @LockMode = 'Exclusive',
                 @LockTimeout = 1000 /*, @DbPrincipal = 'public'  this parameter removed */

             IF @LockResult >= 0 BEGIN /* Lock Acquired */

                  /* Check if FacilityID and Date Exist */
                  SELECT @RecordVersion = FC.RecordVersion
                      FROM FacilityCounts AS FC
                      WHERE FC.FacilityID = @FacilityID AND FC.Date = @Date

                  SET NOCOUNT OFF

                  IF (@RecordVersion IS NULL) BEGIN /* Insert New Row with Counts and Clicks */
                      INSERT INTO FacilityCounts(
                          FacilityID,
                          Date,
                          EntryCounts,
                          ReentryCounts,
                          CrossoverCounts,
                          EntryClicks,
                          ReentryClicks,
                          ExitClicks,
                          RecordVersion,
                          LastUpdate,
                          LastUpdatedBy)
                     VALUES(
                          @FacilityID,
                          @Date,
                          @EntryCounts,
                          @ReentryCounts,
                          @CrossoverCounts,
                          @EntryClicks,
                          @ReentryClicks,
                          @ExitClicks,
                          1,
                          GetDate(),
                          'sa');
                          END
                 ELSE BEGIN /* Update Current Counts and Clicks */
                     UPDATE FacilityCounts SET
                          EntryCounts     = EntryCounts     + @EntryCounts,
                          ReentryCounts   = ReentryCounts   + @ReentryCounts,
                          CrossoverCounts = CrossoverCounts + @CrossoverCounts,
                          EntryClicks     = EntryClicks     + @EntryClicks,
                          ReentryClicks   = ReentryClicks   + @ReentryClicks,
                          ExitClicks      = ExitClicks      + @ExitClicks,
                          RecordVersion   = RecordVersion + 1,
                          LastUpdate      = GetDate(),
                          LastUpdatedBy   = 'sa'
                          WHERE FacilityID = @FacilityID AND Date = @Date
                     END
                  END

         IF @StartTranCount = 0 COMMIT TRANSACTION
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVarChar(MAX), @ErrorSeverity Int, @ErrorState Int;
        SELECT @ErrorMessage = ERROR_MESSAGE() + ' Line ' + CAST(ERROR_LINE() AS NVarChar(5)), @ErrorSeverity = ERROR_SEVERITY(), @ErrorState = ERROR_STATE();
        IF XACT_STATE() <> 0 AND @StartTranCount = 0 ROLLBACK TRANSACTION
        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

--
--
--                  ***  End GTSUpdateFacilityCounts Stored Procedure  ***
--  -------------------------------------------------------------------
--


