CREATE PROCEDURE [dbo].[GTSUpdateAttractionCounts]
    @AttractionID Int,
    @Date DateTime,
    @EntryCounts Int,
    @ReentryCounts Int,
    @EntryClicks Int,
    @ReentryClicks Int,
    @ExitClicks Int

    /*
    Updates EntryCounts, ReentryCounts, EntryClicks, ReentryClicks,
    and ExitClick Delta values for the given AttractionID and Date. Calling this
    stored procedure where AttractionID and/or Date is not found creates a new row
    with the Delta values.
    */

AS
BEGIN
    SET NOCOUNT ON
    SET XACT_ABORT ON

    DECLARE @LockName nVarChar(255)
    DECLARE @LockResult Int
    DECLARE @RecordVersion Int
    DECLARE @LastUpdatedBy varchar(20)
    DECLARE @StartTranCount Int

    BEGIN TRY
         SELECT @StartTranCount = @@TRANCOUNT

         /* The name of the application lock is "GTS_UpdateApplicationCountsX" (where X is the AttractionID) */
         SET @LockName = 'GTS_UpdateAttractionCounts' + CAST(@AttractionID as VarChar(10))

         IF @StartTranCount = 0 BEGIN TRANSACTION
             /* Acquire application lock */
             EXEC @LockResult = sp_getapplock
                  @Resource = @LockName, @LockMode = 'Exclusive',
                  @LockTimeout = 1000 /*, @DbPrincipal = 'public'  this parameter removed */

         IF @LockResult >= 0 BEGIN /* Lock Acquired */

             /* Check if AttractionID and Date Exist */
             SELECT @RecordVersion = AC.RecordVersion
                 FROM AttractionCounts AS AC
                  WHERE AC.AttractionID = @AttractionID AND AC.Date = @Date

             SET NOCOUNT OFF

             IF (@RecordVersion IS NULL) BEGIN /* Insert New Row with Counts and Clicks */

                  INSERT INTO AttractionCounts(
                           AttractionID,
                          Date,
                          EntryCounts,
                          ReentryCounts,
                          EntryClicks,
                          ReentryClicks,
                          ExitClicks,
                          RecordVersion,
                          LastUpdate,
                          LastUpdatedBy)
                  VALUES(
                          @AttractionID,
                          @Date,
                          @EntryCounts,
                          @ReentryCounts,
                           @EntryClicks,
                          @ReentryClicks,
                          @ExitClicks,
                          1,
                          GetDate(),
                          'sa'); /* This should probably be ACS Node / TCon Node Info */
                 END
             ELSE BEGIN /* Update Current Counts and Clicks */
                  UPDATE AttractionCounts SET
                          EntryCounts     = EntryCounts     + @EntryCounts,
                          ReentryCounts   = ReentryCounts   + @ReentryCounts,
                           EntryClicks     = EntryClicks     + @EntryClicks,
                          ReentryClicks   = ReentryClicks   + @ReentryClicks,
                          ExitClicks      = ExitClicks      + @ExitClicks,
                          RecordVersion   = RecordVersion + 1,
                          LastUpdate      = GetDate(),
                          LastUpdatedBy   = 'sa'
                          /* This should probably be ACS Node / TCon Node Info */
                 WHERE AttractionID = @AttractionID AND Date = @Date
                 END
             END

         IF @StartTranCount = 0 COMMIT TRANSACTION
    END TRY
    BEGIN CATCH
         DECLARE @ErrorMessage NVarChar(MAX), @ErrorSeverity Int, @ErrorState Int;
         SELECT @ErrorMessage = ERROR_MESSAGE() + ' Line ' + CAST(ERROR_LINE() AS NVarChar(5)), @ErrorSeverity = ERROR_SEVERITY(), @ErrorState = ERROR_STATE();
IF XACT_STATE() <> 0 AND @StartTranCount = 0 ROLLBACK TRANSACTION
         RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO
