CREATE PROCEDURE dbo.GTSAddWSLocalizationRow

(@GroupID int,
@Page varchar(256),
@StringKey varchar(256),
@StringValue Text,
@ComboIndex int,
@Module int)

AS BEGIN

    DECLARE
        @SQL          nvarchar(3000),
        @ParamType    nvarchar(1000)

    SET @SQL = 'DECLARE @counter int
        IF NOT EXISTS  (select * from WSLocalization where page = @xPage and stringkey = @xStringKey and WSLocalizationGroupID = @xGroupID and ControlIndex = @xComboIndex and Module = @xModule AND ISNULL(TranslationLanguageID,0) = 0 ) BEGIN
        EXEC @counter = GetNextGatewayCounter ''WSLocalizationID''

        INSERT INTO WSLocalization (WSLocalizationID, Page, StringKey, StringValue, WSLocalizationGroupID, ControlIndex, Module, TranslationLanguageID, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES(@counter, @xPage, @xStringKey, @xStringValue, @xGroupID, @xComboIndex, @xModule, 0, 1, GetDate(), ''WebStore'' )
        END'
    SET @ParamType = '@xPage varchar(256), @xStringKey varchar(256), @xGroupID int, @xComboIndex int, @xStringValue Text, @xModule int'

    EXEC sp_executesql @SQL, @ParamType, @xPage = @Page, @xStringKey = @StringKey, @xGroupID = @GroupID, @xComboIndex = @ComboIndex, @xStringValue = @StringValue, @xModule = @Module
END
GO

