PRINT '    ' + 'Creating GTSAddWSLocalizationResellerValues...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSAddWSLocalizationResellerValues') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSAddWSLocalizationResellerValues
GO

