--
--                  ***  Start GTSAddWSLocalizationDefaultValues Stored Procedure  ***
--
--  NOTE: Calls to remove Obsolete Localization strings are executed after all the adds
--
PRINT '    ' + 'Creating GTSAddWSLocalizationDefaultValues...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSAddWSLocalizationDefaultValues') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSAddWSLocalizationDefaultValues
GO

CREATE Procedure dbo.GTSAddWSLocalizationDefaultValues(@GroupID integer, @RunMode integer = 0) as BEGIN
    /* don't do anything if WSLocalizationGroupID has not been created */
    DECLARE
        @ColumnExists bit

    EXEC @ColumnExists = GTSColumnExists WSLocalization, WSLocalizationGroupID
    if @ColumnExists = 0 RETURN

	-- Update GatewayCounter if needed
	DECLARE
		@MaxGatewayCounterValue INT
	SELECT @MaxGatewayCounterValue = MAX(WSLocalizationID) FROM WSLocalization;
	IF EXISTS (SELECT 1 FROM GatewayCounters WHERE name = 'WSLocalizationID')
		UPDATE GatewayCounters SET CountValue = @MaxGatewayCounterValue WHERE name = 'WSLocalizationID'

    -- first REMOVE obsolete localization rows - keep in alphabetical order:
    EXEC GTSDeleteWSLocalizationRow @GroupID, 'accountProfile/index', 'CityPlaceholder', 'City', 0, 0
