--
--                  ***  Start GTSRemoveUnusedLocalizationStrings Stored Procedure  ***
--
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSRemoveUnusedLocalizationStrings') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
