           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeWSHtml
GO
CREATE PROCEDURE dbo.GTSUpgradeWSHtml(@RunMode int, @Error int OUTPUT) AS BEGIN
    /*
     This is an one time upgrade to WSHtml -- many to many between WSHtml and Merchant and Sales Channel Details
     From now on, Merchant and Sales Channel Detail (Group) has a connection to
     the WSHtmlConnections table.  This allows a many to many connections

     This store proc prepare that data.
     */
    SET nocount ON

    DECLARE
        @Log varchar(4000),
        @SQL varchar(4000)

    SET @Log = 'WSHtml data must be upgraded.  This section will populate the WSHtmlConnections entries from the existing WSHtml data.'
    EXEC dbo.GTSAddUpgradeLog @RunMode, @Log, 2

    /* Create Connection entries */
    SELECT @SQL = '
        DECLARE
            @ID  Int,
            @Now DateTime

        EXEC @ID = dbo.GetNextGatewayCounter ''WSHtmlConnectionID''
        SELECT @Now = GetDate()

        INSERT INTO dbo.WSHtmlConnections
            (WSHtmlConnectionID, WSHtmlID, ConnectionType, ConnectionID, RecordVersion, LastUpdate, LastUpdatedBy)
        SELECT
            Rank = count(*) + @ID,
            a1.WSHtmlID, a1.OwnerType, a1.OwnerID,
            1, @Now, ''Upgrade''
        FROM dbo.WSHtml a1, dbo.WSHtml a2
        WHERE a1.WSHtmlID > a2.WSHtmlID
        GROUP BY a1.WSHtmlID, a1.OwnerType, a1.OwnerID
        ORDER BY Rank

        UPDATE GatewayCounters SET CountValue = IsNull(b.MaxID, 0)
        FROM (SELECT Max(WSHtmlConnectionID) MaxID FROM WSHtmlConnections) b
        WHERE Name = ''WSHtmlConnectionID''
        '

    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END
GO

--
--
--                  ***  End GTSUpgradeWSHtml Stored Procedure  ***
--  -------------------------------------------------------------------
--


