PRINT '    ' + 'Creating GTSUpgradeWSLocalization...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeWSLocalization') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpgradeWSLocalization
GO
CREATE PROCEDURE dbo.GTSUpgradeWSLocalization(@RunMode int, @Error int OUTPUT) AS BEGIN
    /*
     This is an one time upgrade to WSLocalization
     From now on, WSLocalization table will be a detail table of WSLocalizationGroups table
     This store proc prepare that data.
     */
    SET nocount ON

    DECLARE
        @ColumnExists bit

    /* if we already went thru the upgrade, don't bother */
    EXEC @ColumnExists = GTSColumnExists WSLocalization, WSLocalizationGroupID
    IF @ColumnExists = 1 RETURN

    DECLARE
        @Log varchar(4000)

    SET @Log = 'WSLocalization table must be upgraded.  This section updates the WSLocalization table and create entries in WSLocalizationGroups.'
    EXEC dbo.GTSAddUpgradeLog @RunMode, @Log, 2
    EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  WSLocalization,  WSLocalizationGroupID, int
    IF ((@RunMode % 10) = 0) /* Test Mode */ RETURN

    /* now update the new column with the MerchantID */
    DECLARE
        @SQL varchar(4000)

    /* Create WSLocalizationGroup entries */

    SELECT @SQL = '
        DECLARE
          @Now DateTime

        SELECT @Now = GetDate()

        UPDATE dbo.WSLocalization SET WSLocalizationGroupID = MerchantID
        UPDATE dbo.Merchants SET WSLocalizationGroupID = MerchantID

        INSERT INTO dbo.WSLocalizationGroups (WSLocalizationGroupID, Name, StringType, RecordVersion, LastUpdate, LastUpdatedBy)
        SELECT DISTINCT
          l.MerchantID,
          m.Code, 0,
          1, @Now, ''Upgrade''
        FROM dbo.WSLocalization l
           INNER JOIN dbo.Merchants m ON l.MerchantID = m.MerchantID
        ORDER BY l.MerchantID

        UPDATE dbo.GatewayCounters SET
            CountValue = IsNull(b.MaxID, 0)
        FROM (SELECT Max(WSLocalizationGroupID) MaxID FROM dbo.WSLocalizationGroups) b
        WHERE Name = ''WSLocalizationGroupID''
        '

    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END
GO

