CREATE PROCEDURE dbo.GTSCreateWSLocalizationGroupDeleteTrigger(@RunMode int, @Error int OUTPUT) AS BEGIN
    /*
     Create Delete trigger for WSLocalizationGroups table so when an entry is
     removed, the associated WSLocalization entries are also removed
     */
    SET nocount ON

    DECLARE
        @SQL varchar(4000)

    /* Always recreate the trigger */
    IF dbo.GTSIsTrigger('trWSLocalizationGroupsDeleteRemoveWSLocalization') = 1 BEGIN
	        SELECT @SQL = 'DROP TRIGGER dbo.trWSLocalizationGroupsDeleteRemoveWSLocalization'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    SELECT @SQL = '
       CREATE TRIGGER dbo.trWSLocalizationGroupsDeleteRemoveWSLocalization ON dbo.WSLocalizationGroups AFTER DELETE AS BEGIN
            /*
             *  Remove all WSLocalization entries linked to the deleted Group
             */
            SET NOCOUNT ON

            DELETE dbo.WSLocalization
            FROM dbo.WSLocalization l
                 INNER JOIN Deleted d ON l.WSLocalizationGroupID = d.WSLocalizationGroupID
            END
        '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL, @DontUseNoCount = 1
    END
GO

