CREATE PROCEDURE dbo.GTSCreateWSHTMLConnectionsDeleteTrigger(@RunMode int, @Error int OUTPUT) AS BEGIN
    SET nocount ON

    DECLARE
        @SQL varchar(4000)

    /* Always recreate the trigger */
    IF dbo.GTSIsTrigger('trWSHTMLConnectionsDelete') = 1 BEGIN
        SELECT @SQL = 'DROP TRIGGER dbo.trWSHTMLConnectionsDelete'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    SELECT @SQL = '
        CREATE TRIGGER dbo.trWSHTMLConnectionsDelete ON dbo.WSHtmlConnections AFTER DELETE AS BEGIN
            -- SET NOCOUNT ON added to prevent extra result sets from
            -- interfering with SELECT statements.
            SET NOCOUNT ON

            DELETE dbo.WSHtmlConnections
            FROM dbo.WSHtmlConnections l
                INNER JOIN Deleted d ON
                    l.WSHtmlID = d.WSHtmlID AND
                    l.ConnectionType = d.ConnectionType AND
                    l.ConnectionID = d.ConnectionID AND
                    IsNull(d.TranslationLanguageID, 0) = 0
            END
        '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL, @DontUseNoCount = 1
    END
GO

