CREATE PROCEDURE dbo.ConvertLocalization( @PageName varchar(256),
                                         @OldStringKey varchar(256),
                                         @NewStringKey varchar(256)) AS BEGIN
    SET nocount ON

    DECLARE
        @ColumnExists bit,
        @SQL nvarchar(4000),
        @ParamType nvarchar(1000)

    EXEC @ColumnExists = GTSColumnExists  WSLocalizationGroups, StringType

    IF (@ColumnExists = 0) RETURN

    SET @SQL = 'UPDATE WSLocalization
    SET StringKey = @xNewStringKey
    WHERE
        StringKey = @xOldStringKey AND
        Page = @xPageName AND
        EXISTS (SELECT WSG.WSLocalizationGroupID FROM WSLocalizationGroups WSG WHERE WSG.WSLocalizationGroupID = WSLocalizationGroupID AND WSG.StringType = 0)'
    SET @ParamType = '@xPageName varchar(256), @xOldStringKey varchar(256), @xNewStringKey varchar(256)'

    EXEC sp_executesql @SQL, @ParamType, @xPageName = @PageName, @xOldStringKey = @OldStringKey, @xNewStringKey = @NewStringKey
    END
GO

