CREATE FUNCTION [dbo].[GTSGetReservationRuleSet] (@PassID INT) RETURNS VARCHAR(36)
AS BEGIN
	DECLARE @GUID VARCHAR(36);

	SELECT @GUID = rrs.ACSReservationRuleSetGUID
	FROM ACSReservationRuleSets rrs
	  JOIN PassKindGroups pkg
		ON rrs.PassKindGroupGUID = pkg.PassKindGroupGUID
	  JOIN PassKindGroupDetails pkgd
		ON pkg.PassKindGroupGUID = pkgd.PassKindGroupGUID
	  JOIN PassKinds pk
		ON pkgd.PassKindID = pk.ID
	  JOIN Passes p
		ON pk.ID = p.Kind
	WHERE p.PassNo = @PassID;

	RETURN @GUID
END
GO

