CREATE FUNCTION [dbo].[GTSHasReservationRuleSet] (@PassID INT) RETURNS BIT
AS
BEGIN

	DECLARE @GUID VARCHAR(36);
	DECLARE @HAS_RULE_SET BIT;

	SELECT @GUID = [dbo].[GTSGetReservationRuleSet](@PassID);
	SELECT @HAS_RULE_SET = CASE ISNULL(@GUID,'N') WHEN 'N' THEN 0 ELSE 1 END;

	RETURN @HAS_RULE_SET;

END
GO

