CREATE FUNCTION [dbo].[GTSHasSameReservationRuleSet] (@PassID1 INT, @PassID2 INT) RETURNS BIT
AS
BEGIN

	DECLARE @HAS_SAME_RULE_SET BIT = 0;

	DECLARE @ACSReservationRuleSetGUID1 VARCHAR(36);
	DECLARE @ACSReservationRuleSetGUID2 VARCHAR(36);

	SELECT @ACSReservationRuleSetGUID1 = [dbo].[GTSGetReservationRuleSet](@PassID1);
	SELECT @ACSReservationRuleSetGUID2 = [dbo].[GTSGetReservationRuleSet](@PassID2);

	IF (@ACSReservationRuleSetGUID1 = @ACSReservationRuleSetGUID2) SET @HAS_SAME_RULE_SET = 1;

	RETURN @HAS_SAME_RULE_SET;
END
GO

