CREATE FUNCTION [dbo].[GTSCanViewReservation] (@PassID INT, @UserID INT) RETURNS BIT
AS
BEGIN

	DECLARE @GUID VARCHAR(36);
	DECLARE @CAN_VIEW BIT = 0;

	SELECT @GUID = [dbo].[GTSGetReservationRuleSet](@PassID);

	IF EXISTS(SELECT *
	          FROM gxusers u
	            JOIN userprofiles up
	              ON u.classid = up.Name
	            JOIN UserProfilePasskindGroups uppkg
	              ON uppkg.UserProfileID = up.Name
	            JOIN ACSReservationRuleSets arrs
	            	ON arrs.PassKindGroupGUID = uppkg.PassKindGroupGUID
  		  WHERE (arrs.ACSReservationRuleSetGUID = @GUID) AND (u.UserID = @UserID)
        ) BEGIN
        SET @CAN_VIEW = 1;
        END
    ELSE IF NOT EXISTS(SELECT TOP 1 *
                       FROM UserProfilePasskindGroups
                       WHERE UserProfileID = (SELECT ClassID FROM GxUsers WHERE UserID = @UserID)
        ) BEGIN
        SET @CAN_VIEW = 1;
        END;

	RETURN @CAN_VIEW;

END
GO

