CREATE FUNCTION [dbo].[GTSReservationRuleSetInUse] (@RuleSetGUID VARCHAR(36)) RETURNS BIT
AS
BEGIN

	DECLARE @IN_USE BIT = 0;
	SET @IN_USE = (SELECT CASE WHEN COUNT(*) >= 1 THEN 1 ELSE 0 END FROM [dbo].[ACSReservations] WHERE ACSReservationRuleSetID = @RuleSetGUID)
	RETURN @IN_USE;

END
GO

