CREATE PROCEDURE [dbo].[GTSGetACSAdmissionList] (@PassID INT)
AS
BEGIN

  SET NOCOUNT ON;

  DECLARE @GUID VARCHAR(36);

  SELECT @GUID = [dbo].[GTSGetReservationRuleSet] (@PassID);

  SELECT ah.AdmHeaderID, RTRIM(LEFT(ah.Description,20)) AS Description, rsah.IsDefault
  FROM ACSReservationRuleSetAdmissionHeaders rsah
    JOIN AdmissionHeaders ah
	  ON ah.AdmHeaderID = rsah.AdmissionHeaderID
  WHERE rsah.ACSReservationRuleSetGUID = @GUID
  ORDER BY ah.AdmHeaderID;

END
GO

PRINT '    ' + 'Dropping GTSGetACSReservationScope stored procedure...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGetACSReservationScope') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSGetACSReservationScope
GO

PRINT '    ' + 'Creating sp_GTS_GetPassByVisualID stored procedure...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'sp_GTS_GetPassByVisualID') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.sp_GTS_GetPassByVisualID
GO
CREATE PROCEDURE dbo.sp_GTS_GetPassByVisualID
(
	@VisualId	varchar(40)
)
AS
BEGIN

	SELECT		TOP 1
				*
	FROM		Passes
	WHERE		VisualID = @VisualId
	ORDER BY	PassNo DESC

END
GO

IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'sp_GTS_GetSuperTicketByVisualID') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.sp_GTS_GetSuperTicketByVisualID
GO

CREATE PROCEDURE dbo.sp_GTS_GetSuperTicketByVisualID
(
    @VisualId            varchar(40)
)
AS
BEGIN

                SELECT   TOP 1 *
                FROM     SuperTickets
                WHERE    VisualID = @VisualId
                ORDER BY SuperTicketID DESC
END
GO
/*************** END OF ACS RESERVATION SCALAR FUNCTIONS/STORED PROCEDURES SECTION ******************/


/*************** START OF RESOURCE MANAGEMENT STORED PROCEDURES SECTION ******************/
PRINT '    ' + 'Creating Resource Management stored procedures...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'CreateRMStoredProcedures') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.CreateRMStoredProcedures
GO

CREATE PROCEDURE [dbo].[CreateRMStoredProcedures]
AS BEGIN
    SET nocount ON
    DECLARE @SQL nvarchar(MAX)
    DECLARE @Err Int

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_AdjustCapacityHold') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_AdjustCapacityHold

     SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_AdjustCapacityHold] ') +
        dbo.GTSFormatSQL('    @RMFunction Int, -- No longer required but included for mixed mode compatibility. Must be 2. ') +
        dbo.GTSFormatSQL('    @EventID Int, ') +
        dbo.GTSFormatSQL('    @ResourceID Int, ') +
        dbo.GTSFormatSQL('    @Qty Int, ') +
        dbo.GTSFormatSQL('    @NodeNo Int, ') +
        dbo.GTSFormatSQL('    @GroupIDType Int, ') +
        dbo.GTSFormatSQL('    @GroupID Int, ') +
        dbo.GTSFormatSQL('    @CapacityID Int, ') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20), ') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT, ') +
        dbo.GTSFormatSQL('    @SalesChannelID Int = 0 ') +
        dbo.GTSFormatSQL('    AS BEGIN ') +
        dbo.GTSFormatSQL('        SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */ ') +

        dbo.GTSFormatSQL('    DECLARE @RowsAffected int ') +
        dbo.GTSFormatSQL('    DECLARE @HoldRowsAffected int ') +
        dbo.GTSFormatSQL('    DECLARE @StartTranCount int ') +
        dbo.GTSFormatSQL('    DECLARE @SalesChannelCapacityLimitMode Int ') +
        dbo.GTSFormatSQL('    DECLARE @RMCapacityHoldUID Int ') +
        dbo.GTSFormatSQL('    SET @ResultCode = 0 ') +
        dbo.GTSFormatSQL('    SET @RowsAffected = 0 ') +
        dbo.GTSFormatSQL('    SET @HoldRowsAffected = 0 ') +
        dbo.GTSFormatSQL('    SELECT @StartTranCount = @@TRANCOUNT ') +
        dbo.GTSFormatSQL('    BEGIN TRY ') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('            BEGIN TRANSACTION ') +
        dbo.GTSFormatSQL('        ELSE ') +
        dbo.GTSFormatSQL('            SAVE TRANSACTION LocalTran /* Check if a capacity hold record already exists */ ') +

        dbo.GTSFormatSQL('        IF @RMFunction <> 2 BEGIN') +
        dbo.GTSFormatSQL('            RAISERROR (''Legacy RMFunction not supported.'', 16, 1) ') +
        dbo.GTSFormatSQL('            END') +

        dbo.GTSFormatSQL('        /* Get the SalesChannelCapacityLimitMode from the event */ ') +
        dbo.GTSFormatSQL('        SELECT @SalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode ') +
        dbo.GTSFormatSQL('        FROM RMEvents ') +
        dbo.GTSFormatSQL('        WHERE EventID = @EventID ') +

        dbo.GTSFormatSQL('        /* Update the RMCapacityHold table */ ') +
        dbo.GTSFormatSQL('        UPDATE c ') +
        dbo.GTSFormatSQL('            SET HoldQuantity = HoldQuantity - @Qty, ') +
        dbo.GTSFormatSQL('                DateTimeHeld = GETDATE(), ') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1, ') +
        dbo.GTSFormatSQL('                LastUpdate = GETDATE(), ') +
        dbo.GTSFormatSQL('                LastUpdatedBy = @LastUpdatedBy, ') +
        dbo.GTSFormatSQL('                @RMCapacityHoldUID = RMCapacityHoldUID ') +
        dbo.GTSFormatSQL('            FROM RMCapacityHold c WITH (INDEX (IXAdjustCapacityHoldDelete)) ') +
        dbo.GTSFormatSQL('            WHERE EventID = @EventID ') +
        dbo.GTSFormatSQL('            AND ResourceID = @ResourceID ') +
        dbo.GTSFormatSQL('            AND (@NodeNo = 0 ') +
        dbo.GTSFormatSQL('            OR Node = @NodeNo) ') +
        dbo.GTSFormatSQL('            AND GroupIDType = @GroupIDType ') +
        dbo.GTSFormatSQL('            AND GroupID = @GroupID ') +
        dbo.GTSFormatSQL('            AND (@CapacityID = 0 ') +
        dbo.GTSFormatSQL('            OR CapacityID = @CapacityID) ') +
        dbo.GTSFormatSQL('            AND HoldQuantity > @Qty ') +
        dbo.GTSFormatSQL('            OPTION (RECOMPILE) ') +
        dbo.GTSFormatSQL('        SELECT @RowsAffected = @@ROWCOUNT ') +
        dbo.GTSFormatSQL('        IF @RowsAffected > 1 BEGIN ') +
        dbo.GTSFormatSQL('            SET @ResultCode = 3 ') +
        dbo.GTSFormatSQL('            RAISERROR (''Unable to update row in RMCapacityHold, more than 1 row would be modified'', 16, 1) ') +
        dbo.GTSFormatSQL('            END ') +

        dbo.GTSFormatSQL('        /* If update was successful and configured to look at sales channel then update the RMSalesChannelCapacityHold table */ ') +
        dbo.GTSFormatSQL('        IF (@RowsAffected > 0) AND (@SalesChannelCapacityLimitMode > 0) BEGIN ') +
        dbo.GTSFormatSQL('            UPDATE c ') +
        dbo.GTSFormatSQL('                SET HoldQuantity = HoldQuantity - @Qty, ') +
        dbo.GTSFormatSQL('                    RecordVersion = RecordVersion + 1, ') +
        dbo.GTSFormatSQL('                    LastUpdate = GETDATE(), ') +
        dbo.GTSFormatSQL('                    LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                FROM RMSalesChannelCapacityHold c ') +
        dbo.GTSFormatSQL('                WHERE RMCapacityHoldUID = @RMCapacityHoldUID ') +
        dbo.GTSFormatSQL('                    AND SalesChannelID = @SalesChannelID ') +
        dbo.GTSFormatSQL('                    AND HoldQuantity > @Qty ') +
        dbo.GTSFormatSQL('            SELECT @HoldRowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('            /* If RMSalesChannelCapacityHold table could not be updated then need to delete the row */ ') +
        dbo.GTSFormatSQL('            IF @HoldRowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                DELETE RMSalesChannelCapacityHold ') +
        dbo.GTSFormatSQL('                WHERE RMCapacityHoldUID = @RMCapacityHoldUID ') +
        dbo.GTSFormatSQL('                    AND SalesChannelID = @SalesChannelID ') +
        dbo.GTSFormatSQL('                    AND HoldQuantity = @Qty ') +
        dbo.GTSFormatSQL('                SELECT @HoldRowsAffected = @@ROWCOUNT ') +
        dbo.GTSFormatSQL('                IF @HoldRowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                    SET @ResultCode = 6 ') +
        dbo.GTSFormatSQL('                    RAISERROR (''Qty exceeds tickets on hold for Sales Channel'', 16, 1) ') +
        dbo.GTSFormatSQL('                    END ') +
        dbo.GTSFormatSQL('                END ') +
        dbo.GTSFormatSQL('            END ') +

        dbo.GTSFormatSQL('        /* If update was not successful then need to delete the row from the RMCapacityHold table */ ') +
        dbo.GTSFormatSQL('        IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('            SELECT @RMCapacityHoldUID = RMCapacityHoldUID ') +
        dbo.GTSFormatSQL('                FROM RMCapacityHold ') +
        dbo.GTSFormatSQL('                WHERE EventID = @EventID ') +
        dbo.GTSFormatSQL('                    AND ResourceID = @ResourceID ') +
        dbo.GTSFormatSQL('                    AND GroupIDType = @GroupIDType ') +
        dbo.GTSFormatSQL('                    AND GroupID = @GroupID ') +
        dbo.GTSFormatSQL('                    AND (@CapacityID = 0 OR CapacityID = @CapacityID) ') +
        dbo.GTSFormatSQL('                    AND (@NodeNo = 0 OR Node = @NodeNo) ') +
        dbo.GTSFormatSQL('                    AND HoldQuantity = @Qty ') +
        dbo.GTSFormatSQL('                OPTION (RECOMPILE) ') +
        dbo.GTSFormatSQL('            DELETE RMCapacityHold ') +
        dbo.GTSFormatSQL('                WHERE RMCapacityHoldUID = @RMCapacityHoldUID ') +
        dbo.GTSFormatSQL('                OPTION (RECOMPILE) ') +
        dbo.GTSFormatSQL('            SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('            IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('                RAISERROR (''Qty exceeds tickets on hold'', 16, 1) ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            /* If configured to look at sales channel then delete from RMSalesChannelCapacityHold table too*/ ') +
        dbo.GTSFormatSQL('            ELSE IF @SalesChannelCapacityLimitMode > 0 BEGIN ') +
        dbo.GTSFormatSQL('                DELETE RMSalesChannelCapacityHold ') +
        dbo.GTSFormatSQL('                WHERE RMCapacityHoldUID = @RMCapacityHoldUID ') +
        dbo.GTSFormatSQL('                    AND SalesChannelID = @SalesChannelID ') +
        dbo.GTSFormatSQL('                    AND HoldQuantity = @Qty ') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT ') +
        dbo.GTSFormatSQL('                IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                    SET @ResultCode = 6 ') +
        dbo.GTSFormatSQL('                    RAISERROR (''Qty exceeds tickets on hold for Sales Channel'', 16, 1) ') +
        dbo.GTSFormatSQL('                    END ') +
        dbo.GTSFormatSQL('                END ') +
        dbo.GTSFormatSQL('            END ') +

        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                COMMIT TRANSACTION ') +
        dbo.GTSFormatSQL('        END TRY ') +
        dbo.GTSFormatSQL('        BEGIN CATCH ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                OR XACT_STATE() = -1 /*un-committable transaction*/ ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION LocalTran ') +
        dbo.GTSFormatSQL('            IF @ResultCode = 0 ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 5 ') +
        dbo.GTSFormatSQL('            RETURN (ERROR_NUMBER()) ') +
        dbo.GTSFormatSQL('        END CATCH ') +
        dbo.GTSFormatSQL('    END ')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_AdjustCapacityHold due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_AdjustCapacityHold created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created

    Print N'Creating stored procedure GTS_SP_RM_EventSaleLimitOffSaleRollover...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_EventSaleLimitOffSaleRollover') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_EventSaleLimitOffSaleRollover

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_EventSaleLimitOffSaleRollover]') +
        dbo.GTSFormatSQL('    @EventID int,') +
        dbo.GTSFormatSQL('    @SalesChannelID int,') +
        dbo.GTSFormatSQL('    @Recurse bit,') +
        dbo.GTSFormatSQL('    @NowDateTime DateTime,') +
        dbo.GTSFormatSQL('    @LastUpdate DateTime,') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20),') +
        dbo.GTSFormatSQL('    @ResultCode int OUTPUT,') +
        dbo.GTSFormatSQL('    @RecurseIncludeParent int = 0') +
        dbo.GTSFormatSQL('    AS BEGIN') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    DECLARE @CapacityUnit int') +
        dbo.GTSFormatSQL('    DECLARE @CapacityLimitMode int') +
        dbo.GTSFormatSQL('    DECLARE @EventSaleLimitID int') +
        dbo.GTSFormatSQL('    DECLARE @OffSaleDateTime DateTime') +
        dbo.GTSFormatSQL('    DECLARE @ParentSalesChannelID int') +
        dbo.GTSFormatSQL('    DECLARE @ParentOffSaleDateTime DateTime') +
        dbo.GTSFormatSQL('    DECLARE @ParentRollOverEventSaleLimitID int') +
        dbo.GTSFormatSQL('    DECLARE @RecurseResultCode int') +
        dbo.GTSFormatSQL('    DECLARE @RolloverSalesChannelID int') +
        dbo.GTSFormatSQL('    DECLARE @RowsAffected int') +
        dbo.GTSFormatSQL('    DECLARE @StartTranCount int') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SET @ResultCode = 0') +
        dbo.GTSFormatSQL('    SET @RowsAffected = 0') +
        dbo.GTSFormatSQL('    SELECT @StartTranCount = @@TRANCOUNT') +
        dbo.GTSFormatSQL('    BEGIN TRY') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0') +
        dbo.GTSFormatSQL('            BEGIN TRANSACTION') +
        dbo.GTSFormatSQL('        ELSE') +
        dbo.GTSFormatSQL('            SAVE TRANSACTION LocalTran') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Get the event and rollover details for the Event Sale Limit') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            @CapacityLimitMode = E.SalesChannelCapacityLimitMode,') +
        dbo.GTSFormatSQL('            @CapacityUnit = L.CapacityUnit,') +
        dbo.GTSFormatSQL('            @EventSaleLimitID = L.EventSaleLimitID,') +
        dbo.GTSFormatSQL('            @OffSaleDateTime = L.OffSale,') +
        dbo.GTSFormatSQL('            @ParentSalesChannelID = PL.SalesChannelID,') +
        dbo.GTSFormatSQL('            @ParentOffSaleDateTime = PL.OffSale,') +
        dbo.GTSFormatSQL('            @ParentRollOverEventSaleLimitID = PL.OffSaleRolloverEventSaleLimitID,') +
        dbo.GTSFormatSQL('            @RolloverSalesChannelID = ORL.SalesChannelID') +
        dbo.GTSFormatSQL('        FROM EventSaleLimits L') +
        dbo.GTSFormatSQL('        JOIN RMEvents E ON E.EventID = L.EventID') +
        dbo.GTSFormatSQL('        JOIN EventSaleLimits ORL ON ORL.EventSaleLimitID = L.OffSaleRolloverEventSaleLimitID') +
        dbo.GTSFormatSQL('        LEFT JOIN EventSaleLimits PL ON PL.EventSaleLimitID = L.ParentEventSaleLimitID') +
        dbo.GTSFormatSQL('        WHERE L.EventID = @EventID AND L.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Verify rollover is applicable') +
        dbo.GTSFormatSQL('        IF @OffSaleDateTime > @NowDateTime OR @CapacityLimitMode <> 1 /*Per Sales Channel*/ BEGIN') +
        dbo.GTSFormatSQL('            SET @ResultCode = 1 /*Not applicable*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        ELSE IF @RolloverSalesChannelID IS NULL BEGIN') +
        dbo.GTSFormatSQL('            SET @ResultCode = 1 /*Not applicable*/') +
        dbo.GTSFormatSQL('            -- Recurse parent rollover if required') +
        dbo.GTSFormatSQL('            IF @Recurse = 1 AND @RecurseIncludeParent = 1 AND @ParentSalesChannelID > 0 AND @ParentOffSaleDateTime <= @NowDateTime AND @ParentRollOverEventSaleLimitID > 0 BEGIN') +
        dbo.GTSFormatSQL('                EXEC [dbo].[GTS_SP_RM_EventSaleLimitOffSaleRollover]') +
        dbo.GTSFormatSQL('                    @EventID, @ParentSalesChannelID, @Recurse, @NowDateTime, @LastUpdate, @LastUpdatedBy, @RecurseResultCode OUTPUT, 0 /*RecurseParent*/') +
        dbo.GTSFormatSQL('                SET @ResultCode = CASE WHEN @RecurseResultCode = 99 /*Unknown Exception*/ THEN 999 /*Unknown Exception on recurse*/ ELSE @RecurseResultCode END') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        ELSE BEGIN') +
        dbo.GTSFormatSQL('            -- Get Sold/Pending quantity for the Sales Channel') +
        dbo.GTSFormatSQL('            DECLARE @CapacityLimit int') +
        dbo.GTSFormatSQL('            DECLARE @CapacityLimitMax int') +
        dbo.GTSFormatSQL('            DECLARE @HasLimit bit') +
        dbo.GTSFormatSQL('            DECLARE @OnSaleDateTime datetime') +
        dbo.GTSFormatSQL('            DECLARE @QuantitySoldOrPendingForEvent int') +
        dbo.GTSFormatSQL('            DECLARE @QuantitySoldOrPendingForSalesChannel int') +
        dbo.GTSFormatSQL('            DECLARE @ParentCapacityLimit int') +
        dbo.GTSFormatSQL('            DECLARE @ParentCapacityLimitMode int') +
        dbo.GTSFormatSQL('            DECLARE @QuantitySoldOrPendingForParent int') +
        dbo.GTSFormatSQL('            DECLARE @RolloverCapacity int') +
        dbo.GTSFormatSQL('            DECLARE @TotalCapacityForEvent int') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            EXEC [dbo].[GTS_SP_RM_GetSalesChannelCapacityLimitData]') +
        dbo.GTSFormatSQL('               @EventID') +
        dbo.GTSFormatSQL('              ,@SalesChannelID') +
        dbo.GTSFormatSQL('              ,@CapacityLimitMode OUTPUT') +
        dbo.GTSFormatSQL('              ,@HasLimit OUTPUT') +
        dbo.GTSFormatSQL('              ,@CapacityUnit OUTPUT') +
        dbo.GTSFormatSQL('              ,@CapacityLimit OUTPUT') +
        dbo.GTSFormatSQL('              ,@OnSaleDateTime OUTPUT') +
        dbo.GTSFormatSQL('              ,@OffSaleDateTime OUTPUT') +
        dbo.GTSFormatSQL('              ,@QuantitySoldOrPendingForEvent OUTPUT') +
        dbo.GTSFormatSQL('              ,@QuantitySoldOrPendingForSalesChannel OUTPUT') +
        dbo.GTSFormatSQL('              ,@TotalCapacityForEvent OUTPUT') +
        dbo.GTSFormatSQL('              ,@ParentCapacityLimitMode OUTPUT') +
        dbo.GTSFormatSQL('              ,@ParentCapacityLimit OUTPUT') +
        dbo.GTSFormatSQL('              ,@QuantitySoldOrPendingForParent OUTPUT') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            IF @ParentCapacityLimitMode = 1 /*IS_PARENT*/') +
        dbo.GTSFormatSQL('                SET @QuantitySoldOrPendingForSalesChannel = @QuantitySoldOrPendingForParent') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Calculate the capacity to rollover') +
        dbo.GTSFormatSQL('            IF @CapacityUnit = 0 /*PERCENTAGE_CAPACITY_UNIT*/ BEGIN') +
        dbo.GTSFormatSQL('                DECLARE @TotalCapacity INT = CASE WHEN @ParentSalesChannelID > 0 THEN ROUND((@ParentCapacityLimit * @TotalCapacityForEvent) / 100.0, 0, 0) ELSE @TotalCapacityForEvent END') +
        dbo.GTSFormatSQL('                SET @CapacityLimitMax = 100') +
        dbo.GTSFormatSQL('                SET @RolloverCapacity = CAST(ROUND(((@CapacityLimit * @TotalCapacity) / 100.0) - @QuantitySoldOrPendingForSalesChannel, 0, 0) / @TotalCapacity * 100 AS int)') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            ELSE BEGIN /*QUANTITY_CAPACITY_UNIT*/') +
        dbo.GTSFormatSQL('                SET @CapacityLimitMax = CASE WHEN @ParentSalesChannelID > 0 THEN @ParentCapacityLimit ELSE @TotalCapacityForEvent END') +
        dbo.GTSFormatSQL('                SET @RolloverCapacity = @CapacityLimit - @QuantitySoldOrPendingForSalesChannel') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Rollover the capacity') +
        dbo.GTSFormatSQL('            IF @RolloverCapacity <= 0 BEGIN') +
        dbo.GTSFormatSQL('                SET @ResultCode = 2 /*No Change*/') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            ELSE BEGIN') +
        dbo.GTSFormatSQL('                -- Decrease source limit') +
        dbo.GTSFormatSQL('                UPDATE EventSaleLimits') +
        dbo.GTSFormatSQL('                    SET Capacity = CASE WHEN Capacity - @RolloverCapacity > 0 THEN Capacity - @RolloverCapacity ELSE 0 END,') +
        dbo.GTSFormatSQL('                        RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                    WHERE EventID = @EventID AND SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('                -- Increase rollover limit') +
        dbo.GTSFormatSQL('                UPDATE EventSaleLimits') +
        dbo.GTSFormatSQL('                    SET Capacity = CASE WHEN Capacity + @RolloverCapacity < @CapacityLimitMax THEN Capacity + @RolloverCapacity ELSE @CapacityLimitMax END,') +
        dbo.GTSFormatSQL('                        RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                    WHERE EventID = @EventID AND SalesChannelID = @RolloverSalesChannelID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('                -- Decrease all sub-limits whose quantity capacity is greater than the parent''s capacity') +
        dbo.GTSFormatSQL('                IF @ParentCapacityLimitMode = 1 /*IS_PARENT*/ AND @CapacityUnit = 1 /*QUANTITY_CAPACITY_UNIT*/ BEGIN') +
        dbo.GTSFormatSQL('                    DECLARE @SubLimitLimitMax int = @CapacityLimit - @RolloverCapacity') +
        dbo.GTSFormatSQL('                    UPDATE EventSaleLimits') +
        dbo.GTSFormatSQL('                        SET Capacity = @SubLimitLimitMax,') +
        dbo.GTSFormatSQL('                            RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                        WHERE EventID = @EventID AND ParentEventSaleLimitID = @EventSaleLimitID AND Capacity > @SubLimitLimitMax') +
        dbo.GTSFormatSQL('                    END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('                SET @ResultCode = 0 /*Success*/') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('                -- Recurse rollover if required') +
        dbo.GTSFormatSQL('                IF @Recurse = 1 BEGIN') +
        dbo.GTSFormatSQL('                    EXEC [dbo].[GTS_SP_RM_EventSaleLimitOffSaleRollover]') +
        dbo.GTSFormatSQL('                        @EventID, @RolloverSalesChannelID, @Recurse, @NowDateTime, @LastUpdate, @LastUpdatedBy, @RecurseResultCode OUTPUT, 0 /*RecurseParent*/') +
        dbo.GTSFormatSQL('                    IF @RecurseResultCode = 99 /*Unknown Exception*/') +
        dbo.GTSFormatSQL('                        SET @ResultCode = 999 /*Unknown Exception on recurse*/') +
        dbo.GTSFormatSQL('                    END') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Recurse parent rollover if required') +
        dbo.GTSFormatSQL('            IF @Recurse = 1 AND @RecurseIncludeParent = 1 AND @ParentSalesChannelID > 0 AND @ParentOffSaleDateTime <= @NowDateTime AND @ParentRollOverEventSaleLimitID > 0 BEGIN') +
        dbo.GTSFormatSQL('                EXEC [dbo].[GTS_SP_RM_EventSaleLimitOffSaleRollover]') +
        dbo.GTSFormatSQL('                    @EventID, @ParentSalesChannelID, @Recurse, @NowDateTime, @LastUpdate, @LastUpdatedBy, @RecurseResultCode OUTPUT, 0 /*RecurseParent*/') +
        dbo.GTSFormatSQL('                IF @RecurseResultCode = 99 /*Unknown Exception*/') +
        dbo.GTSFormatSQL('                    SET @ResultCode = 999 /*Unknown Exception on recurse*/') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0') +
        dbo.GTSFormatSQL('            COMMIT TRANSACTION') +
        dbo.GTSFormatSQL('    END TRY') +
        dbo.GTSFormatSQL('    BEGIN CATCH') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0 OR XACT_STATE() = -1 /*un-committable transaction*/') +
        dbo.GTSFormatSQL('            ROLLBACK TRANSACTION') +
        dbo.GTSFormatSQL('        ELSE') +
        dbo.GTSFormatSQL('            ROLLBACK TRANSACTION LocalTran') +
        dbo.GTSFormatSQL('        IF @ResultCode = 0') +
        dbo.GTSFormatSQL('            SET @ResultCode = 99 /*Unknown Exception*/') +
        dbo.GTSFormatSQL('        SELECT ERROR_MESSAGE()') +
        dbo.GTSFormatSQL('        RETURN(ERROR_NUMBER())') +
        dbo.GTSFormatSQL('    END CATCH') +
        dbo.GTSFormatSQL('END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_EventSaleLimitOffSaleRollover due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_EventSaleLimitOffSaleRollover created successfully.'

    Print N'Creating stored procedure GTS_SP_RM_Update_RMCapacity...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_Update_RMCapacity') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_Update_RMCapacity

     SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_Update_RMCapacity] ') +
        dbo.GTSFormatSQL('    @RMFunction Int, -- No longer required but included for mixed mode compatibility. Must be 2. ') +
        dbo.GTSFormatSQL('    @EventID Int, ') +
        dbo.GTSFormatSQL('    @ResourceID Int, ') +
        dbo.GTSFormatSQL('    @Qty Int, ') +
        dbo.GTSFormatSQL('    @CapacityType Int, ') +
        dbo.GTSFormatSQL('    @CapacityID Int, ') +
        dbo.GTSFormatSQL('    @LastUpdate DateTime, ') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20), ') +
        dbo.GTSFormatSQL('    @SalesChannelID Int = 0 ') +
        dbo.GTSFormatSQL('    AS BEGIN ') +
        dbo.GTSFormatSQL('        SET NOCOUNT ON; /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */ ') +
        dbo.GTSFormatSQL('        Declare @RowsAffected int; ') +
        dbo.GTSFormatSQL('        Declare @StartTranCount Int; ') +
        dbo.GTSFormatSQL('        Declare @SalesChannelCapacityLimitMode Int; ') +
        dbo.GTSFormatSQL('        Declare @UpdatedCapacityID Int; ') +

        dbo.GTSFormatSQL('        SET @RowsAffected = 0; ') +

        dbo.GTSFormatSQL('        SELECT @StartTranCount = @@TRANCOUNT; ') +

        dbo.GTSFormatSQL('        BEGIN TRY ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                BEGIN TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                SAVE TRANSACTION LocalTran; ') +

        dbo.GTSFormatSQL('             IF @RMFunction <> 2 BEGIN') +
        dbo.GTSFormatSQL('                 RAISERROR (''Legacy RMFunction not supported.'', 16, 1) ') +
        dbo.GTSFormatSQL('                 END') +

        dbo.GTSFormatSQL('            /* Get the SalesChannelCapacityLimitMode from the event */ ') +
        dbo.GTSFormatSQL('            SELECT @SalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode ') +
        dbo.GTSFormatSQL('            FROM RMEvents ') +
        dbo.GTSFormatSQL('            WHERE EventID = @EventID ') +

        dbo.GTSFormatSQL('            /* Update the RMCapacity record to move committed capacity from Hold to Sold */ ') +
        dbo.GTSFormatSQL('            UPDATE R ') +
        dbo.GTSFormatSQL('                SET Sold = Sold + @Qty, ') +
        dbo.GTSFormatSQL('                    QuantityOnHold = QuantityOnHold - @Qty, ') +
        dbo.GTSFormatSQL('                    RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy, ') +
        dbo.GTSFormatSQL('                    @UpdatedCapacityID = CapacityID ') +
        dbo.GTSFormatSQL('                -- this hint to ensures data is always accessed in order and locks are held for duration of transaction to prevent deadlocks ') +
        dbo.GTSFormatSQL('                FROM dbo.RMCapacity R WITH(INDEX (IXRMCapacityEventIDResourceID), HOLDLOCK) ') +
        dbo.GTSFormatSQL('                WHERE EventID = @EventID and ResourceID = @ResourceID and ') +
        dbo.GTSFormatSQL('                    (((@CapacityID = 0) and ((CapacityType = @CapacityType) or (CapacityType is NULL))) or CapacityID = @CapacityID) and ') +
        dbo.GTSFormatSQL('                    (QuantityOnHold >= @Qty) ') +
        dbo.GTSFormatSQL('            OPTION (RECOMPILE); ') +
        dbo.GTSFormatSQL('            SELECT @RowsAffected = @@ROWCOUNT; ') +

        dbo.GTSFormatSQL('            /* Update the RMSalesChannelCapacity record to move committed capacity from Hold to Sold */ ') +
        dbo.GTSFormatSQL('            IF (@RowsAffected > 0) AND (@SalesChannelCapacityLimitMode > 0) BEGIN ' ) +
        dbo.GTSFormatSQL('                UPDATE R ') +
        dbo.GTSFormatSQL('                    SET Sold = Sold + @Qty, ') +
        dbo.GTSFormatSQL('                        QuantityOnHold = QuantityOnHold - @Qty, ') +
        dbo.GTSFormatSQL('                        RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                    FROM dbo.RMSalesChannelCapacity R WITH(INDEX (IXCapacityIDSalesChannelID), HOLDLOCK) ') +
        dbo.GTSFormatSQL('                    WHERE (CapacityID = @UpdatedCapacityID) AND (SalesChannelID = @SalesChannelID) and ') +
        dbo.GTSFormatSQL('                    (QuantityOnHold >= @Qty) ') +
        dbo.GTSFormatSQL('                END; ') +
        dbo.GTSFormatSQL('             IF @StartTranCount = 0 COMMIT TRANSACTION; ') +
        dbo.GTSFormatSQL('             RETURN(@RowsAffected); ') +
        dbo.GTSFormatSQL('             END TRY ') +
        dbo.GTSFormatSQL('         BEGIN CATCH ') +
        dbo.GTSFormatSQL('             IF @StartTranCount = 0 OR XACT_STATE() = -1 /*un-committable transaction*/ ') +
        dbo.GTSFormatSQL('                 ROLLBACK TRANSACTION ') +
        dbo.GTSFormatSQL('             ELSE ') +
        dbo.GTSFormatSQL('                 ROLLBACK TRANSACTION LocalTran; ') +
        dbo.GTSFormatSQL('             RETURN(@RowsAffected); ') +
        dbo.GTSFormatSQL('             END CATCH; ') +
        dbo.GTSFormatSQL('         END;')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_Update_RMCapacity due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_Update_RMCapacity created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created

    Print N'Creating stored procedure GTS_SP_RM_HoldTickets...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_HoldTickets') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_HoldTickets

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_HoldTickets] ') +
        dbo.GTSFormatSQL('    @EventID Int, ') +
        dbo.GTSFormatSQL('    @ResourceID Int, ') +
        dbo.GTSFormatSQL('    @Qty Int, ') +
        dbo.GTSFormatSQL('    @NodeNo Int, ') +
        dbo.GTSFormatSQL('    @GroupIDType Int, ') +
        dbo.GTSFormatSQL('    @GroupID Int, ') +
        dbo.GTSFormatSQL('    @CapacityType Int, ') +
        dbo.GTSFormatSQL('    @CapacityID Int, ') +
        dbo.GTSFormatSQL('    @LastUpdate DateTime, ') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20), ') +
        dbo.GTSFormatSQL('    @NewUniqueHoldID Int, ') +
        dbo.GTSFormatSQL('    @ExistingUniqueHoldID Int, ') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT, ') +
        dbo.GTSFormatSQL('    @IgnoreCapacity bit = 0, ') +
        dbo.GTSFormatSQL('    @SalesChannelID Int = 0 ') +

        dbo.GTSFormatSQL('    AS ') +
        dbo.GTSFormatSQL('    BEGIN ') +
        dbo.GTSFormatSQL('        SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */ ') +

        dbo.GTSFormatSQL('        Declare @DefaultLockMode nvarchar(32) ') +
        dbo.GTSFormatSQL('        Declare @LockName nvarchar(255) ') +
        dbo.GTSFormatSQL('        Declare @LockResult Int ') +
        dbo.GTSFormatSQL('        Declare @RowsAffected Int ') +
        dbo.GTSFormatSQL('        Declare @StartTranCount Int ') +
        dbo.GTSFormatSQL('        Declare @SalesChannelCapacityLimitMode Int ') +
        dbo.GTSFormatSQL('        Declare @RMCapacityHoldUID Int ') +

        dbo.GTSFormatSQL('        /* Set default values for lock mode and database principal variables */ ') +
        dbo.GTSFormatSQL('        SET @DefaultLockMode = ''Exclusive'' ') +
        dbo.GTSFormatSQL('        SET @LockName = ''HoldTicketsLockEventID'' + CAST(@EventID AS varchar(15)) + ''ResourceID'' + CAST(@ResourceID AS varchar(15)) ') +

        dbo.GTSFormatSQL('        SET @ResultCode = 0 ') +

        dbo.GTSFormatSQL('        SELECT @StartTranCount = @@TRANCOUNT ') +

        dbo.GTSFormatSQL('        BEGIN TRY ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                BEGIN TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                SAVE TRANSACTION LocalTran ') +

        dbo.GTSFormatSQL('            EXEC @LockResult = sp_getapplock @Resource = @LockName, @LockMode = ''Exclusive''  /* TO DO: TimeOut can be passed in as a parameter */ ') +
        dbo.GTSFormatSQL('            /* STOP if unable to acquire the application lock in the first place */ ') +
        dbo.GTSFormatSQL('            IF @LockResult < 0 BEGIN ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('                RAISERROR (''Unable to acquire application lock'', 16, 1) ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            /* Get the SalesChannelCapacityLimitMode from the event */ ') +
        dbo.GTSFormatSQL('            SELECT @SalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode ') +
        dbo.GTSFormatSQL('            FROM RMEvents ') +
        dbo.GTSFormatSQL('            WHERE EventID = @EventID ') +

        dbo.GTSFormatSQL('            /* First, attempt to update the RMCapacity table */ ') +
        dbo.GTSFormatSQL('            UPDATE R ') +
        dbo.GTSFormatSQL('            SET Available = ((Available - @Qty) + ABS(Available - @Qty))/2, ') +
        dbo.GTSFormatSQL('            QuantityOnHold = QuantityOnHold + @Qty, ') +
        dbo.GTSFormatSQL('            RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('            FROM RMCapacity R WITH(INDEX (IXRMCapacityEventIDResourceID), HOLDLOCK) ') +
        dbo.GTSFormatSQL('            WHERE (EventID = @EventID) and (ResourceID = @ResourceID) and (CapacityID = @CapacityID) and ((@IgnoreCapacity = 1) OR (@Qty <= Available)) ') +
        dbo.GTSFormatSQL('            SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('            IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 2 ') +
        dbo.GTSFormatSQL('                RAISERROR (''Unable to update RMCapacity table'', 16, 1) ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            /* Attempt to update the RMSalesChannelCapacity table */ ') +
        dbo.GTSFormatSQL('            IF @SalesChannelCapacityLimitMode > 0 BEGIN ') +
        dbo.GTSFormatSQL('                UPDATE RMSalesChannelCapacity ') +
        dbo.GTSFormatSQL('                SET QuantityOnHold = QuantityOnHold + @Qty, ') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                WHERE (CapacityID = @CapacityID) AND (SalesChannelID = @SalesChannelID)  ') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('                /* There was no entry to update so add a new entry */ ') +
        dbo.GTSFormatSQL('                IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                    INSERT INTO RMSalesChannelCapacity (CapacityID, SalesChannelID, Sold, QuantityOnHold, RecordVersion, LastUpdate, LastUpdatedBy) ') +
        dbo.GTSFormatSQL('                    VALUES (@CapacityID, @SalesChannelID, 0, @Qty, 1, @LastUpdate, @LastUpdatedBy) ') +
        dbo.GTSFormatSQL('                    SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('                    IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                        SET @ResultCode = 5 ') +
        dbo.GTSFormatSQL('                        RAISERROR (''Unable to update RMSalesChannelCapacity table'', 16, 1) ') +
        dbo.GTSFormatSQL('                        END ') +
        dbo.GTSFormatSQL('                    END ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            /* Next, attempt to update the RMCapacityHold table */ ') +
        dbo.GTSFormatSQL('            /* Check if a capacity hold record already exists */ ') +
        dbo.GTSFormatSQL('            IF @ExistingUniqueHoldID > 0 BEGIN ') +
        dbo.GTSFormatSQL('                /* Hold record exists in RMCapacityHold table, just update HoldQuantity */ ') +
        dbo.GTSFormatSQL('                UPDATE RMCapacityHold ') +
        dbo.GTSFormatSQL('                SET HoldQuantity = HoldQuantity + @Qty, DateTimeHeld = @LastUpdate, ') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy, ') +
        dbo.GTSFormatSQL('                @RMCapacityHoldUID = RMCapacityHoldUID ') +
        dbo.GTSFormatSQL('                WHERE RMCapacityHoldUID = @ExistingUniqueHoldID ') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT ') +
        dbo.GTSFormatSQL('                END ') +
        dbo.GTSFormatSQL('            ELSE BEGIN ') +
        dbo.GTSFormatSQL('                /* Hold record does not exist in RMCapacityHold table, insert it */ ') +
        dbo.GTSFormatSQL('                INSERT INTO RMCapacityHold (EventID, Node, HoldQuantity, ResourceID, DateTimeHeld, GroupIDType, GroupID, CapacityID, RecordVersion, LastUpdate, LastUpdatedBy) ') +
        dbo.GTSFormatSQL('                VALUES (@EventID, @NodeNo, @Qty, @ResourceID, @LastUpdate, @GroupIDType, @GroupID, @CapacityID, 1, @LastUpdate, @LastUpdatedBy) ') +
        dbo.GTSFormatSQL('                SET @RMCapacityHoldUID = @@IDENTITY ') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('                IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                    SET @ResultCode = 3 ') +
        dbo.GTSFormatSQL('                    RAISERROR (''Failed to update/insert RMCapacityHold table'', 16, 1) ') +
        dbo.GTSFormatSQL('                    END ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            /* Attempt to update the SalesChannelCapacityLimitHold table */ ') +
        dbo.GTSFormatSQL('            IF @SalesChannelCapacityLimitMode > 0 BEGIN ') +
        dbo.GTSFormatSQL('                UPDATE RMSalesChannelCapacityHold ') +
        dbo.GTSFormatSQL('                SET HoldQuantity = HoldQuantity + @Qty, ') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                WHERE (RMCapacityHoldUID = @RMCapacityHoldUID) AND (SalesChannelID = @SalesChannelID)  ') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('                /* There was no entry to update so add a new entry */ ') +
        dbo.GTSFormatSQL('                IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                    INSERT INTO RMSalesChannelCapacityHold (RMCapacityHoldUID, SalesChannelID, HoldQuantity, RecordVersion, LastUpdate, LastUpdatedBy) ') +
        dbo.GTSFormatSQL('                    VALUES (@RMCapacityHoldUID, @SalesChannelID, @Qty, 1, @LastUpdate, @LastUpdatedBy) ') +
        dbo.GTSFormatSQL('                    SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('                    IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                        SET @ResultCode = 6 ') +
        dbo.GTSFormatSQL('                        RAISERROR (''Unable to update/insert RMSalesChannelCapacityHold table'', 16, 1) ') +
        dbo.GTSFormatSQL('                        END ') +
        dbo.GTSFormatSQL('                    END ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            EXEC @LockResult = sp_releaseapplock @Resource = @LockName ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 COMMIT TRANSACTION ') +
        dbo.GTSFormatSQL('            END TRY ') +
        dbo.GTSFormatSQL('        BEGIN CATCH ') +
        dbo.GTSFormatSQL('            IF @ResultCode <> 1 EXEC @LockResult = sp_releaseapplock @Resource = @LockName ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION LocalTran ') +
        dbo.GTSFormatSQL('            IF @ResultCode = 0 SET @ResultCode = 4 ') +
        dbo.GTSFormatSQL('            RETURN(ERROR_NUMBER()) ') +
        dbo.GTSFormatSQL('            END CATCH ') +
        dbo.GTSFormatSQL('        END ')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_HoldTickets due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_HoldTickets created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created

    Print N'Creating stored procedure GTS_SP_RM_EventCapacityDataByResource...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_EventCapacityDataByResource') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_EventCapacityDataByResource

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_EventCapacityDataByResource]') +
        dbo.GTSFormatSQL('    @EventID INT,') +
        dbo.GTSFormatSQL('    @ResourceID INT,') +
        dbo.GTSFormatSQL('    @RSEventSeatMapID INT,') +
        dbo.GTSFormatSQL('    @PLU NVARCHAR(20),') +
        dbo.GTSFormatSQL('    @Available INT OUTPUT,') +
        dbo.GTSFormatSQL('    @AvailableBucketID INT OUTPUT,') +
        dbo.GTSFormatSQL('    @Sold INT OUTPUT,') +
        dbo.GTSFormatSQL('    @Pending INT OUTPUT,') +
        dbo.GTSFormatSQL('    @TotalCapacity INT OUTPUT,') +
        dbo.GTSFormatSQL('    @Held INT OUTPUT,') +
        dbo.GTSFormatSQL('    @Releasable INT OUTPUT,') +
        dbo.GTSFormatSQL('    @IsSequencedEvent BIT OUTPUT,') +
        dbo.GTSFormatSQL('    @EventHasHolds BIT OUTPUT,') +
        dbo.GTSFormatSQL('    @MaxAvailableHoldBlockForPLU INT OUTPUT,') +
        dbo.GTSFormatSQL('    @MaxAvailableHoldBlockForPLUBucketID INT OUTPUT') +
        dbo.GTSFormatSQL('    AS') +
        dbo.GTSFormatSQL('    BEGIN') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON') +
        dbo.GTSFormatSQL('    SET @Available = 0') +
        dbo.GTSFormatSQL('    SET @Sold = 0') +
        dbo.GTSFormatSQL('    SET @Pending = 0') +
        dbo.GTSFormatSQL('    SET @TotalCapacity = 0') +
        dbo.GTSFormatSQL('    SET @Held = 0') +
        dbo.GTSFormatSQL('    SET @Releasable = 0') +
        dbo.GTSFormatSQL('    SET @IsSequencedEvent = 0') +
        dbo.GTSFormatSQL('    SET @MaxAvailableHoldBlockForPLU = 0') +
        dbo.GTSFormatSQL('    SET @EventHasHolds = 0') +
        dbo.GTSFormatSQL('    SET @AvailableBucketID = NULL') +
        dbo.GTSFormatSQL('    SET @MaxAvailableHoldBlockForPLUBucketID = NULL') +
        dbo.GTSFormatSQL('    IF @RSEventSeatMapID > 0 BEGIN') +
        dbo.GTSFormatSQL('        SELECT @Available = Available, @Sold = Sold, @Pending = Reserved, @TotalCapacity = Available + Sold + Reserved FROM dbo.RSEventSeatMaps WHERE RSEventSeatMapID = @RSEventSeatMapID') +
        dbo.GTSFormatSQL('        RETURN 0') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('    ELSE BEGIN') +
        dbo.GTSFormatSQL('        DECLARE @FoundResource BIT = 0') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        DECLARE @TempCapacityList TABLE (') +
        dbo.GTSFormatSQL('            CapacityID INT,') +
        dbo.GTSFormatSQL('            ResourceID INT,') +
        dbo.GTSFormatSQL('            AncestorID INT,') +
        dbo.GTSFormatSQL('            CapacityType INT,') +
        dbo.GTSFormatSQL('            HoldGroupID INT,') +
        dbo.GTSFormatSQL('            Available INT,') +
        dbo.GTSFormatSQL('            Sold INT,') +
        dbo.GTSFormatSQL('            QuantityOnHold INT,') +
        dbo.GTSFormatSQL('            TotalCapacity INT,') +
        dbo.GTSFormatSQL('            ReleaseState INT,') +
        dbo.GTSFormatSQL('            ReleasedCapacity INT,') +
        dbo.GTSFormatSQL('            Sequence INT,') +
        dbo.GTSFormatSQL('            HasHoldForPLU BIT,') +
        dbo.GTSFormatSQL('            INDEX IXSequenceCapacityID (Sequence, CapacityID)') +
        dbo.GTSFormatSQL('        )') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Gather the capacity data for the event') +
        dbo.GTSFormatSQL('        INSERT INTO @TempCapacityList') +
        dbo.GTSFormatSQL('            SELECT C.CapacityID, C.ResourceID, ISNULL(RMR.AncestorID, 0) AS AncestorID, C.CapacityType, C.HoldGroupID, C.Available, C.Sold, C.QuantityOnHold,') +
        dbo.GTSFormatSQL('                   C.TotalCapacity, C.ReleaseState, C.ReleasedCapacity, C.Sequence,') +
        dbo.GTSFormatSQL('                   CAST(CASE WHEN ISNULL(@PLU, '''') <> '''' AND ISNULL(c.HoldGroupID, 0) > 0 AND EXISTS(') +
        dbo.GTSFormatSQL('                       SELECT TOP 1 PLU FROM HoldDetails WHERE DetailType = 1 AND AuxID = c.HoldGroupID AND PLU = @PLU') +
        dbo.GTSFormatSQL('                       UNION') +
        dbo.GTSFormatSQL('                       SELECT TOP 1 IGD.PLU FROM HoldDetails HD JOIN ItemGroups IG ON IG.ItemGroupID = HD.ItemGroupID JOIN ItemGroupDetails IGD ON IGD.ItemGroupID = IG.ItemGroupID AND IGD.PLU = @PLU WHERE HD.DetailType = 1 AND HD.AuxID = c.HoldGroupID)') +
        dbo.GTSFormatSQL('                   THEN 1 ELSE 0 END AS BIT) AS HasHoldForPLU') +
        dbo.GTSFormatSQL('            FROM RMCapacity C WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            LEFT JOIN RMResources RMR ON C.ResourceID = RMR.ResourceID') +
        dbo.GTSFormatSQL('            WHERE C.EventID = @EventID') +
        dbo.GTSFormatSQL('            ORDER BY C.Sequence') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Calculate @IsSequencedEvent') +
        dbo.GTSFormatSQL('        SELECT @IsSequencedEvent = CASE WHEN COUNT(*) > 1 AND SUM(CASE WHEN Sequence > 0 THEN 1 ELSE 0 END) > 0 THEN 1 ELSE 0 END FROM @TempCapacityList') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Calculate aggregated values') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            @Available = SUM(CASE WHEN CapacityType = 0 /*GENERAL_CAPACITY*/') +
        dbo.GTSFormatSQL('                                  AND ((@IsSequencedEvent = 1) OR (@ResourceID = 0) OR (@ResourceID = ResourceID) OR (@ResourceID = AncestorID))') +
        dbo.GTSFormatSQL('                                  THEN Available ELSE 0 END),') +
        dbo.GTSFormatSQL('            @Held = SUM(CASE WHEN CapacityType <> 0') +
        dbo.GTSFormatSQL('                             AND ((@IsSequencedEvent = 1) OR (@ResourceID = 0) OR (@ResourceID = ResourceID) OR (@ResourceID = AncestorID))') +
        dbo.GTSFormatSQL('                             THEN Available ELSE 0 END),') +
        dbo.GTSFormatSQL('            @Releasable = SUM(CASE WHEN CapacityType <> 0 AND ReleaseState = 1 /*IS_RELEASABLE*/') +
        dbo.GTSFormatSQL('                                   AND ((@IsSequencedEvent = 1) OR (@ResourceID = 0) OR (@ResourceID = ResourceID) OR (@ResourceID = AncestorID))') +
        dbo.GTSFormatSQL('                                   THEN Available ELSE 0 END),') +
        dbo.GTSFormatSQL('            @Sold = SUM(CASE WHEN ((@IsSequencedEvent = 1) OR (@ResourceID = 0) OR (@ResourceID = ResourceID) OR (@ResourceID = AncestorID))') +
        dbo.GTSFormatSQL('                             THEN Sold ELSE 0 END),') +
        dbo.GTSFormatSQL('            @Pending = SUM(CASE WHEN ((@IsSequencedEvent = 1) OR (@ResourceID = 0) OR (@ResourceID = ResourceID) OR (@ResourceID = AncestorID))') +
        dbo.GTSFormatSQL('                                THEN QuantityOnHold ELSE 0 END),') +
        dbo.GTSFormatSQL('            @TotalCapacity = SUM(CASE WHEN ((@IsSequencedEvent = 1) OR (@ResourceID = 0) OR (@ResourceID = ResourceID) OR (@ResourceID = AncestorID))') +
        dbo.GTSFormatSQL('                                      THEN CASE WHEN ReleaseState = 2 /*WAS_RELEASED*/ THEN (TotalCapacity - ReleasedCapacity) ELSE TotalCapacity END') +
        dbo.GTSFormatSQL('                                      ELSE 0 END),') +
        dbo.GTSFormatSQL('            @FoundResource = CASE WHEN SUM(CASE WHEN (@ResourceID <> 0) AND ((@ResourceID = ResourceID) OR (@ResourceID = AncestorID)) THEN 1 ELSE 0 END) > 0') +
        dbo.GTSFormatSQL('                                  THEN 1 ELSE 0 END,') +
        dbo.GTSFormatSQL('            @EventHasHolds = CASE WHEN SUM(CASE WHEN HoldGroupID > 0 THEN 1 ELSE 0 END) > 0') +
        dbo.GTSFormatSQL('                                  THEN 1 ELSE 0 END') +
        dbo.GTSFormatSQL('        FROM @TempCapacityList') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Get the first available bucket ID for general capacity') +
        dbo.GTSFormatSQL('        SELECT TOP 1 @AvailableBucketID = CapacityID') +
        dbo.GTSFormatSQL('        FROM @TempCapacityList') +
        dbo.GTSFormatSQL('        WHERE CapacityType = 0 /*GENERAL_CAPACITY*/') +
        dbo.GTSFormatSQL('            AND Available > 0') +
        dbo.GTSFormatSQL('            AND ((@IsSequencedEvent = 1) OR (@ResourceID = 0) OR (@ResourceID = ResourceID) OR (@ResourceID = AncestorID))') +
        dbo.GTSFormatSQL('        ORDER BY Sequence, CapacityID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Get the maximum available hold block for PLU') +
        dbo.GTSFormatSQL('        IF @PLU <> '''' BEGIN') +
        dbo.GTSFormatSQL('            SELECT TOP 1') +
        dbo.GTSFormatSQL('                @MaxAvailableHoldBlockForPLU = Available,') +
        dbo.GTSFormatSQL('                @MaxAvailableHoldBlockForPLUBucketID = CapacityID') +
        dbo.GTSFormatSQL('            FROM @TempCapacityList') +
        dbo.GTSFormatSQL('            WHERE HasHoldForPLU = 1') +
        dbo.GTSFormatSQL('                AND CapacityType <> 0') +
        dbo.GTSFormatSQL('                AND ((@IsSequencedEvent = 1) OR (@ResourceID = 0) OR (@ResourceID = ResourceID) OR (@ResourceID = AncestorID))') +
        dbo.GTSFormatSQL('            ORDER BY Available DESC, Sequence, CapacityID') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        RETURN CASE WHEN @ResourceID <> 0 AND @FoundResource = 0 THEN -1 ELSE 0 END') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('    END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_EventCapacityDataByResource due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_EventCapacityDataByResource created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created

    Print N'Creating stored procedure GTS_SP_RM_GetSalesChannelCapacityLimitData...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_GetSalesChannelCapacityLimitData') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_GetSalesChannelCapacityLimitData

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_GetSalesChannelCapacityLimitData]') +
        dbo.GTSFormatSQL('    @EventID Int,') +
        dbo.GTSFormatSQL('    @SalesChannelID Int,') +
        dbo.GTSFormatSQL('    @CapacityLimitMode Int OUTPUT,') +
        dbo.GTSFormatSQL('    @HasLimit Bit OUTPUT,') +
        dbo.GTSFormatSQL('    @CapacityUnit Int OUTPUT,') +
        dbo.GTSFormatSQL('    @CapacityLimit Int OUTPUT,') +
        dbo.GTSFormatSQL('    @OnSaleDateTime DateTime OUTPUT,') +
        dbo.GTSFormatSQL('    @OffSaleDateTime DateTime OUTPUT,') +
        dbo.GTSFormatSQL('    @QuantitySoldOrPendingForEvent Int OUTPUT,') +
        dbo.GTSFormatSQL('    @QuantitySoldOrPendingForSalesChannel Int OUTPUT,') +
        dbo.GTSFormatSQL('    @TotalCapacityForEvent Int OUTPUT,') +
        dbo.GTSFormatSQL('    @ParentCapacityLimitMode Int = 0 OUTPUT,') +
        dbo.GTSFormatSQL('    @ParentCapacityLimit Int = 0 OUTPUT,') +
        dbo.GTSFormatSQL('    @QuantitySoldOrPendingForParent Int = 0 OUTPUT') +
        dbo.GTSFormatSQL('    AS') +
        dbo.GTSFormatSQL('    BEGIN') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */') +
        dbo.GTSFormatSQL('    DECLARE') +
        dbo.GTSFormatSQL('        @EventSaleLimitID INT,') +
        dbo.GTSFormatSQL('        @ParentEventSaleLimitID INT,') +
        dbo.GTSFormatSQL('        @RSEventSeatMapID INT') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Retrieve sales channel limit information') +
        dbo.GTSFormatSQL('    SELECT') +
        dbo.GTSFormatSQL('        @EventSaleLimitID = ESL.EventSaleLimitID,') +
        dbo.GTSFormatSQL('        @CapacityLimitMode = E.SalesChannelCapacityLimitMode,') +
        dbo.GTSFormatSQL('        @CapacityUnit = ESL.CapacityUnit,') +
        dbo.GTSFormatSQL('        @CapacityLimit = ESL.Capacity,') +
        dbo.GTSFormatSQL('        @HasLimit = CASE WHEN ESL.EventSaleLimitID > 0 THEN 1 ELSE 0 END,') +
        dbo.GTSFormatSQL('        @RSEventSeatMapID = E.RSEventSeatMapID,') +
        dbo.GTSFormatSQL('        @OnSaleDateTime = ESL.OnSale,') +
        dbo.GTSFormatSQL('        @OffSaleDateTime = ESL.OffSale,') +
        dbo.GTSFormatSQL('        @ParentEventSaleLimitID = ESL.ParentEventSaleLimitID,') +
        dbo.GTSFormatSQL('        -- Calculate capacity data in the same query for RSEventSeatMapID > 0') +
        dbo.GTSFormatSQL('        @QuantitySoldOrPendingForEvent = CASE') +
        dbo.GTSFormatSQL('            WHEN E.RSEventSeatMapID > 0 THEN RS.Sold + RS.Reserved') +
        dbo.GTSFormatSQL('            ELSE NULL END,') +
        dbo.GTSFormatSQL('        @QuantitySoldOrPendingForSalesChannel = CASE') +
        dbo.GTSFormatSQL('            WHEN E.RSEventSeatMapID > 0 THEN 0') +
        dbo.GTSFormatSQL('            ELSE NULL END,') +
        dbo.GTSFormatSQL('        @TotalCapacityForEvent = CASE') +
        dbo.GTSFormatSQL('            WHEN E.RSEventSeatMapID > 0 THEN RS.Available + RS.Sold + RS.Reserved') +
        dbo.GTSFormatSQL('            ELSE NULL END') +
        dbo.GTSFormatSQL('    FROM dbo.RMEvents E') +
        dbo.GTSFormatSQL('    LEFT JOIN dbo.EventSaleLimits ESL ON E.EventID = ESL.EventID AND ESL.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('    LEFT JOIN dbo.RSEventSeatMaps RS ON E.RSEventSeatMapID = RS.RSEventSeatMapID AND E.RSEventSeatMapID > 0') +
        dbo.GTSFormatSQL('    WHERE E.EventID = @EventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Handle capacity data for non-RSEventSeatMap cases') +
        dbo.GTSFormatSQL('    IF @RSEventSeatMapID IS NULL OR @RSEventSeatMapID = 0 BEGIN') +
        dbo.GTSFormatSQL('        -- Gather capacity data for the event and sales channel') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            @QuantitySoldOrPendingForEvent = SUM(C.Sold + C.QuantityOnHold),') +
        dbo.GTSFormatSQL('            @QuantitySoldOrPendingForSalesChannel = ISNULL(SUM(ISNULL(SCC.Sold + SCC.QuantityOnHold, 0)), 0),') +
        dbo.GTSFormatSQL('            @TotalCapacityForEvent = SUM(CASE WHEN C.ReleaseState = 2 /*WAS_RELEASED*/ THEN C.TotalCapacity - C.ReleasedCapacity ELSE C.TotalCapacity END)') +
        dbo.GTSFormatSQL('        FROM RMCapacity C WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('        LEFT JOIN dbo.RMSalesChannelCapacity SCC ON SCC.CapacityID = C.CapacityID AND SCC.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('        WHERE C.EventID = @EventID') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Gather capacity data for Parent/Sub-limits if applicable') +
        dbo.GTSFormatSQL('    IF @HasLimit = 1 AND @CapacityLimitMode = 1 /*Per Sales Channel*/ AND (@ParentEventSaleLimitID > 0 OR EXISTS (SELECT 1 FROM EventSaleLimits WHERE EventID = @EventID AND ParentEventSaleLimitID = @EventSaleLimitID)) BEGIN') +
        dbo.GTSFormatSQL('        IF @ParentEventSaleLimitID = 0 BEGIN') +
        dbo.GTSFormatSQL('            SET @ParentEventSaleLimitID = @EventSaleLimitID') +
        dbo.GTSFormatSQL('            SET @ParentCapacityLimitMode = 1 /*IS_PARENT*/') +
        dbo.GTSFormatSQL('            SET @ParentCapacityLimit = @CapacityLimit') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        ELSE BEGIN') +
        dbo.GTSFormatSQL('            SELECT @ParentCapacityLimit = Capacity') +
        dbo.GTSFormatSQL('            FROM EventSaleLimits') +
        dbo.GTSFormatSQL('            WHERE EventSaleLimitID = @ParentEventSaleLimitID') +
        dbo.GTSFormatSQL('            SET @ParentCapacityLimitMode = 2 /*IS_SUBLIMIT*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Calculate quantity sold or pending for parent and sub-limits') +
        dbo.GTSFormatSQL('        SELECT @QuantitySoldOrPendingForParent = ISNULL(SUM(SCC.Sold + SCC.QuantityOnHold), 0)') +
        dbo.GTSFormatSQL('        FROM EventSaleLimits ESL WITH (INDEX(IXEventSaleLimitsEventIDSCID))') +
        dbo.GTSFormatSQL('        INNER JOIN RMCapacity C WITH (INDEX(IXRMCapacityEventIDResourceID)) ON C.EventID = ESL.EventID') +
        dbo.GTSFormatSQL('        INNER JOIN RMSalesChannelCapacity SCC ON SCC.CapacityID = C.CapacityID AND SCC.SalesChannelID = ESL.SalesChannelID') +
        dbo.GTSFormatSQL('        WHERE ESL.EventID = @EventID AND (ESL.EventSaleLimitID = @ParentEventSaleLimitID OR ESL.ParentEventSaleLimitID = @ParentEventSaleLimitID)') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('    ELSE BEGIN') +
        dbo.GTSFormatSQL('        SET @ParentCapacityLimitMode = 0 /*NONE*/') +
        dbo.GTSFormatSQL('        SET @ParentCapacityLimit = 0') +
        dbo.GTSFormatSQL('        SET @QuantitySoldOrPendingForParent = 0') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('    END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_GetSalesChannelCapacityLimitData due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_GetSalesChannelCapacityLimitData created successfully.'

    Print N'Creating stored procedure GTS_SP_RM_GetSalesPerSalesChannel...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_GetSalesPerSalesChannel') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_GetSalesPerSalesChannel

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_GetSalesPerSalesChannel] ') +
        dbo.GTSFormatSQL('    @EventID Int, ') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT ') +
        dbo.GTSFormatSQL('    AS ') +
        dbo.GTSFormatSQL('    BEGIN ') +
        dbo.GTSFormatSQL('        SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */ ') +
        dbo.GTSFormatSQL('        SET @ResultCode     =  0 ') +
        dbo.GTSFormatSQL('        BEGIN TRY ') +
        dbo.GTSFormatSQL('            /* Get tickets sold per sales channel for the given Event. */ ') +
        dbo.GTSFormatSQL('            /* Only applicable when configured for Capacity Limit Mode = Per Sales Channel. */ ') +
        dbo.GTSFormatSQL('            SELECT SalesChannelID, SUM(SCC.Sold) AS Count, SUM(SCC.QuantityOnHold) AS PendingCount ') +
        dbo.GTSFormatSQL('            FROM RMSalesChannelCapacity SCC INNER JOIN RMCapacity C ') +
        dbo.GTSFormatSQL('            ON SCC.CapacityID = C.CapacityID ') +
        dbo.GTSFormatSQL('            WHERE C.EventID = @EventID ') +
        dbo.GTSFormatSQL('            GROUP BY SalesChannelID ') +
        dbo.GTSFormatSQL('            ORDER BY SalesChannelID ') +
        dbo.GTSFormatSQL('            END TRY ') +
        dbo.GTSFormatSQL('        BEGIN CATCH ') +
        dbo.GTSFormatSQL('            SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('            RETURN(ERROR_NUMBER()) ') +
        dbo.GTSFormatSQL('            END CATCH ') +
        dbo.GTSFormatSQL('        END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_GetSalesPerSalesChannel due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_GetSalesPerSalesChannel created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created

    Print N'Creating stored procedure GTS_SP_RM_QueryEventDatesData...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_QueryEventDatesData') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_QueryEventDatesData

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_QueryEventDatesData]') +
        dbo.GTSFormatSQL('    @EventTypeID INT,') +
        dbo.GTSFormatSQL('    @StartDateFrom DATETIME,') +
        dbo.GTSFormatSQL('    @StartDateThru DATETIME,') +
        dbo.GTSFormatSQL('    @Quantity INT,') +
        dbo.GTSFormatSQL('    @SalesChannelID INT,') +
        dbo.GTSFormatSQL('    @PLU NVARCHAR(20),') +
        dbo.GTSFormatSQL('    @IgnoreAvailability BIT,') +
        dbo.GTSFormatSQL('    @ResourceID INT = 0,') +
        dbo.GTSFormatSQL('    @CurrentDateTime DATETIME = NULL') +
        dbo.GTSFormatSQL('    WITH RECOMPILE') +
        dbo.GTSFormatSQL('    AS') +
        dbo.GTSFormatSQL('    BEGIN') +
        dbo.GTSFormatSQL('    -- SP Version 20260410') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    IF @CurrentDateTime IS NULL SET @CurrentDateTime = GETDATE()') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    DECLARE @UseEventSaleLimits BIT = CASE WHEN ISNULL(@SalesChannelID, 0) > 0 THEN 1 ELSE 0 END') +
        dbo.GTSFormatSQL('    DECLARE @UseCapacityType    BIT = CASE WHEN ISNULL(@PLU, '''') = '''' THEN 1 ELSE 0 END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 1: Materialize filtered events; all downstream phases join by PK seek.') +
        dbo.GTSFormatSQL('    CREATE TABLE #FilteredEvents (EventID INT NOT NULL PRIMARY KEY CLUSTERED)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    INSERT INTO #FilteredEvents (EventID)') +
        dbo.GTSFormatSQL('    SELECT DISTINCT e.EventID') +
        dbo.GTSFormatSQL('    FROM RMEvents e') +
        dbo.GTSFormatSQL('    LEFT JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('        ON c.EventID = e.EventID') +
        dbo.GTSFormatSQL('        AND (@UseCapacityType = 0 OR c.CapacityType = 0)') +
        dbo.GTSFormatSQL('        AND (@IgnoreAvailability = 1 OR c.Available > 0)') +
        dbo.GTSFormatSQL('    LEFT JOIN RMResources rmr') +
        dbo.GTSFormatSQL('        ON rmr.ResourceID = CASE WHEN c.ResourceID IS NULL THEN e.ResourceID ELSE c.ResourceID END') +
        dbo.GTSFormatSQL('    LEFT JOIN RSEventSeatMaps r') +
        dbo.GTSFormatSQL('        ON r.EventID = e.EventID') +
        dbo.GTSFormatSQL('        AND r.RSEventSeatMapID = e.RSEventSeatMapID') +
        dbo.GTSFormatSQL('        AND r.Available > 0') +
        dbo.GTSFormatSQL('    LEFT JOIN EventSaleLimits esl WITH (INDEX(IXEventSaleLimitsEventIDSCID), FORCESEEK)') +
        dbo.GTSFormatSQL('        ON esl.EventID = e.EventID') +
        dbo.GTSFormatSQL('        AND esl.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('    WHERE') +
        dbo.GTSFormatSQL('        (@EventTypeID = 0 OR e.EventTypeID = @EventTypeID)') +
        dbo.GTSFormatSQL('        AND e.ActiveIndicator = 0') +
        dbo.GTSFormatSQL('        AND e.StartDateTime BETWEEN @StartDateFrom AND @StartDateThru') +
        dbo.GTSFormatSQL('        AND (@ResourceID = 0 OR e.HasSequencedCapacity = 1') +
        dbo.GTSFormatSQL('            OR rmr.ResourceID = @ResourceID OR rmr.AncestorID = @ResourceID)') +
        dbo.GTSFormatSQL('        AND (c.Available IS NOT NULL OR r.Available IS NOT NULL)') +
        dbo.GTSFormatSQL('        AND (') +
        dbo.GTSFormatSQL('            (@UseEventSaleLimits = 0') +
        dbo.GTSFormatSQL('                AND (@Quantity = 0') +
        dbo.GTSFormatSQL('                    OR (e.RSEventSeatMapID > 0 AND r.Available >= @Quantity)') +
        dbo.GTSFormatSQL('                    OR (ISNULL(e.RSEventSeatMapID, 0) = 0 AND c.Available >= @Quantity))') +
        dbo.GTSFormatSQL('                AND @CurrentDateTime BETWEEN e.OnSaleDateTime AND e.OffSaleDateTime)') +
        dbo.GTSFormatSQL('            OR') +
        dbo.GTSFormatSQL('            (@UseEventSaleLimits = 1') +
        dbo.GTSFormatSQL('                AND ((esl.SalesChannelID IS NULL') +
        dbo.GTSFormatSQL('                        AND @CurrentDateTime BETWEEN e.OnSaleDateTime AND e.OffSaleDateTime)') +
        dbo.GTSFormatSQL('                    OR (esl.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('                        AND @CurrentDateTime BETWEEN esl.OnSale AND esl.OffSale)))') +
        dbo.GTSFormatSQL('        )') +
        dbo.GTSFormatSQL('    OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 2: Pre-compute PLU hold groups. Empty when @PLU is blank.') +
        dbo.GTSFormatSQL('    DECLARE @PLUHolds TABLE (HoldGroupID INT NOT NULL PRIMARY KEY)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    IF ISNULL(@PLU, '''') <> '''' BEGIN') +
        dbo.GTSFormatSQL('        INSERT INTO @PLUHolds (HoldGroupID)') +
        dbo.GTSFormatSQL('        SELECT DISTINCT hd.AuxID') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            ON c.EventID = fe.EventID AND c.HoldGroupID IS NOT NULL') +
        dbo.GTSFormatSQL('        JOIN HoldDetails hd') +
        dbo.GTSFormatSQL('            ON hd.AuxID = c.HoldGroupID AND hd.DetailType = 1 AND hd.PLU = @PLU') +
        dbo.GTSFormatSQL('        UNION') +
        dbo.GTSFormatSQL('        SELECT DISTINCT hd.AuxID') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            ON c.EventID = fe.EventID AND c.HoldGroupID IS NOT NULL') +
        dbo.GTSFormatSQL('        JOIN HoldDetails hd') +
        dbo.GTSFormatSQL('            ON hd.AuxID = c.HoldGroupID AND hd.DetailType = 1') +
        dbo.GTSFormatSQL('        JOIN ItemGroups ig ON ig.ItemGroupID = hd.ItemGroupID') +
        dbo.GTSFormatSQL('        JOIN ItemGroupDetails igd') +
        dbo.GTSFormatSQL('            ON igd.ItemGroupID = ig.ItemGroupID AND igd.PLU = @PLU') +
        dbo.GTSFormatSQL('    END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- No-ESL fast path: return filtered capacity rows directly, skip aggregation.') +
        dbo.GTSFormatSQL('    IF @UseEventSaleLimits = 0 BEGIN') +
        dbo.GTSFormatSQL('        SELECT DISTINCT') +
        dbo.GTSFormatSQL('            e.EventID,') +
        dbo.GTSFormatSQL('            e.StartDateTime AS EventDate,') +
        dbo.GTSFormatSQL('            CASE WHEN c.ResourceID IS NULL THEN e.ResourceID ELSE c.ResourceID END AS ResourceID,') +
        dbo.GTSFormatSQL('            CASE WHEN c.Available IS NULL THEN r.Available ELSE c.Available END AS Available,') +
        dbo.GTSFormatSQL('            CASE WHEN c.TotalCapacity IS NULL') +
        dbo.GTSFormatSQL('                THEN ISNULL(r.Available, 0) + ISNULL(r.Reserved, 0) + ISNULL(r.Sold, 0)') +
        dbo.GTSFormatSQL('                ELSE c.TotalCapacity END AS TotalCapacity,') +
        dbo.GTSFormatSQL('            ISNULL(c.HoldGroupID, 0) AS HoldGroupID,') +
        dbo.GTSFormatSQL('            CAST(CASE WHEN ISNULL(@PLU, '''') <> ''''') +
        dbo.GTSFormatSQL('                      AND ISNULL(c.HoldGroupID, 0) > 0') +
        dbo.GTSFormatSQL('                      AND c.HoldGroupID IN (SELECT HoldGroupID FROM @PLUHolds)') +
        dbo.GTSFormatSQL('                 THEN 1 ELSE 0 END AS BIT) AS HasHoldForPLU,') +
        dbo.GTSFormatSQL('            e.OnSaleDateTime,') +
        dbo.GTSFormatSQL('            e.OffSaleDateTime,') +
        dbo.GTSFormatSQL('            CAST(0 AS BIT) AS HasHolds,') +
        dbo.GTSFormatSQL('            ISNULL(e.RSEventSeatMapID, 0) AS RSEventSeatMapID,') +
        dbo.GTSFormatSQL('            e.HasSequencedCapacity,') +
        dbo.GTSFormatSQL('            e.HasEventSaleLimits,') +
        dbo.GTSFormatSQL('            e.SalesChannelCapacityLimitMode,') +
        dbo.GTSFormatSQL('            0 AS SalesChannelID,') +
        dbo.GTSFormatSQL('            0 AS SalesChannelCapacityUnit,') +
        dbo.GTSFormatSQL('            100 AS SalesChannelCapacityLimit,') +
        dbo.GTSFormatSQL('            CASE WHEN c.Available IS NULL THEN r.Available ELSE c.Available END AS ResourceAvailable,') +
        dbo.GTSFormatSQL('            0 AS ResourceHeld,') +
        dbo.GTSFormatSQL('            0 AS MaxAvailableHoldBlockForPLU,') +
        dbo.GTSFormatSQL('            0 AS QuantitySoldOrPendingForEvent,') +
        dbo.GTSFormatSQL('            0 AS QuantitySoldOrPendingForSalesChannel,') +
        dbo.GTSFormatSQL('            0 AS TotalCapacityForEvent,') +
        dbo.GTSFormatSQL('            0 AS ParentCapacityLimitMode,') +
        dbo.GTSFormatSQL('            0 AS ParentCapacityLimit,') +
        dbo.GTSFormatSQL('            0 AS QuantitySoldOrPendingForParent') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN RMEvents e ON e.EventID = fe.EventID') +
        dbo.GTSFormatSQL('        LEFT JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            ON c.EventID = e.EventID') +
        dbo.GTSFormatSQL('            AND (@UseCapacityType = 0 OR c.CapacityType = 0)') +
        dbo.GTSFormatSQL('            AND (@IgnoreAvailability = 1 OR c.Available > 0)') +
        dbo.GTSFormatSQL('        LEFT JOIN RSEventSeatMaps r') +
        dbo.GTSFormatSQL('            ON r.EventID = e.EventID AND r.RSEventSeatMapID = e.RSEventSeatMapID') +
        dbo.GTSFormatSQL('            AND r.Available > 0') +
        dbo.GTSFormatSQL('        ORDER BY e.StartDateTime, e.EventID') +
        dbo.GTSFormatSQL('        OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('        RETURN 0') +
        dbo.GTSFormatSQL('    END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 3: Pre-compute (EventID, ResourceID) pairs with hold capacity rows. ESL path only.') +
        dbo.GTSFormatSQL('    CREATE TABLE #EventResourceHasHolds (') +
        dbo.GTSFormatSQL('        EventID    INT NOT NULL,') +
        dbo.GTSFormatSQL('        ResourceID INT NOT NULL,') +
        dbo.GTSFormatSQL('        PRIMARY KEY CLUSTERED (EventID, ResourceID)') +
        dbo.GTSFormatSQL('    )') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    IF @UseEventSaleLimits = 1 BEGIN') +
        dbo.GTSFormatSQL('        INSERT INTO #EventResourceHasHolds (EventID, ResourceID)') +
        dbo.GTSFormatSQL('        SELECT DISTINCT c.EventID, c.ResourceID') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            ON c.EventID = fe.EventID AND c.CapacityType = 1') +
        dbo.GTSFormatSQL('        OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('    END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 4: Determine sequenced vs non-sequenced per event. Counts all capacity types.') +
        dbo.GTSFormatSQL('    CREATE TABLE #EventSequenced (') +
        dbo.GTSFormatSQL('        EventID          INT NOT NULL PRIMARY KEY CLUSTERED,') +
        dbo.GTSFormatSQL('        IsSequencedEvent BIT NOT NULL') +
        dbo.GTSFormatSQL('    )') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    INSERT INTO #EventSequenced (EventID, IsSequencedEvent)') +
        dbo.GTSFormatSQL('    SELECT') +
        dbo.GTSFormatSQL('        c.EventID,') +
        dbo.GTSFormatSQL('        CAST(CASE WHEN COUNT(*) > 1') +
        dbo.GTSFormatSQL('                   AND SUM(CASE WHEN c.Sequence > 0 THEN 1 ELSE 0 END) > 0') +
        dbo.GTSFormatSQL('             THEN 1 ELSE 0 END AS BIT)') +
        dbo.GTSFormatSQL('    FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('    JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID)) ON c.EventID = fe.EventID') +
        dbo.GTSFormatSQL('    WHERE EXISTS (SELECT 1 FROM #EventResourceHasHolds hh WHERE hh.EventID = fe.EventID)') +
        dbo.GTSFormatSQL('       OR EXISTS (SELECT 1 FROM RMEvents e2 WHERE e2.EventID = fe.EventID AND e2.HasSequencedCapacity = 1)') +
        dbo.GTSFormatSQL('    GROUP BY c.EventID') +
        dbo.GTSFormatSQL('    OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 5: Materialize per-event capacity rows for downstream CTE joins.') +
        dbo.GTSFormatSQL('    CREATE TABLE #EventCapacityRows (') +
        dbo.GTSFormatSQL('        EventID                       INT      NOT NULL,') +
        dbo.GTSFormatSQL('        EventDate                     DATETIME NULL,') +
        dbo.GTSFormatSQL('        ResourceID                    INT      NULL,') +
        dbo.GTSFormatSQL('        Available                     INT      NULL,') +
        dbo.GTSFormatSQL('        TotalCapacity                 INT      NULL,') +
        dbo.GTSFormatSQL('        HoldGroupID                   INT      NOT NULL,') +
        dbo.GTSFormatSQL('        HasHoldForPLU                 BIT      NOT NULL,') +
        dbo.GTSFormatSQL('        OnSaleDateTime                DATETIME NULL,') +
        dbo.GTSFormatSQL('        OffSaleDateTime               DATETIME NULL,') +
        dbo.GTSFormatSQL('        HasHolds                      BIT      NOT NULL,') +
        dbo.GTSFormatSQL('        RSEventSeatMapID              INT      NULL,') +
        dbo.GTSFormatSQL('        HasSequencedCapacity          BIT      NULL,') +
        dbo.GTSFormatSQL('        HasEventSaleLimits            BIT      NULL,') +
        dbo.GTSFormatSQL('        SalesChannelCapacityLimitMode INT      NULL,') +
        dbo.GTSFormatSQL('        SalesChannelID                INT      NULL,') +
        dbo.GTSFormatSQL('        SalesChannelCapacityUnit      INT      NULL,') +
        dbo.GTSFormatSQL('        SalesChannelCapacityLimit     INT      NULL,') +
        dbo.GTSFormatSQL('        INDEX IX1 NONCLUSTERED (EventID, ResourceID),') +
        dbo.GTSFormatSQL('        INDEX IX2 NONCLUSTERED (EventID)') +
        dbo.GTSFormatSQL('    )') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    INSERT INTO #EventCapacityRows') +
        dbo.GTSFormatSQL('    SELECT') +
        dbo.GTSFormatSQL('        e.EventID,') +
        dbo.GTSFormatSQL('        e.StartDateTime AS EventDate,') +
        dbo.GTSFormatSQL('        CASE WHEN c.ResourceID IS NULL THEN e.ResourceID ELSE c.ResourceID END AS ResourceID,') +
        dbo.GTSFormatSQL('        CASE WHEN c.Available IS NULL THEN r.Available ELSE c.Available END AS Available,') +
        dbo.GTSFormatSQL('        CASE WHEN c.TotalCapacity IS NULL') +
        dbo.GTSFormatSQL('            THEN ISNULL(r.Available, 0) + ISNULL(r.Reserved, 0) + ISNULL(r.Sold, 0)') +
        dbo.GTSFormatSQL('            ELSE c.TotalCapacity END AS TotalCapacity,') +
        dbo.GTSFormatSQL('        ISNULL(c.HoldGroupID, 0) AS HoldGroupID,') +
        dbo.GTSFormatSQL('        CAST(CASE WHEN ISNULL(@PLU, '''') <> ''''') +
        dbo.GTSFormatSQL('                  AND ISNULL(c.HoldGroupID, 0) > 0') +
        dbo.GTSFormatSQL('                  AND c.HoldGroupID IN (SELECT HoldGroupID FROM @PLUHolds)') +
        dbo.GTSFormatSQL('             THEN 1 ELSE 0 END AS BIT) AS HasHoldForPLU,') +
        dbo.GTSFormatSQL('        CASE WHEN esl.OnSale IS NULL THEN e.OnSaleDateTime ELSE esl.OnSale END AS OnSaleDateTime,') +
        dbo.GTSFormatSQL('        CASE WHEN esl.OffSale IS NULL THEN e.OffSaleDateTime ELSE esl.OffSale END AS OffSaleDateTime,') +
        dbo.GTSFormatSQL('        -- HasHolds: 0 for no-ESL path and RS events.') +
        dbo.GTSFormatSQL('        CAST(CASE WHEN @UseEventSaleLimits = 0 OR c.ResourceID IS NULL THEN 0') +
        dbo.GTSFormatSQL('                  ELSE CASE WHEN hh.EventID IS NOT NULL THEN 1 ELSE 0 END') +
        dbo.GTSFormatSQL('             END AS BIT) AS HasHolds,') +
        dbo.GTSFormatSQL('        ISNULL(e.RSEventSeatMapID, 0) AS RSEventSeatMapID,') +
        dbo.GTSFormatSQL('        e.HasSequencedCapacity,') +
        dbo.GTSFormatSQL('        e.HasEventSaleLimits,') +
        dbo.GTSFormatSQL('        e.SalesChannelCapacityLimitMode,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 THEN 0   ELSE esl.SalesChannelID   END AS SalesChannelID,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 THEN 0   ELSE esl.CapacityUnit     END AS SalesChannelCapacityUnit,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 THEN 100 ELSE esl.Capacity         END AS SalesChannelCapacityLimit') +
        dbo.GTSFormatSQL('    FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('    JOIN RMEvents e ON e.EventID = fe.EventID') +
        dbo.GTSFormatSQL('    LEFT JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('        ON c.EventID = e.EventID') +
        dbo.GTSFormatSQL('        AND (@UseCapacityType = 0 OR c.CapacityType = 0)') +
        dbo.GTSFormatSQL('        AND (@IgnoreAvailability = 1 OR c.Available > 0)') +
        dbo.GTSFormatSQL('    LEFT JOIN RSEventSeatMaps r') +
        dbo.GTSFormatSQL('        ON r.EventID = e.EventID AND r.RSEventSeatMapID = e.RSEventSeatMapID') +
        dbo.GTSFormatSQL('        AND r.Available > 0') +
        dbo.GTSFormatSQL('    LEFT JOIN EventSaleLimits esl WITH (INDEX(IXEventSaleLimitsEventIDSCID), FORCESEEK)') +
        dbo.GTSFormatSQL('        ON esl.EventID = e.EventID AND esl.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('    LEFT JOIN #EventResourceHasHolds hh') +
        dbo.GTSFormatSQL('        ON hh.EventID = e.EventID') +
        dbo.GTSFormatSQL('        AND hh.ResourceID = CASE WHEN c.ResourceID IS NULL THEN e.ResourceID ELSE c.ResourceID END') +
        dbo.GTSFormatSQL('    OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 6: CTE chain.') +
        dbo.GTSFormatSQL('    ;WITH') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Distinct (EventID, ResourceID) pairs requiring aggregation (ESL path, sequenced or HasHolds only).') +
        dbo.GTSFormatSQL('    EventResourcePairs AS (') +
        dbo.GTSFormatSQL('        SELECT DISTINCT ecr.EventID, ecr.ResourceID, ecr.HasSequencedCapacity') +
        dbo.GTSFormatSQL('        FROM #EventCapacityRows ecr') +
        dbo.GTSFormatSQL('        WHERE ecr.RSEventSeatMapID = 0') +
        dbo.GTSFormatSQL('          AND @UseEventSaleLimits = 1') +
        dbo.GTSFormatSQL('          AND (ecr.HasSequencedCapacity = 1 OR ecr.HasHolds = 1)') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Aggregate capacity per (EventID, ResourceID) for events needing it.') +
        dbo.GTSFormatSQL('    CapacityAgg AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            erp.EventID,') +
        dbo.GTSFormatSQL('            erp.ResourceID AS TargetResourceID,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN c.CapacityType = 0') +
        dbo.GTSFormatSQL('                      AND (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                THEN c.Available ELSE 0 END) AS ResourceAvailable,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN c.CapacityType <> 0') +
        dbo.GTSFormatSQL('                      AND (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                THEN c.Available ELSE 0 END) AS ResourceHeld,') +
        dbo.GTSFormatSQL('            -- Sequenced: max single available bucket. Non-sequenced: PLU-filtered max hold block.') +
        dbo.GTSFormatSQL('            CASE WHEN MAX(CAST(es.IsSequencedEvent AS INT)) = 1') +
        dbo.GTSFormatSQL('                THEN ISNULL(MAX(c.Available), 0)') +
        dbo.GTSFormatSQL('                ELSE ISNULL(MAX(CASE WHEN c.CapacityType <> 0') +
        dbo.GTSFormatSQL('                                      AND ph.HoldGroupID IS NOT NULL') +
        dbo.GTSFormatSQL('                                      AND (erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                                THEN c.Available ELSE 0 END), 0)') +
        dbo.GTSFormatSQL('            END AS MaxAvailableHoldBlockForPLU') +
        dbo.GTSFormatSQL('        FROM EventResourcePairs erp') +
        dbo.GTSFormatSQL('        JOIN #EventSequenced es ON es.EventID = erp.EventID') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID)) ON c.EventID = erp.EventID') +
        dbo.GTSFormatSQL('        LEFT JOIN RMResources rmr ON rmr.ResourceID = c.ResourceID') +
        dbo.GTSFormatSQL('        LEFT JOIN @PLUHolds ph ON ph.HoldGroupID = c.HoldGroupID') +
        dbo.GTSFormatSQL('        GROUP BY erp.EventID, erp.ResourceID') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- RS events: totals from RSEventSeatMaps.') +
        dbo.GTSFormatSQL('    SCSeatMapTotals AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            ecr.EventID,') +
        dbo.GTSFormatSQL('            sm.Sold + sm.Reserved AS QuantitySoldOrPendingForEvent,') +
        dbo.GTSFormatSQL('            0 AS QuantitySoldOrPendingForSalesChannel,') +
        dbo.GTSFormatSQL('            sm.Available + sm.Sold + sm.Reserved AS TotalCapacityForEvent') +
        dbo.GTSFormatSQL('        FROM (SELECT DISTINCT EventID, RSEventSeatMapID') +
        dbo.GTSFormatSQL('              FROM #EventCapacityRows WHERE RSEventSeatMapID > 0) ecr') +
        dbo.GTSFormatSQL('        JOIN RSEventSeatMaps sm ON sm.RSEventSeatMapID = ecr.RSEventSeatMapID') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Sold/pending/total capacity per event for the ESL path.') +
        dbo.GTSFormatSQL('    SCCapacityTotals AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            fe.EventID,') +
        dbo.GTSFormatSQL('            SUM(c.Sold + c.QuantityOnHold) AS QuantitySoldOrPendingForEvent,') +
        dbo.GTSFormatSQL('            ISNULL(SUM(ISNULL(sc.Sold + sc.QuantityOnHold, 0)), 0) AS QuantitySoldOrPendingForSalesChannel,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN c.ReleaseState = 2') +
        dbo.GTSFormatSQL('                THEN c.TotalCapacity - c.ReleasedCapacity') +
        dbo.GTSFormatSQL('                ELSE c.TotalCapacity END) AS TotalCapacityForEvent') +
        dbo.GTSFormatSQL('        FROM (SELECT DISTINCT EventID FROM #EventCapacityRows WHERE SalesChannelID IS NOT NULL) fe') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID)) ON c.EventID = fe.EventID') +
        dbo.GTSFormatSQL('        LEFT JOIN RMSalesChannelCapacity sc') +
        dbo.GTSFormatSQL('            ON sc.CapacityID = c.CapacityID AND sc.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('        WHERE @UseEventSaleLimits = 1') +
        dbo.GTSFormatSQL('        GROUP BY fe.EventID') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Merge: RS events use seatmap totals, others use capacity totals.') +
        dbo.GTSFormatSQL('    SCTotals AS (') +
        dbo.GTSFormatSQL('        SELECT EventID, QuantitySoldOrPendingForEvent, QuantitySoldOrPendingForSalesChannel, TotalCapacityForEvent') +
        dbo.GTSFormatSQL('        FROM SCCapacityTotals sct') +
        dbo.GTSFormatSQL('        WHERE NOT EXISTS (SELECT 1 FROM SCSeatMapTotals sm WHERE sm.EventID = sct.EventID)') +
        dbo.GTSFormatSQL('        UNION ALL') +
        dbo.GTSFormatSQL('        SELECT EventID, QuantitySoldOrPendingForEvent, QuantitySoldOrPendingForSalesChannel, TotalCapacityForEvent') +
        dbo.GTSFormatSQL('        FROM SCSeatMapTotals') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- EventSaleLimits rows for @SalesChannelID, driven from #FilteredEvents.') +
        dbo.GTSFormatSQL('    ESLData AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            fe.EventID,') +
        dbo.GTSFormatSQL('            esl.EventSaleLimitID,') +
        dbo.GTSFormatSQL('            esl.ParentEventSaleLimitID,') +
        dbo.GTSFormatSQL('            esl.Capacity,') +
        dbo.GTSFormatSQL('            ecr.SalesChannelCapacityLimitMode') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN EventSaleLimits esl WITH (INDEX(IXEventSaleLimitsEventIDSCID), FORCESEEK)') +
        dbo.GTSFormatSQL('            ON esl.EventID = fe.EventID AND esl.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('        JOIN (SELECT DISTINCT EventID, SalesChannelCapacityLimitMode FROM #EventCapacityRows) ecr') +
        dbo.GTSFormatSQL('            ON ecr.EventID = fe.EventID') +
        dbo.GTSFormatSQL('        WHERE @UseEventSaleLimits = 1') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Parent/sub-limit resolution per sales channel.') +
        dbo.GTSFormatSQL('    ParentLimitData AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            ed.EventID,') +
        dbo.GTSFormatSQL('            CASE') +
        dbo.GTSFormatSQL('                WHEN ed.ParentEventSaleLimitID = 0') +
        dbo.GTSFormatSQL('                     AND EXISTS (SELECT 1 FROM EventSaleLimits ch') +
        dbo.GTSFormatSQL('                                 WHERE ch.EventID = ed.EventID') +
        dbo.GTSFormatSQL('                                   AND ch.ParentEventSaleLimitID = ed.EventSaleLimitID)') +
        dbo.GTSFormatSQL('                    THEN 1  -- IS_PARENT') +
        dbo.GTSFormatSQL('                WHEN ed.ParentEventSaleLimitID > 0') +
        dbo.GTSFormatSQL('                    THEN 2  -- IS_SUBLIMIT') +
        dbo.GTSFormatSQL('                ELSE 0') +
        dbo.GTSFormatSQL('            END AS ParentCapacityLimitMode,') +
        dbo.GTSFormatSQL('            CASE') +
        dbo.GTSFormatSQL('                WHEN ed.ParentEventSaleLimitID = 0 THEN ed.Capacity') +
        dbo.GTSFormatSQL('                ELSE (SELECT p.Capacity FROM EventSaleLimits p') +
        dbo.GTSFormatSQL('                      WHERE p.EventSaleLimitID = ed.ParentEventSaleLimitID)') +
        dbo.GTSFormatSQL('            END AS ParentCapacityLimit,') +
        dbo.GTSFormatSQL('            ISNULL((') +
        dbo.GTSFormatSQL('                SELECT SUM(sc.Sold + sc.QuantityOnHold)') +
        dbo.GTSFormatSQL('                FROM EventSaleLimits esl2') +
        dbo.GTSFormatSQL('                JOIN RMCapacity c2 ON c2.EventID = esl2.EventID') +
        dbo.GTSFormatSQL('                JOIN RMSalesChannelCapacity sc') +
        dbo.GTSFormatSQL('                    ON sc.CapacityID = c2.CapacityID AND sc.SalesChannelID = esl2.SalesChannelID') +
        dbo.GTSFormatSQL('                WHERE esl2.EventID = ed.EventID') +
        dbo.GTSFormatSQL('                  AND (esl2.EventSaleLimitID = CASE WHEN ed.ParentEventSaleLimitID = 0') +
        dbo.GTSFormatSQL('                            THEN ed.EventSaleLimitID ELSE ed.ParentEventSaleLimitID END') +
        dbo.GTSFormatSQL('                    OR esl2.ParentEventSaleLimitID = CASE WHEN ed.ParentEventSaleLimitID = 0') +
        dbo.GTSFormatSQL('                            THEN ed.EventSaleLimitID ELSE ed.ParentEventSaleLimitID END)') +
        dbo.GTSFormatSQL('            ), 0) AS QuantitySoldOrPendingForParent') +
        dbo.GTSFormatSQL('        FROM ESLData ed') +
        dbo.GTSFormatSQL('        WHERE ed.SalesChannelCapacityLimitMode = 1  -- Per Sales Channel only') +
        dbo.GTSFormatSQL('          AND (ed.ParentEventSaleLimitID > 0') +
        dbo.GTSFormatSQL('               OR EXISTS (SELECT 1 FROM EventSaleLimits ch') +
        dbo.GTSFormatSQL('                          WHERE ch.EventID = ed.EventID') +
        dbo.GTSFormatSQL('                            AND ch.ParentEventSaleLimitID = ed.EventSaleLimitID))') +
        dbo.GTSFormatSQL('    )') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SELECT DISTINCT') +
        dbo.GTSFormatSQL('        ecr.EventID,') +
        dbo.GTSFormatSQL('        ecr.EventDate,') +
        dbo.GTSFormatSQL('        ecr.ResourceID,') +
        dbo.GTSFormatSQL('        ecr.Available,') +
        dbo.GTSFormatSQL('        ecr.TotalCapacity,') +
        dbo.GTSFormatSQL('        ecr.HoldGroupID,') +
        dbo.GTSFormatSQL('        ecr.HasHoldForPLU,') +
        dbo.GTSFormatSQL('        ecr.OnSaleDateTime,') +
        dbo.GTSFormatSQL('        ecr.OffSaleDateTime,') +
        dbo.GTSFormatSQL('        ecr.HasHolds,') +
        dbo.GTSFormatSQL('        ecr.RSEventSeatMapID,') +
        dbo.GTSFormatSQL('        ecr.HasSequencedCapacity,') +
        dbo.GTSFormatSQL('        ecr.HasEventSaleLimits,') +
        dbo.GTSFormatSQL('        ecr.SalesChannelCapacityLimitMode,') +
        dbo.GTSFormatSQL('        ecr.SalesChannelID,') +
        dbo.GTSFormatSQL('        ecr.SalesChannelCapacityUnit,') +
        dbo.GTSFormatSQL('        ecr.SalesChannelCapacityLimit,') +
        dbo.GTSFormatSQL('        -- ResourceAvailable: aggregated for sequenced/hold events; direct otherwise.') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0         THEN ecr.Available') +
        dbo.GTSFormatSQL('             WHEN ecr.RSEventSeatMapID > 0        THEN ISNULL(ecr.Available, 0)') +
        dbo.GTSFormatSQL('             WHEN ecr.HasSequencedCapacity = 1    THEN ISNULL(ca.ResourceAvailable, 0) + ISNULL(ca.ResourceHeld, 0)') +
        dbo.GTSFormatSQL('             WHEN ecr.HasHolds = 1                THEN ISNULL(ca.ResourceAvailable, 0)') +
        dbo.GTSFormatSQL('             ELSE ecr.Available') +
        dbo.GTSFormatSQL('        END AS ResourceAvailable,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 THEN 0') +
        dbo.GTSFormatSQL('             WHEN ecr.HasSequencedCapacity = 1 OR ecr.HasHolds = 1 THEN ISNULL(ca.ResourceHeld, 0)') +
        dbo.GTSFormatSQL('             ELSE 0') +
        dbo.GTSFormatSQL('        END AS ResourceHeld,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 THEN 0') +
        dbo.GTSFormatSQL('             WHEN ecr.HasSequencedCapacity = 1 OR ecr.HasHolds = 1 THEN ISNULL(ca.MaxAvailableHoldBlockForPLU, 0)') +
        dbo.GTSFormatSQL('             ELSE 0') +
        dbo.GTSFormatSQL('        END AS MaxAvailableHoldBlockForPLU,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 OR ecr.HasEventSaleLimits = 0 OR ISNULL(ecr.SalesChannelID, 0) = 0') +
        dbo.GTSFormatSQL('             THEN 0 ELSE ISNULL(sct.QuantitySoldOrPendingForEvent, 0) END AS QuantitySoldOrPendingForEvent,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 OR ecr.HasEventSaleLimits = 0 OR ISNULL(ecr.SalesChannelID, 0) = 0') +
        dbo.GTSFormatSQL('             THEN 0 ELSE ISNULL(sct.QuantitySoldOrPendingForSalesChannel, 0) END AS QuantitySoldOrPendingForSalesChannel,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 OR ecr.HasEventSaleLimits = 0 OR ISNULL(ecr.SalesChannelID, 0) = 0') +
        dbo.GTSFormatSQL('             THEN 0 ELSE ISNULL(sct.TotalCapacityForEvent, 0) END AS TotalCapacityForEvent,') +
        dbo.GTSFormatSQL('        ISNULL(pld.ParentCapacityLimitMode, 0) AS ParentCapacityLimitMode,') +
        dbo.GTSFormatSQL('        ISNULL(pld.ParentCapacityLimit, 0) AS ParentCapacityLimit,') +
        dbo.GTSFormatSQL('        ISNULL(pld.QuantitySoldOrPendingForParent, 0) AS QuantitySoldOrPendingForParent') +
        dbo.GTSFormatSQL('    FROM #EventCapacityRows ecr') +
        dbo.GTSFormatSQL('    LEFT JOIN CapacityAgg ca') +
        dbo.GTSFormatSQL('        ON ca.EventID = ecr.EventID') +
        dbo.GTSFormatSQL('        AND ca.TargetResourceID = ecr.ResourceID') +
        dbo.GTSFormatSQL('        AND ecr.RSEventSeatMapID = 0') +
        dbo.GTSFormatSQL('        AND (ecr.HasSequencedCapacity = 1 OR ecr.HasHolds = 1)') +
        dbo.GTSFormatSQL('    LEFT JOIN SCTotals sct ON sct.EventID = ecr.EventID') +
        dbo.GTSFormatSQL('    LEFT JOIN ParentLimitData pld ON pld.EventID = ecr.EventID') +
        dbo.GTSFormatSQL('    ORDER BY ecr.EventDate, ecr.EventID') +
        dbo.GTSFormatSQL('    OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    RETURN 0') +
        dbo.GTSFormatSQL('    END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_QueryEventDatesData due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_QueryEventDatesData created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created

    Print N'Creating stored procedure GTS_SP_RM_QueryEventsData...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_QueryEventsData') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_QueryEventsData

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_QueryEventsData]') +
        dbo.GTSFormatSQL('    @EventTypeID INT,') +
        dbo.GTSFormatSQL('    @StartDateFrom DATETIME,') +
        dbo.GTSFormatSQL('    @StartDateThru DATETIME,') +
        dbo.GTSFormatSQL('    @SalesChannelID INT,') +
        dbo.GTSFormatSQL('    @PLU NVARCHAR(20),') +
        dbo.GTSFormatSQL('    @IncludeInactiveEvents BIT,') +
        dbo.GTSFormatSQL('    @IncludeOffSaleEvents BIT,') +
        dbo.GTSFormatSQL('    @IncludePriorDayEvents BIT,') +
        dbo.GTSFormatSQL('    @ReservedSeatingOnly BIT,') +
        dbo.GTSFormatSQL('    @ResourceID INT = 0,') +
        dbo.GTSFormatSQL('    @CurrentDateTime DATETIME = NULL') +
        dbo.GTSFormatSQL('    WITH RECOMPILE') +
        dbo.GTSFormatSQL('    AS') +
        dbo.GTSFormatSQL('    BEGIN') +
        dbo.GTSFormatSQL('    -- SP Version 20260410') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    IF @CurrentDateTime IS NULL SET @CurrentDateTime = GETDATE()') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    DECLARE @UseEventSaleLimits BIT = CASE WHEN ISNULL(@SalesChannelID, 0) > 0 THEN 1 ELSE 0 END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 1: Materialize filtered events; all downstream phases join by PK seek.') +
        dbo.GTSFormatSQL('    CREATE TABLE #FilteredEvents (EventID INT NOT NULL PRIMARY KEY CLUSTERED)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    INSERT INTO #FilteredEvents (EventID)') +
        dbo.GTSFormatSQL('    SELECT DISTINCT e.EventID') +
        dbo.GTSFormatSQL('    FROM RMEvents e') +
        dbo.GTSFormatSQL('    LEFT JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('        ON c.EventID = e.EventID AND c.CapacityType = 0') +
        dbo.GTSFormatSQL('    LEFT JOIN RMResources rmr') +
        dbo.GTSFormatSQL('        ON rmr.ResourceID = CASE WHEN c.ResourceID IS NULL THEN e.ResourceID ELSE c.ResourceID END') +
        dbo.GTSFormatSQL('    LEFT JOIN RSEventSeatMaps r') +
        dbo.GTSFormatSQL('        ON r.EventID = e.EventID AND r.RSEventSeatMapID = e.RSEventSeatMapID') +
        dbo.GTSFormatSQL('    LEFT JOIN EventSaleLimits esl WITH (INDEX(IXEventSaleLimitsEventIDSCID), FORCESEEK)') +
        dbo.GTSFormatSQL('        ON esl.EventID = e.EventID AND esl.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('    WHERE') +
        dbo.GTSFormatSQL('        (@EventTypeID = 0 OR e.EventTypeID = @EventTypeID)') +
        dbo.GTSFormatSQL('        AND (@IncludeInactiveEvents = 1 OR e.ActiveIndicator = 0)') +
        dbo.GTSFormatSQL('        AND (@ReservedSeatingOnly = 0 OR e.RSEventSeatMapID > 0)') +
        dbo.GTSFormatSQL('        AND ((e.StartDateTime BETWEEN @StartDateFrom AND @StartDateThru)') +
        dbo.GTSFormatSQL('            OR (@IncludePriorDayEvents = 1 AND @StartDateFrom BETWEEN e.StartDateTime AND e.EndDateTime))') +
        dbo.GTSFormatSQL('        AND (@ResourceID = 0 OR e.HasSequencedCapacity = 1') +
        dbo.GTSFormatSQL('            OR rmr.ResourceID = @ResourceID OR rmr.AncestorID = @ResourceID)') +
        dbo.GTSFormatSQL('        AND (') +
        dbo.GTSFormatSQL('            @IncludeOffSaleEvents = 1') +
        dbo.GTSFormatSQL('            OR (@UseEventSaleLimits = 0') +
        dbo.GTSFormatSQL('                AND @CurrentDateTime BETWEEN e.OnSaleDateTime AND e.OffSaleDateTime)') +
        dbo.GTSFormatSQL('            OR (@UseEventSaleLimits = 1') +
        dbo.GTSFormatSQL('                AND ((esl.SalesChannelID IS NULL') +
        dbo.GTSFormatSQL('                        AND @CurrentDateTime BETWEEN e.OnSaleDateTime AND e.OffSaleDateTime)') +
        dbo.GTSFormatSQL('                    OR (esl.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('                        AND @CurrentDateTime BETWEEN esl.OnSale AND esl.OffSale)))') +
        dbo.GTSFormatSQL('        )') +
        dbo.GTSFormatSQL('    OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 2: Pre-compute PLU hold groups. Empty when @PLU is blank.') +
        dbo.GTSFormatSQL('    DECLARE @PLUHolds TABLE (HoldGroupID INT NOT NULL PRIMARY KEY)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    IF ISNULL(@PLU, '''') <> '''' BEGIN') +
        dbo.GTSFormatSQL('        INSERT INTO @PLUHolds (HoldGroupID)') +
        dbo.GTSFormatSQL('        SELECT DISTINCT hd.AuxID') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            ON c.EventID = fe.EventID AND c.HoldGroupID IS NOT NULL') +
        dbo.GTSFormatSQL('        JOIN HoldDetails hd') +
        dbo.GTSFormatSQL('            ON hd.AuxID = c.HoldGroupID AND hd.DetailType = 1 AND hd.PLU = @PLU') +
        dbo.GTSFormatSQL('        UNION') +
        dbo.GTSFormatSQL('        SELECT DISTINCT hd.AuxID') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            ON c.EventID = fe.EventID AND c.HoldGroupID IS NOT NULL') +
        dbo.GTSFormatSQL('        JOIN HoldDetails hd') +
        dbo.GTSFormatSQL('            ON hd.AuxID = c.HoldGroupID AND hd.DetailType = 1') +
        dbo.GTSFormatSQL('        JOIN ItemGroups ig ON ig.ItemGroupID = hd.ItemGroupID') +
        dbo.GTSFormatSQL('        JOIN ItemGroupDetails igd') +
        dbo.GTSFormatSQL('            ON igd.ItemGroupID = ig.ItemGroupID AND igd.PLU = @PLU') +
        dbo.GTSFormatSQL('    END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 3: Determine sequenced vs non-sequenced per event. Counts all capacity types.') +
        dbo.GTSFormatSQL('    CREATE TABLE #EventSequenced (') +
        dbo.GTSFormatSQL('        EventID          INT NOT NULL PRIMARY KEY CLUSTERED,') +
        dbo.GTSFormatSQL('        IsSequencedEvent BIT NOT NULL') +
        dbo.GTSFormatSQL('    )') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    INSERT INTO #EventSequenced (EventID, IsSequencedEvent)') +
        dbo.GTSFormatSQL('    SELECT') +
        dbo.GTSFormatSQL('        c.EventID,') +
        dbo.GTSFormatSQL('        CAST(CASE WHEN COUNT(*) > 1') +
        dbo.GTSFormatSQL('                   AND SUM(CASE WHEN c.Sequence > 0 THEN 1 ELSE 0 END) > 0') +
        dbo.GTSFormatSQL('             THEN 1 ELSE 0 END AS BIT)') +
        dbo.GTSFormatSQL('    FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('    JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID)) ON c.EventID = fe.EventID') +
        dbo.GTSFormatSQL('    GROUP BY c.EventID') +
        dbo.GTSFormatSQL('    OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 4: Materialize per-event capacity rows for downstream CTE joins.') +
        dbo.GTSFormatSQL('    CREATE TABLE #EventCapacityRows (') +
        dbo.GTSFormatSQL('        EventID                      INT           NOT NULL,') +
        dbo.GTSFormatSQL('        EventName                    NVARCHAR(100) NOT NULL,') +
        dbo.GTSFormatSQL('        StartDateTime                DATETIME      NULL,') +
        dbo.GTSFormatSQL('        EndDateTime                  DATETIME      NULL,') +
        dbo.GTSFormatSQL('        EventTypeID                  INT           NULL,') +
        dbo.GTSFormatSQL('        OnSaleDateTime               DATETIME      NULL,') +
        dbo.GTSFormatSQL('        OffSaleDateTime              DATETIME      NULL,') +
        dbo.GTSFormatSQL('        UserEventNumber              INT           NULL,') +
        dbo.GTSFormatSQL('        ActiveIndicator              INT           NULL,') +
        dbo.GTSFormatSQL('        HasEventSaleLimits           BIT           NULL,') +
        dbo.GTSFormatSQL('        NodeNumber                   INT           NULL,') +
        dbo.GTSFormatSQL('        PrivateEvent                 BIT           NULL,') +
        dbo.GTSFormatSQL('        RosterAttributeGroupID       INT           NULL,') +
        dbo.GTSFormatSQL('        NotesID                      INT           NULL,') +
        dbo.GTSFormatSQL('        AttributeValueGroupID        INT           NULL,') +
        dbo.GTSFormatSQL('        HasRoster                    BIT           NULL,') +
        dbo.GTSFormatSQL('        RSEventSeatMapID             INT           NULL,') +
        dbo.GTSFormatSQL('        HasSequencedCapacity         BIT           NULL,') +
        dbo.GTSFormatSQL('        HasWaitList                  BIT           NULL,') +
        dbo.GTSFormatSQL('        SalesChannelCapacityLimitMode INT          NULL,') +
        dbo.GTSFormatSQL('        ResourceID                   INT           NULL,') +
        dbo.GTSFormatSQL('        Available                    INT           NULL,') +
        dbo.GTSFormatSQL('        Pending                      INT           NULL,') +
        dbo.GTSFormatSQL('        Sold                         INT           NULL,') +
        dbo.GTSFormatSQL('        Sequence                     INT           NULL,') +
        dbo.GTSFormatSQL('        TotalCapacity                INT           NULL,') +
        dbo.GTSFormatSQL('        SalesChannelID               INT           NULL,') +
        dbo.GTSFormatSQL('        SalesChannelCapacityUnit     INT           NULL,') +
        dbo.GTSFormatSQL('        SalesChannelCapacityLimit    INT           NULL,') +
        dbo.GTSFormatSQL('        TranslationEventNameID       INT           NULL,') +
        dbo.GTSFormatSQL('        INDEX IX1 NONCLUSTERED (EventID, ResourceID),') +
        dbo.GTSFormatSQL('        INDEX IX2 NONCLUSTERED (EventID)') +
        dbo.GTSFormatSQL('    )') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    INSERT INTO #EventCapacityRows') +
        dbo.GTSFormatSQL('    SELECT') +
        dbo.GTSFormatSQL('        e.EventID,') +
        dbo.GTSFormatSQL('        e.EventName,') +
        dbo.GTSFormatSQL('        e.StartDateTime,') +
        dbo.GTSFormatSQL('        e.EndDateTime,') +
        dbo.GTSFormatSQL('        e.EventTypeID,') +
        dbo.GTSFormatSQL('        CASE WHEN esl.OnSale  IS NULL THEN e.OnSaleDateTime  ELSE esl.OnSale  END,') +
        dbo.GTSFormatSQL('        CASE WHEN esl.OffSale IS NULL THEN e.OffSaleDateTime ELSE esl.OffSale END,') +
        dbo.GTSFormatSQL('        e.UserEventNumber,') +
        dbo.GTSFormatSQL('        e.ActiveIndicator,') +
        dbo.GTSFormatSQL('        e.HasEventSaleLimits,') +
        dbo.GTSFormatSQL('        e.NodeNumber,') +
        dbo.GTSFormatSQL('        e.PrivateEvent,') +
        dbo.GTSFormatSQL('        e.RosterAttributeGroupID,') +
        dbo.GTSFormatSQL('        e.NotesID,') +
        dbo.GTSFormatSQL('        e.AttributeValueGroupID,') +
        dbo.GTSFormatSQL('        e.HasRoster,') +
        dbo.GTSFormatSQL('        ISNULL(e.RSEventSeatMapID, 0) AS RSEventSeatMapID,') +
        dbo.GTSFormatSQL('        e.HasSequencedCapacity,') +
        dbo.GTSFormatSQL('        e.HasWaitList,') +
        dbo.GTSFormatSQL('        e.SalesChannelCapacityLimitMode,') +
        dbo.GTSFormatSQL('        CASE WHEN c.ResourceID IS NULL THEN e.ResourceID ELSE c.ResourceID END,') +
        dbo.GTSFormatSQL('        CASE WHEN c.Available IS NULL THEN r.Available ELSE c.Available END,') +
        dbo.GTSFormatSQL('        CASE WHEN c.QuantityOnHold IS NULL THEN r.Reserved ELSE c.QuantityOnHold END,') +
        dbo.GTSFormatSQL('        CASE WHEN c.Sold IS NULL THEN r.Sold ELSE c.Sold END,') +
        dbo.GTSFormatSQL('        CASE WHEN c.ResourceID IS NULL THEN 0 ELSE c.Sequence END,') +
        dbo.GTSFormatSQL('        CASE WHEN c.ResourceID IS NULL') +
        dbo.GTSFormatSQL('            THEN ISNULL(r.Available, 0) + ISNULL(r.Reserved, 0) + ISNULL(r.Sold, 0)') +
        dbo.GTSFormatSQL('            ELSE c.TotalCapacity END,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 THEN 0   ELSE esl.SalesChannelID   END,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 THEN 0   ELSE esl.CapacityUnit     END,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 0 THEN 100 ELSE esl.Capacity         END,') +
        dbo.GTSFormatSQL('        (SELECT TOP 1 ten.TranslationEventNameID FROM TranslationEventNames ten WHERE ten.EventName = e.EventName)') +
        dbo.GTSFormatSQL('    FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('    JOIN RMEvents e ON e.EventID = fe.EventID') +
        dbo.GTSFormatSQL('    LEFT JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('        ON c.EventID = e.EventID AND c.CapacityType = 0') +
        dbo.GTSFormatSQL('    LEFT JOIN RSEventSeatMaps r') +
        dbo.GTSFormatSQL('        ON r.EventID = e.EventID AND r.RSEventSeatMapID = e.RSEventSeatMapID') +
        dbo.GTSFormatSQL('    LEFT JOIN EventSaleLimits esl WITH (INDEX(IXEventSaleLimitsEventIDSCID), FORCESEEK)') +
        dbo.GTSFormatSQL('        ON esl.EventID = e.EventID AND esl.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('    OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Phase 5: CTE chain.') +
        dbo.GTSFormatSQL('    ;WITH') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Distinct (EventID, ResourceID) pairs for non-RS events.') +
        dbo.GTSFormatSQL('    EventResourcePairs AS (') +
        dbo.GTSFormatSQL('        SELECT DISTINCT EventID, ResourceID, HasSequencedCapacity') +
        dbo.GTSFormatSQL('        FROM #EventCapacityRows') +
        dbo.GTSFormatSQL('        WHERE RSEventSeatMapID = 0') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Aggregate capacity per (EventID, ResourceID) with resource scoping and hold detection.') +
        dbo.GTSFormatSQL('    CapacityAgg AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            erp.EventID,') +
        dbo.GTSFormatSQL('            erp.ResourceID AS TargetResourceID,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN c.CapacityType = 0') +
        dbo.GTSFormatSQL('                      AND (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                THEN c.Available ELSE 0 END) AS ResourceAvailable,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                THEN c.Sold ELSE 0 END) AS ResourceSold,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                THEN c.QuantityOnHold ELSE 0 END) AS ResourcePending,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN c.CapacityType <> 0') +
        dbo.GTSFormatSQL('                      AND (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                THEN c.Available ELSE 0 END) AS ResourceHeld,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN c.CapacityType <> 0') +
        dbo.GTSFormatSQL('                      AND c.ReleaseState = 1  -- IS_RELEASABLE') +
        dbo.GTSFormatSQL('                      AND (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                THEN c.Available ELSE 0 END) AS ResourceReleasable,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                           OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                           OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                THEN CASE WHEN c.ReleaseState = 2  -- WAS_RELEASED') +
        dbo.GTSFormatSQL('                    THEN c.TotalCapacity - c.ReleasedCapacity') +
        dbo.GTSFormatSQL('                    ELSE c.TotalCapacity END') +
        dbo.GTSFormatSQL('                ELSE 0 END) AS ResourceTotalCapacity,') +
        dbo.GTSFormatSQL('            ISNULL(MAX(CASE WHEN c.CapacityType <> 0') +
        dbo.GTSFormatSQL('                             AND ph.HoldGroupID IS NOT NULL') +
        dbo.GTSFormatSQL('                             AND (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                                  OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                                  OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('                        THEN c.Available ELSE 0 END), 0) AS MaxAvailableHoldBlockForPLU,') +
        dbo.GTSFormatSQL('            CAST(MAX(CASE WHEN c.HoldGroupID > 0 THEN 1 ELSE 0 END) AS BIT) AS EventHasHolds') +
        dbo.GTSFormatSQL('        FROM EventResourcePairs erp') +
        dbo.GTSFormatSQL('        JOIN #EventSequenced es ON es.EventID = erp.EventID') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID)) ON c.EventID = erp.EventID') +
        dbo.GTSFormatSQL('        LEFT JOIN RMResources rmr ON rmr.ResourceID = c.ResourceID') +
        dbo.GTSFormatSQL('        LEFT JOIN @PLUHolds ph ON ph.HoldGroupID = c.HoldGroupID') +
        dbo.GTSFormatSQL('        GROUP BY erp.EventID, erp.ResourceID') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- First available GENERAL capacity row per resource, ordered by Sequence then CapacityID.') +
        dbo.GTSFormatSQL('    AvailableBuckets AS (') +
        dbo.GTSFormatSQL('        SELECT erp.EventID, erp.ResourceID AS TargetResourceID, ab.AvailableBucketID') +
        dbo.GTSFormatSQL('        FROM EventResourcePairs erp') +
        dbo.GTSFormatSQL('        JOIN #EventSequenced es ON es.EventID = erp.EventID') +
        dbo.GTSFormatSQL('        CROSS APPLY (') +
        dbo.GTSFormatSQL('            SELECT TOP 1 c.CapacityID AS AvailableBucketID') +
        dbo.GTSFormatSQL('            FROM RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            LEFT JOIN RMResources rmr ON rmr.ResourceID = c.ResourceID') +
        dbo.GTSFormatSQL('            WHERE c.EventID = erp.EventID') +
        dbo.GTSFormatSQL('                AND c.CapacityType = 0') +
        dbo.GTSFormatSQL('                AND c.Available > 0') +
        dbo.GTSFormatSQL('                AND (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                    OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                    OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('            ORDER BY c.Sequence, c.CapacityID') +
        dbo.GTSFormatSQL('        ) ab') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- HOLD row with largest available for @PLU. NULL when @PLU is blank.') +
        dbo.GTSFormatSQL('    MaxHoldBuckets AS (') +
        dbo.GTSFormatSQL('        SELECT erp.EventID, erp.ResourceID AS TargetResourceID, mhb.MaxAvailableHoldBlockForPLUBucketID') +
        dbo.GTSFormatSQL('        FROM EventResourcePairs erp') +
        dbo.GTSFormatSQL('        JOIN #EventSequenced es ON es.EventID = erp.EventID') +
        dbo.GTSFormatSQL('        CROSS APPLY (') +
        dbo.GTSFormatSQL('            SELECT TOP 1 c.CapacityID AS MaxAvailableHoldBlockForPLUBucketID') +
        dbo.GTSFormatSQL('            FROM RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID))') +
        dbo.GTSFormatSQL('            LEFT JOIN RMResources rmr ON rmr.ResourceID = c.ResourceID') +
        dbo.GTSFormatSQL('            WHERE c.EventID = erp.EventID') +
        dbo.GTSFormatSQL('                AND c.CapacityType <> 0') +
        dbo.GTSFormatSQL('                AND c.HoldGroupID IN (SELECT HoldGroupID FROM @PLUHolds)') +
        dbo.GTSFormatSQL('                AND (es.IsSequencedEvent = 1 OR erp.ResourceID = 0') +
        dbo.GTSFormatSQL('                    OR c.ResourceID = erp.ResourceID') +
        dbo.GTSFormatSQL('                    OR ISNULL(rmr.AncestorID, 0) = erp.ResourceID)') +
        dbo.GTSFormatSQL('            ORDER BY c.Available DESC, c.Sequence, c.CapacityID') +
        dbo.GTSFormatSQL('        ) mhb') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Sales channel capacity totals per EventID (non-RS events).') +
        dbo.GTSFormatSQL('    SCCapacityTotals AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            fe.EventID,') +
        dbo.GTSFormatSQL('            SUM(c.Sold + c.QuantityOnHold) AS QuantitySoldOrPendingForEvent,') +
        dbo.GTSFormatSQL('            ISNULL(SUM(ISNULL(sc.Sold + sc.QuantityOnHold, 0)), 0) AS QuantitySoldOrPendingForSalesChannel,') +
        dbo.GTSFormatSQL('            SUM(CASE WHEN c.ReleaseState = 2') +
        dbo.GTSFormatSQL('                THEN c.TotalCapacity - c.ReleasedCapacity') +
        dbo.GTSFormatSQL('                ELSE c.TotalCapacity END) AS TotalCapacityForEvent') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN RMCapacity c WITH (INDEX(IXRMCapacityEventIDResourceID)) ON c.EventID = fe.EventID') +
        dbo.GTSFormatSQL('        LEFT JOIN RMSalesChannelCapacity sc') +
        dbo.GTSFormatSQL('            ON sc.CapacityID = c.CapacityID AND sc.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('        GROUP BY fe.EventID') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- RS events: capacity totals from RSEventSeatMaps.') +
        dbo.GTSFormatSQL('    SCSeatMapTotals AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            ecr.EventID,') +
        dbo.GTSFormatSQL('            sm.Sold + sm.Reserved AS QuantitySoldOrPendingForEvent,') +
        dbo.GTSFormatSQL('            0 AS QuantitySoldOrPendingForSalesChannel,') +
        dbo.GTSFormatSQL('            sm.Available + sm.Sold + sm.Reserved AS TotalCapacityForEvent') +
        dbo.GTSFormatSQL('        FROM (SELECT DISTINCT EventID, RSEventSeatMapID') +
        dbo.GTSFormatSQL('              FROM #EventCapacityRows WHERE RSEventSeatMapID > 0) ecr') +
        dbo.GTSFormatSQL('        JOIN RSEventSeatMaps sm ON sm.RSEventSeatMapID = ecr.RSEventSeatMapID') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Merge: RS events use seatmap totals, others use capacity totals.') +
        dbo.GTSFormatSQL('    SCTotals AS (') +
        dbo.GTSFormatSQL('        SELECT EventID, QuantitySoldOrPendingForEvent, QuantitySoldOrPendingForSalesChannel, TotalCapacityForEvent') +
        dbo.GTSFormatSQL('        FROM SCCapacityTotals sct') +
        dbo.GTSFormatSQL('        WHERE NOT EXISTS (SELECT 1 FROM SCSeatMapTotals sm WHERE sm.EventID = sct.EventID)') +
        dbo.GTSFormatSQL('        UNION ALL') +
        dbo.GTSFormatSQL('        SELECT EventID, QuantitySoldOrPendingForEvent, QuantitySoldOrPendingForSalesChannel, TotalCapacityForEvent') +
        dbo.GTSFormatSQL('        FROM SCSeatMapTotals') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- EventSaleLimits rows for @SalesChannelID, driven from #FilteredEvents.') +
        dbo.GTSFormatSQL('    ESLData AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            fe.EventID,') +
        dbo.GTSFormatSQL('            esl.EventSaleLimitID,') +
        dbo.GTSFormatSQL('            esl.ParentEventSaleLimitID,') +
        dbo.GTSFormatSQL('            esl.Capacity,') +
        dbo.GTSFormatSQL('            ecr.SalesChannelCapacityLimitMode') +
        dbo.GTSFormatSQL('        FROM #FilteredEvents fe') +
        dbo.GTSFormatSQL('        JOIN EventSaleLimits esl WITH (INDEX(IXEventSaleLimitsEventIDSCID), FORCESEEK)') +
        dbo.GTSFormatSQL('            ON esl.EventID = fe.EventID AND esl.SalesChannelID = @SalesChannelID') +
        dbo.GTSFormatSQL('        JOIN (SELECT DISTINCT EventID, SalesChannelCapacityLimitMode FROM #EventCapacityRows) ecr') +
        dbo.GTSFormatSQL('            ON ecr.EventID = fe.EventID') +
        dbo.GTSFormatSQL('        WHERE @UseEventSaleLimits = 1') +
        dbo.GTSFormatSQL('    ),') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Parent/sub-limit resolution per sales channel.') +
        dbo.GTSFormatSQL('    ParentLimitData AS (') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            ed.EventID,') +
        dbo.GTSFormatSQL('            CASE') +
        dbo.GTSFormatSQL('                WHEN ed.ParentEventSaleLimitID = 0') +
        dbo.GTSFormatSQL('                     AND EXISTS (SELECT 1 FROM EventSaleLimits ch') +
        dbo.GTSFormatSQL('                                 WHERE ch.EventID = ed.EventID') +
        dbo.GTSFormatSQL('                                   AND ch.ParentEventSaleLimitID = ed.EventSaleLimitID)') +
        dbo.GTSFormatSQL('                    THEN 1  -- IS_PARENT') +
        dbo.GTSFormatSQL('                WHEN ed.ParentEventSaleLimitID > 0') +
        dbo.GTSFormatSQL('                    THEN 2  -- IS_SUBLIMIT') +
        dbo.GTSFormatSQL('                ELSE 0') +
        dbo.GTSFormatSQL('            END AS ParentCapacityLimitMode,') +
        dbo.GTSFormatSQL('            CASE') +
        dbo.GTSFormatSQL('                WHEN ed.ParentEventSaleLimitID = 0 THEN ed.Capacity') +
        dbo.GTSFormatSQL('                ELSE (SELECT p.Capacity FROM EventSaleLimits p') +
        dbo.GTSFormatSQL('                      WHERE p.EventSaleLimitID = ed.ParentEventSaleLimitID)') +
        dbo.GTSFormatSQL('            END AS ParentCapacityLimit,') +
        dbo.GTSFormatSQL('            ISNULL((') +
        dbo.GTSFormatSQL('                SELECT SUM(sc.Sold + sc.QuantityOnHold)') +
        dbo.GTSFormatSQL('                FROM EventSaleLimits esl2') +
        dbo.GTSFormatSQL('                JOIN RMCapacity c2 ON c2.EventID = esl2.EventID') +
        dbo.GTSFormatSQL('                JOIN RMSalesChannelCapacity sc') +
        dbo.GTSFormatSQL('                    ON sc.CapacityID = c2.CapacityID AND sc.SalesChannelID = esl2.SalesChannelID') +
        dbo.GTSFormatSQL('                WHERE esl2.EventID = ed.EventID') +
        dbo.GTSFormatSQL('                  AND (esl2.EventSaleLimitID = CASE WHEN ed.ParentEventSaleLimitID = 0') +
        dbo.GTSFormatSQL('                            THEN ed.EventSaleLimitID ELSE ed.ParentEventSaleLimitID END') +
        dbo.GTSFormatSQL('                    OR esl2.ParentEventSaleLimitID = CASE WHEN ed.ParentEventSaleLimitID = 0') +
        dbo.GTSFormatSQL('                            THEN ed.EventSaleLimitID ELSE ed.ParentEventSaleLimitID END)') +
        dbo.GTSFormatSQL('            ), 0) AS QuantitySoldOrPendingForParent') +
        dbo.GTSFormatSQL('        FROM ESLData ed') +
        dbo.GTSFormatSQL('        WHERE ed.SalesChannelCapacityLimitMode = 1  -- Per Sales Channel only') +
        dbo.GTSFormatSQL('          AND (ed.ParentEventSaleLimitID > 0') +
        dbo.GTSFormatSQL('               OR EXISTS (SELECT 1 FROM EventSaleLimits ch') +
        dbo.GTSFormatSQL('                          WHERE ch.EventID = ed.EventID') +
        dbo.GTSFormatSQL('                            AND ch.ParentEventSaleLimitID = ed.EventSaleLimitID))') +
        dbo.GTSFormatSQL('    )') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SELECT') +
        dbo.GTSFormatSQL('        ecr.EventID,') +
        dbo.GTSFormatSQL('        ecr.EventName,') +
        dbo.GTSFormatSQL('        ecr.StartDateTime,') +
        dbo.GTSFormatSQL('        ecr.EndDateTime,') +
        dbo.GTSFormatSQL('        ecr.EventTypeID,') +
        dbo.GTSFormatSQL('        ecr.OnSaleDateTime,') +
        dbo.GTSFormatSQL('        ecr.OffSaleDateTime,') +
        dbo.GTSFormatSQL('        ecr.UserEventNumber,') +
        dbo.GTSFormatSQL('        ecr.ActiveIndicator,') +
        dbo.GTSFormatSQL('        ecr.HasEventSaleLimits,') +
        dbo.GTSFormatSQL('        ecr.NodeNumber,') +
        dbo.GTSFormatSQL('        ecr.PrivateEvent,') +
        dbo.GTSFormatSQL('        ecr.RosterAttributeGroupID,') +
        dbo.GTSFormatSQL('        ecr.NotesID,') +
        dbo.GTSFormatSQL('        ecr.AttributeValueGroupID,') +
        dbo.GTSFormatSQL('        ecr.HasRoster,') +
        dbo.GTSFormatSQL('        ecr.RSEventSeatMapID,') +
        dbo.GTSFormatSQL('        ecr.HasSequencedCapacity,') +
        dbo.GTSFormatSQL('        ecr.HasWaitList,') +
        dbo.GTSFormatSQL('        ecr.SalesChannelCapacityLimitMode,') +
        dbo.GTSFormatSQL('        ecr.ResourceID,') +
        dbo.GTSFormatSQL('        ecr.Available,') +
        dbo.GTSFormatSQL('        ecr.Pending,') +
        dbo.GTSFormatSQL('        ecr.Sold,') +
        dbo.GTSFormatSQL('        ecr.Sequence,') +
        dbo.GTSFormatSQL('        ecr.TotalCapacity,') +
        dbo.GTSFormatSQL('        ecr.SalesChannelID,') +
        dbo.GTSFormatSQL('        ecr.SalesChannelCapacityUnit,') +
        dbo.GTSFormatSQL('        ecr.SalesChannelCapacityLimit,') +
        dbo.GTSFormatSQL('        -- Resource-level capacity aggregates.') +
        dbo.GTSFormatSQL('        CASE WHEN ecr.RSEventSeatMapID > 0 THEN ISNULL(ecr.Available, 0)') +
        dbo.GTSFormatSQL('             ELSE ISNULL(ca.ResourceAvailable, 0) END AS ResourceAvailable,') +
        dbo.GTSFormatSQL('        CASE WHEN ecr.RSEventSeatMapID > 0 THEN ISNULL(ecr.Sold, 0)') +
        dbo.GTSFormatSQL('             ELSE ISNULL(ca.ResourceSold, 0) END AS ResourceSold,') +
        dbo.GTSFormatSQL('        CASE WHEN ecr.RSEventSeatMapID > 0 THEN ISNULL(ecr.Pending, 0)') +
        dbo.GTSFormatSQL('             ELSE ISNULL(ca.ResourcePending, 0) END AS ResourcePending,') +
        dbo.GTSFormatSQL('        CASE WHEN ecr.RSEventSeatMapID > 0 THEN 0') +
        dbo.GTSFormatSQL('             ELSE ISNULL(ca.ResourceHeld, 0) END AS ResourceHeld,') +
        dbo.GTSFormatSQL('        CASE WHEN ecr.RSEventSeatMapID > 0 THEN 0') +
        dbo.GTSFormatSQL('             ELSE ISNULL(ca.ResourceReleasable, 0) END AS ResourceReleasable,') +
        dbo.GTSFormatSQL('        CASE WHEN ecr.RSEventSeatMapID > 0') +
        dbo.GTSFormatSQL('             THEN ISNULL(ecr.Available, 0) + ISNULL(ecr.Sold, 0) + ISNULL(ecr.Pending, 0)') +
        dbo.GTSFormatSQL('             ELSE ISNULL(ca.ResourceTotalCapacity, 0) END AS ResourceTotalCapacity,') +
        dbo.GTSFormatSQL('        CASE WHEN ecr.RSEventSeatMapID > 0 THEN CAST(0 AS BIT)') +
        dbo.GTSFormatSQL('             ELSE ISNULL(ca.EventHasHolds, CAST(0 AS BIT)) END AS EventHasHolds,') +
        dbo.GTSFormatSQL('        ab.AvailableBucketID,') +
        dbo.GTSFormatSQL('        ISNULL(ca.MaxAvailableHoldBlockForPLU, 0) AS MaxAvailableHoldBlockForPLU,') +
        dbo.GTSFormatSQL('        mhb.MaxAvailableHoldBlockForPLUBucketID,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 1 AND ecr.HasEventSaleLimits = 1 AND ISNULL(ecr.SalesChannelID, 0) > 0') +
        dbo.GTSFormatSQL('             THEN ISNULL(sct.QuantitySoldOrPendingForEvent, 0) ELSE 0 END AS QuantitySoldOrPendingForEvent,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 1 AND ecr.HasEventSaleLimits = 1 AND ISNULL(ecr.SalesChannelID, 0) > 0') +
        dbo.GTSFormatSQL('             THEN ISNULL(sct.QuantitySoldOrPendingForSalesChannel, 0) ELSE 0 END AS QuantitySoldOrPendingForSalesChannel,') +
        dbo.GTSFormatSQL('        CASE WHEN @UseEventSaleLimits = 1 AND ecr.HasEventSaleLimits = 1 AND ISNULL(ecr.SalesChannelID, 0) > 0') +
        dbo.GTSFormatSQL('             THEN ISNULL(sct.TotalCapacityForEvent, 0) ELSE 0 END AS TotalCapacityForEvent,') +
        dbo.GTSFormatSQL('        ISNULL(pld.ParentCapacityLimitMode, 0) AS ParentCapacityLimitMode,') +
        dbo.GTSFormatSQL('        ISNULL(pld.ParentCapacityLimit, 0) AS ParentCapacityLimit,') +
        dbo.GTSFormatSQL('        ISNULL(pld.QuantitySoldOrPendingForParent, 0) AS QuantitySoldOrPendingForParent,') +
        dbo.GTSFormatSQL('        ecr.TranslationEventNameID') +
        dbo.GTSFormatSQL('    FROM #EventCapacityRows ecr') +
        dbo.GTSFormatSQL('    LEFT JOIN CapacityAgg ca') +
        dbo.GTSFormatSQL('        ON ca.EventID = ecr.EventID') +
        dbo.GTSFormatSQL('        AND ca.TargetResourceID = ecr.ResourceID') +
        dbo.GTSFormatSQL('        AND ecr.RSEventSeatMapID = 0') +
        dbo.GTSFormatSQL('    LEFT JOIN AvailableBuckets ab') +
        dbo.GTSFormatSQL('        ON ab.EventID = ecr.EventID') +
        dbo.GTSFormatSQL('        AND ab.TargetResourceID = ecr.ResourceID') +
        dbo.GTSFormatSQL('        AND ecr.RSEventSeatMapID = 0') +
        dbo.GTSFormatSQL('    LEFT JOIN MaxHoldBuckets mhb') +
        dbo.GTSFormatSQL('        ON mhb.EventID = ecr.EventID') +
        dbo.GTSFormatSQL('        AND mhb.TargetResourceID = ecr.ResourceID') +
        dbo.GTSFormatSQL('        AND ecr.RSEventSeatMapID = 0') +
        dbo.GTSFormatSQL('    LEFT JOIN SCTotals sct ON sct.EventID = ecr.EventID') +
        dbo.GTSFormatSQL('    LEFT JOIN ParentLimitData pld ON pld.EventID = ecr.EventID') +
        dbo.GTSFormatSQL('    ORDER BY ecr.StartDateTime, ecr.EventID') +
        dbo.GTSFormatSQL('    OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    RETURN 0') +
        dbo.GTSFormatSQL('    END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_QueryEventsData due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_QueryEventsData created successfully.'
