    Print N'Creating stored procedure GTS_SP_RM_CapacityHoldExists...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_CapacityHoldExists') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_CapacityHoldExists

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_CapacityHoldExists] ') +
        dbo.GTSFormatSQL('    @EventID Int, ') +
        dbo.GTSFormatSQL('    @ResourceID Int, ') +
        dbo.GTSFormatSQL('    @NodeNo Int, ') +
        dbo.GTSFormatSQL('    @GroupIDType Int, ') +
        dbo.GTSFormatSQL('    @GroupID Int, ') +
        dbo.GTSFormatSQL('    @CapacityID Int, ') +
        dbo.GTSFormatSQL('    @ExistingHoldID Int OUTPUT, ') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT ') +
        dbo.GTSFormatSQL('    AS ') +
        dbo.GTSFormatSQL('    BEGIN ') +
        dbo.GTSFormatSQL('        SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */ ') +
        dbo.GTSFormatSQL('        SET @ExistingHoldID =  0 ') +
        dbo.GTSFormatSQL('        SET @ResultCode     =  0 ') +

        dbo.GTSFormatSQL('        BEGIN TRY ') +
        dbo.GTSFormatSQL('            /* Check if a capacity hold record already exists */ ') +
        dbo.GTSFormatSQL('            SELECT @ExistingHoldID = RMCapacityHoldUID FROM RMCapacityHold ') +
        dbo.GTSFormatSQL('            WHERE EventID = @EventID and ResourceID = @ResourceID and ') +
        dbo.GTSFormatSQL('                  (@NodeNo = 0 or Node = @NodeNo) and GroupIDType = @GroupIDType and ') +
        dbo.GTSFormatSQL('                  GroupID = @GroupID and (@CapacityID = 0 or CapacityID = @CapacityID) ') +
        dbo.GTSFormatSQL('            END TRY ') +
        dbo.GTSFormatSQL('        BEGIN CATCH ') +
        dbo.GTSFormatSQL('            SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('            RETURN(ERROR_NUMBER()) ') +
        dbo.GTSFormatSQL('            END CATCH ') +
        dbo.GTSFormatSQL('        END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_CapacityHoldExists due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_CapacityHoldExists created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created
    END

	Print N'Creating stored procedure GTS_SP_RM_Release_RMCapacity...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_Release_RMCapacity') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_Release_RMCapacity

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_Release_RMCapacity] ') +
        dbo.GTSFormatSQL('    @CapacityID Int, ') +
        dbo.GTSFormatSQL('    @EventID Int, ') +
        dbo.GTSFormatSQL('    @ResourceID Int, ') +
        dbo.GTSFormatSQL('    @ReleasedCapacity1 Int, ') +
        dbo.GTSFormatSQL('    @ReleasedCapacity2 Int, ') +
        dbo.GTSFormatSQL('    @ReleasedCapacity3 Int, ') +
        dbo.GTSFormatSQL('    @ReleasedCapacity4 Int, ') +
        dbo.GTSFormatSQL('    @AddToTotalCapacity Int, ') +
        dbo.GTSFormatSQL('    @CapacityType Int, ') +
        dbo.GTSFormatSQL('    @LastUpdate DateTime, ') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20), ') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT, ') +
        dbo.GTSFormatSQL('    @SalesChannelID Int = 0 ') +
        dbo.GTSFormatSQL('    AS BEGIN ') +
        dbo.GTSFormatSQL('        SET NOCOUNT ON; /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */ ') +
        dbo.GTSFormatSQL('        Declare @RowsAffected int; ') +
        dbo.GTSFormatSQL('        Declare @StartTranCount Int; ') +
        dbo.GTSFormatSQL('        Declare @SalesChannelCapacityLimitMode Int; ') +
        dbo.GTSFormatSQL('        Declare @UpdatedCapacityID Int ') +

        dbo.GTSFormatSQL('        SET @RowsAffected = 0; ') +
        dbo.GTSFormatSQL('        SET @ResultCode = 0; ') +

        dbo.GTSFormatSQL('        SELECT @StartTranCount = @@TRANCOUNT; ') +

        dbo.GTSFormatSQL('        BEGIN TRY ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                BEGIN TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                SAVE TRANSACTION LocalTran; ') +

        dbo.GTSFormatSQL('            /* Get the SalesChannelCapacityLimitMode from the event */ ') +
        dbo.GTSFormatSQL('            SELECT @SalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode ') +
        dbo.GTSFormatSQL('            FROM RMEvents ') +
        dbo.GTSFormatSQL('            WHERE EventID = @EventID ') +

        dbo.GTSFormatSQL('            UPDATE R ') +
        dbo.GTSFormatSQL('                SET Available = ((TotalCapacity + @ReleasedCapacity1 - Sold - QuantityOnHold) + ') +
        dbo.GTSFormatSQL('                        ABS(TotalCapacity + @ReleasedCapacity2 - Sold - QuantityOnHold)) / 2, ') +
        dbo.GTSFormatSQL('                    QuantityOnHold = ((QuantityOnHold - @ReleasedCapacity3) + ABS(QuantityOnHold - @ReleasedCapacity4)) / 2, ') +
        dbo.GTSFormatSQL('                    TotalCapacity = ((TotalCapacity + @AddToTotalCapacity) + ABS(TotalCapacity + @AddToTotalCapacity)) / 2, ') +
        dbo.GTSFormatSQL('                    RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy, ') +
        dbo.GTSFormatSQL('                    @UpdatedCapacityID = CapacityID ') +
        dbo.GTSFormatSQL('                -- this hint to ensures data is always accessed in order and locks are held for duration of transaction to prevent deadlocks ') +
        dbo.GTSFormatSQL('                FROM dbo.RMCapacity R WITH(INDEX (IXRMCapacityEventIDResourceID), HOLDLOCK) ') +
        dbo.GTSFormatSQL('                WHERE EventID = @EventID and ResourceID = @ResourceID and ') +
        dbo.GTSFormatSQL('                    (((@CapacityID = 0) and ((CapacityType = @CapacityType) or (CapacityType is NULL))) or CapacityID = @CapacityID) and ') +
        dbo.GTSFormatSQL('                    ((ReleaseState is NULL) or (ReleaseState <> 2)) and ') +
        dbo.GTSFormatSQL('                    (QuantityOnHold >= @ReleasedCapacity3) and (QuantityOnHold >= @ReleasedCapacity4) ') +
        dbo.GTSFormatSQL('            SELECT @RowsAffected = @@ROWCOUNT; ') +

        dbo.GTSFormatSQL('            /* Update the RMSalesChannelCapacity record  */ ') +
        dbo.GTSFormatSQL('            IF (@RowsAffected > 0) AND (@SalesChannelCapacityLimitMode > 0) BEGIN ') +
        dbo.GTSFormatSQL('                UPDATE R ') +
        dbo.GTSFormatSQL('                    SET QuantityOnHold = ((QuantityOnHold - @ReleasedCapacity3) + ABS(QuantityOnHold - @ReleasedCapacity4)) / 2, ') +
        dbo.GTSFormatSQL('                        RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                    -- this hint to ensures data is always accessed in order and locks are held for duration of transaction to prevent deadlocks ') +
        dbo.GTSFormatSQL('                    FROM dbo.RMSalesChannelCapacity R WITH(INDEX (IXCapacityIDSalesChannelID), HOLDLOCK) ') +
        dbo.GTSFormatSQL('                    WHERE (CapacityID = @UpdatedCapacityID) AND (SalesChannelID = @SalesChannelID) and ') +
        dbo.GTSFormatSQL('                    (QuantityOnHold >= @ReleasedCapacity3) and (QuantityOnHold >= @ReleasedCapacity4) ') +
        dbo.GTSFormatSQL('                -- Check for Event Sale Limit Off Sale Rollover') +
        dbo.GTSFormatSQL('                DECLARE @OffSaleRolloverResultCode int ') +
        dbo.GTSFormatSQL('                EXEC [dbo].[GTS_SP_RM_EventSaleLimitOffSaleRollover] ') +
        dbo.GTSFormatSQL('                    @EventID, @SalesChannelID, 1 /*Recurse*/, @LastUpdate, @LastUpdate, @LastUpdatedBy, @OffSaleRolloverResultCode OUTPUT, 1 /*RecurseIncludeParent*/') +
        dbo.GTSFormatSQL('                END; ') +

        dbo.GTSFormatSQL('            IF @StartTranCount = 0 COMMIT TRANSACTION; ') +
        dbo.GTSFormatSQL('            IF @RowsAffected = 0 ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('            END TRY ') +
        dbo.GTSFormatSQL('        BEGIN CATCH ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 OR XACT_STATE() = -1 /*un-committable transaction*/ ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION LocalTran; ') +
        dbo.GTSFormatSQL('            SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('            END CATCH; ') +
        dbo.GTSFormatSQL('        END;')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_Release_RMCapacity due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_Release_RMCapacity created successfully.'
    -- TO DO: Handle error condition where stored procedure is not created

    Print N'Creating stored procedure GTS_SP_RM_Sell_Tickets...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_Sell_Tickets') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_Sell_Tickets

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_Sell_Tickets] ') +
        dbo.GTSFormatSQL('    @EventID Int, ') +
        dbo.GTSFormatSQL('    @ResourceID Int, ') +
        dbo.GTSFormatSQL('    @SalesChannelID Int, ') +
        dbo.GTSFormatSQL('    @Qty Int, ') +
        dbo.GTSFormatSQL('    @CapacityType Int, ') +
        dbo.GTSFormatSQL('    @CapacityID Int, ') +
        dbo.GTSFormatSQL('    @LastUpdate DateTime, ') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20), ') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT, ') +
        dbo.GTSFormatSQL('    @IgnoreCapacity bit = 0 ') +

        dbo.GTSFormatSQL('    AS ') +
        dbo.GTSFormatSQL('    BEGIN ') +
        dbo.GTSFormatSQL('        SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */ ') +

        dbo.GTSFormatSQL('        Declare @DefaultLockMode nvarchar(32) ') +
        dbo.GTSFormatSQL('        Declare @LockName nvarchar(255) ') +
        dbo.GTSFormatSQL('        Declare @LockResult Int ') +
        dbo.GTSFormatSQL('        Declare @RowsAffected Int ') +
        dbo.GTSFormatSQL('        Declare @StartTranCount Int ') +
        dbo.GTSFormatSQL('        Declare @SalesChannelCapacityLimitMode Int ') +
        dbo.GTSFormatSQL('        Declare @RMCapacityHoldUID Int ') +
        dbo.GTSFormatSQL('        Declare @UpdatedCapacityID Int ') +

        dbo.GTSFormatSQL('        /* Set default values for lock mode and database principal variables */ ') +
        dbo.GTSFormatSQL('        SET @DefaultLockMode = ''Exclusive'' ') +
        dbo.GTSFormatSQL('        SET @LockName = ''HoldTicketsLockEventID'' + CAST(@EventID AS varchar(15)) + ''ResourceID'' + CAST(@ResourceID AS varchar(15)) ') +

        dbo.GTSFormatSQL('        SET @ResultCode = 0 ') +

        dbo.GTSFormatSQL('        SELECT @StartTranCount = @@TRANCOUNT ') +

        dbo.GTSFormatSQL('        BEGIN TRY ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                BEGIN TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                SAVE TRANSACTION LocalTran ') +

        dbo.GTSFormatSQL('            EXEC @LockResult = sp_getapplock @Resource = @LockName, @LockMode = ''Exclusive''  /* TO DO: TimeOut can be passed in as a parameter */ ') +
        dbo.GTSFormatSQL('            /* STOP if unable to acquire the application lock in the first place */ ') +
        dbo.GTSFormatSQL('            IF @LockResult < 0 BEGIN ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('                RAISERROR (''Unable to acquire application lock'', 16, 1) ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            /* Get the SalesChannelCapacityLimitMode from the event */ ') +
        dbo.GTSFormatSQL('            SELECT @SalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode ') +
        dbo.GTSFormatSQL('            FROM RMEvents ') +
        dbo.GTSFormatSQL('            WHERE EventID = @EventID ') +

        dbo.GTSFormatSQL('            /* First, attempt to update the RMCapacity table */ ') +
        dbo.GTSFormatSQL('            UPDATE RMCapacity ') +
        dbo.GTSFormatSQL('            SET Sold = Sold + @Qty, ' ) +
        dbo.GTSFormatSQL('            Available = ((Available - @Qty) + ABS(Available - @Qty))/2, ') +
        dbo.GTSFormatSQL('            RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy, ') +
        dbo.GTSFormatSQL('            @UpdatedCapacityID = CapacityID ') +
        dbo.GTSFormatSQL('            WHERE (EventID = @EventID) and (ResourceID = @ResourceID) and (((@CapacityID = 0) and ((CapacityType = @CapacityType) or (CapacityType is NULL)))  or CapacityID = @CapacityID) and ') +
        dbo.GTSFormatSQL('                ((@IgnoreCapacity = 1) OR ((Sold + @Qty <= TotalCapacity) and (Available >= @Qty))) ') +
        dbo.GTSFormatSQL('            SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('            IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 2 ') +
        dbo.GTSFormatSQL('                RAISERROR (''Unable to update RMCapacity table'', 16, 1) ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            /* Attempt to update the RMSalesChannelCapacity table */ ') +
        dbo.GTSFormatSQL('            IF @SalesChannelCapacityLimitMode > 0 BEGIN ') +
        dbo.GTSFormatSQL('                UPDATE RMSalesChannelCapacity ') +
        dbo.GTSFormatSQL('                SET Sold = Sold + @Qty, ') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                WHERE (CapacityID = @UpdatedCapacityID) AND (SalesChannelID = @SalesChannelID) ') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('                /* There was no entry to update so add a new entry */ ') +
        dbo.GTSFormatSQL('                IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                    INSERT INTO RMSalesChannelCapacity (CapacityID, SalesChannelID, Sold, QuantityOnHold, RecordVersion, LastUpdate, LastUpdatedBy) ') +
        dbo.GTSFormatSQL('                    VALUES (@UpdatedCapacityID, @SalesChannelID, @Qty, 0, 1, @LastUpdate, @LastUpdatedBy) ') +
        dbo.GTSFormatSQL('                    SELECT @RowsAffected = @@ROWCOUNT ') +

        dbo.GTSFormatSQL('                    IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                        SET @ResultCode = 3 ') +
        dbo.GTSFormatSQL('                        RAISERROR (''Unable to update RMSalesChannelCapacity table'', 16, 1) ') +
        dbo.GTSFormatSQL('                        END ') +
        dbo.GTSFormatSQL('                    END ') +
        dbo.GTSFormatSQL('                END ') +

        dbo.GTSFormatSQL('            EXEC @LockResult = sp_releaseapplock @Resource = @LockName ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 COMMIT TRANSACTION ') +
        dbo.GTSFormatSQL('            END TRY ') +
        dbo.GTSFormatSQL('        BEGIN CATCH ') +
        dbo.GTSFormatSQL('            IF @ResultCode <> 1 EXEC @LockResult = sp_releaseapplock @Resource = @LockName ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION LocalTran ') +
        dbo.GTSFormatSQL('            IF @ResultCode = 0 SET @ResultCode = 4 ') +
        dbo.GTSFormatSQL('            RETURN(ERROR_NUMBER()) ') +
        dbo.GTSFormatSQL('            END CATCH ') +
        dbo.GTSFormatSQL('        END ')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
