        dbo.GTSFormatSQL('            FROM RMCapacity R WITH(INDEX (IXRMCapacityEventIDResourceID), HOLDLOCK) ') +
        dbo.GTSFormatSQL('            WHERE (EventID = @EventID) and (ResourceID = @ResourceID) and (((@CapacityID = 0) and ((CapacityType = @CapacityType) or (CapacityType is NULL))) or CapacityID = @CapacityID) ') +
        dbo.GTSFormatSQL('                and (Sold >= @Qty) and ((QuantityOnHold + @Qty) <= TotalCapacity) ') +
