        dbo.GTSFormatSQL('        SELECT @StartTranCount = @@TRANCOUNT; ') +

        dbo.GTSFormatSQL('        BEGIN TRY ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('                BEGIN TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                SAVE TRANSACTION LocalTran; ') +

        dbo.GTSFormatSQL('            /* Get the SalesChannelCapacityLimitMode from the event */ ') +
        dbo.GTSFormatSQL('            SELECT @SalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode ') +
        dbo.GTSFormatSQL('            FROM RMEvents ') +
        dbo.GTSFormatSQL('            WHERE EventID = @EventID ') +

        dbo.GTSFormatSQL('            UPDATE R ') +
        dbo.GTSFormatSQL('                SET QuantityOnHold = ((QuantityOnHold - @ReleasedCapacity) + ABS(QuantityOnHold - @ReleasedCapacity)) / 2, ') +
        dbo.GTSFormatSQL('                    ReleasedCapacity = ReleasedCapacity + @ReleasedCapacity, ') +
        dbo.GTSFormatSQL('                    RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy, ') +
        dbo.GTSFormatSQL('                    @UpdatedCapacityID = CapacityID ') +
        dbo.GTSFormatSQL('                -- this hint to ensures data is always accessed in order and locks are held for duration of transaction to prevent deadlocks ') +
        dbo.GTSFormatSQL('                FROM dbo.RMCapacity R WITH(INDEX (IXRMCapacityEventIDResourceID), HOLDLOCK) ') +
        dbo.GTSFormatSQL('                WHERE EventID = @EventID and ResourceID = @ResourceID and ') +
        dbo.GTSFormatSQL('                    (((@CapacityID = 0) and ((CapacityType = @CapacityType) or (CapacityType is NULL))) or CapacityID = @CapacityID) and ') +
        dbo.GTSFormatSQL('                    (QuantityOnHold >= @ReleasedCapacity) and ((ReleasedCapacity + @ReleasedCapacity) <= TotalCapacity) ') +
        dbo.GTSFormatSQL('            SELECT @RowsAffected = @@ROWCOUNT; ') +

        dbo.GTSFormatSQL('            /* Update the RMSalesChannelCapacity record  */ ') +
        dbo.GTSFormatSQL('            IF (@RowsAffected > 0) AND (@SalesChannelCapacityLimitMode > 0) BEGIN ' ) +
        dbo.GTSFormatSQL('                UPDATE R ') +
        dbo.GTSFormatSQL('                SET QuantityOnHold = ((QuantityOnHold - @ReleasedCapacity) + ABS(QuantityOnHold - @ReleasedCapacity)) / 2, ') +
        dbo.GTSFormatSQL('                    RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                    -- this hint to ensures data is always accessed in order and locks are held for duration of transaction to prevent deadlocks ') +
        dbo.GTSFormatSQL('                    FROM dbo.RMSalesChannelCapacity R WITH(INDEX (IXCapacityIDSalesChannelID), HOLDLOCK) ') +
        dbo.GTSFormatSQL('                    WHERE (CapacityID = @UpdatedCapacityID) AND (SalesChannelID = @SalesChannelID) and ') +
        dbo.GTSFormatSQL('                        (QuantityOnHold >= @ReleasedCapacity) ') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT; ') +
        dbo.GTSFormatSQL('                -- Check for Event Sale Limit Off Sale Rollover') +
        dbo.GTSFormatSQL('                DECLARE @OffSaleRolloverResultCode int ') +
        dbo.GTSFormatSQL('                EXEC [dbo].[GTS_SP_RM_EventSaleLimitOffSaleRollover] ') +
        dbo.GTSFormatSQL('                    @EventID, @SalesChannelID, 1 /*Recurse*/, @LastUpdate, @LastUpdate, @LastUpdatedBy, @OffSaleRolloverResultCode OUTPUT, 1 /*RecurseIncludeParent*/') +
        dbo.GTSFormatSQL('                END; ') +

        dbo.GTSFormatSQL('            IF @StartTranCount = 0 COMMIT TRANSACTION; ') +
        dbo.GTSFormatSQL('            IF @RowsAffected = 0 ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('            END TRY ') +
        dbo.GTSFormatSQL('        BEGIN CATCH ') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0 OR XACT_STATE() = -1 /*un-committable transaction*/ ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION ') +
        dbo.GTSFormatSQL('            ELSE ') +
        dbo.GTSFormatSQL('                ROLLBACK TRANSACTION LocalTran; ') +
        dbo.GTSFormatSQL('            SET @ResultCode = 1 ') +
        dbo.GTSFormatSQL('            END CATCH; ') +
        dbo.GTSFormatSQL('        END;')

