    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_TransferCapacityHoldQuantity] ') +
        dbo.GTSFormatSQL('    @EventID Int,') +
        dbo.GTSFormatSQL('    @ToRMCapacityHoldUID Int,') +
        dbo.GTSFormatSQL('    @FromRMCapacityHoldUID Int,') +
        dbo.GTSFormatSQL('    @QuantityToMove Int,') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20),') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT') +
        dbo.GTSFormatSQL('    AS BEGIN ') +
        dbo.GTSFormatSQL('        SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */ ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    DECLARE @FromSalesChannelID Int') +
        dbo.GTSFormatSQL('    DECLARE @SalesChannelCapacityLimitMode Int') +
        dbo.GTSFormatSQL('    DECLARE @RowsAffected int') +
        dbo.GTSFormatSQL('    DECLARE @StartTranCount Int') +
        dbo.GTSFormatSQL('    SET @ResultCode = 0 ') +
        dbo.GTSFormatSQL('    SET @RowsAffected = 0 ') +
        dbo.GTSFormatSQL('    SELECT @StartTranCount = @@TRANCOUNT ') +
        dbo.GTSFormatSQL('    BEGIN TRY ') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('            BEGIN TRANSACTION ') +
        dbo.GTSFormatSQL('        ELSE') +
        dbo.GTSFormatSQL('            SAVE TRANSACTION LocalTran') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Get the SalesChannelCapacityLimitMode from the event') +
        dbo.GTSFormatSQL('        SELECT @SalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode') +
        dbo.GTSFormatSQL('        FROM RMEvents') +
        dbo.GTSFormatSQL('        WHERE EventID = @EventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Update RMCapacityHold line to increase capacity ') +
        dbo.GTSFormatSQL('        UPDATE RMCapacityHold') +
        dbo.GTSFormatSQL('            SET HoldQuantity = HoldQuantity + @QuantityToMove,') +
        dbo.GTSFormatSQL('                DateTimeHeld = GETDATE(),') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1,') +
        dbo.GTSFormatSQL('                LastUpdate = GETDATE(),') +
        dbo.GTSFormatSQL('                LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('            WHERE RMCapacityHoldUID = @ToRMCapacityHoldUID ') +
        dbo.GTSFormatSQL('            OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('        SELECT @RowsAffected = @@ROWCOUNT') +
        dbo.GTSFormatSQL('        IF @RowsAffected = 0 BEGIN ') +
