        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Remove other line from RMCapacityHold') +
        dbo.GTSFormatSQL('        DELETE RMCapacityHold') +
        dbo.GTSFormatSQL('        WHERE RMCapacityHoldUID = @FromRMCapacityHoldUID') +
        dbo.GTSFormatSQL('            AND HoldQuantity = @QuantityToMove') +
        dbo.GTSFormatSQL('        OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('        SELECT @RowsAffected = @@ROWCOUNT') +
        dbo.GTSFormatSQL('        IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('            UPDATE RMCapacityHold') +
        dbo.GTSFormatSQL('            SET HoldQuantity = HoldQuantity - @QuantityToMove,') +
        dbo.GTSFormatSQL('                DateTimeHeld = GETDATE(),') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1,') +
        dbo.GTSFormatSQL('                LastUpdate = GETDATE(),') +
        dbo.GTSFormatSQL('                LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('            WHERE RMCapacityHoldUID = @FromRMCapacityHoldUID') +
        dbo.GTSFormatSQL('                AND HoldQuantity > @QuantityToMove') +
        dbo.GTSFormatSQL('            OPTION (RECOMPILE)') +
        dbo.GTSFormatSQL('            SELECT @RowsAffected = @@ROWCOUNT') +
        dbo.GTSFormatSQL('            IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                SET @ResultCode = 2 ') +
        dbo.GTSFormatSQL('                RAISERROR (''Unable to remove row from RMCapacityHold'', 16, 1) ') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- If configured to look at sales channel then make changes to RMSalesChannelCapacityHold') +
        dbo.GTSFormatSQL('        IF @SalesChannelCapacityLimitMode > 0 BEGIN') +
        dbo.GTSFormatSQL('            SELECT @FromSalesChannelID = SalesChannelID') +
        dbo.GTSFormatSQL('            FROM RMSalesChannelCapacityHold') +
        dbo.GTSFormatSQL('            WHERE RMCapacityHoldUID = @FromRMCapacityHoldUID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Try to increase RMSalesChannelCapacityHold to increase capacity and remove other line') +
        dbo.GTSFormatSQL('            UPDATE RMSalesChannelCapacityHold') +
        dbo.GTSFormatSQL('                SET HoldQuantity = HoldQuantity + @QuantityToMove,') +
        dbo.GTSFormatSQL('                    RecordVersion = RecordVersion + 1,') +
        dbo.GTSFormatSQL('                    LastUpdate = GETDATE(), ') +
        dbo.GTSFormatSQL('                    LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                WHERE RMCapacityHoldUID = @ToRMCapacityHoldUID  ') +
        dbo.GTSFormatSQL('                    AND SalesChannelID = @FromSalesChannelID ') +
        dbo.GTSFormatSQL('            SELECT @RowsAffected = @@ROWCOUNT') +
        dbo.GTSFormatSQL('            IF @RowsAffected > 0 BEGIN ') +
        dbo.GTSFormatSQL('                DELETE RMSalesChannelCapacityHold') +
        dbo.GTSFormatSQL('                WHERE RMCapacityHoldUID = @FromRMCapacityHoldUID') +
        dbo.GTSFormatSQL('                    AND SalesChannelID = @FromSalesChannelID') +
        dbo.GTSFormatSQL('                    AND HoldQuantity = @QuantityToMove') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT') +
        dbo.GTSFormatSQL('                IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                    UPDATE RMSalesChannelCapacityHold') +
        dbo.GTSFormatSQL('                    SET HoldQuantity = HoldQuantity - @QuantityToMove,') +
        dbo.GTSFormatSQL('                        RecordVersion = RecordVersion + 1,') +
        dbo.GTSFormatSQL('                        LastUpdate = GETDATE(), ') +
        dbo.GTSFormatSQL('                        LastUpdatedBy = @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                    WHERE RMCapacityHoldUID = @FromRMCapacityHoldUID') +
        dbo.GTSFormatSQL('                        AND SalesChannelID = @FromSalesChannelID') +
        dbo.GTSFormatSQL('                        AND HoldQuantity > @QuantityToMove') +
        dbo.GTSFormatSQL('                    SELECT @RowsAffected = @@ROWCOUNT') +
        dbo.GTSFormatSQL('                    IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                        SET @ResultCode = 4 ') +
        dbo.GTSFormatSQL('                        RAISERROR (''Unable to remove row from RMSalesChannelCapacityHold'', 16, 1) ') +
        dbo.GTSFormatSQL('                        END') +
        dbo.GTSFormatSQL('                    END') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            ELSE BEGIN') +
        dbo.GTSFormatSQL('                -- If could not find a row for this SalesChannelID then update RMSalesChannelCapacityHold with new RMCapacityHoldUID') +
        dbo.GTSFormatSQL('                UPDATE RMSalesChannelCapacityHold') +
        dbo.GTSFormatSQL('                    SET RMCapacityHoldUID = @ToRMCapacityHoldUID,') +
        dbo.GTSFormatSQL('                        RecordVersion = RecordVersion + 1,') +
        dbo.GTSFormatSQL('                        LastUpdate = GETDATE(), ') +
        dbo.GTSFormatSQL('                        LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                    WHERE RMCapacityHoldUID = @FromRMCapacityHoldUID') +
        dbo.GTSFormatSQL('                        AND SalesChannelID = @FromSalesChannelID') +
        dbo.GTSFormatSQL('                SELECT @RowsAffected = @@ROWCOUNT') +
        dbo.GTSFormatSQL('                IF @RowsAffected = 0 BEGIN ') +
        dbo.GTSFormatSQL('                    SET @ResultCode = 3') +
        dbo.GTSFormatSQL('                    RAISERROR (''Unable to update RMCapacityHoldUID in RMSalesChannelCapacityHold'', 16, 1) ') +
        dbo.GTSFormatSQL('                    END') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('        COMMIT TRANSACTION; ') +
        dbo.GTSFormatSQL('    END TRY ') +
        dbo.GTSFormatSQL('    BEGIN CATCH ') +
        dbo.GTSFormatSQL('    IF @StartTranCount = 0 OR XACT_STATE() = -1 /*un-committable transaction*/ ') +
        dbo.GTSFormatSQL('        ROLLBACK TRANSACTION ') +
        dbo.GTSFormatSQL('    ELSE ') +
        dbo.GTSFormatSQL('        ROLLBACK TRANSACTION LocalTran; ') +
        dbo.GTSFormatSQL('    IF @ResultCode = 0 ') +
        dbo.GTSFormatSQL('        SET @ResultCode = 5 ') +
        dbo.GTSFormatSQL('    RETURN(ERROR_NUMBER())') +
        dbo.GTSFormatSQL('    END CATCH; ') +
        dbo.GTSFormatSQL('END            ')

