    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE dbo.GTS_SP_RM_UpdateCapacitySequence ') +
        dbo.GTSFormatSQL('    @EventID    int,') +
        dbo.GTSFormatSQL('    @LastUpdate DateTime, ') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20), ') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT') +
        dbo.GTSFormatSQL('AS') +
        dbo.GTSFormatSQL('BEGIN') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON;') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    DECLARE') +
        dbo.GTSFormatSQL('        @StartTranCount         int,') +
        dbo.GTSFormatSQL('        @RecordCount            int') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    DECLARE @TempTable TABLE (CapacityID int, CurrentSequence int, NewSequence int)') +
        dbo.GTSFormatSQL('    DECLARE @seq    int') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SET @ResultCode = 0') +
        dbo.GTSFormatSQL('    SELECT @StartTranCount = @@TRANCOUNT') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    BEGIN TRY') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0') +
        dbo.GTSFormatSQL('            BEGIN TRANSACTION') +
        dbo.GTSFormatSQL('        ELSE') +
        dbo.GTSFormatSQL('            SAVE TRANSACTION LocalTran') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        --Get the highest Sequence to start from') +
        dbo.GTSFormatSQL('        SELECT TOP 1 @seq = Sequence FROM RMCapacity where EventID = @EventID AND CapacityType = 0 ORDER BY Sequence DESC') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @@ROWCOUNT =  0') +
        dbo.GTSFormatSQL('        BEGIN') +
        dbo.GTSFormatSQL('            SET @ResultCode = 1 /* No GENERAL_CAPACITY found */') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('        ELSE') +
        dbo.GTSFormatSQL('        BEGIN') +
        dbo.GTSFormatSQL('            --Insert fixed data into @TempTable table var to make it easier to update the real data') +
        dbo.GTSFormatSQL('            INSERT INTO @TempTable') +
        dbo.GTSFormatSQL('                SELECT CapacityID, [Sequence], @seq + ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) ') +
        dbo.GTSFormatSQL('                FROM RMCapacity WHERE EventID = @EventID AND CapacityType = 1 AND [Sequence] > 0') +
        dbo.GTSFormatSQL('                ORDER BY CapacityType, HoldGroupID, Sequence') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            SET @RecordCount = @@ROWCOUNT') +
        dbo.GTSFormatSQL('            IF @RecordCount = 0') +
        dbo.GTSFormatSQL('            BEGIN') +
        dbo.GTSFormatSQL('                SET @ResultCode = 2 /* No sequence managed HOLD_CAPACITY records found */') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('            ELSE') +
        dbo.GTSFormatSQL('            BEGIN') +
        dbo.GTSFormatSQL('                --Update the RMCapacity table based on the fixed data in the @TempTable') +
        dbo.GTSFormatSQL('                UPDATE rmc') +
        dbo.GTSFormatSQL('                SET ') +
        dbo.GTSFormatSQL('                    rmc.Sequence = tt.NewSequence,') +
        dbo.GTSFormatSQL('                    RecordVersion = RecordVersion + 1,') +
        dbo.GTSFormatSQL('                    LastUpdate = @LastUpdate,') +
        dbo.GTSFormatSQL('                    LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                FROM') +
        dbo.GTSFormatSQL('                    dbo.RMCapacity rmc') +
        dbo.GTSFormatSQL('                    INNER JOIN @TempTable tt ON rmc.CapacityID = tt.CapacityID') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('            IF @StartTranCount = 0') +
        dbo.GTSFormatSQL('                COMMIT TRANSACTION') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('    END TRY') +
        dbo.GTSFormatSQL('    BEGIN CATCH') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0 OR XACT_STATE() = -1 /*un-committable transaction*/') +
        dbo.GTSFormatSQL('            ROLLBACK TRANSACTION') +
        dbo.GTSFormatSQL('        ELSE') +
        dbo.GTSFormatSQL('            ROLLBACK TRANSACTION LocalTran') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @ResultCode = 0') +
        dbo.GTSFormatSQL('            SET @ResultCode = 99 /*Unknown Exception*/') +
        dbo.GTSFormatSQL('        SELECT ERROR_MESSAGE()') +
        dbo.GTSFormatSQL('        RETURN(ERROR_NUMBER())        ') +
        dbo.GTSFormatSQL('    END CATCH') +
        dbo.GTSFormatSQL('END ')

