    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_ReleaseHoldCapacity]') +
        dbo.GTSFormatSQL('    @CapacityID int,') +
        dbo.GTSFormatSQL('    @ResequenceHoldCapacity int,') +
        dbo.GTSFormatSQL('    @LastUpdate DateTime, ') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20), ') +
        dbo.GTSFormatSQL('    @TotalReleased  int = 0 OUTPUT,') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT') +
        dbo.GTSFormatSQL('AS') +
        dbo.GTSFormatSQL('BEGIN') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON;') +
        dbo.GTSFormatSQL('    DECLARE') +
        dbo.GTSFormatSQL('        @AvailableForRelease    int,') +
        dbo.GTSFormatSQL('        @EventID                int,') +
        dbo.GTSFormatSQL('        @RecordCount            int') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    BEGIN TRY') +
        dbo.GTSFormatSQL('        BEGIN TRANSACTION') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        SELECT ') +
        dbo.GTSFormatSQL('            @ResultCode = ') +
        dbo.GTSFormatSQL('            CASE') +
        dbo.GTSFormatSQL('                WHEN rmc.ReleaseState <> 1 THEN 1') +
        dbo.GTSFormatSQL('                WHEN ReleasedCapacity + Available > TotalCapacity THEN 2') +
        dbo.GTSFormatSQL('                WHEN Available > Available THEN 3') +
        dbo.GTSFormatSQL('                ELSE 0') +
        dbo.GTSFormatSQL('                END,') +
        dbo.GTSFormatSQL('            @AvailableForRelease = rmc.Available,') +
        dbo.GTSFormatSQL('            @EventID = rmc.EventID') +
        dbo.GTSFormatSQL('        FROM ') +
        dbo.GTSFormatSQL('            dbo.RMCapacity rmc') +
        dbo.GTSFormatSQL('        WHERE ') +
        dbo.GTSFormatSQL('            CapacityID = @CapacityID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @ResultCode = 0') +
        dbo.GTSFormatSQL('        BEGIN') +
        dbo.GTSFormatSQL('            --Update the Capacity Hold') +
        dbo.GTSFormatSQL('            UPDATE dbo.RMCapacity') +
        dbo.GTSFormatSQL('            SET') +
        dbo.GTSFormatSQL('                ReleasedCapacity = ReleasedCapacity + @AvailableForRelease,') +
        dbo.GTSFormatSQL('                Available = 0,') +
        dbo.GTSFormatSQL('                ReleaseState = 2,') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1,') +
        dbo.GTSFormatSQL('                LastUpdate = @LastUpdate,') +
        dbo.GTSFormatSQL('                LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('            WHERE') +
        dbo.GTSFormatSQL('                CapacityID = @CapacityID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            --Update the General Capacity') +
        dbo.GTSFormatSQL('            UPDATE dbo.RMCapacity ') +
        dbo.GTSFormatSQL('            SET') +
        dbo.GTSFormatSQL('                TotalCapacity = TotalCapacity + @AvailableForRelease,') +
        dbo.GTSFormatSQL('                Available = Available + @AvailableForRelease,') +
        dbo.GTSFormatSQL('                RecordVersion = RecordVersion + 1,') +
        dbo.GTSFormatSQL('                LastUpdate = @LastUpdate,') +
        dbo.GTSFormatSQL('                LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('            WHERE   ') +
        dbo.GTSFormatSQL('                EventID = @EventID') +
        dbo.GTSFormatSQL('                AND CapacityType = 0            ') +
        dbo.GTSFormatSQL(' ') +
        dbo.GTSFormatSQL('            SELECT @RecordCount = @@ROWCOUNT ') +
        dbo.GTSFormatSQL('            IF @ResequenceHoldCapacity = 1 ') +
        dbo.GTSFormatSQL('            BEGIN ') +
        dbo.GTSFormatSQL('                DECLARE @RC int ') +
        dbo.GTSFormatSQL('                EXECUTE @RC = dbo.GTS_SP_RM_UpdateCapacitySequence ') +
        dbo.GTSFormatSQL('                   @EventID, ') +
        dbo.GTSFormatSQL('                   @LastUpdate, ') +
        dbo.GTSFormatSQL('                   @LastUpdatedBy ') +
        dbo.GTSFormatSQL('                  ,@ResultCode OUTPUT ') +
        dbo.GTSFormatSQL(' ') +
        dbo.GTSFormatSQL('                IF @ResultCode <= 2 ') +
        dbo.GTSFormatSQL('                BEGIN ') +
        dbo.GTSFormatSQL('                    SET @ResultCode = 0 ') +
        dbo.GTSFormatSQL('                END ') +
        dbo.GTSFormatSQL('                ELSE ') +
        dbo.GTSFormatSQL('                    SET @ResultCode = 5 ') +
        dbo.GTSFormatSQL('            END ') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        COMMIT TRANSACTION') +
        dbo.GTSFormatSQL('        SET @TotalReleased = @AvailableForRelease') +
        dbo.GTSFormatSQL('        RETURN @ResultCode        ') +
        dbo.GTSFormatSQL('    END TRY') +
        dbo.GTSFormatSQL('    BEGIN CATCH') +
        dbo.GTSFormatSQL('        ROLLBACK TRANSACTION     ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @ResultCode = 0') +
        dbo.GTSFormatSQL('            SET @ResultCode = 99 /*Unknown Exception*/') +
        dbo.GTSFormatSQL('        SELECT ERROR_MESSAGE()') +
        dbo.GTSFormatSQL('        RETURN(ERROR_NUMBER())        ') +
        dbo.GTSFormatSQL('    END CATCH') +
        dbo.GTSFormatSQL('END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_ReleaseHoldCapacity due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_ReleaseHoldCapacity created successfully.'

    Print N'Creating stored procedure GTS_SP_RM_MergeEvents...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_MergeEvents') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_MergeEvents

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_MergeEvents]') +
        dbo.GTSFormatSQL('    @SourceEventID int,') +
        dbo.GTSFormatSQL('    @DestinationEventID int,') +
        dbo.GTSFormatSQL('    @HoldCapacityFailoverMode int,') +
        dbo.GTSFormatSQL('    @EventSaleLimitsMode int,') +
        dbo.GTSFormatSQL('    @LastUpdate datetime,') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20)') +
        dbo.GTSFormatSQL('AS') +
        dbo.GTSFormatSQL('BEGIN') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */') +
        dbo.GTSFormatSQL('    DECLARE @CapacityMappings TABLE (CapacityID int, ResourceID int, CapacityType int, DestinationGeneralCapacityID int, DestinationCapacityID int, DestinationReleaseState int, QuantityMigrated int)') +
        dbo.GTSFormatSQL('    DECLARE @CapacityNeeded TABLE (CapacityID int, CapacityType int, QuantityMissing int)') +
        dbo.GTSFormatSQL('    DECLARE @CurrentOrderID int') +
        dbo.GTSFormatSQL('    DECLARE @CurrentRecordID int') +
        dbo.GTSFormatSQL('    DECLARE @CurrentRequiredQuantity int') +
        dbo.GTSFormatSQL('    DECLARE @DestinationCapacityID int') +
        dbo.GTSFormatSQL('    DECLARE @DestinationCapacityResourceID int') +
        dbo.GTSFormatSQL('    DECLARE @DestinationCapacityType int') +
        dbo.GTSFormatSQL('    DECLARE @DestinationEventTypeID int') +
        dbo.GTSFormatSQL('    DECLARE @DestinationGeneralCapacityID int') +
        dbo.GTSFormatSQL('    DECLARE @DestinationHasSequencedCapacity bit') +
        dbo.GTSFormatSQL('    DECLARE @DestinationReleaseState int') +
        dbo.GTSFormatSQL('    DECLARE @DestinationEventResourceID int') +
        dbo.GTSFormatSQL('    DECLARE @DestinationRSEventSeatMapID bit') +
        dbo.GTSFormatSQL('    DECLARE @DestinationSalesChannelCapacityLimitMode int') +
        dbo.GTSFormatSQL('    DECLARE @ResultCode int = 0') +
        dbo.GTSFormatSQL('    DECLARE @ResultErrors TABLE (ErrorCode int, CapacityID int NULL, Quantity int NULL, SalesChannelID int NULL, SQLErrorNumber int NULL)') +
        dbo.GTSFormatSQL('    DECLARE @RMTicketsSPResultsCode int') +
        dbo.GTSFormatSQL('    DECLARE @RowsAffected int') +
        dbo.GTSFormatSQL('    DECLARE @StartTranCount int') +
        dbo.GTSFormatSQL('    DECLARE @SourceCapacityID int') +
        dbo.GTSFormatSQL('    DECLARE @SourceEventTypeID int') +
        dbo.GTSFormatSQL('    DECLARE @SourceEventResourceID int') +
        dbo.GTSFormatSQL('    DECLARE @SourceRSEventSeatMapID bit') +
        dbo.GTSFormatSQL('    DECLARE @SourceSalesChannelCapacityLimitMode int') +
        dbo.GTSFormatSQL('    DECLARE @SourceSalesChannelID int') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SELECT @StartTranCount = @@TRANCOUNT') +
        dbo.GTSFormatSQL('    BEGIN TRY') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0') +
        dbo.GTSFormatSQL('            BEGIN TRANSACTION') +
        dbo.GTSFormatSQL('        ELSE') +
        dbo.GTSFormatSQL('            SAVE TRANSACTION LocalTran') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @SourceEventID = @DestinationEventID BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode) SELECT 1 /*SOURCE_EVENT_IS_DESTINATION*/') +
        dbo.GTSFormatSQL('            RAISERROR(''Source event cannot be the same as the Destination'', 16, 1 /*EVENTS_NOT_COMPATIBLE*/)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Deactivate Source Event') +
        dbo.GTSFormatSQL('        UPDATE RMEvents SET ActiveIndicator = 1, OffSaleDateTime = LastUpdate, RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('        WHERE EventID = @SourceEventID') +
        dbo.GTSFormatSQL('        IF @@ROWCOUNT <> 1 BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode) SELECT 2 /*SOURCE_EVENT_NOT_FOUND*/') +
        dbo.GTSFormatSQL('            RAISERROR(''Source event was not found'', 16, 1 /*EVENTS_NOT_COMPATIBLE*/)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        UPDATE EventSaleLimits SET OffSale = LastUpdate, RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('        WHERE EventID = @SourceEventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Update Destination Event so it is locked') +
        dbo.GTSFormatSQL('        UPDATE RMEvents SET RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('        WHERE EventID = @DestinationEventID') +
        dbo.GTSFormatSQL('        IF @@ROWCOUNT <> 1 BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode) SELECT 3 /*DESTINATION_EVENT_NOT_FOUND*/') +
        dbo.GTSFormatSQL('            RAISERROR(''Destination event was not found'', 16, 1 /*EVENTS_NOT_COMPATIBLE*/)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Verify destination is a suitable match for the merge') +
        dbo.GTSFormatSQL('        SELECT @SourceEventTypeID = EventTypeID, @SourceEventResourceID = ResourceID, @SourceSalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode, @SourceRSEventSeatMapID = RSEventSeatMapID FROM RMEvents WHERE EventID = @SourceEventID;') +
        dbo.GTSFormatSQL('        SELECT @DestinationEventTypeID = EventTypeID, @DestinationEventResourceID = ResourceID, @DestinationSalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode, @DestinationRSEventSeatMapID = RSEventSeatMapID, @DestinationHasSequencedCapacity = HasSequencedCapacity FROM RMEvents WHERE EventID = @DestinationEventID;') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @SourceEventTypeID <> @DestinationEventTypeID BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode) SELECT 4 /*EVENT_TYPE_MISMATCH*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @SourceEventResourceID <> @DestinationEventResourceID BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode) SELECT 5 /*RESOURCE_ID_MISMATCH*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @SourceSalesChannelCapacityLimitMode <> @DestinationSalesChannelCapacityLimitMode BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode) SELECT 6 /*CAPACITY_LIMIT_MODE_MISMATCH*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @SourceRSEventSeatMapID > 0 OR @DestinationRSEventSeatMapID > 0 BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode) SELECT 7 /*HAS_RESERVED_SEATS*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Map source capacity records to Destination capacity records') +
        dbo.GTSFormatSQL('        INSERT INTO @CapacityMappings') +
        dbo.GTSFormatSQL('            SELECT SC.CapacityID, SC.ResourceID, SC.CapacityType, TGC.CapacityID AS DestinationGeneralCapacityID, TC.CapacityID as DestinationCapacityID, COALESCE(TC.ReleaseState, 1 /*IS_RELEASABLE*/)  AS DestinationReleaseState, 0 AS QuantityMigrated') +
        dbo.GTSFormatSQL('            FROM RMCapacity SC') +
        dbo.GTSFormatSQL('            LEFT JOIN RMResources R ON R.ResourceID = SC.ResourceID') +
        dbo.GTSFormatSQL('            LEFT JOIN RMCapacity TGC ON TGC.EventID = @DestinationEventID AND TGC.ResourceID = SC.ResourceID AND TGC.CapacityType = 0 /*GENERAL_CAPACITY*/') +
        dbo.GTSFormatSQL('            OUTER APPLY (') +
        dbo.GTSFormatSQL('                SELECT TOP 1 TC.*') +
        dbo.GTSFormatSQL('                FROM RMCapacity TC') +
        dbo.GTSFormatSQL('                OUTER APPLY (') +
        dbo.GTSFormatSQL('                    SELECT COUNT(*) AS MissingHoldDetails') +
        dbo.GTSFormatSQL('                    FROM HoldDetails SHD') +
        dbo.GTSFormatSQL('                    LEFT JOIN HoldDetails THD ON THD.DetailType = SHD.DetailType AND THD.AuxID = TC.HoldGroupID AND THD.PLU = SHD.PLU AND THD.ItemGroupID = SHD.ItemGroupID') +
        dbo.GTSFormatSQL('                    WHERE SC.CapacityType = 1 /*HOLD_CAPACITY*/ AND SHD.DetailType = 1 /*EVENT_HOLD*/ AND SHD.AuxID = SC.HoldGroupID AND THD.HoldDetailID IS NULL') +
        dbo.GTSFormatSQL('                ) HD') +
        dbo.GTSFormatSQL('                WHERE TC.EventID = @DestinationEventID AND TC.ResourceID = SC.ResourceID AND TC.CapacityType = SC.CapacityType') +
        dbo.GTSFormatSQL('                    AND ((SC.CapacityType <> 1 /*HOLD_CAPACITY*/) OR (TC.Name = SC.Name AND HD.MissingHoldDetails = 0))') +
        dbo.GTSFormatSQL('            ) TC') +
        dbo.GTSFormatSQL('            WHERE SC.EventID = @SourceEventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Check for source capacities without a match') +
        dbo.GTSFormatSQL('        IF @HoldCapacityFailoverMode = 1 /*USE_GENERAL*/ BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode, CapacityID)') +
        dbo.GTSFormatSQL('                SELECT 8 /*CAPACITY_MATCH_NOT_FOUND*/, CapacityID') +
        dbo.GTSFormatSQL('                FROM @CapacityMappings') +
        dbo.GTSFormatSQL('                WHERE DestinationCapacityID IS NULL AND DestinationGeneralCapacityID IS NULL') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        ELSE BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode, CapacityID)') +
        dbo.GTSFormatSQL('                SELECT 8 /*CAPACITY_MATCH_NOT_FOUND*/, CapacityID') +
        dbo.GTSFormatSQL('                FROM @CapacityMappings') +
        dbo.GTSFormatSQL('                WHERE DestinationCapacityID IS NULL') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Check for non-order based pending capacities') +
        dbo.GTSFormatSQL('        INSERT INTO @ResultErrors (ErrorCode, CapacityID, Quantity)') +
        dbo.GTSFormatSQL('            SELECT 9 /*PENDING_CAPACITY_FOUND*/, CapacityID, Sum(HoldQuantity)') +
        dbo.GTSFormatSQL('            FROM RMCapacityHold') +
        dbo.GTSFormatSQL('            WHERE EventID = @SourceEventID AND GroupIDType <> 1 /*CAPGRP_ORDER*/ GROUP BY CapacityID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @EventSaleLimitsMode = 1 /*MERGE_EVENT_SALE_LIMITS_MODE_QUANTITY*/ BEGIN') +
        dbo.GTSFormatSQL('            -- Check for source sales channels with invalid capacity units') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode)') +
        dbo.GTSFormatSQL('                SELECT DISTINCT 13 /*SOURCE_INVALID_CAPACITY_UNIT*/') +
        dbo.GTSFormatSQL('                FROM EventSaleLimits') +
        dbo.GTSFormatSQL('                WHERE EventID = @SourceEventID AND CapacityUnit <> 1 /*QUANTITY_CAPACITY_UNIT*/') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Check for destination sales channels with invalid capacity units') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode)') +
        dbo.GTSFormatSQL('                SELECT DISTINCT 14 /*DESTINATION_INVALID_CAPACITY_UNIT*/') +
        dbo.GTSFormatSQL('                FROM EventSaleLimits') +
        dbo.GTSFormatSQL('                WHERE EventID = @DestinationEventID AND CapacityUnit <> 1 /*QUANTITY_CAPACITY_UNIT*/') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Check for source sales channel limits without a match') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode, SalesChannelID)') +
        dbo.GTSFormatSQL('                SELECT 15 /*SALES_CHANNEL_MATCH_NOT_FOUND*/, SL.SalesChannelID') +
        dbo.GTSFormatSQL('                FROM EventSaleLimits SL') +
        dbo.GTSFormatSQL('                LEFT JOIN EventSaleLimits SLP ON SLP.EventID = SL.EventID AND SLP.EventSaleLimitID = SL.ParentEventSaleLimitID') +
        dbo.GTSFormatSQL('                LEFT JOIN EventSaleLimits TL ON TL.EventID = @DestinationEventID AND SL.SalesChannelID = TL.SalesChannelID') +
        dbo.GTSFormatSQL('                LEFT JOIN EventSaleLimits TLP ON TLP.EventID = TL.EventID AND TLP.EventSaleLimitID = TL.ParentEventSaleLimitID') +
        dbo.GTSFormatSQL('                WHERE SL.EventID = @SourceEventID AND (TL.SalesChannelID IS NULL OR SLP.SalesChannelID <> TLP.SalesChannelID)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF EXISTS(SELECT 1 FROM @ResultErrors) BEGIN') +
        dbo.GTSFormatSQL('            RAISERROR(''The specified events are not compatible'', 16, 1 /*EVENTS_NOT_COMPATIBLE*/)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Keep track of missing capacities') +
        dbo.GTSFormatSQL('        INSERT INTO @CapacityNeeded') +
        dbo.GTSFormatSQL('            SELECT TC.CapacityID, TC.CapacityType, 0 AS QuantityMissing') +
        dbo.GTSFormatSQL('            FROM RMCapacity TC') +
        dbo.GTSFormatSQL('            LEFT JOIN RMResources R ON R.ResourceID = TC.ResourceID') +
        dbo.GTSFormatSQL('            WHERE EventID = @DestinationEventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Migrate ticket capacities') +
        dbo.GTSFormatSQL('        DECLARE TicketCursor CURSOR LOCAL STATIC FORWARD_ONLY READ_ONLY FOR') +
        dbo.GTSFormatSQL('            SELECT TicketID, CapacityID, SalesChannelID, Qty') +
        dbo.GTSFormatSQL('            FROM Tickets') +
        dbo.GTSFormatSQL('            WHERE EventNo = @SourceEventID') +
        dbo.GTSFormatSQL('            ORDER BY TicketID') +
        dbo.GTSFormatSQL('        OPEN TicketCursor') +
        dbo.GTSFormatSQL('        FETCH NEXT FROM TicketCursor INTO @CurrentRecordID, @SourceCapacityID, @SourceSalesChannelID, @CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('        WHILE (@@FETCH_STATUS = 0) BEGIN') +
        dbo.GTSFormatSQL('            -- Lookup Destination Capacity') +
        dbo.GTSFormatSQL('            SELECT @DestinationCapacityType = CapacityType, @DestinationCapacityResourceID = ResourceID, @DestinationGeneralCapacityID = DestinationGeneralCapacityID, @DestinationCapacityID = DestinationCapacityID, @DestinationReleaseState = DestinationReleaseState') +
        dbo.GTSFormatSQL('            FROM @CapacityMappings') +
        dbo.GTSFormatSQL('            WHERE CapacityID = @SourceCapacityID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            IF @DestinationCapacityID IS NULL OR (@DestinationCapacityType = 1 /*HOLD_CAPACITY*/ AND @DestinationReleaseState = 2 /*WAS_RELEASED*/) BEGIN') +
        dbo.GTSFormatSQL('                SET @RMTicketsSPResultsCode = 2 /*UpdateRMCapacityFailed*/') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            ELSE BEGIN') +
        dbo.GTSFormatSQL('                -- Attempt to sell the ticket from the mapped capacity') +
        dbo.GTSFormatSQL('                EXECUTE [dbo].[GTS_SP_RM_Sell_Tickets]') +
        dbo.GTSFormatSQL('                    @DestinationEventID') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityResourceID') +
        dbo.GTSFormatSQL('                    ,@SourceSalesChannelID') +
        dbo.GTSFormatSQL('                    ,@CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityType') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityID') +
        dbo.GTSFormatSQL('                    ,@LastUpdate') +
        dbo.GTSFormatSQL('                    ,@LastUpdatedBy') +
        dbo.GTSFormatSQL('                    ,@RMTicketsSPResultsCode OUTPUT') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Attempt to sell the ticket from the mapped general capacity if allowed') +
        dbo.GTSFormatSQL('            IF @RMTicketsSPResultsCode <> 0 AND @DestinationCapacityType = 1 /*HOLD_CAPACITY*/ AND @DestinationReleaseState <> 0 /*NOT_RELEASABLE*/ AND @HoldCapacityFailoverMode = 1 /*USE_GENERAL*/ BEGIN') +
        dbo.GTSFormatSQL('                SET @DestinationCapacityID = @DestinationGeneralCapacityID') +
        dbo.GTSFormatSQL('                EXECUTE [dbo].[GTS_SP_RM_Sell_Tickets]') +
        dbo.GTSFormatSQL('                    @DestinationEventID') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityResourceID') +
        dbo.GTSFormatSQL('                    ,@SourceSalesChannelID') +
        dbo.GTSFormatSQL('                    ,@CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('                    ,0 /*GENERAL_CAPACITY*/') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityID') +
        dbo.GTSFormatSQL('                    ,@LastUpdate') +
        dbo.GTSFormatSQL('                    ,@LastUpdatedBy') +
        dbo.GTSFormatSQL('                    ,@RMTicketsSPResultsCode OUTPUT') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            IF @RMTicketsSPResultsCode = 0 BEGIN') +
        dbo.GTSFormatSQL('                -- Capacity movement was successful') +
        dbo.GTSFormatSQL('                UPDATE Tickets SET EventNo = @DestinationEventID, CapacityID = @DestinationCapacityID, RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                WHERE TicketID = @CurrentRecordID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('                UPDATE @CapacityMappings SET QuantityMigrated = QuantityMigrated + @CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('                WHERE CapacityID = @SourceCapacityID') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            ELSE BEGIN') +
        dbo.GTSFormatSQL('                -- Capacity movement failed') +
        dbo.GTSFormatSQL('                UPDATE @CapacityNeeded SET QuantityMissing = QuantityMissing + @CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('                WHERE CapacityID = @DestinationCapacityID') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            FETCH NEXT FROM TicketCursor INTO @CurrentRecordID, @SourceCapacityID, @SourceSalesChannelID, @CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        CLOSE TicketCursor') +
        dbo.GTSFormatSQL('        DEALLOCATE TicketCursor') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Migrate unissued order line capacities') +
        dbo.GTSFormatSQL('        DECLARE OrderLineCursor CURSOR LOCAL STATIC FORWARD_ONLY READ_ONLY FOR') +
        dbo.GTSFormatSQL('            SELECT OrderLineID, OrderID, CapacityID, SalesChannelID, Quantity') +
        dbo.GTSFormatSQL('            FROM OrderLines') +
        dbo.GTSFormatSQL('            WHERE EventID = @SourceEventID AND IssuedQuantity = 0') +
        dbo.GTSFormatSQL('            ORDER BY OrderLineID') +
        dbo.GTSFormatSQL('        OPEN OrderLineCursor') +
        dbo.GTSFormatSQL('        FETCH NEXT FROM OrderLineCursor INTO @CurrentRecordID, @CurrentOrderID, @SourceCapacityID, @SourceSalesChannelID, @CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('        WHILE (@@FETCH_STATUS = 0) BEGIN') +
        dbo.GTSFormatSQL('            -- Lookup Destination Capacity') +
        dbo.GTSFormatSQL('            SELECT @DestinationCapacityType = CapacityType, @DestinationCapacityResourceID = ResourceID, @DestinationGeneralCapacityID = DestinationGeneralCapacityID, @DestinationCapacityID = DestinationCapacityID, @DestinationReleaseState = DestinationReleaseState') +
        dbo.GTSFormatSQL('            FROM @CapacityMappings') +
        dbo.GTSFormatSQL('            WHERE CapacityID = @SourceCapacityID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            IF @DestinationCapacityID IS NULL OR (@DestinationCapacityType = 1 /*HOLD_CAPACITY*/ AND @DestinationReleaseState = 2 /*WAS_RELEASED*/) BEGIN') +
        dbo.GTSFormatSQL('                SET @RMTicketsSPResultsCode = 2 /*UpdateRMCapacityFailed*/') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            ELSE BEGIN') +
        dbo.GTSFormatSQL('                -- Attempt to hold the ticket from the mapped capacity') +
        dbo.GTSFormatSQL('                EXECUTE [dbo].[GTS_SP_RM_HoldTickets]') +
        dbo.GTSFormatSQL('                    @DestinationEventID') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityResourceID') +
        dbo.GTSFormatSQL('                    ,@CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('                    ,0 /*@NodeNo*/') +
        dbo.GTSFormatSQL('                    ,1 /*@GroupIDType = CAPGRP_ORDER*/') +
        dbo.GTSFormatSQL('                    ,@CurrentOrderID /*@GroupID*/') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityType') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityID') +
        dbo.GTSFormatSQL('                    ,@LastUpdate') +
        dbo.GTSFormatSQL('                    ,@LastUpdatedBy') +
        dbo.GTSFormatSQL('                    ,0 /*@NewUniqueHoldID*/') +
        dbo.GTSFormatSQL('                    ,0 /*@ExistingUniqueHoldID*/') +
        dbo.GTSFormatSQL('                    ,@RMTicketsSPResultsCode OUTPUT') +
        dbo.GTSFormatSQL('                    ,0 /*@IgnoreCapacity*/') +
        dbo.GTSFormatSQL('                    ,@SourceSalesChannelID') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Attempt to hold the ticket from the mapped general capacity if allowed') +
        dbo.GTSFormatSQL('            IF @RMTicketsSPResultsCode <> 0 AND @DestinationCapacityType = 1 /*HOLD_CAPACITY*/ AND @DestinationReleaseState <> 0 /*NOT_RELEASABLE*/ AND @HoldCapacityFailoverMode = 1 /*USE_GENERAL*/ BEGIN') +
        dbo.GTSFormatSQL('                SET @DestinationCapacityID = @DestinationGeneralCapacityID') +
        dbo.GTSFormatSQL('                EXECUTE [dbo].[GTS_SP_RM_HoldTickets]') +
        dbo.GTSFormatSQL('                    @DestinationEventID') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityResourceID') +
        dbo.GTSFormatSQL('                    ,@CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('                    ,0 /*@NodeNo*/') +
        dbo.GTSFormatSQL('                    ,1 /*@GroupIDType = CAPGRP_ORDER*/') +
        dbo.GTSFormatSQL('                    ,@CurrentOrderID /*@GroupID*/') +
        dbo.GTSFormatSQL('                    ,0 /*GENERAL_CAPACITY*/') +
        dbo.GTSFormatSQL('                    ,@DestinationCapacityID') +
        dbo.GTSFormatSQL('                    ,@LastUpdate') +
        dbo.GTSFormatSQL('                    ,@LastUpdatedBy') +
        dbo.GTSFormatSQL('                    ,0 /*@NewUniqueHoldID*/') +
        dbo.GTSFormatSQL('                    ,0 /*@ExistingUniqueHoldID*/') +
        dbo.GTSFormatSQL('                    ,@RMTicketsSPResultsCode OUTPUT') +
        dbo.GTSFormatSQL('                    ,0 /*@IgnoreCapacity*/') +
        dbo.GTSFormatSQL('                    ,@SourceSalesChannelID') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            IF @RMTicketsSPResultsCode = 0 BEGIN') +
        dbo.GTSFormatSQL('                -- Capacity movement was successful') +
        dbo.GTSFormatSQL('                UPDATE OrderLines SET EventID = @DestinationEventID, CapacityID = @DestinationCapacityID, RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                WHERE OrderLineID = @CurrentRecordID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('                UPDATE @CapacityMappings SET QuantityMigrated = QuantityMigrated + @CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('                WHERE CapacityID = @SourceCapacityID') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            ELSE BEGIN') +
        dbo.GTSFormatSQL('                -- Capacity movement failed') +
        dbo.GTSFormatSQL('                UPDATE @CapacityNeeded SET QuantityMissing = QuantityMissing + @CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('                WHERE CapacityID = @DestinationCapacityID') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            FETCH NEXT FROM OrderLineCursor INTO @CurrentRecordID, @CurrentOrderID, @SourceCapacityID, @SourceSalesChannelID, @CurrentRequiredQuantity') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        CLOSE OrderLineCursor') +
        dbo.GTSFormatSQL('        DEALLOCATE OrderLineCursor') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Fail if any capacity was not available') +
        dbo.GTSFormatSQL('        INSERT INTO @ResultErrors (ErrorCode, CapacityID, Quantity)') +
        dbo.GTSFormatSQL('            SELECT 10 /*CAPACITY_UNAVAILABLE*/, CapacityID, QuantityMissing') +
        dbo.GTSFormatSQL('            FROM @CapacityNeeded') +
        dbo.GTSFormatSQL('            WHERE QuantityMissing > 0') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF EXISTS(SELECT 1 FROM @ResultErrors) BEGIN') +
        dbo.GTSFormatSQL('            RAISERROR(''The destination event does not have enough capacity available'', 16, 2 /*CAPACITY_UNAVAILABLE*/)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Fail if any capacity was not migrated') +
        dbo.GTSFormatSQL('        INSERT INTO @ResultErrors (ErrorCode, CapacityID, Quantity)') +
        dbo.GTSFormatSQL('            SELECT 11 /*CAPACITY_NOT_MIGRATED*/, C.CapacityID, C.Sold + C.QuantityOnHold - M.QuantityMigrated') +
        dbo.GTSFormatSQL('            FROM RMCapacity C') +
        dbo.GTSFormatSQL('            JOIN @CapacityMappings M ON C.CapacityID = M.CapacityID') +
        dbo.GTSFormatSQL('            WHERE C.Sold + C.QuantityOnHold - M.QuantityMigrated <> 0') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Fail if nothing was migrated') +
        dbo.GTSFormatSQL('        IF EXISTS(SELECT 1 FROM @CapacityMappings HAVING SUM(QuantityMigrated) = 0) BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode) SELECT 12 /*CAPACITY_NONE_MIGRATED*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF EXISTS(SELECT 1 FROM @ResultErrors) BEGIN') +
        dbo.GTSFormatSQL('            RAISERROR(''The source event has capacity that was not migrated'', 16, 3 /*CAPACITY_NOT_MIGRATED*/)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Clear out source event capacity values') +
        dbo.GTSFormatSQL('        UPDATE RMSalesChannelCapacity SET Sold = 0, QuantityOnHold = 0, RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('        WHERE CapacityID IN (SELECT CapacityID FROM RMCapacity WHERE EventID = @SourceEventID)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        UPDATE RMCapacity SET Available = 0, Sold = 0, QuantityOnHold = 0, TotalCapacity = 0, ReleasedCapacity = 0, RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('        WHERE EventID = @SourceEventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        DELETE FROM RMSalesChannelCapacityHold') +
        dbo.GTSFormatSQL('        WHERE RMCapacityHoldUID IN (SELECT RMCapacityHoldUID FROM RMCapacityHold WHERE EventID = @SourceEventID AND GroupIDType = 1 /*CAPGRP_ORDER*/)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        DELETE FROM RMCapacityHold') +
        dbo.GTSFormatSQL('        WHERE EventID = @SourceEventID AND GroupIDType = 1 /*CAPGRP_ORDER*/') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Migrate Event Sale Limit quantities') +
        dbo.GTSFormatSQL('        IF @EventSaleLimitsMode = 1 /*MERGE_EVENT_SALE_LIMITS_MODE_QUANTITY*/ BEGIN') +
        dbo.GTSFormatSQL('            DECLARE @DestinationTotalCapacity int') +
        dbo.GTSFormatSQL('            IF @DestinationHasSequencedCapacity = 1 BEGIN') +
        dbo.GTSFormatSQL('                SELECT @DestinationTotalCapacity = SUM(CASE WHEN RMCapacity.ReleaseState = 2 /*WAS_RELEASED*/ THEN RMCapacity.TotalCapacity - RMCapacity.ReleasedCapacity ELSE RMCapacity.TotalCapacity END)') +
        dbo.GTSFormatSQL('                FROM RMCapacity') +
        dbo.GTSFormatSQL('                WHERE RMCapacity.EventID = @DestinationEventID') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            ELSE BEGIN') +
        dbo.GTSFormatSQL('                SELECT @DestinationTotalCapacity = SUM(CASE WHEN RMCapacity.ReleaseState = 2 /*WAS_RELEASED*/ THEN RMCapacity.TotalCapacity - RMCapacity.ReleasedCapacity ELSE RMCapacity.TotalCapacity END)') +
        dbo.GTSFormatSQL('                FROM RMCapacity') +
        dbo.GTSFormatSQL('                JOIN dbo.RMResources ON RMResources.ResourceID = RMCapacity.ResourceID') +
        dbo.GTSFormatSQL('                WHERE RMCapacity.EventID = @DestinationEventID AND ((RMCapacity.ResourceID = @DestinationEventResourceID) OR (RMResources.AncestorID = @DestinationEventResourceID))') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            UPDATE TL SET') +
        dbo.GTSFormatSQL('                Capacity = CASE WHEN TL.Capacity + SL.Capacity > @DestinationTotalCapacity THEN @DestinationTotalCapacity ELSE TL.Capacity + SL.Capacity END,') +
        dbo.GTSFormatSQL('                RecordVersion = TL.RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('            FROM EventSaleLimits TL') +
        dbo.GTSFormatSQL('            JOIN EventSaleLimits SL ON SL.EventID = @SourceEventID AND SL.SalesChannelID = TL.SalesChannelID') +
        dbo.GTSFormatSQL('            WHERE TL.EventID = @DestinationEventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            UPDATE EventSaleLimits SET Capacity = 0, RecordVersion = RecordVersion + 1, LastUpdate = @LastUpdate, LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('            WHERE EventID = @SourceEventID') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0 COMMIT TRANSACTION') +
        dbo.GTSFormatSQL('        END TRY') +
        dbo.GTSFormatSQL('    BEGIN CATCH') +
        dbo.GTSFormatSQL('        DECLARE @ERROR_NUMBER INT = ERROR_NUMBER();') +
        dbo.GTSFormatSQL('        DECLARE @ERROR_STATE INT = ERROR_STATE();') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0') +
        dbo.GTSFormatSQL('            ROLLBACK TRANSACTION') +
        dbo.GTSFormatSQL('        ELSE') +
        dbo.GTSFormatSQL('            ROLLBACK TRANSACTION LocalTran') +
        dbo.GTSFormatSQL('        IF @ERROR_NUMBER = 50000 BEGIN') +
        dbo.GTSFormatSQL('            SET @ResultCode = @ERROR_STATE') +
        dbo.GTSFormatSQL('            IF @ResultCode = 0 SET @ResultCode = 1 /*EVENTS_NOT_COMPATIBLE*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        ELSE BEGIN') +
        dbo.GTSFormatSQL('            INSERT INTO @ResultErrors (ErrorCode, SQLErrorNumber) VALUES (99 /*SQL_ERROR*/, @ERROR_NUMBER)') +
        dbo.GTSFormatSQL('            IF @ResultCode = 0 SET @ResultCode = 99 /*SQL_ERROR*/') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        END CATCH') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SELECT * FROM @ResultErrors') +
        dbo.GTSFormatSQL('    RETURN @ResultCode') +
        dbo.GTSFormatSQL('END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_MergeEvents due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_MergeEvents created successfully.'

    Print N'Creating stored procedure GTS_SP_RM_DeleteEvent...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_SP_RM_DeleteEvent') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTS_SP_RM_DeleteEvent

    SET @SQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_SP_RM_DeleteEvent]') +
        dbo.GTSFormatSQL('    @EventID Int,') +
        dbo.GTSFormatSQL('    @ResultCode Int OUTPUT') +
        dbo.GTSFormatSQL('AS') +
        dbo.GTSFormatSQL('BEGIN') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported */') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    DECLARE') +
        dbo.GTSFormatSQL('        @StartTranCount Int,') +
        dbo.GTSFormatSQL('        @ReservationID Int,') +
        dbo.GTSFormatSQL('        @AttributeValueGroupID Int,') +
        dbo.GTSFormatSQL('        @RosterAttributeGroupID Int,') +
        dbo.GTSFormatSQL('        @NotesID Int,') +
        dbo.GTSFormatSQL('        @SalesChannelCapacityLimitMode Int,') +
        dbo.GTSFormatSQL('        @HasSequencedCapacity Bit,') +
        dbo.GTSFormatSQL('        @SoldCapacityID Int,') +
        dbo.GTSFormatSQL('        @RSEventSeatMapID Int,') +
        dbo.GTSFormatSQL('        @HasWaitList Bit') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SET @ResultCode = 0 ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SELECT @StartTranCount = @@TRANCOUNT ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    BEGIN TRY ') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('            BEGIN TRANSACTION ') +
        dbo.GTSFormatSQL('        ELSE ') +
        dbo.GTSFormatSQL('            SAVE TRANSACTION LocalTran ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Check for valid EventID') +
        dbo.GTSFormatSQL('        IF @EventID = 0 BEGIN') +
        dbo.GTSFormatSQL('            SET @ResultCode = 1') +
        dbo.GTSFormatSQL('            RAISERROR (''Invalid Event ID'', 16, 1)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Gather additional event information') +
        dbo.GTSFormatSQL('        SELECT') +
        dbo.GTSFormatSQL('            @ReservationID = ResourceReservationID,') +
        dbo.GTSFormatSQL('            @AttributeValueGroupID = AttributeValueGroupID,') +
        dbo.GTSFormatSQL('            @RosterAttributeGroupID = RosterAttributeGroupID,') +
        dbo.GTSFormatSQL('            @NotesID = NotesID,') +
        dbo.GTSFormatSQL('            @SalesChannelCapacityLimitMode = SalesChannelCapacityLimitMode,') +
        dbo.GTSFormatSQL('            @HasSequencedCapacity = HasSequencedCapacity,') +
        dbo.GTSFormatSQL('            @RSEventSeatMapID = RSEventSeatMapID,') +
        dbo.GTSFormatSQL('            @HasWaitList = HasWaitList') +
        dbo.GTSFormatSQL('        FROM RMEvents') +
        dbo.GTSFormatSQL('        WHERE EventID = @EventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Check for valid ReservationID') +
        dbo.GTSFormatSQL('        IF @HasSequencedCapacity = 0 AND @ReservationID = 0 BEGIN') +
        dbo.GTSFormatSQL('            SET @ResultCode = 2') +
        dbo.GTSFormatSQL('            RAISERROR (''Invalid Reservation ID'', 16, 1)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Check for any tickets sold or onhold for this event') +
        dbo.GTSFormatSQL('        SELECT TOP 1 @SoldCapacityID = RMCapacity.CapacityID') +
        dbo.GTSFormatSQL('        FROM RMCapacity') +
        dbo.GTSFormatSQL('        LEFT JOIN (SELECT TOP 1 EventNo FROM JnlTickets WHERE EventNo = @EventID) JnlTickets ON JnlTickets.EventNo = @EventID') +
        dbo.GTSFormatSQL('        WHERE EventID = @EventID') +
        dbo.GTSFormatSQL('        AND (RMCapacity.Sold <> 0 OR RMCapacity.QuantityOnHold <> 0 OR JnlTickets.EventNo IS NOT NULL) ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @SoldCapacityID > 0  BEGIN') +
        dbo.GTSFormatSQL('            SET @ResultCode = 3') +
        dbo.GTSFormatSQL('            RAISERROR (''Tickets have been sold or are pending for the event.'', 16, 1)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @RSEventSeatMapID <> 0 BEGIN') +
        dbo.GTSFormatSQL('            IF (SELECT TOP 1 RSEventSeatMapID') +
        dbo.GTSFormatSQL('            FROM RSEventSeatMaps') +
        dbo.GTSFormatSQL('            WHERE EventID = @EventID AND ((Sold <> 0) OR (Reserved <> 0))) > 0 BEGIN') +
        dbo.GTSFormatSQL('                SET @ResultCode = 4') +
        dbo.GTSFormatSQL('                RAISERROR (''Reserved seat tickets have been sold or are pending for the event.'', 16, 1)') +
        dbo.GTSFormatSQL('                END') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Make sure the WaitList is empty ') +
        dbo.GTSFormatSQL('        IF (@HasWaitList = 1) AND ((SELECT COUNT(*) FROM WaitLists WHERE EventID = @EventID)  > 0) BEGIN') +
        dbo.GTSFormatSQL('            SET @ResultCode = 5') +
        dbo.GTSFormatSQL('            RAISERROR (''The waitlist is not empty.'', 16, 1)') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete the RMReservations associated with the event') +
        dbo.GTSFormatSQL('        DELETE FROM RMReservations WHERE EventID = @EventID OR ReservationID = @ReservationID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete HoldDetails before RMCapacity is deleted') +
        dbo.GTSFormatSQL('        DELETE FROM HoldDetails WHERE DetailType = 1 and AuxID IN') +
        dbo.GTSFormatSQL('            (SELECT HoldGroupID FROM RMCapacity WHERE EventID = @EventID AND CapacityType = 1)') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete the EventSaleLimits associated with the event') +
        dbo.GTSFormatSQL('        DELETE FROM EventSaleLimits WHERE EventID = @EventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete the AttributeValues associated with this event') +
        dbo.GTSFormatSQL('        IF @AttributeValueGroupID > 0 BEGIN') +
        dbo.GTSFormatSQL('            DELETE FROM AttributeValues WHERE AttributeValueGroupID = @AttributeValueGroupID') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete the roster AttributeDefinitionGroups associated with this event') +
        dbo.GTSFormatSQL('        IF @RosterAttributeGroupID > 0 BEGIN') +
        dbo.GTSFormatSQL('            DELETE FROM AttributeDefinitionGroups WHERE AttributeGroupID = @RosterAttributeGroupID') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete the GxFileConnections associated with the event') +
        dbo.GTSFormatSQL('        DELETE FROM GxFileConnections WHERE ConnectionType = 2 AND ConnectionID = @EventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete the Notes record associated with the event') +
        dbo.GTSFormatSQL('        IF @NotesID > 0 BEGIN') +
        dbo.GTSFormatSQL('            DELETE FROM Notes WHERE NoteID = @NotesID') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete all RMCapacity/RMSalesChannelCapacity records associated with the event') +
        dbo.GTSFormatSQL('        IF @SalesChannelCapacityLimitMode = 1 BEGIN') +
        dbo.GTSFormatSQL('            DELETE RMSalesChannelCapacity FROM RMSalesChannelCapacity') +
        dbo.GTSFormatSQL('            JOIN RMCapacity ON RMCapacity.CapacityID = RMSalesChannelCapacity.CapacityID') +
        dbo.GTSFormatSQL('            WHERE RMCapacity.EventID = @EventID') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        DELETE FROM RMCapacity WHERE EventID = @EventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Delete the RMEvents record itself') +
        dbo.GTSFormatSQL('        DELETE FROM RMEvents WHERE EventID = @EventID') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0 COMMIT TRANSACTION ') +
        dbo.GTSFormatSQL('        END TRY ') +
        dbo.GTSFormatSQL('    BEGIN CATCH ') +
        dbo.GTSFormatSQL('        IF @StartTranCount = 0 ') +
        dbo.GTSFormatSQL('            ROLLBACK TRANSACTION ') +
        dbo.GTSFormatSQL('        ELSE ') +
        dbo.GTSFormatSQL('            ROLLBACK TRANSACTION LocalTran ') +
        dbo.GTSFormatSQL('        END CATCH ') +
        dbo.GTSFormatSQL('END')

    EXEC sp_executesql @SQL
    SELECT @Err = @@Error
    IF @Err > 0 PRINT N'Unable to create stored procedure GTS_SP_RM_DeleteEvent due to an error.'
    ELSE PRINT N'Stored procedure GTS_SP_RM_DeleteEvent created successfully.'

GO

PRINT ' '
PRINT '    ' + 'Completed creating Resource Management stored procedures...'
PRINT ' '
/*************** END OF RESOURCE MANAGEMENT STORED PROCEDURES SECTION ******************/

/*************** START OF PRICING SERVICE STORED PROCEDURES SECTION ******************/
PRINT 'Creating GTS_SP_Purge_ApiUsage stored procedure...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
    WHERE (o.name = 'GTS_SP_Purge_ApiUsage') AND (o.type = 'P')
    AND   (o.uid = u.uid)
    AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTS_SP_Purge_ApiUsage
GO

/***
================================================================================
Name        : GTS_SP_Purge_ApiUsage
Author      : JWF
Description : Purges old ApiUsage rows.

This code and all contents are copyright Gateway Ticketing Systems Inc.,
all rights reserved.

===============================================================================
Parameters   :

Name                  | I/O   | Description
--------------------------------------------------------------------------------
@pi_RetentionPeriodDays I       Data older than this many days will be purged.
@pi_ApplicationName     I       Filter what rows to be purged by Application
@pi_BatchSize           I       Determines how many rows will be deleted on each pass.
@pi_ForRealFl           I       If set to 0, the procedure will not actually delete anything.

Result Set:

Column Name   | Data Type       | Source Procedure        | Description
--------------------------------------------------------------------------------
If record set is retuned give brief description of the fields being returned

Return Value: Return code
     Success : 0
     Failure : Error number and Description

Revisions    :
--------------------------------------------------------------------------------
Ini|   Date   | Description
--------------------------------------------------------------------------------
================================================================================
***/

CREATE PROCEDURE [dbo].[GTS_SP_Purge_ApiUsage]
	-- Add the parameters for the stored procedure here
  @pi_RetentionPeriodDays smallint = 30,
  @pi_Application nvarchar(50) = NULL,
  @pi_BatchSize int = 1000000,
  @pi_ForRealFl bit = 1,
  @pi_Database sysname = NULL
AS

SET NOCOUNT ON;

DECLARE @PurgeDate date,
        @RowsRemaining bigint = 0,
        @RowsDeleted bigint = 0,
        @RowsDeletedCurrent bigint = 0,
        @CurrentTime varchar(100),
        @SQL nvarchar(4000),
        @DatabaseName sysname,
        @HasTable bit;

SET @PurgeDate = DATEADD(day, -@pi_RetentionPeriodDays, dateadd(day, datediff(day, 0, CURRENT_TIMESTAMP), 0));

DECLARE @DB_Table TABLE
(
  DatabaseName sysname PRIMARY KEY
);

IF object_id('tempdb..#ApiUsage') is not null
  drop table #ApiUsage;
create table #ApiUsage
(
  ApiUsageID int NOT NULL PRIMARY KEY
);

DECLARE DB_Cursor CURSOR FAST_FORWARD FOR
  SELECT dt.DatabaseName
    FROM @DB_Table dt;

BEGIN TRY

IF @pi_Database IS NULL
  -- Get a list of online non system databases
  INSERT INTO @DB_Table
  (
    DatabaseName
  )
  SELECT d.name
    FROM sys.databases d LEFT JOIN sys.dm_hadr_database_replica_states s
          ON d.database_id = s.database_id
         LEFT JOIN sys.dm_hadr_availability_group_states g
          ON g.group_id = s.group_id
   WHERE d.database_id > 4 -- exclude system databases
         AND d.state_desc = 'ONLINE'
         AND d.is_read_only = 0 -- exclude those DBs that are not read_write;
         AND (g.primary_replica = @@SERVERNAME OR g.primary_replica IS NULL)
	     AND (s.is_local = 1 or s.is_local is null)
  ORDER BY d.name ASC;
ELSE
  INSERT INTO @DB_Table
  (
      DatabaseName
  )
  VALUES
  (
      @pi_Database -- DatabaseName - sysname
  );

-- Loop over the databases and purge from those that have the table.
OPEN DB_Cursor;

WHILE 1=1 BEGIN

  FETCH DB_Cursor INTO @DatabaseName;
  IF @@FETCH_STATUS <> 0 BREAK;

  SET @SQL =
  'IF EXISTS (
    SELECT 1
      FROM ' + QUOTENAME(@DatabaseName) + '.INFORMATION_SCHEMA.TABLES
     WHERE TABLE_NAME = ''ApiUsage'')
    SET @HasTable = 1;
  ELSE
    SET @HasTable = 0;';

  EXEC sp_executesql @sql, N'@HasTable bit OUTPUT', @HasTable = @HasTable OUTPUT;

  -- If the table exists...
  IF @HasTable = 1 BEGIN

    -- Reset counts
    SET @RowsDeleted = 0;
    SET @RowsDeletedCurrent = 0;

    -- Create the synonym for the table
    IF EXISTS (
      SELECT 1
        FROM sys.synonyms s
       WHERE s.name = 'ApiUsage_PurgeSyn'
    )
      DROP SYNONYM dbo.ApiUsage_PurgeSyn;

    SET @SQL = 'CREATE SYNONYM dbo.ApiUsage_PurgeSyn FOR ' + QUOTENAME(@DatabaseName) + '.dbo.ApiUsage;';
    EXEC sp_executesql @SQL;

    -- Perform the purge operation
    SET @CurrentTime = CONVERT(varchar, CURRENT_TIMESTAMP, 121);
    RAISERROR('%s::Beginning purge process for database %s.',
              10,
              1,
              @CurrentTime,
              @DatabaseName,
              @RowsRemaining) WITH NOWAIT;

    TRUNCATE TABLE #ApiUsage;
    INSERT INTO #ApiUsage
    (
        ApiUsageID
    )
    SELECT a.ApiUsageID
      FROM dbo.ApiUsage_PurgeSyn a
     WHERE (a.Timestamp <= @PurgeDate)
	 AND ((@pi_Application IS NULL) OR (a.Application = @pi_Application))
    OPTION (RECOMPILE);

    SET @CurrentTime = CONVERT(varchar, CURRENT_TIMESTAMP, 121);
    RAISERROR('%s::Beginning purge process for database %s, ApiUsage. There are approximately %I64d rows left to delete.',
              10,
              1,
              @CurrentTime,
              @DatabaseName,
              @RowsRemaining) WITH NOWAIT;

    -- Begin ApiUsage purge
    SELECT @RowsRemaining = count(1)
      FROM dbo.ApiUsage_PurgeSyn a JOIN #ApiUsage u
            ON a.ApiUsageID = u.ApiUsageID;

    SET @CurrentTime = CONVERT(varchar,CURRENT_TIMESTAMP,121);
    RAISERROR('%s::Beginning purge process for database %s, ApiUsage. There are approximately %I64d rows left to delete.',
              10,
              1,
              @CurrentTime,
              @DatabaseName,
              @RowsRemaining) WITH NOWAIT;

    WHILE (1=1 AND @pi_ForRealFl = 1) BEGIN

      RAISERROR(' Beginning delete...',10,1) WITH NOWAIT;
      WITH TopRows AS
      (
        SELECT TOP(@pi_BatchSize) a.ApiUsageID
          FROM ApiUsage_PurgeSyn a
         WHERE a.ApiUsageID IN (
                SELECT u.ApiUsageID
                  FROM #ApiUsage u
               )
      )
      DELETE
        FROM TopRows;

      SET @RowsDeletedCurrent = @@ROWCOUNT;
      IF @RowsDeletedCurrent = 0 BREAK;
      SET @RowsDeleted = @RowsDeleted + @RowsDeletedCurrent;
      SET @RowsRemaining = @RowsRemaining - @RowsDeletedCurrent;

      SET @CurrentTime = CONVERT(varchar, CURRENT_TIMESTAMP, 121);
      RAISERROR(' %s::%I64d rows deleted so far. There are approximately %I64d rows remaining.',
                10,
                1,
                @CurrentTime,
                @RowsDeleted,
                @RowsRemaining) WITH NOWAIT;

    END; -- End loop for purge ApiUsage

  END; -- End if for existence of table

END; -- End loop for cursor

CLOSE DB_Cursor;
DEALLOCATE DB_Cursor;


END TRY
BEGIN CATCH

  DECLARE @ERROR_MESSAGE NVARCHAR(2048);
  DECLARE @ERROR_SEVERITY TINYINT;
  DECLARE @ERROR_NUMBER INT;

  SET @ERROR_MESSAGE = ERROR_MESSAGE();
  SET @ERROR_NUMBER = ERROR_NUMBER();
  SET @ERROR_SEVERITY = ERROR_SEVERITY();

  RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);

END CATCH;

GO
/*************** END OF PRICING SERVICE STORED PROCEDURES SECTION ******************/

/*************** START OF ARACCOUNTS UPDATE STORED PROCEDURES SECTION ******************/
DECLARE @ARAccountsUpdateMode TINYINT,
        @UseAsynchronousARAccountsUpdate BIT,
        @ARAccountsUpdateSQL NVARCHAR(MAX),
        @ARAccountsUpdateErr INT

/********** Begin getting ARAccounts update method **********/
SELECT @ARAccountsUpdateMode = CONVERT(TINYINT, value) FROM UpgradeSettings WHERE Setting = 'ARAccountsUpdateMode'
SET @ARAccountsUpdateMode = ISNULL(@ARAccountsUpdateMode, 0)

SET @UseAsynchronousARAccountsUpdate = 0
IF @ARAccountsUpdateMode = 2 BEGIN
    SET @UseAsynchronousARAccountsUpdate = 1
    END
ELSE IF @ARAccountsUpdateMode = 0 BEGIN
    IF EXISTS (
        SELECT svcs.name FROM sys.services svcs, sys.database_principals dp
        WHERE (svcs.name = 'ARAccountsUpdate_Service')
        AND   (svcs.principal_id = dp.principal_id)
        AND   (dp.name = 'dbo'))
        SET @UseAsynchronousARAccountsUpdate = 1
    END
/********** End getting ARAccounts update method **********/

PRINT 'Creating GTS_OE_UpdateUsedCreditAmountOnAccount stored procedure...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
    WHERE (o.name = 'GTS_OE_UpdateUsedCreditAmountOnAccount') AND (o.type = 'P')
    AND   (o.uid = u.uid)
    AND   (u.name = 'dbo')) BEGIN
