IF @UseAsynchronousARAccountsUpdate = 0 BEGIN
    SET @ARAccountsUpdateSQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_OE_UpdateUsedCreditAmountOnAccount]') +
        dbo.GTSFormatSQL('        @AccountID     Int,      -- AccountID to update') +
        dbo.GTSFormatSQL('        @NewBalance    Money,    -- NewBalance of the Order, Invoice or CreditMemos') +
        dbo.GTSFormatSQL('        @OldBalance    Money,    -- OldBalance of the Order, Invoice or CreditMemos') +
        dbo.GTSFormatSQL('        @LastUpdatedBy varchar(20)  -- LastUpdatedBy, indicates which trigger is updating the account') +
        dbo.GTSFormatSQL('AS BEGIN') +
        dbo.GTSFormatSQL('    /*') +
        dbo.GTSFormatSQL('    Updates the UsedCreditAmount column to add the delta of the NewBalance and the OldBalance on the account with the given AccountID') +
        dbo.GTSFormatSQL('    */') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON') +
        dbo.GTSFormatSQL('    DECLARE @BalanceDelta Money') +
        dbo.GTSFormatSQL('    IF @AccountID > 0 BEGIN') +
        dbo.GTSFormatSQL('        SET @BalanceDelta = @NewBalance - @OldBalance') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    -- Update UsedCreditAmount on the Account to add the delta of the NewBalance & OldBalance amount') +
        dbo.GTSFormatSQL('    IF @BalanceDelta <> 0 UPDATE ARAccounts') +
        dbo.GTSFormatSQL('                              SET UsedCreditAmount = IsNull(UsedCreditAmount, 0) + @BalanceDelta, RecordVersion = RecordVersion + 1, LastUpdate = GetDate(), LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                              WHERE AccountID = @AccountID') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('    SET NOCOUNT OFF') +
        dbo.GTSFormatSQL('    END')
END
ELSE BEGIN
    SET @ARAccountsUpdateSQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_OE_UpdateUsedCreditAmountOnAccount]') +
        dbo.GTSFormatSQL('    @AccountID     Int,      -- AccountID to update') +
        dbo.GTSFormatSQL('    @NewBalance    Money,    -- NewBalance of the Order, Invoice or CreditMemos') +
        dbo.GTSFormatSQL('    @OldBalance    Money,    -- OldBalance of the Order, Invoice or CreditMemos') +
        dbo.GTSFormatSQL('    @LastUpdatedBy varchar(20)  -- LastUpdatedBy, indicates which trigger is updating the account') +
        dbo.GTSFormatSQL('AS BEGIN') +
        dbo.GTSFormatSQL('    /*') +
        dbo.GTSFormatSQL('    Updates the UsedCreditAmount column to add the delta of the NewBalance and the OldBalance on the account with the given AccountID') +
        dbo.GTSFormatSQL('    */') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    DECLARE @BalanceDelta Money') +
        dbo.GTSFormatSQL('    DECLARE @UsingUsedCreditAmount BIT') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    IF @AccountID > 0 BEGIN') +
        dbo.GTSFormatSQL('        SELECT @UsingUsedCreditAmount = UsingUsedCreditAmount FROM ARAccounts WHERE AccountID = @AccountID') +
        dbo.GTSFormatSQL('        IF @UsingUsedCreditAmount = 1 BEGIN') +
        dbo.GTSFormatSQL('            SET @BalanceDelta = @NewBalance - @OldBalance') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('            -- Update UsedCreditAmount on the Account to add the delta of the NewBalance & OldBalance amount') +
        dbo.GTSFormatSQL('            IF @BalanceDelta <> 0 UPDATE ARAccounts') +
        dbo.GTSFormatSQL('                                      SET UsedCreditAmount = IsNull(UsedCreditAmount, 0) + @BalanceDelta, RecordVersion = RecordVersion + 1, LastUpdate = GetDate(), LastUpdatedBy = @LastUpdatedBy') +
        dbo.GTSFormatSQL('                                      WHERE AccountID = @AccountID') +
        dbo.GTSFormatSQL('            END') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SET NOCOUNT OFF') +
        dbo.GTSFormatSQL('    END')
    END

