    SET @ARAccountsUpdateSQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_OE_ARAccountsUpdate_SendAsyncMessage]') +
        dbo.GTSFormatSQL('  @MessageBody XML') +
        dbo.GTSFormatSQL('AS BEGIN') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON;') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    IF (@MessageBody IS NOT NULL) BEGIN') +
        dbo.GTSFormatSQL('        DECLARE @DialogHandle UNIQUEIDENTIFIER;') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        BEGIN DIALOG CONVERSATION @DialogHandle') +
        dbo.GTSFormatSQL('            FROM SERVICE ARAccountsUpdate_Service TO SERVICE ''ARAccountsUpdate_Service'' ON CONTRACT [ARAccountsUpdate_Contract]') +
        dbo.GTSFormatSQL('            WITH ENCRYPTION = OFF,') +
        dbo.GTSFormatSQL('            LIFETIME = 3600;') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        SEND ON CONVERSATION @DialogHandle MESSAGE TYPE ARAccountsUpdate_Message(@MessageBody);') +
        dbo.GTSFormatSQL('        END') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SET NOCOUNT OFF') +
        dbo.GTSFormatSQL('    END')

