IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
            WHERE (o.name = 'GTS_OE_ARAccountsUpdate_QueueActivation') AND (o.type = 'P')
            AND   (o.uid = u.uid)
            AND   (u.name = 'dbo')) BEGIN
    SET @ARAccountsUpdateSQL = 'DROP PROCEDURE dbo.GTS_OE_ARAccountsUpdate_QueueActivation '
    EXEC(@ARAccountsUpdateSQL)
    END

IF @UseAsynchronousARAccountsUpdate = 1 BEGIN
    PRINT N'Creating GTS_OE_ARAccountsUpdate_QueueActivation stored procedure ...'

    SET @ARAccountsUpdateSQL =
        dbo.GTSFormatSQL('CREATE PROCEDURE [dbo].[GTS_OE_ARAccountsUpdate_QueueActivation]') +
        dbo.GTSFormatSQL('AS BEGIN ') +
        dbo.GTSFormatSQL('    DECLARE @DialogHandle  UNIQUEIDENTIFIER ') +
        dbo.GTSFormatSQL('    DECLARE @MessageType   SYSNAME ') +
        dbo.GTSFormatSQL('    DECLARE @MessageBody   XML ') +
        dbo.GTSFormatSQL('    DECLARE @LastUpdatedBy VARCHAR(20) ') +
        dbo.GTSFormatSQL('    DECLARE @AccountID     INT ') +
        dbo.GTSFormatSQL('    DECLARE @NewBalance    MONEY ') +
        dbo.GTSFormatSQL('    DECLARE @OldBalance    MONEY ') +
        dbo.GTSFormatSQL('    DECLARE @JnlTranID     INT ') +
        dbo.GTSFormatSQL('    DECLARE @AuxtableID    INT ') +
        dbo.GTSFormatSQL('    DECLARE @Amount        MONEY ') +
        dbo.GTSFormatSQL('    DECLARE @ErrorMessage  NVARCHAR(4000) ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    SET NOCOUNT ON; ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('    WHILE (1 = 1) BEGIN ') +
        dbo.GTSFormatSQL('        BEGIN TRAN; ') +
        dbo.GTSFormatSQL('        WAITFOR ( ') +
        dbo.GTSFormatSQL('            RECEIVE TOP(1) ') +
        dbo.GTSFormatSQL('                @DialogHandle = conversation_handle, ') +
        dbo.GTSFormatSQL('                @MessageType = message_type_name, ') +
        dbo.GTSFormatSQL('                @MessageBody = message_body ') +
        dbo.GTSFormatSQL('            FROM dbo.ARAccountsUpdate_Queue ') +
        dbo.GTSFormatSQL('        ), TIMEOUT 1000; ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- No messages available ') +
        dbo.GTSFormatSQL('        IF (@@ROWCOUNT = 0) BEGIN ') +
        dbo.GTSFormatSQL('            ROLLBACK TRAN; ') +
        dbo.GTSFormatSQL('            BREAK; ') +
        dbo.GTSFormatSQL('            END ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        -- Handle different message types ') +
        dbo.GTSFormatSQL('        IF @MessageType = ''ARAccountsUpdate_Message'' BEGIN ') +
        dbo.GTSFormatSQL('            BEGIN TRY ') +
        dbo.GTSFormatSQL('                -- Parse message body ') +
        dbo.GTSFormatSQL('                SELECT ') +
        dbo.GTSFormatSQL('                    @LastUpdatedBy = MB.value(''@LastUpdatedBy'', ''VARCHAR(20)''), ') +
        dbo.GTSFormatSQL('                    @AccountID     = MB.value(''@AccountID'',     ''INT''), ') +
        dbo.GTSFormatSQL('                    @NewBalance    = MB.value(''@NewBalance'',    ''MONEY''), ') +
        dbo.GTSFormatSQL('                    @OldBalance    = MB.value(''@OldBalance'',    ''MONEY''), ') +
        dbo.GTSFormatSQL('                    @JnlTranID     = MB.value(''@JnlTranID'',     ''INT''), ') +
        dbo.GTSFormatSQL('                    @AuxtableID    = MB.value(''@AuxtableID'',    ''INT''), ') +
        dbo.GTSFormatSQL('                    @Amount        = MB.value(''@Amount'',        ''MONEY'') ') +
        dbo.GTSFormatSQL('                FROM @MessageBody.nodes(''//row'') t(MB); ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('                -- Process based on trigger source ') +
        dbo.GTSFormatSQL('                IF (@LastUpdatedBy IS NOT NULL) BEGIN ') +
        dbo.GTSFormatSQL('                    IF ((@LastUpdatedBy LIKE ''Order%Tr'') OR ') +
        dbo.GTSFormatSQL('                        (@LastUpdatedBy LIKE ''ARInv%Tr'') OR ') +
        dbo.GTSFormatSQL('                        (@LastUpdatedBy LIKE ''ARCdm%Tr'')) BEGIN ') +
        dbo.GTSFormatSQL('                        EXEC dbo.GTS_OE_UpdateUsedCreditAmountOnAccount ') +
        dbo.GTSFormatSQL('                            @AccountID, @NewBalance, @OldBalance, @LastUpdatedBy; ') +
        dbo.GTSFormatSQL('                        END ') +
        dbo.GTSFormatSQL('                    ELSE IF (@LastUpdatedBy LIKE ''JnlDt%Tr'') BEGIN ') +
        dbo.GTSFormatSQL('                        EXEC dbo.GTS_OE_UpdateJnlUsedCreditAmountOnAccount ') +
        dbo.GTSFormatSQL('                            @JnlTranID, @AuxTableID, @Amount, @LastUpdatedBy; ') +
        dbo.GTSFormatSQL('                        END ') +
        dbo.GTSFormatSQL('                    END ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('                -- CRITICAL: End conversation after successful processing ') +
        dbo.GTSFormatSQL('                END CONVERSATION @DialogHandle; ') +
        dbo.GTSFormatSQL('                END TRY ') +
        dbo.GTSFormatSQL('            BEGIN CATCH ') +
        dbo.GTSFormatSQL('                SET @ErrorMessage = ERROR_MESSAGE(); ') +
        dbo.GTSFormatSQL('                IF XACT_STATE() <> 0 ROLLBACK TRAN; ') +
        dbo.GTSFormatSQL('                BEGIN TRAN; ') +
        dbo.GTSFormatSQL('                END CONVERSATION @DialogHandle WITH ERROR = 1 ') +
        dbo.GTSFormatSQL('                DESCRIPTION = @ErrorMessage; ') +
        dbo.GTSFormatSQL('                COMMIT TRAN; ') +
        dbo.GTSFormatSQL('                CONTINUE; -- skip outer COMMIT TRAN ') +
        dbo.GTSFormatSQL('                END CATCH ') +
        dbo.GTSFormatSQL('            END ') +
        dbo.GTSFormatSQL('        ELSE IF @MessageType = N''http://schemas.microsoft.com/SQL/ServiceBroker/EndDialog'' BEGIN ') +
        dbo.GTSFormatSQL('            -- Target ended conversation; close initiator side ') +
        dbo.GTSFormatSQL('            END CONVERSATION @DialogHandle; ') +
        dbo.GTSFormatSQL('            END ') +
        dbo.GTSFormatSQL('        ELSE IF @MessageType = N''http://schemas.microsoft.com/SQL/ServiceBroker/Error'' BEGIN ') +
        dbo.GTSFormatSQL('            -- Error occurred, end conversation ') +
        dbo.GTSFormatSQL('            END CONVERSATION @DialogHandle; ') +
        dbo.GTSFormatSQL('            END ') +
        dbo.GTSFormatSQL('        ELSE BEGIN ') +
        dbo.GTSFormatSQL('            -- Discard unrecognized message types ') +
        dbo.GTSFormatSQL('            END CONVERSATION @DialogHandle; ') +
        dbo.GTSFormatSQL('            END ') +
        dbo.GTSFormatSQL('') +
        dbo.GTSFormatSQL('        COMMIT TRAN; ') +
        dbo.GTSFormatSQL('        END ') +
        dbo.GTSFormatSQL('END')

    EXEC sp_executesql @ARAccountsUpdateSQL
    SELECT @ARAccountsUpdateErr = @@Error
    IF @ARAccountsUpdateErr > 0 PRINT N'Unable to create stored procedure GTS_OE_ARAccountsUpdate_QueueActivation due to an error.'
    ELSE PRINT N'Stored procedure GTS_OE_ARAccountsUpdate_QueueActivation created successfully.'
    END
