/* Start LastUpdatedBy Conversion */
IF @UpdateLastUpdatedByLength = 1 BEGIN

	DECLARE @GalaxyTables					TABLE
		(
			TableName		SYSNAME,
			NumRows			INT
		)
	DECLARE @GalaxyTriggers					TABLE
		(
			TableName		SYSNAME,
			TriggerName		SYSNAME
		)
	DECLARE @lubTableName						SYSNAME
	DECLARE @TriggerName					SYSNAME
	DECLARE @NumRows						INT
	DECLARE @lubColumnExists					BIT
	DECLARE @lubSameColumnDef					BIT
	DECLARE @NewColumnName					VARCHAR(15)
	DECLARE @RenameStatement				VARCHAR(200)
	DECLARE @TableIteratorStart				DATETIME
    DECLARE @ErrorMessage                   varchar(256)

	SET NOCOUNT ON

	-- Insert a list of User Tables and their Row Counts into a table variable.
	INSERT INTO
		@GalaxyTables
	SELECT
		so.Name, MAX(si.Rows) AS NumRows
	FROM
		SysObjects so
		LEFT OUTER JOIN SysIndexes si -- Associated Row Counts
			ON so.id = si.id
	WHERE
		so.xtype = 'U'
	GROUP BY
		so.Name
	ORDER BY
		NumRows desc , so.name

	-- Insert a list of Triggers and associated tables into a table variable.
	INSERT INTO
		@GalaxyTriggers
	SELECT
		so.Name, tr.name
	FROM
		SysObjects so
		INNER JOIN SysObjects tr -- Associated Triggers
			ON tr.xtype = 'TR' AND tr.parent_obj = so.id AND so.xtype = 'U'
	WHERE
		OBJECTPROPERTY(tr.id, 'ExecIsTriggerDisabled') = 0
	ORDER BY
		so.name, tr.name

	DECLARE TableIterator CURSOR FOR SELECT TableName, NumRows FROM @GalaxyTables ORDER BY NumRows DESC, TableName
	OPEN TableIterator

	SET @TableIteratorStart = GETDATE()
	SET @NewColumnName = 'LastUpdatedBy1'

	FETCH NEXT FROM TableIterator
		INTO @lubTableName, @NumRows
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		PRINT @lubTableName + ': Start Processing';
		EXEC @lubColumnExists = GTSColumnExists @lubTableName, LastUpdatedBy
		IF @lubColumnExists = 1
		BEGIN
			EXEC @lubSameColumnDef = GTSSameColumnDef @lubTableName, LastUpdatedBy, VARCHAR, 20, 'NULL'
			IF @lubSameColumnDef = 0
			BEGIN
				PRINT @lubTableName + ': Column definition for LastUpdatedBy is different for table';

				DECLARE TriggerIterator CURSOR FOR SELECT TableName, TriggerName FROM @GalaxyTriggers WHERE TableName = @lubTableName
				OPEN TriggerIterator
				FETCH NEXT FROM TriggerIterator
					INTO @lubTableName, @TriggerName
				WHILE (@@FETCH_STATUS = 0)
				BEGIN
					PRINT @lubTableName + ': Disabling Trigger: ' + @TriggerName;
					EXECUTE('DISABLE TRIGGER dbo.' + @TriggerName + ' ON dbo.' + @lubTableName)
					FETCH NEXT FROM TriggerIterator
						INTO @lubTableName, @TriggerName
				END
				CLOSE TriggerIterator

                -- Use Galaxy stored procedures to rename the column and recreate any dropped indexes
			    EXEC GTSUpgradeGatherTableIndexes @lubTableName
                EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency, @lubTableName, LastUpdatedBy, varchar, 20
                IF @Error <> 0 BEGIN
                    SET @ErrorMessage = 'Error occurred while executing the UpdateLastUpdatedByLength conversion'
                    EXEC GTSUpgradeError  @RunMode, @Error OUTPUT, @ErrorMessage
                    END

                EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @lubTableName,  @RecreateDroppedIndexes
                IF @Error <> 0 BEGIN
                    SET @ErrorMessage = 'Error occurred while executing the UpdateLastUpdatedByLength conversion'
                    EXEC GTSUpgradeError  @RunMode, @Error OUTPUT, @ErrorMessage
                    END

				OPEN TriggerIterator
				FETCH NEXT FROM TriggerIterator
					INTO @lubTableName, @TriggerName
				WHILE (@@FETCH_STATUS = 0)
				BEGIN
					PRINT @lubTableName + ': Enabling Trigger: ' + @TriggerName;
					EXECUTE('ENABLE TRIGGER dbo.' + @TriggerName + ' ON dbo.' + @lubTableName)
					FETCH NEXT FROM TriggerIterator
						INTO @lubTableName, @TriggerName
				END
				CLOSE TriggerIterator
				DEALLOCATE TriggerIterator

				PRINT @lubTableName + ': Completed Table';
			END
			ELSE
			BEGIN
				PRINT @lubTableName + ': No Changes Required';
			END
		END

		FETCH NEXT FROM TableIterator
			INTO @lubTableName, @NumRows

		IF DATEDIFF(SECOND, @TableIteratorStart, GETDATE()) >= @UpdateLastUpdatedByMaxRunTime*60
		BEGIN
			PRINT 'Allowed maximum time for LastUpdatedBy column update exceeded. Exiting loop...';
			BREAK
		END
		ELSE
			CONTINUE
        PRINT CHAR(13) + 'Update to the LastUpdatedBy columns is complete...';
	END

	CLOSE TableIterator
	DEALLOCATE TableIterator

END

/* End LastUpdatedBy Conversion */

