/*
 * **************************************************************
 *
 *    Start GetNextGatewayCounter stored procedure creation logic
 *
 * **************************************************************
 */
DECLARE @RecommendSequences BIT = 0

--  Get the current sql server version
DECLARE @invalidSQLSequenceConfig BIT = 0
DECLARE @invalidSQLSequenceConfigMsg VARCHAR(100) = 'Invalid configuration for Galaxy SQL sequences. See messages for more information.'
DECLARE @ver nvarchar(128), @version int
SET @ver = CAST(serverproperty('ProductVersion') AS nvarchar)
SET @ver = SUBSTRING(@ver, 1, CHARINDEX('.', @ver) - 1)
set @version = 0
if ISNUMERIC(@ver) = 1
	set @version = @ver

begin transaction
begin try

    IF EXISTS (SELECT 1	FROM   SYS.PROCEDURES WHERE  NAME = 'GetNextGatewayCounter' AND [Type] IN (N'P',N'PC'))
    BEGIN
        DROP PROCEDURE dbo.GetNextGatewayCounter
    END

    IF EXISTS (SELECT 1	FROM   SYS.PROCEDURES WHERE  NAME = 'GetNextGatewayCounter64' AND [Type] IN (N'P',N'PC'))
    BEGIN
        DROP PROCEDURE dbo.GetNextGatewayCounter64
    END

    IF @version >= 11
    BEGIN
        -- Enable UseSequencesForCertainGatewayCounters if it was ever used in the past.
        PRINT ''
        PRINT 'Checking SQL sequence availability...'
        DECLARE @PreviouslyUpgradedToSequences BIT = 0
        IF ((@WebStoreDB = 1) AND (EXISTS (SELECT * FROM sys.objects WHERE object_id=object_id('dbo.OrderIdSequence') AND [type]='SO')))
           OR
           (EXISTS (SELECT * FROM sys.objects WHERE object_id=object_id('dbo.TicketIDSequence') AND [type]='SO'))
        BEGIN
            PRINT 'This database has already been upgraded to use SQL sequences.'
            PRINT 'Forcing @UseSequencesForCertainGatewayCounters = 1'
            SET @PreviouslyUpgradedToSequences = 1
            SET @UseSequencesForCertainGatewayCounters = 1
        END
        ELSE
        BEGIN
            PRINT 'This database has not previously been upgraded to use SQL sequences.'
        END

        DECLARE @sequences         TABLE (row INT, ColumnName NVARCHAR(32), TableName NVARCHAR(32))
        DECLARE @webStoreSequences TABLE (row INT, ColumnName NVARCHAR(32), TableName NVARCHAR(32))
        DECLARE @galaxySequences   TABLE (row INT, ColumnName NVARCHAR(32), TableName NVARCHAR(32))
        DECLARE @i int
        DECLARE @count int
        DECLARE @seqName NVARCHAR(32)
        DECLARE @seqTableName NVARCHAR(32)

        INSERT INTO @webStoreSequences
            SELECT       2,   N'OrderId',            N'Orders'
            UNION SELECT 3,   N'OrderLineId',        N'OrderLines'
            UNION SELECT 4,   N'AddressID',          N'Addresses'
            UNION SELECT 5,   N'CustContactID',      N'CustContacts'
            --  Can add more tables here

        INSERT INTO @galaxySequences
            SELECT       2,   N'TicketID',           N'Tickets'
            UNION SELECT 3,   N'OrderLineID',        N'OrderLines'
            UNION SELECT 4,   N'TicketBankID',       N'TicketBanks'
            UNION SELECT 5,   N'SuperTicketID',      N'SuperTickets'
            UNION SELECT 6,   N'UsageID',            N'Usage'
            UNION SELECT 7,   N'OrderPaymentID',     N'OrderPayments'
            UNION SELECT 8,   N'OrderDetailID',      N'OrderDetails'
            UNION SELECT 9,   N'ReentryID',          N'Reentry'
            UNION SELECT 10,  N'OEUserFieldID',      N'OEUserFields'
            UNION SELECT 11,  N'OrderTransactionID', N'OrderTransactions'
            UNION SELECT 12,  N'GatewayLockID',      N'GatewayLocks'
            --  Can add more tables here

        /*
         * The above GatewayCounters will be converted to sequences.
         * Every time new counters are added to this list, this script will need to be run with
         * @UseSequencesForCertainGatewayCounters set to 1 in order to start using the new sequences.
         * This option will now be set automatically, once the database is upgraded to use sequences.
         */

        -- Always add a sequence for the SequentialPassCounter
        INSERT INTO @sequences SELECT 1, N'SequentialPassCounter', 'Passes'

        --  Set which tables to create sequences from (all other code will be built dynamically from this)
        IF @UseSequencesForCertainGatewayCounters = 1
        BEGIN
            IF @WebStoreDB = 1
            BEGIN
                INSERT INTO @sequences SELECT * FROM @webStoreSequences
            END
            ELSE IF (@RunMode = 21) OR (@PreviouslyUpgradedToSequences = 1) -- Switching to SQL sequences is permanent and NOT backwards-compatible. Once this is done, mixed-mode may not work.
            BEGIN
                INSERT INTO @sequences SELECT * FROM @galaxySequences
            END
            ELSE
            BEGIN
                PRINT 'Invalid configuration for Galaxy SQL sequences.'
                PRINT '    To upgrade Galaxy, use the following options:'
                PRINT '        @RunMode = 21'
                PRINT '        @UseSequencesForCertainGatewayCounters = 1'
                PRINT '    To upgrade the Web Store, use the following options:'
                PRINT '        @WebStoreDB = 1'
                PRINT '        @UseSequencesForCertainGatewayCounters = 1'
                SET @invalidSQLSequenceConfig = 1
            END
        END
        ELSE -- Not using sequences. Check to see if we recommend switching to sequences.
        BEGIN
            EXEC @TableExists = GTSTableExists 'Orders'
            IF (@TableExists = 1) BEGIN
                -- Check order volume over the past year
                PRINT 'Checking whether SQL sequences are recommended based on order volume...'
                DECLARE @OrderCount INT = (SELECT COUNT(*) FROM Orders WHERE OpenDate BETWEEN DATEADD(year, -1, GETDATE()) AND GETDATE())
                IF @OrderCount < 150000
                BEGIN
                    SET @RecommendSequences = 0
                    PRINT 'Order volume does not warrant using SQL sequences.'
                END
                ELSE
                BEGIN
                    SET @RecommendSequences = 1
                    PRINT 'We recommend using SQL sequences. See the note at the end of the output for more information.'
                END
            END
        END

        --  Set loop variables
        SELECT @i = 1
        SELECT @count = count(*) FROM @sequences

        --  Loop through each table and create a sequence for it
        WHILE @i <= @count
        BEGIN
            SELECT @seqName = ColumnName, @seqTableName = TableName FROM @sequences WHERE row = @i
            SELECT @i = @i + 1;

            IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id=object_id('dbo.' + @seqName + 'Sequence') AND [type]='SO')
            BEGIN
                PRINT 'Creating sequence: dbo.' + @seqName + 'Sequence...'

                --  Determine the old gateway counter value to use as the new sequence seed value
                DECLARE @oldCount INT;
                select @oldCount = 0
                SELECT @oldCount = CountValue FROM GatewayCounters WITH (XLOCK, HOLDLOCK) WHERE Name = @seqName
                SELECT @oldCount = @oldCount + 10	--  Add 10 to the old count to be safe


                --  Determine if we need to create a int or bigint sequence
                DECLARE @SequenceDataType varchar(100)
                DECLARE @MaxValue varchar(100)
                IF EXISTS(SELECT DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @seqTableName AND COLUMN_NAME = @seqName AND DATA_TYPE = 'BIGINT') BEGIN
                    SET @SequenceDataType = 'bigint'
                    SET @MaxValue = '9223372036854775807'
                    END
                ELSE BEGIN
                    SET @SequenceDataType = 'int'
                    SET @MaxValue = '2147483647'
                    END

                --  Done with dynamic sql in order to set dynamic start value
                SET @SQL = '
                    CREATE SEQUENCE dbo.' + @seqName + 'Sequence
                        AS ' + @SequenceDataType + ' START WITH ' + CONVERT(NVARCHAR(32), @oldCount) + '
                        INCREMENT BY 1
                        MINVALUE 1
                        MAXVALUE ' + @MaxValue + ' CACHE CYCLE'

                EXEC(@SQL)
            END
        END

        --  Remove the values from gateway counters and create a constraint to prevent it in the future
        declare @cstrColumnNames nvarchar(max) select @cstrColumnNames = '';
        declare @csvColumnNames nvarchar(max) select @csvColumnNames = '';

        select @cstrColumnNames = @cstrColumnNames + ' or [name]=''' + ColumnName + ''' '
             , @csvColumnNames = @csvColumnNames + ', ''' + ColumnName + ''' ' from @sequences
        select @cstrColumnNames = RIGHT(@cstrColumnNames, len(@cstrColumnNames) - 3)
        select @csvColumnNames = RIGHT(@csvColumnNames, len(@csvColumnNames) - 1)

        select @sql = '


            DELETE FROM [dbo].[gatewaycounters] WHERE [name] IN (' + @csvColumnNames + ');
            ALTER TABLE [dbo].[GatewayCounters] WITH CHECK ADD  CONSTRAINT [CK_SequenceBasedCounters] CHECK  ((NOT (' + @cstrColumnNames + ')))
            ALTER TABLE [dbo].[GatewayCounters] CHECK CONSTRAINT [CK_SequenceBasedCounters]'

        print(@sql)
        exec(@sql)

        select @sql =
'-- The @PKColumnName parameter must be defined as varchar(30) to match the type of the Name column of GatewayCounters table
CREATE PROCEDURE [dbo].[GetNextGatewayCounter](
    @PKColumnName varchar(30),
    @Range int = 1,
    @StartValue int = null OUTPUT,
    @EndValue int = null OUTPUT) AS
BEGIN

    SET NOCOUNT ON
    /*
    Updates and get next GatewayCounter for a Gateway table''s PK Column Name

    Usage

    DECLARE
        @NextID int

    EXEC @NextID = GetNextGatewayCounter ''OrderID''

    SELECT @NextID

    Alternatively you can request a range of counters by using @Range, it will output the first and last available Id''s
    */
    BEGIN TRY
        IF @Range < 1 RAISERROR(''@Range parameter value must be greater than zero.'', 16, 1)
        BEGIN TRANSACTION

            --  Use sequences for certain tables tables now use sql 2012 sequence objects
			IF EXISTS (SELECT 1 FROM sys.sequences s WHERE s.name = @PKColumnName + N''Sequence'')
			BEGIN
				SELECT @PKColumnName = @PKColumnName + N''Sequence''
                DECLARE @start SQL_VARIANT, @end SQL_VARIANT
                EXEC sp_sequence_get_range @PkColumnName, @range, @start OUTPUT, @end OUTPUT
                SELECT @startValue = CONVERT(INT, @start), @endValue = CONVERT(INT, @end)

            END
            ELSE
            BEGIN

                -- Initial value
                SELECT @StartValue = CountValue + 1 FROM GatewayCounters WITH (UPDLOCK) WHERE name = @PKColumnName

                UPDATE GatewayCounters SET CountValue = CountValue + @Range WHERE name = @PKColumnName
                SELECT @EndValue = CountValue FROM GatewayCounters WHERE name = @PKColumnName

                IF @StartValue IS NULL BEGIN
                    INSERT GatewayCounters VALUES (@PKColumnName, @Range)
                    SET @StartValue = 1
                    SET @EndValue = @Range
                    END
            END

        COMMIT TRANSACTION

        RETURN @StartValue

    END TRY
    BEGIN CATCH
        DECLARE @ERROR_MESSAGE NVARCHAR(2048);
        DECLARE @ERROR_SEVERITY TINYINT;
        DECLARE @ERROR_NUMBER INT;

        SET @ERROR_MESSAGE = ERROR_MESSAGE();
        SET @ERROR_NUMBER = ERROR_NUMBER();
        SET @ERROR_SEVERITY = ERROR_SEVERITY();

        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION

        RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
        END CATCH
    END'

        print(@sql)
        exec(@sql)

        select @sql =
'-- The @PKColumnName parameter must be defined as varchar(30) to match the type of the Name column of GatewayCounters table
CREATE PROCEDURE [dbo].[GetNextGatewayCounter64](
    @PKColumnName varchar(30),
    @CounterValue bigint OUTPUT,
    @Range int = 1,
    @StartValue bigint = null OUTPUT,
    @EndValue bigint = null OUTPUT) AS
BEGIN

    SET NOCOUNT ON
    /*
    Updates and get next GatewayCounter for a Gateway table''s PK Column Name.
    Handles values up to 64-bits (bigint).

    Usage

    DECLARE
        @NextID int
        @CounterValue

    EXEC GetNextGatewayCounter64 ''OrderID'', @CounterValue OUTPUT

    SELECT @CounterValue

    Alternatively you can request a range of counters by using @Range, it will output the first and last available Id''s
    */
    SET @CounterValue = 0

    BEGIN TRY
        IF @Range < 1 RAISERROR(''@Range parameter value must be greater than zero.'', 16, 1)
        BEGIN TRANSACTION

            --  Use sequences for certain tables tables now use sql 2012 sequence objects
			IF EXISTS (SELECT 1 FROM sys.sequences s WHERE s.name = @PKColumnName + N''Sequence'')
			BEGIN
				SELECT @PKColumnName = @PKColumnName + N''Sequence''
                DECLARE @start SQL_VARIANT, @end SQL_VARIANT
                EXEC sp_sequence_get_range @PkColumnName, @range, @start OUTPUT, @end OUTPUT
                SELECT @startValue = CONVERT(bigint, @start), @endValue = CONVERT(bigint, @end)

            END
            ELSE
            BEGIN

                -- Initial value
                SELECT @StartValue = CountValue + 1 FROM GatewayCounters WITH (UPDLOCK) WHERE name = @PKColumnName

                UPDATE GatewayCounters SET CountValue = CountValue + @Range WHERE name = @PKColumnName
                SELECT @EndValue = CountValue FROM GatewayCounters WHERE name = @PKColumnName

                IF @StartValue IS NULL BEGIN
                    INSERT GatewayCounters VALUES (@PKColumnName, @Range)
                    SET @StartValue = 1
                    SET @EndValue = @Range
                    END
            END

        COMMIT TRANSACTION

        SET @CounterValue = @StartValue

    END TRY
    BEGIN CATCH
        DECLARE @ERROR_MESSAGE NVARCHAR(2048);
        DECLARE @ERROR_SEVERITY TINYINT;
        DECLARE @ERROR_NUMBER INT;

        SET @ERROR_MESSAGE = ERROR_MESSAGE();
        SET @ERROR_NUMBER = ERROR_NUMBER();
        SET @ERROR_SEVERITY = ERROR_SEVERITY();

