        Node           int            NOT NULL,
        FacilityID     int            NOT NULL,
        Kind           int                NULL,
        ACPGroupID     int                NULL,
        Points         int                NULL,
        CheckpointID   int                NULL,
        LayoutID       int                NULL,
        ExitFacilityID int                NULL,
        AttractionID   int                NULL,
        ValidateGuestMovements bit        NULL,

        RecordVersion  int            NOT NULL,
        LastUpdate     datetime       NOT NULL,
        LastUpdatedBy  nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
    -- Adding a new NOT NULL column AcpUniqueID int NOT NULL
    -- Adding a new nullabel column Kind int NULL

    -- Name column has been changed from "Name varchar(30) NOT NULL" to "char(30) NOT NULL"
    -- LastUpdatedBy column has been changed from "LastUpdatedBy varchar(10) NOT NULL" to "char(10) NOT NULL"
  030722  add index IXACPsACPID
  037212  add ACPGroupID
 */

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  ACPs,  ACPUniqueID,  int,  -1,  'NOT NULL'
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  ACPs,  Kind,         int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  ACPs,  ACPGroupID,   int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  Points,  int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  CheckpointID,  int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  LayoutID,  int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  ExitFacilityID,  int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  AttractionID,  int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  ValidateGuestMovements, bit

EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  ACPs,  Name         ,  char,  30,  'NOT NULL'
DECLARE @LastUpdatedByAlreadyConverted bit
EXEC @LastUpdatedByAlreadyConverted = GTSLastUpdatedByAlreadyConverted @TableName
-- Only change LastUpdatedBy if it has not already been converted to a nullable nvarchar(20) or nvarchar(20)
IF (@LastUpdatedByAlreadyConverted = 0) EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  ACPs,  LastUpdatedBy,  char,  10,  'NOT NULL'

IF ((@RunMode / 10) = 2) BEGIN   /* Post Upgrade Mode */
    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency,  ACPs, name, char, 30

    EXEC GTSPostUpgradeChangePK  @RunMode, @Error OUTPUT,  ACPs, AcpUniqueID, PKACPsACPUniqueID
    END

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  ACPs, ACPUniqueID, PKACPsACPUniqueID

EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  ACPs, FacilityID, IXACPsFacilityID
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  ACPs, ACPID,      IXACPsACPID, 'UNIQUE'

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END



