EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, ACSReservationRuleSetStatusGUID, IXACSReservationRuleSetStatusGUID

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
Copy rows for PassStatusKind 3 to 9998 and 9998
    to add replaced/Renewed and Repalced/Reissued
*/
DECLARE
    @ACSReservationRuleSetStatusesCount int,
    @ACSReservationRuleSetStatusesLog   varchar(256),
    @ACSReservationRuleSetStatusesSQL   varchar(2000)

SELECT @ACSReservationRuleSetStatusesCount =  COUNT(*) FROM ACSReservationRuleSetStatuses WHERE PassStatusKind IN (9997, 9998)
IF @ACSReservationRuleSetStatusesCount <= 0 BEGIN
    SET @ACSReservationRuleSetStatusesLog = 'Adding PASS_REPLACED_RENEWED (9997) and PASS_REPLACED_REISSUED (9998) PassStatusKinds for each ACSReservation ruleset'
    EXEC GTSAddUpgradeLog  @RunMode, @ACSReservationRuleSetStatusesLog, 1

    SET @ACSReservationRuleSetStatusesSQL =
        'INSERT INTO ACSReservationRuleSetStatuses (ACSReservationRuleSetGUID, PassStatusKind, EligibilityKind, ActionKind, XParameter, ACSReservationRuleSetStatusGUID, RecordVersion, LastUpdate, LastUpdatedBy)
        SELECT ACSReservationRuleSetGUID, 9997, EligibilityKind, ActionKind, XParameter, NEWID(), 1, GETDATE(), ''GTSUpgrade''
        FROM ACSReservationRuleSetStatuses WHERE PassStatusKind = 3'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @ACSReservationRuleSetStatusesSQL

    SET @ACSReservationRuleSetStatusesSQL =
        'INSERT INTO ACSReservationRuleSetStatuses (ACSReservationRuleSetGUID, PassStatusKind, EligibilityKind, ActionKind, XParameter, ACSReservationRuleSetStatusGUID, RecordVersion, LastUpdate, LastUpdatedBy)
        SELECT ACSReservationRuleSetGUID, 9998, EligibilityKind, ActionKind, XParameter, NEWID(), 1, GETDATE(), ''GTSUpgrade''
        FROM ACSReservationRuleSetStatuses WHERE PassStatusKind = 3'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @ACSReservationRuleSetStatusesSQL

    END

/* Stop the script if an error has occurred */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

