EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, ACSReservationRuleSetUserProfileGUID, IXACSReservationRuleSetUserProfileGUID

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

IF ((@RunMode / 10) = 2) BEGIN   /* Post Upgrade Mode */
DECLARE
    @IndexExistsPK	bit,
	@IndexExistsRSG bit,
	@IndexExistsRSP bit;

	-- DROP TABLE
    EXEC @TableExists = GTSTableExists  ACSReservationRuleSetUserProfiles
    IF (@TableExists = 1) BEGIN
        SET @Log = 'Drop the ACSReservationRuleSetUserProfiles table which was replaced by UserProfilePasskindGroups'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, 'DROP TABLE ACSReservationRuleSetUserProfiles'
        END
	-- DROP INDEX
	EXEC @IndexExistsPK = GTSIndexExists @TableName, PKACSReservationRuleSetUserProfiles
	IF @IndexExistsPK = 1 BEGIN
		EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, PKACSReservationRuleSetUserProfiles, 1 /* obsolete it */
		END
	EXEC @IndexExistsRSG = GTSIndexExists @TableName, IXACSReservationRuleSetGUID
	IF @IndexExistsRSG = 1 BEGIN
		EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, IXACSReservationRuleSetGUID, 1 /* obsolete it */
		END
	EXEC @IndexExistsRSP = GTSIndexExists @TableName, IXACSReservationRuleSetUserProfileGUID
	IF @IndexExistsRSP = 1 BEGIN
		EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, IXACSReservationRuleSetUserProfileGUID, 1 /* obsolete it */
		END
    END

/* Stop the script if an error has occurred */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

