--
SET @TableName = 'Addresses'
SET @TableStructure = '
        AddressID          int            NOT NULL,
        AddressGUID        uniqueidentifier  NULL DEFAULT newid(),
        AddressType        int            NOT NULL,
        OwnerID            int                NULL,
        Street1            nvarchar(255)   NOT NULL,
        Street2            nvarchar(255)       NULL,
        Street3            nvarchar(255)       NULL,
        City               nvarchar(40)    NOT NULL,
        State              nvarchar(40)    NOT NULL,
        Postal             nvarchar(16)       NOT NULL,
        CountryCode        nchar(2)        NOT NULL,
        AddressCorrection  bit            NOT NULL,
        PersistenceState   int                NULL,
        AllowMailings      bit                NULL,

        RecordVersion      int            NOT NULL,
        LastUpdate         datetime       NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  @TableName, AddressID, PKAddressesAddressID

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, PersistenceState, int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, AllowMailings,    bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, AddressGUID, uniqueidentifier, -1, 'NULL', 'newid()'

/*
        !!!!!!!!!!!!!! NOTE !!!!!!!!!!!!!!!!!!!!!!!!!

        Any columns/indexes added here must also be made to the Addresses structure in
        the Packages\Quasar\Schema\Parcel Express Schema.txt file!
*/

EXEC GTSUpgradeAddNewIDConstraintForGUID @RunMode, @Error OUTPUT, @DropDependency, @TableName, AddressGUID, 0

EXEC @ColumnExists = GTSColumnExists  @TableName, AllowMailings
IF @ColumnExists = 1 BEGIN
  SET @SQL = 'UPDATE Addresses SET AllowMailings = 1 where AllowMailings is NULL'
  EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

  IF (@Error <> 0) BEGIN
      EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
      RETURN
      END
  END

/*
    -- City column has been changed from "City char(20) NOT NULL" to "varchar(40) NOT NULL"
    -- State column has been changed from "State char(20) NOT NULL" to "nvarchar(20) NOT NULL"
    -- all Street columns have been changed from char(36) to varchar(255)
 */

EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  City ,  varchar,  40,  'NOT NULL'

-- Expand State column to 40, but don't change current column's varchar/nvarchar type
IF EXISTS(SELECT DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME = 'State' AND DATA_TYPE = 'NVARCHAR') BEGIN
    PRINT 'Changing nvarchar State to 40'
    EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  State,  nvarchar, 40,  'NOT NULL'
    END
ELSE EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  State,  varchar, 40,  'NOT NULL'

/*
For backward compatibility: Street1 may be Null or Not Null -
    need to determine which before calling GTSUpgradeChangeColumn
*/
DECLARE
    @SameColumnDefWithNULL     bit,
    @SameColumnDefWithNotNULL  bit

EXEC @SameColumnDefWithNULL    = GTSSameColumnDef  @TableName, Street1, char, 36, 'NULL'
EXEC @SameColumnDefWithNotNULL = GTSSameColumnDef  @TableName, Street1, char, 36, 'NOT NULL'

IF (@SameColumnDefWithNULL = 1) BEGIN
    EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  Street1,  varchar,  255, 'NULL'
    END

IF (@SameColumnDefWithNotNULL = 1) BEGIN
    EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  Street1,  varchar,  255, 'NOT NULL'
    END

EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  Street2,  varchar,  255, 'NULL'
EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  Street3,  varchar,  255, 'NULL'

/*   MOVED to GXUsers to ensure we have all columns before doing the update
-- For WebStore DB: populate PersistenceState column
EXEC @TableExists  = GTSTableExists  Addresses
IF @TableExists = 1 BEGIN EXEC @TableExists  = GTSTableExists  CustContacts END
IF @TableExists = 1 BEGIN EXEC @TableExists  = GTSTableExists  GxUsers  END

IF @WebStoreDB = 1 and @TableExists = 1 BEGIN
    SET @SQL = 'UPDATE addresses set PersistenceState = 3 where ((PersistenceState <> 3) or (PersistenceState is NULL)) and AddressID in ( ' +
               'Select distinct a.addressID from addresses a, CustContacts cc ' +
               'where cc.AddressID = a.AddressID and cc.CustContactID in ( ' +
               'select distinct cc.CustContactID from CustContacts cc, GxUsers u ' +
               'where u.ContactID <> 0 and (not u.ContactID is Null) and u.ContactID = cc.CustContactID and u.Publish = 1))'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END */
IF ((@RunMode / 10) = 2) BEGIN   /* Post-Upgrade Mode */
    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  Street1,      varchar,  255
    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  Postal,       char,  16
    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  CountryCode,  char,   2

    EXEC @ColumnExists = GTSColumnExists  @TableName, Country
    IF (@ColumnExists = 1) BEGIN
        SET @SQL = 'ALTER TABLE Addresses DROP COLUMN Country'

        EXEC GTSUpgradeGatherTableIndexes  @TableName
        EXEC GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, @TableName, Country, @DropDependency /* do drop dependency */

        IF (@DropObsoletedColumns = 1) BEGIN
            SET @Log = 'Dropping an obsoleted column "Country"...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END
        ELSE BEGIN
            SET @Log = '"Country" column is no longer used.  This column should be dropped either'             + CHAR(13) + '    ' +
                       'by manually running the provided script, or by setting @DropObsoletedColumns to 1 (true)' + CHAR(13) + '    ' +
                       'at the beginning of the script.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  20 /* Test post upgrade mode */, @Error OUTPUT, @SQL
            END
        END
    END

EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName,  Postal,  IXAddressesPostal
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName,  City  ,  IXAddressesCity
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName,  State ,  IXAddressesState
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName,  AddressGUID, IXAddressesAddressGUID
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName,  PersistenceState, IXAddressesPersistenceState
/*
        !!!!!!!!!!!!!! NOTE !!!!!!!!!!!!!!!!!!!!!!!!!

        Any columns/indexes added here must also be made to the Addresses structure in
        the Packages\Quasar\Schema\Parcel Express Schema.txt file!
*/

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END



