IF dbo.GTSIsTrigger('trARCreditMemosUpdateUsedCreditAmountOnAccountDelete') = 1 BEGIN
    SET @SQL = 'DROP TRIGGER dbo.trARCreditMemosUpdateUsedCreditAmountOnAccountDelete'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF (@Error = 0) AND (@UseAsynchronousARAccountsUpdate = 0) BEGIN
    PRINT 'Adding trARCreditMemosUpdateUsedCreditAmountOnAccountDelete Trigger to ARCreditMemos'

    SET @SQL =
    'CREATE TRIGGER [dbo].[trARCreditMemosUpdateUsedCreditAmountOnAccountDelete] ON [dbo].[ARCreditMemos] FOR DELETE
        AS BEGIN
            /*
            Updates UsedCreditAmount on the customer''s account to add the balance amount of the CreditMemo being deleted
            */
            SET NOCOUNT ON
            DECLARE @AccountID     Int
            DECLARE @NewBalance    Money
            DECLARE @OldBalance    Money
            DECLARE @LastUpdatedBy varchar(20)

            DECLARE DeletedIterator CURSOR FOR
                SELECT IsNull(D.AccountID, 0), 0, IsNull(D.Balance, 0), ''ARCdmDelTr''
                FROM DELETED D, ARAccounts A
                WHERE D.AccountID = A.AccountID AND A.UsingUsedCreditAmount = 1

            OPEN DeletedIterator
            FETCH NEXT FROM DeletedIterator INTO @AccountID, @NewBalance, @OldBalance, @LastUpdatedBy
            WHILE (@@FETCH_STATUS = 0) BEGIN
                EXEC GTS_OE_UpdateUsedCreditAmountOnAccount @AccountID, @NewBalance, @OldBalance, @LastUpdatedBy
                FETCH NEXT FROM DeletedIterator INTO @AccountID, @NewBalance, @OldBalance, @LastUpdatedBy
                END
            CLOSE DeletedIterator
            DEALLOCATE DeletedIterator
            SET NOCOUNT OFF
            END '
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

/* Stop the script if an error has occurred */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

IF dbo.GTSIsTrigger('trARCreditMemosUpdateARAccountsOnDeleteUsingServiceBroker') = 1 BEGIN
    SET @SQL = 'DROP TRIGGER dbo.trARCreditMemosUpdateARAccountsOnDeleteUsingServiceBroker'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF (@Error = 0) AND (@UseAsynchronousARAccountsUpdate = 1) BEGIN
    PRINT 'Adding trARCreditMemosUpdateARAccountsOnDeleteUsingServiceBroker Trigger to ARCreditMemos'

    SET @SQL =
    'CREATE TRIGGER [dbo].[trARCreditMemosUpdateARAccountsOnDeleteUsingServiceBroker] ON [dbo].[ARCreditMemos] FOR DELETE
    AS BEGIN
        /*
        Sends a message to ARAccountsUpdate_Service to
        update UsedCreditAmount on the customer''s account to add the balance amount of the CreditMemo being deleted
        */
        SET NOCOUNT ON;

        DECLARE @MessageBody   XML

        DECLARE @AccountID     INT
        DECLARE @NewBalance    MONEY
        DECLARE @OldBalance    MONEY
        DECLARE @LastUpdatedBy VARCHAR(20)

        DECLARE DeletedIterator CURSOR FOR
            SELECT ISNULL(AccountID, 0), 0, ISNULL(Balance, 0), ''ARCdmDelTr'' FROM DELETED WHERE AccountID > 0

        OPEN DeletedIterator
        FETCH NEXT FROM DeletedIterator INTO @AccountID, @NewBalance, @OldBalance, @LastUpdatedBy
        WHILE (@@FETCH_STATUS = 0) BEGIN
            SET @MessageBody = (
                SELECT
                    @AccountID AS AccountID,
                    @NewBalance AS NewBalance,
                    @OldBalance AS OldBalance,
                    @LastUpdatedBy AS LastUpdatedBy
                FOR XML RAW)

            IF (@MessageBody IS NOT NULL) BEGIN
                EXEC GTS_OE_ARAccountsUpdate_SendAsyncMessage @MessageBody
                END

            FETCH NEXT FROM DeletedIterator INTO @AccountID, @NewBalance, @OldBalance, @LastUpdatedBy
            END
        CLOSE DeletedIterator
        DEALLOCATE DeletedIterator
        SET NOCOUNT OFF
        END '
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

/* Stop the script if an error has occurred */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END



