        FirstUseBasis         int         NULL,
        Points                int         NULL,
        Description           nvarchar(128) NULL,
        RequirementBank       int         NULL,
        RequirementKind       int         NULL,
        RequirementMessage    nvarchar(128) NULL,
        ExcludeFromHistory    bit         NULL,
        ValidationPriority    int         NULL,
        Inactive              bit         NULL,
        IsOverrideCaptureBank bit     NOT NULL DEFAULT (0),
