        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
  037985  Add EnforceFirstUseDate column
  040057  change EnforceFirstUseDate to FirstUseBasis int
*/

EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, FirstUseBasis,   int
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, Points,          int
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, Description,     varchar, 128
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, RequirementBank, int
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, RequirementKind, int
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, RequirementMessage, varchar, 128
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, ExcludeFromHistory, bit
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, ValidationPriority, int
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, Inactive, bit
