EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, ValidateUsesAndDaysPrompt, nvarchar, 128
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, IsOverrideCaptureBank, bit, -1, 'NOT NULL', 0
EXEC GTSUpgradeAddColumn @RunMode,  @Error OUTPUT, @TableName, AdditionalDependency, int

/*
 *  Drop the EnforceFirstUseDate column if it exists...  We can do that here because
 *  the column was just added in 3.0.2 and to one customer
 */
IF ColumnProperty(object_id(@TableName), 'EnforceFirstUseDate', 'AllowsNULL') = 1 BEGIN
    SET @Log = 'The EnforceFirstUseDate BIT column added in 3.0.2 has been replaced by FirstUseBasis INTEGER column.  The EnforceFirstUseDate column will be dropped.'
    EXEC GTSAddUpgradeLog   @RunMode, @Log, 2
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, 'ALTER TABLE BankDetails DROP COLUMN EnforceFirstUseDate'
    END

EXEC GTSUpgradeAddAuditColumns  @RunMode, @Error OUTPUT, BankDetails

IF ((@RunMode / 10) = 2) BEGIN   /* Post Upgrade Mode */
    EXEC GTSPostUpgradeAuditColumns  @RunMode, @Error OUTPUT, @DropDependency,  BankDetails
    END

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  BankDetails, BankDetailID, PKBankDetailsBankDetailID

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

