EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
 *  Add values to this table if they are not alreadt populated
*/
IF (@Error = 0) AND ((@RunMode % 10) = 1) BEGIN
    IF ((NOT EXISTS (select * from BlacklistActionTypeNames where Name = 'Orders')) AND (@Error = 0)) or
	   ((NOT EXISTS (select * from BlacklistActionTypeNames where Name = 'Tickets')) AND (@Error = 0)) or
	   ((NOT EXISTS (select * from BlacklistActionTypeNames where Name = 'Admissions')) AND (@Error = 0)) or
	   ((NOT EXISTS (select * from BlacklistActionTypeNames where Name = 'Passes')) AND (@Error = 0)) BEGIN
        SET @SQL = 'DECLARE @UniqueID int ' +
		'TRUNCATE TABLE BlacklistActionTypeNames ' +
		'Insert into BlacklistActionTypeNames(ActionType, Name, RecordVersion, LastUpdate, LastUpdatedBy) '+
            '    VALUES(1, ''Orders'', 1, GetDate(), ''Script'') ' +
		'Insert into BlacklistActionTypeNames(ActionType, Name, RecordVersion, LastUpdate, LastUpdatedBy) '+
            '    VALUES(2, ''Tickets'', 1, GetDate(), ''Script'') ' +
		'Insert into BlacklistActionTypeNames(ActionType, Name, RecordVersion, LastUpdate, LastUpdatedBy) '+
            '    VALUES(3, ''Admissions'', 1, GetDate(), ''Script'') ' +
		'Insert into BlacklistActionTypeNames(ActionType, Name, RecordVersion, LastUpdate, LastUpdatedBy) '+
            '    VALUES(4, ''Passes'', 1, GetDate(), ''Script'') '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
       END
    END

/*
 *  Stop the script if an error has occurred
*/
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END


