BEGIN CATCH
	DECLARE @ERROR_MESSAGE NVARCHAR(2048);
	DECLARE @ERROR_SEVERITY TINYINT;
	DECLARE @ERROR_NUMBER INT;

	SET @ERROR_MESSAGE = 'An error occurred while applying the UNIQUE constraint to BlockoutDates.BlockoutID.  Please remove duplicate values from this table. ' + ERROR_MESSAGE();
	SET @ERROR_NUMBER = ERROR_NUMBER();
	SET @ERROR_SEVERITY = ERROR_SEVERITY();

    IF XACT_STATE() <> 0
        ROLLBACK;

	RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
END CATCH

