IF @WebStoreDB = 1 and @Transportation = 1 BEGIN
    SET @TableName = 'Carriers'
    SET @TableStructure = '
        CarrierID           int         NOT NULL IDENTITY,
        Carrier             nchar(4)     NOT NULL,
        CompanyNumber       SmallInt        NULL,
        Name                nvarchar(60)     NULL,
        Street1             nvarChar(30)        NULL,
        Street2             nvarChar(30)        NULL,
        City                nvarChar(30)        NULL,
        State               nvarChar(40)        NULL,
        Zip                 nvarChar(16)        NULL,
        Country             nvarChar(20)        NULL,
        Contact1            nvarChar(30)        NULL,
        Phone1              nvarChar(30)        NULL,
        Contact2            nvarChar(30)        NULL,
        Phone2              nvarChar(30)        NULL,
        URL                 nvarchar(80)     NULL,
        Fax                 nvarChar(30)        NULL,
        Tax1_ID             nvarChar(16)        NULL,
        Tax2_ID             nvarChar(16)        NULL,
        Imported            Bit             NULL,

        RecordVersion     int           NOT NULL,
        LastUpdate        datetime      NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
    ' -- *** NO CLOSING PARENTHESIS

    EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure
    EXEC GTSUpgradeAddPK     @RunMode, @Error OUTPUT, @TableName, CarrierID, PKCarriersCarrierID


    -- Expand State column to 40, but don't change current column's varchar/nvarchar type
    IF EXISTS(SELECT DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME = 'State' AND DATA_TYPE = 'NVARCHAR') BEGIN
        EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  State,  nvarchar,  40,  'NULL'
        END
    ELSE EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  State,  varchar,  40,  'NULL'

    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'Carrier', IXCarriersCarrier, 'UNIQUE'
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'CompanyNumber,Carrier,CarrierID', IXCompanyNumCarrierID

    EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END


