--
--                         ***  CITIES  ***
--
IF @WebStoreDB = 1 and @Transportation = 1 BEGIN
    SET @TableName = 'Cities'
    SET @TableStructure = '
        CityID                 int         NOT NULL,     -- Primary Key
        Code                   int             NULL,     -- Industry standard ID number
        Owner                  nchar(4)         NULL,     -- Refers to Carriers.Carrier
        Name                   nvarchar(24)        NULL,     -- City name - the number of characters is limited by a) real estate on ticket stock and b) reports and display space in TX which used 13 characters for the city name plus 2 for state as in READING/PA (16 chars total)
        LongName               nvarchar(40)     NULL,     -- Full city name
        State                  nchar(2)         NULL,     -- State/Provence
        Abbr                   nchar(4)         NULL,     -- 4 char abbreviation (limited to 3 to match Greyhound)
        ZipCode                nvarchar(16)        NULL,     -- Also known as postal code in Canada
        TimeZone               nchar(1)         NULL,     -- NAECMPK
        DST                    bit             NULL,     -- Is Daylight Saving Time used at this location Y/N
        PTP                    smallint        NULL,     -- Preferred Transferr Point rating from 0 to 10
        MinCT                  smallint        NULL,     -- Default Minimum Connect Time
        MaxCT                  smallint        NULL,     -- Defaut Maximum Connect Time (not currently honored)
        FID                    nvarchar(12)        NULL,     -- Feature ID in the USGS database
        Latitude               float           NULL,     -- In decimals
        Longitude              float           NULL,     -- In decimals
        Imported               bit             NULL,     -- Used when importing TX data to delete missing records

        RecordVersion  int       NOT NULL,
        LastUpdate     datetime  NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
    ' -- *** NO CLOSING PARENTHESIS

    EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

    EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  @TableName, CityID, PKCitiesCityID

    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, Abbr, IXCitiesAbbr
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, Code, IXCitiesCode
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, Latitude, IXCitiesLatitude
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, Longitude, IXCitiesLongitude
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, 'State,Name', IXCitiesStateName
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, 'Code,CityID,Name,State', IXExpressReport
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, 'Name,State', IXUserInterface
    END
/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

