--
--  -------------------------------------------------------------------
--
--                  ***  ConfigurationOptions  ***
--
SET @TableName = 'ConfigurationOptions'
SET @TableStructure = '
    ConfigurationOptionID   Integer         NOT NULL,
    Description             nvarchar(100)    NOT NULL,
    Value                   nvarchar(1000)   NOT NULL,
    DataType                Integer         NOT NULL,
    Code                    Integer         NOT NULL,
    Scope                   Integer             NULL,
    OwnerID                 Integer             NULL,
	ConfigurationOptionGUID uniqueidentifier NOT NULL DEFAULT newid(),

    RecordVersion               Int             NOT NULL,
    LastUpdate                  datetime        NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName, Code, Int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName, Scope, Int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName, OwnerID, Int
EXEC GTSUpgradeAddColumn @RunMode, @Error OUTPUT, @TableName, ConfigurationOptionGUID, uniqueidentifier, -1, 'NOT NULL', 'newid()'

EXEC GTSUpgradeRenameColumn  @RunMode, @Error OUTPUT, @TableName, Name, Description

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  @TableName, ConfigurationOptionID, PKConfigurationOptionID
EXEC GTSUpgradeAddIndex @RunMode, @Error OUTPUT, @TableName, Code, IXConfigurationOptionsCode
EXEC GTSUpgradeAddIndex @RunMode, @Error OUTPUT, @TableName, 'DataType, Scope, OwnerID', IXConfigOptionDataTypeScopeOwner

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

DECLARE @FoundScope bit
EXEC @FoundScope = GTSColumnExists @TableName, Scope
IF ((@RunMode % 10) = 1) and (@FoundScope = 1) BEGIN   /* Upgrade Mode  */
    /*
    When Central Configuration was added to Galaxy, a new code (251) was added to the
    ConfigurationOptions table for the Monitor Failed Logons option.  However,
    a code (13) already existed for this option, and that code should have been reused.
    This converts the records with the new code to have the original code if the new
    code has a value of true, indicating that the option was set by the user in Central
    Configuration.  All records with the new code are then deleted.

    Also, THESE 4 CODES:
    17	  CC_CODE_RECORD_LOGGING_USERS
    18    CC_CODE_RECORD_LOGGING_AGENCIES
    19    CC_CODE_RECORD_LOGGING_USER_PROFILES
    20    CC_CODE_RECORD_LOGGING_USER_PASSWORDS

    // REPLACED WITH THESE 4 CODES:
    447	  CC_CODE_LOG_USER_CHANGES
    445	  CC_CODE_LOG_AGENCY_CHANGES
    449   CC_CODE_LOG_PROFILE_CHANGES
    448   CC_CODE_LOG_ALL_PASSWORD_CHANGES
    */
    DECLARE @NewConstTrueCount int,

            @NewLoggingUsers int,
            @NewLoggingProfiles int,
            @NewLoggingAgencies int,
            @NewLoggingPasswords int,
            @NewMaskPasswords int,

            @OldLoggingUsers int,
            @OldLoggingProfiles int,
            @OldLoggingAgencies int,
            @OldLoggingPasswords int,
            @OldMaskPasswords int,

            @DownloadAttributes int,
            @DownloadGenericCalendars int,
            @DisplayQOPConfirmOrderPrompt int,
            @DisplayQOPConfirmIdentificationPrompt int,
            @AllowQOPPartialSearchByExternalID int,
            @DownloadItemTranslations int,
            @DownloadTranslationFields int,
            @DownloadTranslationLanguages int,
            @DownloadTranslationTables int,
            @DownloadTranslationValues int,
            @AutomaticOrderClosing int,

            @SkipAutoIssuanceAtQOV int,
            @DownloadCustomFOPMenus int,
            @DownloadDebitTypes int,
            @ConfigOptionCount int

    /*
    Find out if the new Monitor Failed Logons constant exists and was set to True.
    This would indicate that the user set the value in the application through Central
    Configuration while the application was using the new constant (251). In that
    case we want to keep these values, but remove the new constant.
    */
    SELECT @NewConstTrueCount   = COUNT(*) FROM ConfigurationOptions WHERE Code = 251 AND VALUE = 'YES'
    SELECT @NewLoggingUsers     = COUNT(*) FROM ConfigurationOptions WHERE Code = 447
    SELECT @NewLoggingAgencies  = COUNT(*) FROM ConfigurationOptions WHERE Code = 445
    SELECT @NewLoggingProfiles  = COUNT(*) FROM ConfigurationOptions WHERE Code = 449
    SELECT @NewLoggingPasswords = COUNT(*) FROM ConfigurationOptions WHERE Code = 448
    SELECT @NewMaskPasswords    = COUNT(*) FROM ConfigurationOptions WHERE Code = 325

    SELECT @OldLoggingUsers     = COUNT(*) FROM ConfigurationOptions WHERE Code = 17
    SELECT @OldLoggingAgencies  = COUNT(*) FROM ConfigurationOptions WHERE Code = 18
    SELECT @OldLoggingProfiles  = COUNT(*) FROM ConfigurationOptions WHERE Code = 19
    SELECT @OldLoggingPasswords = COUNT(*) FROM ConfigurationOptions WHERE Code = 20
    SELECT @OldMaskPasswords    = COUNT(*) FROM ConfigurationOptions WHERE Code = 16

    /*
    For Options 251 and 13: If the user did set the option with the new code in Central Config, delete
    the records with the original code and change the records with the new code to have the original code.
    */
    IF (@NewConstTrueCount > 0) BEGIN
            DELETE FROM ConfigurationOptions WHERE Code = 13
            UPDATE ConfigurationOptions SET Code = 13 WHERE Code = 251
            END

    /*  Remove all records with the new (and now unused) code */
    DELETE FROM ConfigurationOptions WHERE Code = 251

    /*
    Preserve ability to rollback - if only old code exists, copy to record with new code;
    if both exist, only delete the old codes in post upgrade mode
    */
    IF (@OldLoggingUsers > 0) and (@NewLoggingUsers = 0) BEGIN
      SET @SQL = 'DECLARE @Value varchar(10), @Scope int, @OwnerID int, @OptionID int ' +
      'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID''  ' +
        'select @Value = Value from ConfigurationOptions where Code = 17 ' +
        'select @Scope = Scope from ConfigurationOptions where Code = 17 ' +
        'select @OwnerID = OwnerID from ConfigurationOptions where Code = 17 ' +
        'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
           'Values(@OptionID, ''Log user changes'', @Value, 3, 447, 1, GetDate(), ''Script'', @Scope, @OwnerID) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

    IF (@Error = 0) and (@OldLoggingAgencies > 0) and (@NewLoggingAgencies = 0) BEGIN
      SET @SQL = 'DECLARE @Value varchar(10), @Scope int, @OwnerID int, @OptionID int ' +
        'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
        'select @Value = Value from ConfigurationOptions where Code = 18 ' +
        'select @Scope = Scope from ConfigurationOptions where Code = 18 ' +
        'select @OwnerID = OwnerID from ConfigurationOptions where Code = 18 ' +
        'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
          'Values(@OptionID, ''Log agency changes'', @Value, 3, 445, 1, GetDate(), ''Script'', @Scope, @OwnerID) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

    IF (@Error = 0) and (@OldLoggingProfiles > 0) and (@NewLoggingProfiles = 0) BEGIN
      SET @SQL = 'DECLARE @Value varchar(10), @Scope int, @OwnerID int, @OptionID int ' +
        'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
        'select @Value = Value from ConfigurationOptions where Code = 19 ' +
        'select @Scope = Scope from ConfigurationOptions where Code = 19 ' +
        'select @OwnerID = OwnerID from ConfigurationOptions where Code = 19 ' +
        'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
          'Values(@OptionID, ''Log user profile changes'', @Value, 3, 449, 1, GetDate(), ''Script'', @Scope, @OwnerID) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

    IF (@Error = 0) and (@OldLoggingPasswords > 0) and (@NewLoggingPasswords = 0) BEGIN
      SET @SQL = 'DECLARE @Value varchar(10), @Scope int, @OwnerID int, @OptionID int ' +
        'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
        'select @Value = Value from ConfigurationOptions where Code = 20 ' +
        'select @Scope = Scope from ConfigurationOptions where Code = 20 ' +
        'select @OwnerID = OwnerID from ConfigurationOptions where Code = 20 ' +
        'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
          'Values(@OptionID, ''Log all password changes'', @Value, 3, 448, 1, GetDate(), ''Script'', @Scope, @OwnerID) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

    IF (@Error = 0) and (@OldMaskPasswords > 0) and (@NewMaskPasswords = 0) BEGIN
      SET @SQL = 'DECLARE @Value varchar(10), @Scope int, @OwnerID int, @OptionID int ' +
        'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
        'select @Value = Value from ConfigurationOptions where Code = 16 ' +
        'select @Scope = Scope from ConfigurationOptions where Code = 16 ' +
        'select @OwnerID = OwnerID from ConfigurationOptions where Code = 16 ' +
        'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
          'Values(@OptionID, ''Mask user password when editing'', @Value, 3, 325, 1, GetDate(), ''Script'', @Scope, @OwnerID) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

	SELECT @DownloadAttributes = COUNT(*) FROM ConfigurationOptions WHERE Code = 1045
	IF (@Error = 0) and (@DownloadAttributes = 0) BEGIN
	  SET @SQL = 'DECLARE @OptionID int ' +
        'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
		'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
        'Values(@OptionID, ''Download central Attributes tables'', ''YES'', 3, 1045, 1, GetDate(), ''Script'', 0, 0) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

	SELECT @DownloadGenericCalendars = COUNT(*) FROM ConfigurationOptions WHERE Code = 1046
	IF (@Error = 0) and (@DownloadGenericCalendars = 0) BEGIN
	  SET @SQL = 'DECLARE @OptionID int ' +
        'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
		'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
        'Values(@OptionID, ''Download central GenericCalendars table'', ''YES'', 3, 1046, 1, GetDate(), ''Script'', 0, 0) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

    SELECT @DownloadCustomFOPMenus = COUNT(*) FROM ConfigurationOptions WHERE Code = 1090
    IF (@Error = 0) and (@DownloadCustomFOPMenus = 0) BEGIN
      SET @SQL = 'DECLARE @OptionID int ' +
        'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
        'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
        'Values(@OptionID, ''Download central FOPMenuHeaders table'', ''YES'', 3, 1090, 1, GetDate(), ''Script'', 0, 0) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

    SELECT @DownloadCustomFOPMenus = COUNT(*) FROM ConfigurationOptions WHERE Code = 1091
    IF (@Error = 0) and (@DownloadCustomFOPMenus = 0) BEGIN
      SET @SQL = 'DECLARE @OptionID int ' +
        'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
        'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
        'Values(@OptionID, ''Download central FOPMenuDetails table'', ''YES'', 3, 1091, 1, GetDate(), ''Script'', 0, 0) '
      EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
      END

    SELECT @DownloadDebitTypes = COUNT(*) FROM ConfigurationOptions WHERE Code = 1183
    IF (@Error = 0) and (@DownloadDebitTypes = 0) BEGIN
      SET @SQL = 'DECLARE @OptionID int ' +
          'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
      'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
          'Values(@OptionID, ''Download central DebitTypes table'', ''YES'', 3, 1183, 1, GetDate(), ''Script'', 0, 0) '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    SELECT @ConfigOptionCount = COUNT(*) FROM ConfigurationOptions WHERE Code = 1243
    IF (@Error = 0) and (@ConfigOptionCount = 0) BEGIN
      SET @SQL = 'DECLARE @OptionID int ' +
          'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
          'Insert into ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
          'Values(@OptionID, ''Download central OE ItemGroups table'', ''YES'', 3, 1243, 1, GetDate(), ''Script'', 0, 0) '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    SELECT @ConfigOptionCount = COUNT(*) FROM ConfigurationOptions WHERE Code = 949 AND Value <> ''
    IF (@Error = 0) and (@ConfigOptionCount = 0) BEGIN
      SET @SQL = 'DECLARE @OptionID int ' +
          'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
          'DELETE FROM ConfigurationOptions WHERE Code = 949 ' +
          'INSERT INTO ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
          'VALUES (@OptionID, ''Customer License Key (GUID) for Galaxy Management Server Features'', NEWID(), 2, 949, 1, GetDate(), ''Script'', 0, 0) '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
  END

IF (@Error = 0) and (@RunMode = 21) BEGIN   /* Post Upgrade Mode - remove obsolete configuration options */
  DELETE FROM ConfigurationOptions WHERE Code BETWEEN 16 AND 20
  END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END



