/* Check the collation of the IdentificationNo column, change to case-sensitive if necessary. */
DECLARE
    @CurrentCollation sysname,
    @NewCollation sysname,
    @CIIndex integer,
    @IDNoIndexExists integer,
    @CollationSQL varchar(1000)

PRINT 'Checking CustContacts.IdentificationNo column collation'
SELECT @CurrentCollation = collation_name FROM sys.columns WHERE OBJECT_ID IN (SELECT OBJECT_ID FROM sys.objects WHERE type = 'U' AND name = 'CustContacts') AND name = 'IdentificationNo'
-- Look for _CI_ in the collation name to see if the current collation is case-insensitive, e.g. Latin1_General_CI_AS vs Latin1_General_CS_AS
set @CIIndex = CHARINDEX('_CI_', @CurrentCollation)
IF @CIIndex > 0 BEGIN
    PRINT 'Dropping the IXCustContactsIdentificationNo index'
    EXEC @IDNoIndexExists = GTSIndexExists @TableName, IXCustContactsIdentificationNo
    IF @IDNoIndexExists = 1 BEGIN
        SET @CollationSQL = 'DROP INDEX CustContacts.IXCustContactsIdentificationNo'
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @CollationSQL
        /* Stop the script if an error has occurred */
        IF (@Error <> 0) BEGIN
            EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
            RETURN
            END

        SET @CollationSQL = 'DELETE FROM TableIndexDefs where TableName = ''' + @TableName + ''' and IndexName=''IXCustContactsIdentificationNo'''
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @CollationSQL
        /* Stop the script if an error has occurred */
        IF (@Error <> 0) BEGIN
            EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
            RETURN
            END
        END

    PRINT 'Changing CustContacts.IdentificationNo column collation to be case-sensitive'
    SET @NewCollation = REPLACE(@CurrentCollation, '_CI_', '_CS_')
	SET @NewCollation = REPLACE(@NewCollation, '_AI', '_AS')
    SET @CollationSQL = 'ALTER TABLE dbo.CustContacts ALTER COLUMN IdentificationNo nvarchar(64) COLLATE ' + @NewCollation + ' NULL'
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @CollationSQL
    /* Stop the script if an error has occurred */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    PRINT 'Recreating the IXCustContactsIdentificationNo index'
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName,  IdentificationNo,  IXCustContactsIdentificationNo
    /* Stop the script if an error has occurred */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END


IF (@Error = 0) AND (@MultiSite_SIHOTPMSServiceModule = 1) BEGIN
    PRINT 'Adding trSIHOTServiceContactInsert Trigger to CustContacts'

    IF dbo.GTSIsTrigger('trSIHOTServiceContactInsert') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trSIHOTServiceContactInsert'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
    SET @SQL =
    'CREATE TRIGGER [dbo].[trSIHOTServiceContactInsert] ON [dbo].[CustContacts] FOR INSERT
            AS BEGIN
                SET NOCOUNT ON

                DECLARE @ProcessCode Int
                DECLARE @MessageType Int
                DECLARE @Action      Int
                SET @ProcessCode = 14  /* PC_SIHOT_PMS_SERVICE     */
                SET @MessageType = 4   /* SITEMESSAGE_TYPE_CONTACT */
                SET @Action      = 1   /* ACTION_INSERT            */

                DECLARE InsertedIterator CURSOR FOR SELECT CustContactID FROM INSERTED
                DECLARE @CustContactID Int
                DECLARE @SiteUniqueID Int

                OPEN InsertedIterator
                FETCH NEXT FROM InsertedIterator into @CustContactID
                WHILE (@@FETCH_STATUS = 0) BEGIN
                    DECLARE SitesIterator CURSOR FOR
                        SELECT
                            DISTINCT SiteUniqueID
                        FROM
                            SiteMessages
                        WHERE
                            MessageType = @MessageType

                    OPEN SitesIterator
                    FETCH NEXT FROM SitesIterator into @SiteUniqueID
                    WHILE (@@FETCH_STATUS = 0) BEGIN
                        INSERT INTO GxTriggers(TableName, ProcessCode, Action, NodeNo, ProcessStatus, CreateDate, Tries, Priority, LastError, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
                        Values (''CustContacts'', @ProcessCode, @Action, NULL, 0, CURRENT_TIMESTAMP, NULL, NULL, '''', @CustContactID, @SiteUniqueID, 1, CURRENT_TIMESTAMP, ''sa'')
                        FETCH NEXT FROM SitesIterator into @SiteUniqueID
                        END
                    CLOSE SitesIterator
                    DEALLOCATE SitesIterator

                    FETCH NEXT FROM InsertedIterator into @CustContactID
                    END

                CLOSE InsertedIterator
                DEALLOCATE InsertedIterator
                END'

    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END


    PRINT 'Adding trSIHOTServiceContactUpdate Trigger to CustContacts'

    IF dbo.GTSIsTrigger('trSIHOTServiceContactUpdate') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trSIHOTServiceContactUpdate'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
    SET @SQL =
    'CREATE TRIGGER [dbo].[trSIHOTServiceContactUpdate] ON [dbo].[CustContacts] FOR UPDATE
            AS BEGIN
                SET NOCOUNT ON

                DECLARE @ProcessCode Int
                DECLARE @MessageType Int
                DECLARE @Action      Int
                SET @ProcessCode = 14  /* PC_SIHOT_PMS_SERVICE     */
                SET @MessageType = 4   /* SITEMESSAGE_TYPE_CONTACT */
                SET @Action      = 3   /* ACTION_UPDATE            */

                DECLARE InsertedIterator CURSOR FOR SELECT INSERTED.CustContactID FROM INSERTED
                DECLARE @CustContactID Int
                DECLARE @SiteUniqueID Int

                OPEN InsertedIterator
                FETCH NEXT FROM InsertedIterator into @CustContactID
                WHILE (@@FETCH_STATUS = 0) BEGIN
                    DECLARE SitesIterator CURSOR FOR
                        SELECT
                            DISTINCT SiteUniqueID
                        FROM
                            SiteMessages
                        WHERE
                            MessageType = @MessageType

                    OPEN SitesIterator
                    FETCH NEXT FROM SitesIterator into @SiteUniqueID
                    WHILE (@@FETCH_STATUS = 0) BEGIN
                      INSERT INTO GxTriggers(TableName, ProcessCode, Action, NodeNo, ProcessStatus, CreateDate, Tries, Priority, LastError, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
                      Values (''CustContacts'', @ProcessCode, @Action, NULL, 0, CURRENT_TIMESTAMP, NULL, NULL, '''', @CustContactID, @SiteUniqueID, 1, CURRENT_TIMESTAMP, ''sa'')
                      FETCH NEXT FROM SitesIterator into @SiteUniqueID
                      END
                    CLOSE SitesIterator
                    DEALLOCATE SitesIterator

                    FETCH NEXT FROM InsertedIterator into @CustContactID
                    END

                CLOSE InsertedIterator
                DEALLOCATE InsertedIterator
                END '

    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END

