SET @TableName = 'DebitTypes'
SET @TableStructure = '
        DebitTypeID        int            NOT NULL,
        MediaID            int                NULL,
        Description        nvarchar(40)       NULL,
        ExpirationType     int                NULL,
        ExpirationDate     datetime           NULL,
        ExpirationDays     int                NULL,
        JournalizeLookups  bit                NULL,
        ExternalHost       int                NULL,
        UseExternalMedia   bit                NULL,
        PluginID           int                NULL,
        UnloadPLU          nchar(20)          NULL,
	DebitTypeGUID	   uniqueidentifier   NULL,
	ExpiredPLU         nvarchar(20)       NULL,

        RecordVersion      int            NOT NULL,
        LastUpdate         datetime       NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
	
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
          Adding a new nullable column JournalizeLookups bit NULL

  029668  Remove LookupPrinter and LookupTicketSet
  038662  Change ExternalHost from bit to integer
*/

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  DebitTypes,  JournalizeLookups,  bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  DebitTypes,  ExternalHost,       bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  DebitTypes,  UseExternalMedia,   bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  DebitTypes,  PluginID,           int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  DebitTypes,  UnloadPLU,          nchar, 20
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  DebitTypeGUID,	     uniqueidentifier
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  DebitTypes,  ExpiredPLU,         nvarchar, 20

EXEC GTSUpgradeAddNewIDConstraintForGUID @RunMode, @Error OUTPUT, @DropDependency, @TableName, DebitTypeGUID, 1

EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT,  @DropDependency, DebitTypes, ExternalHost, int

IF ((@RunMode / 10) = 2) BEGIN   /* Post Upgrade Mode */
    IF (@DropObsoletedColumns = 1) BEGIN
        EXEC @ColumnExists = GTSColumnExists  DebitTypes, LookupPrinter
        IF (@ColumnExists = 1) BEGIN
            SET @SQL = 'ALTER TABLE DebitTypes DROP COLUMN LookupPrinter'

            EXEC GTSUpgradeGatherTableIndexes  DebitTypes
            EXEC GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, DebitTypes, LookupPrinter, @DropDependency /* do drop dependency */

            SET @Log = 'Dropping an obsoleted column "LookupPrinter"...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

            SET @SQL = 'ALTER TABLE DebitTypes DROP COLUMN LookupTicketSet'

            EXEC GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, DebitTypes, LookupTicketSet, @DropDependency /* do drop dependency */

            SET @Log = 'Dropping an obsoleted column "LookupTicketSet"...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END
        END
    ELSE BEGIN
        SET @Log = '"LookupPrinter" and "LookupTicketSet" columns are no longer used.  These columns should be dropped by,'  + CHAR(13) + '    ' +
                   'either, manually running the provided script, or setting @DropObsoletedColumns to 1 (true)' + CHAR(13) + '    ' +
                   'at the beginning of the script.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

        SET @SQL = 'ALTER TABLE DebitTypes DROP COLUMN LookupPrinter'
        EXEC GTSUpgradeExecSQL  20 /* Test post upgrade mode */, @Error OUTPUT, @SQL
        SET @SQL = 'ALTER TABLE DebitTypes DROP COLUMN LookupTicketSet'
        EXEC GTSUpgradeExecSQL  20 /* Test post upgrade mode */, @Error OUTPUT, @SQL
        END
    END

