    -- Name column has been changed from "Name nvarchar(8) NOT NULL" to "char(8) NOT NULL"
    -- Descr column has been changed from "Descr nvarchar(40) NOT NULL" to "char(40) NOT NULL"
    -- LastUpdatedBy column has been changed from "LastUpdatedBy nvarchar(10) NOT NULL" to "char(10) NOT NULL"
