IF @WebStoreDB = 1 and @Transportation = 1 BEGIN
    SET @TableName = 'Fares'
    SET @TableStructure = '
        FareID                 int             NOT NULL,     -- Primary Key
        Carrier                nchar(4)             NULL,     -- Refers to Carriers.Carrier
        Origin                 int             NOT NULL,     -- Refers to Cities.Code    Includes specific city codes and wildcards for * /STATE and */ *
        Destin                 int             NOT NULL,     -- Refers to Cities.Code    Includes specific city codes and wildcards for * /STATE and */ *
        OriginZone             int                 NULL,     -- Refers to Zones.ZoneID
        DestinZone             int                 NULL,     -- Refers to Zones.ZoneID
        OW                     bit                 NULL,     -- True if fare is available one way
        RT                     bit                 NULL,     -- True if fare is available round trip
        OWFare                 smallmoney          NULL,     -- Actual fare if Method is "V" or "$"
        RTFare                 smallmoney          NULL,     -- Actual fare if Method is "V" or "$"
        Restrictions           nvarchar(36)         NULL,     -- Semi-free form A7,S,X67H etc
        TariffID               int                 NULL,     -- Refers to Tariffs.TariffID    While this is the foreign key reference for tariffs, it is also used to get honoring carriers.
        TemplateID             int                 NULL,     -- Refers to Templates.TemplateID
        Method                 nchar(1)             NULL,     -- "M" for mileage based, "C" for combined, otherwise "$"
        MethodID               int                 NULL,     -- Refers to MRT.MRTID
        EffDate                datetime        NOT NULL,     -- Effective date
        ExpDate                datetime            NULL,     -- Expiration date
        EffSell                datetime            NULL,     -- Date to start selling (EffDate - Adv Purchase)
        ExpSell                datetime            NULL,     -- Date to stop selling  (ExpDate - Adv Purchase)
        OWLimit                smallint            NULL,     -- Number of days one way ticket is valid
        RTLimit                smallint            NULL,     -- Number of days round trip ticket is valid

        RecordVersion          int             NOT NULL,
        LastUpdate             datetime        NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
    ' -- *** NO CLOSING PARENTHESIS

    EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

    EXEC GTSUpgradeAddPK     @RunMode, @Error OUTPUT, @TableName, FareID, PKFaresFareID

    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'EffDate,ExpDate,Origin,Destin', IXFaresEffExpDateOriginDestin
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'OriginZone,DestinZone', IXFaresOriginZoneDestinZone
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'Origin,Destin,EffDate', IXFaresOriginDestinEffDate

    END
/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END







