EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  AlternateReturnFOP,    int
IF @Boolean = 0 BEGIN
    SET @Log = 'One time upgrade of FOPs.AlternateReturnFOP. The ChangeFOP value will be copied to the new AlternateReturnFOP column.'
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
    SET @SQL = 'UPDATE FOPs SET AlternateReturnFOP = ChangeFOP'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

EXEC @Boolean = GTSColumnExists @TableName, 'AlternateReturnFOP'
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  AlternateReturnFOP,    int
IF @Boolean = 0 BEGIN
    SET @Log = 'One time upgrade of FOPs.AlternateReturnFOP. The ChangeFOP value will be copied to the new AlternateReturnFOP column.'
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
    SET @SQL = 'UPDATE FOPs SET AlternateReturnFOP = ChangeFOP'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF ((@RunMode / 10) = 2) BEGIN   /* Post Upgrade Mode */
    /*
    The following rename is a special change.  The change is to rename AllowReferal to AllowReferral.
    DBSynch must be upgrade to 1.8.14+  once this is excuted in upgrade or post upgrade mode.
    */
    DECLARE
        @AllowReferalExists bit

    EXEC @AllowReferalExists = GTSColumnExists @TableName, 'AllowReferal'
    IF @AllowReferalExists = 1 BEGIN
        SET @SQL = 'EXEC sp_rename ''FOPs.AllowReferal'', ''AllowReferral'''
        SET @Log = 'The FOPs.AllowReferal column created by DBSynch prior to 1.8.14 was mispelled.  ' +
                   'The correct column name should have been FOPs.AllowReferral.  Once this column has been ' +
                   'corrected by this script, DBSynch must be upgrade to 1.8.14 or later.'
        EXEC GTSAddUpgradeLog  @RunMode, @Log, 1  /* just add it */
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END

    EXEC GTSPostUpgradeChangePK  @RunMode, @Error OUTPUT, FOPs, FOPID, PKFOPsFOPID
    END

