SET @TableName = 'GxEventLog'
SET @TableStructure = '
        GxEventLogUID    bigint         NOT NULL	IDENTITY(1,1),
        EventDateTime    datetime       NOT NULL,
        NodeID           int                NULL,
        UserID           int                NULL,
        Severity         int            NOT NULL,
        ApplicationName  nvarchar(40)       NOT NULL,
        ProcessName      nvarchar(40)           NULL,
        EventText        nvarchar(1000)         NULL,
        EventData        nvarchar(100)          NULL,
        ErrorCode        int                NULL,
        EventCode        int                NULL,
        EventSubCode     int                NULL,
        AgencyNo         int                NULL,

        RecordVersion    int            NOT NULL,
        LastUpdate       datetime       NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

EXEC @ColumnExists = GTSColumnExists @TableName, 'GxEventLogUID'
IF @ColumnExists = 0 BEGIN
    -- Drop whatever the PK currently is, it will great recreated when we call GTSUpgradeAddPK below
    EXEC GTSDropTablePK @RunMode, @Error OUTPUT, @TableName
    IF @Error <> 0 BEGIN
        EXEC GTSUpgradeDoEndUpgrade @RunMode, @Error, @TableName
        RETURN
        END

    SET @SQL = 'ALTER TABLE GxEventLog ALTER COLUMN GxEventLogID int NULL'
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    IF @Error <> 0 BEGIN
        EXEC GTSUpgradeDoEndUpgrade @RunMode, @Error, @TableName
        RETURN
        END
    END

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, EventCode,    int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, EventSubCode, int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, AgencyNo,     int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, GxEventLogUID, bigint, -1, 'NOT NULL', NULL, 1

EXEC GTSUpgradeDropColumn @RunMode, @Error OUTPUT, @TableName, GxEventLogID, @DropObsoletedColumns

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  GxEventLog, GxEventLogUID, PKGxEventLog

EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, EventDateTime, IXGxEventLogEventDateTime
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'Severity,ApplicationName,ProcessName,EventDateTime', IXGxEventLogViewLog

IF @AddIndexesForAttributeBasedPricing = 1 BEGIN
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, EventData, IXGxEventLogEventData
    END

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

IF dbo.GTSIsTrigger('trGxEventLogInsert') = 1 BEGIN
    SET @SQL = 'DROP TRIGGER dbo.trGxEventLogInsert'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF @WebStoreDB = 1 AND @Error = 0 BEGIN
    PRINT 'Adding trGxEventLogInsert Trigger to GxEventLog for the web store'

    SET @SQL =
    'CREATE TRIGGER [dbo].[trGxEventLogInsert] ON [dbo].[GxEventLog] AFTER INSERT
    AS BEGIN
        SET NOCOUNT ON

        DECLARE @GxEventLogID bigint
        DECLARE EventIDs CURSOR FOR
            SELECT GxEventLogUID
            FROM INSERTED

        OPEN EventIDs
        WHILE 1 = 1 BEGIN
            FETCH NEXT FROM EventIDs INTO @GxEventLogID

            IF @@FETCH_STATUS <> 0 BREAK

            INSERT INTO GxTriggers
                (TableName,     RecordID,
                 ProcessCode,   Action,        ProcessStatus,
                 CreateDate,    RecordVersion, LastUpdate,
                 LastUpdatedBy)
            VALUES
                (''GxEventLog'',    -- TableName
                @GxEventLogID,      -- RecordID
                10,                 -- ProcessCode:   PC_LOG_TRANSFER_SERVICE
                1,                  -- Action:        ACTION_INSERT
                0,                  -- ProcessStatus: STATUS_AVAILABLE
                CURRENT_TIMESTAMP,  -- CreateDate
                1,                  -- RecordVersion
                CURRENT_TIMESTAMP,  -- LastUpdate
                ''EventLogTr'')       -- LastUpdatedBy
                END

        CLOSE EventIDs
        DEALLOCATE EventIDs
        END '

    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

