EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  GxUsers, ExternalLogonID, IXExternalLogonID

-- Active column default value = 1 (TRUE)
DECLARE @ActiveColumnExists bit
EXEC @ActiveColumnExists = GTSColumnExists @TableName, Active
IF (@Error = 0) and  (@ActiveColumnExists = 1) BEGIN
    SET @SQL = ' Update GXUsers set Active = 1 where Active is Null '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF @WebStoreDB = 1 BEGIN   /* Upgrade or Post-Upgrade Mode */

    -- For WebStore DB: populate Addresses.PersistenceState column
    EXEC @TableExists  = GTSTableExists  Addresses
    IF @TableExists = 1 BEGIN EXEC @TableExists  = GTSTableExists  CustContacts END
    IF @TableExists = 1 BEGIN EXEC @TableExists  = GTSTableExists  GxUsers  END

    DECLARE @ColumnFound bit
    EXEC @ColumnFound = GTSColumnExists GxUsers, ContactID
    IF @ColumnFound = 1 BEGIN EXEC @ColumnFound = GTSColumnExists GxUsers, Publish END

    IF @TableExists = 1 and @ColumnFound = 1 BEGIN
        SET @SQL = 'UPDATE addresses set PersistenceState = 3 where ((PersistenceState <> 3) or (PersistenceState is NULL)) and AddressID in ( ' +
                   'Select distinct a.addressID from addresses a, CustContacts cc ' +
                   'where cc.AddressID = a.AddressID and cc.CustContactID in ( ' +
                   'select distinct cc.CustContactID from CustContacts cc, GxUsers u ' +
                   'where u.ContactID <> 0 and (not u.ContactID is Null) and u.ContactID = cc.CustContactID and u.Publish = 1))'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    END

