/* Unfortunately, this cannot be a unique index, even though it should be.
   PDAutomation has duplicate entries in the ItemGUID column.
   Checked several customer config backups and didn't find any duplicate ItemGUIDs. */
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, ItemGUID, IXItemsItemGUID

IF @EnableSmartUpsell = 1 BEGIN
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, LastUpdate, IXItemsLastUpdate
    END

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

--
--              PROCEDURE GTS_SP_UpdateItemPrices
--    /*  Update item prices based on the ItemPrices table  */
--
DECLARE @ItemPricesSPSQL varchar(8000)
PRINT '    ' + 'Creating GTS_SP_UpdateItemPrices...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
       WHERE (o.name = 'GTS_SP_UpdateItemPrices') AND (o.type = 'P')
       AND   (o.uid = u.uid)
       AND   (u.name = 'dbo')) BEGIN
    SET @ItemPricesSPSQL = 'DROP PROCEDURE dbo.GTS_SP_UpdateItemPrices'
    EXEC(@ItemPricesSPSQL)
    END

SET @ItemPricesSPSQL =
    'CREATE PROCEDURE dbo.GTS_SP_UpdateItemPrices
    @ProcessDate DateTime,
	@ApplicationName char(40),
	@NodeID int,
	@AgencyNo int,
	@UserID int,
    @ItemUpdateCount Int OUTPUT
AS BEGIN
  SET NOCOUNT ON  /* Turn off NOCOUNT option so number of rows affected by every select does not get reported  */
  DECLARE
    @PLU char(20),
    @RowsAffected integer,
    @NewPrice money,
    @NewCost money,
    @NewMinPrice money,
    @NewMaxPrice money,
    @OldPrice money,
    @OldCost money,
    @OldMinPrice money,
    @OldMaxPrice money,
    @EffectiveDate datetime,
    @CurrentDateTime datetime,
    @GxEventLogUID bigint,
    @EventText char(1000),
    @NextPublishCount int,
    @PackagePLU char(20),
    @OldPackagePrice money,
    @NewPackagePrice money,
    @DetailQuantity int

  SET @ItemUpdateCount = 0
  SET @CurrentDateTime = GetDate()

  DECLARE UpdateItemPricesCursor CURSOR FOR
    SELECT ip.PLU, ip.EffectiveDate, ip.Price as NewPrice, ip.Cost as NewCost, ip.MinPrice as NewMinPrice, ip.MaxPrice as NewMaxPrice,
           i.price as OldPrice, i.Cost as OldCost, i.MinPrice as OldMinPrice, i.MaxPrice as OldMaxPrice FROM ItemPrices AS ip
    INNER JOIN (SELECT MAX(EffectiveDate) AS EffectiveDate, PLU FROM ItemPrices WHERE EffectiveDate <= @ProcessDate GROUP BY PLU) AS mp
    INNER JOIN Items i on mp.PLU = i.PLU and i.ItemPriceMethod = 1
    ON (ip.PLU = mp.PLU) AND (ip.EffectiveDate = mp.EffectiveDate) and ((i.Price <> ip.Price) or (i.Cost <> ip.Cost) or (i.MinPrice <> ip.MinPrice) or (i.MaxPrice <> ip.MaxPrice))
    ORDER BY ip.PLU
  OPEN UpdateItemPricesCursor
  FETCH NEXT FROM UpdateItemPricesCursor INTO @PLU, @EffectiveDate, @NewPrice, @NewCost, @NewMinPrice, @NewMaxPrice, @OldPrice, @OldCost, @OldMinPrice, @OldMaxPrice
  WHILE ( @@Fetch_Status = 0 ) BEGIN
    UPDATE Items set Price = @NewPrice, Cost = @NewCost, MinPrice = @NewMinPrice, MaxPrice = @NewMaxPrice, RecordVersion = RecordVersion + 1, LastUpdatedBy = ''ItmPrcUpd''
    WHERE (PLU = @PLU)

	SET @EventText = ''The PLU "'' + RTRIM(@PLU) + ''" was updated.  Effective Date: '' + CAST(@EffectiveDate as varchar(50)) + '', Price: '' + CAST(@OldPrice as varchar(20)) + ''-->'' + CAST(@NewPrice as varchar(20)) + '', Cost: '' + CAST(@OldCost as varchar(20)) + ''-->'' + CAST(@NewCost as varchar(20))+ '', MinPrice: '' + CAST(@OldMinPrice as varchar(20)) + ''-->'' + CAST(@NewMinPrice as varchar(20)) + '', MaxPrice: '' + CAST(@OldMaxPrice as varchar(20)) + ''-->'' + CAST(@NewMaxPrice as varchar(20))
	-- Insert a row in GxEventLog for each item updated
	INSERT INTO GxEventLog (EventDateTime, NodeID, AgencyNo, UserID, Severity, ApplicationName, ProcessName, EventText, EventData, ErrorCode, EventCode, EventSubCode, RecordVersion, LastUpdate, LastUpdatedBy )
	VALUES (
		@CurrentDateTime,
		@NodeID,
		@AgencyNo,
		@UserID,
		0, -- 0 = InformationSeverity
		@ApplicationName,
		''Price Update'',
		@EventText,
		@PLU, -- EventData
		0, -- ErrorCode
		0, -- EventCode
		0, -- EventSubCode
		1, -- RecordVersion
		@CurrentDateTime,
		''ItmPrcUpd'')

    SELECT @GxEventLogUID = @@IDENTITY
    SELECT @RowsAffected = @@ROWCOUNT
    SET @ItemUpdateCount = @ItemUpdateCount + @RowsAffected

    -- Insert a row into GxTriggers
    INSERT INTO GxTriggers
            (TableName,     RecordID,
             ProcessCode,   Action,        ProcessStatus,
             CreateDate,    RecordVersion, LastUpdate,
             LastUpdatedBy)
    VALUES
            (''GxEventLog'',    -- TableName
            @GxEventLogUID,     -- RecordID
            10,                 -- ProcessCode:   PC_SYSLOG_SENDER_SERVICE
            1,                  -- Action:        ACTION_INSERT
            0,                  -- ProcessStatus: STATUS_AVAILABLE
            CURRENT_TIMESTAMP,  -- CreateDate
            1,                  -- RecordVersion
            CURRENT_TIMESTAMP,  -- LastUpdate
            ''ItmPrcUpd'')      -- LastUpdatedBy

    -- Update price on all sum-of-details priced packages containing the item
    DECLARE PackageCursor CURSOR FOR
        SELECT I.PLU, I.Price, PD.Quantity
        FROM PackageDetails PD
        INNER JOIN Packages P
            ON P.PriceMethod = 1
            AND P.PackagePLU = PD.PackagePLU
        INNER JOIN Items I
            ON I.PLU = P.PackagePLU
        WHERE PD.ItemPLU = @PLU

    OPEN PackageCursor
    FETCH NEXT FROM PackageCursor INTO @PackagePLU, @OldPackagePrice, @DetailQuantity
    WHILE (@@FETCH_STATUS = 0) BEGIN
        SET @NewPackagePrice = @OldPackagePrice - (@OldPrice * @DetailQuantity) + (@NewPrice * @DetailQuantity)

        UPDATE Items
        SET Price = @NewPackagePrice, RecordVersion = RecordVersion + 1, LastUpdatedBy = ''ItmPrcUpd'', LastUpdate = @CurrentDateTime
        WHERE PLU = @PackagePLU

        SET @EventText = ''The Package PLU "'' + RTRIM(@PackagePLU) + ''" was updated.  Effective Date: '' + CAST(@EffectiveDate as varchar(50)) + '', Price: '' + CAST(@OldPackagePrice as varchar(20)) + ''-->'' + CAST(@NewPackagePrice as varchar(20))
        -- Insert a row in GxEventLog for each item updated
        INSERT INTO GxEventLog (EventDateTime, NodeID, AgencyNo, UserID, Severity, ApplicationName, ProcessName, EventText, EventData, ErrorCode, EventCode, EventSubCode, RecordVersion, LastUpdate, LastUpdatedBy )
        VALUES (
            @CurrentDateTime,
            @NodeID,
            @AgencyNo,
            @UserID,
            0, -- 0 = InformationSeverity
            @ApplicationName,
            ''Price Update'',
            @EventText,
            @PackagePLU, -- EventData
            0, -- ErrorCode
            0, -- EventCode
            0, -- EventSubCode
            1, -- RecordVersion
            @CurrentDateTime,
            ''ItmPrcUpd'')

        SELECT @GxEventLogUID = @@IDENTITY
        SELECT @RowsAffected = @@ROWCOUNT
        SET @ItemUpdateCount = @ItemUpdateCount + @RowsAffected

        -- Insert a row into GxTriggers
        INSERT INTO GxTriggers
            (TableName,     RecordID,
             ProcessCode,   Action,        ProcessStatus,
             CreateDate,    RecordVersion, LastUpdate,
             LastUpdatedBy)
        VALUES
            (''GxEventLog'',    -- TableName
            @GxEventLogUID,     -- RecordID
            10,                 -- ProcessCode:   PC_SYSLOG_SENDER_SERVICE
            1,                  -- Action:        ACTION_INSERT
            0,                  -- ProcessStatus: STATUS_AVAILABLE
            CURRENT_TIMESTAMP,  -- CreateDate
            1,                  -- RecordVersion
            CURRENT_TIMESTAMP,  -- LastUpdate
            ''ItmPrcUpd'')      -- LastUpdatedBy

        FETCH NEXT FROM PackageCursor INTO @PackagePLU, @OldPackagePrice, @DetailQuantity
        END

    CLOSE PackageCursor
    DEALLOCATE PackageCursor

    FETCH NEXT FROM UpdateItemPricesCursor INTO @PLU, @EffectiveDate, @NewPrice, @NewCost, @NewMinPrice, @NewMaxPrice, @OldPrice, @OldCost, @OldMinPrice, @OldMaxPrice
    END

  CLOSE UpdateItemPricesCursor
  DEALLOCATE UpdateItemPricesCursor

  -- Manually publish all the RowChanges entries that this SP just generated for the Items table (ITEM_DBID = 8)
  EXEC @NextPublishCount = GetNextPublishCount
  UPDATE RowChanges SET PublishCount = @NextPublishCount where (PublishCount = 0) and (TableID = 8) and (LastUpdatedBy = ''ItmPrcUpd'')
  END'

EXEC(@ItemPricesSPSQL)


--
--  -------------------------------------------------------------------
--
--                  ***  ItemModifierGroupDetails  ***
--
SET @TableName = 'ItemModifierGroupDetails'
SET @TableStructure = '
        ItemModifierGroupDetailID  int  NOT NULL,
        ItemPLU           nvarchar(20)  NOT NULL,
        ModifierGroupID   int           NOT NULL,
        SelectMax         int               NULL,
        SelectMin         int               NULL,
        Sequence          int               NULL,
        OverrideGroupMinMax bit             NULL,
        ItemModifierGroupDetailGUID uniqueidentifier  NULL,

        RecordVersion     int           NOT NULL,
        LastUpdate        datetime      NOT NULL,
        LastUpdatedBy     nvarchar(20)      NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

DECLARE @IsClustered bit
EXEC @IndexExists = GTSIndexExists @TableName, PKItemModifierGroupDetailID
SET @IsClustered  = IsNULL(IndexProperty (object_id(@TableName), 'PKItemModifierGroupDetailID', 'IsClustered'), 0)
IF (@IndexExists = 1) AND (@IsClustered = 0) BEGIN
    PRINT '    Dropping the non-clustered PKItemModifierGroupDetailID, allow it to be recreated as clustered'
    EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, PKItemModifierGroupDetailID
    END

EXEC GTSUpgradeAddPK     @RunMode, @Error OUTPUT, @TableName, ItemModifierGroupDetailID, PKItemModifierGroupDetailID

EXEC GTSUpgradeAddColumn @RunMode, @Error OUTPUT,  @TableName, ItemModifierGroupDetailGUID, uniqueidentifier

EXEC GTSUpgradeAddNewIDConstraintForGUID @RunMode, @Error OUTPUT, @DropDependency, @TableName, ItemModifierGroupDetailGUID, 1

EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'ItemPLU', IXItemModifierGroupDetailsItemPLU
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'ModifierGroupID', IXItemModifierGroupDetailsModifierGroupID

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END


