-- Legs table changed to ItineraryDetails, so if Legs still exists, RENAME it
EXEC @TableExists = GTSTableExists 'Legs'
IF (@TableExists = 1) BEGIN
    SET @SQL = ' EXECUTE sp_rename ''[dbo].[Legs]'', ''ItineraryDetails'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

-- RENAME LegID column to ItineraryDetailID
EXEC @TableExists = GTSTableExists 'ItineraryDetails'
EXEC @ColumnExists = GTSColumnExists @TableName, LegID
IF (@Error = 0) and (@TableExists = 1) and (@ColumnExists = 1) BEGIN
    SET @SQL = ' EXECUTE sp_rename ''[dbo].[ItineraryDetails].[LegID]'', ''ItineraryDetailID'', ''COLUMN'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END


-- RENAME the PK index if old still exists
EXEC @TableExists = GTSTableExists 'ItineraryDetails'
EXEC @IndexExists = GTSIndexExists  @TableName, PKLegsLegID
IF (@Error = 0) and (@TableExists = 1) and (@IndexExists = 1) BEGIN
    SET @SQL = ' EXECUTE sp_rename ''[dbo].[ItineraryDetails].[PKLegsLegID]'', ''PKItineraryDetailsID'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

-- RENAME the GatewayCounter For this table:
IF (@Error = 0) BEGIN
    SET @SQL = ' Update GatewayCounters set Name = ''ItineraryDetailID'' '+
               ' WHERE Name = ''LegID'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

