IF ((@RunMode / 10) = 2) BEGIN   /* Post-Upgrade Mode */
    EXEC GTSPostUpgradeAuditColumns  @RunMode, @Error OUTPUT, @DropDependency,  JnlChangeFunds

    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency,  JnlChangeFunds, JnlTranID, int

    EXEC @ColumnExists = GTSColumnExists  JnlChangeFunds, JnlDetailID
    IF (@ColumnExists = 1) BEGIN
        SET @SQL = 'ALTER TABLE JnlChangeFunds DROP COLUMN JnlDetailID'

        EXEC GTSUpgradeGatherTableIndexes  JnlChangeFunds
        EXEC GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, JnlChangeFudns, JnlDetailID, @DropDependency /* do drop dependency */

        IF (@DropObsoletedColumns = 1) BEGIN
            SET @Log = 'Dropping an obsoleted column "JnlDetailID"...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END
        ELSE BEGIN
            SET @Log = '"JnlDetailID" column is no longer used.  This column should be dropped either'             + CHAR(13) + '    ' +
                       'by manually running the provided script, or by setting @DropObsoletedColumns to 1 (true)' + CHAR(13) + '    ' +
                       'at the beginning of the script.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  20 /* Test post upgrade mode */, @Error OUTPUT, @SQL
            END
        END
    END

