SET @SQL = 'DECLARE @JnlTranID int'
SET @SQL = @SQL + ' DECLARE PostedToDB_cursor CURSOR for Select JnlTranID from JnlHeaders (NOLOCK) where PostedToDB is NULL'
SET @SQL = @SQL + ' OPEN PostedToDB_Cursor'
SET @SQL = @SQL + ' FETCH NEXT from PostedToDB_cursor into @JnlTranID'
SET @SQL = @SQL + ' WHILE (@@FETCH_STATUS = 0)'
SET @SQL = @SQL + ' BEGIN'
SET @SQL = @SQL + ' UPDATE JnlHeaders set PostedToDB = 1 where JnlTranID = @JnlTranID'
SET @SQL = @SQL + ' FETCH NEXT from PostedToDB_cursor into @JnlTranID'
SET @SQL = @SQL + ' END'
SET @SQL = @SQL + ' CLOSE PostedToDB_cursor'
SET @SQL = @SQL + ' DEALLOCATE PostedToDB_cursor'
EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

