EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT,  @TableName,  AKJnlHeadersNodeTranDateJnlSeq, 1 /* obsolete it */

/*
Now, we need to check if there was new JnlHeaders unique index create error.
If there was a problem creating the index and the @RemoveDupJnlEntries is not set to 1,
output an error message indicating so.
*/
DECLARE
    @Errored             bit,
    @RemoveDupJnlEntries bit

SELECT @RemoveDupJnlEntries = convert(bit, Value) FROM UpgradeSettings WHERE Setting = 'Remove Duplicate Journal Entries'
SELECT @RemoveDupJnlEntries = IsNULL(@RemoveDupJnlEntries, 0)

IF (@Error <> 0)
    SET @Errored = 1
ELSE
    SET @Errored = 0

IF @RemoveDupJnlEntries = 1 BEGIN
    EXEC GTSRemoveDupJnlEntries @RunMode, @Error OUTPUT
    END

EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName,  'NodeNo,TranNo,TranDate,JnlCode',  AKJnlHeadersNodeTranDateJnlCde,  'UNIQUE', '', 0, 'JnlTranID'
IF (@Errored = 0) AND (@Error <> 0) BEGIN
    -- error'ed creating the new unique index
    IF @RemoveDupJnlEntries = 0 BEGIN
        SET @Log = 'Could not create unique index on JnlHeaders.  Please set @RemoveDupJnlEntries = 1 to remove duplicated journal entries'
        END
    END

