    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

IF (@Error = 0) AND (@MultiSite_SIHOTPMSServiceModule = 1) BEGIN
    PRINT 'Adding trSIHOTServiceJnlHeadersInsert Trigger to JnlHeaders'

    IF dbo.GTSIsTrigger('trSIHOTServiceJnlHeadersInsert') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trSIHOTServiceJnlHeadersInsert'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
    SET @SQL =
    'CREATE TRIGGER [dbo].[trSIHOTServiceJnlHeadersInsert] ON [dbo].[JnlHeaders] FOR INSERT
            AS BEGIN
                SET NOCOUNT ON

                DECLARE @ProcessCode  Int
                DECLARE @MessageType  Int
                DECLARE @Action       Int
                SET @ProcessCode  = 14  /* PC_SIHOT_PMS_SERVICE           */
                SET @MessageType  = 5   /* SITEMESSAGE_TYPE_TRANSACTION  */
                SET @Action       = 1   /* ACTION_INSERT                  */

                DECLARE InsertedIterator CURSOR FOR SELECT JnlTranID, JnlCode, TranKind FROM INSERTED
                DECLARE @JnlTranID Int
                DECLARE @JnlCode Int
                DECLARE @TranKind Int
                DECLARE @SiteUniqueID Int

                OPEN InsertedIterator
                FETCH NEXT FROM InsertedIterator into @JnlTranID, @JnlCode, @TranKind
                WHILE (@@FETCH_STATUS = 0) BEGIN
                    IF @TranKind in (1, 4) BEGIN  /* TICKET_TRANS, VOID_TRANS */
                        DECLARE SitesIterator CURSOR FOR
                            SELECT
                                DISTINCT SiteUniqueID
                            FROM
                                SiteMessages
                            WHERE
                                MessageType = @MessageType

                        OPEN SitesIterator
                        FETCH NEXT FROM SitesIterator into @SiteUniqueID
                        WHILE (@@FETCH_STATUS = 0) BEGIN
                            INSERT INTO GxTriggers(TableName, ProcessCode, Action, NodeNo, ProcessStatus, CreateDate, Tries, Priority, LastError, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
                            Values (''JnlHeaders'', @ProcessCode, @Action, NULL, 0, CURRENT_TIMESTAMP, NULL, NULL, '''', @JnlTranID, @SiteUniqueID, 1, CURRENT_TIMESTAMP, ''sa'')
                            FETCH NEXT FROM SitesIterator into @SiteUniqueID
                            END
                        CLOSE SitesIterator
                        DEALLOCATE SitesIterator
                        END

                    FETCH NEXT FROM InsertedIterator into @JnlTranID, @JnlCode, @TranKind
                    END

                CLOSE InsertedIterator
                DEALLOCATE InsertedIterator
                END'

    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

    /*
    *  Stop the script if an error has occurred
    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END


