IF (@Error = 0) AND (@MultiSite_ExportServiceModule = 1) BEGIN
    PRINT 'Adding trExportServiceJnlItemsInsert Trigger to JnlItems'

    IF dbo.GTSIsTrigger('trExportServiceJnlItemsInsert') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trExportServiceJnlItemsInsert'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
    SET @SQL =
    'CREATE TRIGGER [dbo].[trExportServiceJnlItemsInsert] ON [dbo].[JnlItems] FOR INSERT
        AS BEGIN
            SET NOCOUNT ON

            DECLARE InsertedIterator CURSOR FOR
                SELECT JnlItemID, INSERTED.PLU
                FROM INSERTED
                  JOIN Items ON INSERTED.PLU = Items.PLU
                WHERE
                  Kind = 8 -- Retail Item
                  OR Kind = 22 -- Food and Beverage
            DECLARE @SiteUniqueID int
            DECLARE @JnlItemID int
            DECLARE @PLU nvarchar(20)

            OPEN InsertedIterator
            FETCH NEXT FROM InsertedIterator into @JnlItemID, @PLU
            WHILE (@@FETCH_STATUS = 0) BEGIN
                DECLARE SitesIterator CURSOR FOR
                    SELECT DISTINCT SiteUniqueID
                      FROM SiteItems
                      WHERE
                        SiteUniqueID IN (SELECT SiteUniqueID FROM SiteMessages WHERE (MessageType = 3 OR MessageType = 6) AND SiteUniqueID = SiteItems.SiteUniqueID)
                        AND
                         ((PLU <> '''' AND PLU = @PLU) OR
                          (ItemGroupID IN (SELECT ItemGroupID FROM ItemGroupDetails WHERE ItemGroupDetails.PLU = @PLU)))

                OPEN SitesIterator
                    FETCH NEXT FROM SitesIterator into @SiteUniqueID
                    WHILE (@@FETCH_STATUS = 0) BEGIN
                        INSERT INTO GxTriggers(TableName, ProcessCode, Action, NodeNo, ProcessStatus, CreateDate, Tries, Priority, LastError, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
                            Values (''JnlItems'', 8, 1, NULL, 0, CURRENT_TIMESTAMP, NULL, NULL, '''', @JnlItemID, @SiteUniqueID, 1, CURRENT_TIMESTAMP, ''sa'')
                        FETCH NEXT FROM SitesIterator into @SiteUniqueID
                        END
                    CLOSE SitesIterator
                    DEALLOCATE SitesIterator
               FETCH NEXT FROM InsertedIterator into @JnlItemID, @PLU
               END
           CLOSE InsertedIterator
           DEALLOCATE InsertedIterator
            END '

    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END

