-- RENAME JnlSegments to JnlItineraries
EXEC @TableExists = GTSTableExists 'JnlSegments'
IF (@TableExists = 1) BEGIN
    SET @SQL = ' EXECUTE sp_rename ''[dbo].[JnlSegments]'', ''JnlItineraries'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

-- RENAME PK JnlSegmentID column to JnlItineraryID
EXEC @TableExists = GTSTableExists 'JnlItineraries'
EXEC @ColumnExists = GTSColumnExists @TableName, JnlSegmentID
IF (@Error = 0) and (@TableExists = 1) and (@ColumnExists = 1) BEGIN
    SET @SQL = ' EXECUTE sp_rename ''[dbo].[JnlItineraries].[JnlSegmentID]'', ''JnlItineraryID'', ''COLUMN'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

-- RENAME the PK index, if old exists
EXEC @IndexExists = GTSIndexExists  @TableName, PKJnlSegmentID
IF (@Error = 0) and (@TableExists = 1) and (@IndexExists = 1) BEGIN
    SET @SQL = ' EXECUTE sp_rename ''[dbo].[JnlItineraries].[PkJnlSegmentID]'', ''PKJnlItineraryID'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

-- RENAME the clustered index, if old  exists
EXEC @IndexExists = GTSIndexExists  @TableName, CXJnlSegments
IF (@Error = 0) and (@TableExists = 1) and (@IndexExists = 1) BEGIN
    SET @SQL = ' EXECUTE sp_rename ''[dbo].[JnlItineraries].[CXJnlSegments]'', ''CXJnlItineraries'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

-- RENAME the GatewayCounter For this table:
IF (@Error = 0) BEGIN
    SET @SQL = ' Update GatewayCounters set Name = ''JnlItineraryID'' '+
               ' WHERE Name = ''JnlSegmentID'' '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

