--
SET @TableName = 'Lockouts'
SET @TableStructure = '
        LockoutID       int            NOT NULL,
        AccessCode      int            NOT NULL,
        Serial          nvarchar(20)   NOT NULL,
        HiSerial        nvarchar(20)   NOT NULL,
        LockoutMsg      nvarchar(80)       NULL,
        SoundFile       nvarchar(12)       NULL,
        AllowAccess     bit            NOT NULL,
        PageLead        bit            NOT NULL,
        LongReason      nvarchar(255)      NULL,
        FromVisualID    nvarchar(40)       NULL,
        ThruVisualID    nvarchar(40)       NULL,
        ExpirationDate  datetime           NULL,

        RecordVersion   int            NOT NULL,
        LastUpdate      datetime       NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
    -- Adding a new nullable column FromVisualID varchar(40) NULL
    -- Adding a new nullable column ThruVisualID varchar(40) NULL
    -- Adding a new nullable column ExpirationDate datetime NULL
 034927  Add index on (AccessCode,Serial) and (FromVisualID,ThruVisualID)
 */

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Lockouts,  FromVisualID  ,  varchar ,  40
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Lockouts,  ThruVisualID  ,  varchar ,  40
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Lockouts,  ExpirationDate,  datetime
IF ((@RunMode / 10) = 2) BEGIN   /* Post-Upgrade Mode */
    EXEC @ColumnExists = GTSColumnExists  Lockouts, ExpirationDate
    IF (@ColumnExists = 1) BEGIN
        PRINT '    ' + 'The following set of scripts will be executed if the IF condition is met...'
        SET @SQL = 'IF EXISTS (SELECT ExpirationDate FROM Lockouts WHERE ExpirationDate IS NULL) BEGIN' + CHAR(13) + '    ' +
                   '        DECLARE  @SQL    varchar(3000), '                                           + CHAR(13) + '    ' +
                   '                 @Error  int '                                                      + CHAR(13) + '    ' +
                   '        PRINT ''    Setting ExpirationDate to 2079-Dec-31 where NULL'' '            + CHAR(13) + '    ' +
                   '        SET @SQL = ''UPDATE Lockouts SET ExpirationDate = 65743 /*2079-Dec-31*/ WHERE ExpirationDate IS NULL'' ' + CHAR(13) + '    ' +
                   '        EXEC GTSUpgradeExecSQL  ' + convert(varchar, @RunMode) + ', @Error, @SQL' + CHAR(13) + '    ' +
                   '        END '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    END

EXEC GTSUpgradeAddPK    @RunMode, @Error OUTPUT,  Lockouts, LockoutID, PKLockoutsLockoutID
EXEC GTSUpgradeAddIndex @RunMode, @Error OUTPUT,  Lockouts, 'AccessCode,Serial,HiSerial', IXLockoutsACSerialHiSerial   -- 2.3.1
EXEC GTSUpgradeAddIndex @RunMode, @Error OUTPUT,  Lockouts, 'FromVisualID,ThruVisualID',  IXLockoutsFromThruVisualID   -- 2.3.1

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

