--
--              PROCEDURE GTSInsertLogData
--    /*  SP to write an entry to the LogData table */
--
DECLARE @GTSInsertLogDataSPSQL varchar(8000)
PRINT '    ' + 'Creating GTSInsertLogData...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
       WHERE (o.name = 'GTSInsertLogData') AND (o.type = 'P')
       AND   (o.uid = u.uid)
       AND   (u.name = 'dbo')) BEGIN
    SET @GTSInsertLogDataSPSQL = 'DROP PROCEDURE dbo.GTSInsertLogData'
    EXEC(@GTSInsertLogDataSPSQL)
    END

SET @GTSInsertLogDataSPSQL = 'CREATE PROCEDURE dbo.GTSInsertLogData(
    @ApplicationName varchar(20),
	@NodeNo int,
	@Date DateTime,
	@Time BigInt,
	@ThreadDeltaTime BigInt,
	@ThreadName varchar(40),
	@ThreadID int,
	@Source varchar(40),
	@TransactionID int,
	@Msg varchar(max),
	@EnterEntry bit,
	@ExitEntry bit,
	@Warning bit,
	@Error bit,
	@Exception bit,
	@StackTrace bit,
	@LastUpdatedBy nvarchar(20)
	) AS BEGIN
            SET NOCOUNT ON

            INSERT INTO LogData
                (ApplicationName, NodeNo,
			     Date, Time,
				 ThreadDeltaTime, ThreadName, ThreadID,
				 Source, TransactionID, Msg,
				 EnterEntry, ExitEntry, Warning, Error, Exception, StackTrace,
				 RecordVersion, LastUpdate, LastUpdatedBy)
            VALUES (
				@ApplicationName, @NodeNo,
				@Date, @Time,
				@ThreadDeltaTime, @ThreadName, @ThreadID,
				@Source, @TransactionID, @Msg,
				@EnterEntry, @ExitEntry, @Warning, @Error, @Exception, @StackTrace,
				1, GetDate(), @LastUpdatedBy
				)

    END'

EXEC(@GTSInsertLogDataSPSQL)

