--
--  -------------------------------------------------------------------
--
--                  ***  OnlineMenus  ***
--
SET @TableName = 'OnlineMenus'
SET @TableStructure = '
        OnlineMenuID   int            NOT NULL,
        MenuNo         int            NOT NULL,
        FKeyNo         int            NOT NULL,
        MenuFunction   int            NOT NULL,
        ItemLabel      nvarchar(8)            NULL,

        RecordVersion  int            NOT NULL,
        LastUpdate     datetime       NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
 * Add new PK column OnlineMenuID int NOT NULL
 */

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  OnlineMenus, OnlineMenuID, int, -1, 'NOT NULL'
IF ((@RunMode / 10) = 2) BEGIN   /* Post-Upgrade Mode */
    EXEC GTSPostUpgradeChangePK  @RunMode, @Error OUTPUT,  OnlineMenus, OnlineMenuID, PKOnlineMenusMenuID
    END

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  OnlineMenus, OnlineMenuID, PKOnlineMenusMenuID

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END



--
--  -------------------------------------------------------------------
--
--                  ***  Operations  ***
--
SET @TableName = 'Operations'
SET @TableStructure = '
        OperationUniqueID  int            NOT NULL,
        OperationID        int            NOT NULL,
        Description        nvarchar(50)       NULL,
        Facility           int                NULL,
        Points             int                NULL,
        Attraction         int                NULL,

        RecordVersion      int            NOT NULL,
        LastUpdate         datetime       NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
 *  add new PK columns OperationUniqueID int NOT NULL
    -- Description column has been changed from "Description varchar(50) NULL" to "char(50) NULL"
 */

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName,  OperationUniqueID,  int,   -1, 'NOT NULL'

EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  @TableName,  Description,        char,  50

EXEC GTSUpgradeAddAuditColumns  @RunMode, @Error OUTPUT, @TableName
IF ((@RunMode / 10) = 2) BEGIN   /* Post-Upgrade Mode */
    EXEC GTSPostUpgradeAuditColumns  @RunMode, @Error OUTPUT, @DropDependency,  @TableName

    EXEC GTSPostUpgradeChangePK  @RunMode, @Error OUTPUT, @TableName, OperationUniqueID, PKOperationsOperationUniqueID
    END

DECLARE @OldPKExists bit
EXEC @OldPKExists = GTSPKNameExists PKOperationsOperationID
if @OldPKExists = 1 BEGIN
    EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, PKOperationsOperationID, 0
    -- Need to manually remove the TableIndexDefs entry so the subsequent call to GTSUpgradeAddPK will work
    SET @SQL = 'delete from tableindexdefs where indexcolumns = ''OperationUniqueID'''
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  Points,  int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  Attraction,  int

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  Operations, OperationUniqueID, PKOperationsOperationUniqueID

EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, OperationID, PKOperationsOperationID, 'UNIQUE'

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/* Stop the script if an error has occurred */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

