        ContactID                int            NOT NULL,
        BillToContactID          int                NULL,
        ShipToContactID          int                NULL,
        GroupVisitID             int                NULL,
        OrderStatus              int            NOT NULL,
        OpenDate                 datetime       NOT NULL,
        NoteID                   int                NULL,
        Reference                nvarchar(40)           NULL,
        PO                       nvarchar(20)           NULL,
        UnissuedQty              int                NULL,
        UnissuedAmt              money              NULL,
        Balance                  money              NULL,
        BatchPrintDate           datetime           NULL,
        DeliveryMethod           int                NULL,
        DeliveryMethodID         int                NULL,
        DeliveryDetails          nvarchar(255)       NULL,
        SPConnectionID           int                NULL,
        TrackingNbr              nvarchar(30)           NULL,
        PickupDate               datetime           NULL,
        ExternalID               nvarchar(40)       NULL,
        UnformattedExternalID    nvarchar(40)       NULL,
