EXEC GTSAddPassColumnNameWithDefaultValues @RunMode, @Error OUTPUT

/*
    Checks whether or not we have any problematic data, and alters it if necassary
*/
SET @SQL = 'IF EXISTS(SELECT PassColumnName FROM PassEditFields WHERE PassColumnName = ''Birthday'' AND FieldNumber = 9) BEGIN
            UPDATE PassEditFields SET PassColumnName = ''DOB'' WHERE FieldNumber = 9
            END'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

SET @SQL = 'IF EXISTS(SELECT PassColumnName FROM PassEditFields WHERE PassColumnName = ''Title'' AND FieldNumber = 26) BEGIN
            UPDATE PassEditFields SET PassColumnName = ''NameTitleID'' WHERE FieldNumber = 26
            END'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

SET @SQL = 'IF EXISTS(SELECT PassColumnName FROM PassEditFields WHERE PassColumnName = ''Suffix'' AND FieldNumber = 27) BEGIN
            UPDATE PassEditFields SET PassColumnName = ''NameSuffixID'' WHERE FieldNumber = 27
            END'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  @TableName, FieldID, PKPassEditFieldsFieldID

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
    Defaults Sequence field to FieldNumber if necessary
*/
SET @SQL = 'UPDATE PassEditFields set Sequence = FieldNumber where Sequence is NULL'
EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

/* Expand State field length from 20 to 40 */
SET @SQL = 'UPDATE PassEditFields SET FieldLength = 40 where FieldNumber = 6 and FieldLength = 20'
EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

/* Set Phone default length to 30 from 16. */
SET @SQL = 'UPDATE PassEditFields SET FieldLength = 30 where FieldNumber = 8 and FieldLength = 16'
EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END


