-- 284836
IF (@Error = 0) AND ((@MultiSite = 2) OR (((@RunMode / 10) = 2) AND (dbo.GTSIsTrigger('trExportServicePassInsert') = 1))) BEGIN
    PRINT 'Adding trExportServicePassInsert Trigger to Passes'

    IF dbo.GTSIsTrigger('trExportServicePassInsert') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trExportServicePassInsert'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
    SET @SQL =
    'CREATE TRIGGER [dbo].[trExportServicePassInsert] ON [dbo].[Passes] FOR INSERT
        AS BEGIN

		    SET NOCOUNT ON

            DECLARE @PLU char(20)
            DECLARE InsertedIterator
				CURSOR FOR SELECT PassNo, Status, PLU, VisualID
				FROM INSERTED
				WHERE (Status <> 9) and (VisualID <> '''') --Unissued

            DECLARE @PassNo Int
			DECLARE @Status int
            DECLARE @SiteUniqueID Int
            DECLARE @VisualID varchar(40)

            OPEN InsertedIterator
            FETCH NEXT FROM InsertedIterator into @PassNo, @Status, @PLU, @VisualID
            WHILE (@@FETCH_STATUS = 0) BEGIN
				DECLARE SitesIterator CURSOR FOR
					SELECT
						DISTINCT SiteUniqueID
					FROM
						SiteItems
					WHERE
						SiteUniqueID IN (SELECT SiteUniqueID FROM SiteMessages WHERE MessageType = 7 AND SiteUniqueID = SiteItems.SiteUniqueID) AND
						((PLU <> '''' AND PLU = @PLU) OR
						ItemGroupID IN (SELECT ItemGroupID FROM ItemGroupDetails WHERE PLU = @PLU))

				OPEN SitesIterator
				FETCH NEXT FROM SitesIterator into @SiteUniqueID
				WHILE (@@FETCH_STATUS = 0) BEGIN
					INSERT INTO GxTriggers(TableName, ProcessCode, Action, NodeNo, ProcessStatus, CreateDate, Tries, Priority, LastError, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
					Values (''Passes'', 8, 1, NULL, 0, CURRENT_TIMESTAMP, NULL, NULL, '''', @PassNo, @SiteUniqueID, 1, CURRENT_TIMESTAMP, ''sa'')
					FETCH NEXT FROM SitesIterator into @SiteUniqueID
					END
				CLOSE SitesIterator
				DEALLOCATE SitesIterator

				FETCH NEXT FROM InsertedIterator into @PassNo, @Status, @PLU, @VisualID
				END

            CLOSE InsertedIterator
            DEALLOCATE InsertedIterator
            END '

    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END

IF (@Error = 0) AND ((@MultiSite = 2) OR (((@RunMode / 10) = 2) AND (dbo.GTSIsTrigger('trExportServicePassUpdate') = 1))) BEGIN
    PRINT 'Adding trExportServicePassUpdate Trigger to Tickets'

    IF dbo.GTSIsTrigger('trExportServicePassUpdate') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trExportServicePassUpdate'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
    SET @SQL =
    'CREATE TRIGGER [dbo].[trExportServicePassUpdate] ON [dbo].[Passes] FOR UPDATE
        AS BEGIN
            SET NOCOUNT ON

            DECLARE @PLU char(20)
			DECLARE @AdditionalInfo nvarchar(max)
            DECLARE InsertedIterator
				CURSOR FOR SELECT INSERTED.PassNo, INSERTED.PLU, INSERTED.VisualID, DELETED.VisualID
				FROM INSERTED
				INNER JOIN DELETED ON INSERTED.PassNo = DELETED.PassNo
				WHERE (INSERTED.Status <> 9) and (INSERTED.VisualID <> '''') -- Unissued

            DECLARE @PassNo Int
            DECLARE @SiteUniqueID Int
            DECLARE @VisualID varchar(40)
			DECLARE @OldVisualID varchar(40)

            OPEN InsertedIterator
            FETCH NEXT FROM InsertedIterator into @PassNo, @PLU, @VisualID, @OldVisualID
            WHILE (@@FETCH_STATUS = 0) BEGIN
				SET @AdditionalInfo = ''OriginalVisualID='' + @OldVisualID + ''|CurrentVisualID='' + @VisualID

				DECLARE SitesIterator CURSOR FOR
					SELECT
						DISTINCT SiteUniqueID
					FROM
						SiteItems
					WHERE
						SiteUniqueID IN (SELECT SiteUniqueID FROM SiteMessages WHERE MessageType = 7 AND SiteUniqueID = SiteItems.SiteUniqueID) AND
						((PLU <> '''' AND PLU = @PLU) OR
						ItemGroupID IN (SELECT ItemGroupID FROM ItemGroupDetails WHERE PLU = @PLU))

				OPEN SitesIterator
				FETCH NEXT FROM SitesIterator into @SiteUniqueID
				WHILE (@@FETCH_STATUS = 0) BEGIN
					INSERT INTO GxTriggers(TableName, ProcessCode, Action, NodeNo, ProcessStatus, CreateDate, Tries, Priority, LastError, RecordID, GalaxySiteID, AdditionalInformation, RecordVersion, LastUpdate, LastUpdatedBy)
					Values (''Passes'', 8, 3, NULL, 0, CURRENT_TIMESTAMP, NULL, NULL, '''', @PassNo, @SiteUniqueID, @AdditionalInfo, 1, CURRENT_TIMESTAMP, ''sa'')
					FETCH NEXT FROM SitesIterator into @SiteUniqueID
					END
				CLOSE SitesIterator
				DEALLOCATE SitesIterator

                FETCH NEXT FROM InsertedIterator into @PassNo, @PLU, @VisualID, @OldVisualID
                END

            CLOSE InsertedIterator
            DEALLOCATE InsertedIterator
            END '

    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END

/* Conversion to update new PurchaserContactID column based on old Purchaser column, ONLY if the PurchaserContactID column exists */
EXEC @HasPurchaserContactIDColumn = GTSColumnExists @TableName, PurchaserContactID
IF @HasPurchaserContactIDColumn = 1 BEGIN
    PRINT 'Running conversion to update new PurchaserContactID column based on old Purchaser column'
    SET @SQL = 'IF EXISTS(SELECT p1.PassNo FROM Passes p1 INNER JOIN Passes p2 ON p2.PassNo = p1.Purchaser WHERE p1.Purchaser > 0 AND p2.ContactID > 0 AND ((p1.PurchaserContactID = 0) OR (p1.PurchaserContactID is NULL))) BEGIN
        ALTER TABLE Passes DISABLE TRIGGER ALL

        DECLARE
            @ContactID int,
            @PassNo    int,
            @Purchaser int

        DECLARE PurchaserCursor INSENSITIVE CURSOR FOR
            SELECT PassNo, Purchaser
            FROM Passes
            WHERE (Purchaser > 0)
            AND ((PurchaserContactID = 0) OR (PurchaserContactID IS NULL))

        OPEN PurchaserCursor
        FETCH NEXT FROM PurchaserCursor INTO @PassNo, @Purchaser
        WHILE @@FETCH_STATUS = 0 BEGIN
            SELECT @ContactID = ContactID
            FROM Passes
            WHERE PassNo = @Purchaser

            IF @ContactID > 0 BEGIN
                UPDATE Passes
                SET PurchaserContactID = @ContactID
                WHERE PassNo = @PassNo
                END

            FETCH NEXT FROM PurchaserCursor INTO @PassNo, @Purchaser
            END
        CLOSE PurchaserCursor
        DEALLOCATE PurchaserCursor

        ALTER TABLE Passes ENABLE TRIGGER ALL
        END'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END

