EXEC GTSUpgradeDropColumn @RunMode, @Error OUTPUT, @TableName, TotalPaid, @DropObsoletedColumns

PRINT 'Adding trPaymentPlanLogInsert Trigger to PaymentPlanLog'

IF dbo.GTSIsTrigger('trPaymentPlanLogInsert') = 1 BEGIN
    SET @SQL = 'DROP TRIGGER dbo.trPaymentPlanLogInsert'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF @Error = 0 BEGIN
SET @SQL =
'CREATE TRIGGER [dbo].[trPaymentPlanLogInsert]
    ON [dbo].[PaymentPlanLog]
    AFTER INSERT
    AS BEGIN
        SET NOCOUNT ON

        DECLARE @PaymentPlanLogID Int
        DECLARE PaymentPlanLogIDs CURSOR FOR
            SELECT DISTINCT INSERTED.PaymentPlanLogID
            FROM INSERTED
                    INNER JOIN
                PaymentContractItems ON PaymentContractItems.PaymentContractID = INSERTED.AuxTableID
                    INNER JOIN
                GiftDetails ON GiftDetails.OrderLineID = PaymentContractItems.AuxID
                    INNER JOIN
                Gifts ON Gifts.GiftID = GiftDetails.GiftID
            WHERE INSERTED.LogType = 1                                -- PAYMENT_CONTRACT_LOG_TYPE
              AND PaymentContractItems.ContractItemType IN (0,1,2)    -- Pass(0), Ticket(1), or Item(2)
              AND GiftDetails.Status = 0                              -- VALID_GIFT
              AND Gifts.REGiftType = 8                                -- RE_GIFT_TYPE_PLEDGE

        OPEN PaymentPlanLogIDs
        FETCH NEXT FROM PaymentPlanLogIDs INTO @PaymentPlanLogID

        WHILE @@FETCH_STATUS = 0 BEGIN

            INSERT INTO GxTriggers
                (TableName,    RecordID,
                ProcessCode,   Action,        ProcessStatus,
                CreateDate,    Tries,         RecordVersion,
                LastUpdate,    LastUpdatedBy)
            VALUES
                (''PaymentPlanLog'', -- TableName
                @PaymentPlanLogID,  -- RecordID
                3,                  -- ProcessCode:   PC_REMERGE
                1,                  -- Action:        ACTION_INSERT
                0,                  -- ProcessStatus: STATUS_AVAILABLE
                CURRENT_TIMESTAMP,  -- CreateDate
                0,                  -- Tries
                1,                  -- RecordVersion
                CURRENT_TIMESTAMP,  -- LastUpdate
                ''PayPlanTr'')      -- LastUpdateBy

            FETCH NEXT FROM PaymentPlanLogIDs INTO @PaymentPlanLogID

            END

      CLOSE PaymentPlanLogIDs
      DEALLOCATE PaymentPlanLogIDs
      END '

EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
END

/*
 *  Stop the script if an error has occurred
*/
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END


