EXEC GTSUpgradeAddColumn @RunMode, @Error OUTPUT, @TableName, RenewalPaymentOffsetUnits, int, -1, 'NULL', 0

/*
 * RecurrencePatternID is being replaced by PaymentPlanRecurrencePatternID.
 * The CURSOR that moves the existing payment plan RecurrencePatterns to the
 * PaymentPlanRecurrencePattern table should only run once - at the time the PaymentPlanRecurrencePatternID is added.
 */
IF (@Error = 0) and ((@RunMode % 10) = 1) BEGIN
    DECLARE @PPRPIDExists bit,
      @PPSQL  varchar(5000)
    EXEC @PPRPIDExists = GTSColumnExists  @TableName, PaymentPlanRecurrencePatternID
    IF @PPRPIDExists = 0 BEGIN

      EXEC GTSUpgradeAddColumn @RunMode, @Error OUTPUT, @TableName, PaymentPlanRecurrencePatternID, int

      SET @PPSQL = 'SET NOCOUNT ON
      DECLARE
      @PaymentPlanID  Integer,
      @OldPlanRecurrencePatternID Integer,
      @UniqueID       Integer,
      @RecurrenceID   Integer,
      @Name           Varchar(50),
      @DayOfMonth		  Integer,
      @DayOfMonthMask	Integer,
      @DayOfWeekMask	Integer,
      @Instance		    Integer,
      @Interval		    Integer,
      @MonthOfYear	  Integer,
      @RecurrenceType	Integer,
      @StartDate		  Datetime,
      @EndDate		    Datetime,
      @EnableTime		  Bit,
      @StartTime		  Datetime,
      @EndTime		    datetime,
      @RecordVersion	Integer,
      @LastUpdate		  Datetime,
      @LastUpdatedBy	nvarchar(20)

    DECLARE PPRecurrencePatternsCursor CURSOR for
     SELECT  PP.PaymentPlanID,
      PP.RecurrencePatternID,
      RP.RecurrenceID,
      RP.Name,
      RP.DayOfMonth,
      RP.DayOfMonthMask,
      RP.DayOfWeekMask,
      RP.Instance,
      RP.Interval,
      RP.MonthOfYear,
      RP.RecurrenceType,
      RP.StartDate,
      RP.EndDate,
      RP.EnableTime,
      RP.StartTime,
      RP.EndTime,
      RP.RecordVersion,
      RP.LastUpdate,
      RP.LastUpdatedBy
     FROM RecurrencePatterns RP, PaymentPlans PP
     WHERE RP.RecurrencePatternID = PP.RecurrencePatternID

    Open PPRecurrencePatternsCursor
    FETCH NEXT From PPRecurrencePatternsCursor into
      @PaymentPlanID, @OldPlanRecurrencePatternID, @RecurrenceID, @Name, @DayOfMonth, @DayOfMonthMask, @DayOfWeekMask, @Instance,
      @Interval, @MonthOfYear, @RecurrenceType, @StartDate, @EndDate, @EnableTime, @StartTime, @EndTime, @RecordVersion, @LastUpdate, @LastUpdatedBy

    WHILE ( @@Fetch_Status = 0 ) BEGIN
      EXEC @UniqueID = GetNextGatewayCounter ''PaymentPlanRecurrencePatternID''

      /* Move the RecurrencePattern to the new table  */
      INSERT INTO PaymentPlanRecurrencePatterns
          (PaymentPlanRecurrencePatternID, RecurrenceID, Name, DayOfMonth, DayOfMonthMask, DayOfWeekMask, Instance, Interval, MonthOfYear,
          RecurrenceType, StartDate, EndDate, EnableTime, StartTime, EndTime, RecordVersion, LastUpdate, LastUpdatedBy)

        VALUES(@UniqueID, @RecurrenceID, @Name, @DayOfMonth, @DayOfMonthMask, @DayOfWeekMask, @Instance, @Interval, @MonthOfYear,
          @RecurrenceType, @StartDate, @EndDate, @EnableTime, @StartTime, @EndTime, @RecordVersion, @LastUpdate, @LastUpdatedBy )

      /* Update the RecurrencePatternID on the Payment Plan  */
      UPDATE PaymentPlans Set PaymentPlanRecurrencePatternID = @UniqueID where PaymentPlanID = @PaymentPlanID

      FETCH NEXT From PPRecurrencePatternsCursor into @PaymentPlanID, @OldPlanRecurrencePatternID, @RecurrenceID,@Name,@DayOfMonth,@DayOfMonthMask,@DayOfWeekMask,@Instance,
        @Interval,@MonthOfYear,@RecurrenceType,@StartDate,@EndDate,@EnableTime,@StartTime,@EndTime,@RecordVersion,@LastUpdate,@LastUpdatedBy

      END

  CLOSE PPRecurrencePatternsCursor
  DEALLOCATE PPRecurrencePatternsCursor'

  EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @PPSQL
  END
END

