PRINT 'Running conversion to split PkgInstanceDetails with a quantity > 1'
SET @SQL = 'SET NOCOUNT ON
    DECLARE
        @PkgInstanceDetailID int,
        @PkgInstanceID       int,
        @PackageDetailID     int,
        @VisualID            varchar(40),
        @PLU                 varchar(20),
        @TicketType          int,
        @IssuanceStatus      int,
        @Quantity            int,
        @Amount              float,
        @Tax                 float,
        @NodeNo              int,
        @TransNo             int,
        @TransDate           datetime,
        @JnlDetailID         bigint,
        @MediaVisualID       varchar(40),
        @PreviousVisualID    varchar(40),
        @Deferred            bit,
        @Status              int,
        @NewID               int

    DECLARE DetailCursor INSENSITIVE CURSOR FOR
    SELECT
        PkgInstanceDetailID, PkgInstanceID, PackageDetailID, VisualID, PLU, TicketType, IssuanceStatus,
        Quantity, Amount, Tax, NodeNo, TransNo, TransDate, JnlDetailID, MediaVisualID, PreviousVisualID,
        Deferred, Status
    FROM PkgInstanceDetails
    WHERE Quantity > 1
    ORDER BY PkgInstanceDetailID

    OPEN DetailCursor

    FETCH NEXT FROM DetailCursor INTO @PkgInstanceDetailID, @PkgInstanceID, @PackageDetailID, @VisualID, @PLU,
        @TicketType, @IssuanceStatus, @Quantity, @Amount, @Tax, @NodeNo, @TransNo, @TransDate, @JnlDetailID,
        @MediaVisualID, @PreviousVisualID, @Deferred, @Status

    WHILE @@FETCH_STATUS = 0 BEGIN

        WHILE @Quantity > 1 BEGIN
            EXEC @NewID = GetNextGatewayCounter ''PkgInstanceDetailID''

            INSERT INTO PkgInstanceDetails
                (
                PkgInstanceDetailID, PkgInstanceID, PackageDetailID, VisualID, PLU, TicketType, IssuanceStatus,
                Quantity, Amount, Tax, NodeNo, TransNo, TransDate, JnlDetailID, MediaVisualID,
                PreviousVisualID, Deferred, Status, RecordVersion, LastUpdate, LastUpdatedBy
                )
                VALUES
                (
                @NewID, @PkgInstanceID, @PackageDetailID, @VisualID, @PLU, @TicketType, @IssuanceStatus,
                1, @Amount, @Tax, @NodeNo, @TransNo, @TransDate, @JnlDetailID, @MediaVisualID,
                @PreviousVisualID, @Deferred, @Status, 1, GETDATE(), ''PkgSplit''
                )

            SET @Quantity = @Quantity - 1
            END

        UPDATE PkgInstanceDetails
        SET Quantity = 1, RecordVersion = RecordVersion + 1, LastUpdate = GETDATE(), LastUpdatedBy = ''PkgSplit''
        WHERE PkgInstanceDetailID = @PkgInstanceDetailID

        FETCH NEXT FROM DetailCursor INTO @PkgInstanceDetailID, @PkgInstanceID, @PackageDetailID, @VisualID, @PLU,
            @TicketType, @IssuanceStatus, @Quantity, @Amount, @Tax, @NodeNo, @TransNo, @TransDate, @JnlDetailID,
            @MediaVisualID, @PreviousVisualID, @Deferred, @Status
        END

    CLOSE DetailCursor
    DEALLOCATE DetailCursor'

EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

/* Stop the script if an error has occurred */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

