/*
    -- LastUpdatedBy column has been changed from "LastUpdatedBy varchar(10) NULL" to "char(10) NOT NULL"
 */

EXEC @LastUpdatedByAlreadyConverted = GTSLastUpdatedByAlreadyConverted @TableName
-- Only change LastUpdatedBy if it has not already been converted to a nullable nvarchar(20) or nvarchar(20)
IF (@LastUpdatedByAlreadyConverted = 0)     EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  Pictures, LastUpdatedBy,  char,  10,  'NOT NULL'
IF ((@RunMode / 10) = 2) BEGIN   /* Post-Upgrade Mode */
    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency,  Pictures,  PictureID    ,  int

    EXEC GTSPostUpgradeAuditColumns  @RunMode, @Error OUTPUT, @DropDependency,  Pictures

    EXEC GTSPostUpgradeChangePK  @RunMode, @Error OUTPUT,  Pictures, PictureID, PKPicturesPictureID

    EXEC @ColumnExists = GTSColumnExists  Pictures, ID
    IF (@ColumnExists = 1) BEGIN
        SET @SQL = 'ALTER TABLE Pictures DROP COLUMN ID'

        EXEC GTSUpgradeGatherTableIndexes  Pictures
        EXEC GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, Pictures, ID, @DropDependency

        IF (@DropObsoletedColumns = 1) BEGIN
            SET @Log = 'Dropping an obsoleted column "ID"...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END
        ELSE BEGIN
            SET @Log = '"ID" column is no longer used.  This column should be dropped either'             + CHAR(13) + '    ' +
                       'by manually running the provided script, or by setting @DropObsoletedColumns to 1 (true)' + CHAR(13) + '    ' +
                       'at the beginning of the script.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  20 /* Test post upgrade mode */, @Error OUTPUT, @SQL
            END
        END
    END

