--  -------------------------------------------------------------------
--
--                  ***  ProfilePrivs  ***
--
SET @TableName = 'ProfilePrivs'
SET @TableStructure = '
        ProfilePrivID    int            NOT NULL,
        UserProfileID    int                NULL,
        PrivNumber       int                NULL,
        PrivilegeText    nvarchar(100)       NULL,
        PersistenceState int                NULL,
		ProfilePrivGUID  uniqueidentifier NOT NULL DEFAULT newid(),

        RecordVersion  int            NOT NULL,
        LastUpdate     datetime       NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  PrivilegeText,  VarChar, 100
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  PersistenceState, int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  ProfilePrivGUID, uniqueidentifier, -1, 'NOT NULL', 'newid()'

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  ProfilePrivs, ProfilePrivID, PKProfilePrivsProfilePrivID

EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  ProfilePrivs, UserProfileID, IXProfilePrivsUserProfileID
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, 'PrivNumber,UserProfileID', IXProfilePrivsPrivNumProfileID

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

-- See if we need to convert the user privileges
IF @ConvertEventEditPrivileges = 1 BEGIN
    SET @SQL = 'DECLARE @UserProfileID int, @NextID int'
    SET @SQL = @SQL + ' DECLARE ConvertEventEditPrivileges_cursor CURSOR for'
    SET @SQL = @SQL + ' select UserProfileID from ProfilePrivs (NOLOCK) where ProfilePrivID in (select ProfilePrivID from ProfilePrivs where PrivNumber = 505)'
    SET @SQL = @SQL + ' OPEN ConvertEventEditPrivileges_cursor'
    SET @SQL = @SQL + ' FETCH NEXT from ConvertEventEditPrivileges_cursor into @UserProfileID'
    SET @SQL = @SQL + ' WHILE (@@FETCH_STATUS = 0) BEGIN'
--                          Add new "Add Events" privilege'
    SET @SQL = @SQL + ' 	IF NOT EXISTS(select * from ProfilePrivs where PrivNumber = 1144 and UserProfileID = @UserProfileID) BEGIN'
    SET @SQL = @SQL + ' 	    EXEC @NextID = dbo.GetNextGatewayCounter ''ProfilePrivID'''
    SET @SQL = @SQL + ' 	    INSERT into ProfilePrivs (ProfilePrivID, UserProfileID, PrivNumber, PrivilegeText, PersistenceState, RecordVersion, LastUpdate, LastUpdatedBy)'
    SET @SQL = @SQL + ' 	    VALUES (@NextID, @UserProfileID, 1144, ''Add Events'', 0, 1, GETDATE(), ''GD'')'
    SET @SQL = @SQL + ' 	    END'
--                          Add new "Edit Events" privilege'
    SET @SQL = @SQL + ' 	IF NOT EXISTS(select * from ProfilePrivs where PrivNumber = 1145 and UserProfileID = @UserProfileID) BEGIN'
    SET @SQL = @SQL + ' 	    EXEC @NextID = dbo.GetNextGatewayCounter ''ProfilePrivID'''
    SET @SQL = @SQL + ' 	    INSERT into ProfilePrivs (ProfilePrivID, UserProfileID, PrivNumber, PrivilegeText, PersistenceState, RecordVersion, LastUpdate, LastUpdatedBy)'
    SET @SQL = @SQL + ' 	    VALUES (@NextID, @UserProfileID, 1145, ''Edit Events'', 0, 1, GETDATE(), ''GD'')'
    SET @SQL = @SQL + ' 	    END'
--                          Add new "Delete Events" privilege'
    SET @SQL = @SQL + ' 	IF NOT EXISTS(select * from ProfilePrivs where PrivNumber = 1146 and UserProfileID = @UserProfileID) BEGIN'
    SET @SQL = @SQL + ' 	    EXEC @NextID = dbo.GetNextGatewayCounter ''ProfilePrivID'''
    SET @SQL = @SQL + ' 	    INSERT into ProfilePrivs (ProfilePrivID, UserProfileID, PrivNumber, PrivilegeText, PersistenceState, RecordVersion, LastUpdate, LastUpdatedBy)'
    SET @SQL = @SQL + ' 	    VALUES (@NextID, @UserProfileID, 1146, ''Delete Events'', 0, 1, GETDATE(), ''GD'')'
    SET @SQL = @SQL + ' 	    END'
    SET @SQL = @SQL + ' 	FETCH NEXT from ConvertEventEditPrivileges_cursor into @UserProfileID'
    SET @SQL = @SQL + ' 	END'
    SET @SQL = @SQL + ' CLOSE ConvertEventEditPrivileges_cursor'
    SET @SQL = @SQL + ' DEALLOCATE ConvertEventEditPrivileges_cursor'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END



