--
--              PROCEDURE GTS_SP_PurgeRowChanges
--      Purges records older than the specified number of days from the ROWCHANGES table.
--      Moved down here to ensure that the RowChangeUID column exists first.
--
DECLARE @PurgeRowChangesSPSQL nvarchar(MAX)
PRINT '    ' + 'Creating GTS_SP_PurgeRowChanges...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
       WHERE (o.name = 'GTS_SP_PurgeRowChanges') AND (o.type = 'P')
       AND   (o.uid = u.uid)
       AND   (u.name = 'dbo')) BEGIN
    SET @PurgeRowChangesSPSQL = 'DROP PROCEDURE dbo.GTS_SP_PurgeRowChanges'
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @PurgeRowChangesSPSQL
    END

SET @PurgeRowChangesSPSQL =
'CREATE PROCEDURE dbo.GTS_SP_PurgeRowChanges(@DateOrPublishCountFl varchar(15) = ''Date'',
                                            @RetentionPeriodInDays smallint = 90,
                                            @PublishesToKeep smallint = 2,
                                            @SetOutOfDateNodesForResync bit = 0,
                                            @Help bit = 0) AS BEGIN
    /***
    ================================================================================
    =help

    Name        : GTS_SP_PurgeRowChanges
    Description : Purges records older than the specified number of days from the ROWCHANGES table.

    Parameters  :

      @DateOrPublishCountFl - indicates if you want to purge based on publish count (i.e. keep the latest ''x'' publishes)
      or by date (i.e. purge publishes older than ''x'' date). Possible values are ''Date'' and ''PublishCount''.

      @RetentionPeriodInDays - when @DateOrPublishFL = ''Date'', data older than this many days will be purged from the table.

      @SetOutOfDateNodesForResync - if set to 1 (default is 0) this will set any node which has not connected
      in "@RetentionPeriodInDays" to re-download all data on its next connection.

      @PublishesToKeep - when specified, and @DateOrPublishCountFl = ''PublishCount'', indicates how many
      publishes should be retained.

    =endhelp
    ================================================================================
    ***/

    SET NOCOUNT ON;

    DECLARE @PurgeDate datetime, -- The oldest date of records to retain
            @IterationPurgeRowCount bigint, -- The number of rows deleted this iteration
            @TotalPurgeRowCount bigint, -- The total number of rows deleted so far
            @ToBePurgedRowCount bigint, -- The number of rows qualified to be purged.
            @RemainingRowCount bigint, -- The number of rows remaining to be purged.
            @MaxRowChangeUID bigint, -- The maximum PK value for rows to be purged.
            @MinRetainedPublishCount int; -- The minimum PublishCount to retain.

    DECLARE @ERROR_MESSAGE NVARCHAR(2048);
    DECLARE @ERROR_SEVERITY TINYINT;
    DECLARE @ERROR_NUMBER INT;

    SET @IterationPurgeRowCount = 0;
    SET @TotalPurgeRowCount = 0;
    SET @ToBePurgedRowCount = 0;
    SET @RemainingRowCount = 0;

    DECLARE @sql nvarchar(max),
            @MessageText nvarchar(max);

    -- Props to Adam Machanic and sp_whoisactive for this technique
    -- to get help text from within a stored procedure.
    -- http://sqlblog.com/blogs/adam_machanic/archive/2012/03/22/released-who-is-active-v11-11.aspx
    IF @Help = 1
    BEGIN

      SELECT @SQL = dest.text
        FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) dest
        WHERE r.session_id = @@SPID;
      --PRINT @SQL;
      -- Cut up the SQL text and get the help section
      SET @MessageText = SUBSTRING(@SQL,
                            CHARINDEX(''=help'',@SQL),
                            CHARINDEX(''=endhelp'',@SQL)-CHARINDEX(''=help'',@SQL)+8
                          );

      PRINT @MessageText;
      RETURN;

    END;

    BEGIN TRY

      IF @DateOrPublishCountFl = ''PublishCount''
        SELECT @MinRetainedPublishCount = PublishCount
          FROM (
                  SELECT MIN(PublishCount) AS PublishCount
                    FROM (
                            SELECT TOP(@PublishesToKeep) PublishCount
			      FROM (
			              SELECT DISTINCT rc.PublishCount
					FROM dbo.RowChanges rc
				   ) x1
                            ORDER BY PublishCount DESC
                         ) x
               ) x2;
      ELSE IF @DateOrPublishCountFl = ''Date''
        SET @PurgeDate = DATEADD(day,DATEDIFF(day,0,CURRENT_TIMESTAMP) - @RetentionPeriodInDays,0);
      ELSE
        RAISERROR(''Invalid value specified for @DateOrPublishCountFL.'',16,1);

      SELECT @ToBePurgedRowCount = COUNT_BIG(1),
             @MaxRowChangeUID = MAX(l.RowChangeUID)
        FROM dbo.ROWCHANGES l
       WHERE (l.LastUpdate < @PurgeDate AND @DateOrPublishCountFl = ''Date'')
             OR (l.PublishCount < @MinRetainedPublishCount AND @DateOrPublishCountFl = ''PublishCount'');

      RAISERROR(''Beginning purge operations.'',10,1) WITH NOWAIT;
      IF @ToBePurgedRowCount > 0
        RAISERROR(''There are %I64d rows qualified for purging.'',10,1,@ToBePurgedRowCount) WITH NOWAIT;
      ELSE
      BEGIN
        RAISERROR(''There are no rows qualified for purging.'',10,1) WITH NOWAIT;
        GOTO NodeDataUpdate;
      END;

      SET @RemainingRowCount = @ToBePurgedRowCount;

      -- Disable indexes
      SET @SQL = (
        SELECT
            ''ALTER INDEX ''
              + quotename(sidx.name)
              + '' ON ''
              + quotename(ssch.name)
              + ''.'' + quotename(sobj.name)
              + '' ''
              + ''DISABLE;'' + char(10)
          FROM
            sys.schemas ssch join sys.objects sobj
              on ssch.schema_id = sobj.schema_id
                 and ssch.name = ''dbo''
                 and sobj.name = ''ROWCHANGES''
            join sys.indexes sidx
              on sobj.object_id = sidx.object_id
                 and sidx.is_primary_key = 0 -- exclude primary keys
                 and sidx.is_unique = 0 -- exclude unique indexes
                 and sidx.index_id > 1 -- exclude clustered index and heap
                 and sidx.is_disabled = 0
        FOR XML path('''')
      );

      EXEC sp_executesql @sql;

      -- We use a nested TRY block here to be sure indexes are re-enabled afterwards even in the event of an error
      BEGIN TRY
        WHILE 1=1
        BEGIN
          DELETE TOP(1000000)
            FROM dbo.ROWCHANGES
           WHERE ROWCHANGES.RowChangeUID <= @MaxRowChangeUID
		 AND ROWCHANGES.PublishCount <> 0;

          SET @IterationPurgeRowCount = @@ROWCOUNT;
          SET @TotalPurgeRowCount = @TotalPurgeRowCount + @IterationPurgeRowCount;
          SET @RemainingRowCount = @RemainingRowCount - @IterationPurgeRowCount;

          RAISERROR(''%I64d rows purged in this iteration, %I64d rows deleted total. %I64d rows remaining.''
                    ,10
                    ,1
                    ,@IterationPurgeRowCount
                    ,@TotalPurgeRowCount
                    ,@RemainingRowCount) WITH NOWAIT;

          IF @IterationPurgeRowCount = 0 BREAK;

        END;
      END TRY
      BEGIN CATCH
        SET @ERROR_MESSAGE = CONVERT(varchar,ERROR_LINE()) + '': '' + ERROR_MESSAGE();
        SET @ERROR_NUMBER = ERROR_NUMBER();
        SET @ERROR_SEVERITY = ERROR_SEVERITY();
      END CATCH;

      -- Re-enable indexes
      SET @SQL = (
        SELECT
            ''ALTER INDEX ''
              + quotename(sidx.name)
              + '' ON ''
              + quotename(ssch.name)
              + ''.'' + quotename(sobj.name)
              + '' ''
              + ''REBUILD;'' + char(10)
          FROM
            sys.schemas ssch join sys.objects sobj
              on ssch.schema_id = sobj.schema_id
                 and ssch.name = ''dbo''
                 and sobj.name = ''ROWCHANGES''
            join sys.indexes sidx
              on sobj.object_id = sidx.object_id
                 and sidx.is_primary_key = 0 -- exclude primary keys
                 and sidx.is_unique = 0 -- exclude unique indexes
                 and sidx.index_id > 1 -- exclude clustered index and heap
                 and sidx.is_disabled = 1
        FOR XML path('''')
      );

      EXEC sp_executesql @sql;

      -- If an error occurred during purging, re-raise it.
      IF @ERROR_MESSAGE IS NOT NULL
        RAISERROR(@ERROR_MESSAGE,16,1);

      NodeDataUpdate:
      IF @SetOutOfDateNodesForResync = 1
      BEGIN
        UPDATE dbo.NodeDataStatus
           SET RefreshData = 1
         WHERE (LastDownload <= @PurgeDate AND @PurgeDate IS NOT NULL)
               OR (dbo.NodeDataStatus.ApplyCount < @MinRetainedPublishCount AND @PublishesToKeep IS NOT NULL);

        RAISERROR(''%i nodes set to resync data on next connection.'',10,1,@@ROWCOUNT);
      END;

    END TRY
    BEGIN CATCH

      SET @ERROR_MESSAGE = CONVERT(varchar,ERROR_LINE()) + '': '' + ERROR_MESSAGE();
      SET @ERROR_NUMBER = ERROR_NUMBER();
      SET @ERROR_SEVERITY = ERROR_SEVERITY();

      IF XACT_STATE() <> 0
        ROLLBACK;

      RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);

    END CATCH;
END'

IF ((@RunMode % 10) = 1) BEGIN
    EXEC(@PurgeRowChangesSPSQL)
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

