/* Defaults HasEventSaleLimits for events that have not ended yet */
SET @SQL = 'UPDATE RMEvents SET HasEventSaleLimits = (CASE WHEN Exists(Select * FROM EventSaleLimits WHERE EventID = RMEvents.EventID) THEN 1 ELSE 0 END) WHERE EndDateTime >= GETDATE() and HasEventSaleLimits is null'
EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

/* Check if RMEvents table is using Unicode */
DECLARE @RMEventsTableNotUnicode BIT = 0

IF NOT EXISTS(SELECT DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME = 'EventName' AND DATA_TYPE = 'NVARCHAR') BEGIN
	SET @RMEventsTableNotUnicode = 1
	END

