/*
If there are no defined seat types, add default configurations
*/
IF (@Error = 0) AND ((@RunMode % 10) = 1) BEGIN
    IF (NOT EXISTS (select SeatStatus from RSSeatDisplayStatuses where SeatStatus = 0)) AND (@Error = 0) BEGIN
        Set @SQL =  'Insert into RSSeatDisplayStatuses(SeatStatus,  DisplayName, Description, Color, RecordVersion, LastUpdate, LastUpdatedBy) '+
            '    VALUES(0, ''Available'',''Seat is available for selection'',65280, 1, GetDate(), ''Script'') '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF (NOT EXISTS (select SeatStatus from RSSeatDisplayStatuses where SeatStatus = 1)) AND (@Error = 0) BEGIN
        Set @SQL =  'Insert into RSSeatDisplayStatuses(SeatStatus,  DisplayName, Description, Color, RecordVersion, LastUpdate, LastUpdatedBy) '+
            '    VALUES(1, ''SessionReserved'',''Seat is selected in current transaction'',16777215, 1, GetDate(), ''Script'') '
          EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
