    IF (NOT EXISTS (select SeatStatus from RSSeatDisplayStatuses where SeatStatus = 2)) AND (@Error = 0) BEGIN
        Set @SQL =  'Insert into RSSeatDisplayStatuses(SeatStatus,  DisplayName, Description, Color, RecordVersion, LastUpdate, LastUpdatedBy) '+
            '    VALUES(2, ''LocallyReserved'',''Seat is selected in other transaction'',65535, 1, GetDate(), ''Script'') '
