--
--  -------------------------------------------------------------------
--
--                  ***  Start GTSAddSalesChannelOption Stored Procedure  ***
--

PRINT '    ' + 'Creating GTSAddSalesChannelOption...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSAddSalesChannelOption') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSAddSalesChannelOption

EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE dbo.GTSAddSalesChannelOption

(@SalesChannelID int,
@SalesChannelDetailID int,
@Name varchar(50),
@Value nvarchar(max),
@ResellerSalesChannelDetailID int,
@DataType int,
@Code int)

 AS BEGIN
	DECLARE
        @SQL          nvarchar(3000),
        @ParamType    nvarchar(1000)

    SET @SQL = N''IF NOT EXISTS  (Select * from SalesChannelOptions WHERE SalesChannelID=@xSalesChannelID and SalesChannelDetailID=@xSalesChannelDetailID and Code=@xCode) BEGIN

        INSERT INTO SalesChannelOptions (SalesChannelID, SalesChannelDetailID, Name, Value, ResellerSalesChannelDetailID, DataType, Code, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES(@xSalesChannelID, @xSalesChannelDetailID, @xName, @xValue, @xResellerSalesChannelDetailID, @xDataType, @xCode, 1, GetDate(), ''''Upgrade'''' )
        END''
    SET @ParamType = N''@xSalesChannelID int, @xSalesChannelDetailID int, @xName varchar(50), @xValue nvarchar(max), @xResellerSalesChannelDetailID int, @xDataType int, @xCode int''

    EXEC sp_executesql @SQL, @ParamType, @xSalesChannelID=@SalesChannelID, @xSalesChannelDetailID=@SalesChannelDetailID, @xName=@Name, @xValue=@Value, @xResellerSalesChannelDetailID=@ResellerSalesChannelDetailID, @xDataType=@DataType, @xCode=@Code
END'


--
--  -------------------------------------------------------------------
--
--                  ***  Start GTSUpdateNULLCodeSalesChannelOptions Stored Procedure  ***
--

IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpdateNULLCodeSalesChannelOptions') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSUpdateNULLCodeSalesChannelOptions

PRINT '    ' + 'Creating GTSUpdateNULLCodeSalesChannelOptions...'

EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE dbo.GTSUpdateNULLCodeSalesChannelOptions

AS BEGIN
	-- Updating SalesChannelOptions to populate any existing records with DataType and Code

	Update SalesChannelOptions
	SET

	Code = CASE Name
		WHEN ''GalaxyConnect'' THEN 1
		WHEN ''RequiresOfflineDelivery'' THEN 2
		WHEN ''GalaxyConnectAppConfigID'' THEN 3
		WHEN ''customerID'' THEN 4
		WHEN ''salesProgramID'' THEN 5
		WHEN ''ChannelStatus'' THEN 6
		WHEN ''Hide unavailable products for selected event'' THEN 7
		WHEN ''Sales channel default merchant ID'' THEN 8
		WHEN ''Show event capacity'' THEN 9
		WHEN ''Allow multiple event selection'' THEN 10
		ELSE NULL
	END,

	DataType = CASE Name
		WHEN ''GalaxyConnect'' THEN 3 -- Boolean
		WHEN ''RequiresOfflineDelivery'' THEN 3 -- Boolean
		WHEN ''GalaxyConnectAppConfigID'' THEN 1 -- Integer
		WHEN ''customerID'' THEN 1 -- Integer
		WHEN ''salesProgramID'' THEN 1 -- Integer
		WHEN ''ChannelStatus'' THEN 2 -- String
		WHEN ''Hide unavailable products for selected event'' THEN 3 -- Boolean
		WHEN ''Sales channel default merchant ID'' THEN 1 -- Integer
		WHEN ''Show event capacity'' THEN 3 -- Boolean
	    WHEN ''Allow multiple event selection'' THEN 3 -- Boolean
		ELSE NULL
	END,

	RecordVersion = RecordVersion + 1,
	LastUpdate = GetDate(),
	LastUpdatedBy = ''Upgrade''

	WHERE Code IS NULL

END'


--  -------------------------------------------------------------------
--
--                  ***  Start GTSAddNewSalesChannelOptionsFromExistingDetails Stored Procedure  ***
--
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSAddNewSalesChannelOptionsFromExistingDetails') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
    DROP PROCEDURE dbo.GTSAddNewSalesChannelOptionsFromExistingDetails

PRINT '    ' + 'Creating GTSAddNewSalesChannelOptionsFromExistingDetails...'
EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE dbo.GTSAddNewSalesChannelOptionsFromExistingDetails
 AS BEGIN
	DECLARE SalesChannelDetailCursor CURSOR FOR
        SELECT scd.SalesChannelDetailID, scd.SalesChannelID, ResellerSalesChannelDetailID
		FROM SalesChannelDetails scd
		LEFT JOIN ResellerSalesChannelDetails rscd on rscd.SalesChannelDetailID = scd.SalesChannelDetailID
		WHERE ShowCapacity=1

    DECLARE
        @SalesChannelDetailID int,
		@SalesChannelID int,
		@ResellerSalesChannelDetailID int

    OPEN SalesChannelDetailCursor
    FETCH FROM SalesChannelDetailCursor INTO @SalesChannelDetailID, @SalesChannelID, @ResellerSalesChannelDetailID
    WHILE (@@FETCH_STATUS = 0) BEGIN

		SET @ResellerSalesChannelDetailID = ISNULL(@ResellerSalesChannelDetailID, 0)

		EXEC GTSAddSalesChannelOption @SalesChannelID, @SalesChannelDetailID, ''Show event capacity'', ''True'', @ResellerSalesChannelDetailID, 3, 9
		EXEC GTSAddSalesChannelOption @SalesChannelID, @SalesChannelDetailID, ''Allow multiple event selection'', ''True'', @ResellerSalesChannelDetailID, 3, 10

        FETCH FROM SalesChannelDetailCursor INTO @SalesChannelDetailID, @SalesChannelID, @ResellerSalesChannelDetailID
        END

    CLOSE SalesChannelDetailCursor
    DEALLOCATE SalesChannelDetailCursor

END'

/*
The following 2 routines were needed for issue 273495 in version 7.8.0.5.
-- Update Code and DataType with their proper values.  Before version 7.8.0.5 these columns did not exist.
-- SalesChannelDetails.ShowCapacity was split into 2 new SalesChannelOptions.  Any SalesChannelDetails
   That had ShowCapacity = 1 will create the 2 new options in SalesChannelOptions.
*/
DECLARE
