DECLARE @CatetoryTypeColumnExists bit,
        @ResellerWebStoreColumnExists bit
EXEC @CatetoryTypeColumnExists = GTSColumnExists SalesChannelDetails, CategoryType
EXEC @ResellerWebStoreColumnExists = GTSColumnExists SalesChannelDetails, ResellerWebStore
IF @CatetoryTypeColumnExists = 0 AND @ResellerWebStoreColumnExists = 1 BEGIN
    EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  CategoryType, int
    SET @SQL = 'Update SalesChannelDetails set CategoryType = ResellerWebStore'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END


--DAD 091204 don't obsolete index, or can't be re-added
--EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT,  @TableName,  IXSalesChannelIDParentID, 1
