-- end Drop Columns never used

/*
   If AutoSelectEvents has never been populated, default it to true
   if we are using the pre-existing date only (1) calendar display mode.
*/
SET @SQL = 'UPDATE SalesChannelDetails SET AutoSelectEvents = 1 WHERE AutoSelectEvents IS NULL AND CalendarDisplay = 1'
EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL


/*
Starting with version 4.11 we now support mixing Pass Renewal and non-pass renewal
PLUs in the same Sales Category Group.  The script below finds all Sales Category Groups with
CategoryType of 2 (Pass Renewal) and first marks all Sales Categories as Pass Renewal under
each Sales Category Group and then changes the CategoryType on the Sales Category Group to 0 (Standard)
*/
IF (@Error = 0) and ((@RunMode % 10) = 1) BEGIN
    SET @SQL =
    'DECLARE SalesChannelDetailsCursor CURSOR FAST_FORWARD FOR '+
    '    SELECT SalesChannelDetailID FROM SalesChannelDetails '+
    '    WHERE DetailType = 0 AND CategoryType = 2  '+
    '    ORDER BY SalesChannelDetailID  '+

    'DECLARE @SalesChannelDetailID int '+

    'Open SalesChannelDetailsCursor  '+

    'FETCH NEXT FROM SalesChannelDetailsCursor INTO @SalesChannelDetailID  '+
    'WHILE (@@FETCH_STATUS = 0) BEGIN   '+
        -- First update all Sales Categories under this Sales Category Group
        -- and set the CategoryType to 2 (Pass Renewal)
    '    UPDATE SalesChannelDetails SET CategoryType = 2 '+
    '    WHERE DetailType = 1 AND ParentID = @SalesChannelDetailID '+

        -- Finally set the CategoryType to 0 (Standard) on the Sales Category Group
    '    UPDATE SalesChannelDetails SET CategoryType = 0 '+
    '    WHERE SalesChannelDetailID = @SalesChannelDetailID '+

    '    FETCH NEXT FROM SalesChannelDetailsCursor INTO @SalesChannelDetailID '+
    '    END  '+

    'CLOSE SalesChannelDetailsCursor '+
    'DEALLOCATE SalesChannelDetailsCursor '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF (@ERROR = 0) and (@WebStoreDB = 1) BEGIN
    SET @Log = ' '
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
    SET @Log = 'Web Store index Upgrade...'
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
    SET @Log = ' '
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 1

    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'DetailType,ExternalID',          IXSalesChannelDetailsTypeExternalID
    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, 'DetailType,ParentID,ExternalID', IXSalesChannelDetailsTypeParentIDExternalID
    END

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

