        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
    -- SettlementCode column has been changed from "SettlementCode varchar(31) NOT NULL" to "char(31) NOT NULL"
    -- SortCode column has been changed from "SortCode varchar(16) NOT NULL" to "char(16) NOT NULL"
    -- Sequence column has been changed from "Sequence varchar(4) NOT NULL" to "char(4) NOT NULL"
    -- LastUpdatedBy column has been changed from "LastUpdatedBy varchar(10) NOT NULL" to "char(10) NOT NULL"
    -- OrigSaleDate column has been changed from "OrigSaleDate datetime NOT NULL" to "datetime NULL"
 */

EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  Settlements,  SettlementCode,  char    ,  31,  'NOT NULL'
EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  Settlements,  SortCode      ,  char    ,  16,  'NOT NULL'
EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  Settlements,  Sequence      ,  char    ,   4,  'NOT NULL'
EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  Settlements,  OrigSaleDate  ,  DateTime
EXEC @LastUpdatedByAlreadyConverted = GTSLastUpdatedByAlreadyConverted @TableName
-- Only change LastUpdatedBy if it has not already been converted to a nullable nvarchar(20) or nvarchar(20)
IF (@LastUpdatedByAlreadyConverted = 0)     EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  Settlements,  LastUpdatedBy ,  char    ,  10,  'NOT NULL'

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  Settlements, SettlementID, PKSettlementsSettlementID

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

