        Name           nvarchar(40)       NULL,
        TaxRate        float          NOT NULL,
        FloorLimit     float              NULL,
        TaxCap         float          NOT NULL,
        Method         nchar(1)           NULL,
        TaxOnTax       bit                NULL,
        TaxGUID        uniqueidentifier NOT NULL DEFAULT newid(),
        EffectiveDate  datetime           NULL,

        RecordVersion  int            NOT NULL,
        LastUpdate     datetime       NOT NULL,
        LastUpdatedBy  nvarchar(20)       NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
    -- Adding a new NOT NULL column TaxRate float NOT NULL
    -- Adding a new nullable column Name char(40) NULL
    -- Adding a new NOT NULL column TaxCap float NOT NULL
    -- Adding a new nullable column Method char(1) NULL

    -- LastUpdatedBy column has been changed from "LastUpdatedBy varchar(10) NOT NULL" to "char(10) NOT NULL"
  034105  Add TaxOnTax
  038867  Add FloorLimit
 */

-- begin 023344
DECLARE @TaxUniqueIDExists bit
EXEC @TaxUniqueIDExists = GTSColumnExists @TableName, TaxUniqueID
IF @TaxUniqueIDExists = 0 BEGIN
    -- DROP OLD PRIMARY KEY INDEX
    EXEC GTSUpgradeDropIndexByColumn @RunMode, @Error OUTPUT, @TableName, TaxID, 1 --obsolete it
    -- Change Primary Key from TaxID to TaxUniqueID, and Add TaxID
    EXEC GTSUpgradeRenameColumn @RunMode, @Error OUTPUT,  @TableName,  TaxID, TaxUniqueID
    EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  TaxID,  int, -1, 'NOT NULL'
    -- Set initial value for TaxID
    SET @SQL = 'UPDATE TAXES set TAXID = TaxUniqueID where TAXID IS NULL'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END
-- end of 023344 change

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Taxes,  Name   ,    char ,  40
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Taxes,  TaxRate,    float,  -1,  'NOT NULL'
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Taxes,  FloorLimit, float
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Taxes,  TaxCap ,    float,  -1,  'NOT NULL'
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Taxes,  Method ,    char ,   1
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  Taxes,  TaxOnTax,   bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName, TaxGUID, uniqueidentifier, -1, 'NOT NULL', 'newid()'
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName, EffectiveDate, datetime

EXEC @LastUpdatedByAlreadyConverted = GTSLastUpdatedByAlreadyConverted @TableName
-- Only change LastUpdatedBy if it has not already been converted to a nullable nvarchar(20) or nvarchar(20)
IF (@LastUpdatedByAlreadyConverted = 0) EXEC GTSUpgradeChangeColumn  @RunMode, @Error OUTPUT, @DropDependency,  Taxes, LastUpdatedBy, char, 10, 'NOT NULL'

IF ((@RunMode / 10) = 2) BEGIN   /* Post Upgrade Mode */
    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency,  Taxes,  TaxRate,  float
    EXEC GTSPostUpgradeChangeToNotNULL  @RunMode, @Error OUTPUT, @DropDependency,  Taxes,  TaxCap ,  float

    EXEC @ColumnExists = GTSColumnExists  Taxes, Description
    IF (@ColumnExists = 1) BEGIN
        SET @SQL = 'ALTER TABLE Taxes DROP COLUMN Description'

        EXEC GTSUpgradeGatherTableIndexes  Taxes
        EXEC GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, Taxes, Description, @DropDependency

        IF (@DropObsoletedColumns = 1) BEGIN
            SET @Log = 'Dropping an obsoleted column "Description"...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END
        ELSE BEGIN
            SET @Log = '"Description" column is no longer used.  This column should be dropped either'             + CHAR(13) + '    ' +
                       'by manually running the provided script, or by setting @DropObsoletedColumns to 1 (true)' + CHAR(13) + '    ' +
                       'at the beginning of the script.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  20 /* Test post upgrade mode */, @Error OUTPUT, @SQL
            END
        END

    EXEC @ColumnExists = GTSColumnExists  Taxes, Rate
    IF (@ColumnExists = 1) BEGIN
        SET @SQL = 'ALTER TABLE Taxes DROP COLUMN Rate'

        EXEC GTSUpgradeGatherTableIndexes  Taxes
        EXEC GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, Taxes, Rate, @DropDependency

        IF (@DropObsoletedColumns = 1) BEGIN
            SET @Log = 'Dropping an obsoleted column "Rate"...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END
        ELSE BEGIN
            SET @Log = '"Rate" column is no longer used.  This column should be dropped either'             + CHAR(13) + '    ' +
                       'by manually running the provided script, or by setting @DropObsoletedColumns to 1 (true)' + CHAR(13) + '    ' +
                       'at the beginning of the script.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  20 /* Test post upgrade mode */, @Error OUTPUT, @SQL
            END
        END

    EXEC @ColumnExists = GTSColumnExists  Taxes, Cap
    IF (@ColumnExists = 1) BEGIN
        SET @SQL = 'ALTER TABLE Taxes DROP COLUMN Cap'

        EXEC GTSUpgradeGatherTableIndexes  Taxes
        EXEC GTSUpgradeDropDependencies  @RunMode, @Error OUTPUT, Taxes, Cap, @DropDependency

        IF (@DropObsoletedColumns = 1) BEGIN
            SET @Log = 'Dropping an obsoleted column "Cap"...'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
            END
        ELSE BEGIN
            SET @Log = '"Cap" column is no longer used.  This column should be dropped either'             + CHAR(13) + '    ' +
                       'by manually running the provided script, or by setting @DropObsoletedColumns to 1 (true)' + CHAR(13) + '    ' +
                       'at the beginning of the script.'
            EXEC GTSAddUpgradeLog  @RunMode, @Log, 1
            EXEC GTSUpgradeExecSQL  20 /* Test post upgrade mode */, @Error OUTPUT, @SQL
            END
        END
    END

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT,  Taxes, TaxUniqueID, PKTaxesTaxUniqueID

IF @WebStoreDB = 0 BEGIN
    EXEC GTSUpgradeAddIndex @RunMode, @Error OUTPUT, @TableName, TaxGUID, IXTaxesTaxGUID, 'UNIQUE'
    END
ELSE BEGIN
    EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT,  @TableName,  IXTaxesTaxGUID
    END

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

