-- FOR TEST ONLY ADD NON-CLUSTERED INDEX ON TICKETLOGID
-- EXEC GTSUpgradeAddPK @RunMode, @Error OUTPUT, @TableName, TicketLogID, PKTicketLogID, 'NONCLUSTERED'

-- If clustered primary key index on TicketLogID does not exist, create it
DECLARE @FoundIndex Bit,
        @WasClustered Bit,
        @IndexName SysName
EXEC @FoundIndex = GTSIndexExistsByColumnDef @TableName, TicketLogID
IF (@FoundIndex = 1) BEGIN
    -- If the index is non-clustered, drop and obsolete it, and add clustered index
    EXEC @WasClustered = dbo.GTSHasClusteredPK @TableName

    IF @WasClustered = 0 BEGIN
        PRINT '    Non-clustered index on TicketLogID will be replaced by clustered primary key index'
        EXEC @IndexName = GTSGetPKName @TableName
        EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, @IndexName, 1 -- obsolete it

        -- remove index from TableIndexDefs
        SET @SQL = 'Delete from TableIndexDefs where TableName = ''TicketLog'' and IndexColumns = ''TicketLogID'' '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

        EXEC GTSUpgradeAddPK @RunMode, @Error OUTPUT, @TableName, TicketLogID, PKTicketLogTicketLogID

        END
    END
ELSE BEGIN
    -- if there is no index on TicketLog ID, add Primary Key clustered index
    EXEC GTSUpgradeAddPK @RunMode, @Error OUTPUT, @TableName, TicketLogID, PKTicketLogTicketLogID
    END

