--
--              PROCEDURE GTSGetGuestPhotos
--  Stored procedure to retrieve tickets and their associated pictures for a
--  scanned ticket as well as the other tickets sold in that transaction.
--  Created here to ensure that Tickets.PictureID exists before being added.
--

PRINT '    ' + 'Creating GTSGetGuestPhotos...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSGetGuestPhotos') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo')) BEGIN
    SET @SQL = 'DROP PROCEDURE dbo.GTSGetGuestPhotos'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF (@Error = 0) and (@RunMode IN (11,21)) BEGIN
    EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE dbo.GTSGetGuestPhotos
           @VisualID VarChar(255),
           @DisplayMode Integer

           AS BEGIN
             SET NOCOUNT ON

             DECLARE @GuestTickets TABLE(
               TicketID int,
               VisualID VarChar(40),
               Status int,
               RemainingValue int,
               PictureID int,
               GuestPhotoRequired bit,
               FirstName VarChar(30),
               LastName VarChar(30),
               PixelDepth int,
               ImageData image,
               ScannedTicket bit)

             -- Insert the ticket for the scanned VisualID
             INSERT INTO @GuestTickets
               SELECT
                   T.TicketID, T.VisualID, T.Status, T.RemainingValue, T.PictureID, T.GuestPhotoRequired,
                   C.FirstName, C.LastName, P.PixelDepth, P.ImageData,
                   1 AS ScannedTicket -- This is the scanned in ticket

                 FROM Tickets T (NOLOCK)
                 LEFT OUTER JOIN CustContacts C (NOLOCK)
                   ON (T.ContactID <> 0) AND (T.ContactID = C.CustContactID)
                 LEFT OUTER JOIN Pictures P (NOLOCK)
                   ON (T.PictureID <> 0) AND (T.PIctureID = P.PictureID)

             WHERE T.VisualID = @VisualID

             IF @DisplayMode = 1 BEGIN
                 -- Now find all tickets from original transaction
                 DECLARE @OriginalVisualID VarChar(255)

                 SELECT @OriginalVisualID = ST2.VisualID
                 FROM SuperTickets ST (NOLOCK)
                     JOIN SuperTickets ST2 (NOLOCK)
                       ON (ST.BaseID = ST2.BaseID)

                 WHERE ST.VisualID = @VisualID
                 AND ST2.TicketType = 0 -- Tickets
                 AND ST2.NextID <> 0 -- Not the most recent (cannot use current, all are marked current(?))
                 ORDER BY ST2.SuperTicketID DESC

                 -- If no Super Tickets, set to the passed in VisualID
                 IF (ISNULL(@OriginalVisualID, '''') = '''') SET @OriginalVisualID = @VisualID

                 INSERT INTO @GuestTickets
                 SELECT
                     T2.TicketID, T2.VisualID, T2.Status, T2.RemainingValue, T2.PictureID, T2.GuestPhotoRequired,
                     C.FirstName, C.LastName, P.PixelDepth, P.ImageData,
                     0 AS ScannedTicket

                 FROM Tickets T (NOLOCK)
                     INNER JOIN Tickets T2 (NOLOCK)
                       ON (T.TransNo = T2.TransNo) AND (T.NodeNo = T2.NodeNo)
                     LEFT OUTER JOIN CustContacts C (NOLOCK)
                       ON (T2.ContactID <> 0) AND (T2.ContactID = C.CustContactID)
                     LEFT OUTER JOIN Pictures P (NOLOCK)
                       ON (T2.PictureID <> 0) AND (T2.PIctureID = P.PictureID)

                 WHERE T.VisualID = @OriginalVisualID
                 AND T2.VisualID <> @OriginalVisualID
                 AND T2.GuestPhotoRequired = 1
                 AND T2.PictureID <> 0
                 END

             SELECT * FROM @GuestTickets
             RETURN
             END '
    END

IF (@Error = 0) AND (@MultiSite_MultiSiteModule = 1) BEGIN
    PRINT 'Adding trMultiSiteTicketInsert Trigger to Tickets'

    IF dbo.GTSIsTrigger('trMultiSiteTicketInsert') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trMultiSiteTicketInsert'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
        SET @SQL =
          'CREATE TRIGGER [dbo].[trMultiSiteTicketInsert] ON [dbo].[Tickets] FOR INSERT
          AS BEGIN
              SET NOCOUNT ON
              DECLARE @AccessCode Int
              DECLARE InsertedIterator CURSOR FOR SELECT TicketID, AccessCode, VisualID FROM INSERTED
              DECLARE @TicketID Int
              DECLARE @GalaxySiteID Int
              DECLARE @VisualID varchar(40)

              OPEN InsertedIterator
              FETCH NEXT FROM InsertedIterator into @TicketID, @AccessCode, @VisualID
              WHILE (@@FETCH_STATUS = 0) BEGIN
                  IF NOT EXISTS(SELECT VisualID FROM ExternalSiteRecords WHERE VisualID = @VisualID AND TableName = ''Tickets'') BEGIN
                      DECLARE MultiSitesIterator CURSOR FOR
                          SELECT DISTINCT GalaxySiteID FROM MultiSiteAccessCodeConfig
                                          WHERE AccessCode = @AccessCode AND GalaxySiteID NOT IN (SELECT ISNULL(CONVERT(Int, Value), 0) FROM ConfigurationOptions WHERE Code = 723)

                      OPEN MultiSitesIterator
                      FETCH NEXT FROM MultiSitesIterator into @GalaxySiteID
                      WHILE (@@FETCH_STATUS = 0) BEGIN
                          INSERT INTO GxTriggers(TableName, ProcessCode, Action, ProcessStatus, CreateDate, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
                          Values (''Tickets'', 7, 1, 0, CURRENT_TIMESTAMP, @TicketID, @GalaxySiteID, 1, CURRENT_TIMESTAMP, ''sa'')
                          FETCH NEXT FROM MultiSitesIterator into @GalaxySiteID
                          END
                      CLOSE MultiSitesIterator
                      DEALLOCATE MultiSitesIterator
                      END

                  FETCH NEXT FROM InsertedIterator into @TicketID, @AccessCode, @VisualID
                  END
              CLOSE InsertedIterator
              DEALLOCATE InsertedIterator
              END '
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END

    PRINT 'Adding trMultiSiteTicketUpdate to Tickets'

    IF dbo.GTSIsTrigger('trMultiSiteTicketUpdate') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trMultiSiteTicketUpdate'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
        SET @SQL =
          'CREATE TRIGGER [dbo].[trMultiSiteTicketUpdate] ON [dbo].[Tickets] FOR UPDATE
          AS BEGIN
              SET NOCOUNT ON

              DECLARE @AccessCode Int
              DECLARE InsertedIterator CURSOR FOR SELECT TicketID, AccessCode, VisualID FROM INSERTED
              DECLARE @TicketID Int
              DECLARE @GalaxySiteID Int
              DECLARE @VisualID varchar(40)

              OPEN InsertedIterator
              FETCH NEXT FROM InsertedIterator into @TicketID, @AccessCode, @VisualID
              WHILE (@@FETCH_STATUS = 0) BEGIN
                  IF NOT EXISTS(SELECT VisualID FROM ExternalSiteRecords WHERE VisualID = @VisualID AND TableName = ''Tickets'') BEGIN
                      DECLARE MultiSitesIterator CURSOR FOR
                          SELECT DISTINCT GalaxySiteID FROM MultiSiteAccessCodeConfig
                                  WHERE AccessCode = @AccessCode AND GalaxySiteID NOT IN (SELECT ISNULL(CONVERT(Int, Value), 0) FROM ConfigurationOptions WHERE Code = 723)

                      OPEN MultiSitesIterator
                          FETCH NEXT FROM MultiSitesIterator into @GalaxySiteID
                          WHILE (@@FETCH_STATUS = 0) BEGIN
                              INSERT INTO GxTriggers(TableName, ProcessCode, Action, ProcessStatus, CreateDate, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
                              Values (''Tickets'', 7, 3, 0, CURRENT_TIMESTAMP, @TicketID, @GalaxySiteID, 1, CURRENT_TIMESTAMP, ''sa'')
                              FETCH NEXT FROM MultiSitesIterator into @GalaxySiteID
                              END
                      CLOSE MultiSitesIterator
                          DEALLOCATE MultiSitesIterator
                          END

                  FETCH NEXT FROM InsertedIterator into @TicketID, @AccessCode, @VisualID
                  END
              CLOSE InsertedIterator
              DEALLOCATE InsertedIterator
              END '
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END

    END

IF (@Error = 0) AND ((@MultiSite_ExportServiceModule = 1) OR (((@RunMode / 10) = 2) AND (dbo.GTSIsTrigger('trExportServiceTicketInsert') = 1))) BEGIN
