IF (@Error = 0) AND (@MultiSite_MultiSiteModule = 1) BEGIN
    PRINT 'Adding trMultiSiteUsageInsert Trigger to Usage'

    IF dbo.GTSIsTrigger('trMultiSiteUsageInsert') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trMultiSiteUsageInsert'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
        SET @SQL =
        'CREATE TRIGGER [dbo].[trMultiSiteUsageInsert] ON [dbo].[Usage] FOR INSERT
        AS BEGIN
           SET NOCOUNT ON

           DECLARE @AccessCode Int
           DECLARE InsertedIterator CURSOR FOR SELECT UsageID, GalaxySiteID, AccessCode FROM INSERTED
           DECLARE @UsageID int
           DECLARE @CurrentGalaxySiteID int
           DECLARE @GalaxySiteID Int

           OPEN InsertedIterator
           FETCH NEXT FROM InsertedIterator into @UsageID, @CurrentGalaxySiteID, @AccessCode
           WHILE (@@FETCH_STATUS = 0) BEGIN
               IF IsNull(@CurrentGalaxySiteID, 0) = 0 BEGIN
                   DECLARE MultiSitesIterator CURSOR FOR
                       SELECT DISTINCT GalaxySiteID FROM MultiSiteAccessCodeConfig
                       WHERE AccessCode = @AccessCode AND GalaxySiteID NOT IN (SELECT ISNULL(CONVERT(Int, Value), 0) FROM ConfigurationOptions WHERE Code = 723)

                   OPEN MultiSitesIterator
                   FETCH NEXT FROM MultiSitesIterator into @GalaxySiteID
                   WHILE (@@FETCH_STATUS = 0) BEGIN
                       INSERT INTO GxTriggers(TableName, ProcessCode, Action, ProcessStatus, CreateDate, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
                       Values (''Usage'', 7, 1, 0, CURRENT_TIMESTAMP, @UsageID, @GalaxySiteID, 1, CURRENT_TIMESTAMP, ''sa'')
                       FETCH NEXT FROM MultiSitesIterator into @GalaxySiteID
                       END
                   CLOSE MultiSitesIterator
                   DEALLOCATE MultiSitesIterator
                   END
               FETCH NEXT FROM InsertedIterator INTO @UsageID, @CurrentGalaxySiteID, @AccessCode
               END
           CLOSE InsertedIterator
           DEALLOCATE InsertedIterator
           END '
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END

IF (@Error = 0) AND (@MultiSite_ExportServiceModule = 1) BEGIN
    PRINT 'Adding trExportServiceUsageInsert Trigger to Usage'

    IF dbo.GTSIsTrigger('trExportServiceUsageInsert') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trExportServiceUsageInsert'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
        SET @SQL =
        'CREATE TRIGGER [dbo].[trExportServiceUsageInsert] ON [dbo].[Usage] FOR INSERT
        AS BEGIN
            SET NOCOUNT ON

            DECLARE @VisualID char(40)
            DECLARE InsertedIterator CURSOR FOR SELECT UsageID, VisualID, AccessCode FROM INSERTED WHERE RTRIM(VisualID) <> '''' AND Code IN (0, 11) AND Status IN (0, 6, 23, 46)
            DECLARE @UsageID bigint
            DECLARE @AccessCode int
                           DECLARE @SiteUniqueID int

            OPEN InsertedIterator
            FETCH NEXT FROM InsertedIterator into @UsageID, @VisualID, @AccessCode
            WHILE (@@FETCH_STATUS = 0) BEGIN
                DECLARE SitesIterator CURSOR FOR
                SELECT DISTINCT SiteUniqueID FROM SiteItems
		            INNER JOIN AccessCodes ac on ac.AccessCode = @AccessCode
		        WHERE
                    SiteUniqueID IN (SELECT SiteUniqueID FROM SiteMessages WHERE MessageType = 2 AND SiteUniqueID = SiteItems.SiteUniqueID) AND
                                    ((PLU <> '''' AND PLU IN (SELECT PLU FROM Tickets WHERE VisualID = @VisualID)) OR
                                    (PLU <> '''' AND PLU IN (SELECT PLU FROM Passes WHERE VisualID = @VisualID)) OR
                                    ItemGroupID IN (SELECT ItemGroupID FROM ItemGroupDetails, Tickets WHERE ItemGroupDetails.PLU = Tickets.PLU AND Tickets.VisualID = @VisualID) OR
                                    ItemGroupID IN (SELECT ItemGroupID FROM ItemGroupDetails, Passes WHERE ItemGroupDetails.PLU = Passes.PLU AND Passes.VisualID = @VisualID) OR
                                    (ISNULL(@AccessCode, '''') <> '''' AND ac.Dynamic = 1 AND PLU IN (SELECT PLU FROM Items (NOLOCK) WHERE AccessCode = @AccessCode AND Kind IN (1, 6)))) -- Support REGULAR and GROUP item kinds.

                OPEN SitesIterator
                    FETCH NEXT FROM SitesIterator into @SiteUniqueID
                    WHILE (@@FETCH_STATUS = 0) BEGIN
                        INSERT INTO GxTriggers(TableName, ProcessCode, Action, NodeNo, ProcessStatus, CreateDate, Tries, Priority, LastError, RecordID, GalaxySiteID, RecordVersion, LastUpdate, LastUpdatedBy)
                            Values (''Usage'', 8, 1, NULL, 0, CURRENT_TIMESTAMP, NULL, NULL, '''', @UsageID, @SiteUniqueID, 1, CURRENT_TIMESTAMP, ''sa'')
                        FETCH NEXT FROM SitesIterator into @SiteUniqueID
                        END
                    CLOSE SitesIterator
                    DEALLOCATE SitesIterator
               FETCH NEXT FROM InsertedIterator into @UsageID, @VisualID, @AccessCode
               END
           CLOSE InsertedIterator
           DEALLOCATE InsertedIterator
           END '

        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END

IF @Error = 0 and @CreateTriggerForInvoiceByUseTimeProcess = 1 BEGIN
    PRINT 'Adding trPendingUsageInsertForInvoiceByUseTime Trigger to Usage'

    IF dbo.GTSIsTrigger('trPendingUsageInsertForInvoiceByUseTime') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trPendingUsageInsertForInvoiceByUseTime'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
        SET @SQL =
        'CREATE TRIGGER dbo.trPendingUsageInsertForInvoiceByUseTime ON Usage FOR INSERT
        AS BEGIN
            INSERT INTO PendingUsage(UseTime, VisualID, AccessCode, IDNo, Code, ACP, Status, Qty, UseNo, Operator, EntryMethod, SerialNo, Override, UsageCondition, OriginalStatus, BankNo, BiometricStatus,
                                     OperationID, RecordVersion, LastUpdate, LastUpdatedBy, ProcessCode, ProcessStatus, ScannedVisualID, AttractionID, FacilityID, OriginalUsageID, EntitlementCharged, BankCharged)
            SELECT UseTime, VisualID, AccessCode, IDNo, Code, ACP, Status, Qty, UseNo, Operator, EntryMethod, SerialNo, Override, UsageCondition, OriginalStatus, BankNo, BiometricStatus,
                               OperationID, RecordVersion, LastUpdate, LastUpdatedBy, 2, 0, ScannedVisualID, AttractionID, FacilityID, OriginalUsageID, EntitlementCharged, BankCharged FROM Inserted
            END '

        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END
    END

if @Error = 0 AND @CreatePrimaryKeyOnUsageTable = 1 BEGIN
		DECLARE @UsageID BIGINT
		DECLARE cur CURSOR LOCAL for
			SELECT @UsageID FROM Usage WHERE UsageID IS NULL

		OPEN cur

		FETCH NEXT FROM cur INTO @UsageID

		WHILE @@FETCH_STATUS = 0 BEGIN
				EXEC @UsageID = GetNextGatewayCounter 'UsageID'
				UPDATE Usage SET UsageID = @UsageID WHERE CURRENT of Cur

			FETCH NEXT FROM cur INTO @UsageID
		END;

		CLOSE cur
		DEALLOCATE cur

        -- Drop indices which depend on UsageID so we can alter the UsageID column.
		-- Using real SQL for dropping first one, because GTSUpgradeDropIndexByName doesn't seem to work on this column. (Same for adding it below....)
		SET @SQL = 'DROP INDEX IXOriginalUsageIDUsageID on Usage'
		EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        EXEC GTSDropTablePK @RunMode, @ERROR OUTPUT, @TableName
		EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT, @TableName, IXUsageID

		-- Alter the UsageID Column to be NOT NULL
		SET @SQL = 'ALTER TABLE Usage ALTER COLUMN UsageID BIGINT NOT NULL'
		EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL

		-- Add the Indices back in, including the new Primary Key.  Had to "hard code" the addition of IXOriginalUsageIDUsageID, as noted above
		SET @SQL = 'CREATE INDEX IXOriginalUsageIDUsageID on Usage (OriginalUsageID,UsageID)'
		EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
		EXEC GTSUpgradeAddPK @RUNMODE, @ERROR OUTPUT, @TableName, 'UsageID', PKUsageID

		END

/* Stop the script if an error has occurred */
IF (@Error <> 0) BEGIN
	EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
	RETURN
	END

