        PasswordExpirationDays   int              NULL,
        PersistenceState         int              NULL,
        Publish                  bit              NULL,
        ExternalGroup            nvarchar(255)    NULL,
		UserProfileGUID          uniqueidentifier NOT NULL DEFAULT newid(),

        RecordVersion  int            NOT NULL,
        LastUpdate     datetime       NOT NULL,
        LastUpdatedBy     nvarchar(20)    NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

/*
  038183  Add PasswordExpirationDays
*/

EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  PasswordExpirationDays,  int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  PersistenceState, int
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  Publish, bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  ExternalGroup,    nvarchar, 255
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT,  @TableName,  UserProfileGUID, uniqueidentifier, -1, 'NOT NULL', 'newid()'

EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT, UserProfiles, UserProfileID, PKUserProfilesUserProfileID

EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  UserProfiles, Name, IXUserProfilesName, 'UNIQUE'
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  UserProfiles, ExternalGroup, IXExternalGroup

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/* Update the UserProfiles.Publish flag for any Profile with the Web Admin privilege or any Reseller Privilege  */
Declare @PublishColumnExists bit
EXEC @PublishColumnExists = GTSColumnExists @TableName, Publish
IF @WebStoreDB = 0 and @Transportation = 0 and @PublishColumnExists = 1 BEGIN
    SET @SQL = 'Update UserProfiles set Publish = 1 from UserProfiles up, ProfilePrivs pv where up.UserProfileID = pv.UserProfileID AND ((pv.PrivNumber = 971) or (pv.PrivNumber = 1032) or (pv.PrivNumber between 1006 and 1019) or (pv.PrivNumber between 1242 and 1256) or (pv.PrivNumber between 1185 and 1186))'
    PRINT '  Update the UserProfile.Publish flag for any profiles with the Web Admin privilege or any Reseller Privileges'
    PRINT '    ' + @SQL
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

/* Update GxUsers here because we need to ensure that the UserProfiles table has been created already */
/* Update the GxUsers.Publish flag for any users created in Galaxy (not on webstore) with the Web Admin privilege or any Reseller Priv  */
EXEC @PublishColumnExists = GTSColumnExists GXUsers, Publish
IF @WebStoreDB = 0 and @Transportation = 0 and @PublishColumnExists = 1 BEGIN
    SET @SQL = 'update GXUsers set Publish = 1 from UserProfiles up, ProfilePrivs pv WHERE GxUsers.PersistenceState <> 2
                and ClassID = up.Name AND up.UserProfileID = pv.UserProfileID AND ((pv.PrivNumber = 971) or (pv.PrivNumber = 1032) or (pv.PrivNumber between 1006 and 1019) or (pv.PrivNumber between 1242 and 1256) or (pv.PrivNumber between 1185 and 1186))'
    PRINT '  Update the GXUsers.Publish flag for any users with the Web Admin privilege or any Reseller Privileges'
    PRINT '    ' + @SQL
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

