    EXEC GTSUpgradeWSHtml @RunMode, @Error OUTPUT
    END

/* in case user is not going to run post upgrade right away let the columns be Null */
IF (@OwnerTypeColumnExists = 1) and (@OwnerIDColumnExists = 1) /* Upgrade */ BEGIN
    /*drop index and recreate as non-unique */
    EXEC GTSUpgradeDropIndexByName @RunMode, @Error OUTPUT,  @TableName,  IXWSHTMLOwerTypeIDKind, 1 /* make it obsolete */
    SET @Log = 'Create Non-Unique Index on WSHTML.OwnerType, WSHTML.OwnerID,Kind '
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
    SET @SQL = 'CREATE INDEX IXWSHTMLOwerTypeIDKind ON WSHTML(OwnerType, OwnerID, Kind)'
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL

    SET @Log = 'Changing the WSHTML.OwnerType column to allow NULL'
    EXEC GTSAddUpgradeLog  @RunMode, @Log, 2
    SET @SQL = 'ALTER TABLE ' + @TableName + ' ALTER COLUMN OwnerType int NULL'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

		SET @Log = 'Changing the WSHTML.OwnerID column to allow NULL'
