    SET @SQL = 'ALTER TABLE ' + @TableName + ' ALTER COLUMN OwnerID int NULL'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

    END

IF (@RunMode / 10) = 2 /* Post upgrade */ BEGIN
    EXEC GTSUpgradeDropIndexByColumn @RunMode, @Error OUTPUT, @TableName, 'OwnerType,OwnerID,Kind'
    EXEC GTSUpgradeDropColumn @RunMode, @Error OUTPUT, @TableName, OwnerType, @DropObsoletedColumns
    EXEC GTSUpgradeDropColumn @RunMode, @Error OUTPUT, @TableName, OwnerID, @DropObsoletedColumns
    END
