--                ADDITIONAL TASKS RE: LOCALIZATION
--  These happen here after the required tables and fields have been created.
--  1)  Drop obsolete Trigger: WSLocalizationGroup Insert Trigger
--
--  2)  Create default Localization Groups
--
--  3)  Create Localization Group Modules based on existing Localization Group data
--      - GTSUpgradeWSLocalizationGroups - to populate WSLocalizationGroupModules table and WSLocalization.Module column'
--
--  4)  GTSUpdateExistingGroupLocalizations - updates localization strings for various modules
--
--  5)  Create Trigger GTSCreateWSLocalizationGroupDeleteTrigger
--
--  6)  Run the GTSConsolidateResponsiveLocalization stored procedure
--


-- TASK 1:  REMOVE OBSOLETE TRIGGER
PRINT '    ' + 'Dropping obsolete trigger on WSLocalizationGroups Insert ...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSCreateWSLocalizationGroupInsertTrigger') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo')) BEGIN
    SET @SQL = 'DROP PROCEDURE dbo.GTSCreateWSLocalizationGroupInsertTrigger'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

IF dbo.GTSIsTrigger('trWSLocalizationGroupsInsertBuildWSLocalization') = 1 BEGIN
    SET @SQL = 'DROP TRIGGER dbo.trWSLocalizationGroupsInsertBuildWSLocalization'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END


/* TASK 2: CREATE DEFAULT LOCALIZATION GROUPS
Populate default localization Group with stringtype 0 for all merchants.
(StringType is now called Module and 0 = webstore module)
This is one-time update of existing merchants on the first upgrade.
Because user could previously define a merchant without to have Localization data.
*/

IF (@Error = 0) BEGIN
    SET @Log = 'Adding default WSLocalization values for all defined Merchants that have no defined WSLocalization yet.'
    EXEC GTSAddUpgradeLog @RunMode, @Log, 1

    -- Note: MerchantID is added to the WSLocalizationGroupID to ensure unique ID,
    -- because originally the WSLocalizationGroupID was set to MerchantID

    SELECT @SQL = '
	DECLARE Merchant_Cursor CURSOR Fast_Forward
		FOR SELECT MerchantID, Code FROM dbo.Merchants WHERE WSLocalizationGroupID IS NULL

	DECLARE @MerchantID int,
	        @Code varchar(30),
	        @WSLocalizationGroupID int

	OPEN Merchant_Cursor

	FETCH NEXT FROM Merchant_Cursor INTO @MerchantID, @Code
	WHILE (@@FETCH_STATUS = 0) BEGIN

		EXEC @WSLocalizationGroupID = dbo.GetNextGatewayCounter ''WSLocalizationGroupID''
        SET @WSLocalizationGroupID = @WSLocalizationGroupID + @MerchantID

		UPDATE dbo.Merchants SET WSLocalizationGroupID = @WSLocalizationGroupID
		WHERE MerchantID = @MerchantID

        INSERT INTO WSLocalizationGroups (WSLocalizationGroupID, Name, StringType, RecordVersion, LastUpdate, LastUpdatedBy)
		VALUES (@WSLocalizationGroupID, @Code, 0, 1, GetDate(), ''Upgrade'')

		FETCH NEXT FROM Merchant_Cursor INTO @MerchantID, @Code
	END

	CLOSE Merchant_Cursor
	DEALLOCATE Merchant_Cursor

    UPDATE dbo.GatewayCounters SET
        CountValue = IsNull(b.MaxID, 0)
        FROM (SELECT Max(WSLocalizationGroupID) MaxID FROM dbo.WSLocalizationGroups) b
        WHERE Name = ''WSLocalizationGroupID''
    '
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END

-- THIS SECTION REPLACED BY THE ABOVE - DAD 05/01/09
