/* TASK 2.5: If Merchants and WSLocalizationGroups already exist when WSLocalizatonGroups.StringType is added
 * the above procedure will not initialize the StringType, but it cannot be left null
 * Initialize the StringType to Default {0= webstore} so that WSLocalizationGroupModules
 * and WSLocalization can be populated
 */
IF (@Error = 0) BEGIN
    SET @SQL = 'UPDATE WSLocalizationGroups set StringType = 0 WHERE StringType IS NULL'
    EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
    END


/*  TASK 3 -  CREATE LOCALIZATION GROUP MODULES and initialize new WSLocalization.Module column
 *  Create stored procedure to populate WSLocalizationGroupModules
 *  and update WSLocalization for Module value  (one time upgrade)
 *  Note: Originally, a LocalizationGroup could only have one 'stringType' or 'module'
 */
  IF (@Error = 0) and ((@RunMode % 10) = 1) BEGIN
    PRINT '    ' + 'Creating GTSUpgradeWSLocalizationGroups to populate WSLocalizationGroupModules table and WSLocalization.Module column'

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSUpgradeWSLocalizationGroups') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTSUpgradeWSLocalizationGroups'
        EXEC(@SQL)
        END

    SET @SQL =
    'CREATE PROCEDURE dbo.GTSUpgradeWSLocalizationGroups AS BEGIN

    -- SET NOCOUNT ON to prevent extra result sets from interfering with SELECT statements
    SET NOCOUNT ON

    DECLARE Groups_Cursor CURSOR Fast_Forward FOR
        SELECT WSLocalizationGroupID, StringType FROM WSLocalizationGroups

    DECLARE @ID int,
            @GroupID int,
            @StringType int,
            @ModuleCount int

    OPEN Groups_Cursor

    FETCH FROM Groups_Cursor INTO @GroupID, @StringType
    WHILE (@@FETCH_STATUS = 0) BEGIN

        SELECT @ModuleCount = Count(*) FROM WSLocalizationGroupModules WHERE WSLocalizationGroupID = @GroupID

        IF (@ModuleCount = 0) BEGIN
            EXEC @ID = dbo.GetNextGatewayCounter ''WSLocalizationGroupModuleID''
            INSERT INTO WSLocalizationGroupModules (WSLocalizationGroupModuleID, WSLocalizationGroupID, Module, RecordVersion, LastUpdate, LastUpdatedBy) VALUES (@ID, @GroupID, @StringType, 1, GetDate(), ''upgrade'')
            UPDATE WSLocalization SET Module = @StringType, RecordVersion = RecordVersion + 1, LastUpdate = GetDate(), LastUpdatedBy = ''upgrade'' WHERE WSLocalizationGroupID = @GroupID
            END

        FETCH NEXT FROM Groups_Cursor INTO @GroupID, @StringType
    END

    CLOSE Groups_Cursor
    DEALLOCATE Groups_Cursor
    END'

    EXEC(@SQL)

    EXEC GTSUpgradeWSLocalizationGroups
END

/* TASK 4:  UPDATE EXISTING LOCALIZATION STRINGS - GTSUpdateExistingGroupLocalizations
 * create Stored procedure if it has not been created yet, before we call it.
 * It may not have been created because the WSLocalizationGroupModules table didn't exist
*/
IF (@Error = 0) AND ((@RunMode % 10) = 1) BEGIN
    DECLARE @StringTypeExists bit
    EXEC @StringTypeExists = GTSColumnExists WSLocalizationGroups, StringType   -- prevent error in test mode
    IF @StringTypeExists = 1 BEGIN

      IF NOT EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
             WHERE (o.name = 'GTSUpdateExistingGroupLocalizations') AND (o.type = 'P')
             AND   (o.uid = u.uid)
             AND   (u.name = 'dbo')) BEGIN

      PRINT '    ' + 'Creating GTSUpdateExistingGroupLocalizations...'
      SET @SQL =

      'CREATE PROCEDURE dbo.GTSUpdateExistingGroupLocalizations(@RunMode integer = 0)
      AS BEGIN
          DECLARE LocalizationGroupCursor CURSOR FOR
              SELECT m.WSLocalizationGroupID, m.Module
              FROM
                  WSLocalizationGroups g
              INNER JOIN
                  WSLocalizationGroupModules m
              ON
                  g.WSLocalizationGroupID = m.WSLocalizationGroupID

          DECLARE
              @GroupID int,
              @MODULE  int

          -- Update any existing WSLocalizations to change NULL values to 0 for TranslationLanguageID
          UPDATE WSLocalization SET TranslationLanguageID = isnull(TranslationLanguageID, 0)

          OPEN LocalizationGroupCursor
          FETCH FROM LocalizationGroupCursor INTO @GroupID, @Module
          WHILE (@@FETCH_STATUS = 0) BEGIN
              if (@Module = 0) EXEC GTSAddWSLocalizationDefaultValues @GroupID, @RunMode
              ELSE if (@Module = 1) EXEC GTSAddWSLocalizationResellerValues @GroupID
              ELSE if (@Module = 2) EXEC GTSAddWSLocalizationTransportationValues @GroupID
              ELSE if (@Module = 3) EXEC GTSAddWSLocalizationPassPortalValues @GroupID
              ELSE if (@Module = 4) EXEC GTSAddWSLocalizationMobileValues @GroupID

              FETCH FROM LocalizationGroupCursor INTO @GroupID, @Module
              END

          CLOSE LocalizationGroupCursor
          DEALLOCATE LocalizationGroupCursor
          END'

      EXEC(@SQL)
      END

      EXEC GTSUpdateExistingGroupLocalizations @RunMode

   END
END

/*  TASK 5 - CREATE DELETE TRIGGER on WSLocalizationGroup table
 * Only applies to Galaxy DB
 * Create triggers on WSLocalizationGroups table.  This must be done here because
 * during the upgrade of the WSLocalization table, the trigger must not be activated.
 */
 IF @WebStoreDB = 0 BEGIN
     -- EXEC GTSCreateWSLocalizationGroupInsertTrigger @RunMode, @Error OUTPUT  -- this trigger now obsolete,dropped above
     EXEC GTSCreateWSLocalizationGroupDeleteTrigger @RunMode, @Error OUTPUT
     END

/* TASK 6: Run the GTSConsolidateResponsiveLocalization stored procedure */
IF (@Error = 0) AND ((@RunMode % 10) = 1) BEGIN
    PRINT '    ' + 'Creating GTSConsolidateResponsiveLocalization to clean up unused localization strings for the responsive store'

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSConsolidateResponsiveLocalization') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTSConsolidateResponsiveLocalization'
        EXEC(@SQL)
        END

    SET @SQL =
    'CREATE PROCEDURE dbo.GTSConsolidateResponsiveLocalization AS BEGIN
        DECLARE
            @TableExists bit,
            @GroupID int

        EXEC @TableExists  = GTSTableExists ''WSLocalization_Backup_ResponsiveDesignConsolidation''
        IF (@TableExists = 0) BEGIN
            -- Create backup of WSlocalization if table WSLocalization_Backup_ResponsiveDesignConsolidation does not exist before deleting text strings that are no longer used
            SELECT * INTO dbo.WSLocalization_Backup_ResponsiveDesignConsolidation from WSLocalization

            DECLARE LocalizationGroupCursor CURSOR FOR
                SELECT WSLocalizationGroupID FROM WSLocalizationGroupModules

            OPEN LocalizationGroupCursor
            FETCH FROM LocalizationGroupCursor INTO @GroupID
            WHILE (@@FETCH_STATUS = 0) BEGIN
                EXEC GTSRemoveUnusedLocalizationStrings @GroupID
                FETCH FROM LocalizationGroupCursor INTO @GroupID
                END

            CLOSE LocalizationGroupCursor
            DEALLOCATE LocalizationGroupCursor
            END
        END'

    EXEC(@SQL)

    EXEC GTSConsolidateResponsiveLocalization
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

