    IF @TemplateCount = 0 BEGIN

        Set @SQL = 'DECLARE @TemplateID int ' +
            'EXEC @TemplateID = GetNextGatewayCounter ''WebTemplateID''  ' +
            'Insert into WebTemplates(WebTemplateID, TemplateName, TemplateKind, HTMLBody, PlainTextBody, RecordVersion, LastUpdate, LastUpdatedBy) '+
            '    VALUES(@TemplateID, ''Upsell Replacement Script'', 5, ''<% if IsOriginalSelection then begin %> Keep <% Write(ItemName) %> <% end else begin %>Upgrade to <%Write(UpsellItemName)%> for an additional $<% Write(PriceDifference) %><% end %>'', '+
            '           '''', 1, GetDate(), ''Script'') '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL

        IF @Error = 0 BEGIN
          Set @SQL = 'DECLARE @TemplateID int ' +
              'EXEC @TemplateID = GetNextGatewayCounter ''WebTemplateID''  ' +
              'Insert into WebTemplates(WebTemplateID, TemplateName, TemplateKind, HTMLBody, PlainTextBody, RecordVersion, LastUpdate, LastUpdatedBy) '+
              '    VALUES(@TemplateID, ''Upsell Add-On Script'', 5, ''Add <%Write(UpsellItemName)%> for an additional $<%Write(UpsellPrice)%> each'', ' +
              '           '''', 1, GetDate(), ''Script'') '
          EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
          END

        IF @Error = 0 BEGIN
          Set @SQL = 'DECLARE @TemplateID int ' +
              'EXEC @TemplateID = GetNextGatewayCounter ''WebTemplateID''  ' +
              'Insert into WebTemplates(WebTemplateID, TemplateName, TemplateKind, HTMLBody, PlainTextBody, RecordVersion, LastUpdate, LastUpdatedBy) '+
              '    VALUES(@TemplateID, ''Upsell Replacement Header Script'', 5, ''Replace <%Write(ItemName)%>?'', ' +
              '           '''', 1, GetDate(), ''Script'') '
          EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
          END

        IF @Error = 0 BEGIN
          Set @SQL = 'DECLARE @TemplateID int ' +
              'EXEC @TemplateID = GetNextGatewayCounter ''WebTemplateID''  ' +
              'Insert into WebTemplates(WebTemplateID, TemplateName, TemplateKind, HTMLBody, PlainTextBody, RecordVersion, LastUpdate, LastUpdatedBy) '+
              '    VALUES(@TemplateID, ''Upsell Add-On Header Script'', 5, ''<% if AddOnCount > 0 then begin %>Add-Ons<% end %>'', ' +
              '           '''', 1, GetDate(), ''Script'') '
          EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
          END

        IF @Error = 0 BEGIN
          Set @SQL = 'DECLARE @TemplateID int ' +
              'EXEC @TemplateID = GetNextGatewayCounter ''WebTemplateID''  ' +
              'Insert into WebTemplates(WebTemplateID, TemplateName, TemplateKind, HTMLBody, PlainTextBody, RecordVersion, LastUpdate, LastUpdatedBy) '+
              '    VALUES(@TemplateID, ''Transactional Upsell Replacement Script'', 5, ' +
              ' '' Upgrade <% for i = 0 to RequirementCount - 1 do begin Write(Upsell.GetRequirementFields(i, ''''Quantity''''))%> <% Write(Upsell.GetRequirementFields(i, ''''ItemName'''')) %> <% if i <> (RequirementCount - 1) then begin %>, <% end %> <% end %>to <% Write(UpsellItemName) if PriceDifference > 0 then begin %> for an additional <% end else begin%> for a savings of <% end %> $<% Write(FormatCurrency(Abs(PriceDifference))) %> '', ' +
              '           '''', 1, GetDate(), ''Script'') '
          EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
          END

        IF @Error = 0 BEGIN
          Set @SQL = 'DECLARE @TemplateID int ' +
              'EXEC @TemplateID = GetNextGatewayCounter ''WebTemplateID''  ' +
              'Insert into WebTemplates(WebTemplateID, TemplateName, TemplateKind, HTMLBody, PlainTextBody, RecordVersion, LastUpdate, LastUpdatedBy) '+
              '    VALUES(@TemplateID, ''Transactional Upsell Replacement Header Script'', 5, ''Replacement Options'', ' +
              '           '''', 1, GetDate(), ''Script'') '
          EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
          END

        END
    END
