/*************** BEGINNING OF SMART UPSELL SPECIFIC UPGRADES ****************/

IF @EnableSmartUpsell =  1 BEGIN
    /*************** Smart Upsell Specific Tables *******************/
    PRINT '    ' + 'Smart Upsell is enabled, checking Smart Upsell related configuration/tables/procedures'

    PRINT '    ' + 'Setting Smart Upsell Configuration option...'
    SET @SQL = '
        DECLARE @SmartUpsellConfigFlagExists bit
        SELECT @SmartUpsellConfigFlagExists = COUNT(*) FROM ConfigurationOptions WHERE Code = 1051
        IF (@SmartUpsellConfigFlagExists = 0) BEGIN
            DECLARE @OptionID int
            EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID''
            INSERT INTO ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID)
                VALUES (@OptionID, ''Smart upsell is enabled'', ''YES'', 3, 1051, 1, GetDate(), ''Script'', 0, 0)
            END
        ELSE BEGIN
            UPDATE ConfigurationOptions SET Value = ''YES'', RecordVersion = RecordVersion + 1, LastUpdate = CURRENT_TIMESTAMP, LastUpdatedBy = ''Script'' WHERE Code = 1051 AND Value <> ''YES'';
            END'
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL

    --
    --  -------------------------------------------------------------------
    --
    --                  ***  SmartUpsellRules  ***
    --
    SET @TableName = 'SmartUpsellRules'
    SET @TableStructure = '
            SmartUpsellRuleID                int IDENTITY(1,1)    NOT NULL PRIMARY KEY,
            TargetPLU                        nvarchar(20)         NOT NULL,
            Sequence                         int                  NOT NULL,
            Description                      nvarchar(100)        NOT NULL,
            Inactive                         bit                  NOT NULL DEFAULT 0,
            IncludeUpgrades                  bit,
            IncludeUpsellAddOns              bit,
            IncludeUpsellReplacements        bit,
            ConditionScript                  nvarchar(max)        NOT NULL,
            ConditionScriptType              nvarchar(10)         NOT NULL,
            ActionEmphasisEnabled            bit,
            ActionEmphasisValue              int                  NOT NULL,
            ActionHideEnabled                bit,
            ActionHideValue                  bit,
            ActionScriptTemplateIDEnabled    bit,
            ActionScriptTemplateIDValue      int                  NOT NULL,
            IncludeProducts                  bit,

            RecordVersion                    int                  NOT NULL,
            LastUpdate                       datetime             NOT NULL,
            LastUpdatedBy                    nvarchar(20)             NULL
    ' -- *** NO CLOSING PARENTHESIS

    EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

    EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, IncludeProducts, bit

    EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT, @TableName, SmartUpsellRuleID, PKSmartUpsellRuleID

    EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

    /* Stop the script if an error has occurred */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    --
    --  -------------------------------------------------------------------
    --
    --                  ***  SmartUpsellSalesGoals  ***
    --
    SET @TableName = 'SmartUpsellSalesGoals'
    SET @TableStructure = '
            SmartUpsellSalesGoalID           int IDENTITY(1,1)    NOT NULL PRIMARY KEY,
            Description                      nvarchar(100)        NOT NULL,
            ItemGroupID                      int                  NOT NULL,
            GoalSalesCountVariableName       nvarchar(100)        NOT NULL,
            GoalIsMetVariableName            nvarchar(100)        NOT NULL,
            SalesCountVariableName           nvarchar(100)        NOT NULL,

            RecordVersion                    int                  NOT NULL,
            LastUpdate                       datetime             NOT NULL,
            LastUpdatedBy                    nvarchar(20)             NULL
    ' -- *** NO CLOSING PARENTHESIS

    EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

    EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT, @TableName, SmartUpsellSalesGoalID, PKSmartUpsellSalesGoalID

    EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

    /* Stop the script if an error has occurred */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    --
    --  -------------------------------------------------------------------
    --
    --                  ***  SmartUpsellSalesGoalDetails  ***
    --
    SET @TableName = 'SmartUpsellSalesGoalDetails'
    SET @TableStructure = '
            SmartUpsellSalesGoalDetailID     int IDENTITY(1,1)    NOT NULL PRIMARY KEY,
            SmartUpsellSalesGoalID           int                  NOT NULL,
            GoalSalesCount                   int                  NOT NULL,
            GoalStartDate                    datetime             NOT NULL,
            GoalEndDate                      datetime             NOT NULL,

            RecordVersion                    int                  NOT NULL,
            LastUpdate                       datetime             NOT NULL,
            LastUpdatedBy                    nvarchar(20)             NULL
    ' -- *** NO CLOSING PARENTHESIS

    EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

    EXEC GTSUpgradeAddPK  @RunMode, @Error OUTPUT, @TableName, SmartUpsellSalesGoalDetailID, PKSmartUpsellSalesGoalDetailID

    EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT,  @TableName, SmartUpsellSalesGoalID, IXSmartUpsellSalesGoalID

    EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

    /* Stop the script if an error has occurred */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    --                      PROCEDURE GTS_UpdateSmartUpsellUsageCount
    --
    PRINT '    ' + 'Creating GTS_UpdateSmartUpsellUsageCount...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_UpdateSmartUpsellUsageCount') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_UpdateSmartUpsellUsageCount'
        EXEC GTSUpgradeExecSQL @Runmode, @Error OUTPUT, @SQL
        END

    SET @SQL =
    'CREATE PROCEDURE [dbo].[GTS_UpdateSmartUpsellUsageCount]
        @externalVariableName VARCHAR(100), -- The to ExternalVariables.Name to update (or insert).
        @usageTimeSpanMinutes INTEGER, -- The size of the usage window in minutes
        @itemGroupID INTEGER -- GxItemGroups.ItemGroupID of the item group
    AS
    BEGIN
        SET NOCOUNT ON;

        DECLARE @useCount INTEGER
        DECLARE @description VARCHAR(100)
        DECLARE @lastUpdatedBy NVARCHAR(20)
        DECLARE @itemGroupDescription CHAR(40)

        SET @itemGroupDescription = (SELECT Description FROM GxItemGroups WHERE ItemGroupID = @itemGroupID)
        SET @description =  ''Usage of ItemGroupID:'' + CAST(@itemGroupID AS VARCHAR) + '' ('' + RTRIM(@itemGroupDescription) + '') in past '' + CAST(@usageTimeSpanMinutes AS VARCHAR) + '' minute(s)''
        SET @lastUpdatedBy = ''SmtUpslUsgSP''

        -- Count usage of items in the given item group for the given time span.
        SET @useCount = (
            SELECT
                SUM(CASE WHEN Usage.Code IN (0, 13) THEN Usage.Qty ELSE -Usage.Qty END)
            FROM Usage
                LEFT OUTER JOIN Tickets ON Tickets.VisualID = Usage.VisualID
                LEFT OUTER JOIN Passes ON Passes.VisualID = Usage.VisualID
            WHERE Usage.UseTime >= DATEADD(MINUTE, -@usageTimeSpanMinutes, CURRENT_TIMESTAMP)
                AND Usage.Code IN (0,1,9,11,13,14,15)
                AND Usage.Status = 0
                AND COALESCE(Tickets.PLU, Passes.PLU) IN (
                    SELECT PLU
                    FROM GxItemGroupDetails
                    WHERE ItemGroupID = @itemGroupID))
        SET @useCount = ISNULL(@useCount, 0)

        -- Insert (or update) use count in the ExternalVariables table. ExternalVariables.Name is the name given via @externalVariableName.
        MERGE ExternalVariables WITH (HOLDLOCK) AS TargetTable
        USING (SELECT @externalVariableName AS VariableName) AS SourceTable
            ON TargetTable.Name = SourceTable.VariableName
        WHEN MATCHED THEN UPDATE
            SET DataValue = @useCount,
                Description = @description,
                RecordVersion = RecordVersion + 1,
                LastUpdate = CURRENT_TIMESTAMP,
                LastUpdatedBy = @lastUpdatedBy
        WHEN NOT MATCHED THEN
            INSERT (
                Name,
                Description,
                DataType,
                DataValue,
                RecordVersion,
                LastUpdate,
                LastUpdatedBy)
            VALUES (
                @externalVariableName,
                @description,
                3, -- Integer data type
                @useCount,
                1, -- Record version
                CURRENT_TIMESTAMP,
                @lastUpdatedBy);
        END'

    IF ((@RunMode % 10) = 1) BEGIN
        EXEC(@SQL)
        END

    /*
     *  Stop the script if an error has occurred
     */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    END

/*************** END OF SMART UPSELL SPECIFIC UPGRADES ****************/

