    SET @SQL = '
        DECLARE @CloudPublishingConfigFlagExists bit
        SELECT @CloudPublishingConfigFlagExists = COUNT(*) FROM ConfigurationOptions WHERE Code = 1305
        IF (@CloudPublishingConfigFlagExists = 0) BEGIN
            DECLARE @OptionID int
            EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID''
            INSERT INTO ConfigurationOptions(ConfigurationOptionID, Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID)
                VALUES (@OptionID, ''Cloud Publishing Enabled'', ''YES'', 3, 1305, 1, GetDate(), ''Script'', 0, 0)
            END
        ELSE BEGIN
            UPDATE ConfigurationOptions SET Value = ''YES'', RecordVersion = RecordVersion + 1, LastUpdate = CURRENT_TIMESTAMP, LastUpdatedBy = ''Script'' WHERE Code = 1305 AND Value <> ''YES'';
            END'
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
    END


--                      PROCEDURE GTSPopulateGUIDColumnsForCloudTables
--
PRINT '    ' + 'Creating GTSPopulateGUIDColumnsForCloudTables...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSPopulateGUIDColumnsForCloudTables') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo')) BEGIN
    SET @SQL = 'DROP PROCEDURE dbo.GTSPopulateGUIDColumnsForCloudTables'
    EXEC GTSUpgradeExecSQL @Runmode, @Error OUTPUT, @SQL
    END

PRINT '    ' + 'Creating GTSPopulateGUIDColumnsForCloudTables...'
DECLARE @CloudSQL nvarchar(MAX)
SET @CloudSQL =
'CREATE PROCEDURE [dbo].[GTSPopulateGUIDColumnsForCloudTables]
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @table NVARCHAR(128);
    DECLARE @column NVARCHAR(128);
    DECLARE @CloudTableName NVARCHAR(128);
    DECLARE @GUIDColumnName NVARCHAR(128);
    DECLARE @type NVARCHAR(128);
    DECLARE @GUIDsql NVARCHAR(MAX);
    DECLARE @TablesToUpdate TABLE (TableName NVARCHAR(32));

    -- Populate temp table with cloud-supported table names to update
    INSERT INTO @TablesToUpdate VALUES
        (N''AccessCodes''),
        (N''Addresses''),
        (N''Agencies''),
        (N''AttributeCategories''),
        (N''AttributeDefinitionGroups''),
        (N''AttributeDefinitions''),
        (N''COA''),
        (N''ConfigurationOptions''),
        (N''CodeTables''),
        (N''CodeTableValues''),
        (N''Companies''),
        (N''CustCategories''),
        (N''CustContacts''),
        (N''Customers''),
        (N''DeliveryMethodGroups''),
        (N''DeliveryMethods''),
        (N''Disbursements''),
        (N''DisbursementDetails''),
        (N''Discounts''),
        (N''DiscountDetails''),
        (N''DiscountPrivileges''),
        (N''DiscountRequirements''),
        (N''DiscountValidations''),
        (N''EventSaleLimits''),
        (N''FopDetails''),
        (N''FOPs''),
        (N''Holidays''),
        (N''ItemGroups''),
        (N''ItemGroupDetails''),
        (N''ItemModifierGroupDetails''),
        (N''Items''),
        (N''ItemVariations''),
        (N''Media''),
        (N''MediaFiles''),
        (N''MemberEditFields''),
        (N''ModifierGroupDetails''),
        (N''ModifierGroups''),
        (N''Modifiers''),
        (N''Nodes''),
        (N''PackageDetails''),
        (N''Packages''),
        (N''PageTemplates''),
        (N''PassEditFields''),
        (N''PassKindGroupDetails''),
        (N''PassKindGroups''),
        (N''PassKinds''),
        (N''PaymentPlans''),
        (N''PostalCodeRangeDetails''),
        (N''PostalCodeRanges''),
        (N''PriceCalendars''),
        (N''PriceProgramGroups''),
        (N''PricePrograms''),
        (N''PriceProgramTimeRanges''),
        (N''PriceSchedules''),
        (N''RelationshipTypes''),
        (N''RMEventTypes''),
        (N''RMResources''),
        (N''RMResourceTypes''),
        (N''SalesChannelDetails''),
        (N''SalesChannels''),
        (N''SalesPrograms''),
        (N''Storefronts''),
        (N''Taxes''),
        (N''TaxSetDetails''),
        (N''TaxSets''),
        (N''TaxTableDetails''),
        (N''TaxTableHeaders''),
        (N''TranslationLanguages''),
        (N''UpsellOptions''),
        (N''WebTemplates'')
        --  Can add more tables here

    PRINT ''Populating null/blank GUID fields for all cloud-supported tables''
    DECLARE cur CURSOR FOR
    SELECT t.name AS TableName, c.name AS ColumnName, ty.name AS DataType
    FROM sys.tables t
    JOIN sys.columns c ON t.object_id = c.object_id
    JOIN sys.types ty ON c.user_type_id = ty.user_type_id
    JOIN @TablesToUpdate ttu on t.name COLLATE DATABASE_DEFAULT = ttu.TableName COLLATE DATABASE_DEFAULT
    WHERE c.name LIKE ''%GUID%'' AND ty.name = ''uniqueidentifier'' order by tablename
    OPEN cur;
    FETCH NEXT FROM cur INTO @table, @column, @type;
    WHILE @@FETCH_STATUS = 0 BEGIN
        PRINT ''    '' + ''Updating null/blank GUID values for '' + QUOTENAME(@table) + ''.'' + QUOTENAME(@column)
        SET @CloudTableName = QUOTENAME(@table)
        SET @GUIDColumnName = QUOTENAME(@column)

        -- Batch process 10,000 rows at a time to avoid transaction log issues
        SET @GUIDsql = ''WHILE EXISTS (SELECT 1 FROM '' + @CloudTableName + ''WHERE '' + @GUIDColumnName + '' IS NULL OR '' + @GUIDColumnName + '' = ''''00000000-0000-0000-0000-000000000000'''') BEGIN '' +
        ''    UPDATE TOP (10000) '' + @CloudTableName +
        ''        SET '' + @GUIDColumnName + '' = newid() '' +
        ''        WHERE ''+ @GUIDColumnName + '' IS NULL OR '' + @GUIDColumnName + '' = ''''00000000-0000-0000-0000-000000000000'''''' +
        ''    END''
        EXEC sp_executesql @GUIDsql;

        FETCH NEXT FROM cur INTO @table, @column, @type;
        END
    CLOSE cur;
    DEALLOCATE cur;
    END'

IF ((@RunMode % 10) = 1) BEGIN
    EXEC @Error = sp_ExecuteSQL @CloudSQL
    END

/* Stop the script if an error has occurred */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, 'GTSPopulateGUIDColumnsForCloudTables'
    RETURN
    END

IF (@PopulateGUIDColumnsForCloudTables = 1) AND ((@RunMode % 10) = 1) BEGIN
    EXEC GTSPopulateGUIDColumnsForCloudTables
    END
/*************** END OF CLOUD PUBLISHING SPECIFIC UPGRADES ****************/

