IF ((@RunMode % 10) = 1) BEGIN   /* Upgrade Mode or Post-Upgrade Mode */
    EXEC CreateRMStoredProcedures -- Drop/create version specific RM stored procedures
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

--
--                      PROCEDURE GTSReplaceContactReferences
--
PRINT '    ' + 'Creating GTSReplaceContactReferences...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSReplaceContactReferences') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo')) BEGIN
    SET @SQL = 'DROP PROCEDURE dbo.GTSReplaceContactReferences'
    EXEC GTSUpgradeExecSQL @Runmode, @Error OUTPUT, @SQL
    END

SET @SQLMAX =
'CREATE PROCEDURE dbo.GTSReplaceContactReferences(
    @replaceContactID    BIGINT,
    @withContactID       BIGINT,
    @replaceContactGUID  UNIQUEIDENTIFIER = NULL,
    @lastUpdatedBy       VARCHAR(20)      = NULL,
    @lastUpdate          DATETIME         = NULL,
    @testMode            BIT              = NULL,
    @printEnabled        BIT              = NULL,
    @printEachRowUpdated BIT              = NULL,
    @result              BIT              = NULL OUTPUT,
    @resultMessage       NVARCHAR(512)    = NULL OUTPUT) AS
BEGIN
    -- Description: Replaces all references to a contact with another contact.  Does not modify
    -- the CustContacts table.

    SET NOCOUNT ON;

    SET @result = 0 -- Default to failure.
    SET @resultMessage = ''''

    -- *** Declarations ***
    DECLARE @printSkippedTables   BIT             = 1

    DECLARE
        @updateMessagePrefix      VARCHAR(100)    = ''Updating table '',
        @updateMessagePostfix     VARCHAR(100)    = '' if necessary...'',
        @skipFormatMessage        VARCHAR(100)    = ''Skipped nonexistent table '',
        @updatedMessagePostfix    VARCHAR(20)     = '' rows updated.''

    DECLARE
        @currentTable             VARCHAR(255)    = '''',
        @localErrorMessage        NVARCHAR(4000)  = '''',
        @minimumSeverity          TINYINT         = 11, -- 0-10 will not get caught
        @localErrorSeverity       TINYINT         = 11,
        @error                    BIT             = 1,
        @numberUpdated            BIGINT          = 0

    DECLARE
        @withContactGUID          UNIQUEIDENTIFIER,
        @withFirstName            CHAR(30),
        @withMiddleName           VARCHAR(30),
        @withLastName             CHAR(30),
        @withAddressID            INT,
        @withStreet1              VARCHAR(255),
        @withStreet2              VARCHAR(255),
        @withCity                 VARCHAR(40),
        @withState                VARCHAR(40),
        @withPostal               CHAR(16),
        @withCountryCode          CHAR(2),
        @withEmail                VARCHAR(128),
        @withPhone                CHAR(30),
        @withDOB                  DATETIME,
        @withJobTitle             CHAR(30),
        @withFax                  CHAR(30)

    DECLARE @updatedTable TABLE ( TableName VARCHAR(100), ID BIGINT)

    -- *** Initialize/Validate input ***
    IF @lastUpdatedBy IS NULL       SET @lastUpdatedBy       = ''StoredProcedure''
    IF @lastUpdate IS NULL          SET @lastUpdate          = GETDATE()
    IF @testMode IS NULL            SET @testMode            = 0
    IF @printEnabled IS NULL        SET @printEnabled        = 0
    IF @printEachRowUpdated IS NULL SET @printEachRowUpdated = 0

    IF (@replaceContactID IS NULL) OR (@withContactID IS NULL)
    BEGIN
        SET @localErrorMessage = ''All ContactID parameters are required.''
        GOTO ExitSP
    END

    -- Try to look up replaced contact CustContactGUID if it is not provided
    IF (@replaceContactGUID IS NULL) or (LTRIM(RTRIM(@replaceContactGUID)) = '''')
    BEGIN
        SELECT @replaceContactGUID = CustContactGuid FROM CustContacts WHERE CustContactID = @replaceContactID
    END

    -- Make sure replacement ContactID is valid.
    DECLARE @contactCount BIT = 0
    SELECT @contactCount = COUNT(*) FROM CustContacts WHERE CustContactID = @withContactID
    IF @contactCount <> 1
    BEGIN
        SET @localErrorMessage = ''ContactID '' + CONVERT(VARCHAR(10), @withContactID) + '' does not exist.''
        GOTO ExitSP
    END

    -- Look up the replacement Contact names and other info
    SELECT TOP(1)
        @withContactGUID = CustContactGUID,
        @withFirstName = FirstName,
        @withMiddleName = MiddleName,
        @withLastName = LastName,
        @withAddressID = AddressID,
        @withPhone = Phone,
        @withEmail = Email,
        @withDOB = DOB,
        @withJobTitle = JobTitle,
        @withFax = Fax
        FROM CustContacts WHERE CustContactID = @withContactID

    -- Look up replacement Contact''s address
    SELECT
        @withStreet1 = Street1,
        @withStreet2 = Street2,
        @withCity = City,
        @withState = [State],
        @withPostal = Postal,
        @withCountryCode = CountryCode
        FROM Addresses WHERE AddressID = @withAddressID

    -- *** Start Execution ***
    IF @testMode = 1
    BEGIN
        IF @printEnabled = 1 PRINT ''Executing in Test Mode. No rows will be updated.''
        IF @printEnabled = 1 PRINT ''''
    END

    IF @printEnabled = 1 PRINT ''Starting transaction...''
    IF @printEnabled = 1 PRINT ''''
    BEGIN TRANSACTION
    BEGIN TRY

        -- Update table
        SET @currentTable = ''ACSReservationProfiles''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            IF @replaceContactGUID IS NOT NULL
            BEGIN
                UPDATE ACSReservationProfiles SET ContactGUID = @withContactGUID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.ACSReservationProfileID INTO @updatedTable WHERE ContactGUID = @replaceContactGUID
            END

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''ACSReservations''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            IF @replaceContactGUID IS NOT NULL
            BEGIN
                UPDATE ACSReservations SET ContactGUID = @withContactGUID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.ACSReservationID INTO @updatedTable WHERE ContactGUID = @replaceContactGUID
                UPDATE ACSReservations SET ReservedByContactGUID = @withContactGUID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.ACSReservationID INTO @updatedTable WHERE ReservedByContactGUID = @replaceContactGUID
            END

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''Activities''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE Activities SET ContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.ActivityID INTO @updatedTable WHERE ContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''ARAccounts''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE ARAccounts SET BillToContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.AccountID INTO @updatedTable  WHERE BillToContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''ARCreditMemos''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE ARCreditMemos SET BillToContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.CreditMemoID INTO @updatedTable  WHERE BillToContactID = @replaceContactID
            UPDATE ARCreditMemos SET ShipToContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.CreditMemoID INTO @updatedTable  WHERE ShipToContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''ARInvoices''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE ARInvoices SET BillToContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.InvoiceID INTO @updatedTable  WHERE BillToContactID = @replaceContactID
            UPDATE ARInvoices SET ShipToContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.InvoiceID INTO @updatedTable  WHERE ShipToContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
