                , [Middle] = CASE WHEN ISNULL(LTRIM(RTRIM([Middle])), '''') = '''' THEN [Middle] ELSE @withMiddleName END
                , [Last] = CASE WHEN ISNULL(LTRIM(RTRIM([Last])), '''') = '''' THEN [Last] ELSE @withLastName END
                , Street1  = CASE WHEN ((ISNULL(LTRIM(RTRIM(Street1)), '''') <> '''') OR (ISNULL(LTRIM(RTRIM(Street2)), '''') <> '''')) THEN LEFT(@withStreet1, 30) ELSE Street1 END
                , Street2  = CASE WHEN ((ISNULL(LTRIM(RTRIM(Street1)), '''') <> '''') OR (ISNULL(LTRIM(RTRIM(Street2)), '''') <> '''')) THEN LEFT(@withStreet2, 30) ELSE Street2 END
                , City  = CASE WHEN ISNULL(LTRIM(RTRIM(City)), '''') = '''' THEN City ELSE @withCity END
                , [State]  = CASE WHEN ISNULL(LTRIM(RTRIM([State])), '''') = '''' THEN [State] ELSE @withState END
                , Zip  = CASE WHEN ISNULL(LTRIM(RTRIM(Zip)), '''') = '''' THEN Zip ELSE LEFT(@withPostal, 10) END
                , CountryCode  = CASE WHEN ISNULL(LTRIM(RTRIM(CountryCode)), '''') = '''' THEN CountryCode ELSE @withCountryCode END
                , Phone  = CASE WHEN ISNULL(LTRIM(RTRIM(Phone)), '''') = '''' THEN Phone ELSE LEFT(@withPhone, 16) END
                , Email  = CASE WHEN ISNULL(LTRIM(RTRIM(Email)), '''') = '''' THEN Email ELSE @withEmail END
                , DOB  = CASE WHEN ((DOB IS NULL) OR (DOB <= 0)) THEN DOB ELSE @withDOB END -- <= ''1900-01-01''
