            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE PkgInstances SET ContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.PkgInstanceID INTO @updatedTable  WHERE ContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''Rosters''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE Rosters SET ContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.RosterID INTO @updatedTable  WHERE ContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''Relationships''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE Relationships SET FromContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.RelationshipID INTO @updatedTable  WHERE FromContactID = @replaceContactID
            UPDATE Relationships SET ToContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.RelationshipID INTO @updatedTable  WHERE ToContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''RSEventSeats''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE RSEventSeats SET ContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.RSEventSeatID INTO @updatedTable  WHERE ContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''SuperTickets''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE SuperTickets SET ContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.SuperTicketID INTO @updatedTable  WHERE ContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''Tickets''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE Tickets SET ContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1
                , FirstName = CASE WHEN ISNULL(LTRIM(RTRIM(FirstName)), '''') = '''' THEN FirstName ELSE @withFirstName END
                , LastName = CASE WHEN ISNULL(LTRIM(RTRIM(LastName)), '''') = '''' THEN LastName ELSE @withLastName END
                OUTPUT @currentTable, inserted.TicketID INTO @updatedTable  WHERE ContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- Update table
        SET @currentTable = ''WaitLists''
        IF OBJECT_ID(@currentTable, ''U'') IS NOT NULL
        BEGIN
            IF @printEnabled = 1 PRINT @updateMessagePrefix + @currentTable + @updateMessagePostfix
            UPDATE WaitLists SET ContactID = @withContactID, LastUpdate = @lastUpdate, LastUpdatedBy = @lastUpdatedBy, RecordVersion = RecordVersion + 1 OUTPUT @currentTable, inserted.WaitListID INTO @updatedTable  WHERE ContactID = @replaceContactID

            IF @printEachRowUpdated = 1
            BEGIN
                SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable WHERE TableName = @currentTable GROUP BY TableName, ID) ut
                IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + @updatedMessagePostfix
            END
        END
        ELSE IF (@printEnabled = 1) AND (@printSkippedTables = 1) PRINT @skipFormatMessage + @currentTable + ''.''

        -- If we got this far all updates were successful, so commit the transaction (if not test mode)
        SET @error = 0
        IF @testMode = 0
        BEGIN
            IF @printEnabled = 1 PRINT ''''
            IF @printEnabled = 1 PRINT ''Committing transaction...''
            COMMIT TRANSACTION
        END
        ELSE
        BEGIN
            IF @printEnabled = 1 PRINT ''''
            IF @printEnabled = 1 PRINT ''Rolling back transaction due to test mode...''
            ROLLBACK TRANSACTION
        END

    END TRY
    BEGIN CATCH
        SET @localErrorMessage  = error_message()
        SET @localErrorSeverity = error_severity()

        IF @printEnabled = 1 PRINT ''''
        IF @printEnabled = 1 PRINT ''Rolling back transaction due to error: '' + @localErrorMessage
        ROLLBACK TRANSACTION

        SET @error = 1
        GOTO ExitSP
    END CATCH

ExitSP:
    IF @printEnabled = 1 PRINT ''''
    if @error = 1
    BEGIN
        IF @printEnabled = 1 PRINT ''Failed due to error: '' + @localErrorMessage
        IF @printEnabled = 1 PRINT ''No changes have been made.''
        IF @localErrorSeverity < @minimumSeverity SET @localErrorSeverity = @minimumSeverity

        SET @result = 0
        SET @resultMessage = LEFT(@localErrorMessage, 512)

        RAISERROR(@localErrorMessage, @localErrorSeverity, 1)
        RETURN 0
    END
    ELSE
    BEGIN
        SELECT @numberUpdated = COUNT(*) FROM (SELECT * FROM @updatedTable GROUP BY TableName, ID) ut
        IF @printEnabled = 1 PRINT CONVERT(VARCHAR(10), @numberUpdated) + '' total'' + @updatedMessagePostfix
        IF @printEnabled = 1 PRINT ''Finished successfully.''

        SET @result = 1
        SET @resultMessage = ''Finished successfully.''

        RETURN 1
    END
END'

IF ((@RunMode % 10) = 1) BEGIN
    EXEC(@SQLMAX)
    END

/*
 *  Stop the script if an error has occurred
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

--
--                      PROCEDURE GTSRemoveUnusedPictures
--
IF (@WebStoreDB = 0) and ((@RunMode % 10) = 1) BEGIN
    Print N'Creating stored procedure GTSRemoveUnusedPictures'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSRemoveUnusedPictures') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTSRemoveUnusedPictures

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTSRemoveUnusedPictures] AS
            BEGIN
                SET NOCOUNT ON

                DECLARE
                    @localErrorMessage        NVARCHAR(4000)  = '''',
                    @localErrorSeverity       TINYINT         = 16, -- 0-10 will not get caught
                    @error                    BIT             = 0,
                    @iterationCount           INT             = 0

                RAISERROR (''Running GTSRemoveUnusedPictures...'', 0, 0) WITH NOWAIT

                DECLARE @UnusedPictureIDs TABLE
                (
                    PictureID INT
                )

                BEGIN TRANSACTION
                BEGIN TRY
                    RAISERROR (''Note: Multiple iterations may be required to find and remove all unused pictures.'', 0, 0) WITH NOWAIT
                    -- Multiple iterations may be needed since pictures can be linked by BaseID. We do not delete a picture if another
                    -- picture references it, but it is possible that the referencing picture was deleted, which allows us to delete
                    -- the original image.  We limit the number of iterations to 10 in order to prevent too many loops.
                    WHILE @iterationCount < 10
                    BEGIN
                        DELETE FROM @UnusedPictureIDs
                        SET @iterationCount = @iterationCount + 1
                        RAISERROR ('''', 0, 0) WITH NOWAIT
                        RAISERROR (''Begin iteration %d'', 0, 0, @iterationCount) WITH NOWAIT
                        RAISERROR (''    Finding unused pictures...'', 0, 0) WITH NOWAIT

                        -- Find pictures that are not used by any tables (including Pictures itself)
                        -- IMPORTANT DEV NOTE: If you need to modify this to add/remove tables or columns, you should also update the
                        -- LOADWITHIDIFORPHANED query (in GTSPicturesSQL.pas) with the corresponding change.
                        INSERT INTO @UnusedPictureIDs
                            SELECT PictureID FROM Pictures WHERE PictureID NOT IN
                            (
                                SELECT BaseID AS PictureID FROM Pictures WHERE BaseID > 0 AND BaseID <> PictureID
                                UNION
                                SELECT PictureID FROM Passes WHERE PictureID > 0
                                UNION
                                SELECT PendingPictureID AS PictureID FROM Passes WHERE PendingPictureID > 0
                                UNION
                                SELECT PictureID FROM JointMembers WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM Customers WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM EventManagementSectionActivity WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM OrderLineJointMembers WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM RSEventSections WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM RSSections WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM Tickets WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM TransactionalUpsellOptions WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM UpsellOptions WHERE PictureID > 0
                                UNION
                                SELECT PictureID FROM SalesScriptPictures WHERE PictureID > 0
                             )

                        DECLARE @unusedPictureCount INT = (SELECT COUNT(*) FROM @UnusedPictureIDs)
                        RAISERROR (''        Found %d unused pictures.'', 0, 0, @unusedPictureCount) WITH NOWAIT

                        IF @unusedPictureCount = 0
                        BEGIN
                            BREAK
                        END

                        RAISERROR ('''', 0, 0) WITH NOWAIT
                        RAISERROR (''    Removing unused pictures...'', 0, 0) WITH NOWAIT
                        DELETE FROM Pictures WHERE PictureID IN (SELECT PictureID FROM @UnusedPictureIDs)
                        RAISERROR (''        Done.'', 0, 0) WITH NOWAIT
                    END

                    RAISERROR ('''', 0, 0) WITH NOWAIT
                    RAISERROR (''    Committing SQL transaction...'', 0, 0) WITH NOWAIT
                    COMMIT TRANSACTION
                    RAISERROR(''        Done.'', 0, 0) WITH NOWAIT
                END TRY
                BEGIN CATCH
                    -- If an error occurs, roll back the transaction if it is still open and display the error.

                    SET @localErrorMessage  = error_message()
                    SET @localErrorSeverity = error_severity()
                    SET @error = 1

                    IF (XACT_STATE()) <> 0
                    BEGIN
                        RAISERROR ('''', 0, 0) WITH NOWAIT
                        RAISERROR (''Rolling back SQL transaction due to error: %s'', 0, 0, @localErrorMessage) WITH NOWAIT
                        ROLLBACK TRANSACTION
                        RAISERROR(''    Done.'', 0, 0) WITH NOWAIT
                    END
                END CATCH

                RAISERROR ('''', 0, 0) WITH NOWAIT

                IF @error = 1
                    RAISERROR (''GTSRemoveUnusedPictures completed with an error.'', @localErrorSeverity, 0) WITH NOWAIT
                ELSE
                    RAISERROR (''GTSRemoveUnusedPictures completed successfully.'', 0, 0) WITH NOWAIT

                SET NOCOUNT OFF
            END'
        END
    END

/*
 *  Stop the script if an error has occurred while creating GTSRemoveUnusedPictures.
 */
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode, @Error, @TableName
    RETURN
    END

