        '        SELECT I.NodeID, I.NodeNumber, I.Kind, I.LastUpdatedBy, D.NodeNumber FROM INSERTED I INNER JOIN DELETED D ON I.NodeID = D.NodeID '+

        '    DECLARE                            '+
        '        @ID               int,         '+
        '        @NodeNumber       int,         '+
        '        @Kind             int,         '+
        '        @LastUpdatedBy    varchar(20), '+
        '        @OldNodeNumber    int,         '+
        '        @ResellerKind     int          '+  -- Constant for reseller nodes kind (11)

        'SET @ResellerKind = 11                 '+  -- Nodes.Kind for reseller nodes is 11

        '    OPEN CR                            '+
        '    FETCH FROM CR INTO @ID, @NodeNumber, @Kind, @LastUpdatedBy, @OldNodeNumber  '+

        '    WHILE( @@FETCH_STATUS = 0 ) BEGIN    '+
             -- If node number was changed, need to delete the old node and add the new
        '       IF @OldNodeNumber <> @NodeNumber BEGIN ' +
        '           INSERT INTO RowChanges         '+
        '                    (RowID, TableID, Code, PublishCount, Action,  LocalKey, RecordVersion, LastUpdate, LastUpdatedBy)  '+
        '           VALUES (@ID,   80,      622,   0,           1,       @NodeNumber,   1,        GetDate(),  @LastUpdatedBy) '+

        '           INSERT INTO RowChanges          '+
        '                    (RowID, TableID, Code, PublishCount, Action,  LocalKey, RecordVersion, LastUpdate, LastUpdatedBy) '+
        '           VALUES (@ID,   80,      622,   0,           2,       @OldNodeNumber,   1,        GetDate(),  @LastUpdatedBy) '+
        '           END ' +

             -- DO NOT CREATE ROWCHANGE RECORDS FOR RESELLER NODES
        '       ELSE IF @Kind <> @ResellerKind BEGIN               '+
        '           INSERT INTO RowChanges         '+
        '                   (RowID, TableID, Code, PublishCount, Action,  LocalKey, RecordVersion, LastUpdate, LastUpdatedBy)  '+
