        '           END ' +

        '       FETCH FROM CR INTO @ID, @NodeNumber, @Kind, @LastUpdatedBy, @OldNodeNumber  '+
        '       END                                            '+

        '    CLOSE CR                                          '+
        '    DEALLOCATE CR                                     '+
        '    SET nocount OFF                                   '+
        '    END                                               '

        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END

