    IF dbo.GTSIsTrigger('trUserProfilesRowChangesUpdate') = 1 BEGIN
        SET @SQL = 'DROP TRIGGER dbo.trUserProfilesRowChangesUpdate'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END

    IF @Error = 0 BEGIN
        SET @SQL =
        'CREATE TRIGGER dbo.trUserProfilesRowChangesUpdate ON UserProfiles FOR UPDATE AS BEGIN  '+
        '    SET nocount ON  '+

        '    DECLARE CR CURSOR FOR '+
        '        SELECT UserProfileID, LastUpdatedBy FROM INSERTED '+

        '    DECLARE                            '+
        '        @ID               int,         '+
        '        @LastUpdatedBy    varchar(20)  '+

        '    OPEN CR                            '+
        '    FETCH FROM CR INTO @ID, @LastUpdatedBy  '+
        '    WHILE( @@FETCH_STATUS = 0 ) BEGIN       '+

               -- Do not download Reseller UserProfiles
        '      IF ((SELECT Count(ProfilePrivID) FROM ProfilePrivs WHERE (UserProfileID = @ID) AND ((PrivNumber between 1006 and 1019) or (PrivNumber = 1032) or (PrivNumber between 1185 and 1186))) = 0) BEGIN '+

        '        INSERT INTO RowChanges         '+
        '                    (RowID, TableID, Code, PublishCount, Action,  LocalKey, RecordVersion, LastUpdate, LastUpdatedBy)  '+
        '            VALUES (@ID,   7,       636,  0,            3,       @ID,   1,        GetDate(),  @LastUpdatedBy) '+
        '        END ' +

        '      FETCH FROM CR INTO @ID, @LastUpdatedBy  '+
        '      END  '+

        '    CLOSE CR                   '+
        '    DEALLOCATE CR              '+
        '    SET nocount OFF            '+
        '    END                        '

        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END

    /*    Stop the script if an error has occurred    */
