    PRINT '    ' + 'Creating GTS_CreateCDMRowChangeTrigger...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_CreateCDMRowChangeTrigger') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_CreateCDMRowChangeTrigger'
        EXEC (@SQL)
        END

    SET @SQL =
    'CREATE PROCEDURE dbo.GTS_CreateCDMRowChangeTrigger(@TableName sysname, @CentralKeyColumn sysname, @LocalKeyColumn sysname, @TableID int, @CodeID int, @Action nvarchar(20), @RunMode int, @Error int OUTPUT) AS BEGIN
        DECLARE
            @SQLText nvarchar(max),
            @TriggerName sysname,
            @VTable sysname,
            @ActionId int

        SET @VTable = ''inserted''
        IF @LocalKeyColumn = '''' SET @LocalKeyColumn = @CentralKeyColumn

        IF @Action = ''Insert'' SET @ActionId = 1
        ELSE IF @Action = ''Delete'' BEGIN
            SET @ActionId = 2
            SET @VTable = ''deleted''
            END
        ELSE SET @ActionId = 3

        SET @TriggerName = ''tr'' + @TableName + ''RowChanges'' + @Action

        PRINT ''Dropping trigger '' + @TriggerName
        IF dbo.GTSIsTrigger(@TriggerName) = 1 BEGIN
            SET @SQLText = ''DROP TRIGGER '' + @TriggerName
            EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQLText
            END

        SET @SQLText =
            ''CREATE TRIGGER dbo.'' + @TriggerName + '' ON '' + @TableName +'' FOR '' + @Action + '' AS BEGIN  '' +
            ''    SET nocount ON  '' +

            ''    DECLARE CR CURSOR FOR  '' +
            ''        SELECT '' + @CentralKeyColumn + '', '' + @LocalKeyColumn +  '', LastUpdatedBy FROM '' + @VTable +

            ''    DECLARE                            '' +
            ''        @ID               int,         '' +
            ''        @LocalID          int,         '' +
            ''        @LastUpdatedBy    varchar(20)  '' +
            ''    OPEN CR                            '' +
            ''    FETCH FROM CR INTO @ID, @LocalID, @LastUpdatedBy  '' +
            ''    WHILE( @@FETCH_STATUS = 0 ) BEGIN  '' +
            ''        INSERT INTO RowChanges         '' +
            ''                    (RowID, TableID, Code, PublishCount, Action,  LocalKey, RecordVersion, LastUpdate, LastUpdatedBy)  '' +
            ''            VALUES (@ID,   '' + CAST(@TableID as nvarchar) + '', '' + CAST(@CodeID as nvarchar) + '', 0, '' + CAST(@ActionId as nvarchar) + '', @LocalID, 1, GetDate(), @LastUpdatedBy) '' +
            ''        FETCH FROM CR INTO @ID, @LocalID, @LastUpdatedBy '' +
            ''        END                                          '' +
            ''    CLOSE CR           '' +
            ''    DEALLOCATE CR      '' +
            ''    SET nocount OFF    '' +
            ''    END                ''

        PRINT ''Adding '' + @Action + '' Central DB Trigger to '' + @TableName
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQLText
        END'
    EXEC (@SQL)
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, ''
        RETURN
        END

    PRINT '    ' + 'Creating GTS_CreateCDMRowChangeTriggers...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTS_CreateCDMRowChangeTriggers') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_CreateCDMRowChangeTriggers'
        EXEC (@SQL)
        END

    SET @SQL =
    'CREATE PROCEDURE dbo.GTS_CreateCDMRowChangeTriggers(@TableName sysname, @CentralKeyColumn sysname, @LocalKeyColumn sysname, @TableID int, @CodeID int, @RunMode int, @Error int OUTPUT) AS BEGIN
        EXEC GTS_CreateCDMRowChangeTrigger @TableName, @CentralKeyColumn, @LocalKeyColumn, @TableID, @CodeID, ''Update'', @RunMode, @Error
        IF @Error <> 0 RETURN
        EXEC GTS_CreateCDMRowChangeTrigger @TableName, @CentralKeyColumn, @LocalKeyColumn, @TableID, @CodeID, ''Insert'', @RunMode, @Error
        IF @Error <> 0 RETURN
        EXEC GTS_CreateCDMRowChangeTrigger @TableName, @CentralKeyColumn, @LocalKeyColumn, @TableID, @CodeID, ''Delete'', @RunMode, @Error
        END'
    EXEC (@SQL)
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, ''
        RETURN
        END
