/*************** LOYALTY STORED PROCEDURES SECTION ****************/
/***************       MOVED TO LOYALTY.SQL        ****************/

/*************** START OF ACCESS CONTROL STORED PROCEDURES SECTION ******************/
IF (@WebStoreDB = 0) and ((@RunMode % 10) = 1) BEGIN -- We do not want to create access control stored procedures for the WebStore database
    PRINT '    ' + 'Creating stored procedure GTSGetJointMembersByPassNo...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSGetJointMembersByPassNo') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTSGetJointMembersByPassNo

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTSGetJointMembersByPassNo]
            @PassNo     Integer,     -- The pass number to look up
            @FacilityID Integer
        /*
        Collects data for the Joint Membership picker view in ACS32
        */
        AS BEGIN
            SET NOCOUNT ON

                  SELECT J.JointMemberID, J.MemberType, J.PrimaryMember, J.Status, J.VisualID, J.ContactID,
                         P.PixelDepth, P.ImageData,
                         C.FirstName, C.MiddleName, C.LastName, C.AgeGroup, C.DOB,
                         R.JointMemberID as AdmittedEarlier
                  FROM JointMembers J (NOLOCK)
                        LEFT OUTER JOIN CustContacts C (NOLOCK)
                                ON (J.ContactID <> 0) AND (J.ContactID = C.CustContactID)
                        LEFT OUTER JOIN Pictures P (NOLOCK)
                                ON (J.PictureID <> 0) AND (J.PictureID = P.PictureID)
                         LEFT OUTER JOIN Reentry R (NOLOCK)
                            ON (R.JointMemberID = J.JointMemberID) AND (R.Facility = @FacilityID)
                  WHERE J.PassNo = @PassNo AND J.Status = 0
            END'
         END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    PRINT '    ' + 'Creating stored procedure GTSGetJointMemberUsage...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSGetJointMemberUsage') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo'))
        DROP PROCEDURE dbo.GTSGetJointMemberUsage

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTSGetJointMemberUsage]
            @VisualID     Varchar(255),
            @UseNo        Int
            /*
            Collects member usage data for the ticket lookup screen.
            Returns rows with Usage Code in [USAGE_SCAN, USAGE_MEMBER] and Usage.Status in [TICKET_VALID, TICKET_FREE_ENTRY]
            */
            AS BEGIN
                SET NOCOUNT ON
                    SELECT
                        MU.AdultQty, MU.ChildQty, MU.GuestQty, MU.JointMemberID, JM.ContactID,
                        JM.MemberType, P.ImageData, JM.PrimaryMember, C.FirstName, C.LastName

                    FROM Usage U (NOLOCK)
                        INNER JOIN MemberUsage MU (NOLOCK)
                            ON (MU.UsageID = U.UsageID)
                        LEFT OUTER JOIN JointMembers JM (NOLOCK)
                            ON (MU.JointMemberID <> 0) AND (JM.JointMemberID = MU.JointMemberID)
                        LEFT OUTER JOIN CustContacts C (NOLOCK)
                            ON (JM.ContactID <> 0) AND (JM.ContactID = C.CustContactID)
                        LEFT OUTER JOIN Pictures P (NOLOCK)
                            ON (JM.PictureID <> 0) AND (P.PictureID = JM.PictureID)

                    WHERE U.VisualID = @VisualID AND U.UseNo = @UseNo AND (U.Code IN (0, 12)) AND (U.Status IN (0, 30))
                    END'
         END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END
    END
/*************** END OF ACCESS CONTROL STORED PROCEDURES SECTION ******************/

/*************** START OF ORDER ENTRY TRIGGERS AND STORED PROCEDURES SECTION ****************/

IF (@WebStoreDB = 0) and ((@RunMode % 10) = 1) BEGIN -- We do not want to create the OE triggers and stored procedures for WebStore database

    PRINT 'Creating GTS_SP_GetOrderDetailJnlTranIDs stored procedure...'

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_SP_GetOrderDetailJnlTranIDs') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_SP_GetOrderDetailJnlTranIDs'
        EXEC (@SQL)
        END

    /*
    This stored procedure loads the JnlTranIDs for all of the ticket issuance
    transactions in an order. It is used to aid in loading of payment information
    for enforcing multi-payment return restrictions.
    */
    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_SP_GetOrderDetailJnlTranIDs] @OrderID int AS BEGIN
            SET NOCOUNT ON

            SELECT JnlTranID FROM
            (
                SELECT MAX(JH.JnlTranID) JnlTranID
                    FROM
                    (
                        SELECT DISTINCT OD.NodeNumber NodeNo, OD.TransactionNumber TransNo
                        FROM OrderLines OL
                            INNER JOIN OrderDetails OD
                            ON OL.OrderLineID = OD.OrderLineID
                        WHERE OL.OrderID = @OrderID
                    ) A
                    INNER JOIN JnlHeaders JH
                        ON JH.NodeNo = A.NodeNo
                        AND JH.TranNo = A.TransNo
                GROUP BY JH.NodeNo, JH.TranNo
             ) AS B

            END'
        END

    PRINT 'Creating GTS_OE_GetQuotedOECreditAmount stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_OE_GetQuotedOECreditAmount') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_OE_GetQuotedOECreditAmount'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_OE_GetQuotedOECreditAmount]
            @AccountID            Int,         -- If non-zero then filter transactions by customer
            @QuotedOECreditAmount Money OUTPUT -- UsedOECreditAmount is calculated by querying the OE transactions for the given account
        AS BEGIN
            SET NOCOUNT ON
            DECLARE @OrderBalance      Money
            DECLARE @InvoiceBalance    Money
            DECLARE @CreditMemoBalance Money

            SET @QuotedOECreditAmount = 0

            SELECT @OrderBalance=IsNull(SUM(Balance), 0) FROM Orders
            WHERE OrderStatus in (1, 2) AND AccountID = @AccountID

            SELECT @InvoiceBalance=IsNull(SUM(ARInvoices.Balance), 0) FROM ARInvoices
            WHERE ARInvoices.AccountID = @AccountID AND ARInvoices.OrderID > 0

            SELECT @CreditMemoBalance=IsNull(SUM(ARCreditMemos.Balance), 0) FROM ARCreditMemos
            WHERE ARCreditMemos.AccountID = @AccountID AND ARCreditMemos.OrderID > 0

            SET @QuotedOECreditAmount = (@OrderBalance + @InvoiceBalance) + @CreditMemoBalance
            END '
        END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END


    PRINT 'Creating GTS_OE_GetAccountBalance stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_OE_GetAccountBalance') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_OE_GetAccountBalance'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_OE_GetAccountBalance]
            @AccountID Int,                   -- If non-zero then filter transactions by customer
            @CreditCheckEnforcementType Int,  -- 0 for Enforcing CreditLimit on add and 1 for Enforcing CreditLimit on issue
            @RequestedAmount Money            -- Amount to be used by the current transaction from available CreditLimit. Logic to check credit accounts for this amount and then returns the remaining balance

        AS BEGIN
            /*
            Use this stored procedure to check if a customer''s Account has enough balance available.
            A result set is always returned back to the caller with enough data to clearly indicate the results of the execution of the stored procedure.
            This stored procedure also contains logic to validate the Account to make sure the account is in the good standing before passing the balance check.
            When an account is not valid the reason for error (ValidationErrorText) is returned back in the result set returned.
            Stored procedure performs the balance check considering the UsingUsedCreditAmount conversion flag. If an account is not converted yet then it
            uses the old style balance check as done in versions prior to Galaxy 4.11.
            */

            SET NOCOUNT ON

            DECLARE @CreditLimit        Money
            DECLARE @DisableCredit      Bit
            DECLARE @CreditHoldFlag     Bit
            DECLARE @CreditStatus       Int
            DECLARE @UsingUsedCreditAmount Bit
            DECLARE @UsedCreditAmount    Money
            DECLARE @UsedOECreditAmount  Money
            DECLARE @UsedPOSCreditAmount Money
            DECLARE @UsedAmount          Money
            DECLARE @RemainingBalance Money
            DECLARE @UnlimitedCredit Bit
            DECLARE @ValidationError Bit
            DECLARE @ValidationErrorText varchar(100)

            SET @RemainingBalance    = 0
            SET @UnlimitedCredit     = 0
            SET @ValidationError     = 0
            SET @ValidationErrorText = ''''

            -- If no account is found with the AccountID of zero then return an error
            SELECT @CreditLimit=IsNull(CreditLimit, 0), @DisableCredit=IsNull(DisableCredit, 0), @CreditHoldFlag=IsNull(CreditHoldFlag, 0), @CreditStatus=IsNull(CreditStatus, 0), @UsingUsedCreditAmount=IsNull(UsingUsedCreditAmount, 0),
                   @UsedCreditAmount=IsNull(UsedCreditAmount, 0), @UsedOECreditAmount=IsNull(UsedOECreditAmount, 0), @UsedPOSCreditAmount=IsNull(UsedPOSCreditAmount, 0)
            FROM ARAccounts WHERE AccountID=@AccountID
            IF @@ROWCOUNT = 0 BEGIN
                SET @ValidationErrorText = ''Could not load the account with ID '' + CONVERT(Varchar, @AccountID) + ''.''
                SET @ValidationError = 1
                SELECT @RemainingBalance as RemainingBalance, @UsedAmount as UsedAmount, @UnlimitedCredit as UnlimitedCredit, @ValidationError as ValidationError, @ValidationErrorText as ValidationErrorText
                RETURN
                END

            IF (@CreditCheckEnforcementType <> 0) and (@CreditCheckEnforcementType <> 1) BEGIN
                SET @ValidationErrorText = ''CreditCheckEnforcementType value '' + CONVERT(Varchar, @CreditCheckEnforcementType) + '' is invalid.''
                SET @ValidationError = 1
                SELECT @RemainingBalance as RemainingBalance, @UsedAmount as UsedAmount, @UnlimitedCredit as UnlimitedCredit, @ValidationError as ValidationError, @ValidationErrorText as ValidationErrorText
                RETURN
                END

            IF @DisableCredit = 1 BEGIN
                SET @ValidationErrorText = ''Credit is disabled for this account.''
                SET @ValidationError = 1
                SELECT @RemainingBalance as RemainingBalance, @UsedAmount as UsedAmount, @UnlimitedCredit as UnlimitedCredit, @ValidationError as ValidationError, @ValidationErrorText as ValidationErrorText
                RETURN
                END

            IF @CreditStatus = 1 BEGIN
                SET @ValidationErrorText = ''Account is on hold.''
                SET @ValidationError = 1
                SELECT @RemainingBalance as RemainingBalance, @UsedAmount as UsedAmount, @UnlimitedCredit as UnlimitedCredit, @ValidationError as ValidationError, @ValidationErrorText as ValidationErrorText
                RETURN
                END

            IF @CreditStatus = 2 BEGIN
                SET @ValidationErrorText = ''Account is frozen.''
                SET @ValidationError = 1
                SELECT @RemainingBalance as RemainingBalance, @UsedAmount as UsedAmount, @UnlimitedCredit as UnlimitedCredit, @ValidationError as ValidationError, @ValidationErrorText as ValidationErrorText
                RETURN
                END

            -- Check if this account is already converted to use UsedCreditAmount. If not then do the credit check the old way
            IF @UsingUsedCreditAmount = 0 BEGIN
                -- Set RequestedAmount to zero when Enforcing CreditCheck On Issue
                IF @CreditCheckEnforcementType = 1
                    SET @RequestedAmount = 0
                EXEC GTS_OE_GetQuotedOECreditAmount @AccountID, @UsedAmount OUTPUT
                END
            ELSE BEGIN
                -- Enforcing CreditCheck On Add
                IF @CreditCheckEnforcementType = 0
                    SET @UsedAmount = @UsedCreditAmount + @UsedPOSCreditAmount
                -- Enforcing CreditCheck On Issue
                ELSE IF @CreditCheckEnforcementType = 1
                    SET @UsedAmount = @UsedOECreditAmount + @UsedPOSCreditAmount
                END

            -- If CreditLimit is unlimited (=0) then no need to continue further just return the UnlimitedCredit bit with UsedAmount as it is needed in Galaxy
            -- to show how much is actually used even when account has unlimited credit
            IF @CreditLimit = 0 BEGIN
                SET @UnlimitedCredit = 1
                SELECT @RemainingBalance as RemainingBalance, @UsedAmount as UsedAmount, @UnlimitedCredit as UnlimitedCredit, @ValidationError as ValidationError, @ValidationErrorText as ValidationErrorText
                RETURN
                END

            SET @RemainingBalance = @CreditLimit - @UsedAmount
            IF @RemainingBalance < @RequestedAmount BEGIN
                SET @ValidationErrorText = ''Balance('' + CONVERT(Varchar, (@UsedAmount + @RequestedAmount)) + '') exceeds credit limit('' + CONVERT(Varchar, @CreditLimit) + '').''
                SET @ValidationError = 1
                SET @RemainingBalance = @CreditLimit - @UsedAmount -- Return the actual Remaining Balance of the account NOT including the RequestedAmount
                SELECT @RemainingBalance as RemainingBalance, @UsedAmount as UsedAmount, @UnlimitedCredit as UnlimitedCredit, @ValidationError as ValidationError, @ValidationErrorText as ValidationErrorText
                RETURN
                END

            SELECT @RemainingBalance as RemainingBalance, @UsedAmount as UsedAmount, @UnlimitedCredit as UnlimitedCredit, @ValidationError as ValidationError, @ValidationErrorText as ValidationErrorText
            END '
        END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    PRINT 'Creating GTS_OE_UpdateJnlUsedCreditAmountOnAccount stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_OE_UpdateJnlUsedCreditAmountOnAccount') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_OE_UpdateJnlUsedCreditAmountOnAccount'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_OE_UpdateJnlUsedCreditAmountOnAccount]
            @JnlTranID      Int,     -- JnlTranID of the POS Customer or an OE transaction
            @AuxtableID     Int,     -- AuxTableID from the payment record in JnlDetails table. Used to get the JnlPayment record
            @Amount         Money,   -- Amount from the payment record in JnlDetails table
            @LastUpdatedBy  varchar(20) -- LastUpdatedBy, indicates which trigger is updating the account
        AS BEGIN
        	/*
        	Updates the UsedOECreditLimit or UsedPOSCreditAmount column to add the delta of the NewBalance and the OldBalance on the account with the given AccountID.
        	- If the trasaction is a POS Customer transaction paid with a CreditFOP then UsedPOSCreditAmount column is updated.
        	- If the trasaction is an OE transaction involving a CreditFOP then UsedOECreditAmount column is updated.
        	*/
            SET NOCOUNT ON
            DECLARE @FOPCode       Int
            DECLARE @AccountID     Int
            DECLARE @CustomerID    Int
            DECLARE @IsOETransaction  Bit
            DECLARE @IsPOSTransaction Bit
            DECLARE @IsCreditFOP      Bit
            DECLARE @CurrentUsedOECreditAmount money
            DECLARE @CurrentUsedPOSCreditAmount money

            SET @FOPCode = 0
            SET @IsCreditFOP = 0
            SELECT @FOPCode=IsNull(Fop, 0) FROM JnlPayments WHERE JnlPaymentID=@AuxTableID
        	-- Query below sets the IsCreditFOP flag if the given @FOPCode is either OE CreditFOP, or OE Invoice FOP or OE Credit Memo FOP
            SELECT @IsCreditFOP = 1 FROM ConfigurationOptions
                WHERE Code IN (493 /*CC_CODE_CHARGE_ACCOUNT_FOP*/, 564 /*CC_CODE_INVOICE_FOP*/, 569 /*CC_CODE_REFUND_FOP*/, 834 /*CC_CODE_RESELLER_CHARGE_ACCOUNT_FOP*/) AND IsNull(CONVERT(int, Value), 0) > 0 AND
                Value = IsNull(CONVERT(varchar, @FOPCode), '''')

            -- Query below sets the IsCreditFOP flag if the given @FOPCode has an Endorsement Edit of Charge Account
            SELECT @IsCreditFOP = 1 FROM FOPs
                WHERE EndorseEdit = 10 /*Charge Account*/ AND FOPcode = IsNull (CONVERT(varchar,@FOPCode),'''')

            --If this is a Credit FOP then we need to first find the AccountID & type of transaction and then update the UsedOECreditLimit OR UsedPOSCreditLimit fields accordingly.
            IF @IsCreditFOP = 1 BEGIN
                SET @IsOETransaction = 0
                -- First check if this is a normal OE transaction (a transaction that contains an order record)
            	SELECT @CustomerID=J1.AuxTableID, @IsOETransaction=1 FROM JnlDetails J1
              	WHERE J1.JnlTranID = @JnlTranID AND J1.JnlCodeID = 24 AND
            	J1.JnlTranID IN (SELECT DISTINCT JnlTranID FROM JnlDetails J2 WHERE J2.JnlTranID = @JnlTranID AND J2.JnlCodeID = 37)

            	/*
            	Next check is to see if this is a payment transaction to pay an invoice that contains orders.
            	- Invoice payment transactions with an order record in the journal are considered OETransactions and they should go into the UsedOECreditAmount bucket
            	- Invoice payment transactions without an order record in the journal are considered POSTransactions and they should go into the UsedPOSCreditAmount bucket
            	*/
            	IF @IsOETransaction = 0 BEGIN
            	    SELECT @CustomerID=J1.AuxTableID, @IsOETransaction=1 FROM JnlDetails J1
              	    WHERE J1.JnlTranID = @JnlTranID AND J1.JnlCodeID = 24 AND
            	    J1.JnlTranID IN (SELECT DISTINCT JnlTranID FROM JnlDetails J2 WHERE J2.JnlTranID = @JnlTranID AND J2.JnlCodeID = 40 and EXISTS (SELECT ARInvoiceOrderID FROM ARInvoiceOrders WHERE InvoiceID = J2.AuxTableID))
            	    END

            	IF @IsOETransaction = 1 BEGIN
            	    SELECT @AccountID=A.AccountID, @CurrentUsedOECreditAmount = IsNull(A.UsedOECreditAmount, 0), @CurrentUsedPOSCreditAmount = IsNull(A.UsedPOSCreditAmount, 0) FROM Customers C, ARAccounts A WHERE C.CustomerID = @CustomerID AND C.AccountID = A.AccountID AND A.UsingUsedCreditAmount = 1
                    IF IsNull(@AccountID, 0) > 0 BEGIN
                        UPDATE ARAccounts
                            SET UsedOECreditAmount = IsNull(UsedOECreditAmount, 0) + @Amount, RecordVersion = RecordVersion + 1, LastUpdate = GetDate(), LastUpdatedBy = @LastUpdatedBy
                            WHERE AccountID = @AccountID
                        INSERT INTO OECreditAccountUpdateLog (JnlTranID, JnlPaymentID, AccountID, FOPID, TransactionKind, PaymentAmount, CurrentUsedOECreditAmount, NewUsedOECreditAmount, CurrentUsedPOSCreditAmount, NewUsedPOSCreditAmount, LogDateTime)
                               VALUES (@JnlTranID, @AuxTableID, @AccountID, @FOPCode, 0 /* OE */, @Amount, @CurrentUsedOECreditAmount, @CurrentUsedOECreditAmount + @Amount, @CurrentUsedPOSCreditAmount, @CurrentUsedPOSCreditAmount, GetDate())
                        END
                    END
            	ELSE BEGIN
            	    SET @IsPOSTransaction = 0
            	    SELECT @CustomerID=J1.AuxTableID, @IsPOSTransaction=1 FROM JnlDetails J1
            	    WHERE J1.JnlTranID = @JnlTranID AND J1.JnlCodeID = 24 AND
            	    J1.JnlTranID NOT IN (SELECT DISTINCT JnlTranID FROM JnlDetails J2 WHERE J2.JnlTranID = @JnlTranID AND J2.JnlCodeID = 37)

            	    IF @IsPOSTransaction = 1 BEGIN
            	        SELECT @AccountID=A.AccountID, @CurrentUsedOECreditAmount = IsNull(A.UsedOECreditAmount, 0), @CurrentUsedPOSCreditAmount = IsNull(A.UsedPOSCreditAmount, 0) FROM Customers C, ARAccounts A WHERE C.CustomerID = @CustomerID AND C.AccountID = A.AccountID AND A.UsingUsedCreditAmount = 1
            	    	IF IsNull(@AccountID, 0) > 0 BEGIN
                            UPDATE ARAccounts
                                SET UsedPOSCreditAmount=IsNull(UsedPOSCreditAmount, 0) + @Amount, RecordVersion = RecordVersion + 1, LastUpdate = GetDate(), LastUpdatedBy = @LastUpdatedBy
                                WHERE AccountID=@AccountID
                            INSERT INTO OECreditAccountUpdateLog (JnlTranID, JnlPaymentID, AccountID, FOPID, TransactionKind, PaymentAmount, CurrentUsedOECreditAmount, NewUsedOECreditAmount, CurrentUsedPOSCreditAmount, NewUsedPOSCreditAmount, LogDateTime)
                                   VALUES (@JnlTranID, @AuxTableID, @AccountID, @FOPCode, 1 /* POS */, @Amount, @CurrentUsedOECreditAmount, @CurrentUsedOECreditAmount, @CurrentUsedPOSCreditAmount, @CurrentUsedPOSCreditAmount + @Amount, GetDate())
                            END
                        END
            	    END
            	END
            SET NOCOUNT OFF
            END '
        END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    PRINT 'Creating GTS_OE_GetUsedOECreditAmount stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_OE_GetUsedOECreditAmount') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_OE_GetUsedOECreditAmount'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
		PRINT 'Creating GTS_OE_GetUsedOECreditAmount stored procedure...'
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_OE_GetUsedOECreditAmount]
            @AccountID Int,                  -- If non-zero then filter transactions by account
            @UsedOECreditAmount Money OUT,   -- UsedOECreditAmount is calculated by querying the OE transactions including Credit FOP as a payment
            @IncludeFOPs varchar(500) = '''' -- Comma-delimited list of FOPs to include along with defined credit FOPs
            /*
            Returns the UsedOECreditAmount for a credit account in Galaxy.  To find the UsedOECreditAmount this stored procedure
            first looks up all journal transactions for all orders associated to the given account with a status of Open or Quote and then
            the amount charged to the Credit FOP for each of these transactions is added and returned in the UsedOECreditAmount parameter.
            */
        AS BEGIN
            SET NOCOUNT ON;
			DECLARE @FOPs varchar(100)
			DECLARE @NewSQL nvarchar(max)

            DECLARE @CreditFOPs TABLE (ID int)
            IF @IncludeFOPs <> '''' INSERT INTO @CreditFOPs SELECT ID = ValueElement FROM GTSSplitStringByDelimeter(@IncludeFOPs, '','')

            INSERT INTO @CreditFOPs SELECT case WHEN Value = 0 THEN -1 ELSE ISNULL(Convert(Int, Value), -1) END AS CreditFOP FROM ConfigurationOptions
            WHERE Code IN (493 /*CC_CODE_CHARGE_ACCOUNT_FOP*/, 564 /*CC_CODE_INVOICE_FOP*/, 569 /*CC_CODE_REFUND_FOP*/, 834 /*CC_CODE_RESELLER_CHARGE_ACCOUNT_FOP*/);

			SELECT @FOPs = coalesce(@FOPs + '','', '''') +  convert(varchar(10), ID) FROM @CreditFOPs

			SET @NewSQL = ''WITH
                  CreditTransactions AS (
                    SELECT JnlPaymentID
                    FROM JnlPayments
                    WHERE JnlPayments.FOP IN ('' + @FOPs + '')),

                  OrderOrInvoiceTransactions AS (
                    SELECT DISTINCT JnlTranID
                    FROM JnlDetails
                    WHERE JnlCodeID = 37
                       OR (JnlCodeID = 40 AND ((EXISTS (SELECT ARInvoiceOrderID FROM ARInvoiceOrders WHERE ARInvoiceOrders.InvoiceID = JnlDetails.AuxTableID)) OR
                                               (JnlDetails.AuxTableID = 0)))),

                  OECreditTransactions AS (
                    SELECT
                      JnlDetails.JnlTranID,
                      Customers.AccountID
                    FROM
                      JnlDetails
                      INNER JOIN
                      Customers
                    ON  JnlDetails.JnlCodeID = 24
                    AND JnlDetails.AuxTableID = Customers.CustomerID
                    AND Customers.AccountID = '' + CAST(@AccountID as varchar) + ''
                    AND JnlTranID IN (SELECT JnlTranID FROM OrderOrInvoiceTransactions)),

                  CreditPayments AS (
                    SELECT
                      OECreditTransactions.AccountID,
                      JnlDetails.Amount,
                      JnlDetails.JnlTranID
                    FROM
                      JnlDetails
                      INNER JOIN
                      OECreditTransactions
                    ON  JnlDetails.JnlCodeID = 532
                    AND JnlDetails.JnlTranID = OECreditTransactions.JnlTranID
                    AND JnlDetails.AuxTableID IN (SELECT JnlPaymentID FROM CreditTransactions)),


                  Totals AS (
                    SELECT
                      AccountID,
                      SUM(Amount) AS Amount
                    FROM CreditPayments
                    GROUP BY AccountID)

                  SELECT TOP 1 @UsedOECreditAmount = Amount FROM Totals''
			EXEC sp_executesql @NewSQL, N''@UsedOECreditAmount money OUTPUT'', @UsedOECreditAmount OUTPUT
            END '
		END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END


    PRINT 'Creating GTS_OE_GetUsedPOSCreditAmount stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_OE_GetUsedPOSCreditAmount') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_OE_GetUsedPOSCreditAmount'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_OE_GetUsedPOSCreditAmount]
            @AccountID Int,                  -- If non-zero then filter transactions by account
            @UsedPOSCreditAmount Money OUT,  -- UsedPOSCreditAmount is calculated by querying the POS customer transactions paid with a Credit FOP
            @IncludeFOPs varchar(500) = '''' -- Comma-delimited list of FOPs to include along with defined credit FOPs
            /*
            Returns the UsedPOSCreditAmount for a credit account in Galaxy.  To find the UsedPOSCreditAmount this stored procedure
            first looks up all POS customer journal transactions associated to the given account and then the amount charged to the
            Credit FOP for each of these transactions is added and returned in the UsedPOSCreditAmount parameter.
            */
        AS BEGIN
            SET NOCOUNT ON
            DECLARE @CustomerIDs TABLE(CustomerID Int)
            DECLARE @JnlTranID           Int
            DECLARE @JnlPaymentID        Int
            DECLARE @FOPCode             Int
            DECLARE @CreditFOPs TABLE (ID int)

            SET @UsedPOSCreditAmount = 0

            -- Populate temporary CreditFOPs table with passed-in @IncludeFOPs
            IF @IncludeFOPs <> '''' INSERT INTO @CreditFOPs SELECT ID = ValueElement FROM GTSSplitStringByDelimeter(@IncludeFOPs, '','')

            -- Continue populating temporary CreditFOPs table with applicable credit FOPs defined in central config
            INSERT INTO @CreditFOPs SELECT case WHEN value = 0 THEN -1 ELSE ISNULL(Convert(Int, Value), -1) END AS CreditFOP FROM ConfigurationOptions
            WHERE Code IN (493 /*CC_CODE_CHARGE_ACCOUNT_FOP*/, 564 /*CC_CODE_INVOICE_FOP*/, 569 /*CC_CODE_REFUND_FOP*/, 834 /*CC_CODE_RESELLER_CHARGE_ACCOUNT_FOP*/)

            -- Populate the CustomerIDs temporary table with IDs of the Customer records that are associated to the given AccountID
            INSERT INTO @CustomerIDs SELECT CustomerID FROM Customers WHERE AccountID=@AccountID

            DECLARE JnlDetailIterator CURSOR FOR
                SELECT DISTINCT J1.JnlTranID FROM JnlDetails J1
                WHERE J1.JnlCodeID = 24 AND EXISTS(SELECT CustomerID FROM @CustomerIDs WHERE CustomerID=J1.AuxTableID) AND
                      (J1.JnlTranID NOT IN (SELECT DISTINCT JnlTranID FROM JnlDetails J2 WHERE J2.JnlTranID = J1.JnlTranID AND J2.JnlCodeID = 37)) AND
                      (J1.JnlTranID NOT IN (SELECT DISTINCT JnlTranID FROM JnlDetails J2 WHERE J2.JnlTranID = J1.JnlTranID AND J2.JnlCodeID = 40 and
                          ((EXISTS (SELECT ARInvoiceOrderID FROM ARInvoiceOrders WHERE InvoiceID = J2.AuxTableID)) OR (J2.AuxTableID = 0))))

            -- Execute cursor query and then loop thru each POS customer transaction to get the UsedPOSCreditAmount if the Credit FOP was used as a Payment
            OPEN JnlDetailIterator
            FETCH NEXT FROM JnlDetailIterator INTO @JnlTranID
            WHILE (@@FETCH_STATUS = 0) BEGIN
                -- Loop thru all payments and add the amount of payments with Credit FOP
                DECLARE JnlPaymentIterator CURSOR FOR SELECT JnlPaymentID, Fop FROM JnlPayments WHERE JnlTranID = @JnlTranID
                OPEN JnlPaymentIterator
                FETCH NEXT FROM JnlPaymentIterator INTO @JnlPaymentID, @FOPCode
                WHILE(@@FETCH_STATUS = 0) BEGIN
		            IF EXISTS(select ID from @CreditFOPs where ID = @FOPCode) BEGIN
                        SELECT @UsedPOSCreditAmount=@UsedPOSCreditAmount + Amount FROM JnlDetails WHERE JnlTranID = @JnlTranID AND JnlCodeID = 532 AND AuxTableID = @JnlPaymentID
                        END
                    FETCH NEXT FROM JnlPaymentIterator INTO @JnlPaymentID, @FOPCode
                    END
                CLOSE JnlPaymentIterator
                DEALLOCATE JnlPaymentIterator
                FETCH NEXT FROM JnlDetailIterator INTO @JnlTranID
                END
            CLOSE JnlDetailIterator
            DEALLOCATE JnlDetailIterator
            END '
        END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END


    PRINT 'Creating GTS_OE_ConvertAccountToUseUsedCreditAmount stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_OE_ConvertAccountToUseUsedCreditAmount') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_OE_ConvertAccountToUseUsedCreditAmount'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_OE_ConvertAccountToUseUsedCreditAmount]
            @ConversionType Int,
            /*ConversionType of
              0 - If UsingUsedCreditAmount bit is set on account then do not convert account unless @ForceConversion is set
                  If UsingUsedCreditAmount bit is not set then update UsedCreditAmount, UsedOECreditAmount and UsedPOSCreditAmount for both OE and POS transactions.

              1 - If UsingUsedCreditAmount bit is set on account then do not convert account unless @ForceConversion is set.
                  If UsingUsedCreditAmount bit is not set then only update UsedCreditAmount & UsedOEAmount for OE transactions only. This is to avoid double dipping for SDZ scenario.

              2 - If UsingUsedCreditAmount bit is set on account then do not convert account unless @ForceConversion is set.
                  If UsingUsedCreditAmount bit is not set then only update UsedPOSAmount for POS transactions only. This is for UO scenario.
            */
            @AccountID Int,    -- If non-zero then conversion is only done for this account
            @ConvertAlreadyConverted int = 1,  -- If 1 then Convert an account even if it is already converted. If 0 then only convert the account if it is not already converted
            @IncludeFOPs varchar(500) = ''''   -- Comma-delimited list of FOPs to include along with defined credit FOPs

        AS BEGIN
            /*
            Use this stored procedure to convert an account to use new style credit limit checking. Using the given parameters this
            stored procedure loops thru the accounts in ARAccounts table and populates the UsedCreditAmount, UsedOECreditAmount, and
            UsedPOSCreditAmount columns with proper values by executing queries on Orders, ARInvoices, ARCreditMemos, and journal tables.
            */

            SET NOCOUNT ON  -- Turn off NOCOUNT option so number of rows affected by every select does not get reported

            DECLARE @UsingUsedCreditAmount Bit

            DECLARE @UsedCreditAmount     Money
            DECLARE @QuotedOECreditAmount Money
            DECLARE @UsedOECreditAmount   Money
            DECLARE @UsedPOSCreditAmount  Money

            DECLARE @AccountsUpdated Int
            DECLARE @MsgText         varchar(1000)
            DECLARE @Results TABLE(FieldName varchar(100), AccountID Int, MsgText varchar(1000))

            SET @AccountsUpdated = 0

            DECLARE AccountIterator CURSOR FOR SELECT AccountID, ISNULL(UsingUsedCreditAmount,0) FROM ARAccounts WHERE (@AccountID = 0) OR ((@AccountID > 0) AND AccountID = @AccountID)

            OPEN AccountIterator
            FETCH NEXT FROM AccountIterator INTO @AccountID, @UsingUsedCreditAmount
            WHILE (@@FETCH_STATUS = 0) BEGIN
                SET @UsedCreditAmount = 0
                SET @QuotedOECreditAmount = 0
                SET @UsedOECreditAmount = 0
                SET @UsedPOSCreditAmount = 0

                IF (@ConvertAlreadyConverted = 1) OR (@UsingUsedCreditAmount = 0) BEGIN
                    -- Update all fields UsedCreditAmount, UsedOECreditAmount and UsedPOSCreditAmount for both OE and POS transactions.
                    IF @ConversionType = 0 BEGIN
                        EXEC GTS_OE_GetQuotedOECreditAmount @AccountID, @QuotedOECreditAmount OUTPUT
                        EXEC GTS_OE_GetUsedOECreditAmount   @AccountID, @UsedOECreditAmount   OUTPUT, @IncludeFOPs
                        EXEC GTS_OE_GetUsedPOSCreditAmount  @AccountID, @UsedPOSCreditAmount  OUTPUT, @IncludeFOPs

                        SET @UsedCreditAmount = @QuotedOECreditAmount

                        -- Update the account record
                        UPDATE ARAccounts SET UsedCreditAmount      = @UsedCreditAmount,
                                              UsedOECreditAmount    = @UsedOECreditAmount,
                                              UsedPOSCreditAmount   = @UsedPOSCreditAmount,
                                              UsingUsedCreditAmount = 1,
                                              RecordVersion         = RecordVersion + 1,
                                              LastUpdate            = GETDATE(),
                                              LastUpdatedBy         = ''ConvAcctSP''
                        WHERE AccountID = @AccountID
                        SET @AccountsUpdated = @AccountsUpdated + 1

                        -- Add a row to the Results temp table to log the updated values for this account
                        SET @MsgText = ''Updated fields - UsedCreditAmount: '' + CONVERT(Varchar, @UsedCreditAmount) + '', UsedOECreditAmount: '' + CONVERT(Varchar, @UsedOECreditAmount) + '', UsedPOSCreditAmount: '' + CONVERT(Varchar, @UsedPOSCreditAmount)
                        END

                    -- Update OE fields UsedCreditAmount, and UsedOECreditAmount for OE transactions only. This is to avoid double dipping for SDZ scenario.
                    IF @ConversionType = 1 BEGIN
                        EXEC GTS_OE_GetQuotedOECreditAmount @AccountID, @QuotedOECreditAmount OUTPUT
                        EXEC GTS_OE_GetUsedOECreditAmount   @AccountID, @UsedOECreditAmount   OUTPUT, @IncludeFOPs

                        SET @UsedCreditAmount = @QuotedOECreditAmount

                        -- Update the account record
                        UPDATE ARAccounts SET UsedCreditAmount      = @UsedCreditAmount,
                                              UsedOECreditAmount    = @UsedOECreditAmount,
                                              UsingUsedCreditAmount = 1,
                                              RecordVersion         = RecordVersion + 1,
                                              LastUpdate            = GETDATE(),
                                              LastUpdatedBy         = ''ConvAcctSP''
                        WHERE AccountID = @AccountID
                        SET @AccountsUpdated = @AccountsUpdated + 1

                        -- Add a row to the Results temp table to log the updated values for this account
                        SET @MsgText = ''Updated fields - UsedCreditAmount: '' + CONVERT(Varchar, @UsedCreditAmount) + '', UsedOECreditAmount: '' + CONVERT(Varchar, @UsedOECreditAmount)
                        END

                    -- Update OE fields UsedCreditAmount, and UsedOECreditAmount for OE transactions only. This is to avoid double dipping for SDZ scenario.
                    IF @ConversionType = 2 BEGIN
                        EXEC GTS_OE_GetUsedPOSCreditAmount  @AccountID, @UsedPOSCreditAmount  OUTPUT, @IncludeFOPs

                        -- Update the account record
                        UPDATE ARAccounts SET UsedPOSCreditAmount   = @UsedPOSCreditAmount,
                                              UsingUsedCreditAmount = 1,
                                              RecordVersion         = RecordVersion + 1,
                                              LastUpdate            = GETDATE(),
                                              LastUpdatedBy         = ''ConvAcctSP''
                        WHERE AccountID = @AccountID
                        SET @AccountsUpdated = @AccountsUpdated + 1

                        -- Add a row to the Results temp table to log the updated values for this account
                        SET @MsgText = ''Updated fields -  UsedPOSCreditAmount: '' + CONVERT(Varchar, @UsedPOSCreditAmount)
                        END
                    INSERT INTO @Results Values(''Account '' + CONVERT(Varchar, @AccountID) + '' updated.'', @AccountID, @MsgText)
                    END
                FETCH NEXT FROM AccountIterator INTO @AccountID, @UsingUsedCreditAmount
                END
            CLOSE AccountIterator
            DEALLOCATE AccountIterator
            INSERT INTO @Results Values(''Total Accounts Updated: '' + CONVERT(Varchar, @AccountsUpdated), 0, '''')

            SET NOCOUNT OFF  -- Turn on the NOCOUNT option so number of rows affected by final select is returned as part of result set
            SELECT FieldName, AccountID, MsgText FROM (SELECT * FROM @Results) Res
            END '
        END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    PRINT 'Creating GTS_MWS_AgencyReports_UpsellByUserReport stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_MWS_AgencyReports_UpsellByUserReport') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_MWS_AgencyReports_UpsellByUserReport'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_MWS_AgencyReports_UpsellByUserReport](
              @SearchFromDateTime datetime,
              @SearchThruDateTime datetime,
              @UseAgency Char,
              @AgencyID int,
              @UseCompany Char,
              @CompanyID int,
              @UseUserID Char,
              @UserID int
              )

          AS
          BEGIN
          SET NOCOUNT ON

          DECLARE
              @SearchFromDate DateTime,
              @SearchThruDate DateTime

          SELECT
              @SearchFromDate = DateAdd(day, 0, DateDiff(day, 0, @SearchFromDateTime)),
              @SearchThruDate = DateAdd(day, 0, DateDiff(day, 0, @SearchThruDateTime))

          DECLARE
              @JnlHeaders TABLE (
		              UserID int,
                  JnlTranID int,
				          TransUpsellCancelled bit
                  )

              INSERT INTO @JnlHeaders
              SELECT
                  UserID,
                  JnlTranID,
				          TransUpsellCancelled
              FROM
              (
                  SELECT
                      UserID,
                      JnlTranID,
				              TransUpsellCancelled,
                  CASE WHEN Adjustment = 0
                      THEN FiscalDate + (TranDate - DateAdd(day,0, DateDiff(day, 0, TranDate)))
                      ELSE FiscalDate + (IsNull(AdjustmentTime, 0) - DateAdd(day,0, DateDiff(day, 0, IsNull(AdjustmentTime, 0))))
                      END TranDateTime
                  FROM JnlHeaders
                  WHERE FiscalDate BETWEEN @SearchFromDate AND @SearchThruDate
                  AND ((@UseAgency = ''N'') OR
                      ((@UseAgency = ''Y'') AND (Agency/1000 = @AgencyID)))
				          AND TranKind = 1
              ) jh
              WHERE jh.TranDateTime BETWEEN @SearchFromDateTime AND @SearchThruDateTime

          /* Get all of the Upsell JnlTickets and JnlItems for specified date range, company, and agency */
          DECLARE
              crUpsellReportData CURSOR FOR
          SELECT
              UpsellReportData.UserID,
              JnlTranID,
		          TransUpsellCancelled,
              UpsellStatus,
              UpsellPriceDifference,
			        U.Name
          FROM
          (
              /* JnlTickets */
              SELECT
                  CASE WHEN t.UpsellUserID > 0 THEN t.UpsellUserID
					            ELSE h.UserID END UserID,
                  h.JnlTranID,
				          h.TransUpsellCancelled,
                  t.UpsellStatus,
                  t.UpsellPriceDifference

              FROM @JnlHeaders h
              INNER JOIN JnlDetails d ON h.JnlTranID = d.JnlTranID
              INNER JOIN JnlTickets t ON d.JnlDetailID = t.JnlDetailID
              AND ((@UseCompany = ''N'') OR
                  ((@UseCompany = ''Y'') AND (convert(BigInt, d.AccountID)/100000000 = @CompanyID)))

              UNION ALL

              /* JnlItems */
              SELECT
                  CASE WHEN i.UpsellUserID > 0 THEN i.UpsellUserID
					            ELSE h.UserID END UserID,
                  h.JnlTranID,
				          h.TransUpsellCancelled,
                  i.UpsellStatus,
                  i.UpsellPriceDifference

              FROM @JnlHeaders h
              INNER JOIN JnlDetails d ON h.JnlTranID = d.JnlTranID
              INNER JOIN JnlItems i ON d.JnlTranID = i.JnlTranID
              AND ((d.JnlCodeID = 102) OR (d.JnlCodeID = 104))
              AND d.AuxTableID = i.JnlItemID
			        AND ((@UseCompany = ''N'') OR
                  ((@UseCompany = ''Y'') AND (convert(BigInt, d.AccountID)/100000000 = @CompanyID)))

              UNION ALL

              /* JnlPackages */
              SELECT
                  CASE WHEN p.UpsellUserID > 0 THEN p.UpsellUserID
					            ELSE h.UserID END UserID,
                  h.JnlTranID,
				          h.TransUpsellCancelled,
                  p.UpsellStatus,
                  p.UpsellPriceDifference

		          FROM @JnlHeaders h
              INNER JOIN JnlDetails d ON h.JnlTranID = d.JnlTranID
              INNER JOIN JnlPackages p ON d.AuxTableID = p.JnlPackageID
              AND d.JnlCodeID = 97
              AND ((@UseCompany = ''N'') OR
                  ((@UseCompany = ''Y'') AND (convert(BigInt, d.AccountID)/100000000 = @CompanyID)))

          ) UpsellReportData
		      LEFT OUTER JOIN GxUsers U ON U.UserID = UpsellReportData.UserID

          WHERE ((@UseUserID = ''N'') OR
                ((@UseUserID = ''Y'') AND (UpsellReportData.UserID = @UserID)))

          ORDER BY UpsellReportData.UserID, JnlTranID

          /* Run through the selected records and get Upsell stats */
          DECLARE
              @CurrentUserID int,
              @JnlTranID int,
			        @TransUpsellCancelled bit,
              @UpsellStatus int,
              @UpsellPriceDifference money,

              @PrevUserID int,
              @PrevJnlTranID int,
              @TransCounted bit,
              @IsUpsell bit,
              @UpsellTransCount int,
              @UpsellSuccessCount int,
              @UpsellAmount money,
			        @UserName VarChar(20),
              @PrevUserName VarChar(20)

          DECLARE
              @UpsellReportOutput TABLE (
                  UserID int,
                  UpsellTransCount int,
                  UpsellSuccessCount int,
                  UpsellAmount money,
				          UserName VarChar(20)
                  )

          SET @UpsellTransCount = 0
          SET @UpsellSuccessCount = 0
          SET @UpsellAmount = 0
          SET @TransCounted = 0
          SET @ISUpsell = 0

          OPEN crUpsellReportData
          FETCH FROM crUpsellReportData INTO @CurrentUserID, @JnlTranID, @TransUpsellCancelled, @UpsellStatus, @UpsellPriceDifference, @UserName

          WHILE @@FETCH_STATUS = 0 BEGIN
              IF (@PrevJnlTranID <> @JnlTranID) BEGIN
                  SET @TransCounted = 0
                  SET @IsUpsell = 0
                  END

              IF @PrevUserID IS NOT NULL AND
                (@PrevUserID <> 0) AND
                (@CurrentUserID <> @PrevUserID) BEGIN

				          /* Insert the report data for the user if there are any upsell transactions */
				          IF @UpsellTransCount > 0 BEGIN
                      /* We want 1 row per UserID so insert into UpsellReportOutput table when user changes */
                      INSERT INTO @UpsellReportOutput SELECT @PrevUserID, @UpsellTransCount, @UpsellSuccessCount, @UpsellAmount, @PrevUserName
					            END

                  /* Clear counts */
                  SET @UpsellTransCount = 0
                  SET @UpsellSuccessCount = 0
                  SET @UpsellAmount = 0
                  END

              /* If a transactional upsell was cancelled, this is an upsell transaction */
			        IF (@TransUpsellCancelled = 1) BEGIN
				          IF @TransCounted = 0
                      SET @UpsellTransCount = @UpsellTransCount + 1

                  SET @TransCounted = 1
				          END

              IF (@UpsellStatus = 1) BEGIN /* Success */
                  /* Count this as an Upesell Trans 1 time for each Trans w/ UpsellStatus 1 or 2 */
                  IF @TransCounted = 0
                      SET @UpsellTransCount = @UpsellTransCount + 1

                  /* Only count as UpsellSuccess if it has not been counted for this transaction */
                  IF @IsUpsell = 0
                      SET @UpsellSuccessCount = @UpsellSuccessCount + 1

				          SET @TransCounted = 1
                  SET @IsUpsell = 1
                  END
              ELSE IF (@UpsellStatus = 2) BEGIN /* Cancelled */
                  /* Count this as an Upesell Trans 1 time for each Trans w/ UpsellStatus 1, 2 or 3 */
                  IF @TransCounted = 0
                      SET @UpsellTransCount = @UpsellTransCount + 1

                  SET @TransCounted = 1
                  END
              ELSE IF (@UpsellStatus = 3) BEGIN /* Transactional */
				          IF @TransCounted = 0
					            SET @UpsellTransCount = @UpsellTransCount + 1

				          /* Count as UpsellSuccess if it has not been counted for this transaction */
                  IF @IsUpsell = 0
                      SET @UpsellSuccessCount = @UpsellSuccessCount + 1

				          SET @TransCounted = 1
                  SET @IsUpsell = 1
				          END

              /* Update the UpsellAmount for each record */
              SET @UpsellAmount = @UpsellAmount + IsNull(@UpsellPriceDifference, 0)

              SET @PrevUserID = @CurrentUserID
              SET @PrevJnlTranID = @JnlTranID
              SET @PrevUserName = @UserName
              FETCH FROM crUpsellReportData INTO @CurrentUserID, @JnlTranID, @TransUpsellCancelled, @UpsellStatus, @UpsellPriceDifference, @UserName
              END

          /*Set the final record*/
          IF @PrevUserID IS NOT NULL BEGIN
              INSERT INTO @UpsellReportOutput SELECT @PrevUserID, @UpsellTransCount, @UpsellSuccessCount, @UpsellAmount, @UserName
              END

          SELECT * FROM @UpsellReportOutput
          ORDER BY UserName

          CLOSE crUpsellReportData
          DEALLOCATE crUpsellReportData

          SET NOCOUNT OFF
          END'
        END
    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    PRINT 'Creating GTS_MWS_AgencyReports_UpsellByItemReport stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_MWS_AgencyReports_UpsellByItemReport') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_MWS_AgencyReports_UpsellByItemReport'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_MWS_AgencyReports_UpsellByItemReport](
              @SearchFromDateTime datetime,
              @SearchThruDateTime datetime,
              @UseAgency Char,
              @AgencyID int,
              @UseCompany Char,
              @CompanyID int,
              @UsePLU Char,
              @PLU varchar(20)
              )

          AS
          BEGIN
          SET NOCOUNT ON

          DECLARE
              @SearchFromDate DateTime,
              @SearchThruDate DateTime

          SELECT
              @SearchFromDate = DateAdd(day, 0, DateDiff(day, 0, @SearchFromDateTime)),
              @SearchThruDate = DateAdd(day, 0, DateDiff(day, 0, @SearchThruDateTime))

          DECLARE
              @UpsellByItemReportData TABLE (
                  QtyTotal int,
                  UpsellFrom varchar(20),
                  UpsellStatus int,
                  UpsellType int,
                  SuccessfulUpsellTotal int,
                  UpsoldTo varchar(20),
                  UpsellAmount money,
				          UpsellFromName VarChar(40),
				          UpsoldToName VarChar(40)
                  )

          INSERT INTO @UpsellByItemReportData

          SELECT
              Sum(Qty) QtyTotal,
              UpsellFrom,
              UpsellStatus,
              UpsellType,
              Sum(SuccessfulQty) SuccessfulUpsellTotal,
              UpsoldTo,
              Sum(UpsellPriceDifference) UpsellAmount,
			        CASE WHEN UpsellStatus = 3
				          THEN ''''
				          ELSE UFItems.Name END UpsellFromName,
			        UTItems.Name UpsoldToName
          FROM
          (
              SELECT
              d.Qty,
              CASE WHEN UpsellStatus IN (1, 3)
                  THEN d.Qty
                  ELSE 0
                  END SuccessfulQty,
              CASE WHEN UpsellStatus = 2 THEN t.PLU
				          WHEN UpsellStatus = 3 THEN ''''
				          ELSE t.UpsellPLU END UpsellFrom,
              t.PLU UpsoldTo,
              t.UpsellStatus,
              t.UpsellType,
              t.UpsellPriceDifference,
              CASE WHEN Adjustment = 0
                  THEN FiscalDate + (TranDate - DateAdd(day,0, DateDiff(day, 0, TranDate)))
                  ELSE FiscalDate + (IsNull(AdjustmentTime, 0) - DateAdd(day,0, DateDiff(day, 0, IsNull(AdjustmentTime, 0))))
                  END TranDateTime
              FROM JnlHeaders h
              INNER JOIN JnlDetails d ON h.JnlTranID = d.JnlTranID
              INNER JOIN JnlTickets t ON d.JnlDetailID = t.JnlDetailID

              WHERE FiscalDate BETWEEN @SearchFromDate AND @SearchThruDate
              AND ((@UseAgency  = ''N'') OR
                  ((@UseAgency  = ''Y'') AND (Agency/1000 = @AgencyID)))
              AND ((@UseCompany = ''N'') OR
                  ((@UseCompany = ''Y'') AND (convert(BigInt, d.AccountID)/100000000 = @CompanyID)))

              UNION ALL

              SELECT
              d.Qty Qty,
              CASE WHEN UpsellStatus IN (1, 3)
                  THEN d.Qty
                  ELSE 0
                  END SuccessfulQty,
              CASE WHEN UpsellStatus = 2 THEN i.PLU
                  WHEN UpsellStatus = 3 THEN ''''
                  ELSE i.UpsellPLU END UpsellFrom,
              i.PLU UpsoldTo,
              i.UpsellStatus,
              i.UpsellType,
              i.UpsellPriceDifference,
              CASE WHEN Adjustment = 0
                  THEN FiscalDate + (TranDate - DateAdd(day,0, DateDiff(day, 0, TranDate)))
                  ELSE FiscalDate + (IsNull(AdjustmentTime, 0) - DateAdd(day,0, DateDiff(day, 0, IsNull(AdjustmentTime, 0))))
                  END TranDateTime
              FROM JnlHeaders h
              INNER JOIN JnlDetails d ON h.JnlTranID = d.JnlTranID
              INNER JOIN JnlItems i ON (d.JnlTranID = i.JnlTranID)
              AND ((d.JnlCodeID = 102) or (d.JnlCodeID = 104))
              AND (d.AuxTableID = i.JnlItemID)

              WHERE FiscalDate BETWEEN @SearchFromDate AND @SearchThruDate
              AND ((@UseAgency  = ''N'') OR
                  ((@UseAgency  = ''Y'') AND (Agency/1000 = @AgencyID)))
              AND ((@UseCompany = ''N'') OR
                  ((@UseCompany = ''Y'') AND (convert(BigInt, d.AccountID)/100000000 = @CompanyID)))

              UNION ALL

              SELECT
              1 Qty,
              CASE WHEN UpsellStatus IN (1, 3)
                  THEN 1
                  ELSE 0
                  END SuccessfulQty,
              CASE WHEN UpsellStatus = 2 THEN p.PLU
				          WHEN UpsellStatus = 3 THEN ''''
                  ELSE p.UpsellPLU END UpsellFrom,
              p.PLU UpsoldTo,
              p.UpsellStatus,
              p.UpsellType,
              p.UpsellPriceDifference,
              CASE WHEN Adjustment = 0
                  THEN FiscalDate + (TranDate - DateAdd(day,0, DateDiff(day, 0, TranDate)))
                  ELSE FiscalDate + (IsNull(AdjustmentTime, 0) - DateAdd(day,0, DateDiff(day, 0, IsNull(AdjustmentTime, 0))))
                  END TranDateTime
              FROM JnlHeaders h
              INNER JOIN JnlDetails d ON h.JnlTranID = d.JnlTranID
              INNER JOIN JnlPackages p ON d.AuxTableID = p.JnlPackageID
              AND d.JnlCodeID = 97

              WHERE FiscalDate BETWEEN @SearchFromDate AND @SearchThruDate
              AND ((@UseAgency = ''N'') OR
                  ((@UseAgency = ''Y'') AND (Agency/1000 = @AgencyID)))
              AND ((@UseCompany = ''N'') OR
                  ((@UseCompany = ''Y'') AND (convert(BigInt, d.AccountID)/100000000 = @CompanyID)))

			        UNION ALL

			        SELECT
			        1 Qty,
              0 SuccessfulQty,
			        '''' UpsellFrom,
			        '''' UpsoldTo,
              3 UpsellStatus,
              0 UpsellType,
              0.00 UpsellPriceDifference,
              CASE WHEN Adjustment = 0
                  THEN FiscalDate + (TranDate - DateAdd(day,0, DateDiff(day, 0, TranDate)))
                  ELSE FiscalDate + (IsNull(AdjustmentTime, 0) - DateAdd(day,0, DateDiff(day, 0, IsNull(AdjustmentTime, 0))))
                  END TranDateTime
			        FROM JnlHeaders
			        WHERE FiscalDate BETWEEN @SearchFromDate AND @SearchThruDate
              AND ((@UseAgency = ''N'') OR
                  ((@UseAgency = ''Y'') AND (Agency/1000 = @AgencyID)))
			        AND ((@UseCompany = ''N'') OR
                  ((@UseCompany = ''Y'') AND (CompanyID = @CompanyID)))
			        AND TransUpsellCancelled = 1
          ) UpsellReportData

		      LEFT OUTER JOIN Items UFItems ON (UpsellReportData.UpsellFrom <> '''') AND UpsellReportData.UpsellFrom = UFItems.PLU
		      LEFT OUTER JOIN Items UTItems ON (UpsellReportData.UpsoldTo <> '''') AND UpsellReportData.UpsoldTo = UTItems.PLU

          WHERE UpsellStatus in (1, 2, 3)
          AND ((@UsePLU = ''N'') OR
              ((@UsePLU = ''Y'') AND (UpsellFrom = @PLU)))
          AND TranDateTime BETWEEN @SearchFromDateTime AND @SearchThruDateTime
          GROUP BY UpsellFrom, UFItems.Name, UpsoldTo, UTItems.Name, UpsellStatus, UpsellType
          ORDER BY UpsellFrom

          DECLARE
              crUpsellByItemReportData CURSOR FOR
          SELECT * FROM @UpsellByItemReportData

          DECLARE
              @QtyTotal int,
              @UpsellFrom varchar(20),
              @UpsellStatus int,
              @UpsellType int,
              @SuccessfulUpsellTotal int,
              @UpsoldTo varchar(20),
              @UpsellAmount money,
			        @UpsellFromName VarChar(40),
			        @UpsoldToName VarChar(40)

          DECLARE
              @UpsellByItemReportOutput TABLE (
                  QtyByItemTotal int,
                  UpsellFrom varchar(20),
                  UpsellStatus int,
                  UpsellType int,
                  SuccessfulUpsellTotal int,
                  UpsoldTo varchar(20),
                  UpsellAmount money,
				          UpsellFromName VarChar(40),
				          UpsoldToName VarChar(40),
				          Transactional bit
                  )

          OPEN crUpsellByItemReportData
          FETCH FROM crUpsellByItemReportData INTO @QtyTotal, @UpsellFrom, @UpsellStatus, @UpsellType, @SuccessfulUpsellTotal, @UpsoldTo, @UpsellAmount, @UpsellFromName, @UpsoldToName

          WHILE @@FETCH_STATUS = 0 BEGIN
		      /* Ignore Upsell quantities of 0, they are only needed for calcualation purposes */
              IF @SuccessfulUpsellTotal <> 0 BEGIN
                  INSERT INTO @UpsellByItemReportOutput
                  SELECT SUM(QtyTotal), @UpsellFrom, @UpsellStatus, @UpsellType, @SuccessfulUpsellTotal, @UpsoldTo, @UpsellAmount, @UpsellFromName, @UpsoldToName, CASE WHEN @UpsellStatus = 3 THEN 1 ELSE 0 END Transactional
                  FROM @UpsellByItemReportData
                  WHERE UpsellFrom = @UpsellFrom
                  END

              FETCH FROM crUpsellByItemReportData INTO @QtyTotal, @UpsellFrom, @UpsellStatus, @UpsellType, @SuccessfulUpsellTotal, @UpsoldTo, @UpsellAmount, @UpsellFromName, @UpsoldToName
              END

          SELECT *
          FROM @UpsellByItemReportOutput
          ORDER BY Transactional, QtyByItemTotal DESC, UpsellFromName, SuccessfulUpsellTotal DESC, UpsellAmount DESC

          CLOSE crUpsellByItemReportData
          DEALLOCATE crUpsellByItemReportData

          SET NOCOUNT OFF
          END'
        END
    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END


    PRINT 'Creating GTS_SP_GiftAid_Reports stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_SP_GiftAid_Reports') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_SP_GiftAid_Reports'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE dbo.GTS_SP_GiftAid_Reports
            @ReportType Integer,     -- Type of report for which data should be returned. 0-GiftAid Claim, 1-GiftAid Audit
            @FromDate   DateTime,    -- Transaction start date
            @ThruDate   DateTime,    -- Transaction end date
            @TaxRate    Money        -- Tax rate to use for calculating GiftAid Claim Amount
            /*
            Collects data for GiftAid Claim and Audit reports and returns as a result set.
            */
        AS BEGIN
            SET NOCOUNT ON

            DECLARE @JnlTranIDs TABLE(JnlTranID Integer)

            DECLARE @TransactionsTable TABLE(
                NodeNo        Integer,
                TranNo        Integer,
                TranDate      DateTime,
                JnlTranID     Integer,
                UserID        Integer,
                PLU           Varchar(20),
                Qty           Integer,
                Price         Money,
                Tax           Money,
                GiftAidType   Integer,
                GiftAidAmount Money,
                ContactID     Integer)

            DECLARE TransactionsTableIterator CURSOR FAST_FORWARD FOR
                SELECT * FROM @TransactionsTable ORDER BY TranDate, NodeNo, TranNo

            DECLARE @NodeNo                 Integer
            DECLARE @TranNo                 Integer
            DECLARE @TranDate               DateTime
            DECLARE @JnlTranID              Integer
            DECLARE @UserID                 Integer
            DECLARE @PLU                    varchar(20)
            DECLARE @TicketPLUName          varchar(40)
            DECLARE @Qty                    Integer
            DECLARE @Price                  Money
            DECLARE @Tax                    Money
            DECLARE @GiftAidType            Integer
            DECLARE @GiftAidAmount          Money
            DECLARE @ContactID              Integer
            DECLARE @PrevJnlTranID Integer
            DECLARE @RecNo         Integer
            DECLARE @ClaimAmount   Money

            DECLARE @ItemsTable TABLE(PLU varchar(20), Name varchar(40))
            DECLARE @GxUsersTable TABLE(UserID Integer, Name varchar(20))
            DECLARE @CustContactsTable TABLE (
                ContactID Integer,
                FirstName varchar(30),
                MiddleName varchar(30),
                LastName varchar(30),
                Street varchar(510),
                City varchar(40),
                State varchar(40),
                Postal varchar(30),
                CountryCode varchar(10))

            DECLARE @ReportDataTable TABLE(
                NodeNo Integer,
                TranNo Integer,
                TranDate DateTime,
                JnlTranID Integer,
                RecNo Integer,
                ItemName Varchar(40),
                PurchasePrice Money,
                GiftAidAmount Money,
                GiftAidEligibleTotal Money,
                ClaimAmount Money,
                GiftAidType Integer,
                FirstName varchar(30),
                MiddleName varchar(30),
                LastName varchar(30),
                Street varchar(510),
                City varchar(40),
                State varchar(40),
                Postal varchar(30),
                CountryCode varchar(10),
                UserID Integer,
                UserName varchar(20))

            IF @ReportType = 0 BEGIN
            -- For GiftAid Claim report we need to get only GiftAid tickets, packages, and donations from GiftAid transactions
                INSERT INTO @TransactionsTable
                    SELECT JH.NodeNo, JH.TranNo, JH.TranDate, JH.JnlTranID, JH.UserID, JT.PLU, JT.Qty, JT.Price, JT.Tax, JT.GiftAidType, JT.GiftAidAmount, JC.ContactID
                    FROM JnlHeaders JH, JnlTickets JT, JnlDetails JD, JnlContacts JC
                    WHERE JT.JnlDetailID = JD.JnlDetailID AND JD.JnlTranID = JH.JnlTranID AND JC.JnlTranID = JH.JnlTranID
                    AND JH.TranDate BETWEEN @FromDate AND @ThruDate AND JT.GiftAidType in (1, 2)

                INSERT INTO @TransactionsTable
                    SELECT JH.NodeNo, JH.TranNo, JH.TranDate, JH.JnlTranID, JH.UserID, JP.PLU, 1, (SELECT SUM(PKGDt.Amount) FROM PkgInstanceDetails PKGDt WHERE PKGDt.JnlDetailID in (SELECT JnlDetailID FROM JnlDetails WHERE JnlTranID=JH.JnlTranID)) Price,
                        (SELECT SUM(PKGDt.Tax) FROM PkgInstanceDetails PKGDt WHERE PKGDt.JnlDetailID in (SELECT JnlDetailID FROM JnlDetails WHERE JnlTranID=JH.JnlTranID)) Tax,
                        JP.GiftAidType, JP.GiftAidAmount, JC.ContactID
                    FROM JnlHeaders JH, JnlPackages JP, JnlContacts JC
                    WHERE JP.JnlTranID = JH.JnlTranID AND JC.JnlTranID = JH.JnlTranID
                    AND JH.TranDate BETWEEN @FromDate AND @ThruDate AND JP.GiftAidType in (1, 2)

                INSERT INTO @TransactionsTable
                    SELECT JH.NodeNo, JH.TranNo, JH.TranDate, JH.JnlTranID, JH.UserID, JI.PLU, JD.Qty, JD.Amount, JI.Tax, JI.GiftAidType, 0.00, JC.ContactID
                    FROM JnlHeaders JH
                        INNER JOIN JnlItems JI
                        ON JH.JnlTranID = JI.JnlTranID
                            INNER JOIN JnlDetails JD
                            ON (JD.JnlCodeID = 104)
                            AND (JD.AuxTableID = JI.JnlItemID)
                                INNER JOIN JnlContacts JC
                                    ON JC.JnlTranID = JH.JnlTranID
                    WHERE JH.TranDate BETWEEN @FromDate AND @ThruDate
                    AND JI.GiftAidType = 2

                END
            ELSE BEGIN
            -- For GiftAid Audit report we need to get both GiftAid and non-GiftAid Tickets & Packages from GiftAid transactions
            -- Also get Gift Aid Donations from GiftAid transactions
            -- First get JnlTranID of all transactions that have at least one GiftAid Ticket, Package or Donation sold
                INSERT INTO @JnlTranIDs
                    SELECT DISTINCT JnlTranID FROM(
                        SELECT DISTINCT JH.JnlTranID FROM JnlHeaders JH, JnlTickets JT, JnlDetails JD
                        WHERE JT.JnlDetailID = JD.JnlDetailID AND JD.JnlTranID = JH.JnlTranID
                        AND JH.TranDate BETWEEN @FromDate AND @ThruDate AND JT.GiftAidType in (1, 2)

                        UNION

                        SELECT DISTINCT JH.JnlTranID FROM JnlHeaders JH, JnlPackages JP
                        WHERE JH.JnlTranID = JP.JnlTranID
                        AND JH.TranDate BETWEEN @FromDate AND @ThruDate AND JP.GiftAidType in (1, 2)

                        UNION

                        SELECT DISTINCT JH.JnlTranID
                        FROM JnlHeaders JH
                            INNER JOIN JnlItems JI
                            ON JI.JnlTranID = JH.JnlTranID
                        WHERE JH.TranDate BETWEEN @FromDate AND @ThruDate
                        AND JI.GiftAidType = 2

                        ) AS Trans

                -- Now get all tickets, packages, and GiftAid donations sold in all transactions containing GiftAid items
                INSERT INTO @TransactionsTable
                    SELECT JH.NodeNo, JH.TranNo, JH.TranDate, JH.JnlTranID, JH.UserID, JT.PLU, JT.Qty, JT.Price, JT.Tax, JT.GiftAidType, JT.GiftAidAmount, JC.ContactID
                    FROM @JnlTranIDs TranIDs, JnlHeaders JH, JnlTickets JT, JnlDetails JD, JnlContacts JC
                    WHERE TranIDs.JnlTranID = JH.JnlTranID AND JT.JnlDetailID = JD.JnlDetailID AND JD.JnlTranID = JH.JnlTranID AND JC.JnlTranID = JH.JnlTranID

                INSERT INTO @TransactionsTable
                    SELECT JH.NodeNo, JH.TranNo, JH.TranDate, JH.JnlTranID, JH.UserID, JP.PLU, 1, (SELECT SUM(PKGDt.Amount + PKGDt.Tax) FROM PkgInstanceDetails PKGDt WHERE PKGDt.JnlDetailID in (SELECT JnlDetailID FROM JnlDetails WHERE JnlTranID=JH.JnlTranID)) Price,
                        (SELECT SUM(PKGDt.Tax) FROM PkgInstanceDetails PKGDt WHERE PKGDt.JnlDetailID in (SELECT JnlDetailID FROM JnlDetails WHERE JnlTranID=JH.JnlTranID)) Tax,
                        JP.GiftAidType, JP.GiftAidAmount, JC.ContactID
                    FROM @JnlTranIDs TranIDs, JnlHeaders JH, JnlPackages JP, JnlContacts JC
                    WHERE TranIDs.JnlTranID = JH.JnlTranID AND JP.JnlTranID = JH.JnlTranID AND JC.JnlTranID = JH.JnlTranID

                INSERT INTO @TransactionsTable
                    SELECT JH.NodeNo, JH.TranNo, JH.TranDate, JH.JnlTranID, JH.UserID, JI.PLU, JD.Qty, JD.Amount, JI.Tax, JI.GiftAidType, 0.00, JC.ContactID
                    FROM @JnlTranIDs TranIDs
                        INNER JOIN JnlHeaders JH
                        ON TranIDs.JnlTranID = JH.JnlTranID
                            INNER JOIN JnlItems JI
                            ON JH.JnlTranID = JI.JnlTranID
                                INNER JOIN JnlDetails JD
                                ON (JD.JnlCodeID = 104)
                                AND (JD.AuxTableID = JI.JnlItemID)
                                    INNER JOIN JnlContacts JC
                                    ON JC.JnlTranID = JH.JnlTranID
                    WHERE JI.GiftAidType = 2

                END

            INSERT INTO @ItemsTable
                SELECT PLU, Name FROM Items WHERE PLU IN (SELECT DISTINCT PLU FROM @TransactionsTable)

            INSERT INTO @GxUsersTable
                SELECT UserID, Name FROM GXUsers WHERE UserID IN (SELECT DISTINCT UserID FROM @TransactionsTable)

            INSERT INTO @CustContactsTable
                SELECT CC.CustContactID, FirstName, MiddleName, LastName, Street1 + '' '' + Street2 as Street, City, State, Postal, CountryCode
                FROM CustContacts CC
                    LEFT OUTER JOIN Addresses AD
                    ON CC.AddressID = AD.AddressID
                    AND CC.CustContactID IN (SELECT DISTINCT ContactID FROM @TransactionsTable)

            SET @PrevJnlTranID = 0
            SET @RecNo = 0

            OPEN TransactionsTableIterator
            FETCH NEXT FROM TransactionsTableIterator INTO @NodeNo, @TranNo, @TranDate, @JnlTranID, @UserID, @PLU, @Qty, @Price, @Tax, @GiftAidType, @GiftAidAmount, @ContactID
            WHILE (@@FETCH_STATUS = 0) BEGIN
                IF @JnlTranID <> @PrevJnlTranID BEGIN
                    SET @PrevJnlTranID = @JnlTranID
                    SET @RecNo = 1
                    END

                SELECT @TicketPLUName=Name FROM @ItemsTable WHERE PLU = @PLU

                -- For Group tickets we need to multiply the GiftAidAmount by Qty. @GiftAidAmount is already negative for returned/voided tkts so use absolute Qty when multiplying
                SET @GiftAidAmount = @GiftAidAmount * ABS(@Qty)

                -- GiftAid Claim Amount = Purchase Price + Donation Amount multiplied by the Tax Rate Calculation
                SET @ClaimAmount = ROUND((@Price + @Tax + @GiftAidAmount) * ( @TaxRate / 100 ), 2)

                INSERT INTO @ReportDataTable
                    SELECT @NodeNo, @TranNo, @TranDate, @JnlTranID, @RecNo, @TicketPLUName, @Price + @Tax, @GiftAidAmount, @Price + @Tax + @GiftAidAmount, @ClaimAmount, @GiftAidType, CC.FirstName, CC.MiddleName, CC.LastName, CC.Street, CC.City, CC.State, CC.Postal, CC.CountryCode, @UserID, U.Name
                    FROM @GxUsersTable U, @CustContactsTable CC
                    WHERE U.UserID = @UserID AND CC.ContactID = @ContactID

                FETCH NEXT FROM TransactionsTableIterator INTO @NodeNo, @TranNo, @TranDate, @JnlTranID, @UserID, @PLU, @Qty, @Price, @Tax, @GiftAidType, @GiftAidAmount, @ContactID
                -- Increment @RecNo variable
                SET @RecNo = @RecNo + 1
                END
            CLOSE TransactionsTableIterator
            DEALLOCATE TransactionsTableIterator

            SELECT * FROM @ReportDataTable ORDER BY TranDate, NodeNo, TranNo
            RETURN
            END'
        END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    PRINT 'Creating GTS_SP_GetCreditCardPaymentInfo stored procedure...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_SP_GetCreditCardPaymentInfo') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_SP_GetCreditCardPaymentInfo'
        EXEC (@SQL)
        END

    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE dbo.GTS_SP_GetCreditCardPaymentInfo
            @OrderID        Integer,
            @CardHolderName Varchar(100) output,    -- should match definition of OrderPayments.CardHolderName
            @CardNumber     Varchar(50) output,     -- should match definition of OrderPayments.Endorsement
            @GxKeyID        Integer output,
            @CardType       Varchar(7) output       -- should match definition of FOPs.Name
            AS BEGIN
              -- This stored procedure finds the card holder, card number and card type associated with the first
              -- payment found in the order with the supplied OrderID.  The stored procedure is only active if the
              -- DisplayOrderInfo option is enabled on the customer associated with the order.
              SET NOCOUNT ON

              DECLARE
                @OrderLineID Integer,
                @PaymentFOP Integer,
                @Completed Bit,
                @DisplayOrderInfo Integer,
                @EndorseEdit Integer

              BEGIN
                SET @Completed = 0
                SET @EndorseEdit = 0
                SET @CardHolderName = ''''
                SET @CardNumber     = ''''
                SET @CardType       = ''''
                SET @GxKeyID        = 0

                -- Is the DisplayOrderInfo option enabled on the customer?
                SELECT @DisplayOrderInfo = DisplayOrderInfo
                FROM Customers C
                INNER JOIN Orders O ON C.CustomerID = O.CustomerID
                WHERE O.OrderID = @OrderID

                -- If the option is not enabled, do nothing
                IF @DisplayOrderInfo = 1 BEGIN

                  -- Find all payment order lines for the requested Order ID
                  DECLARE OrderLineCursor CURSOR FOR
                  SELECT OrderLineID
                  FROM OrderLines
                  WHERE (DetailType = 2) AND (OrderID = @OrderID)  -- ID_PAYMENT_ORDERDETAIL
                  ORDER BY OrderLineID

                  OPEN OrderLineCursor
                  FETCH NEXT FROM OrderLineCursor INTO @OrderLineID

                  WHILE (@@Fetch_Status = 0) BEGIN
                    -- Get the payment information for this OrderLine from OrderPayments
                    SELECT @PaymentFOP = PaymentFOP, @CardNumber = SearchEndorsementValue, @CardHolderName = CardHolderName, @GxKeyID = GxKeyID
                    FROM OrderPayments
                    WHERE OrderLineID = @OrderLineID

                    -- Check whether the payment FOP is for a credit card endorsement type
                    SELECT @EndorseEdit = EndorseEdit, @CardType = Name FROM FOPs WHERE FOPCode = @PaymentFOP
                    IF @EndorseEdit = 1 BREAK

                    FETCH NEXT FROM OrderLineCursor INTO @OrderLineID
                  END

                  CLOSE OrderLineCursor
                  DEALLOCATE OrderLineCursor
                END

                -- If not a credit card endorsement, clear output variables
                IF @EndorseEdit <> 1 BEGIN
                  SET @CardHolderName = ''''
                  SET @CardNumber     = ''''
                  SET @CardType       = ''''
                  SET @GxKeyID        = 0
                END
              END
            END'
        END

    /*    Stop the script if an error has occurred    */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

