                FETCH NEXT FROM InsertedIterator INTO @AccountID, @NewBalance, @OldBalance, @LastUpdatedBy
                END
            CLOSE InsertedIterator
            DEALLOCATE InsertedIterator
            SET NOCOUNT OFF
            END '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
