            DECLARE InsertedIterator CURSOR FOR
                SELECT ISNULL(AccountID, 0), ISNULL(Balance, 0), 0, ''OrderInsTr'' FROM INSERTED WHERE AccountID > 0

            OPEN InsertedIterator
