        'CREATE TRIGGER [dbo].[trOrdersUpdateUsedCreditAmountOnAccountDelete] ON [dbo].[Orders] FOR DELETE
        AS BEGIN
            /*
            Updates UsedCreditAmount on the customer''s account to remove any unissued monies before the order is deleted
            */
            SET NOCOUNT ON
            DECLARE @AccountID      Int
            DECLARE @UnissuedAmount Money
            DECLARE @LastUpdatedBy  varchar(20)

            DECLARE DeletedIterator CURSOR FOR
                SELECT IsNull(D.AccountID, 0), IsNull(D.UnissuedAmt, 0), ''OrderDelTr''
                FROM DELETED D, ARAccounts A
                WHERE D.AccountID = A.AccountID AND A.UsingUsedCreditAmount = 1

            OPEN DeletedIterator
            FETCH NEXT FROM DeletedIterator INTO @AccountID, @UnissuedAmount, @LastUpdatedBy
            WHILE (@@FETCH_STATUS = 0) BEGIN
                EXEC GTS_OE_UpdateUsedCreditAmountOnAccount @AccountID, 0, @UnissuedAmount, @LastUpdatedBy
                FETCH NEXT FROM DeletedIterator INTO @AccountID, @UnissuedAmount, @LastUpdatedBy
                END
            CLOSE DeletedIterator
            DEALLOCATE DeletedIterator
            SET NOCOUNT OFF
            END '
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
	END

