        SET @SQL =
        'CREATE TRIGGER [dbo].[trARInvoicesUpdateUsedCreditAmountOnAccountInsert] ON [dbo].[ARInvoices] FOR INSERT
        AS BEGIN
            /*
            Updates UsedCreditAmount on the customer''s account to add the balance amount of the Invoice being inserted
            */
