/*************** END OF ORDER ENTRY TRIGGERS AND STORED PROCEDURES SECTION ******************/

/******************* START OF PASS TRIGGERS STORED PROCEDURES SECTION ***********************/

IF (@WebStoreDB = 0) and ((@RunMode % 10) = 1) BEGIN -- We do not want to create the pass stored procedures for WebStore database

    PRINT 'Creating GTS_SP_PassHasReturnedOrVoidedHistory stored procedure...'

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
        WHERE (o.name = 'GTS_SP_PassHasReturnedOrVoidedHistory') AND (o.type = 'P')
        AND   (o.uid = u.uid)
        AND   (u.name = 'dbo')) BEGIN
        SET @SQL = 'DROP PROCEDURE dbo.GTS_SP_PassHasReturnedOrVoidedHistory'
        EXEC (@SQL)
        END

    /*
    This stored procedure determines if a pass has a return or void in its history.
    It is used to determine if the pass cannot be returned or upgraded in Galaxy.
    */
    IF @Error = 0 BEGIN
        EXEC @Error = sp_ExecuteSQL N'CREATE PROCEDURE [dbo].[GTS_SP_PassHasReturnedOrVoidedHistory]
            @PassID int,             -- The unique ID of the pass record for the history check
            @Result bit OUTPUT,      -- Outputs 1 if the history has a return or void and 0 if it does not
            @Status int OUTPUT,      -- Outputs 1 for void, 2 for return
            @HasRenewal bit OUTPUT   -- Outputs 1 if there is a renewal or upgrade after any return or void in the history

            AS BEGIN
            SET NOCOUNT ON

            DECLARE
                @TransType         int,
                @NewPrice          money,
                @TranNo            int,
                @Done              int,
                @PriorAcct         nvarchar(24),
                @PriorID           int,
                @LastReissueTranNo int

            DECLARE HistoryCursor INSENSITIVE CURSOR FOR
                SELECT TransactionType, Price, TranNo
                FROM PassHistory
                WHERE PassID = @PassID
                ORDER BY PassHistoryID DESC

            SET @Done = 0
            SET @Status = 0
            SET @Result = 0
            SET @HasRenewal = 0
            SET @LastReissueTranNo = 0

            OPEN HistoryCursor

            FETCH NEXT FROM HistoryCursor INTO @TransType, @NewPrice, @TranNo
            WHILE (@@FETCH_STATUS = 0) AND (@Done = 0) BEGIN
                IF (@TransType = 6) BEGIN -- Reissue
                    SET @LastReissueTranNo = @TranNo
                    END
                ELSE IF ((@LastReissueTranNo = 0) OR (@LastReissueTranNo <> @TranNo)) AND -- Not return for reprint
                   ((@TransType = 28) OR (@TransType = 37) OR  -- Void or Return
                   ((@TransType = 2) AND (@NewPrice < 0))) BEGIN -- Negative payment (Return)
                    SET @Result = 1
                    SET @Done = 1
                    IF @TransType = 28
                        SET @Status = 1 -- Voided
                    ELSE SET @Status = 2 -- Returned
                    END
                ELSE IF (@TransType = 7) or (@TransType = 13) BEGIN -- Renewal or Upgrade
                    SET @HasRenewal = 1
                    SET @Done = 1
                    END

                FETCH NEXT FROM HistoryCursor INTO @TransType, @NewPrice, @TranNo
                END

            CLOSE HistoryCursor
            DEALLOCATE HistoryCursor

            IF @Done = 1
                RETURN @Result

            SELECT @PriorAcct = PriorPassAcct
            FROM Passes
            WHERE PassNo = @PassID

            IF (@PriorAcct IS NULL) OR (RTRIM(@PriorAcct) = '''')
                RETURN @Result

            -- Get the ID of the prior pass
            SELECT @PriorID = PassNo
            FROM Passes
            WHERE PassAcct = @PriorAcct
            AND PassNo < @PassID
            ORDER BY PassNo DESC

            IF (@PriorID IS NULL) OR (@PriorID = 0)
                RETURN @Result

            -- Check for return or void on the prior pass
            EXEC @Result = GTS_SP_PassHasReturnedOrVoidedHistory @PriorID, @Result OUTPUT, @Status OUTPUT, @HasRenewal OUTPUT

            RETURN @Result
            END'
        END
    END  --END of the (IF @WebStoreDB = 0) condition

/******************** END OF PASS TRIGGERS STORED PROCEDURES SECTION ************************/

/*************** START OF EVENT STORE STORED PROCEDURES/TRIGGERS SECTION ******************/
IF ((@RunMode % 10) = 1) BEGIN
    --
    --                      PROCEDURE GTSGetNextEventStoreConsequenceQueue
    --
    DECLARE @GTSEventStoreSQL nvarchar(MAX)

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSGetNextEventStoreConsequenceQueue') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        PRINT '    ' + 'Dropping GTSGetNextEventStoreConsequenceQueue...'
        SET @GTSEventStoreSQL = 'DROP PROCEDURE dbo.GTSGetNextEventStoreConsequenceQueue'
        EXEC(@GTSEventStoreSQL)
        END

    --
    --                      PROCEDURE GTSGetNextEventStoreNotificationQueue
    --

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSGetNextEventStoreNotificationQueue') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        PRINT '    ' + 'Dropping GTSGetNextEventStoreNotificationQueue...'
        SET @GTSEventStoreSQL = 'DROP PROCEDURE dbo.GTSGetNextEventStoreNotificationQueue'
        EXEC(@GTSEventStoreSQL)
        END

    --
    --                      PROCEDURE GTSGetNextEventStorePassQueue
    --

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSGetNextEventStorePassQueue') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        PRINT '    ' + 'Dropping GTSGetNextEventStorePassQueue...'
        SET @GTSEventStoreSQL = 'DROP PROCEDURE dbo.GTSGetNextEventStorePassQueue'
        EXEC(@GTSEventStoreSQL)
        END

    --
    --                      PROCEDURE GTSGetNextEventStoreRabbitMQQueue
    --

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSGetNextEventStoreRabbitMQQueue') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        PRINT '    ' + 'Dropping GTSGetNextEventStoreRabbitMQQueue...'
        SET @GTSEventStoreSQL = 'DROP PROCEDURE dbo.GTSGetNextEventStoreRabbitMQQueue'
        EXEC(@GTSEventStoreSQL)
        END

    --
    --                      PROCEDURE GTSGetNextEventStoreUsageQueue
    --

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSGetNextEventStoreUsageQueue') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        PRINT '    ' + 'Dropping GTSGetNextEventStoreUsageQueue...'
        SET @GTSEventStoreSQL = 'DROP PROCEDURE dbo.GTSGetNextEventStoreUsageQueue'
        EXEC(@GTSEventStoreSQL)
        END

    --
    --                      PROCEDURE GTSUpdateEventStoreQueueItem
    --

    PRINT '    ' + 'Creating GTSUpdateEventStoreQueueItem...'
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'GTSUpdateEventStoreQueueItem') AND (o.type = 'P')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        SET @GTSEventStoreSQL = 'DROP PROCEDURE dbo.GTSUpdateEventStoreQueueItem'
        EXEC(@GTSEventStoreSQL)
        END

    SET @GTSEventStoreSQL =
        'CREATE PROCEDURE [dbo].[GTSUpdateEventStoreQueueItem]
        (
               @EventID                   UNIQUEIDENTIFIER
               ,@ConsumerName             NVARCHAR(500)
               ,@FinishedAt         DATETIMEOFFSET
               ,@ProcessStatus            INT
               ,@LastUpdatedBy            NVARCHAR(500)
               ,@Error                           NVARCHAR(MAX) = ''''
        )
        AS

        BEGIN
            SET NOCOUNT ON

               UPDATE GxEventStoreQueue
               SET           ProcessStatus = @ProcessStatus
                             ,Tries = Tries + 1
                             ,LastError = @Error
                             ,FinishedAt = @FinishedAt
                             ,RecordVersion = RecordVersion + 1
                             ,LastUpdate = GETDATE()
                             ,LastUpdatedBy = @LastUpdatedBy
               WHERE  EventID = @EventID
               AND           ConsumerName = @ConsumerName

        END'

    EXEC @Error = sp_ExecuteSQL @GTSEventStoreSQL
    /*  Stop the script if an error has occurred */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

    PRINT 'Adding trGxEventStoreInsertConsumer trigger to GxEventStore'
    IF dbo.GTSIsTrigger('trGxEventStoreInsertConsumer') = 1 BEGIN
        SET @GTSEventStoreSQL = 'DROP TRIGGER dbo.trGxEventStoreInsertConsumer'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @GTSEventStoreSQL
        END

    IF @Error = 0 BEGIN
        SET @GTSEventStoreSQL =
        'CREATE TRIGGER [dbo].[trGxEventStoreInsertConsumer] ON [dbo].[GxEventStore]
        AFTER INSERT
        AS
               IF (ROWCOUNT_BIG() = 0)
               RETURN;
               SET NOCOUNT ON

               BEGIN

                      INSERT
                      INTO          GxEventStoreQueue
                                          (
                                                 EventID
                                                 ,ConsumerName
                                                 ,EventType
                                                 ,NodeID
                                                 ,ProcessStatus
                                                 ,GxEventStoreQueueGUID
                                                 ,CreatedAt
                                                 ,Tries
                                                 ,LastError
                                                 ,RecordVersion
                                                 ,LastUpdate
                                                 ,LastUpdatedBy
                                          )
                      SELECT        E.EventID
                                          ,C.ConsumerName
                                          ,E.EventType
                                          ,NULL
                                          ,0
                                          ,NEWID()
                                          ,TODATETIMEOFFSET(SYSUTCDATETIME(), ''-00:00'')
                                          ,0
                                          ,''''
                                          ,1
                                          ,GETDATE()
                                          ,C.ConsumerName
                      FROM          inserted I
                      INNER JOIN    GxEventStore E
                      ON                   E.GxEventStoreID = I.GxEventStoreID
                      INNER JOIN    GxEventStoreConsumerDetails D
                      ON                   (E.Source LIKE CONCAT(D.EventText, ''%'') AND D.ConsumerDetailKind = 1)
                      OR                   (E.EventType = D.EventText AND D.ConsumerDetailKind = 2)
                      INNER JOIN    GxEventStoreConsumers C
                      ON                   C.GxEventStoreConsumerGUID = D.GxEventStoreConsumerGUID

               RETURN
            END'

        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @GTSEventStoreSQL
	    END

    /*  Stop the script if an error has occurred */
    IF (@Error <> 0) BEGIN
        EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
        RETURN
        END

END --@RunMode
/*************** END OF EVENT STORE STORED PROCEDURES/TRIGGERS SECTION ******************/

