/* Start Security Settings Check */
IF ((@RunMode % 10) = 1) BEGIN
    DECLARE @ConfigurationOptionID int,
		    @UpdateGxUsersFailedRemaining int,
            @SkipPCIDSS bit

    SELECT @SkipPCIDSS = convert(bit, value) FROM UpgradeSettings WHERE Setting = 'Skip PCI-DSS Security Check'
    SET @SkipPCIDSS = IsNULL(@SkipPCIDSS, 0)

    SET @UpdateGxUsersFailedRemaining = 0
    -- If CC_CODE_MIN_PASSWORD_LENGTH does not exist, insert it with the default value of 7
    if NOT EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 3) BEGIN
        EXEC @ConfigurationOptionID = GetNextGatewayCounter 'ConfigurationOptionID'
        SET @SQL = 'INSERT INTO ConfigurationOptions(ConfigurationOptionID,  Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
                   '   VALUES (' + CAST(@ConfigurationOptionID as VarChar(20)) + ', ''Minimun password length'', ''7'', 1, 3, 1, GetDate(), ''Script'', 0, 0)'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    ELSE BEGIN
        -- Ensure CC_CODE_MIN_PASSWORD_LENGTH is at least 7
        if EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 3 and Value < 7) UPDATE ConfigurationOptions SET Value = 7 WHERE Code = 3

        -- Edge case...make sure CC_CODE_MIN_PASSWORD_LENGTH is not greater than max password length (20)
        if EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 3 and Value > 20) UPDATE ConfigurationOptions SET Value = 7 WHERE Code = 3
        END


    -- If CC_CODE_MAX_FAILED_LOGON_ATTEMPTS does not exist, insert it with the default value of 6
    if NOT EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 14) BEGIN
        SET @UpdateGxUsersFailedRemaining = 1
        EXEC @ConfigurationOptionID = GetNextGatewayCounter 'ConfigurationOptionID'
        SET @SQL = 'INSERT INTO ConfigurationOptions(ConfigurationOptionID,  Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
                   'VALUES (' + CAST(@ConfigurationOptionID as VarChar(20)) + ', ''Max failed log on attempts'', ''6'', 1, 14, 1, GetDate(), ''Script'', 0, 0)'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    ELSE BEGIN
        -- See if CC_CODE_MAX_FAILED_LOGON_ATTEMPTS exists and is zero. If so, set the @UpdateGxUsersFailedRemaining flag so we update GxUsers appropriately
        if EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 14 and (Value = 0)) SET @UpdateGxUsersFailedRemaining = 1

        -- Ensure CC_CODE_MAX_FAILED_LOGON_ATTEMPTS is at most 6. If it's zero, also set it to 6.
        if EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 14 and ((Value > 6) OR (Value = 0))) UPDATE ConfigurationOptions SET Value = 6 WHERE Code = 14 AND ((Value > 6) OR (Value = 0))
        END


    -- If CC_CODE_INACTIVITY_TIMEOUT does not exist, insert it with the default value of 15
    if NOT EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 394) BEGIN
        EXEC @ConfigurationOptionID = GetNextGatewayCounter 'ConfigurationOptionID'
        SET @SQL = 'INSERT INTO ConfigurationOptions(ConfigurationOptionID,  Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
                   'VALUES (' + CAST(@ConfigurationOptionID as VarChar(20)) + ', ''Inactivity timeout'', ''15'',  1, 394, 1, GetDate(), ''Script'', 0, 0)'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    ELSE BEGIN
        -- Ensure CC_CODE_INACTIVITY_TIMEOUT is not more than 15 (minutes). If it's zero, also set it to 15.
        if EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 394 and ((Value > 15) OR (Value = 0))) UPDATE ConfigurationOptions SET Value = 15 WHERE Code = 394 AND ((Value > 15) OR (Value = 0))
        END


    -- If CC_CODE_NUM_PASSWORDS_TO_REMEMBER does not exist, insert it with the default value of 4
    if NOT EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 5) BEGIN
        EXEC @ConfigurationOptionID = GetNextGatewayCounter 'ConfigurationOptionID'
        SET @SQL = 'INSERT INTO ConfigurationOptions(ConfigurationOptionID,  Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
                   'VALUES (' + CAST(@ConfigurationOptionID as VarChar(20)) + ', ''Number of passwords to remember'', ''4'', 1, 5, 1, GetDate(), ''Script'', 0, 0)'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    ELSE BEGIN
        -- Ensure CC_CODE_NUM_PASSWORDS_TO_REMEMBER is not less than 4
        if EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 5 and Value < 4) UPDATE ConfigurationOptions SET Value = 4 WHERE Code = 5
        END

    -- If CC_CODE_MAX_PASSWORD_AGE does not exist, insert it with the default value of 90
    if NOT EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 6) BEGIN
        EXEC @ConfigurationOptionID = GetNextGatewayCounter 'ConfigurationOptionID'
        SET @SQL = 'INSERT INTO ConfigurationOptions(ConfigurationOptionID,  Description, Value, DataType, Code, RecordVersion, LastUpdate, LastUpdatedby, Scope, OwnerID) ' +
                   'VALUES (' + CAST(@ConfigurationOptionID as VarChar(20)) + ', ''Maximum password age'', ''90'', 1, 6, 1, GetDate(), ''Script'', 0, 0)'
        EXEC GTSUpgradeExecSQL  @RunMode, @Error OUTPUT, @SQL
        END
    ELSE IF @SkipPCIDSS = 0 BEGIN
        -- Ensure CC_CODE_MAX_PASSWORD_AGE is not more than 90. If it's zero, also set it to 90.
        if EXISTS(SELECT Value FROM ConfigurationOptions WHERE Code = 6 and ((Value > 90) OR (Value = 0))) UPDATE ConfigurationOptions SET Value = 90 WHERE Code = 6 AND ((Value > 90) OR (Value = 0))
        END

    -- Delete user 99 if it exists and the name is 'SYSTEM' (case-sensitive)
    delete from GxUsers where
        UserID = 99 and
        CAST(Name AS varbinary(6)) = CAST('SYSTEM' AS varbinary(6)) -- Case Sensitive check for the Name 'SYSTEM'

    if @UpdateGxUsersFailedRemaining = 1 BEGIN
        -- Upgrading from a version that didn't monitor failed logons - update any user with a FailedRemaining value of zero
        update GxUsers set FailedRemaining = 6 where ((FailedRemaining <= 0) or (FailedRemaining > 6))
        END

    -- Update and UserProfile entries that have PasswordExpirationDays values > 90
    update UserProfiles set PasswordExpirationDays = 90 where PasswordExpirationDays > 90
    END
/* End Security Settings Check */

