/* Convert TicketBankID */
IF @ConvertTicketBankIDToBigint = 1 BEGIN
    PRINT 'Converting TicketBankID columns to Bigint '

		/*
	Drop the CK_SequenceBasedCounters contraint here because we potentially
	need to convert the Name column to varchar(30). This conversion can't
	occur if CK_SequenceBasedCounters constraint exists.
	*/
	if exists (SELECT * FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS where CONSTRAINT_NAME = 'CK_SequenceBasedCounters')
	begin
		ALTER TABLE [dbo].[GatewayCounters] DROP CONSTRAINT [CK_SequenceBasedCounters]
	end

    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, TicketBanks, TicketBankID, bigint, -1, 'NOT NULL'

    -- Check to see if there's a sequence for TicketBankID that's defined as Int, and if so, convert it to BigInt
    IF EXISTS(SELECT name FROM sys.sequences WHERE name = 'TicketBankIDSequence' AND system_type_id = 56) BEGIN
        BEGIN TRANSACTION
        DECLARE @CurrentSeqValue SQL_VARIANT

        -- Get the current value for the sequence
        SELECT @CurrentSeqValue = current_value FROM sys.sequences WHERE name = 'TicketBankIDSequence'

        -- Drop the sequence
        DROP SEQUENCE TicketBankIDSequence

        -- Recreate the sequence as a BIGINT
        SET @SQL = 'CREATE SEQUENCE dbo.TicketBankIDSequence ' +
            'AS BIGINT ' +
            'START WITH ' + convert(varchar, @CurrentSeqValue) + ' ' +
            'INCREMENT BY 1 ' +
            'MINVALUE 1 ' +
            'MAXVALUE 9223372036854775807 ' +
            'CACHE CYCLE '
        EXEC(@SQL)

        -- Check for errors
        IF @@Error = 0 COMMIT TRANSACTION
        ELSE ROLLBACK TRANSACTION
        END
    END

/* Convert UsageID */
IF @ConvertUsageIDToBigint = 1 BEGIN
    PRINT 'Converting Usage columns to Bigint '

		/*
	Drop the CK_SequenceBasedCounters contraint here because we potentially
	need to convert the Name column to varchar(30). This conversion can't
	occur if CK_SequenceBasedCounters constraint exists.
	*/
	if exists (SELECT * FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS where CONSTRAINT_NAME = 'CK_SequenceBasedCounters')
	begin
		ALTER TABLE [dbo].[GatewayCounters] DROP CONSTRAINT [CK_SequenceBasedCounters]
	end

    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, Usage, UsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, Usage, OriginalUsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, JnlUsage, JnlUsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, JnlUsage, OriginalUsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, MemberUsage, MemberUsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, MemberUsage, UsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, PendingUsage, OriginalUsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, PendingUsage, PendingUsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, PendingUsage, UsageID, bigint, -1, 'NOT NULL'
    EXEC GTSUpgradeChangeColumn @RunMode, @Error OUTPUT, 1, RFCSUsage, UsageID, bigint, -1, 'NOT NULL'

    -- Check to see if there's a sequence for UsageID that's defined as Int, and if so, convert it to BigInt
    IF EXISTS(SELECT name FROM sys.sequences WHERE name = 'UsageIDSequence' AND system_type_id = 56) BEGIN
        BEGIN TRANSACTION
        -- Get the current value for the sequence
        SELECT @CurrentSeqValue = current_value FROM sys.sequences WHERE name = 'UsageIDSequence'

        -- Drop the sequence
        DROP SEQUENCE UsageIDSequence

        -- Recreate the sequence as a BIGINT
        SET @SQL = 'CREATE SEQUENCE dbo.UsageIDSequence ' +
            'AS BIGINT ' +
            'START WITH ' + convert(varchar, @CurrentSeqValue) + ' ' +
            'INCREMENT BY 1 ' +
            'MINVALUE 1 ' +
            'MAXVALUE 9223372036854775807 ' +
            'CACHE CYCLE '
        EXEC(@SQL)

        -- Check for errors
        IF @@Error = 0 COMMIT TRANSACTION
        ELSE ROLLBACK TRANSACTION
        END
    END


