    SELECT @AutomaticOrderClosing = COUNT(*) FROM ConfigurationOptions WHERE Code = 1115
    IF (@Error = 0) BEGIN
      IF (@AutomaticOrderClosing = 0) BEGIN
        SET @SQL = 'DECLARE @AllowAutomaticOrderClosing int ' +
          'DECLARE @AutomaticOrderClosingValue Integer ' +
          'DECLARE @OptionID int ' +
          'EXEC @OptionID = GetNextGatewayCounter ''ConfigurationOptionID'' ' +
          'SELECT @AllowAutomaticOrderClosing = COUNT(*) FROM ConfigurationOptions WHERE Code = 519 ' +
          'IF (@AllowAutomaticOrderClosing > 0) BEGIN ' +
            'DECLARE @AllowAutomaticOrderClosingValue varchar(3) ' +
            'SET @AllowAutomaticOrderClosingValue = (SELECT Value FROM ConfigurationOptions WHERE Code = 519) ' +
              'IF (@AllowAutomaticOrderClosingValue = ''YES'') BEGIN ' +
                'SET @AutomaticOrderClosingValue = 1 ' +
                'END ' +
              'ELSE BEGIN ' +
                'SET @AutomaticOrderClosingValue = 0 ' +
                'END ' +
              'END ' +
          'ELSE BEGIN ' +
            'SET @AutomaticOrderClosingValue = 0 ' +
            'END ' +
