          'VALUES (@OptionID, ''Auto order close'', @AutomaticOrderClosingValue, 1, 1115, 1, GETDATE(), ''Script'', 0, 0) '
        EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
        END ELSE BEGIN
          SELECT @AutomaticOrderClosing = COUNT(*) FROM ConfigurationOptions WHERE Code = 1115 AND RecordVersion = 0
          IF (@AutomaticOrderClosing > 0) BEGIN
              SET @SQL = 'UPDATE ConfigurationOptions SET RecordVersion = 1 WHERE Code = 1115 AND RecordVersion = 0'
              EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @SQL
              END
        END

      END
  END

