/***
================================================================================
Name        : ACSReservationsView
Author      : AMC
Description : A view used to retrieve additional information about a reservation which includes the contact who made
             the reservation, the contact who the reservation is for, and details about the admission header.
***/
IF (@Error = 0) and ((@RunMode % 10) = 1) BEGIN
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
               WHERE (o.name = 'ACSReservationsView') AND (o.type = 'V')
               AND   (o.uid = u.uid)
               AND   (u.name = 'dbo')) BEGIN
        PRINT '    Dropping view ACSReservationsView'
		SET @SQL = 'DROP VIEW dbo.ACSReservationsView'
        EXEC (@SQL)
        END

    SET @SQL =
        'CREATE VIEW dbo.ACSReservationsView AS ' +
        '    SELECT TOP (100) PERCENT dbo.ACSReservations.ACSReservationID, dbo.ACSReservations.ConfirmationNumber, dbo.ACSReservations.VisualID, dbo.ACSReservations.ContactGUID, dbo.ACSReservations.PassID,  ' +
        '        dbo.ACSReservations.ReservedByContactGUID, dbo.ACSReservations.VisitDate, dbo.ACSReservations.Quantity, dbo.ACSReservations.AdmissionListID, dbo.ACSReservations.Email, dbo.ACSReservations.ReservationGroupID,  ' +
        '        dbo.ACSReservations.Status, dbo.ACSReservations.PassKindGroupID, dbo.ACSReservations.PassKindID, dbo.ACSReservations.ACSReservationRuleSetID, dbo.ACSReservations.CancellationDeadline,  ' +
        '        dbo.ACSReservations.ModificationDeadline, dbo.ACSReservations.CreatedAt, dbo.ACSReservations.CancelledAt, dbo.ACSReservations.CancellationReason, dbo.ACSReservations.LastSequenceApplied,  ' +
        '        dbo.ACSReservations.ACSReservationGUID, dbo.ACSReservations.RecordVersion, dbo.ACSReservations.LastUpdate, dbo.ACSReservations.LastUpdatedBy, dbo.AdmissionHeaders.Description AS AdmissionListDescription,  ' +
        '        dbo.CustContacts.FirstName AS ReservedByFirstName, dbo.CustContacts.MiddleName AS ReservedByMiddleName, dbo.CustContacts.LastName AS ReservedByLastName, CustContacts_1.Email AS ContactEmail,  ' +
        '        dbo.ACSReservations.CreatedByGxUserGUID, dbo.ACSReservations.AvailabilityOverrideReason, dbo.ACSReservations.AvailabilityOverriden, dbo.ACSReservations.EligibilityOverriden,  ' +
        '        dbo.ACSReservations.EligibilityOverrideReason, CustContacts_2.FirstName AS CreatedByFirstName, CustContacts_2.MiddleName AS CreatedByMiddleName, CustContacts_2.LastName AS CreatedByLastName,  ' +
        '        dbo.GXUsers.UserID AS CreatedByUserID, dbo.GXUsers.UserName AS CreatedByUserName, dbo.ACSReservations.ModificationAllowed, dbo.ACSReservations.CancellationAllowed,  ' +
        '        dbo.ACSReservations.ForgiveNoShowReason, dbo.ACSReservations.ForgiveNoShowAt, dbo.GXUsers.Name AS CreatedByName, dbo.ACSReservations.ForgiveCancellationAt, dbo.ACSReservations.ForgiveCancellationReason, ' +
        '        dbo.ACSReservations.AvailabilityRequestID, dbo.ACSReservations.RedeemedQuantity ' +
        '    FROM dbo.ACSReservations ' +
        '    LEFT OUTER JOIN dbo.GXUsers ON dbo.GXUsers.GxUserGUID = dbo.ACSReservations.CreatedByGxUserGUID ' +
        '    LEFT OUTER JOIN dbo.CustContacts AS CustContacts_2 ON dbo.GXUsers.ContactID = CustContacts_2.CustContactID ' +
        '    INNER JOIN dbo.AdmissionHeaders ON dbo.ACSReservations.AdmissionListID = dbo.AdmissionHeaders.AdmHeaderID ' +
        '    INNER JOIN dbo.CustContacts ON dbo.ACSReservations.ReservedByContactGUID = dbo.CustContacts.CustContactGUID ' +
        '    INNER JOIN dbo.CustContacts AS CustContacts_1 ON dbo.ACSReservations.ContactGUID = CustContacts_1.CustContactGUID ';

    PRINT '    Creating Views ACSReservationsView...'
    EXEC(@SQL)
    END


PRINT 'Done Creating Views...'
