/************ BEGINNING OF SERVICE BROKER UPDATES FOR GALAXY *************/
IF (@WebStoreDB = 0) AND (@UseAsynchronousARAccountsUpdate = 1) BEGIN
    /* Start - Enable Service Broker for Galaxy */
    DECLARE @EnableServiceBrokerGalaxySQL NVARCHAR(MAX)

    SET @EnableServiceBrokerGalaxySQL = '
    USE [master]

    IF (SELECT d.is_broker_enabled FROM sys.databases d WHERE d.name = '''+@Database+''') = 0 BEGIN
         --  If there are any active connections, this script will deadlock.
         --  Setting to single user will kick everyone out
         ALTER DATABASE ['+@Database+'] SET SINGLE_USER WITH ROLLBACK IMMEDIATE

         --  Done to ensure the service broker guid is unique
         ALTER DATABASE ['+@Database+'] SET NEW_BROKER

         --  Enable service broker
         ALTER DATABASE ['+@Database+'] SET ENABLE_BROKER WITH NO_WAIT

         --  Make sure the database is owned by a valid user
         ALTER AUTHORIZATION ON DATABASE::['+@Database+'] TO [sa];

         --  Revert back to multi user
         ALTER DATABASE ['+@Database+'] SET MULTI_USER
    end

    USE ['+@Database+']'

    PRINT 'Enabling Service Broker for Galaxy...'
    EXEC(@EnableServiceBrokerGalaxySQL)
    /* End - Enable Service Broker for Galaxy */

    /* Make sure Service Broker is enabled and no error */
    DECLARE @GalaxyServiceBrokerEnabled INT
    SELECT @GalaxyServiceBrokerEnabled = is_broker_enabled FROM sys.databases WHERE name = @Database

    IF (@Error <> 0 or @GalaxyServiceBrokerEnabled <> 1)
        RAISERROR('Service Broker has not been enabled for the (%s) database.  Please check this setting manually under the Database Properties > Options > Service Broker > Broker Enabled', 20, 1, @Database) WITH LOG
        ELSE
        PRINT '... Service Broker Enabled for Galaxy'
    PRINT ' '
    END

IF EXISTS (SELECT svcs.name FROM sys.services svcs, sys.database_principals dp
    WHERE (svcs.name = 'ARAccountsUpdate_Service')
    AND   (svcs.principal_id = dp.principal_id)
    AND   (dp.name = 'dbo')) BEGIN
    PRINT 'Deleting ARAccountsUpdate_Service service broker service...'
    SET @SQL = 'DROP SERVICE ARAccountsUpdate_Service '
    EXEC(@SQL)
    END

IF EXISTS (SELECT name FROM sys.service_queues
    WHERE (name = 'ARAccountsUpdate_Queue')) BEGIN
    PRINT 'Deleting ARAccountsUpdate_Queue service broker queue...'
    SET @SQL = 'DROP QUEUE [dbo].[ARAccountsUpdate_Queue] '
    EXEC(@SQL)
    END

IF EXISTS (SELECT sc.name FROM sys.service_contracts sc, sys.database_principals dp
    WHERE sc.name = 'ARAccountsUpdate_Contract'
    AND   (sc.principal_id = dp.principal_id)
    AND   (dp.name = 'dbo')) BEGIN
    PRINT 'Deleting ARAccountsUpdate_Contract service broker contract...'
    SET @SQL = 'DROP CONTRACT ARAccountsUpdate_Contract '
    EXEC(@SQL)
    END

IF EXISTS (SELECT smt.name FROM sys.service_message_types smt, sys.database_principals dp
    WHERE (smt.name = 'ARAccountsUpdate_Message')
    AND   (smt.principal_id = dp.principal_id)
    AND   (dp.name = 'dbo')) BEGIN
    PRINT 'Deleting ARAccountsUpdate_Message service broker message type...'
    SET @SQL = 'DROP MESSAGE TYPE ARAccountsUpdate_Message '
    EXEC(@SQL)
    END

IF (@WebStoreDB = 0) AND (@UseAsynchronousARAccountsUpdate = 1) BEGIN
    PRINT 'Creating ARAccountsUpdate_Message service broker message type...'
    SET @SQL = '
    CREATE MESSAGE TYPE ARAccountsUpdate_Message
        AUTHORIZATION dbo
        VALIDATION = NONE '
    EXEC(@SQL)

    PRINT 'Creating ARAccountsUpdate_Contract service broker contract...'
    SET @SQL = '
    CREATE CONTRACT ARAccountsUpdate_Contract
        AUTHORIZATION dbo (
            ARAccountsUpdate_Message SENT BY ANY) '
    EXEC(@SQL)

    PRINT 'Creating ARAccountsUpdate_Queue service broker queue...'
    SET @SQL = '
    CREATE QUEUE [dbo].[ARAccountsUpdate_Queue]
        WITH STATUS = ON,
        RETENTION = OFF,
        ACTIVATION (
            STATUS = ON,
            PROCEDURE_NAME = GTS_OE_ARAccountsUpdate_QueueActivation,
            MAX_QUEUE_READERS = 1,
            EXECUTE AS OWNER) '
    EXEC(@SQL)

    PRINT 'Creating ARAccountsUpdate_Service service broker service...'
    SET @SQL = '
    CREATE SERVICE ARAccountsUpdate_Service
        AUTHORIZATION dbo
        ON QUEUE ARAccountsUpdate_Queue (ARAccountsUpdate_Contract)'
    EXEC(@SQL)
    END
/************ END OF SERVICE BROKER UPDATES FOR GALAXY *************/

/************ Check and Update DB Compatibility Level to Max Available *************/
DECLARE @RecommendCompatibilityLevelUpdate BIT = 0
DECLARE @CurrentDBCompatibilityLevel       TINYINT
DECLARE @MaxDBCompatibilityLevel           TINYINT
SELECT @CurrentDBCompatibilityLevel = compatibility_level FROM sys.databases WHERE [name] = @Database
SELECT @MaxDBCompatibilityLevel = MAX(compatibility_level) FROM sys.databases
IF @CurrentDBCompatibilityLevel < @MaxDBCompatibilityLevel
BEGIN
    IF @UpdateDBCompatibilityLevelToMax = 0
    BEGIN
        SET @RecommendCompatibilityLevelUpdate = 1
    END
    ELSE IF ((@RunMode % 10) = 1)
    BEGIN
        SET @RecommendCompatibilityLevelUpdate = 0
        PRINT ''
        PRINT 'Updating compatibility level from ' + CONVERT(NVARCHAR(3), @CurrentDBCompatibilityLevel) + ' to ' + CONVERT(NVARCHAR(3), @MaxDBCompatibilityLevel)
        DECLARE @ChangeCompatibilityLevelSQL NVARCHAR(MAX) =
            N'ALTER DATABASE ' +
            QUOTENAME(@Database) +
            ' SET COMPATIBILITY_LEVEL = ' +
            CONVERT(NVARCHAR(3), @MaxDBCompatibilityLevel)
        EXEC(@ChangeCompatibilityLevelSQL)

        -- Retrieve current compatibility level again
        SELECT @CurrentDBCompatibilityLevel = compatibility_level FROM sys.databases WHERE [name] = @Database
    END
END

