DECLARE @WSPaymentConfigHeaderDetailsExist bit
EXEC @WSPaymentConfigHeaderDetailsExist = GTSTableExists WSPaymentConfigHeaders
IF @WSPaymentConfigHeaderDetailsExist = 0 BEGIN EXEC @WSPaymentConfigHeaderDetailsExist = GTSTableExists WSPaymentConfigDetails END

DECLARE @WSPaymentConfigSQL nvarchar(MAX)
PRINT '    ' + 'Creating CreateWSPaymentConfigDetails...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'CreateWSPaymentConfigDetails') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo')) BEGIN
    SET @WSPaymentConfigSQL = 'DROP PROCEDURE dbo.CreateWSPaymentConfigDetails'
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @WSPaymentConfigSQL
    END

SET @WSPaymentConfigSQL = N'CREATE PROCEDURE dbo.CreateWSPaymentConfigDetails(@WSConfigHeaderId int, @PaymentConfigHeaderId int)
AS
BEGIN
SET NOCOUNT ON

DECLARE @NextId int,
	@Key varchar(200),
	@Value varchar(200)

DECLARE PaymentConfigCursor INSENSITIVE CURSOR FOR
	SELECT [key], value FROM
	WSPaymentConfig
	WHERE WSConfigID = @WSConfigHeaderId

OPEN PaymentConfigCursor

FETCH NEXT FROM PaymentConfigCursor INTO @Key, @Value
WHILE @@FETCH_STATUS = 0 BEGIN
    if (@Key = ''AccertifyUrl'') OR
       (@Key = ''AccertifyUser'') OR
       (@Key = ''AccertifyPassword'') OR
       (@Key = ''AccertifyMerchant'') OR
       (@Key = ''AccertifyOutputFormat'') OR
       (@Key = ''AccertifyProcess'') BEGIN
        FETCH NEXT FROM PaymentConfigCursor INTO @Key, @Value
        CONTINUE;
        END

    EXEC @NextId = GetNextGatewayCounter ''WSPaymentConfigDetailID''

    INSERT INTO WSPaymentConfigDetails (WSPaymentConfigDetailID, WSPaymentConfigHeaderID, [Key], value, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES (@NextId, @PaymentConfigHeaderId, @Key, @Value, 1, GETDATE(), ''Script'')

	FETCH NEXT FROM PaymentConfigCursor INTO @Key, @Value
	END

CLOSE PaymentConfigCursor
DEALLOCATE PaymentConfigCursor
END'

IF ((@RunMode % 10) = 1) BEGIN
    EXEC(@WSPaymentConfigSQL)
    END

PRINT '    ' + 'Creating CreateWSPaymentConfigHeaders...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'CreateWSPaymentConfigHeaders') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo')) BEGIN
    SET @WSPaymentConfigSQL = 'DROP PROCEDURE dbo.CreateWSPaymentConfigHeaders'
    EXEC GTSUpgradeExecSQL @RunMode, @Error OUTPUT, @WSPaymentConfigSQL
    END

SET @WSPaymentConfigSQL = N'CREATE PROCEDURE dbo.CreateWSPaymentConfigHeaders
AS
BEGIN
SET NOCOUNT ON

DECLARE @ConfigHeaderId int,
	@DefaultConfig int,
	@NextId int,
	@DefaultPaymentProvider varchar(30),
	@AccertifyUrl varchar(200),
	@AccertifyUser varchar(200),
	@AccertifyPassword varchar(200),
	@AccertifyMerchant varchar(200),
	@AccertifyOutputFormat varchar(200),
	@AccertifyProcess varchar(200)

DECLARE ConfigHeaderCursor INSENSITIVE CURSOR FOR
	SELECT WSConfigHeaderID, DefaultConfig FROM
	WSConfigHeaders
	ORDER BY WSConfigHeaderID

OPEN ConfigHeaderCursor

FETCH NEXT FROM ConfigHeaderCursor INTO @ConfigHeaderId, @DefaultConfig
WHILE @@FETCH_STATUS = 0 BEGIN
    -- Get default payment provider
    SELECT @DefaultPaymentProvider = (SELECT value from WSConfigDetails where WSConfigHeaderID = @ConfigHeaderId and  [key] = ''PaymentProvider'')

    EXEC @NextId = GetNextGatewayCounter ''WSPaymentConfigHeaderID''

    INSERT INTO WSPaymentConfigHeaders (WSPaymentConfigHeaderID, WSConfigHeaderID, Active, ProviderType, [Default], Sequence, RecordVersion, LastUpdate, LastUpdatedBy)
                VALUES (@NextId, @ConfigHeaderId, 1, @DefaultPaymentProvider, 1, 1, 1, GETDATE(), ''Script'')

    -- Call proc to create WSPaymentConfigDetails pass in @NextId
    EXEC dbo.CreateWSPaymentConfigDetails @ConfigHeaderId, @NextId

    -- Check for AccertifyUrl value in WSPaymentConfig and move to WSConfigDetails
    SELECT @AccertifyUrl = (SELECT value from WSPaymentConfig where WSConfigID = @ConfigHeaderId and  [key] = ''AccertifyUrl'')

    if (@AccertifyUrl IS NOT NULL AND LEN(@AccertifyUrl) > 0) BEGIN
        EXEC @NextId = GetNextGatewayCounter ''WSConfigDetailID''
        INSERT INTO WSConfigDetails (WSConfigDetailID, WSConfigHeaderID, [Key], Value, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES (@NextId, @ConfigHeaderId, ''AccertifyUrl'', @AccertifyUrl, 1, GETDATE(), ''Script'')
        END

    -- Check for AccertifyUser value in WSPaymentConfig and move to WSConfigDetails
    SELECT @AccertifyUser = (SELECT value from WSPaymentConfig where WSConfigID = @ConfigHeaderId and  [key] = ''AccertifyUser'')

    if (@AccertifyUser IS NOT NULL AND  LEN(@AccertifyUser) > 0) BEGIN
        EXEC @NextId = GetNextGatewayCounter ''WSConfigDetailID''
        INSERT INTO WSConfigDetails (WSConfigDetailID, WSConfigHeaderID, [Key], Value, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES (@NextId, @ConfigHeaderId, ''AccertifyUser'', @AccertifyUser, 1, GETDATE(), ''Script'')
        END

    -- Check for AccertifyPassword value in WSPaymentConfig and move to WSConfigDetails
    SELECT @AccertifyPassword = (SELECT value from WSPaymentConfig where WSConfigID = @ConfigHeaderId and  [key] = ''AccertifyPassword'')

    if (@AccertifyPassword IS NOT NULL AND LEN(@AccertifyPassword) > 0) BEGIN
        EXEC @NextId = GetNextGatewayCounter ''WSConfigDetailID''
        INSERT INTO WSConfigDetails (WSConfigDetailID, WSConfigHeaderID, [Key], Value, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES (@NextId, @ConfigHeaderId, ''AccertifyPassword'', @AccertifyPassword, 1, GETDATE(), ''Script'')
        END

    -- Check for AccertifyMerchant value in WSPaymentConfig and move to WSConfigDetails
    SELECT @AccertifyMerchant = (SELECT value from WSPaymentConfig where WSConfigID = @ConfigHeaderId and  [key] = ''AccertifyMerchant'')

    if (@AccertifyMerchant IS NOT NULL AND LEN(@AccertifyMerchant) > 0) BEGIN
        EXEC @NextId = GetNextGatewayCounter ''WSConfigDetailID''
        INSERT INTO WSConfigDetails (WSConfigDetailID, WSConfigHeaderID, [Key], Value, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES (@NextId, @ConfigHeaderId, ''AccertifyMerchant'', @AccertifyMerchant, 1, GETDATE(), ''Script'')
        END

    -- Check for AccertifyOutputFormat value in WSPaymentConfig and move to WSConfigDetails
    SELECT @AccertifyOutputFormat = (SELECT value from WSPaymentConfig where WSConfigID = @ConfigHeaderId and  [key] = ''AccertifyOutputFormat'')

    if (@AccertifyOutputFormat IS NOT NULL AND LEN(@AccertifyOutputFormat) > 0) BEGIN
        EXEC @NextId = GetNextGatewayCounter ''WSConfigDetailID''
        INSERT INTO WSConfigDetails (WSConfigDetailID, WSConfigHeaderID, [Key], Value, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES (@NextId, @ConfigHeaderId, ''AccertifyOutputFormat'', @AccertifyOutputFormat, 1, GETDATE(), ''Script'')
        END

    -- Check for AccertifyProcess value and move to WSConfigDetails
    SELECT @AccertifyProcess = (SELECT value from WSPaymentConfig where WSConfigID = @ConfigHeaderId and  [key] = ''AccertifyProcess'')

    if (@AccertifyProcess IS NOT NULL AND LEN(@AccertifyProcess) > 0) BEGIN
        EXEC @NextId = GetNextGatewayCounter ''WSConfigDetailID''
        INSERT INTO WSConfigDetails (WSConfigDetailID, WSConfigHeaderID, [Key], Value, RecordVersion, LastUpdate, LastUpdatedBy)
        VALUES (@NextId, @ConfigHeaderId, ''AccertifyProcess'', @AccertifyProcess, 1, GETDATE(), ''Script'')
        END

	FETCH NEXT FROM ConfigHeaderCursor INTO @ConfigHeaderId, @DefaultConfig
	END

CLOSE ConfigHeaderCursor
DEALLOCATE ConfigHeaderCursor
END'

IF ((@RunMode % 10) = 1) BEGIN
    EXEC(@WSPaymentConfigSQL)
    END

