EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, PickupAndPublishing, bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, Reseller, bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, PassPortal, bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, Mobile, bit
EXEC GTSUpgradeAddColumn  @RunMode, @Error OUTPUT, @TableName, GroupSales, bit

