--
--              PROCEDURE GTSWriteToWSLog
--    /*  SP to write an entry to the WSLog table */
--
DECLARE @GTSWriteToWSLogSPSQL varchar(8000)
PRINT '    ' + 'Creating GTSWriteToWSLog...'
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
       WHERE (o.name = 'GTSWriteToWSLog') AND (o.type = 'P')
       AND   (o.uid = u.uid)
       AND   (u.name = 'dbo')) BEGIN
    SET @GTSWriteToWSLogSPSQL = 'DROP PROCEDURE dbo.GTSWriteToWSLog'
    EXEC(@GTSWriteToWSLogSPSQL)
    END

SET @GTSWriteToWSLogSPSQL =
    'CREATE PROCEDURE dbo.GTSWriteToWSLog(@LogLevel nvarchar(200), @CallSite nvarchar(200), @Message nvarchar(200)) AS BEGIN
    SET nocount ON
    /*
     Writes a record to the WSLog table.

       Parameter Expected Values
       @LogLevel - *Required Value* - SQL, Trace, Debug, Info, Warn, Error
       @CallSite - Stored Procedure, Function, or Calling Method
       @Message - Error Message to be logged

     Usage

     EXEC GTSRowSize ''SQL'', ''GTS_MS_SP_ResetExternalOrderStatus42'', ''<ExternalIdReset><orderid>426089</orderid></ExternalIdReset>''

     */

              IF @LogLevel in (''SQL'', ''Trace'', ''Debug'', ''Info'', ''Warn'', ''Error'')
                     BEGIN
                           INSERT INTO WSLOG
                                  ([DateTime],
                                         [LogLevel],
                                         [ASPNetSessionID],
                                         [CallSite],
                                         [Message],
                                         [StackTrace],
                                         [RemoteAddress],
                                         [HttpReferer],
                                         [HttpUserAgent],
                                         [WebServerIP]
                                  )
                           VALUES
                                  (GETDATE(),
                                         @LogLevel,
                                         '''', --[ASPNetSessionID]
                                         @CallSite,
                                         @Message,
                                         '''', --[StackTrace]
                                         CONVERT(nvarchar(500),CONNECTIONPROPERTY(''client_net_address'')), --[RemoteAddress]
                                         '''', --[HttpReferer]
                                         ISNULL(CONVERT(nvarchar(50),CONNECTIONPROPERTY(''protocol_type'')),'''') , --[HttpUserAgent]
                                         ISNULL(CONVERT(nvarchar(50),CONNECTIONPROPERTY(''local_net_address'')),'''') --[WebServerIP]
                                  )
                     END
     END'

EXEC(@GTSWriteToWSLogSPSQL)

