/*
  ---------------------------------------------------------------------------

        *** Web Store Database Purge Scripts ***

*/

--
--  -------------------------------------------------------------------
--
--                  ***  GTSWSDeleteHistoricalDataFromTable  ***
--
DECLARE @WSPurgeScriptSQL varchar(max)

IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSWSDeleteHistoricalDataFromTable') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
BEGIN
  SET @WSPurgeScriptSQL = 'DROP PROCEDURE dbo.GTSWSDeleteHistoricalDataFromTable'
  EXEC(@WSPurgeScriptSQL)
END

IF EXISTS (SELECT * FROM [sys].[table_types] WHERE user_type_id = Type_id('IdListForDelete'))
BEGIN
  SET @WSPurgeScriptSQL = 'DROP TYPE dbo.IdListForDelete'
  EXEC(@WSPurgeScriptSQL)
END
SET @WSPurgeScriptSQL = 'CREATE TYPE IdListForDelete AS TABLE (RecordID bigint NOT NULL)'
EXEC(@WSPurgeScriptSQL)

SET @WSPurgeScriptSQL = 'CREATE PROCEDURE GTSWSDeleteHistoricalDataFromTable
  @TableName nvarchar(100),
  @TableIdColumn nvarchar(100),
  @IdsToDelete IdListForDelete READONLY,
  @PerformDeletes bit = 0,
  @BatchSize int = 1000000
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @RowsDeletedCurrent bigint = 0,
          @RowsDeleted bigint = 0,
          @RowsRemaining bigint = 0,
          @sql nvarchar(max)

  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = @TableName) BEGIN
    RAISERROR(''Database does not contain table %s. Skipping delete.'', 10, 1, @TableName) WITH NOWAIT;
    RETURN;
	END

  SET @sql =
    ''SELECT @RowsRemainingOutput = COUNT(1) '' +
    ''  FROM ['' + @TableName + ''] '' +
    '' WHERE ['' + @TableIdColumn + ''] IN (SELECT RecordID FROM @IdsToDeleteInput)'';

  EXECUTE sp_executesql @sql, N''@IdsToDeleteInput IdListForDelete READONLY, @RowsRemainingOutput bigint OUTPUT'', @IdsToDeleteInput = @IdsToDelete, @RowsRemainingOutput = @RowsRemaining OUTPUT

  RAISERROR(''Beginning delete from %s. Approximately %I64d rows to delete.'', 10, 1, @TableName, @RowsRemaining) WITH NOWAIT;

  BEGIN TRY
    WHILE (@RowsRemaining > 0 AND @PerformDeletes = 1) BEGIN
	SET @sql =
        ''WITH TopRows AS '' +
	    ''('' +
	    ''  SELECT TOP ('' + CONVERT(varchar, @BatchSize) + '') ['' + @TableIdColumn + ''] '' +
        ''    FROM ['' + @TableName + ''] '' +
        ''   WHERE ['' + @TableIdColumn + ''] IN (SELECT RecordID FROM @IdsToDeleteInput)'' +
	    '') DELETE FROM TopRows;''

        EXECUTE sp_executesql @sql, N''@IdsToDeleteInput IdListForDelete READONLY'', @IdsToDeleteInput = @IdsToDelete

	    SET @RowsDeletedCurrent = @@ROWCOUNT;
	    IF @RowsDeletedCurrent = 0 BREAK;
	    SET @RowsDeleted = @RowsDeleted + @RowsDeletedCurrent;
	    SET @RowsRemaining = @RowsRemaining - @RowsDeletedCurrent;

        RAISERROR(''  %I64d rows deleted so far. Approximately %I64d rows remaining.'', 10, 1, @RowsDeleted, @RowsRemaining) WITH NOWAIT;
    END

    RAISERROR(''  Finished. Deleted %I64d rows from %s.'', 10, 1, @RowsDeleted, @TableName) WITH NOWAIT;
  END TRY
  BEGIN CATCH
    DECLARE @ERROR_MESSAGE NVARCHAR(2048);
    DECLARE @ERROR_SEVERITY TINYINT;
    DECLARE @ERROR_NUMBER INT;

    SET @ERROR_MESSAGE = ERROR_MESSAGE();
    SET @ERROR_NUMBER = ERROR_NUMBER();
    SET @ERROR_SEVERITY = ERROR_SEVERITY();

    RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
  END CATCH
END'
EXEC(@WSPurgeScriptSQL)

--
--  -------------------------------------------------------------------
--
--                  ***  GTSWSPurgeLogData  ***
--
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSWSPurgeLogData') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
BEGIN
  SET @WSPurgeScriptSQL = 'DROP PROCEDURE dbo.GTSWSPurgeLogData'
  EXEC(@WSPurgeScriptSQL)
END

SET @WSPurgeScriptSQL = 'CREATE PROCEDURE GTSWSPurgeLogData
  @RetentionPeriodDays int = 90,
  @PerformDeletes bit = 0,
  @BatchSize int = 1000
AS
BEGIN
  SET NOCOUNT ON;

  BEGIN TRY

    DECLARE @RetentionDate datetime = DATEADD(day, -@RetentionPeriodDays, DATEADD(day, DATEDIFF(day, 0, CURRENT_TIMESTAMP),0));
    DECLARE @RetentionDateText varchar(50) = CAST(@RetentionDate as varchar);

    RAISERROR(''Will delete logging data with DateTime before %s'', 10, 1, @RetentionDateText) WITH NOWAIT;

    DECLARE @TempIdList IdListForDelete

    INSERT INTO @TempIdList SELECT WSPublishingLogID FROM WSPublishingLog WHERE DateTime < DATEADD(day, -@RetentionPeriodDays, DATEADD(day, DATEDIFF(day, 0, CURRENT_TIMESTAMP),0));
    EXEC GTSWSDeleteHistoricalDataFromTable ''WSPublishingLog'', ''WSPublishingLogID'', @TempIdList, @PerformDeletes, @BatchSize

    DELETE FROM @TempIdList
    INSERT INTO @TempIdList SELECT WSLogID FROM WSLog WHERE DateTime < DATEADD(day, -@RetentionPeriodDays, DATEADD(day, DATEDIFF(day, 0, CURRENT_TIMESTAMP),0));
    EXEC GTSWSDeleteHistoricalDataFromTable ''WSLog'', ''WSLogID'', @TempIdList, @PerformDeletes, @BatchSize

  END TRY
  BEGIN CATCH
    DECLARE @ERROR_MESSAGE NVARCHAR(2048);
    DECLARE @ERROR_SEVERITY TINYINT;
    DECLARE @ERROR_NUMBER INT;

    SET @ERROR_MESSAGE = ERROR_MESSAGE();
    SET @ERROR_NUMBER = ERROR_NUMBER();
    SET @ERROR_SEVERITY = ERROR_SEVERITY();

    RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
  END CATCH
END'
EXEC(@WSPurgeScriptSQL)

--
--  -------------------------------------------------------------------
--
--                  ***  GTSWSPurgeOrderData  ***
--
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSWSPurgeOrderData') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
BEGIN
  SET @WSPurgeScriptSQL = 'DROP PROCEDURE dbo.GTSWSPurgeOrderData'
  EXEC(@WSPurgeScriptSQL)
END

SET @WSPurgeScriptSQL = 'CREATE PROCEDURE GTSWSPurgeOrderData
  @RetentionPeriodDays int = 90,
  @PerformDeletes bit = 0,
  @BatchSize int = 1000
AS
BEGIN
  SET NOCOUNT ON;

  -- We must retain order data for 5 years plus the current year, so calculate what the "minimum" date we must retain is.
  DECLARE @CurrentYearStartDate datetime = DATEADD(YY, DATEDIFF(YY, 0, CURRENT_TIMESTAMP), 0)
  DECLARE @MinAllowedDate datetime = DATEADD(yy, -5, @CurrentYearStartDate)

  -- Calculate the date the caller requested to delete data after
  DECLARE @RequestedMinDate datetime = DATEADD(day, -@RetentionPeriodDays, DATEADD(day, DATEDIFF(day, 0, CURRENT_TIMESTAMP), 0))

  DECLARE @RetentionDate datetime = IIF(@RequestedMinDate < @MinAllowedDate, @RequestedMinDate, @MinAllowedDate)

  IF @RequestedMinDate > @MinAllowedDate RAISERROR(''Increasing requested retention period so it includes current year plus 5 years.'', 10, 1) WITH NOWAIT;

  DECLARE @RetentionDateText varchar(50) = CAST(@RetentionDate as varchar)
  RAISERROR(''Will delete order data with LastUpdate before %s'', 10, 1, @RetentionDateText) WITH NOWAIT;

  BEGIN TRY
    DECLARE @OrdersToDelete IdListForDelete;
    INSERT INTO @OrdersToDelete SELECT OrderID FROM Orders WHERE OpenDate < @RetentionDate;

    DECLARE @TempIdList IdListForDelete

    -- PaymentContractItems
    INSERT INTO @TempIdList
    SELECT PaymentContractItems.PaymentContractItemID
        FROM PaymentContractItems
        JOIN PaymentContracts ON PaymentContracts.PaymentContractID = PaymentContractItems.PaymentContractID
        WHERE PaymentContracts.OrderID IN (SELECT RecordID from @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''PaymentContractItems'', ''PaymentContractItemID'', @TempIdList, @PerformDeletes, @BatchSize

    -- PaymentContracts
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT PaymentContractID FROM PaymentContracts WHERE OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''PaymentContracts'', ''PaymentContractID'', @TempIdList, @PerformDeletes, @BatchSize

    -- AttributeValues
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
        SELECT AttributeValues.AttributeValueID
        FROM AttributeValues
        JOIN Orders ON Orders.AttributeValueGroupID = AttributeValues.AttributeValueGroupID
        WHERE Orders.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    UNION
        SELECT AttributeValues.AttributeValueID
        FROM AttributeValues
        JOIN Rosters ON Rosters.RosterAttributeValueGroupID = AttributeValues.AttributeValueGroupID
        JOIN OrderLines ON OrderLines.OrderLineID = Rosters.OrderLineID
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''AttributeValues'', ''AttributeValueID'', @TempIdList, @PerformDeletes, @BatchSize

    -- WSPaymentBootstrapDetails
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT WSPaymentBootstrapDetails.PaymentBootstrapDetailID
        FROM WSPaymentBootstrapDetails
        JOIN WSPaymentBootstrapHeaders ON WSPaymentBootstrapDetails.PaymentBootstrapHeaderID = WSPaymentBootstrapHeaders.PaymentBootstrapHeaderID
        WHERE WSPaymentBootstrapHeaders.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''WSPaymentBootstrapDetails'', ''PaymentBootstrapDetailID'', @TempIdList, @PerformDeletes, @BatchSize

    -- WSPaymentBootstrapHeaders
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT WSPaymentBootstrapHeaders.PaymentBootstrapHeaderID
        FROM WSPaymentBootstrapHeaders
        WHERE OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''WSPaymentBootstrapHeaders'', ''PaymentBootstrapHeaderID'', @TempIdList, @PerformDeletes, @BatchSize

    -- WSOrderPaymentsLog
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT WSOrderPaymentsLogID FROM WSOrderPaymentsLog WHERE OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''WSOrderPaymentsLog'', ''WSOrderPaymentsLogID'', @TempIdList, @PerformDeletes, @BatchSize

    DECLARE @ContactsToDelete IdListForDelete

    -- Gather CustContacts to delete
    INSERT INTO @ContactsToDelete
        SELECT Orders.ContactID
        FROM Orders
        JOIN CustContacts ON CustContacts.CustContactID = Orders.ContactID
        WHERE OrderID IN (SELECT RecordID FROM @OrdersToDelete) AND ISNULL(CustContacts.PersistenceState, 0) = 0
    UNION
        SELECT Orders.BillToContactID
        FROM Orders
        JOIN CustContacts ON CustContacts.CustContactID = Orders.BillToContactID
        WHERE OrderID IN (SELECT RecordID FROM @OrdersToDelete) AND ISNULL(CustContacts.PersistenceState, 0) = 0
    UNION
        SELECT Orders.ShipToContactID
        FROM Orders
        JOIN CustContacts ON CustContacts.CustContactID = Orders.ShipToContactID
        WHERE OrderID IN (SELECT RecordID FROM @OrdersToDelete) AND ISNULL(CustContacts.PersistenceState, 0) = 0
    UNION
        SELECT CustContacts.CustContactID
        FROM CustContacts
        JOIN Rosters ON Rosters.ContactID = CustContacts.CustContactID
        JOIN OrderLines ON OrderLines.OrderLineID = Rosters.OrderLineID
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete) AND ISNULL(CustContacts.PersistenceState, 0) = 0
    UNION
        SELECT CustContacts.CustContactID
        FROM CustContacts
        JOIN Passes ON Passes.ContactID = CustContacts.CustContactID
        JOIN OrderLines ON OrderLines.PassID = Passes.PassNo
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete) AND ISNULL(CustContacts.PersistenceState, 0) = 0
    UNION
        SELECT CustContacts.CustContactID
        FROM CustContacts
        JOIN JointMembers ON JointMembers.ContactID = CustContactID
        JOIN Passes ON JointMembers.PassNo = Passes.PassNo
        JOIN OrderLines ON OrderLines.PassID = Passes.PassNo
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete) AND ISNULL(CustContacts.PersistenceState, 0) = 0

    -- PhoneNumbers
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT PhoneNumberID
        FROM PhoneNumbers
        WHERE ContactID IN (SELECT RecordID FROM @ContactsToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''PhoneNumbers'', ''PhoneNumberID'', @TempIdList, @PerformDeletes, @BatchSize

    -- Addresses
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT Addresses.AddressID
        FROM Addresses
        JOIN CustContacts ON CustContacts.AddressID = Addresses.AddressID
        WHERE CustContacts.CustContactID IN (SELECT RecordID FROM @ContactsToDelete) AND ISNULL(Addresses.PersistenceState, 0) = 0
    EXEC GTSWSDeleteHistoricalDataFromTable ''Addresses'', ''AddressID'', @TempIdList, @PerformDeletes, @BatchSize

    -- Rosters
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT Rosters.RosterID
        FROM Rosters
        JOIN CustContacts ON CustContacts.CustContactID = Rosters.ContactID
        JOIN OrderLines ON OrderLines.OrderLineID = Rosters.OrderLineID
        WHERE CustContacts.CustContactID IN (SELECT RecordID FROM @ContactsToDelete) AND
            OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''Rosters'', ''RosterID'', @TempIdList, @PerformDeletes, @BatchSize

    -- JointMembers
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT JointMembers.JointMemberID
        FROM JointMembers
        JOIN CustContacts ON CustContacts.CustContactID = JointMembers.ContactID
        JOIN Passes ON Passes.PassNo = JointMembers.PassNo
        JOIN OrderLines ON OrderLines.PassID = Passes.PassNo
        WHERE CustContacts.CustContactID IN (SELECT RecordID FROM @ContactsToDelete) AND
            OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''JointMembers'', ''JointMemberID'', @TempIdList, @PerformDeletes, @BatchSize

    -- Passes
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT Passes.PassNo
        FROM Passes
        JOIN CustContacts ON CustContacts.CustContactID = Passes.ContactID
        JOIN OrderLines ON OrderLines.PassID = Passes.PassNo
        WHERE CustContacts.CustContactID IN (SELECT RecordID FROM @ContactsToDelete) AND
            OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''Passes'', ''PassNo'', @TempIdList, @PerformDeletes, @BatchSize

    -- CustContacts
    EXEC GTSWSDeleteHistoricalDataFromTable ''CustContacts'', ''CustContactID'', @ContactsToDelete, @PerformDeletes, @BatchSize

    -- OEGuests
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OEGuests.OEGuestID
        FROM OEGuests
        JOIN OrderLines ON OrderLines.GuestID = OEGuests.OEGuestID
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OEGuests'', ''OEGuestID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OrderLineSeats
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OrderLineSeats.OrderLineSeatID
        FROM OrderLineSeats
        JOIN OrderLines ON OrderLines.OrderLineID = OrderLineSeats.OrderLineID
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OrderLineSeats'', ''OrderLineSeatID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OrderLineUpsells
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OrderLineUpsells.OrderLineUpsellID
        FROM OrderLineUpsells
        JOIN OrderLines ON OrderLines.OrderLineID = OrderLineUpsells.OrderLineID
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OrderLineUpsells'', ''OrderLineUpsellID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OrderLineDiscounts
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OrderLineDiscounts.OrderLineDiscountID
        FROM OrderLineDiscounts
        JOIN OrderLines ON OrderLines.OrderLineID = OrderLineDiscounts.OrderLineID
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OrderLineDiscounts'', ''OrderLineDiscountID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OrderLineTaxAmounts
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OrderLineTaxAmounts.OrderLineTaxAmountID
        FROM OrderLineTaxAmounts
        JOIN OrderLines ON OrderLines.OrderLineID = OrderLineTaxAmounts.OrderLineID
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OrderLineTaxAmounts'', ''OrderLineTaxAmountID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OrderPayments
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OrderPayments.OrderPaymentID
        FROM OrderPayments
        JOIN OrderLines ON OrderLines.OrderLineID = OrderPayments.OrderLineID
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OrderPayments'', ''OrderPaymentID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OrderSurveys
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OrderSurveys.OrderSurveyID
        FROM OrderSurveys
        WHERE OrderSurveys.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OrderSurveys'', ''OrderSurveyID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OEGroupVisits
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OEGroupVisits.GroupVisitID
        FROM OEGroupVisits
        JOIN Orders ON Orders.GroupVisitID = OEGroupVisits.GroupVisitID
        WHERE Orders.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OEGroupVisits'', ''GroupVisitID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OEUserFields
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OEUserFields.OEUserFieldID
        FROM OEUserFields
        WHERE OEUserFields.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OEUserFields'', ''OEUserFieldID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OrderDiscounts
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OrderDiscounts.OrderDiscountID
        FROM OrderDiscounts
        WHERE OrderDiscounts.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OrderDiscounts'', ''OrderDiscountID'', @TempIdList, @PerformDeletes, @BatchSize

    -- OrderLines
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
    SELECT OrderLines.OrderLineID
        FROM OrderLines
        WHERE OrderLines.OrderID IN (SELECT RecordID FROM @OrdersToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''OrderLines'', ''OrderLineID'', @TempIdList, @PerformDeletes, @BatchSize

    -- Orders
    EXEC GTSWSDeleteHistoricalDataFromTable ''Orders'', ''OrderID'', @OrdersToDelete, @PerformDeletes, @BatchSize

  END TRY
  BEGIN CATCH
    DECLARE @ERROR_MESSAGE NVARCHAR(2048);
    DECLARE @ERROR_SEVERITY TINYINT;
    DECLARE @ERROR_NUMBER INT;

    SET @ERROR_MESSAGE = ERROR_MESSAGE();
    SET @ERROR_NUMBER = ERROR_NUMBER();
    SET @ERROR_SEVERITY = ERROR_SEVERITY();

    RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
  END CATCH
END'
EXEC(@WSPurgeScriptSQL)

--
--  -------------------------------------------------------------------
--
--                  ***  GTSWSPurgePassData  ***
--
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSWSPurgePassData') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
BEGIN
  SET @WSPurgeScriptSQL = 'DROP PROCEDURE dbo.GTSWSPurgePassData'
  EXEC(@WSPurgeScriptSQL)
END

SET @WSPurgeScriptSQL = 'CREATE PROCEDURE GTSWSPurgePassData
  @RetentionPeriodDays int = 90,
  @PerformDeletes bit = 0,
  @BatchSize int = 1000
AS
BEGIN
  SET NOCOUNT ON;

  -- We must retain order data for 5 years plus the current year, so calculate what the "minimum" date we must retain is.
  DECLARE @CurrentYearStartDate datetime = DATEADD(YY, DATEDIFF(YY, 0, CURRENT_TIMESTAMP), 0)
  DECLARE @MinAllowedDate datetime = DATEADD(yy, -5, @CurrentYearStartDate)

  -- Calculate the date the caller requested to delete data after
  DECLARE @RequestedMinDate datetime = DATEADD(day, -@RetentionPeriodDays, DATEADD(day, DATEDIFF(day, 0, CURRENT_TIMESTAMP), 0))

  DECLARE @RetentionDate datetime = IIF(@RequestedMinDate < @MinAllowedDate, @RequestedMinDate, @MinAllowedDate)

  IF @RequestedMinDate > @MinAllowedDate RAISERROR(''Increasing requested retention period so it includes current year plus 5 years.'', 10, 1) WITH NOWAIT;

  DECLARE @RetentionDateText varchar(50) = CAST(@RetentionDate as varchar)
  RAISERROR(''Will delete passes with LastUpdate before %s'', 10, 1, @RetentionDateText) WITH NOWAIT;

  BEGIN TRY
    DECLARE @PassesToDelete IdListForDelete;
    INSERT INTO @PassesToDelete SELECT PassNo FROM Passes WHERE LastUpdate < @RetentionDate;

    DECLARE @TempIdList IdListForDelete

    DECLARE @ContactsToDelete IdListForDelete

    -- Gather CustContacts to delete
    INSERT INTO @ContactsToDelete
         SELECT Passes.ContactID
           FROM Passes
          WHERE Passes.PassNo IN (SELECT RecordID FROM @PassesToDelete)

    -- PhoneNumbers
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
      SELECT PhoneNumberID
        FROM PhoneNumbers
        WHERE ContactID IN (SELECT RecordID FROM @ContactsToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''PhoneNumbers'', ''PhoneNumberID'', @TempIdList, @PerformDeletes, @BatchSize

    -- Addresses
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
      SELECT Addresses.AddressID
        FROM Addresses
        JOIN CustContacts ON CustContacts.AddressID = Addresses.AddressID
        WHERE CustContacts.CustContactID IN (SELECT RecordID FROM @ContactsToDelete) AND ISNULL(Addresses.PersistenceState, 0) = 0
    EXEC GTSWSDeleteHistoricalDataFromTable ''Addresses'', ''AddressID'', @TempIdList, @PerformDeletes, @BatchSize

    -- JointMembers
    DELETE FROM @TempIdList
    INSERT INTO @TempIdList
      SELECT JointMembers.JointMemberID
        FROM JointMembers
        JOIN CustContacts ON CustContacts.CustContactID = JointMembers.ContactID
        JOIN Passes ON Passes.PassNo = JointMembers.PassNo
        WHERE CustContacts.CustContactID IN (SELECT RecordID FROM @ContactsToDelete) AND
              Passes.PassNo IN (SELECT RecordID FROM @PassesToDelete)
    EXEC GTSWSDeleteHistoricalDataFromTable ''JointMembers'', ''JointMemberID'', @TempIdList, @PerformDeletes, @BatchSize

    -- CustContacts
    EXEC GTSWSDeleteHistoricalDataFromTable ''CustContacts'', ''CustContactID'', @ContactsToDelete, @PerformDeletes, @BatchSize

    -- Passes
    EXEC GTSWSDeleteHistoricalDataFromTable ''Passes'', ''PassNo'', @PassesToDelete, @PerformDeletes, @BatchSize
  END TRY
  BEGIN CATCH
    DECLARE @ERROR_MESSAGE NVARCHAR(2048);
    DECLARE @ERROR_SEVERITY TINYINT;
    DECLARE @ERROR_NUMBER INT;

    SET @ERROR_MESSAGE = ERROR_MESSAGE();
    SET @ERROR_NUMBER = ERROR_NUMBER();
    SET @ERROR_SEVERITY = ERROR_SEVERITY();

    RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
  END CATCH
END'
EXEC(@WSPurgeScriptSQL)

