SET @WSPurgeScriptSQL = 'CREATE PROCEDURE GTSWSPurgeOldData
  @LogRetentionPeriodDays int = 90,
  @DataRetentionPeriodDays int = 365,
  @PerformDeletes bit = 0,
  @BatchSize int = 1000000
AS
BEGIN
  SET NOCOUNT ON;

  BEGIN TRY
    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = ''GTSWSPurgeOrderData'') AND (o.type = ''P'')
           AND   (o.uid = u.uid)
           AND   (u.name = ''dbo''))
      EXEC GTSWSPurgeOrderData @DataRetentionPeriodDays, @PerformDeletes, @BatchSize

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = ''GTSWSPurgePassData'') AND (o.type = ''P'')
           AND   (o.uid = u.uid)
           AND   (u.name = ''dbo''))
      EXEC GTSWSPurgePassData @DataRetentionPeriodDays, @PerformDeletes, @BatchSize

    IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = ''GTSWSPurgeLogData'') AND (o.type = ''P'')
           AND   (o.uid = u.uid)
           AND   (u.name = ''dbo''))
      EXEC GTSWSPurgeLogData @LogRetentionPeriodDays, @PerformDeletes, @BatchSize
  END TRY
  BEGIN CATCH
    DECLARE @ERROR_MESSAGE NVARCHAR(2048);
    DECLARE @ERROR_SEVERITY TINYINT;
    DECLARE @ERROR_NUMBER INT;

    SET @ERROR_MESSAGE = ERROR_MESSAGE();
    SET @ERROR_NUMBER = ERROR_NUMBER();
    SET @ERROR_SEVERITY = ERROR_SEVERITY();

    RAISERROR(@ERROR_MESSAGE,@ERROR_SEVERITY,1);
  END CATCH
END'
EXEC(@WSPurgeScriptSQL)

EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName


/*
--
--  new table template
--

--
--  -------------------------------------------------------------------
--
--                  ***  xxx  ***
--
SET @TableName = 'xxx'
SET @TableStructure = '

        RecordVersion  int       NOT NULL,
        LastUpdate     datetime  NOT NULL,
        LastUpdatedBy  nvarchar(20) NULL
' -- *** NO CLOSING PARENTHESIS

EXEC GTSUpgradeAddTable  @RunMode, @Error OUTPUT, @TableName, @TableStructure

EXEC GTSUpgradeAddPK     @RunMode, @Error OUTPUT, @TableName, FilterDefinitionID, PKFilterDefinitionFilterDefID
EXEC GTSUpgradeAddIndex  @RunMode, @Error OUTPUT, @TableName, FilterType,         IXFilterDefinitionsFilterType

EXEC GTSUpgradeRecreateDroppedIndexes  @RunMode, @Error OUTPUT,  @TableName,  @RecreateDroppedIndexes

/ * Stop the script if an error has occurred * /
IF (@Error <> 0) BEGIN
    EXEC GTSUpgradeDoEndUpgrade  @RunMode,  @Error, @TableName
    RETURN
    END

*/


--
--  -------------------------------------------------------------------
--
--  ***  Add partitions to various web store db tables that include a column named PersistenceState ***
--
-- Important: This block requires compatibility_level >= 150 for OPTIMIZE_FOR_SEQUENTIAL_KEY index option to work

IF @CreatePartitionedPublishingStoredProcedures = 0 SET NOEXEC ON

IF @CurrentDBCompatibilityLevel >= 150 BEGIN
    --DECLARE @TableName nvarchar(MAX)

    DECLARE TableCursor CURSOR FOR
        SELECT sys.tables.name FROM sys.columns
            JOIN sys.tables ON sys.tables.object_id = sys.columns.object_id
            WHERE sys.columns.name = 'PersistenceState'
    --        order by sys.tables.name

	OPEN TableCursor;

	FETCH NEXT FROM TableCursor INTO @TableName
	WHILE @@FETCH_STATUS = 0 BEGIN

		-- PRINT @TableName
		-- Get name of primary key
		DECLARE @PKSchema nvarchar(255)
		--, @PKName nvarchar(255), @TypeDesc nvarchar(60)

		SELECT TOP 1 @PKSchema = CONSTRAINT_SCHEMA, @PKName = CONSTRAINT_NAME
			FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS
			WHERE TABLE_SCHEMA = 'dbo' AND TABLE_NAME = @TableName AND CONSTRAINT_TYPE = 'PRIMARY KEY'

		IF NOT @PKSchema IS NULL AND NOT @PKName IS NULL BEGIN

			-- Get primary key type (clustered, non-clustered)
			--SELECT @TypeDesc = type_desc FROM sys.indexes WHERE object_id = object_id('[dbo].[' + @TableName + ']') AND name = @PKName

			DECLARE @PKColumns nvarchar(MAX)
			SET @PKColumns = ''

			SELECT @PKColumns = @PKColumns + '[' + COLUMN_NAME + '],'
				FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE
				WHERE TABLE_NAME = @TableName and TABLE_SCHEMA = 'dbo' AND CONSTRAINT_SCHEMA = @PKSchema AND CONSTRAINT_NAME = @PKName
				ORDER BY ORDINAL_POSITION

			PRINT @TableName + ' PKColumns = "' + @PKColumns + '"'

			IF @PKColumns <> '' BEGIN
				SET @PKColumns = LEFT(@PKColumns, LEN(@PKColumns) - 1)

				DECLARE @SchemeName nvarchar(MAX), @FuncName nvarchar(MAX)

				SET @SchemeName = 'ps' + @TableName + 'PersistenceState'
				SET @FuncName   = 'pf' + @TableName + 'PersistenceState'

				PRINT 'Creating partition ' + @TableName + ', ' + @PKName + ', ' + @PKColumns + ', ' + @SchemeName + ', ' + @FuncName

				IF (NOT EXISTS (SELECT * FROM sys.partition_schemes WHERE name = @SchemeName)) AND
				   (NOT EXISTS (SELECT * FROM sys.partition_functions WHERE name = @FuncName)) BEGIN

					EXEC('CREATE PARTITION FUNCTION [' + @FuncName + '](int) AS RANGE RIGHT FOR VALUES (3)')
					EXEC('CREATE PARTITION SCHEME [' + @SchemeName + '] AS PARTITION [' + @FuncName + '] TO ([PRIMARY], [PRIMARY])')

					EXEC('ALTER TABLE [dbo].[' + @TableName + '] DROP CONSTRAINT [' + @PKName + '] WITH ( ONLINE = OFF )')

					EXEC('ALTER TABLE [dbo].[' + @TableName + '] ADD CONSTRAINT [' + @PKName + '] PRIMARY KEY NONCLUSTERED (' + @PKColumns + ' ASC) ' +
						'WITH (' +
						'	PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, IGNORE_DUP_KEY = OFF, ONLINE = OFF,' +
						'	ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF' +
						'	)' +
						'ON [PRIMARY]')

					EXEC('CREATE CLUSTERED INDEX [ClusteredIndex_on_' + @SchemeName + '] ON [dbo].[' + @TableName + ']([PersistenceState]) ' +
						'WITH (SORT_IN_TEMPDB = OFF, DROP_EXISTING = OFF, ONLINE = OFF) ON [' + @SchemeName + ']([PersistenceState])')

					EXEC('DROP INDEX [ClusteredIndex_on_' + @SchemeName + '] ON [dbo].[' + @TableName + ']')
					END
				END
			END

		FETCH NEXT FROM TableCursor INTO @TableName
		END

	CLOSE TableCursor;
	DEALLOCATE TableCursor;
    END
ELSE BEGIN
    PRINT ''
	PRINT 'Partitions to web tables cannot be performed. DB compatibility level = ' + CONVERT(NVARCHAR(3), @CurrentDBCompatibilityLevel) + '.'
	PRINT 'DB compatibility level must be at least 150.'
    END
/************ End of create partitions *************/

SET NOEXEC OFF

ScriptFinished:

/************ Create or run stored procedure containing custom logic *************/
/*   Once it is created, GTS customers may modify the GTSCustomAfterUpgradeTasks */
/*   stored procedure to meet their unique needs.                                */
/*********************************************************************************/
PRINT ''
IF EXISTS (SELECT o.id FROM SysObjects o, SysUsers u
           WHERE (o.name = 'GTSCustomAfterUpgradeTasks') AND (o.type = 'P')
           AND   (o.uid = u.uid)
           AND   (u.name = 'dbo'))
BEGIN
    IF @SkipCustomAfterUpgradeTasks = 0
    BEGIN
        PRINT 'Executing custom after upgrade task(s)...'
        EXEC GTSCustomAfterUpgradeTasks @RunMode, @Database
    END
    ELSE
    BEGIN
        PRINT 'Custom after upgrade tasks skipped.'
    END
END
ELSE
BEGIN
    DECLARE @CustomAfterUpgradeTasksSPSQL NVARCHAR(MAX)
    SET @CustomAfterUpgradeTasksSPSQL =
        'CREATE PROCEDURE dbo.GTSCustomAfterUpgradeTasks
            @RunMode INT,
            @Database SYSNAME AS
        BEGIN
            -- This custom stored procedure will execute after GalaxyDatabase.sql completes successfully.

            -- Make sure the stored procedure is running against the correct database.
            IF (@Database <> db_name())
            BEGIN
                DECLARE @ConnectedDB SYSNAME
                SELECT @ConnectedDB = db_name()
                -- Stop the script from continuing, severity level 20 terminates the entire connection
                RAISERROR(''The connected database (%s) is not the same as the database this stored procedure is trying to upgrade (%s).'', 20, 1, @ConnectedDB, @Database) WITH LOG
            END

            IF ((@RunMode % 10) = 1) -- Only run this logic when executing in Upgrade or Post Upgrade mode
            BEGIN
                PRINT ''    Executing custom task(s)...''
                -- Example logic
                /*
                BEGIN TRY
                    BEGIN TRANSACTION
                    -- Add custom logic for upgrade and post upgrade mode here.
                    COMMIT TRANSACTION
                END TRY
                BEGIN CATCH
                    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION
                END CATCH
                */
            END
        END'
    IF ((@RunMode % 10) = 1)
    BEGIN
        PRINT 'Creating GTSCustomAfterUpgradeTasks stored procedure...'
        EXEC(@CustomAfterUpgradeTasksSPSQL)
    END
END

/************ Show database recommendations *************/
