IF @RecommendSequences = 1 OR @RecommendCompatibilityLevelUpdate = 1 or ((@RMEventsTableNotUnicode = 1 or @HoldDetailsTableNotUnicode = 1) and not @ConvertRMTablesToUnicode = 1)
BEGIN
