/************ Configuration recommendation checks ************
Use this section to determine whether the customer's data might
benefit from a configuration change. Any recommendations will be
displayed in the next section, as this section is only for the checks.
**************************************************************/

-- Check whether the number of ContactConnections for a customer exceeds a threshold.
-- If it does, add a recommendation to enable IgnoreContactConnections for those customers.
DECLARE @RecommendIgnoreContactConnections BIT = 0
DECLARE @CustContactsIgnoreContactConnectionsThreshold INT = 5000
DECLARE @RecommendIgnoreContactConnectionsTable TABLE
(
    CustomerID INT,
    CustName NVARCHAR(50),
    ContactCount INT
)
DECLARE @RecommendIgnoreContactConnectionsCount INT = 0
SET NOCOUNT ON
INSERT INTO @RecommendIgnoreContactConnectionsTable
    SELECT C.CustomerID, Customers.CustName, C.ContactCount FROM
    (
        SELECT ConnectionID AS CustomerID, ConnectionType, COUNT(*) AS ContactCount FROM ContactConnections WITH (NOLOCK)
        WHERE ConnectionType IN (1, 4) -- 1 = ID_CUSTOMER_CONNECTION, 4 = ID_GROUPSALES_CUSTOMER_CONNECTION
        GROUP BY ConnectionID, ConnectionType
    ) C
    INNER JOIN Customers WITH (NOLOCK) ON C.CustomerID = Customers.CustomerID
    WHERE C.ContactCount > @CustContactsIgnoreContactConnectionsThreshold AND Customers.IgnoreContactConnections = 0
SELECT @RecommendIgnoreContactConnectionsCount = COUNT(*) FROM @RecommendIgnoreContactConnectionsTable
IF @RecommendIgnoreContactConnectionsCount > 0 SET @RecommendIgnoreContactConnections = 1
SET NOCOUNT OFF


/************ Show configuration recommendations (add checks above)*************
Display any recommendations based on the checks in the preceding section.
********************************************************************************/
PRINT ''
-- Show this header only if there are actual recommendations to display.
IF @RecommendIgnoreContactConnections = 1 -- OR @SomeOtherRecommendation OR @YetAnotherRecommendation
BEGIN
    PRINT '********************************************************************************'
    PRINT '*                     Configuration Recommendations                            *'
    PRINT '********************************************************************************'
END

/*
-- TEMPLATE
IF @SomeOtherRecommendation = 1
BEGIN
    PRINT ''
    PRINT 'Recommendation text here.'
    PRINT ''
    PRINT '********************************************************************************'
END
*/

IF @RecommendIgnoreContactConnections = 1
BEGIN
    PRINT ''
    PRINT 'There is/are ' + CONVERT(NVARCHAR(8), @RecommendIgnoreContactConnectionsCount) + ' customer(s) in this database with more than ' + CONVERT(NVARCHAR(8), @CustContactsIgnoreContactConnectionsThreshold) + ' associated'
    PRINT 'contact records. To prevent performance degradation when loading customer'
    PRINT 'details in Galaxy, we recommend enabling the "Ignore Contact Connections" flag'
    PRINT 'for each of these customer records.'
    PRINT ''
    PRINT 'Please run the query below separately to retrieve the full list of Customer IDs'
    PRINT 'that would benefit from this update.'
    PRINT ''
    PRINT '    SELECT C.CustomerID, Customers.CustName, C.ContactCount FROM'
    PRINT '    ('
    PRINT '        SELECT ConnectionID AS CustomerID, ConnectionType, COUNT(*) AS ContactCount FROM ContactConnections WITH (NOLOCK)'
    PRINT '        WHERE ConnectionType IN (1, 4)'
    PRINT '        GROUP BY ConnectionID, ConnectionType'
    PRINT '    ) C'
    PRINT '    INNER JOIN Customers WITH (NOLOCK) ON C.CustomerID = Customers.CustomerID'
    PRINT '    WHERE C.ContactCount > ' + CONVERT(NVARCHAR(8), @CustContactsIgnoreContactConnectionsThreshold) + ' AND Customers.IgnoreContactConnections = 0'
    PRINT ''
    PRINT '********************************************************************************'
END


/************ Persist column changes to UpgradeTableChanges *************/
IF ((@RunMode % 10) = 1) BEGIN
    DECLARE @PersistHistoryID int
    SELECT @PersistHistoryID = MAX(UpgradeHistoryID) FROM UpgradeHistory

    IF @PersistHistoryID IS NOT NULL BEGIN
        -- Persist column alterations (ChangeType = 1)
        IF OBJECT_ID('tempdb..#ColumnAlterations') IS NOT NULL AND EXISTS(SELECT TOP 1 NULL FROM #ColumnAlterations)
            INSERT INTO UpgradeTableChanges (UpgradeHistoryID, ChangeType, TableName, ColumnName, OldDefinition, NewDefinition, DefaultValue)
            SELECT @PersistHistoryID, 1, TableName, ColumnName, OldDefinition, NewDefinition, NULL
            FROM #ColumnAlterations

        -- Persist column additions (ChangeType = 2)
        IF OBJECT_ID('tempdb..#ColumnAdditions') IS NOT NULL AND EXISTS(SELECT TOP 1 NULL FROM #ColumnAdditions)
            INSERT INTO UpgradeTableChanges (UpgradeHistoryID, ChangeType, TableName, ColumnName, OldDefinition, NewDefinition, DefaultValue)
            SELECT @PersistHistoryID, 2, TableName, ColumnName, NULL, Definition, DefaultValue
            FROM #ColumnAdditions
    END
END


/************ Show column alteration summary *************/
IF OBJECT_ID('tempdb..#ColumnAlterations') IS NOT NULL AND EXISTS(SELECT TOP 1 NULL FROM #ColumnAlterations WHERE ShowInSummary = 1)
BEGIN
    DECLARE
        @ColAltId              INTEGER,
        @ColAltTableName       VARCHAR(256),
        @ColAltColumnName      VARCHAR(256),
        @ColAltOldDef          VARCHAR(200),
        @ColAltNewDef          VARCHAR(200),
        @ColAltGridHorizLine   NVARCHAR(MAX) = '-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------',
        @ColAltGridHorizBold   NVARCHAR(MAX) = '*****************************************************************************************************************************************************************************************';

    PRINT ''
    PRINT ''
    PRINT @ColAltGridHorizLine
    PRINT '| ' + CAST('Column Alterations Summary' AS CHAR(182)) + '|'
    PRINT @ColAltGridHorizLine
    PRINT '| ' + CAST('TABLE' AS CHAR(40)) + '| ' + CAST('COLUMN' AS CHAR(40)) + '| ' + CAST('OLD DEFINITION' AS CHAR(48)) + '| ' + CAST('NEW DEFINITION' AS CHAR(48)) + '|'
    PRINT @ColAltGridHorizBold

    SET NOCOUNT ON
    WHILE EXISTS(SELECT TOP 1 NULL FROM #ColumnAlterations WHERE ShowInSummary = 1)
    BEGIN
        SELECT TOP 1 @ColAltId = [Id], @ColAltTableName = TableName, @ColAltColumnName = ColumnName, @ColAltOldDef = OldDefinition, @ColAltNewDef = NewDefinition FROM #ColumnAlterations WHERE ShowInSummary = 1 ORDER BY TableName, ColumnName ASC

        PRINT '| ' + CAST(@ColAltTableName AS CHAR(40)) + '| ' + CAST(@ColAltColumnName AS CHAR(40)) + '| ' + CAST(@ColAltOldDef AS CHAR(48)) + '| ' + CAST(@ColAltNewDef AS CHAR(48)) + '|'
        PRINT @ColAltGridHorizLine

        DELETE FROM #ColumnAlterations WHERE Id = @ColAltId
    END
    SET NOCOUNT OFF
END
ELSE
BEGIN
    PRINT ''
    PRINT 'No column alterations found.'
END
IF OBJECT_ID('tempdb..#ColumnAlterations') IS NOT NULL DROP TABLE #ColumnAlterations


/************ Show notable column additions *************/
IF OBJECT_ID('tempdb..#ColumnAdditions') IS NOT NULL AND EXISTS(SELECT TOP 1 NULL FROM #ColumnAdditions WHERE ShowInSummary = 1)
BEGIN
    DECLARE
        @ColAddId              INTEGER,
        @ColAddTableName       VARCHAR(256),
        @ColAddColumnName      VARCHAR(256),
        @ColAddDef             VARCHAR(200),
        @ColAddDefault         VARCHAR(200),
        @ColAddGridHorizLine   NVARCHAR(MAX) = '-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------',
        @ColAddGridHorizBold   NVARCHAR(MAX) = '*****************************************************************************************************************************************************************************************';

    PRINT ''
    PRINT ''
    PRINT @ColAddGridHorizLine
    PRINT '| ' + CAST('Notable Column Additions (NOT NULL or with Default Value)' AS CHAR(182)) + '|'
    PRINT @ColAddGridHorizLine
    PRINT '| ' + CAST('TABLE' AS CHAR(40)) + '| ' + CAST('COLUMN' AS CHAR(40)) + '| ' + CAST('DEFINITION' AS CHAR(48)) + '| ' + CAST('DEFAULT VALUE' AS CHAR(48)) + '|'
    PRINT @ColAddGridHorizBold

    SET NOCOUNT ON
    WHILE EXISTS(SELECT TOP 1 NULL FROM #ColumnAdditions WHERE ShowInSummary = 1)
    BEGIN
        SELECT TOP 1 @ColAddId = [Id], @ColAddTableName = TableName, @ColAddColumnName = ColumnName, @ColAddDef = Definition, @ColAddDefault = DefaultValue FROM #ColumnAdditions WHERE ShowInSummary = 1 ORDER BY TableName, ColumnName ASC

        PRINT '| ' + CAST(@ColAddTableName AS CHAR(40)) + '| ' + CAST(@ColAddColumnName AS CHAR(40)) + '| ' + CAST(@ColAddDef AS CHAR(48)) + '| ' + CAST(@ColAddDefault AS CHAR(48)) + '|'
        PRINT @ColAddGridHorizLine

        DELETE FROM #ColumnAdditions WHERE Id = @ColAddId
    END
    SET NOCOUNT OFF
END
ELSE
BEGIN
    PRINT ''
    PRINT 'No notable column additions found.'
END
IF OBJECT_ID('tempdb..#ColumnAdditions') IS NOT NULL DROP TABLE #ColumnAdditions


/************ Show index recommendations *************/
--  -------------------------------------------------------------------
--
--                  ***  #IndexRecommendations  ***
--
--  Create temp table and variables used for recommending indexes at the end of this script.
--  -------------------------------------------------------------------
DECLARE @RecommendedIndexExists BIT = 0
DECLARE @RecommendedIndexName NVARCHAR(50) = ''
IF OBJECT_ID('tempdb..#IndexRecommendations') IS NOT NULL
BEGIN
    DROP TABLE #IndexRecommendations
END
CREATE TABLE #IndexRecommendations
(
    Id              INT NOT NULL IDENTITY PRIMARY KEY,
    TableName       VARCHAR(60),
    IndexName       VARCHAR(60),
    EnableBitName   VARCHAR(50),
    AffectedModules VARCHAR(100),
    Notes           VARCHAR(200)
)
SET NOCOUNT ON
/* *****************   Add index recommendation checks here *****************

Use the following pattern to add recommendations.
    EXEC @RecommendedIndexExists = GTSIndexExists @TableName, @RecommendedIndexName
    IF @RecommendedIndexExists = 0
    BEGIN
        IF SOME_CHECK_TO_SEE_IF_WE_RECOMMEND_THE_INDEX
        BEGIN
            INSERT INTO #IndexRecommendations VALUES (@TableName, @RecommendedIndexName, '@EnableBitVariableName', 'Affected Module(s)', 'Note(s)')
        END
    END

EXAMPLE:
    -- Recommendation check for IXOrdersArrivalSummary
    SET @TableName = 'Orders'
    SET @RecommendedIndexName = 'IXOrdersArrivalSummary'
    EXEC @RecommendedIndexExists = GTSIndexExists @TableName, @RecommendedIndexName
    IF @RecommendedIndexExists = 0
    BEGIN
        IF @WebStoreDB = 0
        BEGIN
            DECLARE @OrdersThreshold INT = 10000
            DECLARE @OrdersThresholdCount INT = (SELECT COUNT(*) FROM (SELECT TOP(@OrdersThreshold) NULL as TempCol FROM Orders) AS OT)
            IF @OrdersThresholdCount = @OrdersThreshold
            BEGIN
                INSERT INTO #IndexRecommendations VALUES (@TableName, @RecommendedIndexName, '@AddIndexesForOrderEntryReports', 'Order Entry Reports', 'This index will improve the speed of several order entry reports.')
            END
        END
    END
*/

-- Recommendation check for IXOrderDetailsEventID
SET @TableName = 'OrderDetails'
SET @RecommendedIndexName = 'IXOrderDetailsEventID'
EXEC @RecommendedIndexExists = GTSIndexExists @TableName, @RecommendedIndexName
IF @RecommendedIndexExists = 0
BEGIN
    IF @WebStoreDB = 0
    BEGIN
        IF EXISTS (SELECT OrderDetailID FROM OrderDetails where EventID != 0)
        BEGIN
            INSERT INTO #IndexRecommendations VALUES (@TableName, @RecommendedIndexName, '@AddIndexForOrderDetailsEventID', 'Resource Management', 'This index will improve performance when viewing Sales Details for Resource Managed Events.')
        END
    END
END



/* *****************   Add index recommendation checks above this line. ***************** */

-- Now that we've collected our recommendations, print them if there are any.
IF EXISTS(SELECT TOP 1 NULL FROM #IndexRecommendations)
BEGIN
    DECLARE
        @IdxReccId                INTEGER,
        @IdxReccTableName         CHAR(60),
        @IdxReccIndexName         CHAR(60),
        @IdxEnableBitName         CHAR(50),
        @IdxReccAffectedModules   CHAR(100),
        @IdxReccNotes             CHAR(200),
        @IdxReccGridHorizLine     NVARCHAR(MAX) = '-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------',
        @IdxReccGridHorizLineBold NVARCHAR(MAX) = '*************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************';

    -- Print grid title and headers
    PRINT ''
    PRINT ''
    PRINT @IdxReccGridHorizLine
    PRINT '| ' + CAST('Index Recommendations' AS CHAR(470)) + '        |'
    PRINT @IdxReccGridHorizLine
    PRINT '| ' + CAST('TABLE' AS CHAR(60)) + '| ' + CAST('INDEX' AS CHAR(60)) + '| ' + CAST('ENABLE BIT' AS CHAR(50)) + '| ' + CAST('MODULE(S)' AS CHAR(100)) + '| ' + CAST('NOTES' AS CHAR(200)) + '|'
    PRINT @IdxReccGridHorizLineBold

    -- Print individual recommendations
    SET NOCOUNT ON
    WHILE EXISTS(SELECT TOP 1 NULL FROM #IndexRecommendations)
    BEGIN
        SELECT TOP 1 @IdxReccId = [Id], @IdxReccTableName = TableName, @IdxReccIndexName = IndexName, @IdxEnableBitName = EnableBitName, @IdxReccAffectedModules = AffectedModules, @IdxReccNotes = Notes FROM #IndexRecommendations ORDER BY TableName, IndexName ASC

        PRINT '| ' + @IdxReccTableName + '| ' + @IdxReccIndexName + '| ' + @IdxEnableBitName + '| ' + @IdxReccAffectedModules + '| ' + @IdxReccNotes + '|'

        PRINT @IdxReccGridHorizLine
        DELETE FROM #IndexRecommendations WHERE Id = @IdxReccId
    END
    SET NOCOUNT OFF
END
ELSE
BEGIN
    PRINT ''
    PRINT 'No index recommendations found.'
END
DROP TABLE #IndexRecommendations
SET NOCOUNT OFF
